P.entries["subzone:felfire-hill"] = {n="Холм Демонического Огня",s="Холм Демонического Огня — оскверненная, кишащая демонами возвышенность в восточной части Ясеневого леса. Земля, пораженная падающими инферналами во время Третьей войны, до сих пор горит демонической силой. Орда держит укрепленные сторожевые посты на мостах, ведущих к холму, защищая свои ближние поселения.",h="Холм Демонического Огня — оскверненная, кишащая демонами возвышенность в восточной части Ясеневого леса.",kw={"ashenvale","burning legion","demons","felfire hill","infernals","splintertree post","warsong lumber camp","ясеневый лес","пылающий легион","демоны","холм демонического огня","инферналы","застава расщепленного дерева","лесозаготовки песни войны"},ang={["class:Warlock"]="Необузданная энергия скверны, оставшаяся там, где приземлились инферналы Легиона, делает этот израненный хребет объектом опасного любопытства для приверженцев темной магии.",["faction:Horde"]="Орда удерживает укрепленные мосты вокруг Холма Демонического Огня, чтобы защитить дорогу между Заставой Расщепленного Дерева и Лесозаготовками Песни Войны от демонических налетов."},sec={{t="Шрам Пылающего Легиона",b="Во время катастрофического вторжения Третьей войны над Калимдором падали пылающие метеоры: Пылающий Легион обрушил своих грозных инферналов. Несколько таких огненных исполинов ударили в этот хребет в Ясеневом лесу, выжгли древние леса и осквернили саму землю. Сегодня опаленный ландшафт по-прежнему пропитан энергией скверны, а по нему бродят демоны, пережившие поражение Легиона на горе Хиджал."},{t="Охрана переправ",b="Холм Демонического Огня расположен к юго-востоку от Заставы Расщепленного Дерева и к юго-западу от Лесозаготовок Песни Войны, неуютно близко к важным объектам Орды. Поскольку остатки демонов грозят вырваться в окрестный лес, силы Орды возвели укрепленные заграждения и сторожевые башни у обоих мостов к холму, удерживая мерзких тварей в их оскверненном убежище."}},faq={{q="Почему Холм Демонического Огня осквернен?",a="Во время Третьей войны инферналы Пылающего Легиона градом упали с неба на этот холм. Удар и последовавшее заражение скверной выжгли нетронутый эльфийский лес, оставив обожженный камень и демоническую энергию, которая так и не рассеялась.",al={"why is felfire hill green","felfire hill lore","what happened to felfire hill","почему холм демонического огня зеленый","история холма демонического огня","что случилось с холмом демонического огня"}},{q="Какие существа живут на Холме Демонического Огня?",a="Холм занимают уцелевшие демоны и инфернальные создания, оставшиеся после вторжения Легиона во время Третьей войны. Они враждебны ко всем смертным, забредающим к их оскверненным границам.",al={"monsters at felfire hill","felfire hill mobs","монстры холма демонического огня","мобы холма демонического огня"}},{q="Почему Орда укрепила здешние мосты?",a="Холм Демонического Огня лежит прямо между Заставой Расщепленного Дерева и Лесозаготовками Песни Войны. Командиры Орды укрепили оба моста, чтобы бродящие демоны не вырвались и не захватили соседние лагеря, обозы снабжения и лесозаготовки.",al={"horde bridge guards felfire","why are orcs guarding felfire hill","стража орды на мостах","почему орки охраняют холм демонического огня"}},{q="Связан ли Холм Демонического Огня с ночными эльфами?",a="Хотя сам холм когда-то был частью священной чащи Ясеневого леса, теперь он зловеще возвышается к северо-востоку от Обители Дор'Данил. Ползущая демоническая скверна и бродящие злодеи — постоянная опасность для близлежащих мест упокоения и окрестных земель.",al={"dor danil felfire hill","barrow den demons","дор'данил холм демонического огня","демоны обители"}}},fp="12,296,28.418.0,22.387.0,30.264.0,36.201.0,43.238.0,45.262.0"}
P.entries["subzone:felpaw-village"] = {n="Деревня Сквернолапов",s="Деревня Сквернолапов — оскверненное поселение фурболгов на дальнем севере Оскверненного леса, охраняющее горную тропу, ведущую прямо к Крепости Древобрюхов. Ее населяет павшее племя Мертвого Леса; хижины и места сборищ отравлены демоническим влиянием и враждебны ко всем чужакам.",h="Деревня Сквернолапов — оскверненное поселение фурболгов на дальнем севере Оскверненного леса, охраняющее...",kw={"corruption","deadwood","felpaw","felpaw village","felwood","furbolg","timbermaw","порча","мертвый лес","сквернолапы","деревня сквернолапов","оскверненный лес","фурболг","древобрюх"},ang={["class:Druid"]="Для друидов, стремящихся восстановить естественный порядок, павшие фурболги Мертвого Леса в Деревне Сквернолапов — трагическое напоминание о неугасающем яде Легиона в священных лесах.",["race:NightElf"]="Ночные эльфы когда-то считали фурболгов верными союзниками, поэтому вид безумия Мертвого Леса и ритуального падения в Сквернолапах особенно горек."},sec={{t="Оплот порчи",b="Деревня Сквернолапов, расположенная на северной окраине Оскверненного леса, служит главным северным оплотом павших фурболгов племени Мертвого Леса. Некогда мирные хранители леса, они пали жертвой демонической порчи, высвобожденной во время Третьей войны, и впали в звериное безумие. Теперь деревня — оскверненный анклав с грубыми хижинами, ритуальными тотемами и враждебными воинами, нападающими на всякого, кто подходит к входу в тоннель Крепости Древобрюхов."},{t="Заноза у Крепости Древобрюхов",b="Близость Деревни Сквернолапов к священному входу в Крепость Древобрюхов делает ее серьезной угрозой для немногих неоскверненных фурболгов региона. Стражи Древобрюхов на северном краю Оскверненного леса смотрят на павших сородичей со скорбью и настороженностью и часто просят путников проредить ряды Мертвого Леса, добыть их ритуальные фетиши и не дать порче просочиться через врата в Лунную поляну и Зимние Ключи."}},faq={{q="Кто живет в Деревне Сквернолапов?",a="Поселение принадлежит фурболгам племени Мертвого Леса — местному племени, полностью павшему под власть демонической порчи, распространяющейся по Оскверненному лесу.",al={"felpaw village inhabitants","who is at felpaw","deadwood furbolgs northern felwood","жители деревни сквернолапов","кто в деревне сквернолапов","фурболги мертвого леса"}},{q="Почему здешние фурболги враждебны?",a="Фурболги племени Мертвого Леса обезумели от демонических энергий, отравляющих почву, воду и животных Оскверненного леса. Они считают всех чужаков врагами, и с ними невозможно договориться.",al={"why do deadwood attack","are felpaw furbolgs friendly","why are bears angry felwood","почему мертвый лес нападает","дружелюбны ли фурболги сквернолапы","почему медведи злы"}},{q="Где находится Деревня Сквернолапов?",a="Она лежит на дальнем севере Оскверненного леса, прямо у дороги, ведущей к главному южному входу в Крепость Древобрюхов.",al={"felpaw village map location","where is felpaw village","how to get to felpaw","деревня сквернолапов на карте","где деревня сквернолапов","как добраться до сквернолапов"}},{q="Как Деревня Сквернолапов связана с Крепостью Древобрюхов?",a="Неоскверненное племя Древобрюхов внимательно наблюдает за Деревней Сквернолапов из своих ближних врат. Поскольку Мертвый Лес угрожает безопасности прохода между Оскверненным лесом, Зимними Ключами и Лунной поляной, Древобрюхи награждают чужаков, которые сокращают число враждебных обитателей деревни и добывают ритуальные перья Мертвого Леса.",al={"timbermaw connection","timbermaw hold reputation felpaw","timbermaw deadwood","связь с древобрюхами","репутация древобрюхов сквернолапы","древобрюхи мертвый лес"}}},fp="14,293,26.455.0,29.465.0,28.152.0,34.187.0,32.124.0,49.295.0"}
P.entries["subzone:felstone-field"] = {n="Поле Джанис",s="Поле Джанис — оскверненная ферма на северо-западе Западных Чумных земель. Некогда процветавшие сельскохозяйственные угодья Лордерона, оно захвачено Плетью и стало опорой чумного котла, изрыгающего ядовитые испарения над разоренной землей.",h="Поле Джанис — оскверненная ферма на северо-западе Западных Чумных земель.",kw={"cauldron lord bilemaw","felstone field","janice felstone","jeremiah payson","lordaeron","ol' emma","plague cauldron","scarlet crusade","western plaguelands","хранитель котла желчень","поле джанис","джанис фелстон","иеремия пэйсон","лордерон","старушка эмма","чумной котел","алый орден","западные чумные земли"},ang={["faction:Alliance"]="Для выживших Альянса в Штормграде такие места, как Поле Джанис, — это потерянные родовые земли и разлученные родичи вроде Старушки Эммы, цепляющейся за права на разоренное северное наследство.",["race:Undead"]="Разоренная ферма — суровое напоминание о жизни, которую Отрекшиеся вели в Лордероне; о ней напоминают родственники вроде Иеремии Пэйсона, уцелевшего лишь благодаря нежизни."},sec={{t="Оскверненная усадьба",b="До Третьей войны Поле Джанис было мирной доходной семейной фермой, кормившей жителей Лордерона. Когда чума прошла по северу, усадьба быстро пала перед Культом Проклятых и Плетью. Сегодня на полях вместо зерна растут мертвые сорняки и ползучая гниль. В сердце угодий стоит огромный чумной котел, непрерывно выпускающий в небо зловонные пары под надзором Хранителя котла Желчень и легионов скелетов-свежевателей, колдунов и голодных вурдалаков."},{t="Задержавшиеся призраки и фанатики",b="Несмотря на оккупацию нежити, в руинах остались следы мира живых. В северо-восточном фермерском доме бродит призрак Джанис Фелстон, скорбно блуждающий по остову своего бывшего дома. Тем временем патрули соседнего Алого ордена обходят границы владений, жестоко уничтожая любую нежить и убивая чужаков, подошедших слишком близко к их крестовому походу."}},faq={{q="Для чего нужен котел в центре поля?",a="Котел — чумная машина Плети, предназначенная пропитывать окрестные земли и воздух мором, портя почву и поднимая мертвых. Его охраняет могущественный надзиратель Плети — Хранитель котла Желчень, а также скелеты-прислужники и вурдалаки.",al={"felstone cauldron","why is there a cauldron","plague cauldron felstone","котел поля джанис","зачем здесь котел","чумной котел поля джанис"}},{q="Кто такой призрак в фермерском доме?",a="Это Джанис Фелстон, бывшая хозяйка фермы, погибшая, когда Плеть захватила эти земли. Не желая или не имея возможности упокоиться, ее дух остается связанным с руинами родного дома.",al={"janice felstone","ghost in felstone house","who is in the house","джанис фелстон","призрак в доме фелстон","кто в доме"}},{q="Почему ферму патрулируют бойцы Алого ордена?",a="Алый орден часто отправляет агрессивные отряды в Западные Чумные земли для уничтожения Плети. Любых путников, забредших на территорию, — Орды или Альянса — они считают возможными разносчиками чумы или врагами и нападают без разбора.",al={"scarlet crusade felstone","crusaders at felstone field","алый орден поле джанис","рыцари ордена на поле джанис"}},{q="Кому на самом деле принадлежит право на Поле Джанис?",a="И Иеремия Пэйсон в Подгороде, и Старушка Эмма в Штормграде утверждают, что получили документ от своей сестры, Джанис Фелстон. Остается загадкой, было ли составлено два документа или хаос чумы безнадежно запутал наследство между живыми и мертвыми родственниками.",al={"felstone field deed","who owns felstone","better late than never deed","документ на поле джанис","кому принадлежит поле джанис","лучше поздно чем никогда документ"}}},fp="14,254,20.508.0,28.408.1,54.264.0,38.204.0,52.246.0,45.291.1"}
P.entries["subzone:fenris-keep"] = {n="Крепость Фенриса",s="Крепость Фенриса — уединенная каменная цитадель на вершине Острова Фенриса посреди озера Лордамер. Когда-то это был стратегический оплот с войсками Лордерона, но теперь он перешел в руки Плети под началом отступника-мага Тула Когтя Ворона.",h="Крепость Фенриса — уединенная каменная цитадель на вершине Острова Фенриса посреди озера Лордамер.",kw={"fenris isle","fenris keep","lordaeron","lordamere lake","rot hide","scourge","silverpine forest","thule ravenclaw","остров фенриса","крепость фенриса","лордерон","озеро лордамер","гнилошкуры","плеть","серебряный бор","тул коготь ворона"},ang={["class:Mage"]="Хозяин Крепости Фенриса Тул Коготь Ворона — мрачное предательство учения Кирин-Тора: он извратил арканные знания Даларана, превратив их в темные искусства Плети.",["faction:Horde"]="Для Орды, и особенно для Отрекшихся, Крепость Фенриса — уцелевший оплот Плети, который необходимо уничтожить, чтобы защитить Серебряный бор и водные пути озера Лордамер."},sec={{t="Павший бастион Лордерона",b="До Третьей войны Крепость Фенриса имела стратегическое значение для Королевства Лордерон: там стоял значительный отряд, охранявший озеро Лордамер. Когда нежить из Плети захлестнула страну, островная крепость пала вместе с остальным королевством. Но она не превратилась в забытые руины: ее захватил Тул Коготь Ворона, предатель и бывший волшебник Кирин-Тора. Он заключил союз с Плетью, подчинил местных гноллов мерзкой некромантией, создав свирепую стаю Гнилошкур, и закрепился в каменных залах крепости."},{t="Плеть на Лордамере",b="Сегодня Крепость Фенриса — средоточие власти Когтя Ворона и неминуемая угроза для Отрекшихся, удерживающих Серебряный бор. Из этого бастиона Тул управляет легионами гноллов Гнилошкур, яростно нападающих на всякого, кто осмелится ступить на остров. Поскольку Остров Фенриса лежит всего в нескольких милях по воде от границы Тирисфаля, Отрекшиеся из Гробницы и Подгорода посылают защитников, чтобы сокрушить оборону крепости и покончить с отступником-некромантом."}},faq={{q="Что такое Крепость Фенриса?",a="Крепость Фенриса — укрепленный каменный замок на Острове Фенриса посреди озера Лордамер. Раньше это был военный оплот павшего Королевства Лордерон, а теперь им владеет нежить из Плети.",al={"fenris keep lore","what is fenris keep","fenris castle","предания крепости фенриса","что такое крепость фенриса","замок фенриса"}},{q="Кто сейчас правит Крепостью Фенриса?",a="Крепостью правит Тул Коготь Ворона, бывший маг Кирин-Тора, предавший живых ради службы Плети. Из крепости он командует армией оскверненных нежитью гноллов Гнилошкур.",al={"who controls fenris keep","fenris keep boss","master of fenris isle","кто управляет крепостью фенриса","босс крепости фенриса","хозяин острова фенриса"}},{q="Почему в Крепости Фенриса гноллы?",a="Местных гноллов подчинил Тул Коготь Ворона с помощью темной магии и болезни, превратив их в гноллов Гнилошкур. Они служат ударными отрядами и верными стражами Когтя Ворона по всему замку и острову.",al={"rot hide gnolls fenris","why gnolls in keep","fenris gnolls","гноллы гнилошкуры фенрис","почему гноллы в крепости","гноллы фенриса"}},{q="Почему Отрекшихся волнует Крепость Фенриса?",a="Крепость Фенриса дает Плети надежную базу на озере Лордамер и прямо угрожает передвижениям Отрекшихся по восточной части Серебряного бора и Тирисфальским лесам. Войска Сильваны не могут оставлять действующего командира Плети без присмотра так близко к своим границам.",al={"why forsaken attack fenris","forsaken fenris keep","undercity fenris","почему отрекшиеся нападают на фенрис","отрекшиеся крепость фенриса","подгород фенрис"}}},fp="11,235,29.591.0,24.473.1,20.194.0,32.187.0,40.238.0,43.262.0"}
P.entries["subzone:feral-scar-vale"] = {n="Долина Свирепого Утеса",s="Долина Свирепого Утеса — скалистое ущелье в Высокогорных дебрях западного Фераласа. Она захвачена территориальными йети Свирепого Утеса, и ее пещерные туннели крайне опасны для путников, сошедших с заросших лесных троп.",h="Долина Свирепого Утеса — скалистое ущелье в Высокогорных дебрях западного Фераласа.",kw={"feral scar vale","feralas","high wilderness","homing robot","oox-22/fe","yeti","долина свирепого утеса","фералас","высокогорные дебри","самонаводящийся робот","йети"},ang={["class:Hunter"]="Громадные йети Свирепого Утеса, бродящие по этим скалам, — серьезное испытание для навыков выслеживания и охоты на крупную дичь среди густых крон Высокогорных дебрей.",["profession:Engineering"]="В туннелях йети застрял гномский самонаводящийся робот; чтобы благополучно вернуть его в цивилизацию, понадобятся рука инженера и аварийный маяк."},sec={{t="Логово йети",b="Среди густой листвы и отвесных скал Высокогорных дебрей находится Долина Свирепого Утеса — главное логово свирепых йети Свирепого Утеса. Хотя йети обычны на заснеженных вершинах Альтерака и Дун Морога, эти первобытные громилы полностью приспособились к диким влажным условиям Фераласа. Они яростно защищают сеть пещер долины, копят костяные трофеи и беспощадно прогоняют всех, кто забредет на их охотничьи угодья."},{t="Диковинки в пещерах",b="Помимо первобытной опасности йети, в глубине Долины Свирепого Утеса скрываются неожиданные странности. Сигналы бедствия гномских инженеров порой приводили в эти темные пещеры, где свирепые звери захватили потерянные исследовательские устройства, например застрявших роботов-разведчиков в виде цыплят, которые ждут активации и вызволения."}},faq={{q="Какие существа живут в Долине Свирепого Утеса?",a="В долине господствуют йети Свирепого Утеса — огромные территориальные хищники, которые гнездятся в скалистых пещерах и патрулируют окрестный лес.",al={"feral scar vale mobs","what is in feral scar vale","vale creatures","мобы долины свирепого утеса","что в долине свирепого утеса","существа долины"}},{q="Где находится Долина Свирепого Утеса?",a="Долина Свирепого Утеса находится в западной части Фераласа, в области под названием Высокогорные дебри, к югу от главной дороги, пролегающей сквозь полог дождевого леса.",al={"feral scar vale location","where is feral scar vale","how to find feral scar vale","расположение долины свирепого утеса","где долина свирепого утеса","как найти долину свирепого утеса"}},{q="Почему в пышном тропическом лесу живут йети?",a="Хотя йети обычно связывают со снежными горами, древние и нетронутые дебри Калимдора населяют особые подвиды, например йети Свирепого Утеса, которые на протяжении поколений процветают в густых лесных долинах.",al={"why yetis in feralas","jungle yetis","feralas yeti lore","почему йети в фераласе","йети джунглей","предания о йети фераласа"}},{q="Что за механический цыпленок в пещере?",a="Глубоко в одной из пещер долины находится самонаводящийся робот OOX-22/FE — автономный механический цыпленок-разведчик, созданный гномами-инженерами, который потерпел крушение и застрял в тылу йети.",al={"oox-22/fe","robot chicken feralas","homing robot feral scar vale","робот цыпленок фералас","самонаводящийся робот долина свирепого утеса"}}},fp="15,232,17.450.0,24.355.0,47.148.0,33.158.0,41.215.0,47.187.0"}
P.entries["subzone:field-of-giants"] = {n="Поля Великанов",s="Поля Великанов — обширная равнина в южных Степях между Лагерем Таурахо и болотами Пылевых топей. Свое название она получила от огромных кодо, громадных ящеров и других гигантских зверей, пасущихся в ее сухих зарослях; недавно регион стал куда опаснее из-за вторжения силитидов.",h="Поля Великанов — обширная равнина в южных Степях между Лагерем Таурахо и болотами Пылевых топей.",kw={"barrens","camp taurajo","field of giants","gold road","kodo","korran","ruga ragetotem","silithid","thunder lizard","степи","лагерь таурахо","поля великанов","золотой путь","кодо","корран","руга тотем гнева","силитиды","громовой ящер"},ang={["class:Hunter"]="Бродячие стада громовых ящеров и огромных кодо делают Поля Великанов одним из лучших охотничьих угодий Степей для тех, кто ищет грозных зверей.",["faction:Horde"]="Появление ульев силитидов так близко к дороге между Лагерем Таурахо и Пылевыми топями угрожает путям сообщения, и лидеры по всем Степям призывают разведчиков."},sec={{t="Дикий рубеж на юге",b="Поля Великанов тянутся вдоль южного участка Золотого Пути; по сравнению с северными Степями это глухой, суровый и слабо защищенный край. Деревянные сторожевые башни у дороги в основном заброшены, но сама земля полна жизни. Огромные стада крупных зверей Калимдора бродят по обширным равнинам, привлекая охотников и натуралистов. Однако безопасности здесь нет: дворфийские раскопщики из Бейл Модана упорно копают к югу, а гораздо более зловещая угроза начала рыть землю под ногами."},{t="Ползущий рой",b="В последнее время по всем Полям Великанов из земли вырвались ульи насекомоподобных силитидов — самое северное из известных появлений этих прожорливых тварей в Калимдоре. Странные холмы и агрессивные рои встревожили Орду. Разведчики вроде тролля Коррана из Перекрестка и воины-таурены вроде Руги Тотема Гнева из Лагеря Таурахо призывают искателей приключений исследовать ульи и выяснить, что привлекло этих подземных чудовищ так далеко от глубоких пустынь."}},faq={{q="Почему это место называется Полями Великанов?",a="Равнина получила название из-за огромных размеров живущих на ней животных. Здесь пасутся большие стада громадных кодо и ящеров, которые вместе с другими крупными зверями Калимдора господствуют над местностью.",al={"field of giants name origin","why field of giants","происхождение названия полей великанов","почему поля великанов"}},{q="Что это за кучи в земле?",a="Это холмы силитидов. Эти насекомоподобные хищники поднялись из глубин земли и создали самые северные из найденных в Калимдоре ульи. Их внезапное появление — серьезная угроза для путников и местных животных.",al={"bug mounds barrens","insects in southern barrens","what are the silithid","холмы в степях","насекомые в южных степях","кто такие силитиды"}},{q="Кто живет рядом с Полями Великанов?",a="На самой равнине мало поселений, но у ее границ стоят видные личности. Шаманка-тауренка Брин живет на южном хребте, а изгнанник Ганн Каменное Копье наблюдает неподалеку, замышляя козни против дворфийских раскопок в Бейл Модане.",al={"who lives here","field of giants npcs","кто здесь живет","персонажи полей великанов"}},{q="Почему сторожевые башни вдоль дороги заброшены?",a="Военное присутствие Орды сосредоточено главным образом на северном участке Золотого Пути вокруг Перекрестка. Южные земли патрулируют гораздо реже, и башни оказались заброшены на фоне растущей угрозы силитидов и агрессивных зверей.",al={"abandoned towers gold road","southern barrens watchtowers","заброшенные башни золотой путь","сторожевые башни южных степей"}}},fp="15,307,28.517.0,18.478.0,37.206.0,40.231.0,35.247.0,49.253.0"}
P.entries["subzone:fire-plume-ridge"] = {n="Вулкан Огненного Венца",s="Вулкан Огненного Венца — действующий вулкан, поднимающийся прямо в центре кратера Ун'Горо. Его раскаленные склоны и подземные каналы магмы питают гейзеры и паровые озера кратера, а также служат домом свирепым элементалям огня.",h="Вулкан Огненного Венца — действующий вулкан, поднимающийся прямо в центре кратера Ун'Горо.",kw={"blazerunner","elementals","fire plume ridge","lava","ringo","ungoro","volcano","яропламень","элементали","вулкан огненного венца","лава","ринго","ун'горо","вулкан"},ang={["class:Shaman"]="Духи огня яростно бушуют на вулкане, давая яркое представление о неукротимых силах стихий, бурлящих под корой Калимдора.",["profession:Mining"]="Скалы и раскаленные склоны вулкана богаты обнаженными минералами, особенно жилами плотного тория, образованного вулканическим давлением."},sec={{t="Очаг кратера",b="Вулкан Огненного Венца возвышается над первозданной котловиной Ун'Горо и резко контрастирует с окружающими буйными джунглями. Лава непрерывно стекает по его обожженным скалистым склонам, создавая ландшафт из пепла и базальта. От вулкана под землей паутиной расходятся подземные магматические русла, питающие бурлящие гейзеры и горячие источники, разбросанные по котловине. Здешняя изнуряющая жара легендарна: по замерам гоблинских приборов, она намного превышает обычную температуру вулканов, и плохо подготовленным исследователям опасно бродить здесь без достаточного запаса воды и тени."},{t="Логово элементалей",b="Вулкан — это стихийная топка, кишащая живым пламенем. Живые сполохи и бродячие элементали огня патрулируют раскаленные потоки, привлеченные скоплением чистого подземного жара. Глубоко в пещере возле вершины вулкана обитает Яропламень — бесспорный повелитель стихийных обитателей Ун'Горо. Подъем на вершину хребта сопряжен со смертельным жаром и переменчивыми духами стихий, которые яростно защищают свои огненные владения."}},faq={{q="Что за вулкан находится посреди кратера Ун'Горо?",a="Это Вулкан Огненного Венца, действующий вулкан в самом центре кратера Ун'Горо. Его каналы с расплавленной породой дают жар, который согревает окрестные джунгли и паровые источники.",al={"ungoro volcano name","volcano in center of ungoro","fire plume ridge location","название вулкана ун'горо","вулкан в центре ун'горо","где вулкан огненного венца"}},{q="Кто повелевает элементалями на Вулкане Огненного Венца?",a="В пещере на вершине обитает Яропламень, самый могущественный элементаль огня в кратере Ун'Горо.",al={"boss of fire plume ridge","blazerunner location","fire elemental boss ungoro","босс вулкана огненного венца","где яропламень","босс элементаль огня ун'горо"}},{q="Почему внутри вулкана застрял исследователь?",a="Искатель приключений Ринго, союзник гоблинов, отправился исследовать вулкан, но в одной из южных пещер его свалило сильное тепловое истощение, и без посторонней помощи ему не выбраться.",al={"who is stranded in fire plume ridge","ringo ungoro","lost guy in volcano","кто застрял в вулкане огненного венца","ринго ун'горо","потерявшийся в вулкане"}},{q="Как вулкан влияет на остальной Ун'Горо?",a="Неглубокие жилы магмы расходятся от Вулкана Огненного Венца под всем дном кратера, согревая землю и порождая многочисленные гейзеры, горячие источники и паровые озера по всей котловине.",al={"why is ungoro so hot","crater geothermal activity","shallow magma veins ungoro","почему в ун'горо так жарко","геотермальная активность кратера","жилы магмы ун'горо"}}},fp="16,228,24.574.0,19.446.0,52.167.0,45.96.0,51.187.0,48.205.0"}
P.entries["subzone:fire-scar-shrine"] = {n="Святилище Огненной Расщелины",s="Святилище Огненной Расщелины — оскверненное святилище ночных эльфов в юго-западных чащах Ясеневого леса. Когда-то оно было мирным местом поклонения, но было осквернено демонами и превратилось в нарыв скверны прямо у порога Астранаара.",h="Святилище Огненной Расщелины — оскверненное святилище ночных эльфов в юго-западных чащах Ясеневого леса.",kw={"akkrilus","ashenvale","astranaar","athrikus narassin","cult of the dark strand","fire scar shrine","ilkrud magthrull","shadow council","аккрилус","ясеневый лес","астранаар","атрикус нарассин","культ темной нити","святилище огненной расщелины","илкруд магтрулл","совет теней"},ang={["class:Warlock"]="Шрамы Скверны и дикие демонические призывы здесь несут явный отпечаток тонких проникновений Совета Теней по всему Калимдору.",["race:NightElf"]="Осквернение Святилища Огненной Расщелины — горькое оскорбление так близко от Астранаара, требующее скорой расплаты любым демонам, оскверняющим лес."},sec={{t="Язва в лесу",b="Святилище Огненной Расщелины находится к юго-западу от Астранаара и к западу от Руин Звездной Пыли. Оно служит мрачным напоминанием о яде Пылающего Легиона, оставшемся в Ясеневом лесу. Святилище подпало под власть демонической порчи, которую питали слуги Культа Темной Нити и Совета Теней. Магия Скверны превратила окрестную землю в обожженный камень, где бродячие демоны открыто собираются, бросая вызов защитникам леса."},{t="Тени Темной Нити",b="Падение святилища во тьму возглавили такие приспешники, как орк-чернокнижник Илкруд Магтрулл, действовавший по приказу Атрикуса Нарассина. Хотя порчу принесли смертные чародеи, призванные демоны теперь беспрепятственно бродят у алтарных камней. Местный разрыв в завесе порой привлекает и более страшных созданий, в том числе исполинского стража Скверны Аккрилуса."}},faq={{q="Где находится Святилище Огненной Расщелины?",a="Святилище Огненной Расщелины находится на юго-западе Ясеневого леса, прямо к юго-западу от главного поселения ночных эльфов Астранаара, к югу от Святилища Эссины и сразу к западу от Руин Звездной Пыли.",al={"fire scar shrine location","where is fire scar shrine","fire scar shrine map","где святилище огненной расщелины","святилище огненной расщелины расположение","святилище огненной расщелины карта"}},{q="Почему в Святилище Огненной Расщелины есть демоны?",a="Святилище было захвачено и осквернено агентами Совета Теней и Культа Темной Нити, в частности орком-чернокнижником Илкрудом Магтруллом. Их темные ритуалы призвали демонов и пропитали священную землю стойкой скверной.",al={"why demons here","what corrupted fire scar shrine","who summoned the demons","почему здесь демоны","что осквернило святилище огненной расщелины","кто призвал демонов"}},{q="Кто такой Аккрилус?",a="Аккрилус — грозный страж Скверны, который время от времени появляется возле Святилища Огненной Расщелины, привлеченный мощной демонической энергией, скопившейся вокруг оскверненных камней.",al={"akkrilus","doomguard at fire scar","rare demon fire scar shrine","аккрилус","страж скверны у огненной расщелины","редкий демон святилище огненной расщелины"}},{q="Как это место связано с Культом Темной Нити?",a="Орк-чернокнижник Илкруд Магтрулл, действовавший здесь, служил Атрикусу Нарассину, предводителю Культа Темной Нити. Они использовали святилище как опорный пункт для демонических призывов и своих темных замыслов в Ясеневом лесу.",al={"cult of the dark strand fire scar","dark strand connection","athrikus narassin fire scar","культ темной нити огненная расщелина","связь с темной нитью","атрикус нарассин огненная расщелина"}}},fp="16,241,22.447.0,26.372.0,34.181.0,41.238.0,16.163.0,68.226.0"}
P.entries["subzone:firewatch-ridge"] = {n="Гряда Огненной стражи",s="Гряда Огненной стражи — высокий вулканический утес на севере Тлеющего ущелья, главный лагерь дворфов Черного Железа. Она нависает прямо над огромной выработкой, известной как Котлован, и сильно укреплена дворфийскими часовыми, механическими големами и гнездящимися огненными пауками. На северо-западе система зловещих пещер выдает укоренившееся присутствие культа Сумеречного Молота.",h="Гряда Огненной стражи — высокий вулканический утес на севере Тлеющего ущелья, главный лагерь дворфов Черного...",kw={"cauldron","dark iron","firewatch ridge","flame spiders","golems","searing gorge","twilight's hammer","котлован","черное железо","гряда огненной стражи","огненные пауки","големы","тлеющее ущелье","сумеречный молот"},ang={["race:Dwarf"]="Для дворфов Стальгорна Гряда Огненной стражи — мрачное напоминание об укоренившейся злобе, железной промышленности и темных союзах их сородичей из Черного Железа в тени Черной горы."},sec={{t="Выжженная смотровая площадка",b="Гряда Огненной стражи, возвышающаяся над промышленной разрухой Котлована, служит важным плацдармом для действий клана Черного Железа в Тлеющем ущелье. Дворфийские стражи, инженеры и големы из расплавленного металла патрулируют скалы, яростно защищая свой оплот вместе с ядовитыми огненными пауками, обитающими на тлеющих камнях. Высота дает дворфам Черного Железа беспрепятственный обзор окрестных пепельных равнин и заблаговременно предупреждает о вторжениях соперников из Стальгорна или Братства Тория."},{t="Тень культа",b="На северо-западе гряды скрывается сеть подземных пещер, занятая Сумеречным Молотом. Эти культисты действуют в тени лагеря дворфов Черного Железа, проводят темные ритуалы и укрывают под скалами могущественных фанатиков-элитников. Их близость и к инфраструктуре дворфов Черного Железа, и к Черной горе отражает всепроникающее, коварное влияние культов стихий и конца света в огненном сердце Тлеющего ущелья."}},faq={{q="Что такое Гряда Огненной стражи?",a="Гряда Огненной стражи — возвышенность в Тлеющем ущелье, где дворфы Черного Железа устроили большой лагерь над местом раскопок Котлована.",al={"what is this place","firewatch ridge info","firewatch ridge overview","что это за место","гряда огненной стражи","гряда огненной стражи обзор"}},{q="Какие враги обитают на Гряде Огненной стражи?",a="На гряде обитают враждебные дворфы Черного Железа, механические големы и местные огненные пауки, а система пещер на северо-западе занята элитными членами культа Сумеречного Молота.",al={"what mobs are here","enemies firewatch","firewatch ridge threats","какие мобы здесь","враги гряды огненной стражи","угрозы гряды огненной стражи"}},{q="Почему здесь Сумеречный Молот?",a="Культ Сумеречного Молота обосновался в северо-западных пещерах гряды, чтобы вести поклонение стихиям и ритуалы конца света вблизи Черной горы и связанных в этом регионе элементалей огня.",al={"twilights hammer firewatch","cultists in cave","northwest cave firewatch","сумеречный молот гряда огненной стражи","культисты в пещере","северо-западная пещера"}},{q="Как Гряда Огненной стражи связана с Котлованом?",a="Гряда Огненной стражи расположена прямо над Котлованом и дает дворфам Черного Железа укрепленный наблюдательный пункт, откуда они следят за добычей и защищают свой карьер от возможных нападений.",al={"firewatch and cauldron","cauldron overlook","why overlook cauldron","гряда огненной стражи и котлован","вид на котлован","зачем смотреть на котлован"}}},fp="15,407,24.518.0,22.461.0,24.153.0,37.195.0,34.235.0,48.191.0"}
P.entries["subzone:foothold-citadel"] = {n="Цитадель",s="Цитадель — центральные военные казармы и командный пункт на острове Терамор. Возвышаясь над укрепленным поселением, она служит обиталищем офицеров и стражей, защищающих главный оплот Альянса на юге Калимдора.",h="Цитадель — центральные военные казармы и командный пункт на острове Терамор.",kw={"barracks","daelin proudmoore","dustwallow marsh","foothold citadel","garran vimes","gustaf vanhowzen","samaul","theramore","казармы","даэлин праудмур","пылевые топи","цитадель","гарран веймс","густав ван склифф","самаул","терамор"},ang={["faction:Alliance"]="Цитадель — главный военный оплот Альянса на юге Калимдора; она координирует оборону от болотных тварей, мародеров Зловещего Тотема и бдительных разведчиков Орды.",["faction:Horde"]="Для Орды Цитадель — место, где Рексар и Тралл положили конец мстительному походу верховного адмирала Праудмура, обеспечив выживание Дуротара."},sec={{t="Сердце тераморской стражи",b="Цитадель, поднимающаяся за укрепленными каменными стенами острова Терамор, — нервный центр местной обороны Альянса. Здесь размещается верховное командование тераморской стражи, включая капитана Гаррана Веймса и командира Самаула, а также полевых медиков, офицеров снабжения и интендантов. Ее суровые каменные залы полны регулярных патрулей и тренировок, благодаря которым силы леди Джайны Праудмур готовы к угрозам, выползающим из окрестных болот."},{t="Отголоски падения адмирала",b="Цитадель хранит мрачную историю, связанную с первыми днями Терамора. Когда верховный адмирал Даэлин Праудмур захватил город, чтобы вести личный крестовый поход против Орды, именно эта крепость стала полем его последней битвы. Союзный отряд Тралла во главе с воином-мок'нафалом Рексаром ворвался в цитадель и сразил адмирала. Сегодня крепость восстановлена и неприступна, но память о кровавом сражении по-прежнему витает над ее каменными стенами."}},faq={{q="Для чего служит Цитадель?",a="Цитадель служит штабом и военными казармами тераморской стражи. Здесь размещаются командиры, тактики, учебные помещения и тыловой персонал, например местный казначей и медики.",al={"foothold citadel purpose","theramore barracks","what is this building","назначение цитадели","казармы терамора","что это за здание"}},{q="Что произошло здесь с верховным адмиралом Даэлином Праудмуром?",a="Во время конфликта после Третьей войны верховный адмирал Даэлин Праудмур захватил Терамор, чтобы воевать с молодой Ордой. Объединенный отряд под предводительством героя Рексара штурмовал цитадель и убил адмирала в его собственном штабе.",al={"daelin death","daelin proudmoore last stand","who killed daelin","смерть даэлина","последний бой даэлина праудмура","кто убил даэлина"}},{q="Кто сейчас командует в Цитадели?",a="Оперативное командование гарнизоном лежит на офицерах, таких как капитан Гарран Веймс и командир Самаул, которые руководят ежедневными патрулями и охраной региона под верховной властью леди Джайны Праудмур.",al={"who leads the citadel","theramore guard commander","citadel leader","кто возглавляет цитадель","командир тераморской стражи","глава цитадели"}},{q="Можно ли получить медицинскую помощь в цитадели?",a="Да. В Цитадели живет Доктор Густав ван Склифф: он лечит раненых стражников и обучает путников из Альянса передовой полевой медицине и сортировке раненых.",al={"citadel doctor","theramore medic","first aid trainer theramore","доктор цитадели","медик терамора","учитель первой помощи терамор"}}},fp="16,233,28.476.0,28.503.0,34.229.0,54.241.0,47.204.0,45.164.0"}
P.entries["subzone:forest-s-edge"] = {n="Лесная опушка",s="Лесная опушка — лесистый клин земли на юго-западной границе Элвиннского леса, окруженный реками, ведущими к Западному Краю. Эту дикую местность, которую с севера охраняет Гарнизон у Западного ручья, опасно захватили гноллы Речной Лапы под началом пресловутого Дробителя.",h="Лесная опушка — лесистый клин земли на юго-западной границе Элвиннского леса, окруженный реками, ведущими к...",kw={"elwynn forest","forest's edge","forests edge","gnolls","hogger","nazferiti river","riverpaw","westbrook garrison","элвиннский лес","лесная опушка","гноллы","река назферити","речная лапа","гарнизон у западного ручья"},ang={["faction:Alliance"]="Для новобранцев, расквартированных в Элвиннском лесу, зачистка Лесной опушки и победа над Дробителем — одно из первых серьезных испытаний, доказывающих перед короной их боевую готовность.",["profession:Herbalism"]="На тихих берегах рек и в тенистых рощах Лесной опушки растут обычные лесные травы, хотя при сборе часто приходится уклоняться от агрессивных патрулей гноллов."},sec={{t="Спорная граница",b="Лесная опушка, затерянная к юго-западу от Штормграда между Садом у Зеркального озера и реками на границе Западного Края, образует естественный лесной полуостров. Несмотря на близость Гарнизона у Западного ручья, малочисленность Армии Штормграда оставила местность уязвимой для диких зверей и разбойничьих шаек. Среди деревьев и по берегам рек бродят кабаны, но главная угроза — гноллы Речной Лапы, сделавшие эти леса своим плацдармом."},{t="Оплот Дробителя",b="Леса Лесной опушки — охотничьи угодья Дробителя, огромного и жестокого вожака гноллов. За его голову Армия Штормграда назначила крупную награду, а Дробитель направляет свою стаю на травлю путников и набеги на окрестные фермы, превращая мирный лес в смертельное испытание для молодых искателей приключений из Альянса."}},faq={{q="Где именно находится Лесная опушка?",a="Лесная опушка расположена в юго-западном углу Элвиннского леса. Она лежит к югу от Гарнизона у Западного ручья, граничит с Садом у Зеркального озера и водными путями, ведущими в Западный Край.",al={"forests edge location","where is forests edge","forest edge map","лесная опушка местоположение","где лесная опушка","лесная опушка карта"}},{q="Почему эта местность так опасна?",a="Большая и агрессивная стая гноллов Речной Лапы заняла лес и угрожает путникам на юго-западной границе. Главная опасность — их вожак Дробитель, исключительно свирепый гнолл, бродящий по этим лесам.",al={"why dangerous forests edge","what is at forest edge","forests edge threats","почему опасна лесная опушка","что на лесной опушке","угрозы лесной опушки"}},{q="Кто такой Дробитель?",a="Дробитель — известный и могучий вожак гноллов, виновный в жестоких нападениях на границы Элвинна. Армия Штормграда назначила щедрую награду за доказательство его смерти и предостерегает искателей приключений от встречи с ним в одиночку.",al={"hogger lore","who is hogger","hogger info","дробитель предания","кто такой дробитель","дробитель информация"}},{q="Почему Гарнизон у Западного ручья не очистил местность?",a="Армия Штормграда крайне растянута по всему королевству. Из-за беспорядков в Западном Крае и угроз со всех сторон гарнизону не хватает людей, чтобы разгромить лагеря гноллов, и эта задача ложится на добровольцев-искателей приключений.",al={"why westbrook garrison not clearing","why stormwind guards not help","westbrook guards","почему гарнизон западного ручья не очищает","почему стража штормграда не помогает","стража западного ручья"}}},fp="13,287,20.464.0,19.341.0,31.181.0,30.221.0,14.212.0,47.232.0"}
P.entries["subzone:forest-song"] = {n="Лесная Песнь",s="Лесная Песнь — древние руины ночных эльфов на северо-востоке Ясеневого леса, рядом с оскверненными лесами Сатирнаара и великим порталом Тенистой Кроны. Сейчас они почти пусты, если не считать бдительного друида Кайнета Штиля, охраняющего восточную границу от новых угроз.",h="Лесная Песнь — древние руины ночных эльфов на северо-востоке Ясеневого леса, рядом с оскверненными лесами...",kw={"ashenvale","bough shadow","eastern ashenvale","forest song","kaldorei ruins","kayneth stillwind","satyrnaar","ясеневый лес","тенистая крона","восточный ясеневый лес","лесная песнь","руины кальдораев","кайнет штиль","сатирнаар"},ang={["class:Druid"]="Тихое присутствие Кайнета Штиля подчеркивает одинокий дозор Круга Кенария в оскверненных пограничных землях, прямо под сумрачным пологом леса близ Великого Древа Тенистой Кроны.",["faction:Alliance"]="Лесная Песнь служит важным одиноким форпостом для искателей приключений из Альянса, идущих через северо-восток Ясеневого леса к Азшаре или в Оскверненный лес."},sec={{t="Одинокий дозор в восточном Ясеневом лесу",b="Лесная Песнь, скрытая в густых лесах северо-востока Ясеневого леса, когда-то была изящным поселением кальдораев. Ныне белые каменные колонны и рушащиеся арки поросли плющом и диким папоротником. Руины лежат к северо-востоку от Сатирнаара и сразу к северу от наступающих Лесозаготовок Песни Войны и тихо, но стратегически выгодно обозревают восточные тропы к Азшаре и Тенистой Кроне. Хотя окрестные леса поражены демонической скверной и набегами Орды, сами руины сохраняют призрачный, безмятежный покой."},{t="Страж границы",b="Лесную Песнь ныне охраняет лишь друид Кайнет Штиль. Из этого разрушающегося форпоста Штиль следит за темными замыслами врагов, проникающих в глушь, включая тревожное присутствие Отрекшихся в восточных лесах. Хотя святилище удалено от Астранаара и лишено гарнизонных укреплений, оно служит важным сборным пунктом для путников из Альянса, идущих по северной дороге в Оскверненный лес или изучающих скверну, расползающуюся под пологом деревьев."}},faq={{q="Кто живет в Лесной Песни?",a="Сейчас в Лесной Песни обитает ночной эльф-друид Кайнет Штиль, в одиночку несущий дозор среди древних руин.",al={"who is at forest song","forest song npcs","forest song inhabitants","кто в лесной песни","персонажи лесной песни","жители лесной песни"}},{q="Какие угрозы есть рядом с Лесной Песнью?",a="Руины опасно близки к Сатирнаару на юго-западе, кишащему оскверненными сатирами, и к Лесозаготовкам Песни Войны на юге. На северо-востоке лежит Тенистая Крона, где зеленый драконий род охраняет Великое Древо, ведущее в Изумрудный Сон.",al={"forest song dangers","enemies near forest song","опасности лесной песни","враги рядом с лесной песнью"}},{q="Почему Кайнет Штиль находится здесь?",a="Кайнет следит за передвижениями врагов в восточных лесах и направляет союзников против местных опасностей, включая зловещие замыслы и болезни, которые распространяют действующие в этих местах Отрекшиеся.",al={"why is kayneth here","kayneth stillwind purpose","почему кайнет здесь","кайнет штиль задача"}},{q="Является ли Лесная Песнь крупным поселением Альянса?",a="Нет. В отличие от Астранаара, Лесная Песнь — в основном неукрепленные руины без действующего гарнизона, торговцев и военной инфраструктуры, поддерживаемые лишь как одинокий передовой наблюдательный пост.",al={"alliance town forest song","is forest song a town","поселение альянса лесная песнь","лесная песнь город"}}},fp="11,297,35.537.0,21.515.0,25.126.0,34.252.0,40.197.0,43.177.0"}
P.entries["subzone:forgotten-coast"] = {n="Забытый берег",ang={["faction:Horde"]="К берегу нужно подбираться осторожно: южная тропа проходит рядом с паромными пристанями ночных эльфов, а северные лесные тропы обеспечивают более безопасный путь к воде."},sec={{t="Край тропического леса",b="Забытый берег, протянувшийся вдоль западной окраины Фераласа, — открытое всем ветрам побережье у просторов Сокрытого Моря. В отличие от густого леса вглубь суши, эта граница открыта стихиям, и здесь властвуют огромные морские великаны и бродящие по прибою водные элементали. Путникам, выходящим из-под полога леса, приходится сталкиваться с этими древними стражами побережья, пробираясь к морю, откуда паромы ходят к оплоту ночных эльфов — Острову Сардор."}},faq={{q="Какие угрозы бродят по Забытому берегу?",a="The shoreline is patrolled by immense sea giants and restless water elementals emerging from the Veiled Sea.",al={"monsters on forgotten coast","forgotten coast dangers","what is on the coast","монстры забытого берега","опасности забытого берега","что на берегу"}},{q="Как добраться отсюда до Крепости Оперенной Луны?",a="Берег — главный материковый пункт отправления через пролив к Острову Сардор, где ночные эльфы держат Крепость Оперенной Луны. Небольшая паромная пристань на берегу обеспечивает безопасный путь по воде в обход опасных морских великанов.",al={"how to get to feathermoon","boat to feathermoon","feathermoon ferry","как добраться до оперенной луны","лодка до оперенной луны","паром оперенной луны"}},{q="Is the Forgotten Coast accessible to the Horde?",a="Yes. While the southern road leads directly toward the night elven crossing to Feathermoon Stronghold, a secondary path cuts down to the coast further to the north, allowing Horde travelers to reach the shore without straying into Alliance sentinels.",al={"horde access forgotten coast","how does horde reach coast","safe horde path forgotten coast"}}},fp="15,180,22.489.0,40.108.0,50.253.0,47.250.0"}
P.entries["subzone:forgotten-pool"] = {n="Забытый пруд",s="Забытый пруд — затопленная пещера в глубине залитых водой коридоров Непроглядной Пучины. Этот тихий тупик за Руинами Лунного святилища служит водным логовом чудовищных глубоководных хищников, таящихся в подземной тьме.",h="Забытый пруд — затопленная пещера в глубине залитых водой коридоров Непроглядной Пучины.",kw={"blackfathom deeps","cavern","forgotten pool","moonshrine ruins","old serra'kis","thresher","underwater","непроглядная пучина","пещера","забытый пруд","руины лунного святилища","старина серракис","молотильщик","под водой"},ang={["faction:Horde"]="Разведчики Орды, отправляющиеся в Непроглядную Пучину, могут найти Старину Серракиса в затопленной тьме пруда, вдали от залов, где поют культисты."},sec={{t="Затопленное логово",b="Чтобы добраться до Забытого пруда, нужно нырнуть в затонувшие подземные водные пути за Руинами Лунного святилища. Отрезанный от суши, пруд — изолированная застойная пещера, целиком залитая темной водой. Вдали от поющих культистов Сумеречного Молота и патрулирующих наг этот укромный уголок служит логовом древнего водного ужаса — Старины Серракиса, скрытого во тьме под водой."}},faq={{q="Где находится Забытый пруд?",a="Забытый пруд — полностью затопленная подводная пещера в глубине Непроглядной Пучины. Чтобы добраться до нее, исследователям нужно проплыть по затопленным туннелям, ответвляющимся за Руинами Лунного святилища.",al={"where is forgotten pool","forgotten pool location","how to find forgotten pool","где забытый пруд","расположение забытого пруда","как найти забытый пруд"}},{q="Что скрывается в Забытом пруду?",a="Пещера служит тайным логовом Старины Серракиса, древнего глубоководного зверя, похожего на молотильщика, который устроил в этом укромном тупике свое логово.",al={"forgotten pool monster","who lives in forgotten pool","forgotten pool boss","монстр забытого пруда","кто живет в забытом пруду","босс забытого пруда"}},{q="Ведет ли Забытый пруд куда-нибудь еще?",a="Нет. Пруд — подводный тупик без дальнейших проходов, служащий исключительно укромным водным гнездом.",al={"is forgotten pool a dead end","where does forgotten pool go","забытый пруд тупик","куда ведет забытый пруд"}}},fp="14,254,16.435.0,36.203.0,37.147.0,43.112.0"}
P.entries["subzone:forgotten-pools"] = {n="Забытые пруды",s="Забытые пруды — самый северный из зеленых оазисов, разбросанных по засушливым Степям, к северо-западу от Перекрестка. Этот яркий уголок с густой растительностью и водой питают подземные источники, и за него ведут ожесточенную борьбу местные животные, бродячие кентавры из племени Колкар и Орда.",h="Забытые пруды — самый северный из зеленых оазисов, разбросанных по засушливым Степям, к северо-западу от...",kw={"barrens","centaur","crossroads","deviate fish","forgotten pools","kolkar","laden mushrooms","oasis","степи","кентавр","перекресток","загадочная рыба","забытые пруды","колкар","грибы-тяжеловесы","оазис"},ang={["class:Druid"]="Быстрый рост мутировавших растений и Загадочной рыбы вокруг этих прудов служит важным свидетельством для исследователей Кенарийского круга, изучающих неестественные перемены в Степях.",["faction:Horde"]="Удержание прудов жизненно важно для безопасности торговых путей, расходящихся от Перекрестка, и не дает Колкару перерезать западные линии снабжения Орды."},sec={{t="Оазис в пустошах",b="Situated off the western road leading out of the Crossroads, the Forgotten Pools offers a stark contrast to the parched savannas that surround it. Thick reeds, palm trees, and unusual flora like Laden Mushrooms cluster around its freshwater shore, drawing plainstriders, snapjaw turtles, and zhevras from miles around. However, the oasis is far from peaceful. Kolkar centaur maintain a constant encampment along the banks, jealously guarding the water supply against travelers and bringing them into direct conflict with Horde travelers from the Crossroads."},{t="Экологические загадки",b="Помимо стратегической ценности водопоя, Забытые пруды отличаются своеобразными особенностями. Это одна из редких поверхностных вод в регионе, где водится загадочная Загадочная рыба, что намекает на глубинную подземную связь со странными преобразующими энергиями, которые меняют грунтовые воды Степей. Натуралисты и разведчики Орды внимательно следят за водой и необычными грибными зарослями по берегам, опасаясь того, что может просачиваться в почву."}},faq={{q="Где находятся Забытые пруды?",a="Забытые пруды лежат на севере Степей, прямо к северо-западу от Перекрестка, чуть севернее дороги, которая ответвляется на запад к Когтистым горам.",al={"forgotten pools location","where is forgotten pools","find forgotten pools","забытые пруды расположение","где находятся забытые пруды","как найти забытые пруды"}},{q="Почему здесь живут кентавры Колкар?",a="В засушливых Степях вода — это жизнь. Колкар агрессивно захватывают каждый оазис, до которого могут добраться, чтобы обеспечивать свои отряды и лишать жизненно важных ресурсов проходящие караваны Орды и ближайшие поселения.",al={"centaur at forgotten pools","why are kolkar here","kolkar forgotten pools","кентавры у забытых прудов","почему здесь колкар","колкар забытые пруды"}},{q="Чем необычны здешние рыба и растения?",a="Оазис — одно из немногих мест на поверхности, где можно поймать Загадочную рыбу, и здесь растут скопления необычных грибов-тяжеловесов. Эти странные мутации указывают на подземные возмущения, влияющие на подземные водоносные слои Степей.",al={"deviate fish forgotten pools","laden mushrooms","why are fish weird here","загадочная рыба забытые пруды","грибы-тяжеловесы","почему рыба странная"}},{q="Проходил ли Тралл через этот оазис?",a="Нигде не записано, в каких оазисах отдыхала Орда Тралла во время долгого перехода через Степи, поэтому неизвестно, были ли среди них Забытые пруды.",al={"thrall forgotten pools","did orcs camp here","warcraft 3 oasis","тралл забытые пруды","стояли ли орки лагерем здесь","оазис warcraft 3"}}},fp="15,303,22.557.0,20.456.0,38.162.0,32.194.0,44.237.0,35.152.0"}
P.entries["subzone:forlorn-cloister"] = {n="Покинутый двор",s="Покинутый двор — призрачное кладбищенское крыло Монастыря Алого ордена. Здесь члены Алого ордена отчаянно сжигают тела павших братьев, чтобы те не восстали нежитью, а неупокоенные духи и шаркающие мертвецы бродят среди гробниц.",h="Покинутый двор — призрачное кладбищенское крыло Монастыря Алого ордена.",kw={"forlorn cloister","graveyard","scarlet crusade","scarlet monastery","thalnos","tirisfal glades","покинутый двор","кладбище","алый орден","монастырь алого ордена","талнос","тирисфальские леса"},ang={["class:Priest"]="Прогулка по Покинутому двору — суровое напоминание о том, что бывает, когда святыни падают во тьму, а священные обряды сменяются лихорадочными кострами и измученными призраками.",["race:Undead"]="Отрекшиеся видят во дворе мрачную иронию: ревностные крестоносцы, клеймящие всю нежить чудовищами, не могут даже помешать собственным братьям вставать у них под ногами."},sec={{t="Поглощенное освящение",b="Когда-то это было мирное святилище, где жрецы и паладины Лордерона предавали земле своих почитаемых мертвецов, но Покинутый двор стал мрачным склепом. Несмотря на фанатичную бдительность Алого ордена, скверна чумы глубоко проникла в землю. Крестоносцы с факелами патрулируют окутанное туманом кладбище и лихорадочно сжигают останки, чтобы остановить гниение. И все же призраки скользят между склепами, а мертвецы выбираются из могил под властью темной магии в глубине владений."},{t="Владыка гробниц",b="Глубоко во дворе скрывается Волшебник Крови Талнос, садистский палач Алого ордена, чья ужасная судьба воплощает трагедию Монастыря. Заразившись чумой, он восстал скелетом-ужасом, принял темный некромантский путь: подчиняет души умерших и убивает всякого, кто осмелится вторгнуться на его оскверненное кладбище."}},faq={{q="Где находится Покинутый двор?",a="Покинутый двор образует открытое кладбищенское крыло Монастыря Алого ордена и расположен в северо-восточном углу Тирисфальских лесов.",al={"forlorn cloister location","where is cloister","graveyard wing","покинутый двор расположение","где двор","кладбищенское крыло"}},{q="Почему крестоносцы Алого ордена сжигают здесь тела?",a="Орден сжигает мертвых в отчаянной попытке не дать чуме Плети оживить павших соратников. Поскольку земля двора уже осквернена, несожженные тела быстро восстают бездумными зомби.",al={"why burn corpses","burning bodies scarlet","what are crusaders doing","зачем жечь трупы","сожжение тел алый орден","что делают крестоносцы"}},{q="Кто правит Покинутым двором?",a="Кладбищем владеет Волшебник Крови Талнос, могущественный маг-нежить, который повелевает бродячими мертвецами и нападает на всех живых чужаков.",al={"cloister boss","who is in charge here","graveyard boss","босс двора","кто здесь главный","босс кладбища"}},{q="Почему кладбище населено призраками, если Монастырем владеет Алый орден?",a="Несмотря на религиозное рвение, крестоносцы потеряли контроль над собственным кладбищем. Неослабевающие некромантские энергии, охватившие Лордерон, подняли погребенных мертвецов, и живой гарнизон оказался в бесконечной борьбе с духами своих бывших соратников.",al={"why are there ghosts","why undead in monastery","is graveyard scourge","почему здесь призраки","почему нежить в монастыре","кладбище плеть"}}},fp="16,270,23.503.0,23.332.0,38.138.0,50.217.0,36.144.0,72.281.0"}
P.entries["subzone:forlorn-ridge"] = {n="Одинокая вершина",s="Одинокая вершина — высокая горная гряда, возвышающаяся над юго-западной частью Азшары. Ее выгодная высота и великолепный обзор побережья привлекли внимание и Альянса, и Орды, и каждый возвел укрепления на ее склонах.",h="Одинокая вершина — высокая горная гряда, возвышающаяся над юго-западной частью Азшары.",kw={"azshara","forlorn ridge","fortifications","mountain","ruins of eldarath","volcano","азшара","одинокая вершина","укрепления","гора","руины эльдарата","вулкан"},ang={["faction:Alliance"]="Удержание высот Одинокой вершины дает раннее предупреждение и тактический обзор передвижений Орды, растекающейся на восток из Степей и Ясеневого леса.",["faction:Horde"]="Для Орды закрепление на Одинокой вершине помогает защитить труднодоступные приграничные земли Азшары к северу от Дуротара от вторжений Альянса."},sec={{t="Спорная обзорная точка",b="Резко поднимаясь над осенними лесами западной Азшары, Одинокая вершина господствует над местностью. Напоминая древний давно уснувший вулкан, она с высоты открывает широкий вид на подходы к побережью и разрушенные эльфийские поместья внизу. Поскольку контроль над этими высотами определяет военное превосходство в округе, и силы Альянса, и силы Орды устроили лагеря и форпосты на горных склонах и настороженно следят друг за другом поверх неровных утесов."}},faq={{q="Что такое Одинокая вершина?",a="Одинокая вершина — заметная горная вершина на юго-западе Азшары, возвышающаяся над окрестной глушью и прибрежными дорогами.",al={"where is forlorn ridge","forlorn ridge azshara","what is this mountain","где одинокая вершина","одинокая вершина азшара","что это за гора"}},{q="Почему Альянс и Орда сражаются за эту вершину?",a="С вершины открывается непревзойденный обзор западной Азшары. Тот, кто владеет высотой, может следить за передвижением войск между прибрежными руинами и внутренними перевалами, поэтому обе фракции укрепили позиции на ее склонах.",al={"why are there camps here","who controls forlorn ridge","alliance vs horde forlorn ridge","почему здесь лагеря","кто контролирует одинокую вершину","альянс против орды одинокая вершина"}},{q="Была ли Одинокая вершина когда-то вулканом?",a="Особая форма и грубый состав горы говорят о том, что в далеком прошлом она могла быть вулканом, хотя давно затихла и заросла.",al={"is forlorn ridge a volcano","volcano in azshara","одинокая вершина вулкан","вулкан в азшаре"}}},fp="13,256,19.496.0,22.133.0,56.230.0,39.176.0"}
P.entries["subzone:forlorn-rowe"] = {n="Покинутая усадьба",s="Покинутая усадьба — зловещий темный холм на северной границе Кладбища Вороньего Холма в Сумеречном лесу. Он известен как мрачное обиталище Морбента Скверна, некроманта, чья злая магия оживляет неупокоенных мертвецов по всему лесу.",h="Покинутая усадьба — зловещий темный холм на северной границе Кладбища Вороньего Холма в Сумеречном лесу.",kw={"cemetery","duskwood","forlorn rowe","morbent fel","necromancer","raven hill","undead","кладбище","сумеречный лес","покинутая усадьба","морбент скверн","некромант","вороний холм","нежить"},ang={["class:Paladin"]="Темные обряды, творимые в Покинутой усадьбе, — оскорбление Света, и чтобы пробить защиту некроманта, нужны освященные реликвии и праведный гнев.",["faction:Alliance"]="Изгнание Морбента Скверна из Покинутой усадьбы крайне важно, чтобы вернуть хоть какую-то безопасность западной границе Сумеречного леса."},sec={{t="Средоточие некромантии",b="Покинутая усадьба возвышается вдоль северного края Кладбища Вороньего Холма и вечно окутана мраком. На вершине стоит дом Морбента Скверна, подобного личу некроманта, ответственного за большинство ходячих мертвецов, населяющих окрестные земли. Скованный мерзкими арканными чарами, хозяин холма управляет скелетами-слугами отсюда, из-за чего весь северо-западный угол Сумеречного леса опасен для путников."},{t="Очищение холма",b="Власть Морбента Скверна над Покинутой усадьбой нельзя сломить обычной сталью. Его темные чары защищают тело от смертного оружия, пока он не ослабнет от особых реликвий священной силы. Чтобы одолеть некроманта и разрушить его власть над лесом, искателям приключений нужно добыть освященное оружие и ударить в самое сердце проклятия, душащего кладбище."}},faq={{q="Где находится Покинутая усадьба?",a="Покинутая усадьба находится на северо-западе Сумеречного леса, прямо на северном хребте над раскинувшимся Кладбищем Вороньего Холма.",al={"forlorn rowe location","where is forlorn rowe","find forlorn rowe","покинутая усадьба расположение","где покинутая усадьба","найти покинутую усадьбу"}},{q="Кто живет в Покинутой усадьбе?",a="Это логово Морбента Скверна, могущественного и злобного некроманта, который с помощью темных арканных обрядов поднимает и ведет легионы нежити, бродящей по Сумеречному лесу.",al={"who is at forlorn rowe","forlorn rowe boss","house on the hill duskwood","кто в покинутой усадьбе","босс покинутой усадьбы","дом на холме сумеречный лес"}},{q="Почему здесь так трудно сражаться с Морбентом Скверном?",a="Морбент Скверн защищается мерзкой магией, и обычные атаки почти бесполезны, пока освященная реликвия, созданная для рассеивания его магии, не лишит его темной защиты.",al={"morbent fel shield","morbent fel immune","how to kill morbent fel","щит морбента скверна","морбент скверн неуязвим","как убить морбента скверна"}},{q="Входит ли Покинутая усадьба в состав кладбища?",a="Да, это возвышенный утес вдоль северной границы Кладбища Вороньего Холма, прямо над могилами и склепами внизу.",al={"is forlorn rowe raven hill","raven hill connection","покинутая усадьба вороний холм","связь с вороньим холмом"}}},fp="12,253,20.441.0,18.396.1,34.140.0,30.158.0,41.184.1,41.141.0"}
P.entries["subzone:fray-island"] = {n="Остров Битв",s="Остров Битв — скалистый остров, обдуваемый всеми ветрами, недалеко от Торгового побережья Степей. На нем находится грубая тренировочная арена, и он известен как нейтральное убежище, где воины со всего Азерота приходят проверить свою доблесть.",h="Остров Битв — скалистый остров, обдуваемый всеми ветрами, недалеко от Торгового побережья Степей.",kw={"affray","barrens","berserker stance","big will","fray island","klannoc macleod","побоище","степи","стойка берсерка","большой уилл","остров битв","кланнок маклеод"},ang={["class:Warrior"]="Остров Битв — важное место для вашего обучения. Кланнок Маклеод и испытание Побоища проверят, достаточно ли у вас дисциплины и силы, чтобы принять стойку берсерка.",["race:Human"]="Кланнок Маклеод — человек, но воинов, собирающихся на его арене, объединяет боевое братство, не знающее расовых границ."},sec={{t="Испытательная площадка для бойцов",b="Остров Битв расположен у восточных утесов Степей, вдали от бдительных глаз Оргриммара и Терамора. Он служит местом обучения воинов всех рас и верований. В его центре находится арена, за которой присматривает Кланнок Маклеод; здесь опытные бойцы и неопытные новобранцы собираются, чтобы участвовать в жестоких схватках."},{t="Испытание Побоища",b="Несмотря на враждебность окружающих вод, центральная арена острова подчиняется простому кодексу боевого поединка. Воины приходят сюда по указанию своих наставников, чтобы принять участие в «Побоище» — изнурительном испытании против волн соперников, которое завершается схваткой с чемпионом Большим Уиллом. Здесь принадлежность к Орде или Альянсу отступает перед грубой силой и воинской дисциплиной."}},faq={{q="Для чего нужен Остров Битв?",a="Остров служит тренировочной площадкой для воинов и местом жестокого боевого испытания — Побоища. Воины обеих фракций приходят сюда, чтобы доказать свою выносливость и освоить продвинутые стойки.",al={"why go to fray island","fray island purpose","what is on fray island","зачем идти на остров битв","назначение острова битв","что находится на острове битв"}},{q="Кто управляет Островом Битв?",a="Ни одно королевство и ни одна фракция не правит им. Остров — место обучения воинов всех рас и верований, а его арена действует под присмотром наставника воинов Кланнока Маклеода.",al={"who runs fray island","who lives on fray island","fray island faction","кто управляет островом битв","кто живет на острове битв","фракция острова битв"}},{q="Как добраться до Острова Битв?",a="Остров Битв лежит в Великом море у восточного побережья Степей, к югу от Кабестана. Чтобы добраться до него, нужно долго плыть от материкового берега через воды, кишащие акулами и безумствующими хищниками.",al={"getting to fray island","where is fray island","how to get to fray island","как добраться до острова битв","где остров битв","путь на остров битв"}},{q="Что такое Побоище?",a="Побоище — испытание на выносливость, проходящее в бойцовской клетке острова. Воин должен встать на решетку и победить волны соперников, а затем одолеть бойца Большого Уилла.",al={"the affray","fray island arena","big will fight","побоище","арена острова битв","бой с большим уиллом"}}},fp="11,225,29.347.0,23.411.0,29.202.0,25.188.0,27.190.0,19.194.0"}
P.entries["subzone:frayfeather-highlands"] = {n="Высокогорье Блеклых Перьев",s="Высокогорье Блеклых Перьев — возвышенная глушь в густых лесах Фераласа. Это отдаленное плато — исконное место обитания и гнездовье диких гиппогрифов Блеклых Перьев. Отважные собиратели и натуралисты нередко рискуют встретиться с их воинственными стаями в поисках целых яиц гиппогрифов.",h="Высокогорье Блеклых Перьев — возвышенная глушь в густых лесах Фераласа.",kw={"eggs","feralas","frayfeather","gadgetzan","highlands","hippogryph","nests","яйца","фералас","блеклые перья","прибамбасск","высокогорье","гиппогриф","гнезда"},ang={["class:Druid"]="Друиды высоко чтят диких зверей Калимдора и видят в нетронутых гнездовьях Высокогорья Блеклых Перьев чистое отражение первозданной жизненной силы леса.",["race:NightElf"]="Ночные эльфы почитают гиппогрифов как священных спутников Элуны, поэтому дикие гнезда в Фераласе — важная природная среда, которую нужно оберегать от безрассудной эксплуатации."},sec={{t="Гнездовье гиппогрифов",b="Rising above the surrounding forest floor of Feralas, the Frayfeather Highlands are dominated by steep slopes and crags where wild hippogryphs raise their broods. The local flocks are notoriously aggressive toward intruders, fiercely defending the scattered nests tucked among the rock shelves. Because these beasts are so well adapted to the rugged cliffs, their nesting grounds have drawn significant interest from outsiders—most notably goblin entrepreneurs in distant Gadgetzan who seek unhatched eggs for study and profit."}},faq={{q="Какие существа обитают в Высокогорье Блеклых Перьев?",a="В высокогорье обитают в основном большие стаи диких гиппогрифов Блеклых Перьев, которые гнездятся на высоких скалах и агрессивно защищают свою территорию от незваных гостей.",al={"frayfeather wildlife","what is here","frayfeather beasts","фауна блеклых перьев","что здесь есть","звери блеклых перьев"}},{q="Почему путешественников интересуют гнезда гиппогрифов?",a="В гнездах лежат редкие яйца гиппогрифов. Искатели приключений собирают пригодные яйца и доставляют их через Танарис в Прибамбасск, где гоблины перерабатывают их в Супер-Яйцо-Матике для исследований и наживы.",al={"hippogryph eggs","egg quest","why steal eggs","яйца гиппогрифов","задание на яйца","зачем красть яйца"}},{q="Где находится Высокогорье Блеклых Перьев?",a="Высокогорье расположено в южной части Фераласа, над основным пологом джунглей, и отличается скалистыми склонами и открытыми гнездовыми уступами.",al={"frayfeather location","where is frayfeather highlands","how to find frayfeather","где блеклые перья","где высокогорье блеклых перьев","как найти высокогорье блеклых перьев"}}},fp="21,293,24.529.0,49.177.0,53.200.0,44.167.0"}
P.entries["subzone:freewind-post"] = {n="Застава Вольного Ветра",s="Застава Вольного Ветра — главный оплот Орды в Тысяче Игл, расположенный высоко на одной из величественных каменных столовых гор каньона. Попасть туда можно в основном на подъемнике тауренов и по извилистым веревочным мостам; застава служит защитным убежищем от военных отрядов кентавров и важным передовым пунктом.",h="Застава Вольного Ветра — главный оплот Орды в Тысяче Игл, расположенный высоко на одной из величественных...",kw={"darkcloud pinnacle","elevator","freewind post","galak","highperch","mesa","tauren","thousand needles","wyverns","пик темного облака","подъемник","застава вольного ветра","галак","скальное гнездовье","столовая гора","таурен","тысяча игл","виверны"},ang={["faction:Horde"]="Застава Вольного Ветра — единственное крупное убежище Орды и пункт полетов между Южными степями и Танарисом, обеспечивающий важную логистическую поддержку в центральном Калимдоре.",["race:Tauren"]="Застава Вольного Ветра демонстрирует архитектурную изобретательность шу'хало: они приспособили высоты мезы, чтобы не пускать традиционных кентавров-мародеров, и при этом ухаживают за древними наездничьими вивернами утесов."},sec={{t="Крепость в небесах",b="Застава Вольного Ветра построена прямо на столовых горах каньона и полагается на изобретательность и высоту для защиты своих жителей. Кентавры Галака господствуют на засушливом дне каньона внизу, но не могут ни взобраться на высокие утесы, ни взять тяжелые деревянные подъемники, поднимающие путников Орды в небо. Лабиринт веревочных и дощатых мостов соединяет Вольный Ветер с соседними шпилями, образуя надежное гнездовье. Помимо отражения набегов кентавров застава сдерживает визгливых гарпий, гнездящихся на утесах, и ухаживает за землями виверн в Скальном гнездовье, где диких яиц отбирают и выращивают верных наездников на ветрокрылах для Орды."},{t="Тени Пика Темного Облака",b="Несмотря на неприступную высоту, Застава Вольного Ветра сталкивается с растущей напряженностью в отношениях с северо-западными соседями: племенем Зловещего Тотема, обосновавшимся на Пике Темного Облака. Прежде терпимые как упрямые приверженцы традиций, Зловещие Тотемы под началом вождя Арнака все чаще прибегают к насилию, похищениям и убийствам. Подозрительные ритуалы и слухи о темной силе окружают соседние вершины. Местные таурены тревожно следят за небом и веревочными мостами, ведь самые опасные враги бродят не по соляным равнинам внизу, а засели по другую сторону каньонных ветров."}},faq={{q="Почему Застава Вольного Ветра построена так высоко на столовой горе?",a="Вертикальная планировка защищает поселение от враждебных отрядов кентавров Галака, патрулирующих дно каньона. Кентавры сильны на ровной местности, но не могут взобраться на отвесные утесы или легко взять механические деревянные подъемники тауренов.",al={"why is freewind post in the sky","why mesa","freewind post elevation","почему застава вольного ветра в небе","почему на столовой горе","высота заставы вольного ветра"}},{q="Как подняться на заставу и спуститься с нее?",a="Большинство путников пользуются большими механическими деревянными подъемниками у подножия главной столовой горы. Есть и запасной путь — опасная цепочка веревочных мостов и деревянных пандусов между соседними скальными столбами, но неосторожный шаг может обернуться смертельным падением на дно каньона.",al={"how to get up freewind post","freewind post elevator","freewind entrance","как подняться на заставу вольного ветра","подъемник заставы вольного ветра","вход на заставу вольного ветра"}},{q="Каковы отношения между Заставой Вольного Ветра и племенем Зловещего Тотема?",a="Отношения крайне напряженные. Зловещий Тотем, занимающий Пик Темного Облака к северо-западу от Застава Вольного Ветра, обвиняют в убийствах, похищениях и беспричинной враждебности к другим тауренам, из-за чего защитники заставы пребывают в тихой настороженности перед соседями-сородичами.",al={"grimtotem freewind post","darkcloud pinnacle freewind","why are grimtotem bad here","зловещий тотем застава вольного ветра","пик темного облака застава","почему зловещий тотем здесь плохие"}},{q="Какое значение имеет Скальное гнездовье для заставы?",a="Скальное гнездовье — исконное гнездовье диких виверн прямо через каньон. Таурены с Заставы Вольного Ветра наблюдают за этими существами и отбирают яйца из гнезд, которые затем выхаживают и выращивают как ездовых ветрокрылов для всей Орды.",al={"why highperch","highperch wyverns freewind","почему скальное гнездовье","виверны скального гнездовья"}}},fp="13,279,21.659.0,31.565.1,48.245.0,41.297.0,65.276.0,48.249.0"}
P.entries["subzone:frostmane-hold"] = {n="Форт Мерзлогривов",s="Форт Мерзлогривов — укрепленный лагерь и пещерный комплекс ледяных троллей из племени Мерзлогривов на западе Дун Морога. Он расположен среди скал к югу от Гномрегана и служит главным сборным пунктом троллей-налетчиков, вторгающихся на земли дворфов. Стальгорнская стража внимательно наблюдает за фортом, оценивая растущую угрозу со стороны троллей.",h="Форт Мерзлогривов — укрепленный лагерь и пещерный комплекс ледяных троллей из племени Мерзлогривов на западе...",kw={"dun morogh","frostmane","frostmane hold","headhunter","hideskinner","ice troll","kharanos","vejrek","дун морог","мерзлогрив","форт мерзлогривов","охотник за головами","свежеватель","ледяной тролль","каранос","веирек"},ang={["race:Dwarf"]="Мерзлогривы веками оспаривают Дун Морог, и зачистка Форта Мерзлогривов стала испытанием для горных пехотинцев, защищающих заснеженное сердце земель Стальгорна.",["race:Gnome"]="Расположенный к югу от Гномрегана, форт — еще один опасный враждебный рубеж рядом с осажденной бывшей столицей гномов."},sec={{t="Оплот троллей в снегах",b="Форт Мерзлогривов, высеченный в промерзших скалах западного Дун Морога, состоит из грубых построек под открытым небом и извилистой системы пещер. Для Племени Мерзлогривов это главный оплот, который плотно охраняют свежеватели и охотники за головами. Отсюда тролли совершают набеги на окрестные долины, проверяют на прочность оборону соседних поселений, например Караноса, и угрожают путникам на горных перевалах."},{t="Заноза для Караноса",b="По мере роста напряженности в Дун Мороге дворфийские командиры в Караносе все сильнее тревожатся из-за масштабов сбора Мерзлогривов. Молодых горцев и искателей приключений регулярно отправляют разведывать внутренние пещеры, наносить на карту укрепления и истреблять отряды, пока племя не собрало силы для организованного нападения на дворфийские форпосты."}},faq={{q="Кто живет в Форте Мерзлогривов?",a="Оплот занимает племя ледяных троллей Мерзлогривов — охотники, свежеватели и охотники за головами, а также их вожди и налетчики.",al={"who is in frostmane hold","frostmane hold mobs","trolls in frostmane hold","кто в форте мерзлогривов","мобы форта мерзлогривов","тролли в форте мерзлогривов"}},{q="Где находится Форт Мерзлогривов?",a="Он лежит в западных горах Дун Морога, к югу от промышленных руин Гномрегана и к западу от Караноса.",al={"frostmane hold location","where is frostmane hold","find frostmane hold","расположение форта мерзлогривов","где форт мерзлогривов","найти форт мерзлогривов"}},{q="Почему дворфов интересует эта пещера?",a="Дворфийские предводители в Караносе опасаются, что Мерзлогривы собираются в таком числе, что смогут устраивать серьезные набеги на поселения, поэтому военачальники посылают разведчиков наносить пещеры на карту и сокращать их ряды.",al={"why scout frostmane hold","kharanos troll quest","зачем разведывать форт мерзлогривов","задание про троллей каранос"}},{q="Есть ли в Форте Мерзлогривов трогги?",a="Нет. В наше время оплот безраздельно принадлежит ледяным троллям Мерзлогривам. Активность троггов в Дун Мороге в основном сосредоточена вокруг их собственных логовищ и руин Гномрегана.",al={"troggs frostmane hold","rockjaw frostmane","трогги форт мерзлогривов","каменная челюсть мерзлогривы"}}},fp="14,338,28.417.0,25.349.0,28.164.0,32.122.0,44.207.0,35.189.0"}
P.entries["subzone:frostmane-hovel"] = {n="Пещера Мерзлогривов",s="Пещера Мерзлогривов — суровое пещерное логово в южных скалах Холодной долины в Дун Мороге. Это укрепленное убежище агрессивных троллей Мерзлогривов, наступающих прямо на тренировочные земли дворфов.",h="Пещера Мерзлогривов — суровое пещерное логово в южных скалах Холодной долины в Дун Мороге.",kw={"anvilmar","coldridge valley","dun morogh","frostmane","hovel","trolls","старая наковальня","холодная долина","дун морог","мерзлогрив","пещера","тролли"},ang={["faction:Alliance"]="Постоянное присутствие Мерзлогривов прямо у Старой Наковальни показывает, что даже сердцу земель Стальгорна приходится непрестанно обороняться от местных врагов.",["race:Dwarf"]="Для молодых новобранцев Бронзобородов, обучающихся в Холодной долине, защита рубежей от враждебного Племени Мерзлогривов в таких пещерах — важное испытание."},sec={{t="Логово троллей в долине",b="Пещера Мерзлогривов, высеченная в южных горах у Холодной долины, дает приют коренным троллям Мерзлогривам, не желающим уступать Стальгорну высокие снега. Из таких грубых пещер тролли непрерывно нападают на местные лагеря дворфов и нарушают снабжение долины."}},faq={{q="Что такое Пещера Мерзлогривов?",a="Пещера Мерзлогривов — природная пещера на юге Холодной долины, которую коренные тролли Мерзлогривы, вторгающиеся на земли дворфов, используют как лагерь на время непогоды.",al={"frostmane hovel","what is this cave","coldridge troll cave","пещера мерзлогривов","что за пещера","пещера троллей холодная долина"}},{q="Почему в Холодной долине есть тролли?",a="Племя Мерзлогривов испокон веков живет на заснеженных вершинах Дун Морога. Будучи заклятыми врагами дворфов Бронзобородов, они постоянно спускаются с высоких хребтов, чтобы грабить тропы снабжения и бросать вызов поселениям дворфов.",al={"why trolls here","dun morogh trolls","frostmane presence","почему здесь тролли","тролли дун морога","присутствие мерзлогривов"}},{q="Кто управляет этой пещерой?",a="Пещеру занимают тролли-налетчики Мерзлогривы, которые используют укрытую расщелину для вторжений через южный уступ долины.",al={"who leads the cave","who lives in frostmane hovel","кто главный в пещере","кто живет в пещере мерзлогривов"}}},fp="15,218,25.313.0,28.167.0,41.227.0,23.139.0"}
P.entries["subzone:frostsaber-rock"] = {n="Уступ Ледопардов",s="Уступ Ледопардов — высокая каменная скала над заснеженными северными просторами Зимних Ключей. Это главное убежище и место обучения благородных ледопардов этого края.",h="Уступ Ледопардов — высокая каменная скала над заснеженными северными просторами Зимних Ключей.",kw={"alliance mount","frostsaber","frostsaber rock","rexxar","rivern frostwind","wintersaber","winterspring","скакун альянса","ледопард","уступ ледопардов","рексар","риверн холодный ветер","зимний саблезуб","зимние ключи"},ang={["class:Hunter"]="Скала и ее склоны — вдохновляющее место для охотников, желающих понаблюдать за самыми свирепыми хищниками северного Калимдора.",["faction:Alliance"]="Герои Альянса, заслужившие доверие Риверна Холодного Ветра на вершине скалы, могут пройти трудный путь обучения, чтобы ездить на знаменитом ледопарде Зимних Ключей."},sec={{t="Насест в тундре",b="Уступ Ледопардов, возвышающийся над промерзшими пустошами севера Зимних Ключей, открывает широкий вид на заснеженные дикие земли. Скала названа в честь свирепых и величественных ледопардов, бродящих по склонам и долинам внизу. На самой вершине живет Риверн Холодный Ветер, одинокий ночной эльф, посвятивший себя воспитанию и уходу за этими зверями. Героям, верным Альянсу, которые готовы выдержать суровые условия и доказать свою преданность, Риверн дарит редкую возможность научиться выращивать, приручать и седлать одного из этих легендарных снежных скакунов."}},faq={{q="Кто живет на вершине Уступа Ледопардов?",a="Риверн Холодный Ветер разбил лагерь на самой вершине скалы. Он обучает обращению с местными ледопардами и наставляет представителей Альянса, желающих обрести ледопарда-спутника.",al={"who is at frostsaber rock","frostsaber rock trainer","rivern location","кто на уступе ледопардов","учитель на уступе ледопардов","где риверн"}},{q="Могут ли игроки Орды обучаться здесь приручению зверей?",a="Нет. Риверн Холодный Ветер предлагает обучение и зверей-спутников только доверенным союзникам Альянса. Путникам из Орды на вершине не рады.",al={"horde frostsaber rock","can horde get frostsaber","rivern horde","орда уступ ледопардов","может ли орда получить ледопарда","риверн орда"}},{q="Какие существа обитают вокруг скалы?",a="Ледяная скала и окрестные плато — дом диких ледопардов, которые бродят по заснеженной местности вместе с другими выносливыми зверями сурового климата Зимних Ключей.",al={"what lives here","frostsaber rock beasts","frostsabers in winterspring","кто здесь живет","звери уступа ледопардов","ледопарды в зимних ключах"}},{q="Бывал ли на этой вершине кто-нибудь известный?",a="Известно, что странствующий укротитель Рексар побывал в Зимних Ключах и поднимался на Уступ Ледопардов во время своих одиноких скитаний по Калимдору.",al={"rexxar frostsaber rock","who visited frostsaber rock","рексар уступ ледопардов","кто посещал уступ ледопардов"}}},fp="15,204,21.551.0,31.203.0,36.160.0,41.172.0,39.154.0"}
P.entries["subzone:frostwhisper-gorge"] = {n="Теснина Ледяного Шепота",s="Теснина Ледяного Шепота — студеный каньон в южном нагорье Зимних Ключей, лежащий прямо к северу от зловещей Теснины Зловещего Шепота. Его ледяное дно и окружающие скалы усеяны древними руинами ночных эльфов, а пропастью владеют могучие великаны Ледяного Молота. Высоко над восточным краем одинокий лагерь дворфа смотрит с обрыва на океан внизу.",h="Теснина Ледяного Шепота — студеный каньон в южном нагорье Зимних Ключей, лежащий прямо к северу от зловещей...",kw={"darkwhisper gorge","frostmaul","frostwhisper gorge","ironforge","winterspring","теснина зловещего шепота","ледяной молот","теснина ледяного шепота","стальгорн","зимние ключи"},ang={["race:Dwarf"]="Высоко на восточном краю расселины неизвестный дворф разбил лагерь с флагом Стальгорна, ружьем и запасом эля, чтобы любоваться бескрайним видом на океан.",["race:NightElf"]="В заснеженных глубинах теснины лежат разбитые остатки древних построек ночных эльфов, по которым теперь бродят великаны Ледяного Молота."},sec={{t="Ледяная расселина руин и великанов",b="Теснина Ледяного Шепота, высеченная в южных горах Зимних Ключей, служит преддверием населенных демонами глубин Теснины Зловещего Шепота. Ее заснеженное дно и скалистые гребни усыпаны забытой каменной кладкой древних поселений ночных эльфов. Ныне теснину занимают огромные великаны Ледяного Молота и их хранители. Спуск в ущелье опасен: великаны яростно защищают промерзшие скалы от любых забредших чужаков."},{t="Восточная смотровая",b="На узкой тихой тропе на вершине восточных утесов теснины скрывается любопытный лагерь. Путники, летящие на наездниках на вивернах или грифонах между Азшарой, Оргриммаром и Зимними Ключами, часто замечают его сверху: одинокий лагерь дворфа на самом краю мира. Под знаменем Стальгорна стоят ящики с припасами, бочки эля, удобное кресло и ружье, прислоненное к спинке, а отсюда открывается несравненный вид на обрыв и Великое море внизу."}},faq={{q="Какие существа обитают в Теснине Ледяного Шепота?",a="Дно каньона и окружающие террасы населяют могучие великаны Ледяного Молота и их хранители.",al={"monsters in frostwhisper gorge","what lives in frostwhisper gorge","frostwhisper mobs","монстры теснины ледяного шепота","кто живет в теснине ледяного шепота","мобы ледяного шепота"}},{q="Где находится Теснина Ледяного Шепота?",a="Она расположена на юге Зимних Ключей, в ледяных скалах к северу от Теснины Зловещего Шепота.",al={"frostwhisper gorge location","where is frostwhisper gorge","frostwhisper map","расположение теснины ледяного шепота","где теснина ледяного шепота","карта ледяного шепота"}},{q="Что за маленький лагерь дворфа на восточных утесах?",a="Tucked away high on the eastern ridge overlooking the gorge is a tranquil campsite flying an Ironforge banner. It consists of a chair, a rifle, supply crates, and copious amounts of booze looking over the cliff edge toward the sea.",al={"dwarf camp winterspring","ironforge flag frostwhisper","eastern cliff camp","лагерь дворфа зимние ключи","флаг стальгорна ледяной шепот","лагерь на восточном утесе"}},{q="Есть ли в теснине руины ночных эльфов?",a="Да. Разрушающиеся колонны и каменная кладка ночных эльфов разбросаны и по дну теснины, и по верхним гребням скал — остатки древних жилищ кальдорай.",al={"elven ruins frostwhisper","night elf architecture winterspring gorge","руины эльфов ледяной шепот","архитектура ночных эльфов теснина зимние ключи"}}},fp="18,371,34.477.0,20.511.0,42.110.0,36.110.0,51.231.0,44.167.0"}
P.entries["subzone:fungal-rock"] = {n="Пещера Лишайников",s="Пещера Лишайников — сырая пещерная впадина в северо-восточных скалах Кратера Ун'Горо. Здесь властвуют агрессивные приматы и густые заросли призрачных грибов, и это одно из самых опасных логовищ обезьян в кратере.",h="Пещера Лишайников — сырая пещерная впадина в северо-восточных скалах Кратера Ун'Горо.",kw={"a-me 01","crater","fungal rock","ghost mushroom","gorilla","u'cha","uhk'loc","un'goro","чи-та 3","кратер","пещера лишайников","призрачный гриб","горилла","у'ча","ухк'лок","ун'горо"},ang={["profession:Herbalism"]="Пещера Лишайников — одно из лучших мест в Кратере Ун'Горо для сбора призрачных грибов, хотя собирателям приходится сражаться со стаями территориальных горилл.",["race:Gnome"]="Гномов может привлечь Пещера Лишайников, чтобы выяснить судьбу Чи-Та 3 — амбициозного прототипа механической обезьяны Карны Сомнамбулер, оставленного у озерца возле входа."},sec={{t="Логово обезьян",b="Пещера Лишайников, скрытая за небольшим водопадом и озерцом на северо-восточном краю Кратера Ун'Горо, — главное логово огромных горилл этих мест. В сырых подземных коридорах среди зарослей редких призрачных грибов бродят могучие топтуны и громовые гориллы Ун'Горо. В глубочайших закоулках обитают территориальные исполины, в том числе могучий седой самец У'ча и неуловимая горилла-альбинос Ухк'лок. Помимо диких обитателей, у входа в пещеру любопытные путники могут наткнуться на рукотворные диковины, например Чи-Та 3 — поврежденную механическую обезьяну, брошенную гномами-исследователями."}},faq={{q="Что такое Пещера Лишайников?",a="Пещера Лишайников — большая система пещер в северо-восточной стене Кратера Ун'Горо. Она известна сыростью, обилием призрачных грибов и плотным населением враждебных горилл.",al={"where is fungal rock","what is fungal rock cave","где пещера лишайников","что за пещера лишайников"}},{q="Кто правит обезьянами в Пещере Лишайников?",a="В пещере господствует У'ча — огромный и сильный седой самец гориллы, живущий в самой глубокой пещере. Также известно, что по этим пещерам бродит редкая белая горилла Ухк'лок.",al={"who is u'cha","boss of fungal rock","fungal rock leader","кто такой у'ча","босс пещеры лишайников","вожак пещеры лишайников"}},{q="Почему у пещеры стоит механическая горилла?",a="Возле озерца у входа стоит Чи-Та 3 — механическая обезьяна, построенная гномом-исследователем Карной Сомнамбулер. Она сломалась во время полевых наблюдений и ждет, пока ее разберут или починят.",al={"what is a-me 01","robot gorilla ungoro","ame 01","что такое чи-та 3","робот горилла ун'горо","чи-та 3"}},{q="Какие ценные ресурсы растут в Пещере Лишайников?",a="Сырой, затененный интерьер пещеры идеален для призрачных грибов, поэтому это одно из немногих мест на юге Калимдора, где травники могут собирать этот востребованный гриб.",al={"ghost mushrooms ungoro","herbs in fungal rock","призрачные грибы ун'горо","травы в пещере лишайников"}}},fp="11,221,11.593.0,20.195.0,38.177.0,51.195.0,44.194.0"}
P.entries["subzone:fungal-vale"] = {n="Грибная долина",s="Грибная долина — глубоко зараженная низина на юге центральной части Восточных Чумных земель, к северу от Башни королевской стражи и Поместья Маррисов. Окутанная мутной дымкой и покрытая темно-фиолетовой землей, долина демонстрирует необузданную, мутирующую силу Чумы нежизни. Здесь кишат бродячие чудовища Плети и смертные служители Культа Проклятых.",h="Грибная долина — глубоко зараженная низина на юге центральной части Восточных Чумных земель, к северу от...",kw={"blight","crown guard tower","cult of the damned","eastern plaguelands","fungal vale","fungus","marris stead","plague of undeath","scourge","скверна","башня королевской стражи","культ проклятых","восточные чумные земли","грибная долина","гриб","поместье маррисов","чума нежизни","плеть"},ang={["class:Druid"]="Грибная долина — высшая насмешка над живой природой: естественный круговорот здесь сменила вечная нечестивая гниль, насаждаемая Плетью.",["profession:Herbalism"]="Зараженная, заросшая грибами земля — суровое предостережение о том, что некромантия делает с местной флорой Лордерона."},sec={{t="Сад гнили",b="Грибная долина, расположенная к северу от Поместья Маррисов, — один из самых глубоко оскверненных уголков Лордерона. Земля здесь приобрела болезненный фиолетовый цвет, вздулась чужеродными грибными наростами и тонет в вечной мутной дымке, которую рождают некротические споры. Чума нежизни не просто уничтожила местную экосистему, а извратила почву, заставив ее взращивать нечестивую флору, которая кормит чудовищных падальщиков и бредущую нежить. Члены Культа Проклятых часто бывают здесь: они ухаживают за зараженными цветами и совершают мерзкие обряды посреди противоестественного распада."}},faq={{q="Что такое Грибная долина?",a="Это оскверненная долина на юге Восточных Чумных земель, лежащая прямо к северу от Башни королевской стражи и Поместья Маррисов. Местность сильно заражена Чумой нежизни, которая превращает обычную растительность в разросшуюся грибную заразу.",al={"where is fungal vale","fungal vale lore","fungal vale overview","где грибная долина","грибная долина предыстория","грибная долина обзор"}},{q="Почему здесь фиолетовая земля?",a="Почва полностью пропитана Чумой нежизни. Вместо того чтобы дать растениям погибнуть окончательно, некротическая зараза превращает землю в плодородное ложе для губительных спор, окрашивая ее в цвет синяка.",al={"why is the ground purple","purple dirt plaguelands","fungal vale ground","почему земля фиолетовая","фиолетовая земля чумные земли","земля грибной долины"}},{q="Кто контролирует эту местность?",a="Грибная долина принадлежит Плети и смертным культистам из Культа Проклятых. Порождения нежити бродят в дымке рядом со служителями, которые пестуют оскверненную грибную экосистему.",al={"who is in fungal vale","fungal vale enemies","cultists fungal vale","кто в грибной долине","враги грибной долины","культисты грибной долины"}},{q="Где она находится относительно местных ориентиров?",a="Она лежит на юге центральной части Восточных Чумных земель, прямо к северу от дороги между Поместьем Маррисов и Башней королевской стражи.",al={"how to get to fungal vale","fungal vale location","near crown guard tower","как добраться до грибной долины","расположение грибной долины","рядом с башней королевской стражи"}}},fp="11,374,15.564.0,24.254.0,30.234.0,23.177.0,48.131.0"}
P.entries["subzone:gadgetzan"] = {n="Прибамбасск",s="Прибамбасск — обнесенный стеной пустынный центр Картеля Хитрая Шестеренка, остров торговли на севере Танариса. Город открыт как для Орды, так и для Альянса и придерживается строго соблюдаемого гоблинского нейтралитета, встречая любого, у кого есть монеты или непыльная работа.",h="Прибамбасск — обнесенный стеной пустынный центр Картеля Хитрая Шестеренка, остров торговли на севере Танариса.",kw={"auction house","gadgetzan","goblin","neutral","steamwheedle cartel","tanaris","wastewander","waterspring field","аукционный дом","прибамбасск","гоблин","нейтральный","картель хитрая шестеренка","танарис","дикие скитальцы","родниковое поле"},ang={["profession:Blacksmithing"]="В городе есть мощные кузницы и наковальни, которые любят опытные металлисты; он служит важным опорным пунктом для членов Ордена Мифрила.",["profession:Engineering"]="Прибамбасск — важный перекресток для изобретателей: здесь есть опытные учителя, редкие схемы и телепортационная площадка прибытия, настроенная специально для гномов-инженеров."},sec={{t="Оплот выгоды среди дюн",b="Окруженный раскаленными песками, Прибамбасск служит региональным центром предприятий Картеля Хитрая Шестеренка на юге Калимдора. Построенный с характерной гоблинской изобретательностью и беспорядочной архитектурой, город располагает независимым аукционным домом, банком, гостиницей и мастерскими для инженеров, кузнецов и алхимиков. Здесь есть и распорядители полетов для обеих основных фракций, что обеспечивает постоянный поток искателей приключений, направляющихся в Танарис, Фералас и дикую котловину Ун'Горо. Превыше всего здесь торговля: пока посетители держат оружие в ножнах, а кошельки открытыми, в стенах города они в безопасности."},{t="Пустынные беды и насаждаемый порядок",b="Мир в Прибамбасске поддерживается не доброй волей, а хорошо вооруженными гоблинскими громилами, которые быстро расправляются с теми, кто угрожает торговле или затевает стычки между фракциями. Но за воротами жизнь опасна. Водная компания Прибамбасска постоянно воюет с бандитами Диких Скитальцев, безжалостной шайкой, занявшей важное Родниковое поле. Вода в Танарисе — жидкое золото, и картель часто нанимает посторонних наемников, чтобы устранить главарей бандитов и вернуть украденные бурдюки с водой, не давая иссякнуть городским резервуарам."}},faq={{q="Могут ли Альянс и Орда нападать друг на друга в Прибамбасске?",a="Нет. Прибамбасск — строго нейтральная территория Картеля Хитрая Шестеренка. Гоблинские громилы усиленно патрулируют город и немедленно нападут на любого, кто нарушит мир или начнет насилие против других путников.",al={"is gadgetzan safe","pvp in gadgetzan","can horde and alliance fight here","безопасен ли прибамбасск","пвп в прибамбасске","могут ли орда и альянс драться здесь"}},{q="Почему вода здесь так важна?",a="Расположенный посреди засушливой пустыни, Прибамбасск целиком зависит от водозаборных башен Водной компании Прибамбасска на Родниковом поле. Бандиты Диких Скитальцев захватили эти колодцы, лишив город основного источника воды и вынудив гоблинов платить награды за украденные бурдюки с водой.",al={"gadgetzan water company","why water pouches","waterspring field conflict","водная компания прибамбасска","зачем бурдюки с водой","конфликт на родниковом поле"}},{q="Кто управляет Прибамбасском?",a="Прибамбасск принадлежит Картелю Хитрая Шестеренка и управляется им — крупнейшей и самой влиятельной торговой гоблинской организацией Азерота.",al={"who runs gadgetzan","gadgetzan faction","what cartel owns gadgetzan","кто управляет прибамбасском","фракция прибамбасска","какой картель владеет прибамбасском"}},{q="Чем особенен здешний аукционный дом?",a="В отличие от фракционных рынков Оргриммара или Штормграда, в Прибамбасске действует нейтральный аукционный дом. Игроки Альянса и Орды могут покупать и продавать друг другу товары, хотя за эту возможность гоблины берут гораздо более высокий сбор.",al={"gadgetzan auction house","neutral auction house","cross faction ah","аукционный дом прибамбасска","нейтральный аукцион","аукцион между фракциями"}}},fp="9,283,32.645.0,34.527.0,54.228.0,41.290.0,23.133.0,42.256.0"}
P.entries["subzone:gahrron-s-withering"] = {n="Пустошь Гаррона",s="Пустошь Гаррона — оскверненная усадьба на восточной границе Западных Чумных земель, у дороги в Восточные Чумные земли. Некогда процветающий участок лордеронских угодий под названием Оживление Гаррона, теперь она занята Плетью и держится на огромном котле, выпускающем в воздух ядовитые чумные пары.",h="Пустошь Гаррона — оскверненная усадьба на восточной границе Западных Чумных земель, у дороги в Восточные...",kw={"cauldron","darrowshire","del gahrron","gahrron","gahrron's withering","joseph redpath","quickening","soulwrath","котел","дарроушир","дел гаррон","гаррон","пустошь гаррона","джозеф редпат","оживление","душегнев"},ang={["class:Paladin"]="Мерзкие испарения из котла Хранителя котла Душегнева и неупокоенные мертвецы на разоренных полях делают эту ферму первоочередной целью для священного очищения.",["faction:Alliance"]="Для ветеранов Альянса ферма имеет мрачное значение: именно здесь павшего героя Дарроушира Джозефа Редпата пришлось добить его же соотечественникам."},sec={{t="От оживления к упадку",b="До того как Третья война погубила королевство Лордерон, это поместье называлось Оживление Гаррона по имени своего хозяина, Дела Гаррона. Его плодородные поля давали зерно всему королевству, пока по земле не прокатились Культ Проклятых и Плеть. Усадьба, переименованная в Пустошь Гаррона в горькую насмешку над былой жизненной силой, ныне разрушена и заброшена. Призрачные видения, воющие привидения и неупокоенные духи бродят среди разрушенных построек под надзором надсмотрщиков Плети, присягнувших Королю-личу."},{t="Котел и гибель Редпата",b="В центре зараженных полей стоит один из огромных чумных котлов Плети, за которым присматривает Хранитель котла Душегнев. Этот котел постоянно изрыгает в воздух ядовитые миазмы, отравляя землю и изгоняя все живое. Помимо распространения заразы, ферма отмечает трагическую развязку соседней трагедии Дарроушира: именно здесь защитники Альянса настигли и сразили капитана Джозефа Редпата, павшего жертвой темной порчи. Разбитый щит воина остался лежать среди проклятой земли."}},faq={{q="Как называлась Пустошь Гаррона до чумы?",a="До падения Лордерона ферма называлась Оживление Гаррона. Это была действующая усадьба Дела Гаррона, пока Плеть не опустошила окрестности.",al={"original name","old name","gahrrons quickening","прежнее название","старое название","оживление гаррона"}},{q="Почему здесь огромный котел?",a="Котел — орудие мора, развернутое Плетью для распространения чумных паров по региону. Хранитель котла Душегнев охраняет устройство, чтобы оно непрерывно заражало землю и воздух.",al={"plague cauldron","what does the cauldron do","pot in field","чумной котел","что делает котел","котел в поле"}},{q="Кем был Джозеф Редпат и почему он важен для этого места?",a="Капитан Джозеф Редпат был защитником соседнего Дарроушира, павшим жертвой скверны во время резни, которую Плеть устроила в городе. Силы Альянса наконец загнали в угол и сразили его оскверненный облик на этой усадьбе, а щит остался лежать в грязи.",al={"redpath shield","captain redpath","darrowshire connection","щит редпата","капитан редпат","связь с дарроуширом"}},{q="Кто сейчас контролирует Пустошь Гаррона?",a="Ферма прочно удерживается Плетью. Ее населяют призрачные духи, воющие мертвецы и жуткие видения, а всеми ими командует могущественный некромант Хранитель котла Душегнев.",al={"who is here","mobs at gahrron","scourge in charge","кто здесь","монстры у гаррона","плеть главная"}}},fp="19,333,24.508.0,36.567.1,54.168.0,35.205.0,51.242.1,43.187.0"}
P.entries["subzone:galardell-valley"] = {n="Долина Галарделл",s="Долина Галарделл — суровый, опасный каньон в северо-восточных возвышенностях Красногорья. Ущелье наводнено агрессивными стаями гноллов и лежит в тени печально известной Башни Илгалара.",h="Долина Галарделл — суровый, опасный каньон в северо-восточных возвышенностях Красногорья.",kw={"fangore","galardell valley","gnolls","morganth","redridge","tower of ilgalar","фангор","долина галарделл","гноллы","моргант","красногорье","башня илгалара"},ang={["faction:Alliance"]="Изнуренная городская стража Приозерья не может обезопасить северо-восточную дорогу, пока стаи гноллов и темное присутствие Морганта удерживают Долину Галарделл."},sec={{t="Логово зверей и тьмы",b="Долина Галарделл, врезанная в северо-восточные утесы Красногорья, полностью вышла из-под контроля защитников Приозерья. Свирепые гноллы Красногорья рыщут по низинам и стоят лагерями на дне каньона под началом жестоких вожаков, таких как лейтенант Фангор. Высоко над ущельями возвышается мрачный шпиль Башни Илгалара, оплота мага-отступника Морганта, из-за чего вся долина постоянно внушает ужас окрестным поселениям."}},faq={{q="Где находится Долина Галарделл?",a="Долина Галарделл лежит в самом северо-восточном углу Красногорья, спрятавшись за высокими скалами за дорогами, ведущими на север от Озера Безмолвия.",al={"galardell valley location","where is galardell valley","how to find galardell valley","расположение долины галарделл","где долина галарделл","как найти долину галарделл"}},{q="Какие существа обитают в долине?",a="Долина наводнена кровожадными стаями гноллов, которые плотными группами патрулируют тропы под началом опасных громил вроде лейтенанта Фангора.",al={"mobs in galardell valley","who lives in galardell valley","galardell enemies","монстры долины галарделл","кто живет в долине галарделл","враги галарделл"}},{q="Что за темная башня возвышается над долиной?",a="Это Башня Илгалара, внушительное каменное строение, служащее опорным пунктом чародея-отступника Морганта.",al={"galardell valley tower","spire above galardell","tower near gnolls redridge","башня долины галарделл","шпиль над галарделл","башня возле гноллов красногорья"}},{q="Кто такой лейтенант Фангор?",a="Лейтенант Фангор — грозный вожак гноллов, стоящий в долине. Известный хитростью и свирепостью, он при вызове воет, призывая на помощь соседние стаи гноллов, и быстро одолевает неосторожных путников.",al={"fangore","lieutenant fangore","galardell valley boss","фангор","лейтенант фангор","босс долины галарделл"}}},fp="16,218,26.483.0,34.167.0,34.139.0,46.128.0,26.213.0"}
P.entries["subzone:gallery-of-treasures"] = {n="Галерея сокровищ",s="Галерея сокровищ — богато украшенный и тщательно охраняемый коридор в залах Монастыря Алого ордена, соединяющий Двор охотника с Атенеумом. Стены галереи увешаны возвращенными картинами, реликвиями и иллюминированными рукописями; она демонстрирует богатство и наследие Лордерона, сохраненные Алым орденом посреди его фанатичной войны с нежитью.",h="Галерея сокровищ — богато украшенный и тщательно охраняемый коридор в залах Монастыря Алого ордена...",kw={"athenaeum","gallery of treasures","library","lordaeron relics","paintings","scarlet monastery","атенеум","галерея сокровищ","библиотека","реликвии лордерона","картины","монастырь алого ордена"},ang={["class:Paladin"]="Артефакты и знамена в этой галерее напоминают об утраченной славе Серебряной Длани и павшего Лордерона, но теперь ими владеют фанатики, превратившие праведную убежденность в неразборчивый фанатизм.",["race:Undead"]="Картины и исторические реликвии, хранящиеся здесь, принадлежали предкам Отрекшихся; их ревниво охраняют живые рыцари ордена, стремящиеся истребить бывших жителей Лордерона."},sec={{t="Хранилище утраченного наследия",b="Галерея сокровищ расположена в глубине библиотечного крыла Монастыря Алого ордена и служит большим залом, соединяющим псарни Двора охотника со священными архивами Атенеума. В отличие от собачьих загонов двора, этот коридор украшен изысканными картинами, историческими артефактами и небольшими комнатами с книгами, спасенными со всего павшего королевства Лордерон. Для Алого ордена эти реликвии — незапятнанное наследие человечества, которое они поклялись защищать и которое яростно охраняют от всех чужаков, посмевших вторгнуться в их святилище."}},faq={{q="Где находится Галерея сокровищ?",a="Она находится в библиотечном крыле Монастыря Алого ордена. Галерея расположена сразу за Двором охотника и является последним украшенным проходом перед Атенеумом.",al={"gallery location","where is gallery of treasures","how to find gallery of treasures","расположение галереи","где галерея сокровищ","как найти галерею сокровищ"}},{q="Что хранится в Галерее сокровищ?",a="В галерее хранятся сохраненные произведения искусства, исторические реликвии, иллюминированные рукописи и картины, спасенные из разрушенного королевства Лордерон; они выставлены вдоль коридора и в соседних читальных комнатах.",al={"what is in gallery of treasures","gallery loot","gallery relics","что в галерее сокровищ","добыча галереи","реликвии галереи"}},{q="Зачем Алый орден собирает эти сокровища?",a="Алый орден считает себя истинным наследником Лордерона. Спасая и накапливая эти произведения культуры, его члены сохраняют память и священное наследие своей родины, очищая земли от того, что считают скверной.",al={"why do scarlet have treasures","crusade relics purpose","зачем алому ордену сокровища","цель реликвий ордена"}},{q="Кто охраняет галерею?",a="Коридор патрулируют разные фанатики Алого ордена, в том числе защитники и послушники, охраняющие путь к Чародею Доану и глубинным архивам монастыря.",al={"gallery mobs","who is in gallery of treasures","монстры галереи","кто в галерее сокровищ"}}},fp="20,342,29.584.0,42.194.0,41.200.0,53.234.0,23.187.0"}
P.entries["subzone:gallows-end-tavern"] = {n="Таверна \"Петля висельника\"",s="Таверна «Петля висельника» — главный постоялый двор Брилла и центр гостеприимства Отрекшихся в Тирисфальских лесах. Помимо крова и выпивки для усталых путников, она служит важным узлом для наставников классов, учителей профессий и тайных допросов.",h="Таверна «Петля висельника» — главный постоялый двор Брилла и центр гостеприимства Отрекшихся в Тирисфальских...",kw={"brill","forsaken","gallows end","gallows' end tavern","innkeeper","scarlet zealot","tirisfal glades","undead","брилл","отрекшиеся","петля висельника","таверна петля висельника","трактирщик","фанатик алого ордена","тирисфальские леса","нежить"},ang={["faction:Alliance"]="Под полом общего зала Отрекшиеся держат пленных разведчиков Альянса и фанатиков Алого ордена для получения сведений и допросов.",["race:Undead"]="Как первый крупный постоялый двор за пределами Могильника, Таверна «Петля висельника» служит культурным и практическим перекрестком для недавно пробудившихся Отрекшихся, выходящих в большой мир."},sec={{t="Место сбора мертвых",b="Таверна «Петля висельника» стоит у дороги в Брилле и служит главным местом сбора недавно пробудившихся Отрекшихся, покидающих Могильник и идущих на юг к Подгороду. Несмотря на свою нежизнь, Отрекшиеся по-прежнему приходят сюда пообщаться, поторговать и найти убежище. В таверне работают наставники разных классов — для юных воинов, жрецов, магов, разбойников и чернокнижников, — а также торговцы и лекари."},{t="Тайны подвала",b="Под скрипучими половицами и смехом таверны скрывается куда более мрачное назначение. В подвалах Отрекшиеся держат связанных и охраняемых военнопленных вдали от посторонних глаз. Среди них — плененный фанатик Алого ордена и дворф-горец; их держат под таверной для допросов и опытов, пока Отрекшиеся защищают свои границы и от фанатичных рыцарей, и от разведчиков Альянса."}},faq={{q="Где находится Таверна «Петля висельника»?",a="Она находится в центре Брилла, главного поселения Отрекшихся к северу от Подгорода в Тирисфальских лесах.",al={"gallows end location","where is gallows end tavern","brill inn location","расположение петли висельника","где таверна петля висельника","таверна брилла"}},{q="Зачем нежити постоялый двор или таверна?",a="Хотя Отрекшимся не нужны сон и обычная пища, такие таверны, как «Петля висельника», поддерживают социальные связи и культурные привычки прошлой жизни. Кроме того, это надежный общественный центр для обучения, торговли и официальных дел.",al={"why do undead drink","why do forsaken need taverns","undead inn lore","зачем нежити пить","зачем отрекшимся таверны","таверна нежити"}},{q="Кто заключен в подвале?",a="В подвалах под таверной Отрекшиеся держат пленных врагов, среди которых фанатик из враждебного Алого ордена и дворф-горец Альянса.",al={"tavern prisoners","who is in the cellar","brill tavern dungeon","узники таверны","кто в подвале","темница таверны брилла"}},{q="Какие услуги и учителя здесь есть?",a="В таверне есть наставники для воинов, жрецов, магов, разбойников и чернокнижников, учителя первой помощи и зачарования, торговцы разными товарами и трактирщик.",al={"gallows end trainers","who trains in brill inn","tavern vendors","учителя петли висельника","кто учит в таверне брилла","торговцы таверны"}}},fp="19,258,30.446.0,21.405.0,41.114.0,40.248.0,34.165.0,45.170.0"}
P.entries["subzone:gaping-chasm"] = {n="Зияющая бездна",s="Зияющая бездна — обширный улей силитидов, вырытый глубоко в песках юго-востока Танариса. Его населяют агрессивные насекомоподобные чудовища выводка Хаззали; он служит мрачным предупреждением о растущей угрозе силитидов, расползающейся за пределы западных пустынь.",h="Зияющая бездна — обширный улей силитидов, вырытый глубоко в песках юго-востока Танариса.",kw={"fizzledowser","gaping chasm","hazzali","hive","sandreaver","scrimshank","silithid","tanaris","рудознатец","зияющая бездна","хаззали","улей","песчаный разоритель","костеглыб","силитиды","танарис"},ang={["profession:Mining"]="В открытых подземных расселинах и просевшей земле улья силитидов порой обнаруживаются богатые залежи руды, но добыча требует отбиваться от десятков свирепых роющих насекомых.",["race:Gnome"]="Печальная гибель младшего геодезиста Костеглыба в бездне — суровое напоминание, что полевые исследования в Калимдоре требуют не только научного любопытства, но и серьезной огневой мощи."},sec={{t="Улей в дюнах",b="Прорезая холмистые просторы Танариса, Зияющая бездна уходит вниз, в кишащий подземный лабиринт туннелей, смолистых холмов и дергающихся панцирей. Этот улей принадлежит Хаззали — агрессивному выводку силитидов, зарывшемуся под пустынные пустоши. Из-за подземных жалоносцев, роев и громадных песчаных разорителей любые путники и искатели сокровищ, глупо спустившиеся в бездну, быстро становятся добычей или оказываются в липких коконах."},{t="Могила геодезиста",b="Растущий улей привлек внимание предприимчивых умов Прибамбасска, и Старший геодезист Рудознатец отправил в яму своего младшего геодезиста Костеглыба, чтобы нанести на карту и измерить геологические сдвиги, вызванные туннелями насекомых. Ожидаемо, экспедиция закончилась катастрофой. Костеглыб встретил мрачный конец среди стрекочущих выводков, оставив после себя разбросанное снаряжение и измерительные приборы, предостерегающие от недооценки угрозы силитидов."}},faq={{q="Какие существа обитают в Зияющей бездне?",a="Бездна целиком заражена силитидами Хаззали. В улье есть множество каст этих насекомых: рабочие трутни, крылатые жалоносцы, неисчислимые рои и огромные песчаные разорители в хитиновой броне.",al={"what lives in gaping chasm","bugs in tanaris chasm","gaping chasm mobs","кто живет в зияющей бездне","жуки в танарисе","монстры зияющей бездны"}},{q="Где находится Зияющая бездна?",a="Бездна лежит на юго-востоке Танариса, вырытая в песках пустыни к югу от Прибамбасска и к востоку от горного хребта, отделяющего Танарис от западной глуши.",al={"where is gaping chasm","gaping chasm location","how to find gaping chasm","где зияющая бездна","расположение зияющей бездны","как найти зияющую бездну"}},{q="Почему гнома-геодезиста отправили в бездну?",a="Старший геодезист Рудознатец из Прибамбасска отправил младшего геодезиста Костеглыба обследовать пещеру и оценить ее геологическую активность. К сожалению, Костеглыба одолели и убили силитиды Хаззали, прежде чем он выполнил задание.",al={"who was scrimshank","fizzledowser surveyor quest","why did scrimshank go there","кто такой костеглыб","задание геодезиста рудознатца","зачем костеглыб пошел туда"}},{q="Связаны ли здешние силитиды с теми, что обитают в других частях Калимдора?",a="Да. Силитиды Хаззали в Танарисе имеют ту же насекомую природу и структуру коллективного разума, что и выводки на юге Степей и в оскверненных пустошах Силитуса на западе, что говорит об опасном, согласованном расширении по югу Калимдора.",al={"are these silithid connected to silithus","why are bugs in tanaris","связаны ли силитиды с силитусом","почему жуки в танарисе"}}},fp="12,257,21.484.0,18.469.0,45.216.0,34.169.0,45.248.1,69.252.0"}
P.entries["subzone:garrison-armory"] = {n="Мастерские Гарнизона",s="Мастерские Гарнизона — рудник Альянса, вырубленный в холмах к юго-западу от Крепости Стражей Пустоты в Выжженных землях. Шахтеры и инженеры разрабатывают подземные жилы и добывают ценные минералы, снабжая одинокую крепость и отправляя сырье в Штормград. Это важнейший промышленный источник жизни в бесплодной выжженной глуши.",h="Мастерские Гарнизона — рудник Альянса, вырубленный в холмах к юго-западу от Крепости Стражей Пустоты в...",kw={"blasted lands","garrison armory","mine","nethergarde","nethergarde engineer","nethergarde keep","nethergarde miner","stormwind","выжженные земли","мастерские гарнизона","рудник","крепость стражей пустоты","инженер крепости стражей пустоты","шахтер крепости стражей пустоты","штормград"},ang={["faction:Alliance"]="Работники Мастерских неустанно трудятся, чтобы Крепость Стражей Пустоты не знала нехватки оружия, брони и товаров для обмена и могла нести свой одинокий дозор.",["profession:Mining"]="В штольнях Мастерских Гарнизона скрыты ценные жилы минералов, вырубленные в камне суровых Выжженных земель, из-за чего этот подземный карьер оспаривают."},sec={{t="Источник жизни в красных пустошах",b="Содержание постоянного гарнизона в засушливых пустошах Выжженных земель требует непрерывного снабжения, а Крепость Стражей Пустоты не может полагаться только на долгие обозы из Штормграда. Мастерские Гарнизона — главная промышленная выработка крепости. Шахтеры крепости под надзором бригадиров и при помощи инженеров трудятся в подземных штольнях, добывая ценные минералы. Добытая здесь руда идет напрямую кузнецам и укреплениям крепости либо отправляется в столицу в обмен на продовольствие, инструменты и припасы, необходимые крепости, чтобы нести дозор у Темного портала."},{t="Уязвимое производство",b="Поскольку мастерские расположены вдали от главных стен Крепости Стражей Пустоты, выработка остается открытой суровым опасностям красной пустыни. Тролли, огры и дикие звери бродят среди окрестных скал, а лазутчики Орды пристально следят за добычей руды в крепости. Работники в туннелях трудятся под вооруженной охраной: они знают, что любой сбой в работе мастерских напрямую угрожает способности крепости нести дозор на выжженном рубеже."}},faq={{q="Для чего нужны Мастерские Гарнизона?",a="Мастерские Гарнизона — горнодобывающий комплекс Альянса, которым управляет Крепость Стражей Пустоты. Рабочие добывают под землей металлы и минералы, чтобы содержать крепость и обменивать их в Штормграде на необходимые продовольствие и снаряжение.",al={"garrison armory purpose","what is this mine","why is there a mine here","назначение мастерских гарнизона","что это за рудник","почему здесь рудник"}},{q="Кто работает в мастерских?",a="Рудник обслуживают шахтеры, инженеры и бригадиры крепости, связанные с Альянсом. Они добывают рудные залежи и поддерживают штольни под надзором командования Крепости Стражей Пустоты.",al={"who is inside","armory npcs","garrison miners","кто внутри","персонажи мастерских","шахтеры гарнизона"}},{q="Зачем Крепости Стражей Пустоты этот рудник?",a="Крепость Стражей Пустоты стоит в изоляции посреди безжизненных Выжженных земель, из-за чего регулярное снабжение затруднено. Добывая собственные металлы, крепость может чинить снаряжение, укреплять оборону и обменивать излишки сырья в Штормграде на жизненно важные припасы.",al={"why nethergarde needs it","armory importance","nethergarde resources","зачем он крепости стражей пустоты","значение мастерских","ресурсы крепости стражей пустоты"}},{q="Могут ли игроки Орды войти в Мастерские Гарнизона?",a="Мастерские заняты враждебными рабочими и стражами Альянса, но искатели приключений из Орды часто отваживаются спускаться вглубь, чтобы добыть богатые рудные жилы в штольнях.",al={"can horde go here","horde in garrison armory","is it safe for horde","может ли орда зайти сюда","орда в мастерских гарнизона","безопасно ли для орды"}}},fp="15,360,28.631.0,19.467.0,37.213.0,24.204.0,41.265.0,44.171.0"}
P.entries["subzone:gates-of-ironforge"] = {n="Врата Стальгорна",s="Врата Стальгорна — монументальный главный вход, ведущий путников из заснеженных горных долин Дун Морога в столицу дворфов. Вырубленные прямо в отвесной каменной стене горы, они охраняются изнутри колоссальной статуей верховного короля Модимуса Старой Наковальни.",h="Врата Стальгорна — монументальный главный вход, ведущий путников из заснеженных горных долин Дун Морога в...",kw={"commons","dun morogh","gates of ironforge","ironforge entrance","ironforge main gate","modimus anvilmar","общинный квартал","дун морог","врата стальгорна","вход в стальгорн","главные врата стальгорна","модимус старая наковальня"},ang={["faction:Alliance"]="Врата Стальгорна — один из самых укрепленных оплотов Альянса, практически неуязвимый для осады со стороны холодных долин Дун Морога.",["race:Dwarf"]="Стоя под величественным изваянием верховного короля Модимуса Старой Наковальни, каждый дворф вспоминает древнюю эпоху, когда все кланы жили под одной горой как единый род."},sec={{t="Порог горы",b="К Вратам Стальгорна поднимаются по извилистому укрепленному пандусу из центральной части Дун Морога, и они предстают величественным фасадом, видимым на большей части заснеженных низин. За огромным порталом посетители попадают в сам город, где их сразу встречает громадная каменная статуя верховного короля Модимуса Старой Наковальни — легендарного правителя, объединившего кланы дворфов до Войны трех молотов. Пройдя через эти врата, вы попадаете прямо в оживленный торговый район — Общинный квартал."}},faq={{q="Куда ведут Врата Стальгорна?",a="Они соединяют внешние горные земли Дун Морога с городом Стальгорн. Пройдя через порог, вы сразу окажетесь в юго-западной части Общинного квартала — оживленного торгового и банковского центра города.",al={"ironforge entrance","where do the gates go","gates of ironforge location","вход в стальгорн","куда ведут врата","где врата стальгорна"}},{q="Кого изображает статуя за вратами?",a="Монументальная скульптура сразу за входом изображает верховного короля Модимуса Старой Наковальни. Это был мудрый и почитаемый монарх, правивший всеми кланами дворфов, пока политические распри не раскололи их на Бронзобородов, Громовых Молотов и Черное Железо.",al={"ironforge gate statue","giant dwarf statue","who is the statue at the gate","статуя у врат стальгорна","гигантская статуя дворфа","кто статуя у врат"}},{q="Как добраться до врат из Дун Морога?",a="Из центральной части Дун Морога направляйтесь на север и поднимитесь по широкому укрепленному каменному пандусу, вырубленному в склоне горы. Пандус ведет прямо к внешнему порогу горной крепости.",al={"how to get into ironforge","path to ironforge gates","ironforge ramp","как попасть в стальгорн","путь к вратам стальгорна","пандус стальгорна"}}},fp="18,283,29.506.0,37.216.0,45.253.0,43.183.0"}
P.entries["subzone:gates-of-orgrimmar"] = {n="Врата Оргриммара",s="Врата Оргриммара — внушительный южный порог столицы Орды, вырубленный прямо в красной скале северного Дуротара. Обрамленный тяжелыми бревенчатыми и железными укреплениями, этот величественный вход соединяет засушливые пустоши снаружи с оживленным Общинным кварталом Аллеи Силы. Он служит зримым свидетельством стойкости и воинской мощи орков.",h="Врата Оргриммара — внушительный южный порог столицы Орды, вырубленный прямо в красной скале северного...",ang={["faction:Alliance"]="Для разведчиков и лазутчиков Альянса эти врата — одно из самых охраняемых узких мест Калимдора, которое почти невозможно взять лобовой атакой.",["faction:Horde"]="Массивные врата означают безопасность, принадлежность и завоеванную с трудом родину, созданную под руководством вождя Тралла."},sec={{t="Бастион Дуротара",b="Главные врата, обрамленные высокими деревянными палисадами, огромными железными шипами и укрепленными сторожевыми башнями, охраняют основное ущелье в горах, укрывающих Оргриммар. Для путников, идущих от Колючего Холма и кустарниковых равнин Дуротара, вход служит и радушным памятником, и суровым предостережением для всех, кто посмеет угрожать новой Орде. Подступы патрулируют тяжеловооруженные грунты Оргриммара и охотники за головами Черного Копья, неусыпно наблюдая за всеми, кто входит в город."},{t="Порог долины",b="Пройдя под сумрачной аркой врат, вы попадаете прямо в Аллею Силы — гражданский и военный центр Оргриммара. Туннель врат служит акустическим и тактическим узким местом, пропуская посланников, торговцев и воинов мимо бдительных часовых. Он воплощает мечту вождя Тралла: надежное убежище, созданное в суровой пустыне, где разные народы Орды могут ходить вместе без страха."}},faq={{q="Куда ведут Врата Оргриммара?",a="Врата соединяют северный Дуротар напрямую с Аллеей Силы — главным входом и центральным кварталом Оргриммара.",al={"what do the gates connect","where is the front gate","что соединяют врата","где главные врата"}},{q="Кто охраняет врата?",a="Главные врата охраняют опытные грунты Оргриммара и охотники за головами Черного Копья, постоянно бдящие против вражеских лазутчиков и диких зверей.",al={"who protects the gate","gate guards","кто охраняет врата","стража врат"}},{q="Почему вход укреплен деревом и шипами?",a="Архитектура отражает традиционные орочьи пограничные укрепления: прочная древесина из соседних земель и железные шипы создают устрашающий, легко обороняемый проход среди стен каньона.",al={"why wood and iron spikes","orcish gate design","почему дерево и железные шипы","орочья архитектура врат"}},{q="Могут ли игроки Альянса пройти через эти врата?",a="Члены Альянса, пытающиеся пройти через главные врата, сразу столкнутся с враждебными стражами-ветеранами, готовыми на месте убить любого врага Орды.",al={"can alliance enter","alliance walk through gate","может ли альянс войти","альянс проходит через врата"}}},fp="18,360,22.494.0,23.436.0,37.143.0,21.158.0,51.208.0,44.156.0"}
P.entries["subzone:gelkis-village"] = {n="Деревня Гелкис",s="Деревня Гелкис — главный оплот клана кентавров Гелкис, поклоняющихся земле, на юго-западе Пустошей. Поселение построено вокруг неровного ущелья, через которое переброшены деревянные мосты и проложены тропы по скалам, и охраняет южный путь к Фераласу. Оно господствует над главной дорогой с севера на юг, поэтому проход здесь опасен для любого путника, не заслужившего расположения клана.",h="Деревня Гелкис — главный оплот клана кентавров Гелкис, поклоняющихся земле, на юго-западе Пустошей.",ang={["faction:Horde"]="Поскольку поселение Черного Копья — Деревня Ночных Охотников — лежит прямо к западу на побережье, укрепленное присутствие Гелкис постоянно угрожает ближайшим предприятиям Орды.",["race:Tauren"]="Кентавры поколениями изгоняли таурен с их исконных земель; вид Гелкис, засевших в скалистых бастионах, горько напоминает о той неизменной угрозе, которую они представляют для Калимдора."},sec={{t="Крепость в ущелье",b="Gelkis Village sits in a deep, craggy gorge framed by precarious bluffs and rope bridges. Unlike the nomadic raiders of the Barrens, the Gelkis have fortified their ancestral grounds into a permanent settlement, complete with outposts spreading toward the border of Feralas. The heart of the clan's leadership lies within Bolgan's Hole, a cavern carved into the southern cliff face where Khan Shaka oversees his warriors. Travelers trekking south through Desolace must either cut a bloody path through the gorge or tread carefully, as the Gelkis view uninvited wanderers as fair game in their eternal war against their rival centaur brethren."}},faq={{q="Кто живет в Деревне Гелкис?",a="The settlement belongs to the Gelkis clan, one of the warring centaur tribes of Desolace. They are staunch earth-worshipers ruled by Khan Shaka, who resides deep in the cliffside cave known as Bolgan's Hole.",al={"gelkis residents","who controls gelkis village","centaur village south","жители гелкис","кто управляет деревней гелкис","кентавры на юге"}},{q="Почему кентавры Гелкис враждебны к чужакам?",a="Культура кентавров крайне территориальна и агрессивна к чужакам. Однако Гелкис больше всего ненавидят соперничающий клан — Маграм. Искатели приключений, охотящиеся на воинов Маграм, со временем могут заслужить доверие клана Гелкис и безопасно входить в деревню.",al={"why are gelkis attacking","gelkis hostile","can i be friendly with gelkis","почему гелкис нападают","гелкис враждебны","можно ли подружиться с гелкис"}},{q="Где находится Деревня Гелкис?",a="Она находится на юго-западе Пустошей, к востоку и чуть к югу от тролльего поселения — Деревни Ночных Охотников. Ее ущелья примыкают к южному горному склону и выходят на тропу, ведущую прямо на юг, в Фералас.",al={"gelkis location","how to find gelkis village","where is gelkis","расположение гелкис","как найти деревню гелкис","где гелкис"}},{q="Что такое Пещера Болгана?",a="Пещера Болгана — большая пещера, вырубленная в южной скальной стене ущелья и соединенная с остальной деревней высокими мостами и утесами. Это внутреннее святилище и средоточие власти хана Гелкис.",al={"bolgans hole","cave in gelkis village","where is gelkis khan","пещера болгана","пещера в деревне гелкис","где хан гелкис"}}},fp="14,382,24.642.0,28.207.0,48.264.0,32.221.0,22.223.0"}
P.entries["subzone:ghost-walker-post"] = {n="Застава Скитающихся Духов",s="Застава Скитающихся Духов — скромное поселение таурен в самом сердце Пустошей, рядом с древним Кладбищем кодо. Она гораздо сильнее подвержена местным опасностям, чем Деревня Ночных Охотников на западном побережье, и служит передовым оплотом Орды в борьбе с кланами кентавров и Пылающим Клинком.",h="Застава Скитающихся Духов — скромное поселение таурен в самом сердце Пустошей, рядом с древним Кладбищем кодо.",kw={"burning blade","centaur","desolace","ghost walker post","gurda wildmane","horde","kodo graveyard","shadowprey village","tauren","thrall","пылающий клинок","кентавр","пустоши","застава скитающихся духов","гурда буйногривая","орда","кладбище кодо","деревня ночных охотников","таурен","тралл"},ang={["class:Shaman"]="Под началом Гурды Буйногривой здешние шаманы совершают священный труд: говорят с древними духами и помогают умирающим животным перейти в мир духов.",["race:Tauren"]="Лагерь отражает глубокий священный долг таурен перед миром природы: он стоит стражем рядом с родовым местом упокоения кодо."},sec={{t="Дозор в пустошах",b="Застава Скитающихся Духов, расположенная на пыльных равнинах центральной части Пустошей, служит Орде суровым опорным пунктом на враждебной земле. В отличие от защищенной прибрежной рыбацкой гавани — Деревни Ночных Охотников, эта застава напрямую граничит с кочующими кентаврами-мародерами и поклоняющимися демонам сектантами Пылающего Клинка. Удобства здесь спартанские: путникам доступно лишь самое необходимое, а таверны и распорядителя полетов не видно. Несмотря на суровые условия, гарнизон таурен и отряд орков, присланный вождем Траллом, бдительно охраняют эти бесплодные земли."},{t="Стражи кладбища",b="Заставой руководит шаман-таурен Гурда Буйногривая, и ее духовное сердце тесно связано с соседним Кладбищем кодо. Шаманы, живущие здесь, ухаживают за умирающими животными, которые приходят сюда, чтобы испустить дух, помогают им перейти в следующую жизнь и общаются с их задержавшимися духами. Между духовным общением и постоянной боевой готовностью защитники заставы чтят древнюю связь таурен с могучими кодо среди пепла Пустошей."}},faq={{q="Что такое Застава Скитающихся Духов?",a="Это небольшая суровая застава Орды в центральной части Пустошей, основанная в основном тауренами при поддержке орочьего гарнизона.",al={"ghost walker post info","what is this camp","horde camp desolace","застава скитающихся духов","что это за лагерь","лагерь орды в пустошах"}},{q="Кто руководит Заставой Скитающихся Духов?",a="Заставой руководит Гурда Буйногривая, шаман-таурен, которая заботится об обороне лагеря и соседнем Кладбище кодо.",al={"who is in charge","ghost walker leader","gurda wildmane","кто главный","предводитель заставы скитающихся духов","гурда буйногривая"}},{q="Почему застава расположена рядом с Кладбищем кодо?",a="Гурда Буйногривая и другие шаманы-таурены живут здесь, чтобы помогать умирающим кодо переходить в следующую жизнь и общаться с духами павших животных.",al={"why by kodo graveyard","kodo spirits camp","shaman kodo graveyard","почему у кладбища кодо","духи кодо лагерь","шаман кладбище кодо"}},{q="С какими врагами сражается Застава Скитающихся Духов?",a="Гарнизон ведет непрерывную войну с местными враждебными племенами кентавров и зловещими силами Пылающего Клинка, действующими по всем Пустошам.",al={"ghost walker enemies","who attacks ghost walker post","post threats","враги заставы скитающихся духов","кто нападает на заставу","угрозы заставе"}},{q="Можно ли здесь получить путь полета или отдохнуть в таверне?",a="Нет. Застава предлагает искателям приключений лишь самое необходимое, и здесь нет ни трактирщика, ни распорядителя полетов на наездниках на ветрокрылах. Путникам придется искать транспорт в другом месте, например в Деревне Ночных Охотников.",al={"flight master ghost walker","innkeeper ghost walker","fp here?","распорядитель полетов застава","трактирщик застава","пункт полета здесь"}},{q="Чем она отличается от Деревни Ночных Охотников?",a="Деревня Ночных Охотников — защищенный анклав троллей на западном побережье, а Застава Скитающихся Духов расположена вдали от моря, сильно подвержена окрестным угрозам и занята обороной рубежей и духовными обязанностями.",al={"shadowprey vs ghost walker","other horde camp desolace","деревня ночных охотников или застава","другой лагерь орды в пустошах"}}},fp="17,296,21.553.0,26.464.0,26.134.0,28.119.0,48.152.0,42.144.0,47.188.0,42.198.0"}
P.entries["subzone:gnomeregan"] = {n="Гномреган",s="Гномреган был великолепной подземной столицей гномов, известной по всему Азероту механическим мастерством и технологическими чудесами. Сегодня это радиоактивная гробница, захваченная подземными троггами, взбесившимися защитными автоматами и безумными лепрогномами после того, как отчаянная оборона закончилась катастрофой.",h="Гномреган был великолепной подземной столицей гномов, известной по всему Азероту механическим мастерством и...",kw={"dun morogh","gnomeregan","leper gnome","mekkatorque","thermaplugg","tinkers court","trogg","дун морог","гномреган","лепрогном","меггакрут","термоштепсель","двор механиков","трогг"},ang={["profession:Engineering"]="Даже задыхаясь от радиоактивного яда, Гномреган остается крупнейшим в Восточных королевствах собранием схем, редких запчастей и действующих промышленных механизмов.",["race:Gnome"]="Каждый гном несет травму от потери Гномрегана. Вход в облученные залы — торжественное паломничество, чтобы уничтожить узурпатора Термоштепселя и вернуть утраченные механические реликвии."},sec={{t="Чудо инженерной мысли",b="Гномреган, вырубленный в заснеженных скалах западного Дун Морога, был построен много веков назад с помощью дворфов Стальгорна. Внутри огромные паровые шестерни, затейливые медные трубы и просторные сборочные залы составляли интеллектуальное и промышленное сердце гномов. Именно из этих подземных залов гномьи изобретения, летательные машины и сложное вооружение снабжали Альянс на протяжении Второй войны, и город держался даже в осаде Орды Оргрима Молота Рока."},{t="Падение и отравленные залы",b="Во время Третьей войны из глубин земли хлынули полчища троггов и прорвались в нижние залы города. Не желая отвлекать армии Альянса от бойни в Лордероне, главный механик Гелбин Меггакрут попытался справиться с кризисом в одиночку. По совету своего главного инженера Сикко Термоштепселя Меггакрут приказал выпустить радиоактивный газ через нижние залы, чтобы уничтожить тварей. План обернулся ужасным провалом: газ усилил многих троггов и убил почти восемьдесят процентов гномов. Те, кто подвергся облучению, но выжил, превратились в уродливых лепрогномов, а Термоштепсель захватил власть над отравленными руинами."}},faq={{q="Почему Гномреган полон радиации?",a="Когда подземные трогги захватили город, главный механик Меггакрут по совету Сикко Термоштепселя выпустил радиоактивный газ в нижние вентиляционные шахты. Отчаянный шаг должен был уничтожить тварей, но вместо этого погубил тысячи гномов, превратил выживших в лепрогномов и навсегда оставил город зараженным радиацией.",al={"why is it radioactive","gnomeregan toxic gas","what poisoned gnomeregan","почему радиоактивный","ядовитый газ гномрегана","что отравило гномреган"}},{q="Где сейчас выжившие гномы?",a="Выжившие бежали в соседний город дворфов Стальгорн. Король Магни Бронзобород предоставил им убежище во Дворе Механиков, где главный механик Гелбин Меггакрут теперь координирует помощь своему рассеянному народу и планирует возвращение родного дома.",al={"where do gnomes live","gnome refugees","where is mekkatorque","где живут гномы","гномы-беженцы","где меггакрут"}},{q="Кто сейчас управляет Гномреганом?",a="Сикко Термоштепсель, бывший главный советник Меггакрута, провозгласил себя королем Гномрегана. Сведенный с ума отравлением и манией величия, он командует взбесившимися защитными автоматами, облученными лепрогномами и мутировавшими троггами из самых глубин города.",al={"who is the boss of gnomeregan","gnomeregan leader","thermaplugg","кто главный в гномрегане","предводитель гномрегана","термоштепсель"}},{q="Почему Альянс не помог спасти Гномреган во время вторжения?",a="Меггакрут намеренно не стал просить помощи у Альянса. Поскольку человечество рушилось под натиском Плети во время Третьей войны, гномы держали свою подземную борьбу в тайне, чтобы не отвлекать важных защитников от Лордерона.",al={"why alliance no help","why didn't humans help gnomes","gnomes in third war","почему альянс не помог","почему люди не помогли гномам","гномы в третьей войне"}}},fp="10,327,23.491.0,31.662.0,36.338.0,39.260.0,28.256.0,65.251.0"}
P.entries["subzone:goblin-foundry"] = {n="Гоблинская литейная",s="Гоблинская литейная — промышленная мастерская в глубине Мертвых копей, где гоблины-механики изготавливают тяжелые металлические изделия для Братства Справедливости. Зал занимает огромный плавильный котел, а в нем по-прежнему трудятся гоблины-мастера и инженеры под началом Гилнида.",h="Гоблинская литейная — промышленная мастерская в глубине Мертвых копей, где гоблины-механики изготавливают...",kw={"cauldron","deadmines","defias","goblin foundry","vancleef","котел","мертвые копи","братство справедливости","гоблинская литейная","ван клиф"},ang={["faction:Alliance"]="Мастерская Братства Справедливости показывает масштаб промышленных ресурсов Братства под Западным Краем.",["profession:Engineering"]="Литейная демонстрирует гоблинское металлообрабатывающее мастерство и механическую изобретательность: инженеры защищают мастерскую управляемыми по радио големами."},sec={{t="Промышленные амбиции",b="Гоблинская литейная, вырубленная в подземных глубинах Луноречья, дает Братству Справедливости тяжелую производственную мощь. Гоблины-мастера и инженеры работают среди плавилен и железных помостов, изготавливая якоря и ядра."},{t="Мастерская Гилнида",b="Гилнид управляет гоблинскими работниками литейной. Мастера поддерживают производство, а инженеры защищают мастерскую с помощью управляемых по радио големов, из-за чего узкие помосты и расплавленный металл опасны для чужаков."}},faq={{q="Что строили в Гоблинской литейной?",a="Гоблины-мастера изготавливают тяжелые металлические изделия, включая якоря и ядра, для Братства Справедливости.",al={"what are they making here","foundry purpose","deadmines factory","что здесь делают","назначение литейной","фабрика мертвых копей"}},{q="Почему в литейной есть големы?",a="Гоблины-инженеры используют управляемых по радио големов для защиты мастерской от чужаков.",al={"why golems here","foundry robots","mechanical enemies deadmines","почему здесь големы","роботы литейной","механические враги мертвые копи"}},{q="Где гоблины, управлявшие этой мастерской?",a="Гоблины-мастера и инженеры продолжают работать в литейной под началом плавильщика Гилнида.",al={"where are the goblins","foundry engineers","gilnid workers","где гоблины","инженеры литейной","работники гилнида"}},{q="Что за огромное сооружение в центре зала?",a="В центре зала доминирует огромный промышленный плавильный котел, в котором переплавляют руду, добытую в шахтах, для ковки пластин брони и механических корпусов.",al={"foundry center pot","smelting vat","cauldron in deadmines","котел в центре литейной","плавильный чан","котел в мертвых копях"}}},fp="14,271,20.238.0,17.215.0,43.108.0,36.89.0,44.91.0,54.167.0"}
P.entries["subzone:gol-bolar-quarry"] = {n="Карьер Гол'Болар",s="Карьер Гол'Болар — гномий и дворфийский раскоп в заснеженных холмах юго-востока Дун Морога. Некогда оживленные работы по добыче камня и руды остановились: карьер захватили свирепые трогги, хлынувшие из глубин.",h="Карьер Гол'Болар — гномий и дворфийский раскоп в заснеженных холмах юго-востока Дун Морога.",kw={"dun morogh","gol'bolar","mine","prospector gehn","quarry","trogg","дун морог","гол'болар","рудник","геолог генн","карьер","трогг"},ang={["profession:Mining"]="Открытые каменные уступы и соседние туннели богаты рудными жилами, но старателям придется прорываться через окопавшихся троггов.",["race:Dwarf"]="Очистка карьера Гол'Болар — вопрос и экономической необходимости, и гордости клана: Стальгорн не может позволить грубым троггам завладеть богатствами своих гор."},sec={{t="Карьер в осаде",b="Карьер Гол'Болар, расположенный к юго-востоку от Караноса, основали дворфы Стальгорна, чтобы добывать в горах камень и ценные минералы. Однако при глубоких раскопках обнаружились подземные норы, откуда вырвалась орда враждебных троггов и быстро прогнала шахтеров. Сегодня верхний лагерь служит осажденным оплотом, где надсмотрщики, торговцы и геолог Генн собирают дворфов и гномов-добровольцев, чтобы отбросить тварей и вернуть карьер."}},faq={{q="Что такое карьер Гол'Болар?",a="Карьер Гол'Болар — открытая разработка на юго-востоке Дун Морога. Им управляют дворфы Стальгорна: это и место раскопок, и небольшой форпост, где местные искатели приключений находят припасы и работу.",al={"gol bolar","what is this place","quarry info","гол'болар","что это за место","о карьере"}},{q="Почему здесь так много троггов?",a="Дворфы-шахтеры забрались слишком глубоко и пробили подземные туннели, где обитали трогги. Твари хлынули в открытые карьеры и соседние штольни и вынудили шахтеров отступить на верхний край карьера.",al={"why are troggs here","trogg infestation","who attacked the quarry","почему здесь трогги","нашествие троггов","кто напал на карьер"}},{q="Кто такой геолог Генн?",a="Геолог Генн — дворф-надсмотрщик, расквартированный в лагере карьера. Он руководит защитой места раскопок и выдает награды и поручения искателям приключений, готовым сократить число троггов.",al={"who is gehn","prospector gehn","кто такой генн","геолог генн"}}},fp="16,238,20.470.0,25.217.0,34.226.0,23.195.0"}
P.entries["subzone:gol-bolar-quarry-mine"] = {n="Рудник карьера Гол'Болар",s="Рудник карьера Гол'Болар — захваченная шахта в самом сердце карьера Гол'Болар на востоке Дун Морога. Дворфы-шахтеры пробили туннелями подземные пещеры троггов, и вспыхнувшее нашествие захватило все место. Сегодня самые глубокие штольни служат оплотом отряда троггов под началом громилы Молотохребта.",h="Рудник карьера Гол'Болар — захваченная шахта в самом сердце карьера Гол'Болар на востоке Дун Морога.",kw={"dun morogh","gol'bolar","gol'bolar quarry mine","hammerspine","mine","quarry","troggs","дун морог","гол'болар","рудник карьера гол'болар","молотохреб","рудник","карьер","трогги"},ang={["profession:Mining"]="Суровое напоминание об опасностях подземных раскопок: рудник полностью перекрыт враждебными троггами, пока не очищены его глубочайшие туннели.",["race:Dwarf"]="Каждый удар кирки по горе грозит пробудить то, что лежит внизу. Вернуть рудник Гол'Болар — вопрос и экономической необходимости, и гордости дворфов."},sec={{t="Прорыв в глубине",b="Рудник основали дворфы Стальгорна, искавшие камень и богатые залежи руды под скалистыми пиками Дун Морога. Работы резко и жестоко оборвались, когда кирки пробили стену в древнюю систему подземных пещер, населенных троггами. Хлынув из тьмы, подземные твари смяли рабочих, заставили их поспешно отступить и в итоге выплеснулись наружу, захватив и окружающий карьер."},{t="Логово Молотохребта",b="Пока молодые и слабые трогги бродят по залитым солнцем террасам карьера, в самом руднике скрываются сильнейшие бойцы отряда. В глубине тесных туннелей, освещенных факелами, затаился их свирепый вождь Молотохреб. Вернуть ценный карьер — неотложная задача местных горцев, но чтобы выкурить нашествие, нужно спуститься в самые темные глубины рудника и перерезать тварям путь у истока."}},faq={{q="Почему рудник полон троггов?",a="Дворфы-шахтеры случайно пробили при раскопках скрытую подземную пещеру. Спавшие внутри трогги хлынули через пролом, перебили или прогнали рабочих и сделали штольни своим домом.",al={"why are troggs in gol bolar","how did troggs get here","who took over the mine","почему трогги в гол'болар","как трогги сюда попали","кто захватил рудник"}},{q="Кто предводительствует троггами в руднике карьера Гол'Болар?",a="Троггов в руднике возглавляет Молотохреб — огромный громила, который из глубины штолен командует сильнейшими воинами отряда.",al={"mine boss","trogg leader gol bolar","who is hammerspine","главарь рудника","предводитель троггов гол'болар","кто такой молотохреб"}},{q="Отличается ли рудник от остального карьера?",a="Да. В наружном карьере находятся наземные сооружения и более слабые трогги, а рудник — это глубокие, тесные подземные туннели, где обитают самые сильные трогги и их вождь.",al={"quarry vs mine","are the mine troggs harder","карьер или рудник","сильнее ли трогги в руднике"}},{q="Могут ли здесь по-прежнему работать шахтеры?",a="Нет. Добыча полностью прекращена. Это действующая зона боевых действий: дворфы-горцы и искатели приключений истребляют угрозу троггов, а не добывают камень.",al={"is the mine active","are dwarves still mining","работает ли рудник","добывают ли дворфы руду"}}},fp="21,366,20.435.0,19.432.0,31.222.0,50.145.0,50.192.0,27.181.0"}
P.entries["subzone:golakka-hot-springs"] = {n="Горячие источники Голакка",s="Горячие источники Голакка — геотермальная котловина на западе кратера Ун'Горо, к северу от Пути Ужаса. Кипящие бассейны и гейзеры питаются сильной вулканической активностью соседнего Вулкана Огненного Венца. Богатые минералами воды привлекают чудаковатых исследователей, алхимиков в поисках редких реагентов и бродячих водных элементалей — паровых яростей.",h="Горячие источники Голакка — геотермальная котловина на западе кратера Ун'Горо, к северу от Пути Ужаса.",kw={"fire plume ridge","geyser","golakka","hot springs","krakle","spark nilminer","steaming fury","terror run","un'goro","вулкан огненного венца","гейзер","голакка","горячие источники","краккл","искр пустокоп","паровая ярость","путь ужаса","ун'горо"},ang={["class:Shaman"]="Горячие источники показывают мощное взаимодействие огня и воды: столкновение стихий порождает кипящих паровых яростей на минеральных берегах.",["race:Gnome"]="Экстремальная геологическая активность бесконечно увлекает гномов, таких как Искр Пустокоп, которая рискует среди обжигающих паровых жерл, чтобы вблизи изучить геотермальную механику."},sec={{t="Кипящие воды и вулканический пар",b="Горячие источники Голакка, лежащие в западной части кратера Ун'Горо, — прямое следствие подземного жара Вулкана Огненного Венца. Обжигающая вода непрерывно поднимается на поверхность, образуя ступенчатые минеральные террасы и бурно извергающиеся гейзеры. Здесь повсюду бродят паровые ярости — стихийные воплощения, рожденные слиянием подземных вод и вулканического жара. Несмотря на опасность, источники часто привлекают путешественников, травников и исследователей, увлеченных уникальной геологией кратера."},{t="Любопытные обитатели и странная химия",b="Необычные свойства вод Голакка интересуют не только любителей достопримечательностей. Алхимики ценят обогащенную геотермальным теплом воду как мощный катализатор и даже применяют ее в тонких составах, например в любовных зельях. У гейзерного жерла встречаются и чудаковатые гости: Искр Пустокоп сидит на центральном жерле гейзера, а исследователь Краккл пытается понять, как источники напрямую связаны с вулканическим сердцем кратера."}},faq={{q="Почему источники такие горячие?",a="Источники нагревает мощная вулканическая система под кратером Ун'Горо, напрямую связанная с Вулканом Огненного Венца. Магма под дном кратера перегревает подземные запасы воды, и кипящая, богатая минералами вода с паром вырывается через гейзеры и ступенчатые бассейны.",al={"why is water boiling","geothermal heat un'goro","fire plume connection","почему вода кипит","геотермальный жар ун'горо","связь с огненным венцом"}},{q="Какие существа обитают в горячих источниках Голакка?",a="Чаще всего по берегам и бассейнам бродят паровые ярости. Это духи живой воды, которые под палящим жаром вулканических жерл превратились в клокочущий, нестабильный пар.",al={"hot springs elementals","what lives in golakka","steaming fury","элементали источников","кто живет в голакка","паровая ярость"}},{q="Для чего используют воду горячих источников?",a="Насыщенную минералами воду ценят алхимики и чудаковатые зельевары за ее уникальные химические свойства. В частности, чистые образцы из источников ищут как важный реагент для особых составов, в том числе сильных любовных зелий.",al={"golakka water use","hot springs love potion","hot springs reagents","вода голакка","любовное зелье источники","реагенты источников"}},{q="Кто такой Краккл и что он здесь делал?",a="Краккл — исследователь, изучающий геотермальную связь между горячими источниками Голакка и Вулканом Огненного Венца: он собирает наблюдения и замеры температуры у источников.",al={"krakle un'goro","krakle hot springs","researcher at the hot springs","краккл ун'горо","краккл источники","исследователь у источников"}}},fp="19,367,33.552.0,41.474.0,27.272.0,43.209.0,48.258.0,41.177.0"}
P.entries["subzone:gold-coast-quarry"] = {n="Прииск на Золотом Берегу",s="Прииск на Золотом Берегу — открытая разработка в утесах юго-запада Западного Края. Некогда он был ценным источником камня, минералов и золота для Королевства Штормград, а теперь его захватило Братство Справедливости, чтобы подпитывать растущий мятеж.",h="Прииск на Золотом Берегу — открытая разработка в утесах юго-запада Западного Края.",kw={"defias","defias brotherhood","gold coast quarry","mine","people's militia","quarry","stormwind","westfall","братство справедливости","прииск на золотом берегу","рудник","народное ополчение","прииск","штормград","западный край"},ang={["faction:Alliance"]="Возвращение таких мест, как Прииск на Золотом Берегу, жизненно важно для восстановления порядка в Западном Крае, где из-за отсутствия королевских гарнизонов местным добровольцам пришлось взяться за оружие.",["profession:Mining"]="Шахтеры, забредшие в Западный Край, найдут вдоль утесов прииска богатые каменные пласты и рудные жилы, но чтобы добывать их, придется пробиваться через окопавшиеся патрули Братства Справедливости."},sec={{t="Разграбленное богатство",b="Пока королевство не пришло в упадок, Прииск на Золотом Берегу поставлял строительные материалы и драгоценное золото для восстановления Штормграда. Когда королевские войска ушли из Западного Края и оставили земли без защиты, разбойники Братства Справедливости и беглые рабочие захватили разработки. Теперь Братство патрулирует ступенчатые каменные пандусы, пользуясь видом на побережье, и грабит оставшиеся минералы, чтобы платить за мятеж."}},faq={{q="Для чего изначально использовался прииск?",a="Прииск основало Королевство Штормград, чтобы добывать камень, минералы и золото в прибрежных утесах. Значительная часть камня, добытого в Западном Крае, помогла восстановить Штормград после Второй войны.",al={"why is there a quarry here","what did they mine here","gold coast purpose","зачем здесь прииск","что здесь добывали","назначение золотого берега"}},{q="Кто сейчас контролирует Прииск на Золотом Берегу?",a="Прииск контролирует Братство Справедливости. Его бандиты, мародеры и разбойники патрулируют ступенчатые утесы и входы в шахты, не пуская честных поселенцев и добывая ресурсы для своих незаконных дел.",al={"who is at the quarry","who owns gold coast quarry","enemies at the quarry","кто на прииске","кто владеет прииском на золотом берегу","враги на прииске"}},{q="Почему Штормград не послал стражу, чтобы освободить прииск?",a="Король Вариан Ринн пропал, а Дом знати Штормграда не желает оплачивать постоянный военный гарнизон в Западном Крае, поэтому корона бросила этот край. Местному Народному ополчению приходится самому сражаться за такие места, как прииск.",al={"why no stormwind army","where are the guards","why is it abandoned","почему нет армии штормграда","где стража","почему он заброшен"}},{q="Где находится Прииск на Золотом Берегу?",a="Он вырублен в утесах вдоль юго-западного побережья Западного Края, к югу от ферм Сальден и Поместья Алекстона, с видом на Великое море.",al={"quarry location","how to find gold coast quarry","where is it","где прииск","как найти прииск на золотом берегу","где это"}}},fp="17,251,20.444.0,40.227.0,45.216.0,53.258.0,39.159.0"}
P.entries["subzone:gold-road"] = {n="Золотой Путь",s="Золотой Путь — главная артерия с севера на юг, пересекающая засушливые просторы Степей. Он тянется от Заставы Мор'шан на границе Ясеневого леса мимо Перекрестка к южным областям и служит жизненно важной транспортной линией молодой Орды.",h="Золотой Путь — главная артерия с севера на юг, пересекающая засушливые просторы Степей.",kw={"caravan","crossroads","gold road","great divide","highway","mor'shan","the barrens","караван","перекресток","золотой путь","большой разлом","дорога","мор'шан","степи"},ang={["class:Hunter"]="Саванна у дороги кишит равнинными зверями, поэтому ее долгий путь идеален для выслеживания и приручения первых питомцев охотника, таких как львы и ящеры-ловчие.",["faction:Horde"]="Золотой Путь — основа снабжения Орды в Калимдоре: он связывает орочью столицу в Дуротаре с землями тауренов в Мулгоре и северными передовыми лагерями близ Ясеневого леса."},sec={{t="Артерия Степей",b="Золотой Путь — длинная, выжженная солнцем грунтовая дорога, рассекающая центр Степей. На севере он начинается у укрепленной Заставы Мор'шан и Лагеря Мор'шан, которые защищают от вторжений ночных эльфов из Ясеневого леса. На юге он соединяется с восточной дорогой в Дуротар, а затем пересекает оживленное торговое поселение Перекресток. Далее на юг, мимо зеленых оазисов и предгорий у Пещер Стенаний, северный участок дороги доходит до высохшего русла реки, где путники попадают в более опасную южную часть саванны."},{t="Важный и опасный путь",b="Хотя Золотой Путь — основа торговли и передвижения войск Орды между центральными землями Калимдора, он опасен. Караванам и одиноким гонцам постоянно угрожают свирепые племена свинобразов, отряды кентавров, а также бродящие равнинные ходоки и львы. Орда тратит немало сил, размещая вдоль дороги разведчиков и воинов, но путникам советуют оставаться вооруженными и настороженными, покидая безопасные крупные форпосты."}},faq={{q="Где начинается и заканчивается Золотой Путь?",a="Золотой Путь начинается на крайнем севере Степей у Заставы Мор'шан на границе Ясеневого леса. Его северный участок идет на юг через Перекресток до высохшего русла, разделяющего северные и южные Степи, где Южный Золотой Путь продолжается мимо Лагеря Таурахо к Великому Подъемнику.",al={"gold road route","where does the gold road go","gold road length","маршрут золотого пути","куда ведет золотой путь","длина золотого пути"}},{q="Почему Золотой Путь так важен для Орды?",a="Дорога связывает все основные земли недавно образованной Орды в центральном Калимдоре. По ней идут линии снабжения из Дуротара и порта Кабестан к землям тауренов в Мулгоре и к северному военному фронту против ночных эльфов в Ясеневом лесу.",al={"why is gold road important","importance of gold road","почему важен золотой путь","значение золотого пути"}},{q="Какие угрозы бродят у дороги?",a="Путники часто встречают отряды налетчиков-свинобразов из племен Иглогривых и Дыбогривов, бродячих кентавров Колкара и агрессивных диких зверей, например саванных охотников и громовых ящеров. За пределами Перекрестка дорога далеко не безопасна.",al={"is gold road safe","enemies on gold road","gold road dangers","безопасен ли золотой путь","враги на золотом пути","опасности золотого пути"}},{q="Как Золотой Путь связан с Дуротаром?",a="К северу от Перекрестка от Золотого Пути ответвляется восточная дорога, которая по деревянному мосту через Реку Строптивую ведет прямо в Дуротар.",al={"road to durotar","turn off to durotar","дорога в дуротар","поворот на дуротар"}}},fp="9,271,25.633.0,26.464.0,39.318.0,47.263.0,34.250.0,42.153.0"}
P.entries["subzone:golden-plains"] = {n="Золотые равнины",s="Золотые равнины — обширная залитая солнцем низина к юго-востоку от Громового Утеса в центральной части Мулгора. Эти раздольные луга, любимые таурами, служат отличными охотничьими угодьями и важными пастбищами для бродячих стад кодо.",h="Золотые равнины — обширная залитая солнцем низина к юго-востоку от Громового Утеса в центральной части...",kw={"arra'chea","golden plains","hunting grounds","kodo","mulgore","thunder bluff","арра'чея","золотые равнины","охотничьи угодья","кодо","мулгор","громовой утес"},ang={["class:Hunter"]="Обширные открытые просторы и бродящие стада кодо делают эти равнины отличным испытанием для следопытов, ищущих легендарных зверей вроде Арра'чеи.",["race:Tauren"]="Для тауренов Золотые равнины — непреходящий символ щедрости их родины и священные охотничьи угодья в тени Громового Утеса."},sec={{t="Сердце охоты",b="Золотые равнины раскинулись у подножия высоких плато Громового Утеса и составляют дикое сердце Мулгора. Переливающееся море золотой и зеленой травы дает обильное убежище местным животным, поэтому это одно из самых дорогих сердцу традиционных охотничьих угодий кочевых тауренов. По холмистой низине бродят большие стада кодо, а охотники рассказывают истории о легендарной добыче, прежде всего о великом кодо Арра'чее, который тихо бродит среди высоких стеблей."}},faq={{q="Что такое Золотые равнины?",a="Золотые равнины — широкая травянистая низина к юго-востоку от Громового Утеса в Мулгоре. Это любимые тауренами охотничьи угодья с традиционным значением, известные широкими просторами и обилием диких животных.",al={"golden plains mulgore","where are golden plains","золотые равнины мулгор","где находятся золотые равнины"}},{q="Какие животные обитают на Золотых равнинах?",a="Низина славится обильными стадами диких кодо и другими местными существами Мулгора. Самый известный зверь, который, как говорят, бродит по этим лугам, — неуловимый и почитаемый кодо по имени Арра'чея.",al={"golden plains beasts","kodos in golden plains","звери золотых равнин","кодо на золотых равнинах"}},{q="Почему эта местность важна для тауренов?",a="Равнины служат важным источником дичи и шкур, кормят недавно основанные поселения Мулгора и воплощают тауренскую традицию выслеживать добычу и чтить ее.",al={"tauren golden plains","why tauren hunt here","таурены золотые равнины","почему таурены охотятся здесь"}}},fp="13,248,17.476.0,27.198.0,36.204.0,41.199.0"}
P.entries["subzone:goldshire"] = {n="Златоземье",s="Златоземье — важный перекресток людей в центре Элвиннского леса, соединяющий Штормград с Западным Краем, Красногорьем и южным пограничьем. Отстроенное после разрушения в Первой войне, оно служит оживленным перевалочным пунктом, известным по таверне Гордость Льва и защищаемым изнуренным отрядом Стражи Штормграда.",h="Златоземье — важный перекресток людей в центре Элвиннского леса, соединяющий Штормград с Западным Краем...",kw={"crystal lake","elwynn","goldshire","lion's pride inn","marshal dughan","murloc","riverpaw","stone cairn lake","озеро хрустальное","элвиннский лес","златоземье","таверна гордость льва","маршал дугхан","мурлок","речная лапа","озеро каменных столбов"},ang={["faction:Alliance"]="Златоземье — важный транзитный узел, соединяющий столицу Альянса с окрестными пограничными землями: Западным Краем, Красногорьем и Сумеречным лесом.",["race:Human"]="Для людей, только что покинувших Аббатство Североземья, Златоземье — первое настоящее знакомство с королевством за стенами монастыря и отрезвляющий взгляд на напряженные границы Штормграда."},sec={{t="Перекресток под угрозой",b="Златоземье, лежащее там, где сходятся королевские тракты, давно стало гражданским и торговым сердцем сельского Элвинна. Однако идиллическая картина скрывает растущую опасность в 25 году ПДП. Военные силы Штормграда истощены, а король Вариан Ринн загадочно отсутствует, и маршалу Дугхану приходится полагаться на случайных искателей приключений, а не на регулярные войска. Агрессивные гноллы Речной Лапы наступают с западной границы, а свирепые мурлоки захватили берега Озера Каменных Столбов и Озера Хрустального, убивая королевских стражников и подбираясь опасно близко к центру города."},{t="Шрамы великих войн",b="За тихой атмосферой Златоземья скрывается жестокая военная история. Около 75 года до О.П. поселение отразило свирепые нападения во время войны с гноллами. Десятилетия спустя, во время Первой войны, Златоземье и Луноречье стали последними оплотами, павшими под натиском Орочьей Орды: вождь Чернорук отрезал короля Ллейна Ринна I от его владений, а затем разграбил Крепость Штормграда. Город был обращен в пепел и оставался безжизненным вплоть до окончания Второй войны, когда Альянс Лордерона под началом верховного командующего Туралиона выделил средства и организовал его восстановление, чтобы вернуть на родину беженцев-людей, возвращавшихся на юг."}},faq={{q="Кто отвечает за защиту Златоземья?",a="Оборону здесь возглавляет маршал Дугхан из Стражи Штормграда. Из центра города он управляет гарнизоном, но из-за нехватки подкреплений вынужден нанимать вольных искателей приключений для борьбы с угрозами на границе и чудовищами, за которых назначена награда.",al={"who leads goldshire","goldshire marshal","who protects goldshire","кто руководит златоземьем","маршал златоземья","кто защищает златоземье"}},{q="Какие угрозы сейчас нависли над городом?",a="Златоземье осаждено с нескольких сторон: гноллы Речной Лапы совершают набеги на восток, к Гарнизону у Западного ручья, а шайки враждебных мурлоков заполонили водоемы Озера Каменных Столбов и Озера Хрустального. Местные разведчики предупреждают, что без вмешательства стычки могут дойти до улиц деревни.",al={"goldshire problems","why is goldshire in danger","enemies near goldshire","проблемы златоземья","почему златоземью грозит опасность","враги возле златоземья"}},{q="Что случилось со Златоземьем во время Первой войны?",a="Златоземье было одним из двух последних людских городов, павших перед разорением Штормграда. Вождь Чернорук уничтожил его вместе с Луноречьем, чтобы перерезать линии снабжения короля Ллейна, и поселение лежало в руинах, пока его не отстроили после Второй войны.",al={"goldshire first war","did goldshire fall to orcs","goldshire destruction","златоземье первая война","пало ли златоземье перед орками","разрушение златоземья"}},{q="Чем так известна таверна Гордость Льва?",a="Таверна Гордость Льва славится как одна из самых уважаемых и многолюдных таверн Азерота. Она стоит на пересечении нескольких областных трактов и служит главным местом встреч, отдыха и обучения для путников, проходящих через королевство.",al={"lions pride inn","goldshire inn","tavern in goldshire","таверна гордость льва","таверна златоземья","трактир в златоземье"}}},fp="9,343,25.618.0,23.574.0,40.247.0,45.284.0,48.250.0,39.271.0"}
P.entries["subzone:gordok-commons"] = {n="Палаты клана Гордок",s="Палаты клана Гордок — укрепленный северный квартал древних руин высокорожденных в Забытом Городе. Под властью короля Гордока этот обширный каменный комплекс служит средоточием власти элитной касты воинов огров Гордунни.",h="Палаты клана Гордок — укрепленный северный квартал древних руин высокорожденных в Забытом Городе.",kw={"dire maul north","eldre'thalas","gordok","gordok commons","king gordok","knot thimblejack","mizzle","tribute run","север забытого города","эльдре'талас","гордок","палаты клана гордок","король гордок","узелок","мизль","сбор дани"},ang={["profession:Engineering"]="Пленный гоблин Узелок Наперсток полагается на находчивых инженеров и мастеровых в Палатах: они добывают припасы, чинят сломанные ловушки и придумывают хитрые отвлекающие уловки против стражей-огров."},sec={{t="Престол короля огров",b="Некогда аристократическое крыло Эльдре'Таласа, Палаты клана Гордок были осквернены и переделаны под вкусы огров. В величественных колоннах и арочных проходах ночных эльфов теперь расположены оружейные, грубые баррикады и тренировочные площадки Гордока — самых свирепых и дисциплинированных бойцов клана Гордунни. В глубине крыла находится Престол Гордока, где король Гордок правит своими громилами силой и запугиванием."},{t="Закон преемственности",b="Культура Гордока целиком держится на жестоком обычае: прав тот, кто сильнее. По традиции клана тот, кто убьет правящего владыку, получает титул короля Гордока и немедленное повиновение уцелевших капитанов и стражей. Сообразительные чужаки пользуются этим обычаем и прокрадываются мимо помощников короля или обманывают их, не убивая. Если претендент убьет только короля, уцелевшие стражи признают власть победителя и принесут щедрую дань, вместо того чтобы мстить за прежнего правителя."}},faq={{q="Где находятся Палаты клана Гордок?",a="Палаты находятся в северном квартале Забытого Города в Фераласе. Чтобы добраться до них, войдите в обширные руины через Разрушенный общинный квартал и пройдите по огромным каменным коридорам к северному входу.",al={"gordok commons location","where is dire maul north","how to find gordok commons","расположение палат клана гордок","где север забытого города","как найти палаты клана гордок"}},{q="Кто такие огры Гордок?",a="Гордок — элитная каста воинов клана огров Гордунни. В отличие от своих разрозненных диких сородичей в глуши Фераласа, Гордок в Палатах организованы, хорошо вооружены и подчинены строгой военной иерархии под началом короля.",al={"who are the gordok","gordok clan","gordunni elite","кто такие гордок","клан гордок","элита гордунни"}},{q="Как устроена власть огров в Палатах?",a="Власть Гордока решается в бою. Тот, кто убьет правящего короля Гордока, мгновенно получает корону. Когда король падает, остальные огры сдаются и признают победителя законным владыкой.",al={"how to become king of gordok","gordok succession","king gordok lore","как стать королем гордока","преемственность гордока","предания о короле гордоке"}},{q="Почему искатели приключений оставляют стражей-огров в живых?",a="Если чужак доберется до короля Гордока и победит его, не убив его помощников, выжившие командиры подчиняются новому королю. В награду за сдержанность и прямой захват трона новый правитель получает ценную дань от гарнизона.",al={"why tribute run","sparing the guards","gordok tribute lore","почему сбор дани","пощада стражей","предания о дани гордока"}}},fp="14,242,21.464.0,17.535.0,36.205.0,25.258.0,45.204.0,47.271.0"}
P.entries["subzone:gordunni-outpost"] = {n="Поселение Гордунни",s="Поселение Гордунни, расположенное в суровых скалах к северу от Павильона Лорисс, служит укрепленным лагерем грубых огров Гордунни в Фераласе. Разрушительное влияние клана иссушило некогда пышную здешнюю природу, и земля вокруг стала сухой, увядшей и бурой.",h="Поселение Гордунни, расположенное в суровых скалах к северу от Павильона Лорисс, служит укрепленным лагерем...",kw={"bigfist","channeler","feralas","gordunni","hillguard","lariss pavilion","ogre","outpost","tamer","большой кулак","чаротворец","фералас","гордунни","страж холмов","павильон лорисс","огр","поселение","укротитель"},ang={["class:Druid"]="Присутствие Гордунни — тяжкое оскорбление природы: оно превращает плодородный полог джунглей в неестественно иссохшую, бесплодную пустошь."},sec={{t="Оскверненный оплот",b="Поселение Гордунни, вырубленное в северных горах над Павильоном Лорисс, резко выделяется шрамом на фоне пышного полога лесов Фераласа. Где бы ни селились огры Гордунни, их безрассудное обращение с магией и разрушительные привычки высасывают жизненные силы природы, оставляя растения мертвыми, а склоны голыми. Поселение состоит из земляных троп, неглубокой пещеры у входа и большего огрского кургана, уходящего вглубь задних скал. Лагерь патрулируют тяжеловооруженные стражи холмов, хитрые чаротворцы и укротители огров, а еще в нем держат опасные трофеи — в том числе плененного снежного человека по имени Большой Кулак, которого держат в грубом загоне возле глубокого логова."}},faq={{q="Почему земля вокруг этого поселения иссохла?",a="Клан Гордунни тяжело и губительно действует на окружающую среду. Их безрассудное колдовство и разрушительное присутствие истощают природные силы почвы, и обычно пышная зелень джунглей вянет, превращаясь в сухие бурые заросли.",al={"why is it brown","dead grass feralas","ogre corruption","почему все бурое","мертвая трава фераласа","порча от огров"}},{q="Какие огры живут в Поселении Гордунни?",a="Поселение защищают стражи холмов Гордунни, чаротворцы Гордунни, владеющие грубой боевой магией, и укротители Гордунни, которые присматривают за лагерем и плененными зверями.",al={"what mobs are here","gordunni types","who lives here","какие враги здесь","виды гордунни","кто здесь живет"}},{q="Кто такой Большой Кулак?",a="Большой Кулак — огромный снежный человек, которого огры Гордунни держат в плену у входа в заднюю пещеру. Укротители огров держат его связанным как трофей или подопытную добычу.",al={"caged sasquatch","who is bigfist","ogre prisoner","снежный человек в клетке","кто такой большой кулак","пленник огров"}},{q="Где находится Поселение Гордунни?",a="Поселение расположено высоко на горном хребте прямо к северу от Павильона Лорисс в восточном Фераласе.",al={"where is gordunni outpost","outpost location","how to get to gordunni outpost","где поселение гордунни","расположение поселения","как добраться до поселения гордунни"}}},fp="16,279,19.654.0,50.247.0,48.165.0,15.170.0,38.103.0"}
P.entries["subzone:grand-vestibule"] = {n="Главный вестибюль",s="Главный вестибюль — монументальный входной зал Монастыря Алого ордена в Тирисфальских лесах. Он обрамлен багровыми колоннами и каменными изваяниями павших крестоносцев и служит порогом, где искатели приключений готовятся проникнуть во внутренние залы монастыря.",h="Главный вестибюль — монументальный входной зал Монастыря Алого ордена в Тирисфальских лесах.",kw={"entrance hall","grand vestibule","scarlet augur","scarlet disciple","scarlet monastery","scarlet sentry","tirisfal glades","входной зал","главный вестибюль","алый авгур","алый послушник","монастырь алого ордена","алый часовой","тирисфальские леса"},ang={["faction:Alliance"]="Вестибюль показывает трагическое разложение бывших священных обителей Лордерона и то, как преданность Свету обернулась слепым, жестоким фанатизмом.",["race:Undead"]="Этот величественный вход, расположенный к северо-востоку от Подгорода, — передовая линия живых фанатиков, открыто угрожающих власти Отрекшихся в Тирисфале."},sec={{t="Порог фанатизма",b="За тяжелыми внешними вратами монастыря лежит Главный вестибюль — просторный мраморный зал, посвященный воинской гордости Алого ордена. Статуи закованных в доспехи защитников стоят на страже у сводчатых каменных колонн, а ревностные часовые, послушники и авгуры патрулируют плиты пола и сражают всякого, кто посмеет войти без багрового табарда ордена. Для незваных гостей это первое знакомство с неумолимой дисциплиной и фанатизмом ордена."},{t="Спорное место встречи",b="Вестибюль находится прямо перед охраняемыми внутренними крыльями монастыря, поэтому служит опасным местом сбора. Под этими высокими арками сходятся и отряды Альянса, посланные на север, и силы Орды, выдвигающиеся из соседнего Подгорода, и пышный вход превращается в хаотичное кровавое поле битвы задолго до того, как кто-либо проникнет во внутренние кельи."}},faq={{q="Что такое Главный вестибюль?",a="Это главный входной зал Монастыря Алого ордена на северо-востоке Тирисфальских лесов, соединяющий внешний двор с четырьмя внутренними крыльями.",al={"what is this room","grand vestibule info","monastery entrance hall","что это за зал","информация о главном вестибюле","входной зал монастыря"}},{q="Какие враги охраняют эту область?",a="Зал защищают действующие члены Алого ордена, главным образом алые часовые, алые послушники и алые авгуры, поставленные не пускать чужаков.",al={"who patrols here","vestibule mobs","crusaders in vestibule"}},{q="Почему Альянс и Орда сражаются здесь?",a="Обе фракции посылают героев в монастырь: Альянс стремится вернуть святыни Лордерона или очистить их от еретиков, а Орда — закрепить Тирисфальские леса за Отрекшимися. Их пути неизбежно сталкиваются в этом общем входном зале.",al={"pvp in vestibule","why are players fighting here","contested vestibule","pvp в вестибюле","почему здесь сражаются игроки","спорный вестибюль"}},{q="Кого изображают статуи в вестибюле?",a="Статуи изображают почитаемых воинов и героев Алого ордена, высеченных в тяжелых латных доспехах как непреходящие символы их непреклонного похода против нежити.",al={"who are the statues","vestibule statues","crusade monuments","кто эти статуи","статуи вестибюля","памятники ордена"}}},fp="15,255,25.455.0,26.369.0,28.149.0,29.154.0,41.249.0,44.177.0"}
P.entries["subzone:great-forge"] = {n="Великая кузня",s="Великая кузня — огненное сердце дворфийской столицы Стальгорн, давшее ей имя. Она расположена в самом центре города: ее огромные горны и знаменитая Великая наковальня не знают отдыха, создавая легендарное оружие и служа оживленным центром городской жизни.",h="Великая кузня — огненное сердце дворфийской столицы Стальгорн, давшее ей имя.",kw={"ashbringer","foundry","great anvil","great forge","gryth thurden","ironforge","magni bronzebeard","myolor sunderfury","испепелитель","плавильня","великая наковальня","великая кузня","грит турден","стальгорн","магни бронзобород","миолор громовая ярость"},ang={["profession:Blacksmithing"]="Великая наковальня считается лучшим кузнечным местом Альянса: здесь работают высокоуровневые учителя и стоит легендарная наковальня, на которой король Магни выковал Испепелитель.",["race:Dwarf"]="Кузня — основа дворфийской цивилизации под горой: она хранит многовековую традицию кузнечного дела, не давая своему огню погаснуть."},sec={{t="Сердце горы",b="Великая кузня была первым строением, возведенным древними дворфами под горой Стальгорн, и величественная столица выросла вокруг нее концентрическими кольцами. Расплавленный камень и шлак непрерывно стекают из гигантских плавилен в раскаленные желоба, заливая пещеру янтарным сиянием. В центре стоит огромная Великая наковальня, за которой следит Хранитель Великой кузни Миолор Громовая Ярость. Прославленные мастера металла собираются вокруг нее и день и ночь куют доспехи, инструменты и оружие."},{t="Центр Альянса",b="Помимо кузнечного дела, Великая кузня — оживленный перекресток всего горного города. Здесь расположены гильдейские конторы, лавки со снаряжением и главный в городе гриффонов насест, которым заведует Грит Турден. Путешественники со всех уголков Альянса толкутся здесь среди звона молотов."}},faq={{q="Почему город назван в честь этой кузни?",a="Когда дворфы только начали высекать гору, Великая кузня стала первой частью поселения. Подземные залы расходились от этой центральной палаты, и весь горный город назвали Стальгорном в честь исполинского горна в его сердце.",al={"why ironforge named ironforge","city namesake","ironforge origin","почему стальгорн так называется","тезка города","происхождение названия стальгорн"}},{q="Какие знаменитые предметы здесь созданы?",a="На Великой наковальне были созданы исторические шедевры дворфов. Король Магни Бронзобород лично выковал на ней легендарный клинок Испепелитель. Также дворфы изготовили здесь два огромных колокола Альянса: один отправили в дар Лордерону, другой — в Штормград. Кроме того, здесь сделаны древние реликвии, например Боевая булава Орлиного гнезда.",al={"what was made at the great anvil","great forge famous weapons","ashbringer forged here","что создали на великой наковальне","знаменитое оружие великой кузни","испепелитель выкован здесь"}},{q="Кто управляет кузней?",a="Повседневной работой и обслуживанием огромного горна руководит Миолор Громовая Ярость, носящий титул Хранителя Великой кузни.",al={"keeper of the great forge","who runs the forge","хранитель великой кузни","кто управляет кузней"}},{q="Why is it always so crowded here?",a="Кузня расположена в географическом центре Стальгорна и напрямую соединена с внешним кольцом и соседними районами. Здесь находятся важные учителя ремесел, торговые лавки и главный гриффоний насест Стальгорна, поэтому горожане, гонцы и заезжие искатели приключений проходят здесь постоянно.",al={"why so many people at the forge","why is the forge busy","почему в кузне много людей","почему в кузне многолюдно"}}},fp="11,260,21.488.0,19.290.0,39.281.0,42.349.0,23.145.0,33.289.0"}
P.entries["subzone:great-lift"] = {n="Великий Подъемник",s="Великий Подъемник — огромная система лифтов, построенная тауренами на южной окраине Степей. Это главный путь, по которому путешественники и грузы спускаются на сотни футов в отвесную каньонную котловину Тысячи Игл. Несмотря на стратегическую ценность, наступающие с южных пустошей свинобразы все больше осложняют подход к краю.",h="Великий Подъемник — огромная система лифтов, построенная тауренами на южной окраине Степей.",kw={"brave moonhorn","elevator","great lift","grish longrunner","quilboar","the barrens","thousand needles","храбрец лунный рог","лифт","великий подъемник","гриш выносливый гонец","свинобраз","степи","тысяча игл"},ang={["faction:Horde"]="Подъемник — важная артерия Орды, соединяющая центральный Калимдор с отдаленными землями Тысячи Игл и Мерцающей равниной.",["race:Tauren"]="Подъемник из крепких бревен и противовесов показывает изобретательность вашего народа, умеющего преодолевать суровый рельеф, не оставляя шрамов на земле."},sec={{t="Врата из дерева и веревок",b="Великий Подъемник, перекинутый через отвесный обрыв между южными Степями и дном каньона Тысячи Игл, — образец практичной тауренской постройки. Он сделан из тяжелых бревен, плетеных канатов и блоков с противовесами; его парные платформы безопасно перевозят караваны, гонцов и воинов через пропасть, которая сломала бы любую повозку. На верхней и нижней платформах стоят на страже таурены, такие как Храбрец Лунный Рог и Гриш Выносливый Гонец: они сообщают путникам о дороге впереди и следят за грузами."},{t="Опасности у края",b="Работа подъемника становится все опаснее из-за враждебных земель наверху. Агрессивные племена свинобразов южных Степей все дальше расширяются на юг, перекрывая дорогу к подъемнику и грозя полностью отрезать Тысячу Игл от северных троп. Тем, кто идет на юг, приходится постоянно отбиваться от налетчиков из племени Иглошкурых, прежде чем ступить на деревянные платформы."}},faq={{q="Кто построил Великий Подъемник?",a="Великий Подъемник спроектировали и построили таурены, чтобы преодолеть огромный перепад высот между засушливыми плато Степей и глубоким дном каньона Тысячи Игл.",al={"who made the great lift","great lift builders","tauren elevator origin","кто построил великий подъемник","строители великого подъемника","происхождение тауренского лифта"}},{q="Почему добираться до подъемника опасно?",a="Наступающие свинобразы южных Степей агрессивно расширили свою территорию в сторону края плато. Их отряды налетчиков рыщут на подступах и часто досаждают караванам с припасами и гонцам, направляющимся к платформам подъемника, или прямо нападают на них из засады.",al={"why are there quilboar here","southern barrens danger","lift road blocked","почему здесь свинобразы","опасность южных степей","дорога к подъемнику закрыта"}},{q="Кто охраняет Великий Подъемник?",a="Храбрец Лунный Рог и Гриш Выносливый Гонец несут службу у подъемника: следят за дорогами, помогают путникам Орды и присматривают за окрестными землями.",al={"who guards the lift","lift keepers","tauren at the lift","кто охраняет подъемник","стражи подъемника","таурены у подъемника"}},{q="Куда ведет Великий Подъемник?",a="Спуск на платформах приводит путников на дно каньона Тысячи Игл, а подъем ведет прямо в южные Степи.",al={"where does lift go","what is below the lift","lift destination","куда ведет подъемник","что внизу подъемника","пункт назначения подъемника"}}},fp="10,378,35.548.0,18.430.0,25.180.0,39.252.0,32.153.0,31.143.0"}
P.entries["subzone:green-belt"] = {n="Зеленый Пояс",s="Зеленый Пояс — дикая болотистая местность в восточной Болотине, раскинувшаяся под хребтами Грим Батола. Здесь бродят болотные твари, хищные кроколиски и ядовитые слизи, а охраняет ее в основном одинокий ночной эльф Ретиль Страж Природы.",h="Зеленый Пояс — дикая болотистая местность в восточной Болотине, раскинувшаяся под хребтами Грим Батола.",kw={"bog beasts","dragonmaw","green belt","grim batol","oozes","rethiel","wetlands","whelps","болотные твари","драконья пасть","зеленый пояс","грим батол","слизи","ретиль","болотина","дракончики"},ang={["class:Druid"]="Искаженные слизи и неукротимые болотные твари нарушают природную гармонию топи, и этот край вызывает тревогу у хранителей дикой природы.",["race:NightElf"]="Встретить Ретиль Страж Природы одну в болоте Восточных королевств — неожиданное зрелище, напоминающее о Круге Кенария и о том, как ночные эльфы стремятся исцелять дикие земли, где бы те ни находились."},sec={{t="Дикая и спорная топь",b="Зеленый Пояс, протянувшийся через восточную часть Болотины, — одна из диких низин этого сырого края. Местные животные — от огромных кроколисков до подвижных слизей и неуклюжих болотных тварей — делают путь по мшистым водам опасным. В глубине стоит одинокий сторожевой пост, где несет службу Ретиль Страж Природы, одинокий ночной эльф, изучающий экологию топи и сдерживающий ее враждебных обитателей."},{t="Следы Второй войны",b="Среди грязи разбросаны обломки каравана клана Драконьей Пасти, оставленного после страшной битвы у близлежащего Грим Батола. Багровые дракончики до сих пор бродят вокруг сломанных телег и раздавленных клеток — мрачное напоминание о том, как орочий клан порабощал Алекстразу и ее красных драконов."}},faq={{q="Где находится Зеленый Пояс?",a="Зеленый Пояс занимает восточную половину Болотины и тянется по топким низинам между главной дорогой и предгорьями, поднимающимися к Грим Батолу.",al={"green belt location","where is green belt","green belt wetlands map","расположение зеленого пояса","где зеленый пояс","зеленый пояс болотина карта"}},{q="Кто такой Ретиль Страж Природы?",a="Ретиль — загадочный ночной эльф, стоящий на страже в болотах Болотины. Вдали от родного Калимдора он стремится сохранить равновесие природы в трясине и привлекает путников к борьбе с оскверняющими ее тварями и слизями.",al={"who is rethiel","rethiel the greenwarden","night elf in green belt","кто такой ретиль","ретиль страж природы","ночной эльф в зеленом поясе"}},{q="Почему здесь красные дракончики и сломанные повозки?",a="Это остатки обоза с припасами клана Драконьей Пасти, настигнутого последствиями Второй войны, когда орков выбили из Грим Батола, а их власть над красным драконьим родом рухнула.",al={"dragonmaw caravan","why are there whelps in wetlands","red whelps wetlands","караван драконьей пасти","почему в болотине дракончики","красные дракончики болотина"}},{q="Какие угрозы бродят по Зеленому Поясу?",a="Путники в Поясе часто встречают опасных болотных кроколисков, ядовитых слизей и огромных болотных тварей, сливающихся с сырой растительностью.",al={"green belt mobs","dangers in green belt","what monsters live here","монстры зеленого пояса","опасности зеленого пояса","какие монстры здесь живут"}}},fp="10,257,24.450.0,26.309.0,32.154.0,31.227.0,48.190.0,35.171.0"}
P.entries["subzone:greenpaw-village"] = {n="Деревня Зеленой Лапы",s="Деревня Зеленой Лапы — поселение фурболгов в центральном Ясеневом лесу, между Приютом в Ночных Лесах и Приютом Серебряного Ветра. Это главный дом племени Гиблой Чащи, которым правят вождь Мургут и шаман Дубовая Лапа. Охваченная демонической порчей и осаждаемая внешними силами, деревня — очаг конфликта для путников и Альянса, и Орды.",h="Деревня Зеленой Лапы — поселение фурболгов в центральном Ясеневом лесу, между Приютом в Ночных Лесах и...",kw={"ashenvale","foulweald","furbolg","greenpaw village","murgut","oakpaw","raynewood retreat","silverwind refuge","ясеневый лес","гиблая чаща","фурболг","деревня зеленой лапы","мургут","дубовая лапа","приют в ночных лесах","приют серебряного ветра"},ang={["class:Druid"]="В Деревне Зеленой Лапы друиды воочию видят боль древнего медвежьего народа, у которого равновесие природы сменилось необузданным звериным безумием.",["race:NightElf"]="Для ночных эльфов видеть, как племя Гиблой Чащи поддается порче так близко от Приюта в Ночных Лесах и священных лунных колодцев, — трагичное напоминание о не заживших демонических шрамах Ясеневого леса."},sec={{t="Оскверненное поселение",b="Деревня Зеленой Лапы, лежащая к югу от Приюта в Ночных Лесах и к северо-востоку от Приюта Серебряного Ветра, когда-то была тихим домом медвежьих обитателей леса. После Третьей войны ее жители-фурболги, племя Гиблой Чащи, поддались коварной порче, оскверняющей почву и духов Ясеневого леса. Под властью вождя Мургута и их оскверненного духовного наставника, шамана Дубовой Лапы, племя стало враждебным и неуравновешенным и нападает на всех путников, забредших на его лесные земли."},{t="Под перекрестным огнем",b="Из-за неослабной агрессивности и близости к крупным дорогам Деревня Зеленой Лапы вызывает враждебность со всех сторон. Часовые Альянса и ночные эльфы-друиды стремятся истребить безумных фурболгов, защищая ближние форпосты и священные лунные колодцы. В то же время силы Орды, продвигаясь по Ясеневому лесу, вели кровавые стычки с племенем Гиблой Чащи, пока обе стороны пробивались через древний лес."}},faq={{q="Где находится Деревня Зеленой Лапы?",a="Деревня Зеленой Лапы лежит в центральном Ясеневом лесу, прямо к югу от Приюта в Ночных Лесах, к северо-востоку от Приюта Серебряного Ветра и чуть северо-западнее южного лунного колодца.",al={"greenpaw location","where is greenpaw village","find greenpaw","где зеленая лапа","где деревня зеленой лапы","найти деревню зеленой лапы"}},{q="Кто живет в Деревне Зеленой Лапы?",a="Поселение населяет племя фурболгов Гиблой Чащи, которым правят вождь Мургут и их оскверненный духовный советник, шаман Дубовая Лапа.",al={"who is here","greenpaw mobs","greenpaw furbolgs","кто здесь","монстры деревни зеленой лапы","фурболги зеленой лапы"}},{q="Почему фурболги Деревни Зеленой Лапы враждебны?",a="Как и многие племена фурболгов северного Калимдора, племя Гиблой Чащи пало жертвой демонической порчи, оставшейся после вторжения Пылающего Легиона в Ясеневый лес, и ярость помутила их разум.",al={"why are furbolgs mad","are greenpaw furbolgs corrupt","почему фурболги безумны","оскверненные ли фурболги зеленой лапы"}},{q="Почему Альянс и Орда сражаются здесь?",a="Обе стороны считают агрессивное племя Гиблой Чащи угрозой своим дорогам и поселениям. Ночные эльфы стремятся исцелить или сдержать безумие возле своих лунных колодцев, а силы Орды сталкиваются с фурболгами, продвигаясь по Ясеневому лесу.",al={"greenpaw quests","who attacks greenpaw","задания зеленой лапы","кто нападает на зеленую лапу"}}},fp="16,367,22.495.0,24.405.0,34.157.0,30.152.0,49.210.0,45.239.0"}
P.entries["subzone:greymane-wall"] = {n="Стена Седогрива",s="Стена Седогрива — громадный каменный оплот, протянувшийся вдоль южной границы Серебряного бора. Возведенная королем Генном Седогривом после Второй войны, она отгораживает королевство Гилнеас от внешнего мира неприступными запертыми воротами.",h="Стена Седогрива — громадный каменный оплот, протянувшийся вдоль южной границы Серебряного бора.",kw={"arugal","darius crowley","genn greymane","gilneas","greymane wall","pyrewood","silverpine","аругал","дариус кроули","дженн седогрив","гилнеас","стена седогрива","деревня погребальных костров","серебряный бор"},ang={["faction:Alliance"]="Стена Седогрива — горькое напоминание о предательстве Гилнеаса. Когда Лордерон пал перед Плетью, Седогрив остался глух к бывшим союзникам и бросил их погибать у своих ворот.",["faction:Horde"]="Для Отрекшихся, занявших Серебряный бор, стена образует непроходимую южную границу, скрывающую человеческое королевство, чьи намерения и внутренняя сила остаются совершенно неизвестными."},sec={{t="Памятник изоляции",b="После Второй войны король Генн Седогрив затаил обиду на Альянс Лордерона, особенно из-за налогов на содержание лагерей для орков и строительство Крепости Стражей Пустоты. Решив, что Гилнеас отдал достаточно золота и крови за чужие беды, Седогрив вышел из Альянса и приказал возвести колоссальную преграду поперек начала полуострова. Тем самым он бросил земли лорда Дариуса Кроули, включая Деревню Погребальных Костров и Янтарную мельницу, оставив их по северную сторону стены. Когда Третья война принесла Чуму нежизни и бесчисленных отчаявшихся беженцев к подножию стены, ворота остались безжалостно запертыми."},{t="Цена уединения",b="Хотя стена уберегла полуостров от армий Плети, безопасность обошлась дорого. Гилнеасские войска ненадолго открыли ворота во время войны, чтобы сражаться с нежитью, но были разгромлены. В отчаянии король Седогрив приказал верховному магу Аругалу призвать диких воргенов. Звери отбросили Плеть, но обратились против призвавших. Солдаты Седогрива отступили и снова заперли ворота, однако зараженные бойцы принесли звериную заразу внутрь. За холодной безмолвной стеной внутренний мятеж и подкрадывающееся проклятие разрывают изолированное королевство."}},faq={{q="Что находится за Стеной Седогрива?",a="За стеной лежит полуостровное королевство Гилнеас. Им правит король Генн Седогрив, который до Третьей войны полностью изолировал страну от Лордерона и остального мира, прекратив всякую торговлю и связь.",al={"what is behind the wall","where does greymane wall lead","what kingdom is behind the wall","что за стеной","куда ведет стена седогрива","какое королевство за стеной"}},{q="Можно ли открыть ворота Стены Седогрива?",a="Нет. Массивная решетка и окованные железом двери надежно заперты с южной стороны. Гилнеас прервал все контакты с внешним миром, и никто не входит и не выходит.",al={"how to get past greymane wall","can you open greymane wall","open the gate","как пройти за стену седогрива","можно ли открыть стену седогрива","открыть ворота"}},{q="Почему стену построили здесь, а не южнее?",a="Стена использовала окружающую горную местность как природную преграду. Строительство вдоль этого хребта вынудило королевство бросить северные владения лорда Дариуса Кроули, включая Деревню Погребальных Костров и Янтарную мельницу, и посеяло жестокий раздор внутри Гилнеаса.",al={"why did they build it here","why cut off pyrewood","crowley lands cut off","почему построили здесь","почему отрезали деревню погребальных костров","земли кроули отрезаны"}},{q="Что стало с беженцами, бежавшими сюда во время Третьей войны?",a="Когда Плеть опустошала Лордерон, толпы бегущих людей-беженцев собрались у стены, моля о впуске. Король Седогрив отказался отпереть ворота, защищая свое королевство, и отчаявшихся беженцев в конце концов перебила нежить снаружи.",al={"scourge refugees wall","refugees outside greymane wall","плеть беженцы стена","беженцы у стены седогрива"}}},fp="13,242,23.673.0,22.617.1,35.216.0,44.176.0,53.268.0,65.257.0"}
P.entries["subzone:grim-batol"] = {n="Грим Батол",s="Грим Батол — древняя разрушенная горная крепость дворфов, нависающая над восточным краем Болотины. Построенная кланом Громового Молота, оставленная после темного проклятия во время Войны трех молотов, а позднее занятая орками Драконьей Пасти как логово для разведения драконов, она с запечатанными вратами остается зловещим пятном на нагорье.",h="Грим Батол — древняя разрушенная горная крепость дворфов, нависающая над восточным краем Болотины.",kw={"alexstrasza","demon soul","dragonmaw","grim batol","modgud","nekros","wetlands","wildhammer","алекстраза","душа демона","драконья пасть","грим батол","модгуд","некрос","болотина","громовой молот"},ang={["faction:Horde"]="Гора олицетворяет мрачные высоты Второй войны, когда клан Драконьей Пасти подчинил порабощенных драконов, чтобы завоевать небеса, прежде чем потерпел жестокий крах.",["race:Dwarf"]="Для дворфов Грим Батол — горькое свидетельство Войны трех молотов: некогда гордый город-побратим Стальгорна, навсегда ставший непригодным для жизни из-за колдовства Черного Железа."},sec={{t="Дважды проклятая крепость",b="После древней междоусобной войны трех кланов тан Хардрос Громовой Молот вырубил Грим Батол в неровных горах к востоку от болот. Во время Войны трех молотов колдунья Черного Железа Модгуд осадила крепость. Хардрос сразил ее, но перед смертью Модгуд навлекла на камни злую тень. Остаточная порча сделала залы непригодными для жизни, и уцелевшие дворфы Громового Молота покинули великолепное королевство и ушли на север, во Внутренние земли."},{t="Цепи Королевы драконов",b="Столетия спустя, во время Второй войны, у крепости появилось более мрачное назначение: Оргрим Молот Рока отправил клан Драконьей Пасти занять ее. Под началом чернокнижника Некроса Черепокола орки с помощью древнего артефакта, Души демона, поработили красную Королеву драконов Алекстразу в глубинах горы. Ей пришлось выводить потомство для военных нужд Орды, и она оставалась в цепях, пока небольшой отряд героев не разбил артефакт. Освободившись, разъяренный Аспект драконов испепелил орков внутри, оставив Грим Батол тлеющими пустынными руинами под пристальным наблюдением уцелевших красных драконов."}},faq={{q="Можно ли игрокам войти в Грим Батол?",a="Нет. Колоссальные каменные врата в конце горной дороги надежно заперты и недоступны для путников. Посетить можно только внушительные врата и внешние укрепления в восточных горах Болотины.",al={"can i go inside grim batol","is grim batol open","grim batol gate","можно ли войти в грим батол","открыт ли грим батол","врата грим батола"}},{q="Почему дворфы Громового Молота покинули его?",a="Во время Войны трех молотов колдунья Черного Железа Модгуд наложила на твердыню мерзкое теневое проклятие, прежде чем была убита. Оставшаяся порча сделала крепость непригодной для жизни Громовых Молотов, и они ушли, построив Заоблачный Пик во Внутренних землях.",al={"why did dwarves leave grim batol","wildhammer curse","modgud curse","почему дворфы покинули грим батол","проклятие громового молота","проклятие модгуд"}},{q="Что стало с орками Драконьей Пасти, жившими здесь?",a="Когда маг Ронин и его спутники разбили Душу демона, плененная Королева драконов Алекстраза освободилась от цепей. Разъяренные жестоким пленом, она и ее потомство испепелили Некроса Черепокола и разгромили Драконью Пасть в крепости.",al={"dragonmaw grim batol","what happened to the orcs here","nekros skullcrusher","драконья пасть грим батол","что стало с орками","некрос черепокол"}},{q="Кто сейчас контролирует Грим Батол?",a="Сейчас Грим Батол — заброшенные руины. Хотя остатки клана Драконьей Пасти и дикие звери еще обитают в окрестных скалах, Красный драконий род бдительно следит за проклятой горой, чтобы ее мрачная история не повторилась.",al={"who owns grim batol","who lives in grim batol now","кто владеет грим батолом","кто живет в грим батоле сейчас"}}},fp="10,331,23.518.0,26.609.0,29.218.0,42.280.0,51.264.0,34.242.0"}
P.entries["subzone:grimesilt-dig-site"] = {n="Карьер Грязнули",s="Карьер Грязнули — археологические раскопки в Тлеющем ущелье, начатые дворфами Стальгорна. Захваченный враждебными дворфами Черного Железа, карьер теперь прочно под контролем врага, а уцелевшие участники первоначальной экспедиции пытаются выжить в укрытии.",h="Карьер Грязнули — археологические раскопки в Тлеющем ущелье, начатые дворфами Стальгорна.",kw={"archaeology","dark iron","dorius stonetender","excavation","grimesilt dig site","ironforge","searing gorge","археология","черное железо","дориус хранитель камня","раскопки","карьер грязнули","стальгорн","тлеющее ущелье"},ang={["faction:Alliance"]="Карьер олицетворяет начинание Стальгорна, безжалостно сорванное дворфами Черного Железа: осажденные подданные Альянса ждут эвакуации на опасной территории.",["race:Dwarf"]="Для дворфов Бронзобородов Карьер Грязнули — горькое напоминание об угрозе Черного Железа прямо за горами и об опасностях, грозящих дворфийским древностям и археологам во враждебных землях."},sec={{t="Спорные раскопки",b="Расположенный в покрытых сажей бесплодных землях Тлеющего ущелья, Карьер Грязнули начинался как экспедиция, одобренная учеными Стальгорна, искавшими реликвии под скалами. Предприятие жестоко оборвалось, когда местные дворфы Черного Железа прогнали землекопов и присвоили оборудование. Сегодня котлован кишит стражами Черного Железа, а раненые и разрозненные выжившие из первоначальной стальгорнской команды заперты в карьере и вокруг него."}},faq={{q="Кто изначально основал Карьер Грязнули?",a="Раскопки начали дворфы Бронзобороды из Стальгорна. Их отряд отправили извлечь древние артефакты из-под Тлеющего ущелья, но на него напали и вытеснили.",al={"who dug grimesilt","who made grimesilt dig site","grimesilt founders","кто копал карьер грязнули","кто основал карьер грязнули","основатели карьера грязнули"}},{q="Кто сейчас контролирует раскопки?",a="Раскопки захватил клан Черного Железа. Сейчас он занимает котлованы и охраняет оставшиеся инструменты и территорию от любых попыток Стальгорна вернуть эти земли.",al={"who owns grimesilt","grimesilt enemies","who is at grimesilt","кто владеет карьером грязнули","враги в карьере грязнули","кто в карьере грязнули"}},{q="Остались ли выжившие из первоначальной команды?",a="Да. Несколько рабочих сумели выжить, в том числе раненый землекоп Дориус Хранитель Камня, лежащий у дна котлована, и еще один несчастный товарищ, прячущийся в ближайшем нужнике.",al={"survivors at grimesilt","dorius stonetender","who is trapped at grimesilt","выжившие в карьере грязнули","дориус хранитель камня","кто заперт в карьере грязнули"}}},fp="18,279,22.463.0,50.183.0,30.171.0,47.184.0"}
P.entries["subzone:grimtotem-compound"] = {n="Лагерь Зловещего Тотема",s="Лагерь Зловещего Тотема — укрепленное племенное поселение в глубине дебрей Фераласа, к востоку от эльфийских руин Забытого Города. Лагерь занимает агрессивный и замкнутый клан Зловещего Тотема и использует его как базу для таинственных и разрушительных действий в регионе.",h="Лагерь Зловещего Тотема — укрепленное племенное поселение в глубине дебрей Фераласа, к востоку от эльфийских...",kw={"compound","dire maul","feralas","gnolls","grimtotem","sprite darter","tauren","лагерь","забытый город","фералас","гноллы","зловещий тотем","мотылек-фея","таурены"},ang={["faction:Alliance"]="Зловещий Тотем неустанно враждебен ночным эльфам и их союзникам, и это поселение становится опасной преградой в сердце Фераласа.",["race:Tauren"]="Клан Зловещего Тотема лишь для вида почитает Кэрна Кровавого Копыта, но такие места, как этот лагерь, раскрывают его истинные необузданные амбиции вдали от бдительных глаз Громового Утеса."},sec={{t="Оплот Черного племени",b="Лагерь Зловещего Тотема состоит из двух стоянок к востоку от Забытого Города и дает клану Зловещего Тотема прочный плацдарм в Фераласе. В отличие от таурен, союзных Кэрну Кровавому Копыту в Громовом Утесе, Зловещий Тотем здесь действует независимо и враждебно к чужакам. В южной части поселения они держат пойманных мотыльков-фей в большой деревянной клетке для своих темных целей, а по северной окраине бродят дикие гноллы."}},faq={{q="Кто живет в Лагере Зловещего Тотема?",a="Поселение принадлежит клану Зловещего Тотема — агрессивному и скрытному племени таурен, известному ксенофобией и жестокими методами. Оно действует отдельно от племен Мулгора, союзных Орде.",al={"who is here","grimtotem compound mobs","who controls grimtotem compound","кто здесь","мобы лагеря зловещего тотема","кто контролирует лагерь зловещего тотема"}},{q="Почему в лагере в клетках сидят мотыльки-феи?",a="Зловещий Тотем поймал местных мотыльков-фей и запер их в огромной клетке в южной деревне. Их интерес к этим волшебным существам, по-видимому, связан с темными опытами и использованием природной магической сущности Фераласа.",al={"why are faerie dragons caged","caged sprite darters","grimtotem sprite darters","почему феи в клетках","пойманные мотыльки-феи","мотыльки-феи зловещего тотема"}},{q="Где находится Лагерь Зловещего Тотема?",a="Лагерь расположен в центральной части Фераласа, к востоку от древних руин высокорожденных в Забытом Городе, а к северо-востоку неподалеку стоят лагерем дикие стаи гноллов.",al={"grimtotem compound location","where is grimtotem compound","где лагерь зловещего тотема","расположение лагеря зловещего тотема"}}},fp="18,289,28.475.0,36.203.0,45.238.0,40.153.0"}
P.entries["subzone:grizzled-den"] = {n="Серая берлога",s="Серая берлога — пещера в заснеженных холмах к юго-западу от Караноса. Это известное логово свирепых морозных вендиго, обитающих в Дун Мороге.",h="Серая берлога — пещера в заснеженных холмах к юго-западу от Караноса.",kw={"cave","dun morogh","frost","grizzled den","kharanos","wendigo","пещера","дун морог","мороз","серая берлога","каранос","вендиго"},ang={["profession:Mining"]="Во внешних и внутренних туннелях берлоги есть открытые залежи меди, так что это удобное место для ранней добычи, если вы сумеете отбиться от вендиго.",["race:Dwarf"]="Зачистка Серой берлоги — почти обряд посвящения для юных дворфов-горцев, тренирующихся возле Караноса."},sec={{t="Ледяное логово",b="Глубоко врезанная в скалы к юго-западу от Караноса, Серая берлога известна местным горцам как место гнездования стай вендиго Дун Морога. Эти агрессивные обезьяноподобные звери дышат морозом на незваных гостей и сбиваются в стаи, защищая свои логова. Несмотря на опасность, смелые охотники регулярно спускаются вглубь пещеры за густой гривой вендиго, которая хорошо стоит у мастеров, обивающих холодные кресла и сиденья экипажей утепленным мехом."},{t="Скрытые сокровища",b="Помимо грозных обитателей, извилистые туннели Серой берлоги привлекают искателей наживы, ищущих природные богатства. Старатели часто проходят за внешний вход, чтобы выбивать медные жилы из промерзших каменных стен, а отважные разведчики обшаривают темные углы в поисках брошенных сундуков. Но если зайти слишком глубоко, вы неизбежно встретите самых крупных и свирепых хищников берлоги, затаившихся во мраке."}},faq={{q="Где находится Серая берлога?",a="Серая берлога находится к юго-западу от Караноса в Дун Мороге, укрытая среди заснеженных горных хребтов.",al={"grizzled den location","where is grizzled den","how to get to grizzled den","где серая берлога","расположение серой берлоги","как добраться до серой берлоги"}},{q="Какие существа обитают в Серой берлоге?",a="Пещеру заполонили стаи свирепых вендиго. Эти агрессивные белошерстные звери могут выдыхать леденящий мороз и охотно набрасываются на любого чужака.",al={"what is in grizzled den","grizzled den mobs","creatures inside grizzled den","что в серой берлоге","монстры серой берлоги","существа в серой берлоге"}},{q="Зачем люди отправляются в Серую берлогу?",a="Охотники и искатели приключений идут в берлогу главным образом ради грив вендиго, высоко ценимых для изготовления теплых чехлов на сиденья. Другие спускаются в промерзшие туннели добывать медную руду из стен пещеры.",al={"why go to grizzled den","grizzled den quests","wendigo manes","зачем идти в серую берлогу","задания серой берлоги","гривы вендиго"}}},fp="12,183,20.488.0,16.464.0,34.113.0,40.158.0,44.225.0"}
P.entries["subzone:grizzlepaw-ridge"] = {n="Хребет Седых Лап",s="Хребет Седых Лап — суровый скалистый склон к югу от Телсамара в Лок Модане. Среди местных горцев он известен густой популяцией диких медведей, которых возглавляет легендарный зверь старина Черношкур.",h="Хребет Седых Лап — суровый скалистый склон к югу от Телсамара в Лок Модане.",kw={"bears","grizzlepaw ridge","loch modan","ol' sooty","sooty","thelsamar","медведи","хребет седых лап","лок модан","старина черношкур","черношкур","телсамар"},ang={["class:Hunter"]="Хребет — классическое место для выслеживания диких зверей и схватки с главными хищниками, такими как старина Черношкур.",["race:Dwarf"]="Хребет расположен рядом с Телсамаром, и медведи на нем постоянно досаждают местным горцам и мешают снабжению."},sec={{t="Обитель медведей",b="Хребет Седых Лап нависает над дорогой к югу от Телсамара и граничит на западе с Долиной Камнедробов. Это суровая местность, где господствуют хищные звери. Склоны заняты медведями, охраняющими свои владения и опасными для путников, идущих вдоль гор. В глубине хребта обитает старина Черношкур — огромный и необычайно свирепый медведь, которого боятся местные охотники. Путникам, идущим между поселениями дворфов, нужно внимательно следить за опушкой леса и скалистыми уступами наверху."}},faq={{q="Где находится Хребет Седых Лап?",a="Хребет Седых Лап лежит в центральных холмах Лок Модана, прямо к югу от поселка Телсамар и к востоку от Долины Камнедробов, кишащей троггами.",al={"where is grizzlepaw ridge","grizzlepaw ridge location","how to get to grizzlepaw ridge","где хребет седых лап","расположение хребта седых лап","как добраться до хребта седых лап"}},{q="Какие опасные существа обитают на Хребте Седых Лап?",a="Хребет кишит агрессивными медведями. Самый известный из них — старина Черношкур, исключительно крупный и свирепый зверь, который порой спускается к подножию горы.",al={"bears at grizzlepaw ridge","who is ol sooty","ol sooty loch modan","медведи хребта седых лап","кто такой старина черношкур","старина черношкур лок модан"}}},fp="16,205,17.468.0,34.150.0,50.184.0"}
P.entries["subzone:grol-dom-farm"] = {n="Ферма Гроль'дома",s="Ферма Гроль'дома — скромное орочье хозяйство в северных Степях, у дороги между Дуротаром и Перекрестком. Ферма, где живут Кранал Фисс с семьей, разводит свиней на засушливых равнинах, несмотря на постоянные набеги агрессивных местных свинобразов.",h="Ферма Гроль'дома — скромное орочье хозяйство в северных Степях, у дороги между Дуротаром и Перекрестком.",kw={"barrens","fire totem","grol'dom farm","groldom","kranal fiss","pig farm","razormane","swine","степи","тотем огня","ферма гроль'дома","гроль'дом","кранал фисс","свиноферма","иглогривые","свиньи"},ang={["class:Shaman"]="Для посвященных, идущих путем стихий, Ферма Гроль'дома — важная веха: здесь Кранал Фисс проведет вас через опасные обряды, необходимые для общения с духами огня.",["faction:Horde"]="Хозяйства вроде Фермы Гроль'дома показывают стойкость первых поселенцев Орды, пытавшихся построить устойчивую жизнь в суровых диких Степях."},sec={{t="Свиноферма в саванне",b="Ферма Гроль'дома появилась после заселения Дуротара и отражает первые попытки Орды возделывать сухие просторы Степей. Небольшим хозяйством занимаются орк Кранал Фисс и его дети. Здесь в основном разводят свиней, терпя суровую природу и набеги свинобразов из племени Иглогривых, рыскающих на соседних кряжах. Это одинокий суровый форпост, поставляющий необходимую пищу зарождающейся орочьей нации."},{t="Маяк для юных шаманов",b="Помимо обыденной роли свинофермы, это хозяйство тихо важно для посвященных Орды, идущих духовным путем. Кранал Фисс глубоко знает обряды стихий и играет ключевую роль в наставлении юных шаманов на их испытаниях. Искателей, идущих на запад от Оргриммара, регулярно направляют на эту скромную ферму, чтобы постичь тайны общения с первобытными духами огня."}},faq={{q="Что такое Ферма Гроль'дома?",a="Ферма Гроль'дома — орочья свиноферма в северных Степях. Основанная после возникновения Оргриммара, она служит отдаленным хозяйством, где трудятся орк Кранал Фисс и его дети.",al={"groldom farm info","what is this place barrens","orc pig farm","ферма гроль'дома","что это за место степи","орочья свиноферма"}},{q="Кто живет на Ферме Гроль'дома?",a="Ферму содержит орк по имени Кранал Фисс вместе с детьми. Вместе они ухаживают за загонами, пасут свиней и защищают свой скудный достаток от бродячих зверей и набегов свинобразов.",al={"who is at groldom farm","who lives here","kranal fiss home","кто на ферме гроль'дома","кто здесь живет","кранал фисс дом"}},{q="Почему шаманы приходят на Ферму Гроль'дома?",a="Кранал Фисс знает обряды стихий. Орков и тауренов-шаманов обычно посылают к нему в начале обучения, чтобы они прошли испытания, необходимые для получения Зова Огня и призыва Тотема огня.",al={"shaman fire quest","why come to groldom","kranal fiss shaman","задание шамана на огонь","зачем идти на ферму гроль'дома","кранал фисс шаман"}},{q="Какие опасности грозят ферме?",a="Окрестная саванна кишит свинобразами из племени Иглогривых. Эти агрессивные налетчики постоянно досаждают ферме, угрожая скоту и семье Кранала.",al={"why are there quillboars","who attacks groldom","farm enemies","откуда свинобразы","кто нападает на ферму гроль'дома","враги фермы"}}},fp="13,270,28.428.0,25.401.0,22.195.0,27.199.0,37.222.0,27.188.0"}
P.entries["subzone:grom-gol-base-camp"] = {n="Лагерь Гром'гол",s="Лагерь Гром'гол — главный укрепленный форпост Орды в Тернистой долине, расположенный на северном побережье. Поселением командует командир Агро'гош; оно обеспечивает важный плацдарм и линию снабжения на юге Восточных королевств. Благодаря дирижабельным башням с прямым сообщением с Оргриммаром и Подгородом лагерь служит военной базой против местных племен троллей джунглей и враждебных сил Альянса.",h="Лагерь Гром'гол — главный укрепленный форпост Орды в Тернистой долине, расположенный на северном побережье.",kw={"aggro'gosh","grom'gol","gromgol","orgrimmar","stonard","stranglethorn","undercity","zeppelin","агро'гош","гром'гол","оргриммар","каменор","тернистая долина","подгород","дирижабль"},ang={["faction:Alliance"]="Гром'гол — сильно защищенный вражеский бастион, дающий Орде плацдарм и быстрый доступ по дирижаблям в глубь земель, соседних с югом Лордерона.",["faction:Horde"]="Гром'гол — главное безопасное убежище и снабженческая база для искателей приключений Орды, пробирающихся по коварным джунглям и спорным дорогам Тернистой долины."},sec={{t="Бастион в джунглях",b="Carved into the dense jungle of northwestern Stranglethorn Vale, Grom'gol Base Camp is a fortified military bastion commanded by Commander Aggro'gosh. Ringed by defensive palisades and heavily armed grunts, the base camp endures non-stop harassment from Bloodscalp headhunters, lurking naga, and prowling beasts. Despite these threats, its vital strategic location secures safe supply routes north toward Stonard in the Swamp of Sorrows while keeping a watchful eye on Alliance traffic descending from Duskwood or traveling up from Booty Bay."},{t="Воздушный мост Орды",b="Заметные деревянные дирижабельные башни Гром'гола — один из важнейших логистических узлов Восточных королевств. Гоблинские летательные аппараты, пришвартованные здесь, регулярно летают прямо в столицы — Оргриммар и Подгород. Этот непрерывный воздушный мост позволяет силам Орды быстро доставлять подкрепления и ресурсы в самое сердце Тернистой долины, минуя дороги под властью Альянса и открытое море."}},faq={{q="Для чего нужен Лагерь Гром'гол?",a="Гром'гол служит укрепленным военным плацдармом Орды в Тернистой долине. Под командованием командира Агро'гоша он создает линию снабжения к форпосту Каменор в Болоте Печали и защищает интересы Орды от враждебных троллей джунглей и вторжений Альянса.",al={"why is gromgol here","gromgol purpose","what is gromgol","зачем нужен гром'гол","назначение гром'гола","что такое гром'гол"}},{q="Как добраться до Гром'гола и обратно?",a="В Гром'голе стоят крупные дирижабельные башни с прямыми рейсами в Оргриммар в Калимдоре и в Подгород в Тирисфальских лесах. Здесь также есть насест для летучих мышей и наездников на ветрокрылах, связанный с сетью полетов между Каргатом, Каменором и Пиратской бухтой.",al={"gromgol zeppelin","gromgol flight paths","how to get to gromgol","дирижабль гром'гол","маршруты полетов гром'гол","как добраться до гром'гола"}},{q="Кто командует Лагерем Гром'гол?",a="Форпостом командует орк командир Агро'гош, который отвечает за оборону частокола от враждебных племен троллей, диких ящеров и разведчиков Альянса.",al={"gromgol leader","who runs gromgol","commander of gromgol","глава гром'гола","кто управляет гром'голом","командир гром'гола"}},{q="Какие угрозы нависают над лагерем?",a="Гром'гол окружен опасными противниками со всех сторон. Тролли джунглей племени Кровавого Скальпа охотятся у его границ, дикие ящеры бродят по полям на севере, а солдаты Альянса постоянно приходят из Сумеречного леса или от порта Пиратская бухта.",al={"gromgol enemies","who attacks gromgol","враги гром'гола","кто нападает на гром'гол"}}},fp="18,418,23.542.0,22.430.0,42.300.0,39.253.0,29.177.0,32.262.0"}
P.entries["subzone:grommash-hold"] = {n="Крепость Громмаш",s="Крепость Громмаш — укрепленная резиденция вождя Тралла, высоко в красных скалах Аллеи Мудрости в Оргриммаре. Названная в честь жертвы Громмаша Адского Крика, крепость служит командным центром и политическим сердцем новой Орды.",h="Крепость Громмаш — укрепленная резиденция вождя Тралла, высоко в красных скалах Аллеи Мудрости в Оргриммаре.",kw={"eitrigg","grommash hold","mannoroth","orgrimmar","thrall","thrall's fortress","valley of wisdom","эйтригг","крепость громмаш","маннорот","оргриммар","тралл","крепость тралла","аллея мудрости"},ang={["faction:Horde"]="Это само сердце суверенитета Орды, где заключаются договоры и направляются походы против угроз по всему Калимдору и Восточным королевствам.",["race:Orc"]="Для орков крепость и останки Маннорота у ее входа — величайшее свидетельство освобождения от демонического проклятия крови благодаря жертве Грома Адского Крика."},sec={{t="Резиденция Вождя",b="Крепость Громмаш, расположенная в безмятежной Аллее Мудрости, служит королевским двором и стратегическим убежищем Орды. Ее толстые каменные стены встроены в высокие стены каньона, и внутри заметно сумрачно и прохладно — вождь Тралл намеренно сделал так, чтобы посланники, просители и военачальники во время приемов оставались собранными и трезвыми. Здесь Тралл размышляет об обороне Калимдора; ему помогают опытные советники вроде Эйтригга, а навещают его вожди народов, такие как Вол'джин."},{t="Памятник свободе",b="Сразу за крепостью, на стволе древнего дерева, закреплены разбитые доспехи и рогатый череп властителя преисподней Маннорота. Они размещены в честь Грома Адского Крика, отдавшего жизнь, чтобы убить демона в Ясеневом лесу. Этот памятник — гордый символ освобождения орков от демонического проклятия крови и вечное суровое предостережение не впадать вновь в безрассудную дикость."}},faq={{q="Кто находится в Крепости Громмаш?",a="Вождь Тралл вершит здесь суд вместе с ключевыми вождями и советниками Орды, среди которых орочий старейшина Эйтригг, предводитель племени Черного Копья Вол'джин и воин Назгрел.",al={"who is in the hold","who lives in grommash hold","who rules here","кто в крепости","кто живет в крепости громмаш","кто здесь правит"}},{q="Почему она называется Крепость Громмаш?",a="Она названа в честь Громмаша «Грома» Адского Крика, легендарного вождя клана Песни Войны. Гром убил властителя преисподней Маннорота во время Третьей войны, заплатив жизнью за то, чтобы навсегда освободить орков от демонического рабства.",al={"why grommash hold","who was grommash","named after who","почему крепость громмаш","кто такой громмаш","в честь кого названа"}},{q="Что за гигантские кости выставлены снаружи?",a="Череп и доспехи принадлежат Маннороту, повелителю демонов, чья кровь поработила орков в Дреноре. Останки доставили из Ясеневого леса и закрепили на стволе дерева у крепости как памятник свободе Орды.",al={"demon skull outside","mannoroth skull","bones in front","демонический череп снаружи","череп маннорота","кости перед входом"}},{q="Почему на городских указателях ее называют Крепостью Тралла?",a="Многие орочьи стражи и старые указатели до сих пор называют это строение Крепостью Тралла — по имени Вождя, который вершит в ней суд.",al={"thrall's fortress","thralls fortress","hold vs fortress","крепость тралла","замок тралла","крепость или цитадель"}}},fp="13,255,24.481.0,23.405.0,28.165.0,30.233.0,43.229.0,49.140.0"}
P.entries["subzone:grove-of-the-ancients"] = {n="Роща Древних",s="Роща Древних — священное убежище ночных эльфов среди развалин старого храма на юго-востоке Темных берегов. Эта тихая обитель у Петляющей реки служит местом сбора лесных духов, и за ней присматривает почтенное Древо Мудрости Ону.",h="Роща Древних — священное убежище ночных эльфов среди развалин старого храма на юго-востоке Темных берегов.",kw={"ancient of lore","circle of ancients","darkshore","grove of the ancients","onu","wildbend river","древо мудрости","круг древних","темные берега","роща древних","ону","петляющая река"},ang={["class:Druid"]="Роща — почитаемое природное святилище, дающее друидам прямую связь с мудростью Древа Мудрости Ону и духами леса.",["race:NightElf"]="Окруженная древними развалинами храма и охраняемая лесными духами, роща остается торжественным напоминанием о давней гармонии кальдораев с землей."},sec={{t="Убежище Петляющей реки",b="Роща Древних, укрытая у юго-восточных гор Темных берегов, — мирная обитель среди древних храмовых камней. Через ее сердце течет бурная Петляющая река, дающая тихое прибежище на побережье, все сильнее страдающем от порчи и беспокойных зверей. Роща служит местом встреч Круга Древних, где лесные духи и кальдораи поддерживают хрупкое равновесие леса."},{t="Хранители и стражи",b="Главная фигура рощи — Ону, величественное Древо Мудрости, наблюдающее за переменами судьбы этой земли и делящееся древней мудростью с путниками. Рядом с Ону находят покой странствующие торговцы и спящие друиды под сенью ветвей. Хотя здесь тихо, роща расположена близко к лагерям воинственных фурболгов на юго-востоке, поэтому она — важный пограничный форпост для часовых и друидов Альянса, следящих за югом Темных берегов."}},faq={{q="Где находится Роща Древних?",a="Роща расположена в юго-восточной части Темных берегов, у подножия гор, возле берегов Петляющей реки.",al={"grove of ancients location","where is grove of the ancients","onu location","расположение рощи древних","где роща древних","где ону"}},{q="Кто такой Ону?",a="Ону — Древо Мудрости, обитающее в роще. Он выступает старейшиной-наставником, наблюдает за юго-восточными лесами и советует друидам и путникам, пытающимся восстановить равновесие Темных берегов.",al={"who is onu","ancient in grove of ancients","tree guy darkshore","кто такой ону","древень в роще древних","говорящее дерево темные берега"}},{q="Что такое Круг Древних?",a="Круг Древних — собрание могущественных лесных духов и вековых древней, которые собираются в роще, чтобы общаться, делиться знаниями и обсуждать благополучие диких земель.",al={"circle of ancients","ancients meeting darkshore","круг древних","собрание древних темные берега"}},{q="Есть ли опасности возле рощи?",a="Сама роща — безопасное убежище с дружелюбными стражами и торговцами, но враждебные звери и лагеря воинственных фурболгов находятся сразу за рекой и на юго-востоке.",al={"grove threats","is grove safe","monsters near grove","угрозы роще","безопасна ли роща","монстры возле рощи"}}},fp="21,274,25.440.0,20.434.0,35.138.0,11.195.0,31.177.0,33.182.0"}
P.entries["subzone:growless-cave"] = {n="Промерзшая пещера",s="Промерзшая пещера — холодная пещера в скалах Альтеракских гор, где кишат свирепые горные йети. Она известна прежде всего как место, где находится Пламя Узеля — нечестивый ритуальный костер, связанный с темным некромантством Хелкулара.",h="Промерзшая пещера — холодная пещера в скалах Альтеракских гор, где кишат свирепые горные йети.",kw={"alterac","flame of uzel","frostmaw","growless cave","helcular","skhowl","yeti","альтерак","пламя узеля","морозная пасть","промерзшая пещера","хелкулар","сховл","йети"},ang={["class:Mage"]="Остатки Пламени Узеля — суровое предупреждение о том, что бывает, когда чародейство Кирин-Тора извращается ради некромантии.",["race:Undead"]="Пещера мрачно значима для Отрекшихся, помогающих отомстить Хелкулару: его темные обряды и реликвии до сих пор разбросаны по павшему Альтераку."},sec={{t="Логово зверей и темной магии",b="Промерзшая пещера скрыта на заснеженных высотах над предгорьями и служит прежде всего логовом для свирепых горных йети, бродящих по Альтераку. Путники на опасных склонах обычно обходят ее вход стороной, особенно когда рядом замечен печально известный йети Схоул. Помимо первобытной опасности со стороны зверей, у пещеры мрачное прошлое: внутри находится Пламя Узеля — магическая жаровня, оставленная честолюбивым человеком-магом Хелкуляром. Перед гибелью Хелкуляр собирался использовать этот костер в темном ритуале, чтобы стать личом, и его отвратительное тепло однажды выманило из ледяных пустошей огромного хищника Ледяную Пасть."}},faq={{q="Какие существа обитают в Промерзшей пещере?",a="В пещере живут дикие горные йети, обитающие в Альтераке. Иногда у самого входа бродит опасный редкий йети по имени Сховл.",al={"who lives here","growless cave mobs","what is inside growless cave","кто здесь живет","монстры промерзшей пещеры","что внутри промерзшей пещеры"}},{q="Что такое Пламя Узеля?",a="Пламя Узеля — ритуальный костер, разожженный Хелкуларом, бывшим магом Даларана, ставшим некромантом. Он создал его как часть запретного ритуала, который должен был превратить его в бессмертного лича.",al={"flame of uzel","pyre in growless cave","helcular flame","пламя узеля","костер в промерзшей пещере","пламя хелкулара"}},{q="Кто такая Морозная Пасть?",a="Морозная Пасть — огромный, исключительно свирепый йети, бродящий по вершинам Альтерака. Раньше, если сжечь свежее мясо на Пламени Узеля, ненасытный зверь приходил прямо к пещере.",al={"frostmaw yeti","frostmaw","йети морозная пасть","морозная пасть"}},{q="Зачем путники приходят сюда?",a="Искатели приключений, отваживающиеся войти в пещеру, обычно охотятся на опасных йети ради шкур или ищут оставшиеся некромантические артефакты, связанные с наследием Хелкулара в Альтераке.",al={"why go to growless cave","growless cave quests","зачем идти в промерзшую пещеру","задания промерзшей пещеры"}}},fp="13,244,30.657.0,37.146.0,26.207.0,16.187.0,33.171.0"}
P.entries["subzone:gunther-s-retreat"] = {n="Приют Гюнтера",s="Приют Гюнтера — уединенное островное убежище на Озере Ясноводном в центре Тирисфальских лесов. Это прибежище Гюнтера Чародея, отступника-некроманта, силой воли освободившегося от Плети. Не доверяя чужакам, затворник окружает свой лагерь верными нежитью-слугами, чтобы отпугивать незваных гостей.",h="Приют Гюнтера — уединенное островное убежище на Озере Ясноводном в центре Тирисфальских лесов.",kw={"brightwater lake","gunther arcanus","gunther's retreat","lich","lillith's dinner table","tirisfal glades","undead","озеро ясноводное","гюнтер чародей","приют гюнтера","лич","обеденный стол лиллит","тирисфальские леса","нежить"},ang={["class:Mage"]="Маги оценят редкий подвиг Гюнтера: его магическая воля была достаточно сильна, чтобы полностью разорвать ментальную хватку Короля-лича без посторонней помощи.",["race:Undead"]="Гюнтер Чародей повторяет трагедию самих Отрекшихся: свободный от Короля-лича, он остается подозрительным и настороженным к миру, который, как он полагает, все еще в рабстве у Плети."},sec={{t="Затворник на Озере Ясноводном",b="Приют Гюнтера, скрытый среди туманных вод Озера Ясноводного, — неприметный островной лагерь, который легко принять за очередной оплот Плети. Его хозяин, Гюнтер Чародей, совершил то, на что способны немногие смертные чародеи: после воскрешения в нежити его тайное мастерство позволило ему вырвать душу из железной хватки Короля-лича без чьей-либо помощи. Не доверяя никому, Гюнтер решил, что остальная нежить Лордерона все еще марионетки Плети. Он удалился на этот одинокий остров, чтобы спокойно заниматься своим ремеслом, и выставил зомби-стражей, которые разрывают любого, кто пересечет воду."}},faq={{q="Кто живет в Приюте Гюнтера?",a="Остров населяет Гюнтер Чародей, могущественный некромант, освободившийся от власти Короля-лича собственными силами. Он живет там вместе со свитой нежити-рабов, охраняющих его лагерь.",al={"gunther island","who is on the island","gunther's retreat master","остров гюнтера","кто на острове","хозяин приюта гюнтера"}},{q="Почему нежить на острове враждебна?",a="Гюнтер Чародей считает, что вся остальная нежить в Тирисфале все еще порабощена Плетью. Он ценит свою независимость превыше всего, поэтому его слуги получили приказ нападать на любого, кто приблизится к острову.",al={"why does gunther attack","why hostile","is gunther scourge","почему гюнтер нападает","почему враждебны","гюнтер из плети"}},{q="Союзен ли Гюнтер Отрекшимся?",a="Сначала нет. Хотя Гюнтер, как и Отрекшиеся, — нежить со свободной волей, он полностью замкнулся в себе. Власти Подгорода стремятся доказать ему, что они тоже свободны от хватки Короля-лича, и привлечь его таланты на свою сторону.",al={"is gunther in the horde","gunther forsaken","gunther undercity","гюнтер в орде","гюнтер отрекшийся","гюнтер подгород"}},{q="Что за маленький островок к юго-западу от приюта?",a="У юго-западного края Приюта Гюнтера лежит крошечный безымянный островок, известный как Обеденный стол Лилит, — любопытная и жутковатая достопримечательность в водах Озера Ясноводного.",al={"lillith dinner table","small island near gunther","table island","обеденный стол лиллит","маленький остров у гюнтера","остров-стол"}}},fp="17,338,29.608.0,31.204.0,41.230.0,37.249.0,49.191.0"}
P.entries["subzone:gurubashi-arena"] = {n="Арена Гурубаши",s="Арена Гурубаши — древний каменный колизей на юге Тернистой долины, построенный могучей Империей Гурубаши. Сегодня это место хаотичных схваток «каждый сам за себя», где пираты и бродячие бойцы проливают кровь за запертые сундуки с сокровищами.",h="Арена Гурубаши — древний каменный колизей на юге Тернистой долины, построенный могучей Империей Гурубаши.",kw={"arena","booty run","chest","gurubashi","rastakhan","short john mithril","stranglethorn","the great arena","арена","погоня за добычей","сундук","гурубаши","растахан","коротышка джон мифрил","тернистая долина","великая арена"},ang={["class:Warrior"]="Пески предлагают одно из чистейших воинских испытаний Азерота, лишенное большой военной политики и сведенное к личной стойкости и борьбе за выживание.",["race:Troll"]="Для троллей арена — священная земля, а не простая пиратская забава: здесь проходит турнир раз в поколение под началом зандаларов, где завоевывают честь перед лоа."},sec={{t="Наследие крови",b="Задолго до того, как в Тернистой долине появились люди и орки, Арена Гурубаши, известная также как Великая арена, была возведена как памятник воинской силе обширной тролльской империей Гурубаши. В древности чемпионы бились здесь насмерть, пока земля не становилась скользкой от крови троллей. Раз в поколение, согласно традиции, величайшие воины-тролли со всего Азерота собираются в этих высоких каменных стенах, чтобы сразиться за честь своих лоа под началом короля зандаларов Растахана. Победа в этом обряде — одна из высочайших почестей для тролля-воина."},{t="Погоня за добычей",b="Хотя империя давно распалась на воюющие племена, арена недолго остается чистой. Сегодня беззаконные пираты и головорезы заправляют иным кровавым зрелищем. Пират по имени Коротышка Джон Мифрил управляет ареной, куда каждые несколько часов в центр круга втаскивают сундук с награбленной добычей. Любой, кто выходит на арену, становится законной целью: принадлежность к фракциям исчезает, и бойцы прорубают себе путь к награде против всех."}},faq={{q="Кто построил Арену Гурубаши?",a="Ее много веков назад возвела Империя Гурубаши, когда правила южными землями Восточных королевств. Она задумывалась как огромный стадион для смертельных поединков и древних ритуалов троллей в честь лоа.",al={"who made gurubashi arena","arena origin","troll arena lore","кто построил арену гурубаши","происхождение арены","предания арены троллей"}},{q="Почему здесь теперь сражаются?",a="Местные пираты используют арену для незаконных развлечений. Каждые несколько часов пиратский капитан затаскивает сундук с сокровищами в центр арены, начиная кровавую свалку между всеми, кто осмелится выйти на арену и забрать его.",al={"why fight in gurubashi","gurubashi chest","booty run lore","бои на гурубаши","сундук гурубаши","предания погони за добычей"}},{q="Кто такой Коротышка Джон Мифрил?",a="Коротышка Джон Мифрил — пират, управляющий ареной и регулярной доставкой сундуков. Он награждает бойцов, которые раз за разом выживают в хаотичных схватках и возвращают сокровища арены.",al={"short john mithril","arena overseer","коротышка джон мифрил","управляющий ареной"}},{q="Почему здесь меня могут атаковать члены моей фракции?",a="На арене царит полное беззаконие. Как только вы выходите на песок, все договоры фракций и военные союзы перестают действовать — ваш клинок щадит лишь тех, кто стоит с вами в одной боевой группе.",al={"why is gurubashi free for all","friendly fire in gurubashi","arena pvp rules","почему на гурубаши все против всех","огонь по своим на гурубаши","правила пвп арены"}}},fp="15,286,17.591.0,13.484.0,30.229.0,29.242.0,26.186.0,49.233.0"}
P.entries["subzone:haldarr-encampment"] = {n="Лагерь Халдарр",s="Лагерь Халдарр — оскверненный форпост сатиров в западной Азшаре, к северо-востоку от Святилища Песни Теней и к юго-западу от Храбростана. Густо населенный свирепыми сатирами Халдарр, он остается опасной язвой среди древних эльфийских руин. Здесь же в плену находится раненая часовая ночных эльфов Кельдара Солнечный Клинок.",h="Лагерь Халдарр — оскверненный форпост сатиров в западной Азшаре, к северо-востоку от Святилища Песни Теней и...",kw={"azshara","encampment","haldarr","keldara sunblade","satyr","shadowsong shrine","valormok","азшара","лагерь","халдарр","кельдара солнечный клинок","сатир","святилище песни теней","храбростан"},ang={["faction:Horde"]="Это густое гнездо демонов к юго-западу от Храбростана представляет непосредственную угрозу для разведчиков и линий снабжения Орды, продвигающихся по утесам Азшары.",["race:NightElf"]="Для кальдораев сатиры Халдарр — позорное, неизменное напоминание о падении древних высокорожденных в демоническое безумие, а спасти часовую Кельдару Солнечный Клинок из их лап — долг."},sec={{t="Логово демонических отродий",b="Лагерь Халдарр, расположенный среди разбитых камней западной Азшары, служит местом сбора клана сатиров Халдарр. Эти искаженные создания, древние потомки высокорожденных, проклятых демонической скверной во время Раскола, активно охотятся на всех, кто идет через осенние леса, и досаждают им. Густое поселение постоянно угрожает как силам Орды в соседнем Храбростане, так и редеющим часовым ночных эльфов, пытающимся наблюдать за регионом."},{t="Плененная часовая",b="Среди зловещих обитателей лагеря находится часовая Кельдара Солнечный Клинок, раненая и застрявшая в сердце вражеской земли. Ее присутствие делает Лагерь Халдарр срочной заботой для тех, кто хочет помешать мерзким делам сатиров и выяснить, почему она остается в плену у демонов."}},faq={{q="Что такое Лагерь Халдарр?",a="Лагерь Халдарр — оскверненное поселение в западной Азшаре, находящееся под властью клана сатиров Халдарр. Он лежит к юго-западу от форпоста Орды Храбростан и к северо-востоку от Святилища Песни Теней.",al={"haldarr encampment lore","what is haldarr","who lives in haldarr encampment","предания лагеря халдарр","что такое халдарр","кто живет в лагере халдарр"}},{q="Кто такие Халдарр?",a="Халдарр — свирепая секта сатиров, обитающая в Азшаре. Как и все сатиры, они происходят от древних ночных эльфов, заключивших демонические сделки во время Войны Древних; проклятые, они превратились в козлоногих демонов, служащих воле остатков Пылающего Легиона.",al={"haldarr satyrs","who are the satyrs here","сатиры халдарр","кто здесь сатиры"}},{q="Кто такая часовая Кельдара Солнечный Клинок?",a="Часовая Кельдара Солнечный Клинок — раненая ночная эльфийка, которую держат в Лагере Халдарр; ее окружают враждебные сатиры, не выпускающие ее со своей территории.",al={"keldara sunblade","injured night elf","who is the captive here","кельдара солнечный клинок","раненая ночная эльфийка","кто здесь пленница"}},{q="Чем этот лагерь опасен для путников поблизости?",a="Лагерь густо заселен агрессивными сатирами, которые патрулируют окрестные тропы и угрожают им, подвергая опасности как операции Орды из Храбростана, так и любых одиноких разведчиков в округе.",al={"is haldarr dangerous","why clear haldarr","опасен ли халдарр","зачем зачищать халдарр"}}},fp="18,354,20.474.0,21.324.1,31.196.0,20.256.0,33.164.0,47.194.0"}
P.entries["subzone:hall-of-arms"] = {n="Зал Оружия",s="Зал Оружия — штаб военной мощи Стальгорна и главный арсенал дворфийского королевства. Этот укрепленный комплекс расположен в Военном квартале: здесь обучают дворфийских бойцов и организуют отправку тяжелой брони и воздушных боевых машин.",h="Зал Оружия — штаб военной мощи Стальгорна и главный арсенал дворфийского королевства.",kw={"battlemasters","dwarven army","flying machines","hall of arms","ironforge","military ward","steam tanks","полководцы","дворфийская армия","летающие машины","зал оружия","стальгорн","военный квартал","паровые танки"},ang={["class:Warrior"]="Это здание — главное место сбора дворфийских воинов и ветеранов в столице, где проводится обучение и действует руководство полководцев.",["race:Dwarf"]="Для дворфов Зал Оружия воплощает союз воинской дисциплины и механической изобретательности Каз Модана: здесь размещены танки и воздушные эскадрильи, защищающие горное королевство."},sec={{t="Арсенал сердца горы",b="Зал Оружия находится в юго-восточной части Военного квартала и служит оперативным командным центром вооруженных сил Стальгорна. Помимо опытных наставников для воинов и охотников, этот обширный комплекс является огромным складом и сборным пунктом для механизированной войны. Тяжелые паровые танки собирают и обслуживают прямо здесь, чтобы усилить поля сражений Альянса, а гирокоптеры и летающие машины поднимаются промышленными конвейерами и запускаются через вертикальные шахты в потолке пещеры к Аэродрому Стальгорна наверху."}},faq={{q="Для чего нужен Зал Оружия?",a="Это штаб и командный центр военных сил Стальгорна. Он служит одновременно тренировочной площадкой для воинов и охотников и важным складом, где обслуживают и отправляют боевые машины, такие как паровые танки и гирокоптеры.",al={"what is hall of arms","hall of arms role","why hall of arms exists","что такое зал оружия","роль зала оружия","зачем нужен зал оружия"}},{q="Куда направляются летающие машины, запускаемые через потолок?",a="Дворфийские летающие машины поднимаются конвейерами и запускаются через вертикальные шахты в потолке прямо к Аэродрому Стальгорна на склонах горы. Эта шахта — один из немногих прямых выходов на поверхность из горы, помимо главных ворот.",al={"ceiling shaft ironforge","flying machine tunnel","where do copters go","шахта в потолке стальгорна","туннель летающих машин","куда летят гирокоптеры"}},{q="Кого можно найти в Зале для обучения?",a="В здании находятся наставники воинов и охотников, а также полководцы Альянса, которые организуют передвижение войск и набор на более широкие фронты по всему континенту.",al={"trainers in hall of arms","who teaches here","наставники в зале оружия","кто здесь учит"}},{q="Где находится Зал Оружия?",a="Он расположен в юго-восточной части Стальгорна и замыкает Военный квартал.",al={"hall of arms location","how to get to hall of arms","расположение зала оружия","как добраться до зала оружия"}}},fp="12,275,31.579.0,40.244.0,58.272.0,40.179.0,34.97.0"}
P.entries["subzone:hall-of-arms-northshire"] = {n="Зал Оружия (Североземье)",s="Зал Оружия — военное крыло Аббатства Североземья к югу от Главного зала. Здесь опытные наставники обучают новых рекрутов Армии Штормграда искусству владения мечом, щитом и священному бою.",h="Зал Оружия — военное крыло Аббатства Североземья к югу от Главного зала.",kw={"elwynn forest","hall of arms","northshire abbey","northshire valley","paladin trainer","stormwind army","warrior trainer","элвиннский лес","зал оружия","аббатство североземья","долина североземья","наставник паладинов","армия штормграда","наставник воинов"},ang={["class:Paladin"]="Зал Оружия сочетает священную преданность с воинской закалкой и дает начинающим паладинам основы владения Светом наряду с боевым оружием.",["class:Warrior"]="Для воинов-людей, поступающих на службу, это крыло — место, где вы получаете самые первые уроки стойки, обращения с оружием и воинской дисциплины Армии Штормграда."},sec={{t="Основы стражи",b="Пока клирики и ученые размышляют над древними книгами через двор, в Библиотечном крыле, Зал Оружия звенит от ударов затупленной стали и тяжелого ритма воинских занятий. Эта палата на южной стороне Аббатства Североземья — главный учебный пункт для неопытных людей-бойцов и благочестивых новичков, берущих оружие в ряды Армии Штормграда. Здесь опытные боевые наставники и наставники-паладины учат основным стойкам, дисциплине и основам, необходимым для защиты Элвиннского леса от наседающих кобольдов, бандитов из Братства Справедливости и гноллов-налетчиков."}},faq={{q="Для чего нужен Зал Оружия?",a="Зал Оружия — первое место боевой подготовки в Аббатстве Североземья. Недавно завербованные солдаты, наемники и паладины получают здесь начальное обучение обращению с оружием и боевым приемам, прежде чем отправиться в большое королевство.",al={"what is this room","hall of arms purpose","what happens here","что это за комната","назначение зала оружия","что здесь происходит"}},{q="Кого можно найти в этом крыле?",a="В крыле работают опытные наставники воинов и паладинов, которые от имени Армии Штормграда обучают новобранцев воинской дисциплине, обращению со щитом и основным боевым приемам.",al={"who is in hall of arms","trainers hall of arms","who teaches here","кто в зале оружия","наставники зала оружия","кто здесь учит"}},{q="Где в Аббатстве Североземья находится Зал Оружия?",a="Зал Оружия расположен в южной части Аббатства Североземья, в него можно попасть прямо из центрального Главного зала; через двор аббатства ему симметрично отвечает Библиотечное крыло.",al={"hall of arms location","where is hall of arms","abbey layout","расположение зала оружия","где зал оружия","план аббатства"}}},fp="25,215,23.586.0,40.248.0,34.184.0,58.171.0"}
P.entries["subzone:hall-of-arms-tyr-s-hand"] = {n="Зал Оружия (Длань Тира)",s="Зал Оружия — сильно охраняемое крыло Аббатства Длани Тира на юго-востоке Восточных Чумных земель. Это сборный пункт и казармы для воинского авангарда Алого ордена, расквартированного в крепости. Он расположен напротив библиотеки и вмещает одних из самых фанатичных и хорошо бронированных бойцов ордена.",h="Зал Оружия — сильно охраняемое крыло Аббатства Длани Тира на юго-востоке Восточных Чумных земель.",kw={"abbey","armory","eastern plaguelands","hall of arms","scarlet crusade","tyr's hand","tyrs hand","аббатство","арсенал","восточные чумные земли","зал оружия","алый орден","длань тира"},ang={["class:Paladin"]="Для рыцарей Серебряной Длани вход в Зал Оружия — горькое зрелище: священные традиции святого боя превращены в фанатичную замкнутость.",["class:Warrior"]="Вооружение и дисциплинированная боевая подготовка в Зале Оружия представляют вершину человеческого милитаризма, пусть и служащего фанатизму."},sec={{t="Оплот стали",b="Зал Оружия, расположенный к югу от главного зала аббатства, служит арсеналом и казармой для воинственных сил Длани Тира. Если противоположное крыло хранит архивы и священные тексты, то это посвящено исключительно военному делу. Защитники Алого ордена, облаченные в тяжелые доспехи и поклявшиеся истребить нежить и всех, кого сочтут нечистыми, несут неусыпный караул в своем восточном оплоте, держа оружие заточенным, а щиты начищенными перед лицом окружающих ужасов Чумных земель."}},faq={{q="Где находится Зал Оружия?",a="Зал Оружия находится в Аббатстве Длани Тира — величественной соборной крепости внутри Длани Тира в юго-восточном углу Восточных Чумных земель. Он образует южное крыло комплекса аббатства напротив Библиотечного крыла.",al={"hall of arms location","where is hall of arms","tyrs hand abbey hall of arms","расположение зала оружия","где зал оружия","зал оружия аббатство длани тира"}},{q="Кто занимает Зал Оружия?",a="Крыло полностью занято элитными воинскими силами Алого ордена. Здесь собираются опытные воины, паладины и стражи, которые содержат вооружение и готовятся к бою с Плетью и любыми чужаками, вторгшимися в их убежище.",al={"who lives in hall of arms","hall of arms enemies","scarlet crusade hall of arms","кто живет в зале оружия","враги зала оружия","алый орден зал оружия"}},{q="Чем это крыло отличается от остального аббатства?",a="Если противоположное крыло аббатства посвящено учебе, созерцанию и священным писаниям, то Зал Оружия построен специально для физической обороны, размещения войск и содержания оружия. Он делает священный оплот грозным в военном отношении перед вторжениями Плети.",al={"purpose of hall of arms","what is hall of arms for","назначение зала оружия","для чего нужен зал оружия"}},{q="Могут ли члены Альянса войти туда мирно?",a="Нет. Несмотря на общие человеческие корни и почитание Света, Алый орден в Длани Тира совершенно фанатичен. Орден видит в чужаках возможных переносчиков чумы или пособников зла и нападает на путников как из Альянса, так и из Орды при первой встрече.",al={"is scarlet crusade friendly to alliance","can alliance visit hall of arms","will tyrs hand attack me","дружелюбен ли алый орден к альянсу","может ли альянс зайти в зал оружия","нападет ли длань тира"}}},fp="25,342,18.520.0,34.239.0,30.242.0,67.268.0,45.262.0"}
P.entries["subzone:hall-of-explorers"] = {n="Зал Исследователей",s="Зал Исследователей — обширное археологическое крыло Стальгорна и оживленный штаб дворфийской Лиги исследователей. Отчасти музей, отчасти архив, отчасти командный пункт экспедиций, он собирает реликвии, окаменелости и древние книги со всех уголков Азерота, чтобы восстановить забытое происхождение дворфов.",h="Зал Исследователей — обширное археологическое крыло Стальгорна и оживленный штаб дворфийской Лиги...",kw={"archaeology","explorers' league","hall of explorers","ironforge library","magellas","museum","археология","лига исследователей","зал исследователей","библиотека стальгорна","магеллас","музей"},ang={["race:Dwarf"]="Для дворфов-путешественников зал — главное хранилище наследия их народа: здесь собраны реликвии, помогающие раскрыть ваше древнее происхождение и связь с титанами."},sec={{t="Штаб Лиги",b="Зал Исследователей, занимающий северо-восточную пещеру Стальгорна и порой называемый Собранием исследователей, — нервный центр всех археологических работ, санкционированных Альянсом. Под руководством старшего исследователя Мунинна Магелласа ученые и полевые агенты координируют раскопки в далеких землях, присылая загадочные реликвии, древние механизмы титанов и доисторические кости. Огромная Библиотека в центре зала служит и публичным музеем, и закрытым хранилищем исторических преданий."}},faq={{q="Для чего нужен Зал Исследователей?",a="Это главный штаб и архивный музей Лиги исследователей. Ученые анализируют полевые отчеты, каталогизируют реликвии из раскопок и организуют археологические экспедиции, чтобы выяснить происхождение дворфов и древнего Азерота.",al={"hall of explorers purpose","what happens here","explorers league base","назначение зала исследователей","что здесь происходит","база лиги исследователей"}},{q="Кто руководит работой здесь?",a="Верховный исследователь Мунин Магеллас руководит экспедициями зала, музейной экспозицией и исследовательскими архивами в пределах квартала.",al={"who runs hall of explorers","explorers league leader","high explorer","кто управляет залом исследователей","глава лиги исследователей","верховный исследователь"}},{q="Как это место связано с остальным Стальгорном?",a="Зал Исследователей находится в северо-восточной части города. Арки напрямую соединяют его с Великой кузней на юго-западе, Одинокой пещерой на западе и Городом механиков на юге.",al={"how to get here","hall of explorers exits","where is hall of explorers","как добраться","выходы из зала исследователей","где зал исследователей"}}},fp="17,327,26.517.0,39.239.0,30.127.0,53.195.0"}
P.entries["subzone:hall-of-gears"] = {n="Зал Шестеренок",s="Зал Шестеренок — многоярусный промышленный зал в павшем Гномрегане, сразу за Заводным тоннелем. Некогда оживленный центр механизмов, он лежит в руинах: он затоплен токсичной жижей, по нему бродят слизь и облученные трогги.",h="Зал Шестеренок — многоярусный промышленный зал в павшем Гномрегане, сразу за Заводным тоннелем.",kw={"clean zone","clockwerk run","dormitory","gnomeregan","hall of gears","launch bay","radioactive","troggs","чистая зона","заводной тоннель","общежитие","гномреган","зал шестеренок","пусковая установка","радиоактивный","трогги"},ang={["profession:Engineering"]="Огромный масштаб автоматических передач и приподнятых платформ показывает вершину гномьей инженерии до падения, хотя теперь все сильно разъедено радиоактивными осадками.",["race:Gnome"]="Вид огромных шестерней и мостков, погруженных в облученную жижу, болезненно напоминает об отчаянном решении, которое отравило город и обрекло народ гномов на изгнание."},sec={{t="Разбитая машина",b="Зал Шестеренок, расположенный сразу за Заводным тоннелем, показывает катастрофический крах столицы гномов. Зал разделен на два основных уровня: верхние мостки удерживают агрессивные облученные трогги, прорывающиеся через обрушенные шахты. Внизу пол залит лужами радиоактивных осадков, где в токсичных стоках обитают едкая слизь и живые элементали яда."},{t="Пути через отходы",b="Зал служит важным перекрестком в глубине рабочих кварталов Гномрегана. С верхних мостков пути ведут в зараженные тупики и в относительно безопасные Чистую зону и Общежитие. Спуск в радиоактивные глубины ниже в конце концов выводит путников по извилистым служебным проходам к Пусковой установке, но на любом из этажей придется пробиваться через ужасы, оставшиеся после губительного плана Сикко Термоштепселя по выпуску газа."}},faq={{q="Где находится Зал Шестеренок?",a="Зал Шестеренок находится в глубине подземелья Гномреган, сразу за Заводным тоннелем. Дальше вглубь он соединяется с Чистой зоной, Общежитием и Пусковой установкой.",al={"hall of gears location","where is hall of gears","how to get to hall of gears","зал шестеренок где","где находится зал шестеренок","как добраться до зала шестеренок"}},{q="Почему нижний уровень полон радиоактивной жижи?",a="Когда главный механик Меггакрут приказал выпустить радиоактивный газ, чтобы отразить вторжение троггов, зараженные стоки собрались в низинных машинных залах города и превратили нижний этаж Зала Шестеренок в токсичную пустошь.",al={"why is it green","radioactive waste hall of gears","what is the sludge","почему зеленый","радиоактивные отходы зал шестеренок","что за жижа"}},{q="Какие существа обитают в этом зале?",a="Верхний уровень кишит мутировавшими облученными троггами, лезущими через пробитые туннели. Нижний ярус заполнен радиоактивной слизью, илом и неустойчивыми элементалями яда, возникшими из промышленных стоков.",al={"hall of gears enemies","what lives in hall of gears","hall of gears mobs","зал шестеренок враги","кто живет в зале шестеренок","зал шестеренок мобы"}},{q="Куда ведут выходы отсюда?",a="Верхние мостки ведут на юго-запад к Чистой зоне и Общежитию, а также в тупиковый служебный коридор на юго-востоке. Нижний облученный этаж имеет извилистый проход на запад, ведущий прямо к Пусковой установке.",al={"hall of gears exits","where to go from hall of gears","зал шестеренок выходы","куда идти из зала шестеренок"}}},fp="13,267,19.407.0,26.478.0,35.184.0,50.240.0,36.227.0,34.242.0"}
P.entries["subzone:hall-of-legends"] = {n="Зал Легенд",s="Зал Легенд — элитное военное убежище и казармы офицеров Орды в Аллее Силы Оргриммара. За его защищенным порогом защитники Орды собираются над планами сражений и вооружаются лучшим оружием, добытым в конфликтах по всему Азероту и за его пределами.",h="Зал Легенд — элитное военное убежище и казармы офицеров Орды в Аллее Силы Оргриммара.",kw={"hall of legends","officer barracks","orgrimmar","pvp","spoils of war","stone guard","valley of strength","зал легенд","казармы офицеров","оргриммар","пвп","трофеи войны","каменный страж","аллея силы"},ang={["class:Warrior"]="Для бойцов переднего края вход в Зал Легенд — вершина воинского уважения: он дает доступ к оружию, выкованному в конфликтах во многих мирах.",["faction:Horde"]="Зал Легенд — высшее свидетельство воинских достижений Орды: он дает признание, стратегический совет и ценное вооружение тем, кто проливает кровь за Вождя."},sec={{t="Убежище защитников Орды",b="Зал Легенд, расположенный недалеко от шумных улиц Аллеи Силы, служит закрытым оплотом для заслуженных офицеров Орды. За охраняемым входом стратеги и представители разных фракций, среди которых вождь Землерожденный из Громового Утеса, кровавый страж Хини'вана из племени Черного Копья и советник Виллингтон из Подгорода, совещаются над картами спорных земель и военным положением обеих фракций. Сюда допускаются только воины, проверенные в боях и достигшие звания каменного стража или выше, чтобы получить добычу и вооружение, соответствующие их положению."},{t="Трофеи войны",b="Зал — не просто офицерская гостиная: в нем находятся оружейные с проверенным в боях снаряжением со всего Азерота и разрушенного родного мира орков, Дренора. Многое из этого оружия было взято как трофеи в продолжающихся схватках с Альянсом и другими противниками. Для тех, кто поднимается по военным рангам, он — воплощение чести Орды, воинского мастерства и тяжело доставшейся победы."}},faq={{q="Кому разрешено входить в Зал Легенд?",a="Проход через порог зала открыт только защитникам Орды, достигшим звания каменного стража (6-й ранг) или выше в системе воинской чести. Солдат низших званий и обычных жителей разворачивают у входа.",al={"can i enter hall of legends","hall of legends requirement","rank required for hall of legends","можно ли войти в зал легенд","зал легенд требования","ранг для зала легенд"}},{q="Где находится Зал Легенд?",a="Зал Легенд расположен в Аллее Силы в Оргриммаре, рядом с главными казармами и административным центром города.",al={"where is hall of legends","hall of legends location","how to get to hall of legends","где зал легенд","зал легенд расположение","как добраться до зала легенд"}},{q="Что находится внутри Зала Легенд?",a="Внутри находится центральный стратегический стол, окруженный военными представителями разных рас Орды, а вокруг — карты Азерота и военные записи. Здесь же интенданты держат оружейные и выдают почетное оружие, доспехи и транспорт заслуженным офицерам.",al={"what is in hall of legends","hall of legends interior","что в зале легенд","зал легенд интерьер"}},{q="Есть ли у Альянса подобное место?",a="Да. Аналог Альянса — Зал Защитников в Старом городе Штормграда, который также служит казармами и оружейной для заслуженных бойцов Альянса.",al={"alliance hall of legends","alliance counterpart","зал легенд альянса","аналог для альянса"}}},fp="15,300,28.609.0,17.405.0,42.231.0,37.129.0,35.273.0,46.196.0"}
P.entries["subzone:hall-of-masks"] = {n="Зал Масок",s="Зал Масок — зловещий зал в затонувшем Храме Атал'Хаккара в Болоте Печали. Он украшен гигантскими масками-черепами и изуродован заваленной костями канавой и служит одним из первых порогов вглубь твердыни Атал'ай.",h="Зал Масок — зловещий зал в затонувшем Храме Атал'Хаккара в Болоте Печали.",kw={"atal'ai","broken hall","hall of masks","sunken temple","swamp of sorrows","temple of atal'hakkar","атал'ай","разрушенный зал","зал масок","затонувший храм","болото печали","храм атал'хаккара"},ang={["race:Troll"]="Для троллей Черного Копья этот зал показывает, на какие зловещие крайности шли фанатики Атал'ай в отчаянной погоне за Хаккаром Свежевателем Душ."},sec={{t="Жуткий порог",b="Located just past the staircase descending from the Broken Hall, the Hall of Masks serves as a central junction within the Sunken Temple. The chamber earns its name from the imposing, stylized skull masks mounted along its stone walls. Below them runs a deep trench choked with discarded bones, suggesting a macabre purpose whose exact nature is unknown. Beyond this eerie hall lie passages branching out to the Butchery, the Chamber of Blood, and the Den of the Caller."}},faq={{q="Где находится Зал Масок?",a="Зал Масок — внутреннее крыло Храма Атал'Хаккара, расположенное под водами Озера Слез в Болоте Печали. Вы доберетесь до него, спустившись мимо Разрушенного зала у входа в затонувший комплекс.",al={"hall of masks location","where is hall of masks","find hall of masks","зал масок где","где находится зал масок","найти зал масок"}},{q="Почему он называется Залом Масок?",a="Он получил имя от огромных резных масок-черепов, украшающих стены зала и нависающих над каждым, кто идет по коридорам храма.",al={"hall of masks name meaning","why masks","значение названия зал масок","почему маски"}},{q="Для чего служила канава в полу?",a="The trench is littered with bones, suggesting a macabre function. Its exact purpose is unknown.",al={"why are there bones in the floor","hall of masks bone pit","trench of bones","почему кости в полу","зал масок яма с костями","канава с костями"}},{q="Куда ведут проходы из этого зала?",a="За Залом Масок путь ведет глубже в нижние комплексы храма и напрямую соединяется с такими местами, как Мясницкая, Кровавая палата и Логово Призывателя.",al={"hall of masks exits","where does hall of masks lead","зал масок выходы","куда ведет зал масок"}}},fp="13,242,20.470.0,35.230.0,35.154.0,48.95.0,42.183.0"}
P.entries["subzone:hall-of-mysteries"] = {n="Зал Тайн",s="Зал Тайн, скрытый в Мистическом квартале Стальгорна, — духовное и научное сердце города для тайных искусств и божественного. В его освещенных синим светом стенах гномы и дворфы изучают древние тексты, постигают тайны Света и плетут чародейские чары вдали от лязга Великой кузни.",h="Зал Тайн, скрытый в Мистическом квартале Стальгорна, — духовное и научное сердце города для тайных искусств и...",kw={"hall of mysteries","ironforge","mage","mystic ward","paladin","priest","rohan","silver hand","tome of divinity","зал тайн","стальгорн","маг","мистический квартал","паладин","жрец","рохан","серебряная длань","фолиант божественности"},ang={["class:Paladin"]="Для дворфийских защитников Серебряной Длани зал — основа их призвания: здесь наставники назначают испытания добродетели и открывают доступ к священному Фолианту Божественности.",["class:Priest"]="Верховный жрец Рохан наставляет здесь служителей Света в духовных уроках, а затем отправляет многообещающих жрецов на юг для встречи с руководством в Штормграде."},sec={{t="Храм магии и веры",b="Освещенный особым сине-фиолетовым сиянием, Зал Тайн резко выделяется на фоне остального Стальгорна. Пока город вокруг живет камнем, железом и тяжелыми латами, пять высоких колонн зала укрывают ученых в мягких струящихся мантиях. Он объединяет чародейство и святую преданность и служит штаб-квартирой дворфийского жречества и Ордена Серебряной Длани в Каз Модане. Здесь юные клирики и рыцари изучают священные тексты, например Фолиант Божественности, и получают наставления, прежде чем отправиться в Собор Света Штормграда."}},faq={{q="Для чего нужен Зал Тайн?",a="Зал Тайн — главный центр Стальгорна как для божественной преданности, так и для тайного обучения. Он служит храмом Света и учебным залом, где дворфийские и гномьи жрецы, паладины и маги занимаются своим ремеслом, изучают древние писания и обучают новичков.",al={"what is this place","hall of mysteries purpose","why visit hall of mysteries","что это за место","зал тайн назначение","зачем посещать зал тайн"}},{q="Кто возглавляет здесь духовенство?",a="Верховный жрец Рохан надзирает за жречеством в зале и служит духовным наставником дворфийских служителей Света, наряду с наставниками-паладинами, такими как Вальгар Высокая Кузня, которые направляют рыцарей Серебряной Длани города.",al={"who runs hall of mysteries","priest leader ironforge","who is high priest rohan","кто управляет залом тайн","глава жрецов стальгорн","кто такой верховный жрец рохан"}},{q="Чем он отличается от Собора Света в Штормграде?",a="Если Собор Света Штормграда посвящен исключительно святой вере и торжественным богослужениям, то Зал Тайн гармонично объединяет священное учение и чародейскую науку под одной крышей. Его атмосфера скорее ученая и тихая, чем строго богослужебная.",al={"cathedral of light vs hall of mysteries","is it like stormwind cathedral","собор света или зал тайн","похож ли на собор штормграда"}},{q="Могут ли паладины пройти здесь свои испытания?",a="Да. Дворфийских паладинов направляют в зал изучать Фолиант Божественности под руководством Серебряной Длани: они получают наставления и священные испытания, проверяющие их сострадание, преданность и мужество.",al={"paladin quests ironforge","tome of divinity ironforge","dwarf paladin quests","задания паладина стальгорн","фолиант божественности стальгорн","задания паладина дворфа"}}},fp="17,341,27.605.0,45.289.0,26.230.0,59.266.0,49.211.0"}
P.entries["subzone:hall-of-the-brave"] = {n="Зал Храбрецов",s="Зал Храбрецов — большие казармы воинов на восточных высотах Аллеи Чести в Оргриммаре. Это главный учебный лагерь и дом гильдии для бойцов переднего края Орды, инструкторов и распорядителей боев.",h="Зал Храбрецов — большие казармы воинов на восточных высотах Аллеи Чести в Оргриммаре.",kw={"barracks","battlemaster","hall of the brave","orgrimmar","valley of honor","warrior trainer","warriors guild","казармы","распорядитель боев","зал храбрецов","оргриммар","аллея чести","учитель воинов","гильдия воинов"},ang={["class:Warrior"]="Зал Храбрецов — ваш воинский дом в столице: в нем находятся наставники, открывающие продвинутые стойки и боевые приемы по мере роста вашего мастерства.",["faction:Horde"]="Эти казармы — живая демонстрация дисциплины передовых войск Орды: в них находятся распорядители боев, собирающие войска для сражений по всему континенту."},sec={{t="Бастион воинов",b="Зал Храбрецов, возвышающийся над спокойными водами и тренировочными площадками Аллеи Чести, служит важным военным центром для растущей Орды. Внутри опытные офицеры и закаленные воины обучают новобранцев суровым основам ближнего боя, владению стойками и дисциплине. Зал уставлен тренировочными манекенами и оружием, и в нем находятся распорядители боев, организующие бойцов для крупных военных кампаний по всему Азероту."}},faq={{q="Для чего нужен Зал Храбрецов?",a="Это главные казармы и дом гильдии воинов в Оргриммаре. Здесь воины учатся приемам у опытных наставников, оттачивают удары на тренировочных манекенах и советуются с распорядителями боев о военных назначениях в спорных землях.",al={"what is hall of the brave","what is this building","hall of the brave purpose","что такое зал храбрецов","что это за здание","зал храбрецов назначение"}},{q="Где в Оргриммаре находится зал?",a="Зал Храбрецов расположен на восточной стороне Аллеи Чести, среди красных стен каньона над центральным прудом долины.",al={"where is hall of the brave","hall of the brave location","find warrior trainer orgrimmar","где зал храбрецов","зал храбрецов расположение","найти учителя воинов оргриммар"}},{q="Кого можно найти внутри зала?",a="The hall houses various warrior class trainers, battlemasters coordinating large-scale conflicts, and Horde grunts resting between active patrols.",al={"who is in hall of the brave","hall of the brave npcs","кто в зале храбрецов","зал храбрецов персонажи"}}},fp="17,246,21.443.0,45.254.0,39.151.0,33.146.0"}
P.entries["subzone:hammerfall"] = {n="Павший Молот",s="Павший Молот — главный укрепленный форпост Орды на Нагорье Арати, построенный на руинах печально известного лагеря для военнопленных Альянса. Он назван в честь легендарного бывшего вождя Оргрима Молота Рока, павшего неподалеку в борьбе за освобождение своего плененного народа. Сегодня орки и Отрекшиеся защищают поселение от враждебных огров Тяжелого Кулака, троллей Сухокожих и Лиги Аратора.",h="Павший Молот — главный укрепленный форпост Орды на Нагорье Арати, построенный на руинах печально известного...",kw={"arathi highlands","boulderfist","defilers","hammerfall","internment camp","orgrim doomhammer","thrall","witherbark","нагорье арати","тяжелый кулак","осквернители","павший молот","лагерь для военнопленных","оргрим молот рока","тралл","сухокожие"},ang={["faction:Horde"]="Павший Молот, окруженный враждебными ограми, лесными троллями и остатками Альянса, — единственная крепость Орды, обеспечивающая контроль над центральной частью Нагорья Арати.",["race:Orc"]="Для орков Павший Молот — священная земля: здесь Оргрим Молот Рока отдал жизнь, освобождая плененных соплеменников, и передал бремя вождя Траллу."},sec={{t="Наследие освобождения",b="После Второй войны люди Альянса построили по всему Лордерону огромные лагеря для содержания побежденных орков. Лагерь, стоявший здесь, был одним из крупнейших. Спустя годы Тралл и Оргрим Молот Рока напали на лагерь, чтобы освободить вялых пленников. Во время хаотичного отступления атаковавший рыцарь Альянса пронзил копьем наспинник Молота Рока, смертельно ранив легендарного Вождя. После Третьей войны новая Орда вернула разрушенные земли и основала здесь форпост, назвав его Павшим Молотом в память о погибшем предводителе."},{t="Опорный пункт на нагорье",b="Сегодня Павший Молот служит для Орды путем жизни в Арати. Гарнизон, окруженный враждебными землями, сражается с агрессивными ограми Тяжелого Кулака из Камен'гора и Крепости Тяжелого Кулака, а также с местными троллями Сухокожих. Кроме того, Осквернители из числа Отрекшихся сделали форпост плацдармом, чтобы захватить спорные ресурсы Низины Арати у Лиги Аратора, союзной Альянсу."}},faq={{q="Почему эта база называется Павший Молот?",a="Она названа в честь бывшего вождя Оргрима Молота Рока, который был смертельно ранен на этой земле копьем рыцаря Альянса во время освобождения лагеря для пленных орков.",al={"why hammerfall","hammerfall name origin","who died at hammerfall","почему павший молот","происхождение названия павший молот","кто погиб в павшем молоте"}},{q="Чем был Павший Молот до того, как Орда его отстроила?",a="Это был один из крупнейших лагерей Альянса Лордерона, построенный после Второй войны для содержания пленных орков.",al={"hammerfall history","what was hammerfall before","internment camp arathi","история павшего молота","чем был павший молот раньше","лагерь для военнопленных арати"}},{q="Кто сейчас руководит обороной Павшего Молота?",a="Обороной форпоста руководят такие представители Орды, как Драм Желчный и Сальный: они направляют воинов против наступающих огров Тяжелого Кулака и лесных троллей Сухокожих.",al={"hammerfall leaders","who is in charge of hammerfall","tallow drum fel","руководители павшего молота","кто главный в павшем молоте","сальный драм желчный"}},{q="Почему здесь размещены Отрекшиеся?",a="Осквернители из числа Отрекшихся действуют из Павшего Молота, чтобы добывать жизненно важные припасы в Низине Арати и противостоять Лиге Аратора, союзной Альянсу.",al={"forsaken hammerfall","why are undead in hammerfall","defilers arathi","отрекшиеся павший молот","почему нежить в павшем молоте","осквернители арати"}}},fp="10,390,22.578.0,27.405.0,35.178.0,48.124.0,46.163.0,36.140.0"}
P.entries["subzone:harborage"] = {n="Убежище",s="Убежище — тихое поселение изгнанников из числа уроженцев Дренора на севере Болота Печали. Многие их собратья, пораженные недугом, блуждают по окрестным топям и поддались безумию и первобытной злобе, но обитатели Убежища сумели сохранить рассудок и ясность ума. Они осторожно живут у кромки воды, ища покоя среди сурового и безжалостного захолустья.",h="Убежище — тихое поселение изгнанников из числа уроженцев Дренора на севере Болота Печали.",kw={"broken","draenethyst","harborage","lost ones","magtoor","swamp of sorrows","сломленные","дренетист","убежище","потерянные","магтур","болото печали"},ang={["faction:Alliance"]="Для путников Альянса, спускающихся из безопасного Красногорья в опасные болота, Убежище — одно из немногих мест на севере топи, где встречают не враждебными лицами, а без немедленного кровопролития.",["faction:Horde"]="Присутствие Орды в Каменоре в основном определяет жизнь болота, но эти замкнутые уцелевшие ведут собственное уединенное существование, держась особняком и не принимая ничью сторону в региональных конфликтах."},sec={{t="Приют в трясине",b="Убежище, притаившееся у северных гор Болота Печали, резко отличается от диких племен, бродящих по соседним водам. Этот небольшой лагерь из грубых кожаных шатров, украшенных загадочными подвешенными кристаллами, дает приют изгнанным уцелевшим дренорцам, отказавшимся сдать свой разум. Под руководством старейшин, таких как Магтур, они поддерживают хрупкий цивилизованный оплот, оставаясь настороже перед враждебной глушью, местными хищниками и дикими племенами своих павших братьев, затаившимися сразу за границей поселения."}},faq={{q="Кто живет в Убежище?",a="Убежище — дом для группы изгнанников Дренора: пораженных недугом гуманоидов, попавших в Азерот и сумевших сохранить разум и культуру, в отличие от диких племен в других частях болота.",al={"harborage residents","who is at harborage","who lives here","жители убежища","кто в убежище","кто здесь живет"}},{q="Почему здешние жители мирные, а другие болотные племена нападают?",a="Здешние жители сохранили рассудок и здравое мышление, несмотря на трагические телесные изменения и изгнание. Пока их пораженные недугом собратья по всему болоту теряли разум от одиночества и потрясений, обитатели Убежища сплотились, чтобы сохранить достоинство.",al={"why are they friendly","lost ones friendly","harborage hostile","почему они дружелюбны","потерянные дружелюбны","убежище враждебно"}},{q="Кто возглавляет Убежище?",a="Община полагается на уважаемых старейшин, таких как Магтур, ища у них руководства и совета в борьбе за выживание на чуждом болоте.",al={"harborage leader","magtoor","chief of harborage","предводитель убежища","магтур","вождь убежища"}},{q="Где находится Убежище?",a="Вы найдете его у северных утесов Болота Печали, к востоку от горного прохода, соединяющего топь с Красногорьем.",al={"harborage location","where is harborage","find harborage","где находится убежище","где убежище","найти убежище"}}},fp="9,401,19.591.0,27.199.0,65.274.0,24.125.0,31.154.0"}
P.entries["subzone:hearthglen"] = {n="Дольный Очаг",s="Дольный Очаг — укрепленное поселение в северных холмах Западных Чумных земель, чудом избежавшее полного физического разрушения при падении Лордерона. Сегодня его прочные каменные стены, башни и окружающие фермерские земли служат главным северным оплотом и тренировочной площадкой фанатичного Алого ордена.",h="Дольный Очаг — укрепленное поселение в северных холмах Западных Чумных земель, чудом избежавшее полного...",kw={"andorhal","hearthglen","mardenholde","scarlet crusade","taelan fordring","tirion fordring","western plaguelands","андорал","дольный очаг","марденхольд","алый орден","телан фордринг","тирион фордринг","западные чумные земли"},ang={["class:Paladin"]="Дольный Очаг был домом Тириона Фордринга и стал приютом для остатков Серебряной Длани после падения Лордерона. Пройдя по его подступам, понимаешь, насколько трагичным был раскол ордена и его превращение в фанатичный Алый орден.",["race:Undead"]="Для Отрекшихся Дольный Очаг — смертоносная заноза на севере. Размещенные здесь рыцари питают абсолютную, пылающую ненависть к нежити и активно патрулируют местность, уничтожая любых разведчиков, идущих на север от Андорала."},sec={{t="Бастион среди порчи",b="Пока соседний Андорал лежит в руинах, Дольный Очаг все еще похож на живой город Лордерона: здесь есть лесопилка, сторожевые башни, конюшни и работающий рудник. Исторически им правил из Крепости Марденхольд лорд Тирион Фордринг, и Дольный Очаг славился процветанием и стойкой обороной во время Второй войны. Когда во время Третьей войны Чума нежизни охватила Лордерон, принц Артас Менетил перехватил здесь зараженное зерно, очистил город от пораженных жителей и вместе с Утером Светоносным отразил мощную осаду Плети. Благодаря этому отчаянному вмешательству могучие стены Дольного Очага уцелели."},{t="Под Алым знаменем",b="После того как Серебряная Длань распалась вслед за крушением королевства, сын Тириона Телан Фордринг открыл Дольный Очаг как убежище для уцелевших паладинов. Однако горе и фанатизм, породившие Алый орден, вскоре поглотили крепость. Теперь Дольный Очаг — оплот религиозного экстремизма. Алые рыцари патрулируют подходы и несут стражу на стенах, жестоко казня любого чужака, живого или нежить, вторгшегося на их землю. Верховный лорд Телан Фордринг правит из Крепости Марденхольд, преданный слуга непримиримой войны ордена против Чумных земель."}},faq={{q="Почему Дольный Очаг выглядит таким чистым по сравнению с остальными Чумными землями?",a="Дольный Очаг избежал полного разрушения во время Третьей войны благодаря принцу Артасу и Утеру Светоносному, которые прибыли как раз вовремя, чтобы убить первых жертв чумы и сломить огромную осаду Плети. Позже Алый орден сильно укрепил перевал и долину и постоянно уничтожал наступающую Плеть, не давая порче захватить город.",al={"why is hearthglen intact","hearthglen not destroyed","hearthglen alive","почему дольный очаг цел","дольный очаг не разрушен","дольный очаг жив"}},{q="Кто контролирует Дольный Очаг сейчас?",a="Дольным Очагом владеет Алый орден. Им командует из Крепости Марденхольд верховный лорд Телан Фордринг, сын прежнего лорда и знаменитого паладина Тириона Фордринга.",al={"who rules hearthglen","hearthglen leader","who is in charge of hearthglen","кто правит дольным очагом","предводитель дольного очага","кто главный в дольном очаге"}},{q="Дружелюбен ли Дольный Очаг к посетителям из Альянса и Орды?",a="Нет. Алый орден относится ко всем чужакам с крайней враждебностью и паранойей. Представителей Орды считают чудовищными порождениями, а нейтральных путников из Альянса объявляют разносчиками чумы или еретиками, обреченными на немедленную казнь на месте.",al={"can i go to hearthglen","is hearthglen hostile","hearthglen safe","можно ли в дольный очаг","дольный очаг враждебен","дольный очаг безопасен"}},{q="Что случилось с Тирионом Фордрингом?",a="За годы до Третьей войны Тирион был лишен титула и отлучен Альянсом за защиту благородного орка по имени Эйтригг. Изгнанный в глушь, Тирион был вынужден покинуть Дольный Очаг, и командование Марденхольдом со временем перешло к его сыну Телану.",al={"where is tirion","tirion hearthglen history","why isn't tirion here","где тирион","история тириона в дольном очаге","почему тириона нет здесь"}}},fp="10,343,23.652.0,24.585.0,74.349.0,34.165.0,53.253.0,33.273.0"}
P.entries["subzone:helm-s-bed-lake"] = {n="Озеро Хельмово Ложе",s="Озеро Хельмово Ложе — замерзшее озеро в юго-восточных холмах Дун Морога. Поддерживаемая прорубь в толстом льду дает местным горцам и путникам жизненно важную пресную воду. Однако берег вокруг стал опасным из-за рыщущих зверей, наступающих троггов и враждебных лазутчиков Черного Железа.",h="Озеро Хельмово Ложе — замерзшее озеро в юго-восточных холмах Дун Морога.",kw={"dark iron","dun morogh","helm's bed lake","ice hole","narm faulk","trogg","черное железо","дун морог","озеро хельмово ложе","прорубь","нарм фолк","трогг"},ang={["faction:Alliance"]="Разведчикам Альянса, идущим на восток к Лок Модану, нужно быть здесь начеку: южная тропа проходит неприятно близко к засадам агрессивных дворфов Черного Железа.",["race:Dwarf"]="Для дворфов Стальгорна озеро Хельмово Ложе — и важный источник пресной воды, и досадный провал безопасности: диверсанты Черного Железа и трогги проникают все глубже в сердце Дун Морога."},sec={{t="Коварный берег",b="Озеро Хельмово Ложе тихо лежит под толстым зимним льдом в юго-восточной части Дун Морога. Местные дворфы держат во льду прорубь, чтобы набирать чистую пресную воду. Пересекать замерзшее пространство довольно безопасно, но задерживаться у берегов становится все рискованнее. По краям бродят дикие звери, по хребтам рыщут изгнанные из своих земель трогги, а отряд враждебных дворфов Черного Железа занял заброшенную хижину к югу от озера и яростно устраивает засады на всех проходящих путников."}},faq={{q="Почему посреди замерзшего озера есть прорубь?",a="Прорубь в толстом льду намеренно поддерживают местные дворфы, чтобы иметь постоянный доступ к свежей, незамерзшей воде в морозном климате Дун Морога.",al={"ice hole","water access","why is the ice broken","прорубь","доступ к воде","почему лед разбит"}},{q="Какие опасности таятся вокруг озера Хельмово Ложе?",a="Хотя сама поверхность озера прочна, по берегам охотятся хищные звери и забредшие трогги. На юге лагерь враждебных дворфов Черного Железа занимает старое здание и жестоко отгоняет всех, кто приближается.",al={"threats at helms bed lake","who is attacking here","enemies nearby","угрозы у озера хельмово ложе","кто здесь нападает","враги поблизости"}},{q="Кто такой Нарм Фолк?",a="Нарм Фолк — несчастный дворф, чье тело можно найти на берегу озера Хельмово Ложе: мрачная жертва внезапного роста враждебных угроз и лазутчиков Черного Железа в этой местности.",al={"narm faulk corpse","dead dwarf near lake","dead body at helms bed lake","нарм фолк тело","мертвый дворф у озера","труп у озера хельмово ложе"}},{q="Занимают ли дворфы Черного Железа озеро официально?",a="Само озеро они не захватили, но вооруженный отряд занял заброшенное строение к югу от него и использует его как передовую позицию для стычек в центральной части Дун Морога.",al={"dark irons at the lake","dark iron dwarf lodge","черное железо у озера","хижина дворфов черного железа"}}},fp="15,328,23.514.0,59.157.0,41.227.0,18.193.0,56.188.0"}
P.entries["subzone:heroes-vigil"] = {n="Часовые Вечности",s="Часовые Вечности — тихая священная поляна на центральном острове посреди Озера Каменных Столбов в восточной части Элвиннского леса. В ее центре стоит памятник, известный как Камень Памяти, посвященный павшим в Первой войне. Однако сегодня Штормград почти забросил это святилище, и им завладели опасные волшебники-отступники.",h="Часовые Вечности — тихая священная поляна на центральном острове посреди Озера Каменных Столбов в восточной...",kw={"elwynn forest","henze faulk","heroes vigil","heroes' vigil","rogue wizards","stone cairn lake","stone of remembrance","элвиннский лес","хенз фолк","часовые вечности","волшебники-отступники","озеро каменных столбов","камень памяти"},ang={["class:Mage"]="Волшебники-отступники, расположившиеся на этой священной земле, практикуют опасные, неконтролируемые искусства без дисциплины и одобрения Академии тайных наук.",["race:Human"]="Для людей Штормграда это священное каменное кольцо — горькое напоминание о кровавой цене Первой войны и о том, что королевство теперь не сумело защитить собственное наследие."},sec={{t="Забытый памятник",b="Часовые Вечности были возведены после Первой войны вокруг Камня Памяти — каменного круга с надписями, почитающего солдат и жителей, убитых при разорении Златоземья и окрестных долин Старой Ордой. Когда-то их чтили как священный оплот веры и самопожертвования, но нынешние правители Штормграда постепенно перестали уделять им внимание, и священная земля заросла и осталась без охраны солдат королевства."},{t="Во власти отступников",b="Поскольку королевство оставило остров без гарнизона, памятник захватили изгои. Шайка волшебников-отступников теперь владеет Озером Каменных Столбов и землей вокруг памятника и практикует дикую, недисциплинированную магию вдали от надзора Кирин-Тора и Академии тайных наук. Осквернение выглядит еще горше из-за трагических жертв у камней, среди которых тело Хенза Фолка, и путники гадают, вернется ли святилищу покой."}},faq={{q="Что такое Часовые Вечности?",a="Часовые Вечности — памятник на острове посреди Озера Каменных Столбов в восточной части Элвиннского леса. Он состоит из каменного кольца и мемориала, посвященных памяти жертв Первой войны.",al={"heroes vigil","what is heroes vigil","island shrine elwynn","часовые вечности","что такое часовые вечности","святилище на острове элвиннский лес"}},{q="Что увековечивает Камень Памяти?",a="Камень Памяти установлен в память о павших жителях и защитниках, погибших, когда орки из Орды разорили Златоземье и опустошили восточную часть Элвиннского леса во время Первой войны.",al={"stone of remembrance","monument meaning","what is the stone of remembrance","камень памяти","значение памятника","что такое камень памяти"}},{q="Кто сегодня контролирует Часовых Вечности?",a="Остров и Часовых Вечности захватили враждебные маги-отступники. Эти чародеи действуют вне закона Королевства Штормград и вне надзора признанных магических учреждений.",al={"who is at heroes vigil","heroes vigil enemies","wizards on lake","кто у часовых вечности","враги у часовых вечности","волшебники на озере"}},{q="Почему Штормград забросил Часовых Вечности?",a="Король Вариан Ринн пропал, а королевство перегружено борьбой с внутренними раздорами, разбойниками и нашествиями чудовищ, поэтому отдаленные святилища вроде Часовых Вечности остались без защиты и почти забыты правящим регентским советом.",al={"why is it abandoned","why did stormwind forget it","forgotten shrine","почему оно заброшено","почему штормград забыл о нем","забытое святилище"}},{q="Кто такой Хенз Фолк?",a="Хенз Фолк — погибший путник, чье бездыханное тело лежит возле памятника, печальное свидетельство беспощадной враждебности волшебников-отступников, занявших остров.",al={"henze faulk body","who is the dead guy on the island","тело хенза фолка","кто мертвец на острове"}}},fp="13,356,20.458.0,20.488.0,22.195.0,47.190.0,33.201.0,38.225.0,19.180.0"}
P.entries["subzone:hetaera-s-clutch"] = {n="Гнездо Хетайры",s="Гнездо Хетайры — затонувший храм ночных эльфов, посвященный Элуне, лежащий глубоко под бурными водами Залива Бурь в Азшаре. Некогда священное место поклонения, ныне затопленные руины кишат смертоносными гидрами, выведенными их матерью, Хетайрой. Искатели приключений, отважившиеся спуститься в глубины, найдут древнюю каменную кладку во власти свирепых морских хищников.",h="Гнездо Хетайры — затонувший храм ночных эльфов, посвященный Элуне, лежащий глубоко под бурными водами Залива...",kw={"azshara","bay of storms","elune","hetaera","hetaera's clutch","hetaeras clutch","hydra","sunken temple","temple of elune","азшара","залив бурь","элуна","хетайра","гнездо хетайры","гидра","затонувший храм","храм элуны"},ang={["class:Druid"]="Друидам, исследующим глубины Залива Бурь в водной форме, следует быть осторожными: гидры, завладевшие этим древним святилищем, крайне враждебны к незваным гостям.",["race:NightElf"]="Для ночных эльфов вид священного святилища Элуны, затопленного и оскверненного под гнездо диких гидр, — болезненное напоминание о цивилизации, разрушенной во время Раскола."},sec={{t="Затонувшее святилище",b="До Великого Раскола, разорвавшего древний Калимдор, это строение было величественным храмом, посвященным лунной богине Элуне. Низвергнутые в глубины Залива Бурь, его каменные колонны и священные залы десять тысяч лет провели под водой. Сегодня все следы благоговейного почитания поглотили приливы, оставив лишь суровый памятник утраченной империи кальдораев."},{t="Владения матери выводка",b="Затопленное святилище стало гораздо опаснее: теперь это место гнездования Хетайры, огромной многоголовой гидры, что рыщет в прибрежных водах и среди скалистых островков. Ее многочисленное потомство, Отродья Хетайры, бродит по разрушенным аркам и коридорам затонувшего храма и нападает на любого обитателя суши, осмелившегося нырнуть в залив."}},faq={{q="Для чего изначально построено Гнездо Хетайры?",a="Задолго до того как уйти под воду, это строение было великолепным храмом, посвященным лунной богине Элуне. Его построили на пике могущества древней империи ночных эльфов, а во время Великого Раскола оно было низвергнуто в океан.",al={"what is hetaeras clutch","what was this temple","hetaera clutch lore","что такое гнездо хетайры","что это был за храм","предания гнезда хетайры"}},{q="Где находится Гнездо Хетайры?",a="Гнездо лежит глубоко под водой в Заливе Бурь, у неровного южного побережья Азшары.",al={"where is hetaeras clutch","hetaera clutch location","how to find hetaera clutch","где гнездо хетайры","расположение гнезда хетайры","как найти гнездо хетайры"}},{q="Кто такая Хетайра?",a="Хетайра — свирепая трехглавая гидра, рыщущая в водах Азшары. Ее детеныши заполонили сам затонувший храм, а сама Хетайра обычно плавает чуть севернее Гнезда или греется на ближайших прибрежных островках.",al={"who is hetaera","where is hetaera","what is hetaera","кто такая хетайра","где хетайра","что такое хетайра"}},{q="Какие существа обитают в затопленных руинах?",a="Затонувшие залы кишат выводком Хетайры — свирепыми морскими гидрами, которые защищают свое гнездо от любых чужаков, подплывших слишком близко.",al={"what mobs are in hetaeras clutch","what lives in hetaera clutch","какие монстры в гнезде хетайры","кто живет в гнезде хетайры"}}},fp="16,357,19.389.0,25.356.0,47.240.0,34.108.0,15.238.0,43.152.0"}
P.entries["subzone:hidden-grove"] = {n="Сокрытая роща",s="Сокрытая роща — уединенная кратерная котловина, скрытая за высокими утесами на северо-востоке Зимних Ключей. Некогда мирное убежище арктических зайцев, ныне она перешла во владения свирепо охраняющих территорию диких лунных сов.",h="Сокрытая роща — уединенная кратерная котловина, скрытая за высокими утесами на северо-востоке Зимних Ключей.",kw={"crater","hares","hidden grove","moonkin","winterspring","кратер","зайцы","сокрытая роща","лунные совы","зимние ключи"},ang={["class:Druid"]="Лунные совы, гнездящиеся в кратере, — мрачное напоминание о дикой, необузданной природе, ставшей яростно обороняющейся, и они вызывают глубокий духовный интерес у последователей равновесия."},sec={{t="Уединенное убежище",b="Сокрытая роща, защищенная от пронизывающих воющих ветров Зимних Ключей, представляет собой провалившийся, припорошенный снегом лесной кратер, в который почти невозможно попасть со внешних утесов. Путники, нашедшие его скрытый край, должны отважиться на крутой опасный спуск или пройти по узкому пещерному ходу в юго-восточном хребте. Долина долго была нетронутым домом безобидных белых зайцев, но агрессивные дикие лунные совы заняли поляну и превратили уединенный природный рай в западню для неосторожных странников."}},faq={{q="Как попасть в Сокрытую рощу?",a="Самый безопасный путь в рощу — через скрытую пещеру в юго-восточной стене окружающих утесов. Теоретически можно спрыгнуть вниз по крутому краю утеса сверху, но это сопряжено с высоким риском смертельного падения.",al={"how to enter hidden grove","hidden grove entrance","where is the cave","как попасть в сокрытую рощу","вход в сокрытую рощу","где пещера"}},{q="Какие существа живут в Сокрытой роще?",a="Кратер заполонили дикие враждебные лунные совы, ревностно охраняющие уединенную долину. Пока они не поселились здесь, поляна славилась как мирное убежище, где жили почти одни безобидные белые зайцы.",al={"what is in hidden grove","hidden grove mobs","who lives here","что в сокрытой роще","монстры сокрытой рощи","кто здесь живет"}},{q="Где в Зимних Ключах находится эта роща?",a="Сокрытая роща лежит на крайнем северо-востоке Зимних Ключей, целиком в изолированной чаше высоких каменных утесов.",al={"hidden grove location","where is hidden grove","расположение сокрытой рощи","где сокрытая роща"}}},fp="12,228,20.519.0,37.262.0,40.222.0,44.136.0"}
P.entries["subzone:hidden-path"] = {n="Потайная тропа",kw={"barrens","durotar","hidden path","shaman","spirit rock","valley of trials","степи","дуротар","потайная тропа","шаман","священный камень","долина испытаний"},ang={["class:Shaman"]="Потайная тропа — ваше первое настоящее физическое и духовное восхождение, проверяющее вашу наблюдательность, прежде чем вы начнете общаться с духами земли у Священного Камня.",["faction:Horde"]="Хотя эта тропа священна для шаманов, этот неукрепленный проход — слепое пятно в безопасности над Долиной Испытаний, требующее бдительного присмотра."},sec={{t="Священное восхождение",b="Потайная тропа, вырубленная в красных пиках вокруг Долины Испытаний, намеренно трудна для обнаружения с земли каньона. Наставники направляют сюда молодых шаманов, чтобы те доказали свою наблюдательность и дисциплину, прежде чем общаться с духами у Священного Камня. На самых высоких участках тропы путникам открываются широкие панорамы на запад, к холмистым саваннам Степей."},{t="Стратегическая уязвимость",b="Помимо духовного значения, тропа опасно прорезает природные укрепления, окружающие долину. Низкий перевал на ее пути образует прямой черный ход к Кабестану и дороге на Оргриммар. Поскольку она обходит обычные каньонные заставы, бдительные защитники опасаются, что дерзкие лазутчики Альянса смогут воспользоваться этой тихой тропой и проникнуть прямо на главный учебный полигон Орды."}},faq={{q="Куда ведет Потайная тропа?",a="Тропа поднимается из Долины Испытаний в скалы к Священному Камню, священному месту, где шаманы общаются со стихиями. Она также вьется по горным перевалам, ведущим к Степям и побережью.",al={"hidden path destination","where does hidden path go","hidden path leads to","куда ведет потайная тропа","назначение потайной тропы","потайная тропа ведет"}},{q="Чем тропа важна для шаманов?",a="Начинающим шаманам в Долине Испытаний поручено найти эту уединенную тропу в рамках первых стихийных испытаний. Поднявшись по ней, они достигают Священного Камня и пьют сапту, необходимую для общения с духами.",al={"shaman path valley of trials","spirit rock path","shaman quest path","тропа шаманов долина испытаний","путь к священному камню","задание шамана тропа"}},{q="Могут ли враги использовать Потайную тропу для нападения на Долину Испытаний?",a="Да. Низкие проходы на тропе обходят обычные охраняемые входы в долину. Хитрый отряд Альянса, идущий из Кабестана или с побережья, теоретически мог бы пройти по тропе мимо разведчиков Орды и незамеченным проникнуть на учебную территорию.",al={"hidden path alliance invasion","is valley of trials vulnerable","valley of trials back door","вторжение альянса потайная тропа","уязвима ли долина испытаний","черный ход долины испытаний"}},{q="Что можно увидеть с вершины тропы?",a="В самой высокой точке тропа открывает ясный, возвышенный вид на запад, на обширные равнины Степей, а также широкий вид на красные каньоны Дуротара.",al={"hidden path view","lookout point hidden path","вид с потайной тропы","смотровая площадка потайная тропа"}}},fp="11,276,15.419.0,23.422.0,32.217.0,38.238.0,65.250.0,42.174.0"}
P.entries["subzone:high-rise"] = {n="Высокая вершина",s="Высокая вершина — верхний ярус центральной мезы Громового Утеса, венчающий столицу таурен. Здесь расположены оживленный амфитеатр с общим костром, опытные мастера, торговцы оружием и мастера кулинарии. В отличие от нижних ярусов, эта вершина сообщается с остальным городом только по подвесным веревочным мостам и через насест наездников на ветрокрылах.",h="Высокая вершина — верхний ярус центральной мезы Громового Утеса, венчающий столицу таурен.",kw={"amphitheater","aska's kitchen","bonfire","high rise","mulgore","thunder bluff","wind rider roost","амфитеатр","кухня аски","костер","высокая вершина","мулгор","громовой утес","насест наездников на ветрокрылах"},ang={["profession:Cooking"]="На Высокой вершине находятся Кухня Аски и известные мастера барбекю, поэтому это главное место в Громовом Утесе, где можно оттачивать кулинарное мастерство на открытом огне.",["race:Tauren"]="Высокая вершина — венец вашей столицы, воплощение единства племен: вокруг ее высокого общего костра собираются охотники, шаманы и старейшины."},sec={{t="Вершина мезы",b="Высокая вершина расположена на главном плато Громового Утеса, где открытые ветра гуляют высоко над холмистыми равнинами Мулгора. Это главное место сбора объединенных племен: в центре находятся открытый амфитеатр и очаг, где жители слушают важные объявления племени и судьбоносные решения. В окружающих шатрах и деревянных лавках работают известные торговцы, оружейники и учителя кулинарии, среди них Кухня Аски и Горная рыбалка. Нижние ярусы соединены с прерией Мулгора огромными деревянными подъемниками, а Высокая вершина остается в вышине: сюда можно попасть в основном через насест наездников на ветрокрылах и подвесные мосты, ведущие к соседним Вершине Старейшин и Вершине Охотников."}},faq={{q="Как добраться до Высокой вершины?",a="До Высокой вершины можно добраться через центральное гнездовье наездников на ветрокрылах с нижних ярусов или по подвесным мостам от Вершины Старейшин и Вершины Охотников. Прямого подъемника с равнин Мулгора на этот ярус нет.",al={"how to get to high rise","high rise access","getting up to high rise","как попасть на высокую вершину","доступ на высокую вершину","подъем на высокую вершину"}},{q="Какие услуги есть на Высокой вершине?",a="Этот ярус известен ремесленниками и местами для встреч под открытым небом. Среди заметных заведений — Кухня Аски, где учат готовке, Горная рыбалка со снастями и различные торговцы оружием, например Оружейная Горнего Гнева и Огнестрельное оружие Громового Копыта.",al={"trainers on high rise","shops high rise","what is on high rise","учителя на высокой вершине","магазины высокая вершина","что есть на высокой вершине"}},{q="Для чего используется амфитеатр на Высокой вершине?",a="Открытый амфитеатр окружает центральный костер и служит общим местом сбора. Здесь таурены собираются под открытым небом, чтобы услышать новости, обсудить дела племени и стать свидетелями важных объявлений на вершине мезы.",al={"high rise bonfire","high rise auditorium","tauren meeting place","костер высокой вершины","аудитория высокой вершины","место собраний таурен"}}},fp="9,350,18.713.0,31.224.0,41.258.0,51.248.0"}
P.entries["subzone:high-seat"] = {n="Высокий трон",s="Высокий трон — величественный тронный зал Стальгорна, расположенный между Общинным кварталом и Великой кузней. Из этого возвышенного зала король Магни Бронзобород правит королевством дворфов вместе со своими королевскими советниками и историками. В зале также находится запечатанный проход, ведущий вниз, в древние глубины Старого Стальгорна.",h="Высокий трон — величественный тронный зал Стальгорна, расположенный между Общинным кварталом и Великой кузней.",kw={"archesonus","barin redstone","bronzebeard","high seat","ironforge","magni","throne","аркессон","борин краснокамень","бронзобород","высокий трон","стальгорн","магни","трон"},ang={["faction:Alliance"]="Как резиденция власти дворфов, этот зал имеет решающее значение для снабжения и стратегии высшего уровня Альянса: в нем размещаются посланники, советники и королевские указы.",["race:Dwarf"]="Высокий трон олицетворяет непрерывную преемственность суверенитета Каз Модана, где король Магни Бронзобород по-прежнему ведет свой народ железной волей."},sec={{t="Сердце власти дворфов",b="Высокий трон, возвышающийся над шумными оживленными кольцами Стальгорна, служит королевской резиденцией власти королевства Каз Модан. В этом сводчатом зале король Магни Бронзобород принимает просителей, совещается с советниками и руководит обороной северных бастионов Альянса. По бокам от трона стоят королевские сановники, такие как Королевский историк Аркессон и Сенатор Борин Краснокамень. Высокий трон остается символом непреклонной власти Бронзобородов и стойкости дворфов в тревожные времена, охватившие Азерот."},{t="Врата в Старый Стальгорн",b="За величественным каменным убранством тронного зала находится тяжелая дверь, ведущая в сумрачные просторы Старого Стальгорна. Эти нижние руины — первоначальные, исконные залы, высеченные дворфами до того, как город перестроили вокруг Великой кузни. Охраняемый и закрытый для всеобщего прохода вход напоминает посетителям о глубокой древности и пещерной истории, покоящейся под камнями современной столицы."}},faq={{q="Кто правит с Высокого трона?",a="Король Магни Бронзобород правит Стальгорном с трона в Высоком троне. Он ведет дела клана Бронзобородов, выслушивает подданных и координирует военные и дипломатические вопросы с Великим Альянсом.",al={"who is on the throne","ironforge king","magni throne room","кто на троне","король стальгорна","тронный зал магни"}},{q="Где в Стальгорне находится Высокий трон?",a="Зал расположен в центре Стальгорна и напрямую соединен с внешним кольцом между Общинным кварталом и Великой кузней, что обеспечивает легкий доступ для горожан и посланников.",al={"where is high seat","find high seat","throne room location","где высокий трон","найти высокий трон","расположение тронного зала"}},{q="Что за запечатанный коридор в глубине тронного зала?",a="Большая арка в задней части Высокого трона ведет в Старый Стальгорн — пещерные древние руины, лежащие прямо под современным горным городом. Доступ в эти нижние проходы по-прежнему ограничен.",al={"door behind magni","old ironforge door","high seat basement","дверь за магни","дверь в старый стальгорн","подвал высокого трона"}},{q="Кого еще можно найти здесь среди советников короля?",a="Королю Магни прислуживают видные дворфы, в том числе Королевский историк Аркессон, хранящий записи и реликвии династии Бронзобородов, и Сенатор Борин Краснокамень.",al={"high seat npcs","magni advisors","персонажи высокого трона","советники магни"}}},fp="9,328,21.515.0,24.426.0,29.218.0,44.179.0,59.205.0,45.184.0"}
P.entries["subzone:high-wilderness"] = {n="Высокогорные дебри",s="Высокогорные дебри — обширный дикий участок первобытного леса, покрывающий большую часть западного Фераласа. Граничат с Рекой Вердантис на востоке и Забытым берегом на западе. Под высоким изумрудным пологом здесь обитают разнообразные животные, бродячие древни и опасные звери.",h="Высокогорные дебри — обширный дикий участок первобытного леса, покрывающий большую часть западного Фераласа.",kw={"feralas","forgotten coast","high wilderness","hippogryphs","treants","verdantis river","yetis","фералас","забытый берег","высокогорные дебри","гиппогрифы","древни","река вердантис","йети"},ang={["class:Druid"]="Вековые древни и яркая живность Высокогорных дебрей показывают природную первозданную мощь Калимдора, не тронутую цивилизацией восточных земель.",["class:Hunter"]="Густые популяции свирепых медведей, волков и диких гиппогрифов делают Высокогорные дебри превосходным местом для оттачивания навыков выслеживания и приручения грозных зверей."},sec={{t="Первобытный полог",b="Высокогорные дебри, раскинувшиеся по западной половине Фераласа, — образец дикой природы южного Калимдора. Густая листва и исполинские деревья закрывают большую часть неба, создавая пышные заросли, где кишат волки, медведи, гиппогрифы и йети. Вековые древни бродят среди корней, а агрессивные кланы огров закрепляются на тенистых полянах. Путешествие по этим зеленым просторам требует бдительности: густой кустарник скрывает и природных хищников, и сохранившиеся первобытные опасности."}},faq={{q="Где находятся Высокогорные дебри?",a="Высокогорные дебри охватывают обширные лесные земли западного Фераласа. Они лежат к западу от Реки Вердантис и тянутся до утесов и берегов у Забытого берега.",al={"high wilderness location","where is high wilderness","high wilderness feralas","расположение высокогорных дебрей","где высокогорные дебри","высокогорные дебри фералас"}},{q="Какие существа бродят в Высокогорных дебрях?",a="В лесу водится множество медведей, волков, гиппогрифов и диких йети. Помимо обычных зверей, путешественники регулярно встречают бродячих древней и агрессивных огров, скрывающихся под пологом леса.",al={"high wilderness wildlife","creatures in high wilderness","beasts feralas","животные высокогорных дебрей","существа в высокогорных дебрях","звери фералас"}}},fp="15,303,21.521.0,37.188.0,40.211.0"}
P.entries["subzone:highperch"] = {n="Скальное гнездовье",s="Скальное гнездовье — возвышенное плато в западной части Тысячи Игл, вздымающееся высоко над дном каньона. Оно известно как главное место гнездования диких виверн и всадников ветра. В гнездовье обитают свирепые стаи, защищающие своих детенышей среди продуваемых ветрами скал.",h="Скальное гнездовье — возвышенное плато в западной части Тысячи Игл, вздымающееся высоко над дном каньона.",ang={["class:Hunter"]="Обширное гнездовье дает опытным охотникам возможность вблизи увидеть, как дикие виверны охотятся и охраняют гнезда в естественной, нетронутой среде обитания.",["faction:Horde"]="Всадники ветра, гнездящиеся в Скальном гнездовье, — близкие родичи благородных летающих скакунов, переносящих Орду по Калимдору, поэтому это убежище внушает трепет героям Орды."},sec={{t="Гнездо виверн",b="Rising sharply out of the canyon floor, Highperch is a rugged sanctuary for Kalimdor's native wyverns. The plateau provides natural defense against predators and an unobstructed launch point for their hunting flights across Thousand Needles. Within its reaches, wyvern prides live under the protection of watchful patriarchs and matriarchs, guarding their nests. The beasts fiercely defend their territory against any intruders who manage to climb into their high domain."},{t="Убежище в вышине",b="While hostile to outsiders, the high cliffs occasionally attract travellers and hunters willing to brave the dangerous ascent. The tauren scout Pao'ka Swiftmountain is stranded on these perilous heights and needs help reaching Whitereach Post. For adventurers journeying through the canyon, scaling the ramp to Highperch means contending with dozens of razor-sharp talons and venomous tails."}},faq={{q="Какие существа живут в Скальном гнездовье?",a="Highperch is inhabited exclusively by wild wyverns and wind riders. You will encounter protective patriarchs, consorts, soaring adults defending their clifftop nests.",al={"highperch beasts","what is at highperch","highperch mobs","звери скального гнездовья","что в скальном гнездовье","монстры скального гнездовья"}},{q="Где находится Скальное гнездовье?",a="Скальное гнездовье расположено в западной части Тысячи Игл. Подняться к нему можно по извилистой тропе от южной стены дна каньона.",al={"highperch location","how to find highperch","where is highperch","расположение скального гнездовья","как найти скальное гнездовье","где скальное гнездовье"}},{q="Чем Скальное гнездовье важно для Орды?",a="Виверны, они же всадники ветра, — важные летающие скакуны Орды: они стали союзниками орков во время Третьей войны. Естественные гнездовья вроде Скального гнездовья олицетворяют дикое наследие и процветающую популяцию этих верных зверей.",al={"horde connection to highperch","wyverns and horde","why do orcs care about highperch","связь орды со скальным гнездовьем","виверны и орда","почему оркам важно скальное гнездовье"}},{q="Кто такой Паока Ходячая Гора?",a="Pao'ka Swiftmountain is a tauren scout stranded amidst the deadly wyvern nests on Highperch. He needs an escort to Whitereach Post.",al={"paoka swiftmountain","tauren at highperch","who got trapped at highperch","паока ходячая гора","таурен в скальном гнездовье","кто застрял в скальном гнездовье"}}},fp="9,260,20.471.0,23.391.0,33.166.0,27.138.0,42.232.0,28.131.0"}
P.entries["subzone:hillsbrad-fields"] = {n="Хилсбрадские поля",s="Хилсбрадские поля охватывают возделанные фермерские земли и простое поселение Хилсбрад в западной части Предгорий Хилсбрада. Это одна из немногих уцелевших человеческих общин в бывшем Лордероне, отказавшихся покориться Плети или присоединиться к фанатичному Алому ордену. Теперь ее фермеры и ополчение постоянно подвергаются нападениям соседних Отрекшихся из Мельницы Таррен.",h="Хилсбрадские поля охватывают возделанные фермерские земли и простое поселение Хилсбрад в западной части...",kw={"battle of hillsbrad","darthalia","farmer getz","farmer ray","hillsbrad","hillsbrad fields","magistrate burnside","southshore","tarren mill","verringtan","битва за хилсбрад","дарталия","фермер гетц","фермер рэй","хилсбрад","хилсбрадские поля","мировой судья бернсайд","южнобережье","мельница таррен","верринган"},ang={["faction:Alliance"]="Хилсбрадские поля — важная житница и яркий символ неугасающего духа Лордерона, заслуживающий защиты от истребления Отрекшимися.",["faction:Horde"]="Верховный палач Дарталия требует систематически уничтожать фермы и ополчение Хилсбрада, чтобы обезопасить южную границу для Отрекшихся."},sec={{t="Непокорный оплот Лордерона",b="Хилсбрадские поля, раскинувшиеся среди садов, тыквенных грядок и пастбищ между Холмом Дарроу и Лазуритовым рудником, поставляют необходимые припасы в Южнобережье и уцелевшему сопротивлению Альянса. Хотя большая часть Лордерона пала от чумы нежити, жители Хилсбрада выстояли и с гордостью сохранили королевский табард и геральдику павшего королевства. Городком, находящимся в постоянной осаде, управляет независимый гражданский орган во главе с мировым судьей Бернсайдом и Советом Хилсбрада. Местный кузнец Верринган и его подмастерья вооружают жителей, чтобы каждый фермер и работник был готов защищать свою землю."},{t="Передовая наступления нежити",b="Плодородные поля — главная цель Верховного палача Дарталии и сил Отрекшихся, закрепившихся в Мельнице Таррен. Видя в процветающем человеческом поселении смертельную угрозу на своем южном фланге, Подгород организовал непрерывные набеги на инфраструктуру общины, нацеленные на посевы, скот, советников и мирных фермеров. В ответ защитники Хилсбрада сформировали закаленное ополчение. Местные землевладельцы, такие как фермер Рэй и фермер Гетц, — далеко не беспомощные крестьяне: они устраивают засады и яростно сражаются с вторжениями нежити, защищая свои дома."}},faq={{q="Почему здесь еще работают живые люди?",a="Хилсбрад и соседнее Южнобережье — одни из очень немногих поселений Лордерона, которые избежали полного уничтожения Плетью во время Третьей войны. В отличие от других выживших, бежавших на юг или присоединившихся к фанатичному Алому ордену, эти жители остались, чтобы заново построить свою жизнь и сохранить родную землю.",al={"why are humans in hillsbrad","who lives in hillsbrad fields","are the farmers alive","почему люди в хилсбраде","кто живет на хилсбрадских полях","живы ли фермеры"}},{q="Кто правит городом и полями?",a="Городом и фермерскими землями управляет мировой судья Бернсайд, которому помогают клерк Гораций Белоконь и Совет Хилсбрада из местной ратуши. Окрестными усадьбами управляют землевладельцы, такие как фермер Рэй и фермер Гетц, а местный кузнец Верринган снаряжает городскую стражу.",al={"who leads hillsbrad","hillsbrad leadership","magistrate of hillsbrad","кто правит хилсбрадом","руководство хилсбрада","магистрат хилсбрада"}},{q="Почему Отрекшиеся нападают на фермы?",a="Верховный палач Дарталия из Мельницы Таррен считает Хилсбрад опасным оплотом Альянса на границе Отрекшихся. Приказы Подгорода велят солдатам разорвать линии снабжения людей: уничтожать запасы еды, убивать скот и устранять городских лидеров, чтобы расчистить путь к господству Отрекшихся в предгорьях.",al={"why forsaken attack hillsbrad","battle of hillsbrad reason","tarren mill attacks","почему отрекшиеся нападают на хилсбрад","причина битвы за хилсбрад","нападения мельницы таррен"}},{q="Что случилось с Хилсбрадом во время Второй войны?",a="Во время Второй войны вождь Оргрим Молот Рока приказал нанести по Хилсбраду сокрушительный удар, чтобы сломить моральный дух людей и одновременно собрать силы Орды в районе Южнобережья. Хилсбрад был разрушен в жестокой демонстрации силы, но Альянс изгнал орков, и город впоследствии отстроили заново.",al={"hillsbrad second war","orcs destroyed hillsbrad","history of hillsbrad fields","хилсбрад вторая война","орки разрушили хилсбрад","история хилсбрадских полей"}}},fp="16,358,30.630.0,32.592.0,47.312.0,35.283.0,41.315.0,49.299.0"}
P.entries["subzone:hive-ashi"] = {n="Улей Аши",s="Улей Аши — обширная колония силитидов, господствующая над северными песками Силитуса. Это один из трех крупных гнезд насекомых в регионе: его извилистые туннели и высокие холмы кишат бесчисленными враждебными рабочими, защитниками и жалоносцами.",h="Улей Аши — обширная колония силитидов, господствующая над северными песками Силитуса.",kw={"cenarion","hive ashi","hive'ashi","silithid","silithus","swarming pillar","кенарий","улей аши","силитид","силитиды","силитус","роящаяся вершина"},ang={["class:Druid"]="Пока Круг Кенария следит за оскверненными песками Силитуса, друидам поручено изучать и подавлять насекомую угрозу, исходящую из Улья Аши, пока она не поглотила природную экосистему.",["faction:Alliance"]="Агенты Альянса, действующие в Силитусе, помогают собирать сведения об Улье Аши, чтобы эти агрессивные рои не угрожали соседним землям на юге Калимдора."},sec={{t="Северный холм",b="Улей Аши, расположенный на севере Силитуса, служит главным ульевым комплексом для вновь возрождающихся роев силитидов. Его хитиновые шпили очерчивают особую территорию среди дюн, отправляя рабочих-собирателей и ядовитых защитников на юг и восток, к Роящейся вершине. Всякий, кто пытается постичь странный, согласованный разум, пробуждающийся в пустынных пустошах, неизбежно приходит прямо в опасные гудящие туннели под этими холмами."},{t="Раскрытая угроза",b="Разведчики Круга Кенария, расквартированные по всему Силитусу, пристально следят за Ульем Аши: они нанимают отважных бойцов, чтобы проредить его ряды и добыть донесения разведки из глубин колонии. Глифы и согласованное поведение, описанные в Аши, говорят о том, что эти с виду безмозглые насекомые обладают жуткой единой волей. По мере роста их числа улей грозит выплеснуться за пределы северного Силитуса, поэтому уничтожение его потомства — первоочередная задача для тех, кто охраняет южные границы."}},faq={{q="Что такое Улей Аши?",a="Улей Аши — действующий ульевой комплекс силитидов на севере Силитуса. Здесь обитают тысячи роющих насекомоподобных существ, которые превращают пески пустыни в сеть туннелей и холмов.",al={"ashi hive","hive ashi location","what is ashi","улей аши","где улей аши","что такое аши"}},{q="Какие силитиды живут в Улье Аши?",a="Колонию населяют специализированные касты силитидов, в том числе рабочие Улья Аши, песчаные охотники, ядовитые жалоносцы и тяжело бронированные защитники.",al={"ashi mobs","hive ashi creatures","what silithid are here","монстры аши","существа улья аши","какие силитиды здесь"}},{q="Как Улей Аши связан с Роящейся вершиной?",a="Силитиды, роящиеся вокруг соседней Роящейся вершины, происходят из Улья Аши: это продвижение потомства улья вовне, через пустынную равнину.",al={"swarming pillar connection","ashi and swarming pillar","связь с роящейся вершиной","аши и роящаяся вершина"}},{q="Почему разведчики Кенария изучают этот улей?",a="Круг Кенария стремится понять стремительное возрождение силитидов и то, как согласуются их ульи. Разведчики наблюдают за Аши, чтобы расшифровать странные глифы и отследить, как быстро растет улей.",al={"why scout hive ashi","hive ashi scout report","зачем разведывать улей аши","отчет разведки улья аши"}}},fp="9,240,18.472.0,18.495.0,18.204.0,41.151.0,49.155.0,43.200.0"}
P.entries["subzone:hive-regal"] = {n="Улей Регал",s="Улей Регал — огромный улей силитидов, вырытый на юге Силитуса. Это одна из трех главных колоний насекомых, господствующих в засушливых пустошах, и она кишит агрессивными кастами силитидов, грозящими захлестнуть окрестную пустыню.",h="Улей Регал — огромный улей силитидов, вырытый на юге Силитуса.",kw={"burrowers","hive","hive'regal","regal","silithid","silithus","slavemakers","spitfires","землекопы","улей","улей регал","регал","силитид","силитиды","силитус","рабовладельцы","огнеплевы"},ang={["class:Druid"]="Круг Кенария пристально следит за распространением Улья Регал, видя во вторжении скверны силитидов губительную заразу для пустынной экосистемы."},sec={{t="Южный улей",b="Улей Регал, раскинувшийся по югу Силитуса, — одно из крупнейших скоплений силитидов в Калимдоре. Его высокие смоляные шпили и просторные подземные туннели кишат опасными выводками насекомых: от ядовитых огнеплевов и землекопов до хищных рабовладельцев. Улей действует как единое гнездо: яростно защищает свои границы и собирает органический материал у несчастных путников, подошедших слишком близко."},{t="Подземная сеть",b="Под красными песками лабиринтные ходы Улья Регал уходят глубоко в землю. Странные глифы, выбитые у входа и глубоко в туннелях, говорят о том, что роем управляет организованный разум, а не просто дикий инстинкт. Ученые и разведчики, изучающие угрозу силитидов, полагают, что Улей Регал вместе с родственными ульями входит в состав более крупной возникающей силы, пробуждающейся под пустошами Силитуса."}},faq={{q="Где находится Улей Регал?",a="Улей Регал находится в южной части Силитуса; его отличают высокие холмы насекомых и зараженные красные пески.",al={"hive regal location","where is hive regal","find hive regal","улей регал где","где улей регал","найти улей регал"}},{q="Какие существа живут в Улье Регал?",a="Гнездо населяют различные враждебные породы силитидов, в том числе землекопы, засадники, огнеплевы и рабовладельцы, яростно защищающие улей.",al={"hive regal mobs","what is inside hive regal","hive regal enemies","монстры улья регал","что внутри улья регал","враги улья регал"}},{q="Почему исследователей интересует Улей Регал?",a="Разведчики и ученые изучают улей, чтобы расшифровать странные глифы для общения на его стенах и следить за растущей угрозой роя силитидов на юге Калимдора.",al={"why go to hive regal","hive regal research","hive regal glyphs","зачем идти в улей регал","исследования улья регал","глифы улья регал"}},{q="Чем Улей Регал отличается от других ульев Силитуса?",a="Улей Регал — самая южная из трех крупных колоний Силитуса, наряду с Ульем Аши и Ульем Зора. В каждой колонии обитают свои специализированные касты силитидов, хотя все они, похоже, разделяют единую коварную цель.",al={"other hives silithus","three hives","difference between hives","другие ульи силитуса","три улья","различия ульев"}}},fp="10,250,17.465.0,20.428.0,28.126.0,43.151.0,45.176.0,60.214.0"}
P.entries["subzone:hive-zora"] = {n="Улей Зора",s="Улей Зора — один из трех крупных холмов-колоний силитидов, господствующих над засушливыми просторами Силитуса. Этот кишащий подземный улей расположен на западной окраине пустыни, и в нем обитают агрессивные касты насекомых, служащие великому рою.",h="Улей Зора — один из трех крупных холмов-колоний силитидов, господствующих над засушливыми просторами Силитуса.",kw={"cenarion circle","hive sisters","hive zora","hive'zora","reavers","silithid","silithus","waywatchers","круг кенария","сестры улья","улей зора","разорители","силитид","силитиды","силитус","сторожа троп"},ang={["class:Druid"]="Для друидов Круга Кенария Улей Зора — страшный неестественный всплеск, нарушающий природное равновесие пустынных земель.",["profession:Mining"]="В извилистых туннелях и на окраинах колоний силитидов, таких как Улей Зора, часто встречаются богатые залежи тория и редкие месторождения минералов, покрытые слизью."},sec={{t="Западный рой",b="Улей Зора, поднимающийся из бесплодных песчаных дюн западного Силитуса, — оживленный центр активности насекомых. Огромные пористые каменные шпили и холмы отмечают входы в глубокие подземные туннели, прорытые землекопами-силитидами. Сторожа троп и разорители неустанно патрулируют периметр, а копающие касты и сестры улья роятся в глубинах. Для Круга Кенария и других разведчиков, наблюдающих за пустыней, улей — страшный знак того, что насекомая угроза неуклонно отвоевывает древние рубежи."}},faq={{q="Что такое Улей Зора?",a="Улей Зора — действующий ульевой комплекс силитидов на западе Силитуса. Он состоит из огромных шпилей насекомых на поверхности, соединенных с обширными подземными туннелями.",al={"zora hive","what is hive zora","hive zora silithus","улей зора","что такое улей зора","улей зора силитус"}},{q="Какие существа живут в Улье Зора?",a="Улей целиком занят роем силитидов. Холм населяют разные касты: сторожа троп Улья Зора патрулируют снаружи, тяжелые разорители защищают землю, туннельщики роют землю, а рядом обитают ядовитые сестры улья.",al={"hive zora mobs","what monsters are in hive zora","who lives in hive zora","монстры улья зора","какие монстры в улье зора","кто живет в улье зора"}},{q="Почему Круг Кенария исследует этот улей?",a="Разведчики и исследователи, расквартированные в Силитусе, наблюдают за Ульем Зора, чтобы отслеживать рост и перемещения угрозы силитидов. Посланники изучают их поведение, расшифровывают глифы и сокращают их растущую численность, пока рой не захлестнул регион.",al={"why scout hive zora","cenarion circle hive zora","зачем разведывать улей зора","круг кенария улей зора"}},{q="Чем Улей Зора отличается от других ульев Силитуса?",a="Улей Зора — самый западный из трех великих ульев: Улей Аши удерживает север, а Улей Регал господствует на юге. У каждого улья свой особый выводок, но всех объединяет хищное стремление расширяться по пустыне.",al={"other hives silithus","difference between hives","hive regal hive ashi","другие ульи силитуса","различия ульев","улей регал улей аши"}}},fp="9,243,17.539.0,18.174.0,33.238.0,51.254.0,59.245.0"}
P.entries["subzone:horizon-scout"] = {n="Разведчик горизонта",s="«Разведчик горизонта» — затонувшее судно, лежащее на дне океана в Опустошенном береге у южного побережья Азшары. Пока капитан остается на берегу, несколько членов команды заперты в затопленном корпусе и живы под водой благодаря чарам подводного дыхания.",h="«Разведчик горизонта» — затонувшее судно, лежащее на дне океана в Опустошенном береге у южного побережья...",kw={"azshara shipwreck","azsharite","horizon scout","roland geardabbler","ruined reaches","spitelash","vanessa beltis","кораблекрушение азшара","азшарит","разведчик горизонта","роланд шестеренкин","опустошенный берег","янтарный бич","ванесса белтис"},ang={["faction:Alliance"]="«Разведчик горизонта» — это неудачная морская затея, лояльная Альянсу, в опасных водах Азшары: команда оказалась разделена между берегом и водяной могилой.",["race:Gnome"]="Вся уцелевшая команда обязана дыханием Роланду Шестеренкину, чье неустанное колдовство сдерживает океанские глубины внутри затопленного корпуса."},sec={{t="В ловушке на дне океана",b="Лежа под волнами среди коварных мелей Опустошенного берега, «Разведчик горизонта» нашел жестокий конец у изрезанного берега Азшары. Капитан Ванесса Белтис сумела добраться до суши на соседнем полуострове, а часть команды пошла ко дну вместе с корпусом. Чудом выжившие внутри не утонули: гном по имени Роланд Шестеренкин поддерживает магический пузырь подводного дыхания, который хранит их в обломках. Окруженные враждебными морскими хищниками и кровожадными нага, оставшиеся матросы ждут в темных носовых отсеках, не в силах всплыть сами."},{t="Засада нага",b="Свидетельства на борту намекают на зловещие силы, погубившие корабль. На носовой лестнице лежит небольшой осколок сырого азшарита — загадочного минерала, встречающегося только на этих берегах. Нага из племени Янтарного Бича, рыскающие в водах Опустошенного берега, вероятно, напали на «Разведчика горизонта», чтобы разграбить артефакты или ресурсы экспедиции, и утопили судно, чтобы никто не ушел с секретами или сокровищами побережья."}},faq={{q="Где находится «Разведчик горизонта»?",a="Обломки «Разведчика горизонта» лежат под водой на дне залива в Опустошенном береге, у южного побережья Азшары.",al={"horizon scout location","where is horizon scout","find horizon scout","разведчик горизонта где","где разведчик горизонта","найти разведчика горизонта"}},{q="Как команда еще жива под водой?",a="Гном-инженер или маг по имени Роланд Шестеренкин непрерывно поддерживает ауру подводного дыхания внутри затонувшего корпуса, сохраняя жизнь запертым членам команды в устойчивом пузыре пригодного для дыхания воздуха.",al={"how are they breathing","why crew not dead","roland geardabbler aura","как они дышат","почему команда жива","аура роланда шестеренкина"}},{q="Кто такая капитан Ванесса Белтис?",a="Капитан Ванесса Белтис — командир «Разведчика горизонта». В отличие от матросов, запертых в корпусе, она сумела добраться до безопасного южного полуострова Азшары вместе с несколькими уцелевшими.",al={"vanessa beltis","horizon scout captain","ship captain","ванесса белтис","капитан разведчика горизонта","капитан корабля"}},{q="Что потопило «Разведчика горизонта»?",a="Корабль почти наверняка попал в засаду местных нага из племени Янтарного Бича и был потоплен. Кусок сырого азшарита на нижней палубе говорит о том, что нага напали, чтобы завладеть минеральными богатствами или артефактами, собранными экспедицией.",al={"why did horizon scout sink","who sank horizon scout","what happened to the ship","почему затонул разведчик горизонта","кто потопил разведчика горизонта","что случилось с кораблем"}}},fp="13,293,26.598.0,15.449.0,35.136.0,39.204.0,30.201.0,38.229.0"}
P.entries["subzone:howling-vale"] = {n="Воющая долина",s="Воющая долина — темная лощина на севере центральной части Ясеневого леса, у границы Оскверненного леса. Ее заполонили свирепые чуждые волкоподобные твари — воргены Терроволков. Глубоко в ее пещерах скрыто древнее святилище Мел'Тандрис, благословленные Элуной руины, тесно связанные с трагическим происхождением проклятия ворженов в Калимдоре.",h="Воющая долина — темная лощина на севере центральной части Ясеневого леса, у границы Оскверненного леса.",kw={"ashenvale worgen","howling vale","mel'thandris","scythe of elune","terrowulf","velinde starsong","ворджены ясеневого леса","воющая долина","мел'тандрис","коса элуны","терроволк","велинда песнь звезд"},ang={["class:Druid"]="Одичавшие вожаки стай, бродящие по пещере, несут древнюю проклятую связь с запретными традициями оборотничества, возникшими во время Войны сатиров.",["race:NightElf"]="Осквернение святилища Мел'Тандрис и трагические ошибки Велинды Песни Звезд — горькое напоминание об опасности вмешательства в запретную первобытную магию."},sec={{t="Обитель призраков",b="К северу от дороги на Оскверненный лес спокойное величие Ясеневого леса сменяется жутким хищным воем. В долине растут древние деревья, а рядом бродят оскверненные вожаки стай Терроволков и агрессивные звери. В ее сердце находится пещера, хранящая память о Мел'Тандрис, древней жрице ночных эльфов. Когда-то святилище было местом тихого поклонения, но его тихие залы пришли в запустение, оскверненные одичавшими волколюдьми, чье происхождение озадачивает расквартированных рядом Часовых."},{t="Коса и наследие Песни Звезд",b="Во время древней Войны сатиров Мел'Тандрис было поручено хранить Косу Элуны — роковой артефакт, заточивший одичавших друидов Косы. После ее гибели в бою ее святилище тысячелетиями укрывало артефакт. Недавно ночной эльф Часовой Велинда Песнь Звезд нашла в Дарнассе исторические записи, отправилась сюда и забрала Косу. Ее попытки направить силу артефакта на борьбу с демонами невольно выпустили ворженов на окрестные леса, и долина осталась во власти зверей, которых она призвала."}},faq={{q="Почему она называется Воющей долиной?",a="Долина получила свое мрачное название из-за леденящих воплей ворженов Терроволков, завладевших ею. Их постоянный эхом отдающийся вой разносится по ущелью и пещере, заглушая природные звуки полога Ясеневого леса.",al={"why howling vale","origin of howling vale name","why does it howl","почему воющая долина","происхождение названия воющей долины","почему там воют"}},{q="Что такое святилище Мел'Тандрис?",a="Это древнее святилище, посвященное Элуне и построенное в честь Мел'Тандрис, жрицы ночных эльфов, сражавшейся в древней Войне сатиров. Оно испещрено дарнасскими молитвами и тысячелетиями служило тайным местом упокоения Косы Элуны.",al={"shrine of melthandris","who was mel'thandris","melthandris shrine","святилище мел'тандрис","кто такая мел'тандрис","святилище мел'тандрис где"}},{q="Откуда здесь взялись ворджены?",a="Их происхождение озадачивает Часовых. Часовой Мелирия Ледяная Тень посылает разведчиков Альянса изучить в святилище Том Мел'Тандрис, история которого хранит ключ к тому, откуда взялись волколюди.",al={"how did worgen get to ashenvale","terrowulf origin","why are worgen in ashenvale","как ворджены попали в ясеневый лес","происхождение терроволков","почему ворджены в ясеневом лесу"}},{q="Что такое Том Мел'Тандрис?",a="Это священный исторический текст, хранящийся в святилище в глубине пещеры. Часовой Мелирия Ледяная Тень посылает разведчиков Альянса изучить том, чтобы понять происхождение загадочных волколюдей, терзающих лес.",al={"tome of mel'thandris","tome in howling vale","melthandris book","том мел'тандрис","том в воющей долине","книга мел'тандрис"}}},fp="12,330,15.486.0,34.556.1,34.221.0,35.258.0,36.196.1,33.222.0"}
P.entries["subzone:hunter-rise"] = {n="Вершина Охотников",s="Вершина Охотников — одно из возвышенных плато, составляющих город Громовой Утес, к югу от центрального утеса. Это главное место обучения и сбора воинов, охотников, следопытов и снимающих шкуры таурен. На ее продуваемых ветрами площадках молодые воины оттачивают боевые навыки и готовятся к сражениям.",h="Вершина Охотников — одно из возвышенных плато, составляющих город Громовой Утес, к югу от центрального утеса.",kw={"battlemasters","hunter rise","hunter's hall","mulgore","thunder bluff","trackers","военачальники","вершина охотников","зал охотников","мулгор","громовой утес","следопыты"},ang={["class:Hunter"]="Для молодых таурен-охотников эта вершина — естественное сердце вашего призвания в столице: здесь есть обучение, припасы для питомцев и наставления мастеров-следопытов.",["class:Warrior"]="На Вершине Охотников вы найдете тренировочные манекены, боевых наставников и военачальников, готовых испытать вашу силу в непрерывной обороне Орды."},sec={{t="Собрание воинов",b="Вершина Охотников соединена с соседними утесами качающимися веревочными мостами и посвящена боевым традициям таурен. Ее центр — Зал Охотников, где опытные стрелки, следопыты и воины передают свое мастерство молодым поколениям. Вокруг зала расположены тренировочные площадки с манекенами, стойками для оружия и столбами для снятия шкур, и это оживленное место для тех, кто живет копьем, луком и шкурой."},{t="Воинский долг и оборона",b="Помимо охоты на дичь в равнинах Мулгора, жители Вершины Охотников помогают защищать Громовой Утес и всю Орду. Начальники боевых кличей, размещенные на вершине, набирают опытных бойцов для стычек с вторжениями Альянса на спорных полях боя. Это по-прежнему важное место сбора для каждого, кто поклялся защищать стадо."}},faq={{q="Где находится Вершина Охотников?",a="Вершина Охотников находится на южной стороне Громового Утеса. До нее можно добраться по деревянным веревочным мостам, соединяющим ее с плато Нижней и Верхней вершин города.",al={"where is hunter rise","hunter rise location","how to get to hunter rise","где вершина охотников","расположение вершины охотников","как добраться до вершины охотников"}},{q="Кто живет и тренируется на Вершине Охотников?",a="На плато живут таурены-охотники, воины, следопыты, звероловы и кожевники. Помимо учителей классов и профессий, здесь стоят военачальники Орды и набирают бойцов для войн фракции.",al={"who is on hunter rise","hunter rise trainers","what is on hunter rise","кто на вершине охотников","учителя вершины охотников","что есть на вершине охотников"}},{q="Что такое Зал Охотников?",a="Зал Охотников — главный длинный дом на вершине, где собираются опытные охотники и воины. Он служит оружейной, школой и очагом для тех, кто учится выслеживанию, меткой стрельбе и ближнему бою.",al={"hunters hall","hunters lodge thunder bluff","thunder bluff hunter hall","зал охотников","дом охотников громовой утес","зал охотников громового утеса"}},{q="Могут ли представители Альянса посетить Вершину Охотников?",a="Нет. Громовой Утес — крупная столица Орды, а Вершину Охотников охраняют опытные воины-таурены. Любого искателя приключений из Альянса, попытавшегося пересечь ее мосты, немедленно атакует городская стража.",al={"alliance on hunter rise","can alliance go to hunter rise","альянс на вершине охотников","может ли альянс попасть на вершину охотников"}}},fp="11,329,23.447.0,24.382.0,29.178.0,36.217.0,26.218.0,46.203.0"}
P.entries["subzone:hushed-bank"] = {n="Затихший берег",s="Затихший берег — сумрачное западное побережье Сумеречного леса вдоль реки, отделяющей лес от Западного Края. Он тянется от развилки у Трех Углов на юг к Тернистой долине — тихий, но опасный лес, где рыщут хищные звери и таятся мрачные тайны.",h="Затихший берег — сумрачное западное побережье Сумеречного леса вдоль реки, отделяющей лес от Западного Края.",kw={"covered bridge","duskwood","hushed bank","lars","riverbank","sven yorgen","westfall","крытый мост","сумеречный лес","затихший берег","ларс","берег реки","свен йорген","западный край"},ang={["class:Hunter"]="Волки и пауки, населяющие густую листву вдоль берега реки, — классические дикие звери для следопытов, исследующих мрачные уголки леса.",["faction:Alliance"]="Крытый мост у берега служит важным стратегическим проходом, соединяющим фермерские земли Западного Края с осажденным форпостом в Сумеречном лесу."},sec={{t="Рубеж вдоль реки",b="Затихший берег тянется вдоль реки между Сумеречным лесом и Западным Краем и отмечает переход от открытых равнин и залитых солнцем ферм к всепроникающим неестественным сумеркам. Здесь реку пересекает деревянный крытый мост, по которому путники покидают мрачный лес на запад. Берега реки заросли густым подлеском и затянуты стелющимся туманом, а огромные пауки и голодные лесные волки подстерегают неосторожных странников, сошедших с тропы."},{t="Изгои и отшельники",b="В северной части берега одинокие души устроили себе скудную жизнь вдали от подозрительных глаз Темнолесья. Свен Йорген и его спутник Ларс разбили лагерь в этих густых лесах, наблюдая за опушкой и храня горькую обиду из-за мрачных трагедий, постигших край. Их уединенное убежище — один из немногих признаков присутствия живых гуманоидов на этом безлюдном берегу."}},faq={{q="Где находится Затихший берег?",a="Затихший берег образует западный край Сумеречного леса вдоль реки, отделяющей лес от Западного Края. Он тянется от развилки у Трех Углов на севере к южным границам, ведущим в Тернистую долину.",al={"hushed bank location","where is hushed bank","hushed bank map","расположение затихшего берега","где затихший берег","карта затихшего берега"}},{q="Что соединяет Затихший берег с Западным Краем?",a="Деревянный крытый мост пересекает реку у Затихшего берега и позволяет пешим путникам и повозкам безопасно переправляться между солнечными равнинами Западного Края и проклятым мраком Сумеречного леса.",al={"bridge to westfall","westfall bridge duskwood","how to cross river to westfall","мост в западный край","мост западный край сумеречный лес","как перейти реку в западный край"}},{q="Кто живет вдоль Затихшего берега?",a="Свен Йорген и его помощник Ларс устроили лагерь в северном углу берега. Оба живут как уединенные отшельники, бежав от ужасов, погубивших ферму Свена неподалеку.",al={"camp on hushed bank","who is at hushed bank","npcs hushed bank","лагерь на затихшем береге","кто на затихшем береге","персонажи затихшего берега"}},{q="Какие угрозы встречаются вдоль этого побережья?",a="На Затихшем берегу обитают свирепые лесные звери, включая гигантских лесных пауков и хищных сумеречных волков, нападающих на все, что движется в зарослях.",al={"hushed bank mobs","dangers of hushed bank","hushed bank monsters","монстры затихшего берега","опасности затихшего берега","существа затихшего берега"}}},fp="11,301,26.442.0,20.405.1,33.232.0,42.177.0,32.190.0,44.166.0"}
P.entries["subzone:ice-thistle-hills"] = {n="Холмы Ледополоха",s="Холмы Ледополоха — заснеженное нагорье к юго-востоку от гоблинского поселения Круговзор. В этой местности, где преобладает суровая система пещер, хозяйничают свирепые йети Ледополоха, угрожающие всем путникам, свернувшим с главной дороги.",h="Холмы Ледополоха — заснеженное нагорье к юго-востоку от гоблинского поселения Круговзор.",kw={"everlook","ice thistle hills","ice thistle yetis","icecaps","pristine yeti horn","thick yeti fur","winterspring","yeti cave","круговзор","холмы ледополоха","йети ледополоха","ледяной шип","чистый рог йети","густой мех йети","зимние ключи","пещера йети"},ang={["profession:Herbalism"]="Морозные склоны вокруг холмов — отличное место для сбора холодолюбивых растений вроде ледяного шипа; редкие цветы порой встречаются у входа в пещеру.",["profession:Mining"]="Темная пещера в холме — опасное, но выгодное место для опытных горняков, ищущих богатые жилы тория под охраной стай йети."},sec={{t="Логово белого меха",b="Холмы Ледополоха круто поднимаются над центральными сугробами Зимних Ключей и служат основными охотничьими угодьями и местом гнездования агрессивных ледополохских йети этой долины. В центре холмов находится заметная пещера, глубоко вырытая в скале, и эти громадные звери бродят как по каменистым склонам, так и по извилистым туннелям внутри. Из-за близости к Круговзору йети постоянно досаждают гоблинским торговцам и приезжим старателям и угрожают им. Те регулярно нанимают отважных охотников, чтобы истреблять зверей ради ценных плотных шкур и чистых рогов."}},faq={{q="Где находятся Холмы Ледополоха?",a="Холмы Ледополоха находятся прямо к юго-востоку от гоблинского торгового поста Круговзор в центре Зимних Ключей.",al={"ice thistle hills location","where is ice thistle hills","yeti cave location","расположение холмов ледополоха","где холмы ледополоха","пещера йети"}},{q="Какие существа здесь обитают?",a="Склоны и пещера в холмах населены почти исключительно йети Ледополоха — чудовищными белошерстными громилами, яростно защищающими свою территорию.",al={"ice thistle monsters","what is in ice thistle hills","yeti types","монстры ледополоха","что есть в холмах ледополоха","виды йети"}},{q="Почему искатели приключений охотятся на Холмах Ледополоха?",a="Путники и торговцы из Круговзора часто нанимают искателей приключений, чтобы те добывали густой мех и чистые рога йети Ледополоха, которые ценятся при изготовлении снаряжения для выживания в холодной долине.",al={"why kill yetis","yeti fur winterspring","ice thistle quest","зачем убивать йети","мех йети зимние ключи","задание ледополох"}},{q="Какие ресурсы можно собирать вокруг холмов?",a="На открытых склонах растут редкие горные травы, например ледяной шип, а в глубине пещеры йети скрыты богатые залежи минералов, включая жилы тория.",al={"herbs ice thistle","mining ice thistle cave","травы ледополох","добыча руды пещера ледополоха"}}},fp="17,255,18.572.0,40.116.0,25.157.0,49.211.0,48.164.0"}
P.entries["subzone:infectis-scar"] = {n="Чумной овраг",s="Чумной овраг — глубокая неестественная расселина в оскверненной земле Восточных Чумных земель возле Перекрестка Корина. В отличие от природных оврагов, эта рана в земле была разорвана некромантической силой, когда проклятый рунический клинок разбился о дворфийский щит. Скверна, гниющая на дне разлома, остается вечным свидетельством темного колдовства Плети.",h="Чумной овраг — глубокая неестественная расселина в оскверненной земле Восточных Чумных земель возле...",kw={"chasm","corin's crossing","darrowshire","infectis scar","marduk blackpool","pestilent scar","runesword","пропасть","перекресток корина","дарроушир","чумной овраг","мардук блэкпул","моровой овраг","рунный меч"},ang={["class:Paladin"]="Пропасть источает оскверняющие остатки некромантического колдовства и показывает, насколько глубоко проклятые руны могут осквернить землю, отделившись от владельца.",["race:Dwarf"]="Овраг стоит как памятник стойкости дворфов: он возник лишь потому, что щит безымянного дворфийского капитана выстоял против темного рунного клинка рыцаря смерти и сокрушил проклятую сталь."},sec={{t="Рана темной магии",b="Хотя соседние ущелья, такие как Моровой овраг, возникли как природные участки местности, отравленные чумой, Чумной овраг целиком искусственный. Он возник во время ожесточенных схваток Третьей войны возле Перекрестка Корина. Когда пресловутый рыцарь смерти Мардук Блэкпул столкнулся со стойким дворфийским капитаном, проклятый рунный меч Мардука разбился о щит капитана. Отбросив сломанное оружие, Мардук оставил себе рукоять, но отколотый клинок глубоко ушел в землю. Его мерзкие чары яростно разорвали земную кору и создали зазубренную пропасть, которая и сегодня гниет в Чумных землях."}},faq={{q="Как образовался Чумной овраг?",a="Он возник во время битвы возле Перекрестка Корина, когда рунный меч рыцаря смерти Мардука Блэкпула сломался о щит дворфийского капитана. Когда расколотый клинок ударился о землю, его темная магия глубоко проникла в недра и разорвала огромную расселину.",al={"infectis scar origin","how did infectis scar happen","who made the infectis scar","происхождение чумного оврага","как возник чумной овраг","кто создал чумной овраг"}},{q="Чем он отличается от Морового оврага?",a="Моровой овраг изначально был природным ущельем, оскверненным чумой Плети. Чумной овраг не существовал в природе: он целиком возник от злобного колдовства, просочившегося из сломанного рунного клинка Мардука Блэкпула.",al={"difference between infectis and pestilent scar","pestilent scar comparison","разница между чумным и моровым оврагом","сравнение морового оврага"}},{q="Кто такой Мардук Блэкпул?",a="Мардук Блэкпул, известный как Черный, был рыцарем смерти на службе Плети и участвовал в бойне по всему Лордерону, включая нападение на Дарроушир и стычки возле Перекрестка Корина.",al={"marduk blackpool","who is marduk","мардук блэкпул","кто такой мардук"}},{q="Где сейчас меч?",a="Клинок разбитого рунного меча глубоко ушел в дно созданной им пропасти, а Мардук Блэкпул после схватки оставил себе лишь рукоять.",al={"runeblade location","where is the blade","местонахождение рунного клинка","где клинок"}}},fp="13,383,21.624.0,33.262.0,44.251.0,25.211.0,23.155.0"}
P.entries["subzone:iris-lake"] = {n="Озеро Ирис",s="Озеро Ирис — оскверненный водоем на севере центральной части Ясеневого леса, к востоку от Астранаара. Когда-то чистые воды озера стали болезненно желтовато-зелеными из-за демонической порчи, просачивающейся из Оскверненного леса, а по его берегам теперь бродят враждебные болотные твари.",h="Озеро Ирис — оскверненный водоем на севере центральной части Ясеневого леса, к востоку от Астранаара.",kw={"ashenvale","bog beasts","elune's tear","felwood corruption","iris lake","shael'dryn","ясеневый лес","болотные твари","слеза элуны","порча оскверненного леса","озеро ирис","шаэл'дрин"},ang={["class:Druid"]="Искаженные болотные твари и застойные оскверненные воды показывают, какой разрушительный урон наносит природе демоническая энергия, если ее не остановить.",["race:NightElf"]="Озеро Ирис — горький пример расползающейся порчи, угрожающей Ясеневому лесу, но добыча слез Элуны на его загрязненных берегах дает надежду на очищение леса."},sec={{t="Оскверненное убежище",b="Озеро Ирис лежит между Астранааром и лунным колодцем, за которым присматривает Шаэл'дрин, и служит мрачным напоминанием о ранах, нанесенных в годы Третьей войны. Энергии Скверны, дрейфующие на юг с оскверненных высот Оскверненного леса, отравили котловину и превратили ее некогда прозрачные воды в мерзкую желтовато-зеленую топь. Порча исказила местные растения и духов воды и породила агрессивных болотных тварей, которые набрасываются на любого путника, забредшего поблизости."},{t="Слезы богини",b="Несмотря на сильное загрязнение, удушающее озеро, на его краях еще сохранились священные остатки прошлого. На илистых берегах порой можно найти редкие кристаллические камни, известные как слезы Элуны. Хранители эльфийских традиций, такие как Шаэл'дрин, ищут эти святые камни, чтобы очищать оскверненные лунные колодцы и противостоять распространению демонической порчи по Ясеневому лесу."}},faq={{q="Почему вода в озере Ирис зеленая и мутная?",a="Озеро Ирис осквернено демонической порчей, стекающей из соседнего Оскверненного леса. Темная магия отравила грунтовые воды, и озеро превратилось в желтовато-зеленую лужу, которая искажает местных животных, превращая их в агрессивных чудовищ.",al={"why is iris lake green","iris lake water","why is iris lake tainted","почему озеро ирис зеленое","вода озера ирис","почему озеро ирис осквернено"}},{q="Какие существа обитают вокруг озера Ирис?",a="Озеро и его берега кишат оскверненными болотными тварями. Эти элементали растений и грязи обезумели от энергии Скверны и яростно нападают на всех, кто приближается к воде.",al={"iris lake monsters","iris lake mobs","what attacks at iris lake","монстры озера ирис","мобы озера ирис","кто нападает у озера ирис"}},{q="Что такое слезы Элуны?",a="Слезы Элуны — священные светящиеся синие камни, которые находят у берегов озера Ирис. Жрецы и хранители ночных эльфов используют их освященную природу в обрядах очищения, в частности для очистки оскверненных лунных колодцев.",al={"elunes tears","elune tear","what is elunes tear","слезы элуны","слеза элуны","что такое слеза элуны"}},{q="Где находится озеро Ирис?",a="Озеро Ирис лежит на севере центральной части Ясеневого леса. Оно расположено строго к востоку от поселения ночных эльфов Астранаар и к западу от лунного колодца Шаэл'дрин.",al={"where is iris lake","iris lake location","how to get to iris lake","где озеро ирис","расположение озера ирис","как добраться до озера ирис"}}},fp="9,251,16.450.0,20.376.0,46.237.0,37.183.0,23.211.0,27.149.0"}
P.entries["subzone:ironband-s-compound"] = {n="Мастерская Сталекрута",s="Мастерская Сталекрута — укрепленный форпост в заснеженных холмах к югу от озера Хельмово Ложе в восточной части Дун Морога. Прежде здесь жил геолог Стерджи Сталекрут, но лагерь захватили враждебные дворфы Черного Железа, нападающие на всякого, кто подходит слишком близко.",h="Мастерская Сталекрута — укрепленный форпост в заснеженных холмах к югу от озера Хельмово Ложе в восточной...",kw={"dark iron","dun morogh","dwarf","helm's bed lake","ironband's compound","ironforge","sturgy ironband","черное железо","дун морог","дворф","озеро хельмово ложе","мастерская сталекрута","стальгорн","стерджи сталекрут"},ang={["class:Warrior"]="Начинающих воинов сюда отправляют опытные наставники Стальгорна, чтобы они доказали свою доблесть, помогая павшим товарищам и собирая свидетельства присутствия Черного Железа.",["race:Dwarf"]="Для Бронзобородов вид коварных дворфов Черного Железа, окопавшихся в границах Дун Морога, — прямое оскорбление и постоянная опасность для их родины."},sec={{t="Падение под натиском Черного Железа",b="Эту мастерскую к югу от озера Хельмово Ложе основал Стерджи Сталекрут, и она служила опорным пунктом в заснеженной глуши Дун Морога. Все изменилось, когда лазутчики Черного Железа глубоко проникли на земли Бронзобородов и заняли это место. Теперь мастерская кишит враждебными дворфами и служит передовой базой врага, угрожающей путникам и ближайшим поселениям, прямо под носом у Стальгорна."},{t="Угроза для Стальгорна",b="Укрепленный лагерь Черного Железа в границах самого Дун Морога — серьезная провокация. Стальгорн внимательно следит за мастерской и посылает опытных воинов, чтобы подобрать павших разведчиков и добыть важные сведения, подтверждающие масштаб угрозы Черного Железа в горном королевстве."}},faq={{q="Кто изначально построил Мастерскую Сталекрута?",a="Форпост прежде занимал и использовал Стерджи Сталекрут, пока враждебные силы не изгнали его и не захватили это место.",al={"who made this camp","sturgy ironband","who owns ironbands compound","кто построил этот лагерь","стерджи сталекрут","кому принадлежит мастерская сталекрута"}},{q="Кто сейчас контролирует Мастерскую Сталекрута?",a="Лагерь захватила шайка враждебных дворфов Черного Железа, которые охотно нападают на любых странников и патрули Стальгорна, подходящие к нему.",al={"who is here","what enemies are here","dark irons dun morogh","кто здесь","какие враги здесь","черное железо дун морог"}},{q="Где находится Мастерская Сталекрута?",a="Вы найдете ее среди заснеженных холмов восточного Дун Морога, чуть южнее озера Хельмово Ложе.",al={"where is ironbands compound","how to find ironband compound","ironband location","где мастерская сталекрута","как найти мастерскую сталекрута","сталекрут расположение"}},{q="Почему этот лагерь важен для правителей Стальгорна?",a="Укрепленная база вражеского клана так близко к столице дворфов — тревожный провал безопасности. Власти Стальгорна посылают сюда бойцов, чтобы собрать веские доказательства проникновения Черного Железа.",al={"why care about this camp","ironforge response","dark iron threat","почему важен этот лагерь","ответ стальгорна","угроза черного железа"}}},fp="19,261,24.428.0,21.297.0,41.128.0,37.133.0,37.96.0,55.201.0"}
P.entries["subzone:ironband-s-excavation-site"] = {n="Раскопки Сталекрута",s="Раскопки Сталекрута — обширные дворфийские раскопки на юго-востоке Лок Модана, к югу от озера и юго-западу от Приюта Странников. Археологические работы под руководством геолога Сталекрута были внезапно прерваны, когда агрессивные и свирепые трогги захватили траншеи.",h="Раскопки Сталекрута — обширные дворфийские раскопки на юго-востоке Лок Модана, к югу от озера и юго-западу от...",kw={"digsite","excavation site","explorers league","ironband","loch modan","prospector ironband","troggs","раскопки","место раскопок","лига исследователей","сталекрут","лок модан","геолог сталекрут","трогги"},ang={["profession:Mining"]="Карьер и открытые выработки показывают типичные для дворфов методы тяжелой добычи, хотя постоянная враждебность троггов делает любую разведку опасной.",["race:Dwarf"]="Захваченные раскопки — болезненный удар для Лиги исследователей, которая считает возвращение древних реликвий важным для понимания наследия дворфов."},sec={{t="Раскрывая прошлое",b="Стремясь раскрыть свое древнее происхождение от титанов, геолог Сталекрут основал эти обширные раскопки на скалистых обрывах юго-востока Лок Модана. Многообещающие работы быстро обернулись бедой, когда копатели потревожили необычайно свирепую и крупную породу подземных троггов. Существа хлынули из-под земли, оттеснили шахтеров и устроили лагерь среди разбросанных инструментов, сломанных тележек и наполовину раскопанных реликвий."},{t="Руины в красной земле",b="Как и археологические работы в Бесплодных землях, Болотине и Ульдамане, это место застряло в опасной неопределенности. Уцелевшие геологи жмутся к краям периметра, отчаянно пытаясь вернуть украденное снаряжение и защитить открытые артефакты, включая странные древние статуи давно забытых строителей, от разрушения и расхищения прожорливыми троггами."}},faq={{q="Где находятся Раскопки Сталекрута?",a="Раскопки находятся на юго-востоке Лок Модана, строго к югу от озера Лок и к юго-западу от Приюта Странников.",al={"ironband location","where is ironbands digsite","ironband map","расположение сталекрута","где раскопки сталекрута","карта сталекрута"}},{q="Кто такой геолог Сталекрут?",a="Геолог Сталекрут — археолог и исследователь, возглавляющий раскопки от лица дворфийской Лиги исследователей. Он пытается спасти артефакты и отбросить местных троггов.",al={"who is ironband","prospector ironband lore","кто такой сталекрут","геолог сталекрут предыстория"}},{q="Почему раскопки захвачены троггами?",a="Когда дворфы-шахтеры углубились в почву Лок Модана, их туннели вскрыли подземные полости, где обитала крупная и агрессивная порода троггов. Те быстро одолели рабочих и захватили это место.",al={"why are troggs here","who attacked the digsite","ironband troggs","почему здесь трогги","кто напал на раскопки","трогги сталекрута"}},{q="Что дворфы надеялись здесь найти?",a="Как и на многих дворфийских раскопках по всему Каз Модану, шахтеры искали древние реликвии титанов и каменные руины, способные пролить свет на происхождение расы дворфов.",al={"what are they digging for","ironband artifacts","why dig here","что они ищут","артефакты сталекрута","зачем копать здесь"}}},fp="26,280,19.480.0,22.380.0,44.134.0,27.187.0,47.223.0,42.191.0"}
P.entries["subzone:ironbeard-s-tomb"] = {n="Гробница Железноборода",s="Гробница Железноборода — оскверненное дворфийское захоронение к западу от дороги, ведущей на север к Дун Модру в Болотине. Здесь есть кладбище под открытым небом и каменная статуя того, в чью честь названа гробница. Склеп заброшен, а территорию наводнили кислотные слизи. Путники редко заходят в лощину, разве что в поисках вещей, поглощенных слизью.",h="Гробница Железноборода — оскверненное дворфийское захоронение к западу от дороги, ведущей на север к Дун...",kw={"crypt","dun modr","graveyard","ironbeard","ironbeard's tomb","oozes","sida","wetlands","склеп","дун модр","кладбище","железнобород","гробница железноборода","слизи","сида","болотина"},ang={["race:Dwarf"]="Для любого дворфа, идущего по дороге к Мосту Тандола, видеть место последнего упокоения героя клана, заселенное безмозглыми болотными слизями, — горький позор."},sec={{t="Оскверненное место упокоения",b="Гробница Железноборода возвышается над болотами у дороги на север к Дун Модру и свидетельствует о присутствии дворфов в Болотине. Огромная каменная статуя, предположительно изображающая самого Железноборода, охраняет окрестное кладбище. Но торжественный покой здесь больше не царит. Подземный склеп полностью захвачен слизями черных и багровых разновидностей, и гробница заражена. Дворфы больше не привозят сюда своих мертвых, а те, кто достаточно смел, чтобы потревожить склепы, в основном ищут останки, переваренные затаившейся слизью."}},faq={{q="Кем был Железнобород?",a="О самом Железнобороде известно очень мало, но огромная статуя и территория склепа говорят о том, что он был почитаемым дворфом, известным в Болотине. Памятник в его честь возвышается на склоне над кладбищем.",al={"ironbeard lore","who is ironbeard","statue identity","железнобород предыстория","кто такой железнобород","чья статуя"}},{q="Почему гробница заброшена?",a="Склеп полностью захвачен кислотными черными и багровыми слизями. Поскольку захоронения осквернены и кишат опасной слизью, скорбящие семьи перестали привозить сюда своих мертвых.",al={"why abandoned","oozes in tomb","what happened to the crypt","почему заброшена","слизи в гробнице","что случилось со склепом"}},{q="Почему искатели приключений исследуют Гробницу Железноборода?",a="Помимо борьбы с мерзким нашествием, путники часто обыскивают слизь в гробнице в надежде вернуть поглощенные вещи, в первую очередь потерянную сумку Сиды.",al={"why go here","sida bag","tomb quests","зачем идти сюда","сумка сиды","задания гробницы"}},{q="Где находится Гробница Железноборода?",a="Гробница расположена на севере центральной части Болотины, в холме к западу от главной дороги, ведущей на север к дворфийскому оплоту Дун Модр.",al={"tomb location","how to get to ironbeard tomb","ironbeard wetlands map","расположение гробницы","как добраться до гробницы железноборода","гробница железноборода болотина карта"}}},fp="16,359,24.600.0,18.241.0,26.196.0,44.153.0,34.143.0"}
P.entries["subzone:ironclad-cove"] = {n="Потайная бухта",s="Потайная бухта — огромная подземная пещера под Западным Краем, где находятся подземная верфь и причал. Это тайная верфь, на которой Братство Справедливости строит свой боевой броненосец, и она напрямую соединена с морем.",h="Потайная бухта — огромная подземная пещера под Западным Краем, где находятся подземная верфь и причал.",kw={"cookie","deadmines ship","defias cove","edwin vancleef","ironclad cove","juggernaught","shipyard","пирожок","корабль мертвых копей","бухта братства справедливости","эдвин ван клиф","потайная бухта","броненосец","верфь"},ang={["class:Rogue"]="Бухта — вершина мастерства, инженерного таланта и подземной логистики Эдвина ван Клифа, что делает ее легендарной среди воров и изгоев.",["faction:Alliance"]="Полноразмерный военный галеон, спрятанный под Западным Краем, превращает Братство Справедливости из региональной банды разбойников в смертельную военную угрозу для Королевства Штормград."},sec={{t="Скрытая верфь",b="Потайная бухта, расположенная в самой глубокой части Мертвых копей, — величественная морская пещера, превращенная в укрепленную верфь. Здесь Эдвин ван Клиф и Братство Справедливости построили огромный военный корабль, известный как броненосец. В пещере много деревянных лесов, островков и погрузочных мостков, где работают пираты Братства Справедливости, матросы и надсмотрщики. Ее существование показывает истинный масштаб угрозы: ван Клиф намерен не просто грабить фермы Западного Края, а собрать частный флот, способный обстреливать берега самого Штормграда."},{t="Врата в океан",b="В пещере доминируют колоссальные морские врата, укрепленные железом и вделанные в скальную стену. Когда их открывают, они дают прямой выход в Великое море у побережья чуть севернее Тернистой долины. До того как Братство Справедливости захватило бухту, ею владела независимая пиратская команда, которую Братство перебило ради полной секретности. Скрытая от глаз флота Штормграда, бухта дает Братству неконтролируемый путь для провоза контрабанды, организации морских набегов и подготовки морского нападения."}},faq={{q="Для чего строят корабль в Потайной бухте?",a="Броненосец — центральный элемент военных замыслов Эдвина ван Клифа. Братство Справедливости построило этот огромный военный корабль глубоко под землей, чтобы он мог незаметно выйти по подземным водным каналам и ударить по Штормграду с моря.",al={"why is there a ship here","what is the juggernaught","deadmines ship purpose","почему здесь корабль","что такое броненосец","назначение корабля в мертвых копях"}},{q="Куда ведут большие металлические врата в бухте?",a="Огромные врата открываются прямо в океан у южного побережья Западного Края, около границы с северной частью Тернистой долины. Когда их открывают, броненосец может выйти прямо в Великое море.",al={"where do the sea gates open","deadmines iron doors","exit into the ocean","куда открываются морские врата","железные двери мертвых копей","выход в океан"}},{q="Кто контролирует Потайную бухту?",a="Бухтой владеет Братство Справедливости под командованием Эдвина ван Клифа. Сначала уединенной пещерой пользовались независимые пираты, но силы ван Клифа уничтожили их, чтобы занять причалы и сохранить строительство броненосца в полной тайне.",al={"who runs the cove","who lives in ironclad cove","кто управляет бухтой","кто живет в потайной бухте"}},{q="Кто мурлок на борту корабля?",a="Это Пирожок, кок корабля Братства Справедливости. Вооруженный скалкой и котлами, он необычный союзник среди людей и гоблинов-отступников и объявил камбуз своими личными владениями.",al={"cookie the murloc","why is there a murloc pirate","chef cookie","мурлок пирожок","почему здесь мурлок-пират","повар пирожок"}}},fp="13,235,19.576.0,20.553.1,50.256.0,49.204.0,27.252.0,34.197.0"}
P.entries["subzone:ironforge"] = {n="Стальгорн",s="Стальгорн — подземная столица дворфов, высеченная глубоко в камне горы Стальгорн в Дун Мороге. Он раскинулся вокруг ревущей Великой кузни и служит политическим и торговым центром королевства Каз Модан и оплотом Альянса.",h="Стальгорн — подземная столица дворфов, высеченная глубоко в камне горы Стальгорн в Дун Мороге.",kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni","tinker town","бронзобород","подземный поезд","дун морог","великая кузня","высокий трон","стальгорн","каз модан","магни","город механиков"},ang={["race:Dwarf"]="Стальгорн — родовая столица и сердце клана Бронзобородов, где дворфийское мастерство, доблесть и история высечены прямо в живом камне горы.",["race:Gnome"]="Потеряв Гномреган из-за троггов и радиации, гномы сделали Город механиков временным убежищем и плацдармом для попыток вернуть свой дом."},sec={{t="Горная крепость",b="Город, вырубленный в подземных глубинах горы Стальгорн, состоит из концентрических каменных колец, расходящихся от монументальной Великой кузни. Он был основан тысячелетия назад, после того как дворфы пробудились и покинули Ульдаман, и пережил века истории, в том числе древнюю Войну трех молотов, после которой власть осталась только у клана Бронзобородов. Пещерный город, питаемый потоками расплавленной магмы и защищенный огромными каменными вратами, одновременно служит промышленным центром и неприступной твердыней. Помимо дворфийских мастеров и воинов, в его залах живет и множество изгнанных гномов после недавнего падения Гномрегана."},{t="Сердце торговли Альянса",b="В 25 году ПДП Стальгорн — пожалуй, самый оживленный центр торговли и промышленности во всем Альянсе. Король Магни Бронзобород правит Каз Моданом с Высокого трона, а дворфийские рудознатцы, шахтеры и инженеры работают сообща с гномами-беженцами, поселившимися в Городе механиков. Подземный поезд — непрерывная скоростная линия под горами — напрямую связывает Стальгорн со Штормградом, тесно объединяя обе столицы торговлей, переброской войск и взаимной обороной."}},faq={{q="Кто сейчас правит Стальгорном?",a="Стальгорном правит король Магни Бронзобород, который держит двор на Высоком троне. Город является столицей королевства Каз Модан под единоличным руководством клана Бронзобородов.",al={"who is the king of ironforge","ironforge leader","who leads ironforge","кто король стальгорна","правитель стальгорна","кто управляет стальгорном"}},{q="Почему в Стальгорне живет так много гномов?",a="После катастрофического падения и радиоактивного заражения их соседней столицы, Гномрегана, уцелевшие гномы бежали в Стальгорн. Бронзобороды приняли давних союзников и предоставили им убежище в квартале, известном как Город механиков.",al={"why are gnomes in ironforge","gnomes tinker town","where did gnomes come from","почему гномы в стальгорне","гномы город механиков","откуда взялись гномы"}},{q="Как Стальгорн связан со Штормградом?",a="Стальгорн напрямую связан со Штормградом через Подземный поезд — инженерное чудо, построенное гномами, которое идет под землей от Города механиков до Квартала Дворфов Штормграда.",al={"tram to stormwind","how to get to stormwind","subway to stormwind","поезд в штормград","как добраться до штормграда","метро в штормград"}},{q="Что такое Великая кузня в центре города?",a="Великая кузня — огромный горн, питаемый природными реками магмы, проведенными прямо через сердце горы. Это главный центр кузнечного дела и плавки в королевстве Каз Модан.",al={"giant forge in ironforge","what is the great forge","lava in ironforge center","гигантская кузня стальгорна","что такое великая кузня","лава в центре стальгорна"}}},fp="9,278,21.676.0,23.498.0,30.189.0,49.238.0,45.194.0,50.210.0"}
P.entries["subzone:ironforge-airfield"] = {n="Аэродром Стальгорна",s="Скрытая высоко в заснеженных пиках к северо-востоку от Стальгорна, эта удаленная дворфийская взлетная полоса служит испытательной площадкой и базой для гномьих летающих машин и дворфийских горцев. Плато не отмечено на главных дорогах и возвышается над зубчатыми утесами Дун Морога и крутым спуском к Болотине.",h="Скрытая высоко в заснеженных пиках к северо-востоку от Стальгорна, эта удаленная дворфийская взлетная полоса...",kw={"airfield","airstrip","dun morogh","flying machine","frostmane","ironforge","mountaineers","аэродром","взлетная полоса","дун морог","летающая машина","мерзлогрив","стальгорн","горцы"},ang={["profession:Engineering"]="Для механиков взлетная полоса — вершина гномьей авиации: полностью собранные летающие машины стоят здесь в экстремальном морозе.",["race:Dwarf"]="Аэродром — свидетельство дворфийской бдительности на своих землях: горцы Стальгорна стоят на страже даже на самых недоступных высотах Каз Модана."},sec={{t="Тайная твердыня среди утесов",b="Высокогорный аэродром, расположенный далеко над проторенными тропами Дун Морога, — тихое чудо сотрудничества в Альянсе. Горные пики защищают его от ветров, дворфийская кладка укрепляет продуваемые хребты, а гномьи летающие машины стоят на открытых посадочных полосах. Горцы охраняют периметр, а инженеры в лютый мороз возятся с шестеренками и осматривают дымящие паром двигатели."},{t="Пограничные стычки и замерзшие долины",b="Несмотря на отдаленность, аэродром далеко не спокоен. В окрестной долине, где есть замерзшие воды и утесы, хозяйничают тролли Мерзлогривы, живущие в соседних пещерах и постоянно донимающие дворфийских часовых. В тени пиков дворфийские защитники и патрули Грозовой Вершины регулярно сражаются с троллями-налетчиками на льду, и отдаленный пост пребывает в тихом, бдительном противостоянии."}},faq={{q="Как добраться до аэродрома?",a="К долине не ведут ни дороги, ни полеты, ни поддерживаемые туннели из Стальгорна или нижнего Дун Морога. Добраться туда можно, только взобравшись пешком по крутым склонам, обычно по сложным тропам вдоль хребтов, начинающимся в Лок Модане или возле перевалов Дун Морога.",al={"get to airfield","how to climb to airfield","airfield location","airfield path","добраться до аэродрома","как забраться на аэродром","где аэродром","путь к аэродрому"}},{q="Для чего нужно это место?",a="Это высокогорный испытательный полигон и военная застава, где дворфийские горцы и гномьи инженеры обслуживают летающие машины и разведывают высокогорные пограничные земли, разделяющие Дун Морог, Лок Модан и Болотину.",al={"why is there an airstrip","what is ironforge airfield for","зачем здесь взлетная полоса","для чего аэродром стальгорна"}},{q="Кто нападает на дворфийских стражей?",a="Местные тролли Мерзлогривы живут в пещерах на южных утесах долины. Дворфийские горцы регулярно сражаются с ними на замерзшем озере прямо под взлетной полосой.",al={"who attacks airfield","who is fighting on the lake","кто нападает на аэродром","кто сражается на озере"}},{q="Связан ли аэродром с какими-либо заданиями?",a="Обычные задания не отправляют искателей приключений на взлетную полосу. Это малоизвестное удаленное плато, почти не связанное с основной логистикой дворфийского королевства.",al={"any quests here","airfield quests","задания здесь","задания аэродрома"}}},fp="18,304,29.419.0,38.403.0,34.276.0,34.225.0,41.167.0,44.184.0"}
P.entries["subzone:ironstone-camp"] = {n="Лагерь Железного Камня",s="Лагерь Железного Камня — застава Орды на западной границе Мерцающей равнины в Тысяче Игл. Ее отправили изгнать дворфов-раскопщиков Альянса с ближнего карьера, но теперь гарнизону угрожает смертельная опасность: подземные силитиды захватили раскопки.",h="Лагерь Железного Камня — застава Орды на западной границе Мерцающей равнины в Тысяче Игл.",kw={"horde outpost","ironstone camp","moktar krin","rustmaul digsite","shimmering flats","silithid","thousand needles","застава орды","лагерь железного камня","моктар крин","карьер ржавой кувалды","мерцающая равнина","силитид","тысяча игл"},ang={["faction:Alliance"]="Исследователям Альянса, направляющимся к Мерцающей равнине, следует держаться подальше от лагеря, который изначально был создан именно для того, чтобы донимать и истреблять дворфов-землекопов из Бэл'дана.",["faction:Horde"]="Лагерь — удобная стоянка перед выходом на открытую соляную равнину, хотя местным командирам приходится туго в борьбе с роем силитидов, угрожающим их позиции."},sec={{t="Смена задачи",b="Лагерь Железного Камня стоит на границе между высокими столбами Тысячи Игл и сверкающей соляной равниной Мерцающей равнины. Отряд Орды был послан сюда с ясной единственной целью: выбить дворфийских раскопщиков из Карьера Ржавой Кувалды. Однако столкновение прервал рой прожорливых силитидов, вырвавшийся из соседней пещеры и яростно захлестнувший раскопки, нападая на обе стороны. Под началом Моктара Крина уцелевшие защитники лагеря направили силы на борьбу с насекомыми, пока рой не распространился по всему краю."}},faq={{q="Для чего нужен Лагерь Железного Камня?",a="Лагерь Железного Камня был устроен как передовая база Орды, чтобы вытеснить дворфов-раскопщиков Альянса из Карьера Ржавой Кувалды. Но в округе внезапно появился рой подземных силитидов, и главной задачей лагеря стали выживание и сдерживание насекомых.",al={"why is ironstone camp here","ironstone camp purpose","horde camp shimmering flats","почему здесь лагерь железного камня","зачем лагерь железного камня","лагерь орды мерцающая равнина"}},{q="Кто командует силами в Лагере Железного Камня?",a="Бойцами Орды здесь командует Моктар Крин. Поскольку изначальная задача сорвана нашествием насекомых, он координирует патрули и поручает путникам истреблять агрессивных силитидов, заполонивших соседний карьер.",al={"ironstone camp leader","moktar krin","who runs ironstone camp","предводитель лагеря железного камня","моктар крин","кто управляет лагерем железного камня"}},{q="Где находится Лагерь Железного Камня?",a="Лагерь расположен в Тысяче Игл, на западном краю Мерцающей равнины, неподалеку от тропы, ведущей со дна каньона к слепящей соляной равнине.",al={"ironstone camp location","where is ironstone camp","how to find ironstone camp","где лагерь железного камня","расположение лагеря железного камня","как найти лагерь железного камня"}}},fp="14,306,19.652.0,38.286.0,39.229.0,32.181.0"}
P.entries["subzone:irontree-woods"] = {n="Железнолесье",s="Железнолесье — оскверненная роща на севере Оскверненного леса, некогда любимое ночными эльфами как мирное лесное святилище. Разоренные демонической порчей Третьей войны, ее древние защитники обращены в камень, а среди руин бродят искаженные древни и элементали.",h="Железнолесье — оскверненная роща на севере Оскверненного леса, некогда любимое ночными эльфами как мирное...",kw={"ancients","felwood","hastat","irontree woods","moonwell","petrified trees","stoma","treants","vartrus","древние","оскверненный лес","хастат","железнолесье","лунный колодец","окаменевшие деревья","стома","древни","вартрус"},ang={["class:Druid"]="Искаженные болотные звери и окаменевшие Древние показывают всю разрушительность демонической порчи и взывают к чистым водам лунного колодца, способным пробудить обновление в оскверненной почве.",["race:NightElf"]="Стоять среди окаменевших остовов Хастата, Стомы и Вартруса — горькое напоминание о цене, которую Третья война взяла с ваших священных лесов."},sec={{t="Лес, обратившийся в камень",b="Железнолесье было спокойной лесной поляной, за которой ухаживали кальдораи, но демоническая скверна Пылающего Легиона во время Третьей войны высосала жизнь из ее почвы. Древние-хранители рощи — Хастат, Стома и Вартрус — поддались темной магии и обратились в безжизненные каменные изваяния, которые до сих пор стоят среди оскверненных зарослей. Теперь обезумевшие древни, мерзкие болотные звери и оскверненные водные элементали бродят по искаженной лесной земле и яростно нападают на любого путника, осмелившегося приблизиться."}},faq={{q="Что случилось с гигантскими деревьями?",a="Великие живые деревья ночных эльфов — в частности Древние по имени Хастат, Стома и Вартрус — поддались демонической порче, охватившей Оскверненный лес во время Третьей войны. Темные силы обратили их в камень, оставив замершими безжизненными изваяниями.",al={"why are trees stone","petrified ancients","irontree stone trees","почему деревья каменные","окаменевшие древние","каменные деревья железнолесья"}},{q="Почему существа в этом лесу враждебны?",a="Всепроникающая скверна Пылающего Легиона свела с ума местных обитателей леса. Древни, болотные звери и водные элементали лишились здравого рассудка и обличья и агрессивно относятся ко всему чужому.",al={"angry treants felwood","corrupted elementals irontree","злые древни оскверненный лес","оскверненные элементали железнолесье"}},{q="Сможет ли Железнолесье оправиться от порчи?",a="Роща глубоко искажена, а ее Древние-хранители мертвы и окаменели. Надежда на исцеление связана с друидами, которые стараются очистить демоническую порчу, охватившую весь Оскверненный лес.",al={"healing irontree woods","can felwood be saved","new ancient irontree","исцеление железнолесья","можно ли спасти оскверненный лес","новый древний железнолесья"}},{q="Кто раньше ухаживал за этой рощей?",a="Ночные эльфы и их союзники Древние некогда защищали эту поляну и ухаживали за ней, о чем свидетельствуют кальдорайские каменные постройки, реликвии и окаменевшие деревья-хранители, разбросанные по северу Оскверненного леса.",al={"night elf irontree","who built the statues","ночные эльфы железнолесье","кто построил статуи"}}},fp="14,296,24.509.0,38.267.0,43.239.0,52.193.0,32.207.0"}
P.entries["subzone:isle-of-dread"] = {n="Остров Ужаса",s="Остров Ужаса — пустынный остров в Великом море у юго-западного побережья Фераласа, к югу от острова Сардор. Он известен чудовищными двуглавыми химероками и укоренившимся кланом враждебных наг, скрытых в подземных морских пещерах.",h="Остров Ужаса — пустынный остров в Великом море у юго-западного побережья Фераласа, к югу от острова Сардор.",kw={"chimaerok","feathermoon","feralas","isle of dread","lakmaeran","naga","sardor isle","shalzaru","szallah","химерок","оперенная луна","фералас","остров ужаса","лакмаэран","наги","остров сардор","шалзару","сзаллах"},ang={["faction:Alliance"]="Стражи-ночные эльфы из соседней Крепости Оперенной Луны внимательно следят за островом и ищут отважных героев, чтобы нанести удар по лорду Шалзару и остановить присутствие наг у своих берегов."},sec={{t="Земля чудовищ и приливов",b="Остров Ужаса, поднимающийся из бьющего прибоя Южных морей, оправдывает свое зловещее название. Он окружен отвесными скалами, и во внутреннюю долину можно попасть только по узкой тропе на юго-восточном берегу. В этом замкнутом нагорье бродит смертоносная стая химероков — ненасытных двуглавых зверей, наделенных силой окружающей тайной магии. Их возглавляет чудовищный лорд Лакмаэран, и остров становится смертельной ловушкой для неосторожных путников, пересекающих пролив от острова Сардор."},{t="Северные пещеры",b="Пока внутреннее плато принадлежит химерокам, на северном берегу острова скрыта система пещер, занятая нагами Гребня Ненависти. Под предводительством лорда Шалзару эти змеелюды таятся в глубоких затопленных залах и замышляют зло против стражей-ночных эльфов, расквартированных в соседней Крепости Оперенной Луны. В их подземном логове есть скрытые подводные ходы, ведущие в укромные гроты, — это сильно укрепленный форпост вдали от глаз материка."}},faq={{q="Как попасть во внутреннюю часть Острова Ужаса?",a="Остров окружен высокими отвесными скалами, которые не дают подняться почти с любого берега. Единственный пеший путь на центральное плато — природная тропа на юго-восточной стороне острова.",al={"isle of dread entrance","how to get up isle of dread","climb isle of dread","вход на остров ужаса","как подняться на остров ужаса","подъем на остров ужаса"}},{q="Какие существа обитают на острове?",a="Высокое плато населяют свирепые химероки, в том числе тайные химероки и огромные пожиратели, которыми правит вершина хищной цепи — лорд Лакмаэран. На северном побережье глубокие морские пещеры кишат враждебными нагами Гребня Ненависти.",al={"isle of dread mobs","monsters on isle of dread","chimaeroks feralas","монстры острова ужаса","существа на острове ужаса","химероки фералас"}},{q="Кто предводительствует нагами в морских пещерах?",a="Клан наг, занимающий северный пещерный комплекс, возглавляет лорд Шалзару. Его присутствие — реальная угроза для ночных эльфов в соседней Крепости Оперенной Луны.",al={"isle of dread naga boss","lord shalzaru cave","naga leader feralas island","босс наг острова ужаса","пещера лорда шалзару","предводитель наг фералас"}},{q="Чем так знаменито мясо химероков?",a="Chimaeroks yield exceptionally rich tenderloins prized by master gourmands. Culinary masters like Dirge Quikcleave seek out meat from the island—including the prized carcass of Lord Lakmaeran—to craft legendary feasts.",al={"chimaerok tenderloin","dirge kickin chimaerok chops","isle of dread food"}}},fp="13,283,28.512.0,20.463.0,51.217.0,43.224.0,36.169.0,36.222.0"}
P.entries["subzone:itharius-s-cave"] = {ang={["class:Druid"]="Присутствие зеленых драконидов в болоте делает эту пещеру особенно интересной для друидов, чьи традиции тесно связаны с зеленым драконьим родом и Изумрудным Сном."},sec={{t="Отшельник среди дракончиков",b="Tucked away in the treacherous, moss-draped crags of the southwestern Swamp of Sorrows, this damp cavern shelters the recluse Itharius. Outside its mouth, unruly green whelps wander the mire. Though high elves rarely wander so far south into wild swamps alone, Itharius keeps a watchful eye on these young dragonkin as they grow, living alongside them in quiet isolation."}},faq={{q="Who lives in this cave?",a="The cave is home to Itharius, a mysterious high elf hermit who dwells apart from civilization and watches over the local dragonkin.",al={"who is itharius","cave owner","who lives here"}},{q="Where is Itharius's Cave located?",a="Она спрятана глубоко в юго-западном углу Болота Печали, у горных хребтов к югу от главной дороги.",al={"itharius cave location","where is itharius","how to find cave"}},{q="Почему у пещеры есть зеленые дракончики?",a="The surrounding marsh is inhabited by green whelps. Itharius has taken it upon himself to watch over and protect these unruly young dragons as they grow.",al={"why whelps here","green dragons swamp of sorrows","whelps outside","почему здесь дракончики","зеленые драконы болото печали","дракончики снаружи"}},{q="Почему высший эльф живет в болоте?",a="High elves are rarely seen in these southern bogs, but Itharius remains here specifically to safeguard the green dragonkin of the swamp, keeping to himself in his remote den.",al={"high elf in swamp","why is itharius here"}}},fp="15,237,21.371.0,23.131.0,33.121.0,44.153.0,43.174.0"}
P.entries["subzone:ivar-patch"] = {n="Делянка Ивара",s="Делянка Ивара — зараженная тыквенная ферма на севере Серебряного бора. Некогда процветавшее земледельческое хозяйство Лордерона, оно лишилось всех жителей во время Третьей войны, а они превратились в ненасытных, безмозглых и враждебных вурдалаков.",h="Делянка Ивара — зараженная тыквенная ферма на севере Серебряного бора.",kw={"deathstalkers","ghouls","ivar patch","ivar the foul","pumpkin patch","quinn yorick","rane yorick","silverpine forest","стражи смерти","вурдалаки","делянка ивара","ивар нечистый","тыквенная делянка","квинн йорик","ран йорик","серебряный бор"},ang={["faction:Horde"]="Истребление ненасытных вурдалаков на делянке жизненно важно для безопасности северной дороги между Серебряным бором и Подгородом.",["race:Undead"]="Разоренная ферма — горькое напоминание о Чуме нежизни, разорвавшей Лордерон на части, и показывает ужасную бессмысленную участь, которой чудом избежали Отрекшиеся."},sec={{t="Погубленный урожай",b="До того как Третья война прошла по Лордерону, эта тыквенная делянка была процветающим хозяйством фермера по имени Ивар, у которого работали бойкие батраки и слуги. Когда Плеть распространила по округе Чуму нежизни, ферма была уничтожена полностью. Ивар, его семья и работники не сохранили разум, как свободные Отрекшиеся, а превратились в гниющих диких вурдалаков, обреченных бродить по разоренной земле."},{t="Засада на Стражей смерти",b="Когда Отрекшиеся начали укреплять север Серебряного бора, три Стража смерти — Ран Йорик, Квинн Йорик и Эрланд Маккри — отправились в разведку, чтобы оценить местные угрозы. Проходя через Мертвое поле, дозор попал в засаду дикой стаи у делянки. Квинна жестоко искусал сам Ивар, ныне известный как Ивар Нечистый. Из-за тяжелой раны Квинна Йорики укрепились в старом разрушенном доме на ферме, а Маккри в одиночку двинулся дальше к Саду Мальдена."}},faq={{q="Что случилось с фермой и ее владельцем?",a="Ферму поразила Чума нежизни во время Третьей войны. Фермер Ивар, его семья и работники погибли и восстали вновь дикими гниющими вурдалаками под остаточной властью Плети.",al={"ivar patch history","who was ivar","what happened to ivar","история делянки ивара","кто такой ивар","что случилось с иваром"}},{q="Почему в доме прячутся Стражи смерти?",a="Стражи смерти Ран и Квинн Йорик входили в разведывательный отряд, посланный оценить угрозы в Серебряном боре. Проходя мимо, они попали в засаду вурдалаков, и Квинна тяжело ранил Ивар Нечистый, из-за чего им пришлось укрыться в ветхом фермерском доме.",al={"deathstalkers at ivar patch","why are forsaken here","quinn yorick farmhouse","стражи смерти на делянке ивара","почему здесь отрекшиеся","дом квинна йорика"}},{q="Относятся ли здешние вурдалаки к Отрекшимся?",a="Нет. Вурдалаки, бродящие по тыквенным полям, — безмозглые остатки Плети, созданные Чумой нежизни. У них нет свободной воли, и они нападают на любых живых путников и на Отрекшихся при виде.",al={"are these ghouls forsaken","scourge in ivar patch","why are ghouls hostile","вурдалаки отрекшиеся","плеть на делянке ивара","почему вурдалаки враждебны"}},{q="Где находится Делянка Ивара?",a="Делянка Ивара лежит на севере Серебряного бора, к северу от Мертвого поля и чуть южнее дороги, ведущей к Саду Мальдена.",al={"ivar patch location","where is ivar patch","расположение делянки ивара","где делянка ивара"}}},fp="10,241,16.461.0,23.475.1,40.206.0,52.307.0,41.184.0,32.134.0"}
P.entries["subzone:jadefire-run"] = {n="Холм Нефритового Пламени",s="Холм Нефритового Пламени — сильно укрепленный лагерь сатиров на севере Оскверненного леса. Здесь обитают самые могущественные и хитрые сатиры региона, а сам лагерь служит бастионом демонической порчи в глубине больного леса.",h="Холм Нефритового Пламени — сильно укрепленный лагерь сатиров на севере Оскверненного леса.",kw={"corrupted","demons","felwood","jadefire","jadefire run","satyr","xavaric","осквернение","оскверненный","демоны","оскверненный лес","нефритовое пламя","холм нефритового пламени","сатир","сатиры","ксаварик"},ang={["class:Druid"]="Друиды видят в мерзких ритуалах и присутствии Скверны на Холме Нефритового Пламени открытую рану, отравляющую природных духов Оскверненного леса.",["race:NightElf"]="Для ночных эльфов Холм Нефритового Пламени — чудовищное напоминание о древнем предательстве и демонической осквернении, от которого необходимо очистить священную землю Калимдора."},sec={{t="Бастион обмана",b="Холм Нефритового Пламени, расположенный среди зараженных лесов севера Оскверненного леса, служит крепостью сатиров Нефритового Пламени. В отличие от мелких застав, разбросанных по долине, в этом лагере есть внушительные демонические постройки, а в нем укрываются грозные чародеи и обманщики. Здешние сатиры деятельно замышляют распространить порчу по Калимдору, применяя темное колдовство и подлые уловки против всякого, кто посмеет вторгнуться на их землю."}},faq={{q="Что такое Холм Нефритового Пламени?",a="Холм Нефритового Пламени — крупное поселение сатиров на севере Оскверненного леса. Это главный оплот самых опасных и отборных сатиров, наводнивших лес.",al={"jadefire run info","what is this place felwood","холм нефритового пламени","что это за место оскверненный лес"}},{q="Кто правит на Холме Нефритового Пламени и кто там живет?",a="Лагерь занимают сатиры Нефритового Пламени — оскверненные слуги Пылающего Легиона, которые владеют магией Скверны и обманными иллюзиями и терроризируют окрестный лес.",al={"who lives here","jadefire run mobs","кто здесь живет","монстры холма нефритового пламени"}},{q="Почему Холм Нефритового Пламени так опасен?",a="Здешние сатиры заметно сильнее и организованнее тех, что живут на юге Оскверненного леса. Благодаря демоническим постройкам и мощным чародеям они легко одолевают неподготовленных искателей приключений.",al={"is jadefire run hard","jadefire run danger","сложен ли холм нефритового пламени","опасность холма нефритового пламени"}}},fp="12,226,19.452.0,21.170.0,35.173.0,33.190.0"}
P.entries["subzone:jaedenar"] = {n="Джеденар",s="Джеденар — зараженная лощина в центре Оскверненного леса, построенная на древних руинах ночных эльфов и друидских курганных нор. Названная в гнусную дань демону Кил'джедену, она служит главной базой Совета Теней на севере Калимдора. Сектанты, чернокнижники и призванные демоны прочесывают оскверненную лощину, охраняя подземный спуск в Оплот Теней.",h="Джеденар — зараженная лощина в центре Оскверненного леса, построенная на древних руинах ночных эльфов и...",kw={"barrow dens","deceiver","felwood","jaedenar","kil'jaeden","shadow council","shadow hold","курганные норы","искуситель","оскверненный лес","джеденар","кил'джеден","совет теней","оплот теней"},ang={["class:Druid"]="Джеденар — трагическое осквернение священной земли: его курганы, некогда мирные убежища для единения с Изумрудным Сном, теперь утопают в демонической жиже.",["class:Warlock"]="Чернокнижники Джеденара олицетворяют неизменное присутствие Совета Теней в Азероте: они открыто призывают могучих демонов и владеют нестабильным колдовством Скверны."},sec={{t="Бастион поклонения Скверне",b="Давным-давно в этих лощинах находились священные места ночных эльфов и спали друиды, связанные с Изумрудным Сном. После разрушений Третьей войны мерзкие остатки Совета Теней завладели долиной и назвали ее Джеденар в честь демона Кил'джедена. Здесь собрались чернокнижники — главным образом орки-отступники и Отрекшиеся — вместе с сатирами, суккубами и стражами Скверны. Они занимают как наземные руины, так и глубокие курганные норы, превращая некогда священный лес в мрачный центр демонических призывов."},{t="Врата Оплота Теней",b="На поверхности сектанты собираются в оскверненных местах, таких как Святилище Искусителя, жгут жаровни с мерзким пламенем и проводят ритуалы, чтобы еще сильнее осквернить лес. Под землей находится вход в Оплот Теней — подземную крепость, откуда истинные хозяева Совета направляют свои действия по всему Оскверненному лесу. Изумрудное святилище с глубокой тревогой наблюдает за гниющим анклавом и регулярно привлекает отважных странников, чтобы они разрушали круги призыва и гасили темное пламя, запечатывающее туннели."}},faq={{q="В честь чего назван Джеденар?",a="Джеденар был назван Советом Теней в поклонение Кил'джедену Искусителю, одному из верховных командиров Пылающего Легиона.",al={"jaedenar name origin","why is it called jaedenar","jaedenar namesake","происхождение названия джеденар","почему он называется джеденар","тезка джеденара"}},{q="Кто контролирует Джеденар?",a="Крепость удерживает Совет Теней — коварный заговор смертных чернокнижников, главным образом орков и Отрекшихся, служащих демонической воле Пылающего Легиона вместе с призванными исчадиями и оскверненными сатирами.",al={"who runs jaedenar","jaedenar faction","enemies in jaedenar","кто правит джеденаром","фракция джеденара","враги в джеденаре"}},{q="Что было здесь до прихода демонов?",a="До Третьей войны здесь стояли древние постройки ночных эльфов и мирные друидские курганные норы, где друиды отдыхали, странствуя по Изумрудному Сну.",al={"jaedenar history","who lived in jaedenar","jaedenar barrow dens","история джеденара","кто жил в джеденаре","курганные норы джеденара"}},{q="Что такое Оплот Теней?",a="Оплот Теней — подземная система пещер под Джеденаром. Прежде это были друидские курганные норы, а теперь здесь укрепленная штаб-квартира руководства Совета Теней в Оскверненном лесу.",al={"what is shadow hold","cave in jaedenar","underground jaedenar","что такое оплот теней","пещера в джеденаре","подземный джеденар"}}},fp="8,370,24.534.0,28.529.0,29.132.0,22.210.0,40.165.0,24.191.0"}
P.entries["subzone:jagged-reef"] = {n="Острые рифы",s="Острые рифы образуют суровое северное побережье Азшары, где песчаные пляжи встречаются с зубчатыми каменными выступами и бурным прибоем. Под мелкой водой скрываются коварные скалы, из-за чего морские путешествия невозможны. Пустынный берег населяют в основном бродящие гидры, макруры-падальщики и мурлоки, охраняющие свои земли.",h="Острые рифы образуют суровое северное побережье Азшары, где песчаные пляжи встречаются с зубчатыми каменными...",kw={"azshara","beach","coast","hydras","jagged reef","makrura","murlocs","shallows","азшара","пляж","побережье","гидры","острые рифы","макруры","мурлоки","мелководье"},ang={["class:Hunter"]="Открытые северные пляжи дают множество возможностей изучать или приручать местных земноводных зверей, например гидр и прибрежных ракообразных."},sec={{t="Опасное побережье",b="Острые рифы, протянувшиеся вдоль северного края Азшары, — суровая прибрежная полоса, где разломанные утесы и торчащие каменные выступы делят песчаные берега на уединенные бухты. Под бьющимися волнами лежат затопленные скалы и переменчивые мели, превращающие воды в кладбище для любого корабля, чья команда осмелится подойти близко. На суше дикий берег тоже неприветлив: покрытые солью звери, хищные гидры и свирепые макруры бродят по линии прибоя рядом с укрепившимися мурлоками, которые выискивают в приливах объедки и неосторожную добычу."}},faq={{q="Где находятся Острые рифы?",a="Острые рифы занимают северное побережье Азшары: участки пляжей, скалистые выступы и небольшие морские заливы вдоль северных берегов региона.",al={"jagged reef location","where is jagged reef","где острые рифы","расположение острых рифов"}},{q="Какие существа обитают на Острых рифах?",a="Побережье кишит опасными водными тварями: свирепыми мурлоками, голодными многоголовыми гидрами и бронированными макрурами, обыскивающими и мелководье, и песчаный пляж.",al={"what lives here","jagged reef mobs","monsters in jagged reef","кто здесь живет","существа острых рифов","монстры острых рифов"}},{q="Могут ли корабли плавать в водах у Острых рифов?",a="Нет. Название местность получила из-за множества коварных подводных скал и непредсказуемых мелей: плавание через рифы для любого корабля почти равносильно самоубийству.",al={"can boats sail here","jagged reef shipping","могут ли лодки плыть здесь","судоходство острые рифы"}},{q="Есть ли поселения вдоль рифов?",a="Цивилизованных поселений на Острых рифах нет. Если не считать случайных исследователей и охотников, единственное организованное присутствие — дикие стоянки мурлоков, разбросанные по берегу.",al={"towns near jagged reef","who lives at jagged reef","поселения у острых рифов","кто живет на острых рифах"}}},fp="11,320,20.546.0,33.162.0,39.183.0,53.183.0,41.191.0"}
P.entries["subzone:jaggedswine-farm"] = {n="Свиноферма",s="Свиноферма — скромное скотоводческое хозяйство на севере Дуротара, чуть южнее главного входа в Оргриммар. Она состоит из деревянного склада, просторного загона и грязного водопоя и служит важным источником пищи: здесь выращивают выносливых свиней для близкой столицы Орды.",h="Свиноферма — скромное скотоводческое хозяйство на севере Дуротара, чуть южнее главного входа в Оргриммар.",kw={"boars","durotar","horde provisions","jaggedswine farm","orgrimmar","pig pen","pigs","swine","кабаны","дуротар","провиант орды","свиноферма","оргриммар","свиной загон","свиньи"},ang={["faction:Horde"]="Наладить стабильные поставки мяса в засушливых пустошах Дуротара — вопрос выживания, поэтому такие форпосты, как Свиноферма, жизненно важны для военной мощи Оргриммара.",["profession:Cooking"]="Для поваров Орды, осваивающих ремесло в Дуротаре, обилие свиней у Свинофермы делает ее главным местным источником нежных ребрышек, кусков свинины и жира для готовки."},sec={{t="Провиант для столицы",b="Свиноферма, вырубленная в суровой, выжженной солнцем земле Дуротара, показывает, как нелегко кормить такой городок-крепость, как Оргриммар. Красная почва региона почти не родит, поэтому крепкий скот необходим, чтобы кормить тысячи орочьих воинов и работников. Хозяйство держится на деревянном амбаре, широком загоне и естественном пруду-водопое, где свиней пасут, разводят и забивают, чтобы амбары Орды не пустовали."},{t="Тихий рубеж",b="Хотя на ферме тихо и под сухим зноем она часто выглядит полузаброшенной, здесь регулярно бывают местные свинопасы и патрулирующие Оргриммар грунты. Дикие и взрослые свиньи бродят и в загонах, и за их пределами, порой испытывая терпение стражи неподалеку. Расположенный прямо у подхода к долине столицы, участок остается неприметным, но необходимым звеном в повседневном снабжении Дуротара."}},faq={{q="Для чего нужна Свиноферма?",a="На ферме разводят и содержат свиней, чтобы обеспечить Орду мясом и салом, прежде всего для пропитания жителей и гарнизона соседнего Оргриммара.",al={"what is jaggedswine farm","why is there a pig farm in durotar","jaggedswine farm purpose","что такое свиноферма","зачем свиноферма в дуротаре","назначение свинофермы"}},{q="Где именно находится Свиноферма?",a="Она лежит на севере Дуротара, у южного подхода и больших ворот, ведущих в Аллею Силы в Оргриммаре.",al={"where is jaggedswine farm","how to get to jaggedswine farm","pig farm durotar location","где свиноферма","как добраться до свинофермы","свиноферма дуротар"}},{q="Почему ферма выглядит почти пустой?",a="Орочье скотоводство в Дуротаре утилитарно и непритязательно. Из-за свободно бродящих кабанов и редких деревянных построек в хозяйстве нет больших усадеб, но Орда по-прежнему активно использует его для снабжения.",al={"is jaggedswine farm abandoned","who lives at jaggedswine farm","why no farmers","заброшена ли свиноферма","кто живет на свиноферме","почему нет фермеров"}},{q="Опасны ли здешние свиньи для путников?",a="Домашние свиньи в загонах смирные, но дикие и взрослые кабаны на окраинах могут напасть, если их напугают юные путники или неосторожные собиратели.",al={"are swine hostile","do pigs attack here","swine dangerous","опасны ли свиньи","нападают ли свиньи","свиньи опасны"}}},fp="16,287,26.461.0,16.432.0,40.145.0,42.139.0,41.213.0,41.171.0"}
P.entries["subzone:jaguero-isle"] = {n="Остров Жагуаро",s="Остров Жагуаро — уединенный остров, поросший джунглями, у восточного побережья Пустынного берега в Тернистой долине. Здесь властвуют свирепые дикие пантеры и гориллы, а остров известен как владения огромной гориллы-серебряной спины по имени король Мукла.",h="Остров Жагуаро — уединенный остров, поросший джунглями, у восточного побережья Пустынного берега в Тернистой...",kw={"gorilla","jaguero","jaguero isle","king mukla","panther","princess poobah","stranglethorn","wild shore","горилла","жагуаро","остров жагуаро","король мукла","пантера","принцесса пуба","тернистая долина","пустынный берег"},ang={["class:Hunter"]="Экзотические хищники острова Жагуаро, от крадущихся пантер до самого могучего короля Муклы, становятся неотразимым испытанием для опытных охотников."},sec={{t="Первобытные владения",b="Остров Жагуаро лежит у юго-восточного побережья Тернистой долины, вдали от пиратских лагерей и тролльских руин материка. Остров целиком захвачен дикими животными, в основном пантерами и агрессивными гориллами. Над всеми ними возвышается гигантский примат король Мукла, чья власть над скалистой глубиной острова безраздельна. Немногие моряки по своей воле подходят к его рифам, хотя бутылки, выброшенные на пляжи материка, порой несут отчаянные мольбы о спасении от несчастных, оказавшихся на берегу."},{t="Пленная принцесса",b="Самая необычная и опасная история острова связана с принцессой Пуба, тауренкой, потерпевшей кораблекрушение и плененной королем Муклой. Оказавшись на острове, кишащем хищниками, она сумела отправить послания о помощи в бутылках по волнам Пустынного берега в надежде, что проходящий мимо искатель приключений рискнет навлечь гнев Муклы и поможет ей бежать."}},faq={{q="Где находится остров Жагуаро?",a="Остров Жагуаро лежит в Великом море у юго-восточного побережья Тернистой долины, к востоку от Пустынного берега.",al={"jaguero isle location","where is jaguero","find jaguero isle","где остров жагуаро","расположение острова жагуаро","найти остров жагуаро"}},{q="Кто такой король Мукла?",a="King Mukla is a gigantic, powerful gorilla who reigns over Jaguero Isle. Territorial and aggressive, he dominates the island's interior.",al={"mukla","king mukla gorilla","ape boss stranglethorn","мукла","король мукла горилла","босс обезьян тернистая долина"}},{q="Кто такая принцесса Пуба?",a="Princess Poobah is a stranded tauren trapped on Jaguero Isle far from her home. She casts messages in bottles into the sea in hopes of being rescued.",al={"tauren captive","who is poobah","princess poobah","пленная тауренка","кто такая пуба","принцесса пуба"}},{q="Как начать задание, чтобы посетить остров?",a="Искатели приключений обычно узнают о ее беде, найдя наполовину зарытые в песок бутылки, выброшенные на материковые пляжи Пустынного берега, с аккуратно сложенной запиской с просьбой о помощи.",al={"message in a bottle quest","jaguero island quest","how to get to jaguero","задание бутылка с запиской","задание остров жагуаро","как попасть на остров жагуаро"}}},fp="12,249,15.540.0,20.355.1,30.120.0,18.136.0,23.149.0,47.179.0"}
P.entries["subzone:janeiro-s-point"] = {n="Остров Жанейро",s="Остров Жанейро — небольшой скалистый остров прямо у гавани Пиратской бухты на юге Тернистой долины. Его венчает колоссальная каменная статуя неизвестного гоблина, приветствующего корабли распростертыми руками. Воды и берега острова во власти грозного морского великана Мок'раша Колуна.",h="Остров Жанейро — небольшой скалистый остров прямо у гавани Пиратской бухты на юге Тернистой долины.",kw={"booty bay","goblin statue","janeiro's point","mok'rash","sea giant","stranglethorn","пиратская бухта","статуя гоблина","остров жанейро","мок'раш","морской великан","тернистая долина"},sec={{t="Маяк бухты",b="Остров Жанейро — монументальные врата Пиратской бухты — встречает каждый корабль, идущий в южные моря Тернистой долины. На вершине утеса высится огромное каменное изваяние гоблина с раскинутыми руками — жест радушия и безудержных торговых амбиций. Хотя остров виден морякам и корсарам за много миль, высадка на его берег опасна: скалу объявил своей территорией Мок'раш Колун, жуткий морской великан."}},faq={{q="Что такое остров Жанейро?",a="Остров Жанейро — небольшой скалистый остров недалеко от берега, у гавани Пиратской бухты в Тернистой долине. Он служит ориентиром для кораблей, подходящих к гоблинскому порту.",al={"janeiro point","what is this island","booty bay statue island","остров жанейро","что за остров","остров со статуей пиратской бухты"}},{q="Кого изображает гигантская статуя на острове?",a="Колоссальная статуя изображает неизвестного гоблина с раскинутыми руками. Ее воздвигли, чтобы приветствовать торговые корабли и усталых моряков в торговой гавани Пиратской бухты.",al={"statue identity","who is the goblin statue","who is depicted","личность статуи","кто гоблин на статуе","кто изображен"}},{q="Какое опасное существо живет на острове Жанейро?",a="Остров и окружающие мели — владения Мок'раша Колуна, грозного морского великана, смертельно опасного для любых отважных моряков и пловцов, пытающихся приблизиться к статуе.",al={"sea giant island","who lives on janeiro point","mokrash","остров морского великана","кто живет на острове жанейро","мок'раш"}}},fp="15,342,17.496.0,24.178.0,38.163.0,49.205.0"}
P.entries["subzone:jangolode-mine"] = {s="Рудник Янго — богатая шахта в холмах Западного Края. Когда-то он был важным источником руды и сырья для Штормграда, но теперь его захватили бандиты из Братства Справедливости.",h="Рудник Янго — богатая шахта в холмах Западного Края.",kw={"defias brotherhood","jangolode","jangolode mine","kobold","stormwind","westfall","братство справедливости","рудник янго","кобольд","штормград","западный край"},ang={["faction:Alliance"]="Возвращение ресурсов Западного Края жизненно важно для стабилизации королевства, а изгнание бандитов из Рудника Янго — шаг к возрождению процветания региона.",["profession:Mining"]="Рудник Янго по-прежнему богат залежами меди и олова, что делает его выгодной остановкой для старателей, готовых прорваться через подземных вредителей."},sec={{t="Разграбленное богатство",b="Пока Западный Край не пришел в упадок, Рудник Янго давал стабильный поток металлов, необходимых для восстановления и снабжения Штормграда. Когда порядок рухнул, а королевство вывело гарнизоны, Братство Справедливости захватило рудник для собственных нужд. Теперь бандиты сами разрабатывают богатые жилы и яростно защищают свою подземную добычу."}},faq={{q="Что такое Рудник Янго?",a="Это место добычи в Западном Крае, которое исторически снабжало Штормград необходимыми минералами и металлической рудой. Когда оборона региона ослабла, рудник попал в руки врагов.",al={"jangolode mine info","what is jangolode","jangolode westfall","рудник янго","что такое янго","янго западный край"}},{q="Кто сейчас контролирует рудник?",a="Подземные штольни удерживает Братство Справедливости, изгнав прежних шахтеров ради собственных нужд.",al={"who is in jangolode mine","jangolode mobs","who lives in jangolode","кто в руднике янго","существа рудника янго","кто живет в руднике янго"}},{q="Почему Штормград не вернет себе рудник?",a="Штормград погряз в политических волнениях и с трудом защищает даже основные границы. У королевства нет войск для гарнизонов в дальних рудниках Западного Края, и угрозой занимаются Народное ополчение и местные искатели приключений.",al={"why doesnt stormwind clear jangolode","stormwind garrison westfall","why abandon the mine","почему штормград не очистит рудник янго","гарнизон штормграда западный край","почему бросили рудник"}}},fp="14,217,20.391.0,27.177.0,32.120.0,40.228.0"}
P.entries["subzone:jasperlode-mine"] = {n="Яшмовая шахта",s="Яшмовая шахта — железный и минеральный рудник на севере центральной части Элвиннского леса, когда-то снабжавший Штормград важными ресурсами. Сегодня ее штольни наводнили кобольды и смертоносные гигантские пауки, и королевство, испытывающее нехватку ресурсов, не может вернуть шахту себе.",h="Яшмовая шахта — железный и минеральный рудник на севере центральной части Элвиннского леса, когда-то...",kw={"elwynn forest","fargodeep","gold dust","goldshire","jasperlode","kobold","marshal dughan","mother fang","элвиннский лес","рудник подземных глубин","золотая пыль","златоземье","яшмовая шахта","кобольд","маршал дугхан","мать клык"},ang={["faction:Alliance"]="Добыча сырого металла в Яшмовой шахте жизненно важна для снабжения Штормграда снаряжением, пока границам королевства постоянно угрожает опасность.",["profession:Mining"]="Яшмовая шахта богата рудными жилами и остается заманчивой целью для старателей, готовых пробиться сквозь кобольдовы кирки и паучьи сети, чтобы застолбить участок."},sec={{t="Утраченный ресурс Элвиннского леса",b="Яшмовая шахта исторически была одним из самых продуктивных рудников Штормграда и вместе с соседним Рудником Подземных Глубин обеспечивала стабильный приток минералов. Поскольку армия королевства растянута на защите от внешних угроз и беспорядков, местные гарнизоны не смогли защитить штольни. Кобольды воспользовались случаем, пробрались внутрь, выгнали людей-шахтеров и накопили украденное золото и сальные свечи."},{t="Опасности в глубине",b="Беда Яшмовой шахты не ограничивается обычными вредителями. В самых глубоких и темных коридорах под деревянными опорами обосновалась агрессивная колония шахтных пауков. Ее возглавляет огромная самка, известная местным как Мать Клык. Пауки без труда охотятся и на забредших кобольдов, и на неосторожных старателей, поэтому любая попытка вернуть шахту крайне опасна."}},faq={{q="Почему Яшмовую шахту захватили?",a="Регулярная армия Штормграда растянута по всему королевству, и в сельских аванпостах вроде Златоземья не хватает людей. Кобольды быстро воспользовались ситуацией и заполонили выработки, когда шахтеры лишились охраны.",al={"why are there kobolds","who controls jasperlode","why abandoned","почему там кобольды","кто контролирует яшмовую шахту","почему заброшена"}},{q="Чем Яшмовая шахта отличается от Рудника Подземных Глубин?",a="Рудник Подземных Глубин находится на юге, рядом с фермами Маклюр и Стоунфилд, а Яшмовая шахта лежит на севере, в предгорьях у реки. Оба — крупные месторождения Элвиннского леса, потерянные из-за нашествия кобольдов.",al={"jasperlode vs fargodeep","other elwynn mine","яшмовая шахта или рудник подземных глубин","другая шахта элвиннского леса"}},{q="Что скрывается в глубине шахты?",a="Самые глубокие штольни заполонили хищные шахтные пауки во главе с огромным паукообразным по прозвищу Мать Клык. Даже кобольды-захватчики избегают их паутинных пещер.",al={"spiders in jasperlode","mother fang","what is at the bottom","пауки в яшмовой шахте","мать клык","что в глубине шахты"}},{q="Почему маршал Дугхан не очистил шахту?",a="У маршала Дугхана не хватает солдат для долгой зачистки подземелий. Из-за речных патрулей против Братства Справедливости, набегов гноллов и гарнизонной службы местное ополчение вынуждено полагаться на странствующих искателей приключений, которые разведают шахту и сократят число угроз.",al={"why no stormwind guard","dughan sending soldiers","почему нет стражи штормграда","дугхан отправляет солдат"}}},fp="15,272,25.414.0,19.391.0,31.218.0,56.215.0,35.162.0,43.235.0"}
P.entries["subzone:jerod-s-landing"] = {n="Лагерь Джерода",s="Лагерь Джерода — скромная речная пристань на берегу реки Назферити со стороны Элвиннского леса. Сейчас ее удерживает Братство Справедливости, и лагерь служит тайным пунктом перевалки незаконных грузов, которые провозят по водным путям королевства.",h="Лагерь Джерода — скромная речная пристань на берегу реки Назферити со стороны Элвиннского леса.",kw={"defias dockmaster","jerod's landing","klaven's tower","mathias shaw","nazferiti river","smuggling","snatch and grab","начальник причала братства справедливости","лагерь джерода","башня клейвена","матиас шоу","река назферити","контрабанда","хватай и беги"},ang={["class:Rogue"]="Разбойников, работающих на ШРУ, отправляют в Лагерь Джерода: проверить скрытность, обчистить карманы начальника причала Братства Справедливости и добыть секретные торговые книги.",["faction:Alliance"]="Захват Лагеря Джерода показывает, как основательно Братство Справедливости подчинило внутренние водные пути между Элвиннским лесом и Красногорьем прямо под носом у Штормграда."},sec={{t="Путевая точка контрабандистов",b="Лагерь Джерода, спрятанный на восточных водах реки Назферити, дает выход к реке, соединяющей Элвиннский лес с соседними землями. Прежде это была обычная лодочная пристань, но теперь она прочно оказалась в руках Братства Справедливости. Под присмотром начальника причала Братства разбойники используют пристань как узел для приема товаров, награбленных в Красногорье, и тайно переправляют речные грузы вниз по течению к таким владениям, как Башня Клейвена в Западном Крае."},{t="Глаза в тени",b="Из-за выгодного положения на реке Лагерь Джерода привлек внимание ШРУ, тайной разведывательной службы Штормграда. Агенты, следящие за действиями Братства Справедливости, считают лагерь важным звеном в цепи снабжения синдиката и отправляют туда находчивых разбойников: проникнуть на причалы, выкрасть книги учета речных грузов и раскрыть более широкий заговор, душащий королевство."}},faq={{q="Где находится Лагерь Джерода?",a="Лагерь Джерода находится на востоке Элвиннского леса, на западном берегу реки Назферити, которая служит границей между Элвиннским лесом и Красногорьем.",al={"jerods landing location","where is jerod's landing","jerod dock map","где лагерь джерода","лагерь джерода на карте","пристань джерода"}},{q="Кто контролирует Лагерь Джерода?",a="Лагерь занят членами Братства Справедливости под началом начальника причала, который согласовывает поставки с вооруженными бандитами, охраняющими берег.",al={"who is at jerods landing","defias at jerods landing","jerod landing mobs","кто в лагере джерода","братство справедливости в лагере джерода","мобы лагеря джерода"}},{q="Зачем Братству Справедливости эта пристань?",a="Братство использует пристань как перевалочный пункт для контрабанды: краденые товары и оружие, перехваченные в Красногорье, отправляют в разбойничьи твердыни вроде Башни Клейвена в Западном Крае.",al={"why do defias use jerods landing","defias river smuggling","зачем братство справедливости использует лагерь джерода","речная контрабанда"}},{q="Почему ШРУ интересуется Лагерем Джерода?",a="Мастер Матиас Шоу и его агенты отслеживают поток контрабанды Братства Справедливости через эту пристань, чтобы раскрыть сеть, связывающую Западный Край, Элвиннский лес и Красногорье.",al={"si7 jerods landing","rogue quest jerods landing","шру лагерь джерода","задание разбойника лагерь джерода"}}},fp="15,255,21.490.0,19.384.1,33.175.0,29.163.0,48.194.0,42.163.0"}
P.entries["subzone:karazhan"] = {n="Каражан",s="Каражан — зловещая уединенная башня на южной оконечности Перевала Мертвого Ветра. Когда-то это было святилище Медива, Последнего Стража Тирисфаля; цитадель стоит на мощном средоточии энергетических линий, которое искажает вокруг себя время, пространство и реальность. Хотя Медив был убит во время Первой войны, заброшенная крепость по-прежнему гудит нестабильной тайной энергией, неупокоенными духами и скрытыми опасностями.",h="Каражан — зловещая уединенная башня на южной оконечности Перевала Мертвого Ветра.",kw={"aegwynn","dark riders","deadwind pass","guardian","karazhan","khadgar","medivh","moroes","sargeras","tirisfal","эгвин","темные всадники","перевал мертвого ветра","страж","каражан","кадгар","медив","мороуз","саргерас","тирисфаль"},ang={["class:Mage"]="Каражан — памятник высотам и опасностям смертной магии. Здесь хранится непревзойденное собрание артефактов и трудов, которые когда-то не отдавали Кирин-Тору, однако нестабильные энергетические линии грозят поглотить любого неосторожного чародея.",["faction:Alliance"]="Башня имеет трагическое значение для королевства Штормград. Здесь жил Медив — друг детства короля Ллейна Ринна и Андуина Лотара, — чье предательство, совершенное изнутри этих стен, обрушило Первую войну на человечество."},sec={{t="Шпиль Стража",b="Задолго до Первой войны башню Каражан возвели на земле в форме человеческого черепа, в огромном узле мистических энергетических линий. Она служила уединенным убежищем и хранилищем несметных магических тайн для Стража Эгвин, а позже ее сына Медива. В ее изогнутых залах Медив жил со своим верным управляющим Мороузом, принимал знатных гостей и хранил огромный архив тайных текстов и реликвий, превосходивший даже библиотеки Кирин-Тора. Но башня стала и сценой величайшего предательства Азерота: Медив попал под демоническую власть Саргераса и втайне устроил открытие Темного портала."},{t="Призрачный порог",b="После гибели Медива от рук Андуина Лотара и его ученика Кадгара Каражан запер врата и был оставлен на разрушение. Однако башня так и не уснула по-настоящему. Пересечение могущественных энергетических линий продолжает искажать ткань реальности, порождая призрачные отголоски, иллюзии и временные искажения по всему Перевалу Мертвого Ветра. Ходят слухи, что в тихой крепости вновь пробуждается злое присутствие, а странные существа, включая зловещих Темных всадников, прочесывающих окрестные земли в поисках забытых реликвий, неумолимо влекутся к ее высокому силуэту."}},faq={{q="Кто построил Каражан?",a="Каражан был возведен примерно за шесть столетий до Первой войны Эгвин, Магной Совета Тирисфаля. Искав уединенное убежище вдали от любопытных глаз Кирин-Тора и Совета, она подключилась к мощному узлу энергетических линий на Перевале Мертвого Ветра, чтобы черпать энергию для своих магических защит.",al={"who made karazhan","karazhan creator","origin of karazhan","кто построил каражан","создатель каражана","происхождение каражана"}},{q="Кто такой Медив и почему он жил здесь?",a="Медив был сыном Эгвин и Последним Стражем Тирисфаля, призванным защищать Азерот от демонических угроз. Он сделал Каражан своим главным домом и убежищем, окружив себя огромными запасами тайных знаний, слугами вроде Мороуза и пышными приемами, скрывавшими его падение в безумие.",al={"who lived in karazhan","medivh lore","the last guardian","кто жил в каражане","предания о медиве","последний страж"}},{q="Что случилось с Медивом в башне?",a="Мир не знал, что Медива с рождения одержимо дух Темного Титана Саргераса. Под этим демоническим влиянием он использовал магию башни, чтобы связаться с чернокнижником Гул'даном и открыть Темный портал. Узнав о предательстве, его ученик Кадгар, лорд Андуин Лотар и полуорк Гарона проникли в Каражан и убили Стража, положив конец его порче.",al={"how did medivh die","medivh death","fall of medivh","как умер медив","смерть медива","падение медива"}},{q="Можно ли сейчас войти в Каражан?",a="Нет. Главные врата и порог башни остаются крепко запечатанными и защищенными от чужаков. Путники могут бродить по заброшенной деревне, разрушающейся церкви и мрачным подземным подвалам вокруг, но сам шпиль наглухо закрыт.",al={"can i go inside karazhan","is karazhan open","entering karazhan","можно ли войти в каражан","открыт ли каражан","вход в каражан"}},{q="Почему земля вокруг Каражана так осквернена и мертва?",a="Каражан стоит на древнем эпицентре магического насилия, где ткань реальности была разорвана задолго до постройки башни. Вместе с огромной концентрацией чистой энергии линий под ним и темным демоническим колдовством, которое Медив творил внутри, окружающий каньон засох и превратился в безжизненную пустошь — Перевал Мертвого Ветра.",al={"why is deadwind pass dead","karazhan curse","why deadwind pass empty","почему перевал мертвого ветра мертв","проклятие каражана","почему перевал мертвого ветра пуст"}},{q="Кто такие Темные всадники, связанные с башней?",a="Темные всадники — призрачные фигуры, возникшие, когда Медив проклял шайку торговцев-шарлатанов, пытавшихся продать ему поддельные магические безделушки. Связанные его могучим проклятием, всадники обречены прочесывать земли и добывать подлинные могущественные магические артефакты, чтобы доставлять их в башню.",al={"what are the dark riders","riders of deadwind pass","karazhan riders","кто такие темные всадники","всадники перевала мертвого ветра","всадники каражана"}}},fp="8,395,20.665.0,19.587.0,19.306.0,41.302.0,37.380.0,33.255.0,54.350.0,47.298.0"}
P.entries["subzone:kargath"] = {n="Каргат",s="Каргат — укрепленный аванпост Орды в западных Бесплодных землях, ее единственный оплот в Каз Модане. Основанное Экспедиционным корпусом Каргата по приказу вождя Тралла, поселение связывает важные пути через Восточные королевства и служит базой для операций в направлении Черной горы и раскопок в Ульдамане.",h="Каргат — укрепленный аванпост Орды в западных Бесплодных землях, ее единственный оплот в Каз Модане.",kw={"badlands","blackrock mountain","expeditionary force","kargath","kargath bladefist","shattered hand","thrall","uldaman","бесплодные земли","черная гора","экспедиционный корпус","каргат","каргат острорукий","изувеченная длань","тралл","ульдаман"},ang={["faction:Horde"]="Каргат — единственная дружественная Орде крепость во всем Каз Модане, дающая необходимое снабжение, воздушное сообщение и плацдарм для ударов по Черной горе.",["race:Orc"]="Аванпост носит имя вождя Каргата Острорука и напрямую продвигает кампанию Тралла по уничтожению развращенной Темной Орды Ренда Чернорука."},sec={{t="Бастион во вражеских землях",b="Аванпост Каргат назван в честь вождя клана Изувеченная Длань Каргата Острорука и остается единственным поселением Орды в горных землях Каз Модана. Окруженный сухими пустошами, агрессивными зверями и враждебными дворфийскими кланами, гарнизон дает путникам, пересекающим континент, важное убежище на полпути. Его распорядитель полетов соединяет северные владения, такие как Подгород и Павший Молот, с южными оплотами вроде Каменора и Лагеря Гром'гол."},{t="Экспедиционная миссия",b="Экспедиционный корпус Каргата, посланный по прямому приказу вождя Тралла, преследует в регионе две цели. Отряды часто совершают вылазки в древние титанские залы Ульдамана, чтобы выяснить, почему исследователи Стальгорна так дорожат раскопками. Одновременно разведчики прокладывают путь через Тлеющее ущелье к Черной горе, чтобы ударить по ложной «Темной Орде» Ренда Чернорука и справиться с укоренившимися дворфами Черного Железа."}},faq={{q="Почему этот город Орды стоит посреди Бесплодных земель?",a="Вождь Тралл приказал Экспедиционному корпусу Каргата основать аванпост, чтобы закрепиться в регионе, исследовать тайны дворфийских раскопок в Ульдамане и проложить путь вторжения в Черную гору против Темной Орды.",al={"why is kargath here","purpose of kargath","who built kargath","почему здесь каргат","зачем нужен каргат","кто построил каргат"}},{q="В честь кого назван Каргат?",a="Аванпост назван в честь Каргата Острорука, знаменитого вождя орочьего клана Изувеченная Длань.",al={"kargath name origin","who was kargath","kargath bladefist outpost","происхождение названия каргат","кто такой каргат","аванпост каргата острорукого"}},{q="Почему маршруты полетов из Каргата так важны?",a="Каргат служит важным логистическим звеном, соединяющим аванпосты Орды на севере Лордерона, такие как Подгород и Павший Молот, с южными владениями в Тернистой долине и на Болоте Печали.",al={"kargath flight path","why fly to kargath","полеты из каргата","зачем лететь в каргат"}},{q="К борьбе с какой угрозой готовится гарнизон Каргата?",a="Гарнизон регулярно сражается с местными дворфами Черного Железа, изучает присутствие Стальгорна в Ульдамане и готовит наступление на Ренда Чернорука и его соперничающую Темную Орду, засевшую в Черной горе.",al={"kargath enemies","who does kargath fight","враги каргата","с кем воюет каргат"}}},fp="7,349,30.500.0,25.467.0,57.240.0,27.97.0,52.206.0,58.221.0"}
P.entries["subzone:kargathia-keep"] = {n="Крепость Каргатия",s="Крепость Каргатия — укрепленный оплот Орды, защищающий восточный рубеж Лесозаготовок Песни Войны в Ясеневом лесу. Здесь расположена штаб-квартира надсмотрщиков поселения; крепость охраняет границу по реке и обеспечивает быстрое подкрепление прямо из Оргриммара.",h="Крепость Каргатия — укрепленный оплот Орды, защищающий восточный рубеж Лесозаготовок Песни Войны в Ясеневом...",kw={"ashenvale","kargath bladefist","kargathia keep","kargathia outpost","overseer gorthak","southfury river","warsong lumber camp","ясеневый лес","каргат острорук","крепость каргатия","форпост каргатия","надсмотрщик горсак","река строптивая","лесозаготовки песни войны"},ang={["faction:Horde"]="Для защитников Орды Крепость Каргатия — незаменимое убежище на передовой Ясеневого леса, обеспечивающее сохранность ценной древесины, жизненно важной для строительства Оргриммара.",["race:NightElf"]="Для ночных эльфов этот ощетинившийся шипами оплот олицетворяет агрессивное, глубоко укоренившееся вторжение Орды в их священный родовой лес."},sec={{t="Бастион на Строптивой",b="Крепость Каргатия стоит на восточной окраине Лесозаготовок Песни Войны, к западу от реки Строптивая, и служит командным центром лесозаготовок Орды в Ясеневом лесу. Этот укрепленный форпост, усиленный тяжелыми баррикадами с шипами, занимают надсмотрщик Горсак и его офицеры. Благодаря расположению у речной границы клан Песни Войны следит за вторжениями и получает быстрое подкрепление из соседних земель Дуротара и Оргриммара, когда ночные эльфы нападают."},{t="В честь Острорука",b="Как крепость Каргат в Бесплодных землях и Бухта Острорука на побережье Дуротара, этот форпост назван в честь знаменитого вождя Каргата Острорука. Для орков Песни Войны, отважившихся войти во враждебные чащи Ясеневого леса, внушительная классическая архитектура крепости — неизменный символ воинской стойкости и непокорности Орды на земле, захваченной ночными эльфами."}},faq={{q="Где находится Крепость Каргатия?",a="Крепость Каргатия находится в восточной части Ясеневого леса, на восточной окраине Лесозаготовок Песни Войны, к западу от реки Строптивая.",al={"kargathia keep location","where is kargathia keep","kargathia outpost location","где крепость каргатия","расположение крепости каргатия","форпост каргатия"}},{q="Кто командует крепостью?",a="Надсмотрщик Горсак руководит Лесозаготовками Песни Войны из Крепости Каргатия: он управляет заготовкой леса и координирует оборону от нападений Альянса.",al={"who is in charge of kargathia keep","kargathia keep leader","overseer gorthak","кто командует крепостью каргатия","глава крепости каргатия","надсмотрщик горсак"}},{q="Почему крепость назвали Каргатия?",a="Оплот назван в честь Каргата Острорука, легендарного вождя клана Изувеченная Длань; то же имя носят Каргат в Бесплодных землях и Бухта Острорука в Дуротаре.",al={"who is kargathia keep named after","kargath bladefist","why kargathia","в честь кого названа крепость каргатия","каргат острорук","почему каргатия"}},{q="Каково стратегическое назначение этого оплота?",a="Крепость контролирует восточную границу лесозаготовок вдоль реки Строптивая, защищает важный путь снабжения и позволяет быстро переправлять подкрепление из Оргриммара.",al={"why is kargathia keep here","purpose of kargathia keep","kargathia keep importance","зачем нужна крепость каргатия","назначение крепости каргатия","значение крепости каргатия"}}},fp="14,261,26.521.0,22.373.0,32.129.0,19.158.0,33.195.0,49.185.0"}
P.entries["subzone:kharanos"] = {n="Каранос",s="Каранос — оживленное горное поселение в заснеженном сердце Дун Морога, неподалеку от Стальгорна. Это главный пункт для путников, покидающих Холодную долину; здесь есть кузница, гномьи мастерские и знаменитая таверна «Громоварка».",h="Каранос — оживленное горное поселение в заснеженном сердце Дун Морога, неподалеку от Стальгорна.",kw={"distillery","dun morogh","frostmane","kharanos","lazlo grindwidget","shimmer ridge","thunderbrew","таверна","дун морог","мерзлогрив","каранос","лазло гриндвиджет","мерцающий хребет","громоварское"},ang={["race:Dwarf"]="Для дворфов, покидающих укромные утесы Туннеля Холодной долины, Каранос — первое знакомство с большим королевством, полное дымящихся кузниц и легендарного крепкого эля клана Громоваров.",["race:Gnome"]="Беженцы и механики из Гномрегана часто обосновываются в Караносе и его окрестностях, сотрудничая с местными кузнецами и работая из ближайших складов."},sec={{t="Гостеприимный приют на границе",b="Каранос, расположенный у центральной дороги Дун Морога, — первый настоящий город для новобранцев из Старой Наковальни. Несмотря на лютый холод и ветры, поселение процветает благодаря стойкости дворфов и изобретательности гномов. В его центре — гудящая общая кузница и таверна «Громоварка», известная в восточных горах одним из лучших эля в Каз Модане. Среди ремесленников и усталых путников, ищущих тепла, город служит главным опорным пунктом для дел в нижних горах."},{t="На страже низин",b="За уютными очагами Каранос служит важным военным форпостом, охраняющим горные перевалы. Свирепые местные вендиго бродят по ледяным пещерам прямо на западе, а воинственные тролли Мерзлогривы укрепились на Мерцающем хребте к северо-западу. Поскольку регулярные войска Стальгорна разбросаны по королевству, город сильно зависит от приезжих искателей приключений и местной стражи, которые отражают набеги, истребляют опасных хищников и держат торговые пути открытыми."}},faq={{q="Что такое Каранос?",a="Каранос — главное поселение дворфов и гномов в центральной части Дун Морога. Он служит перекрестком между Холодной долиной, Стальгорном и дикими землями, здесь есть торговцы, учителя и таверна.",al={"kharanos overview","where is kharanos","kharanos town","каранос","где находится каранос","город каранос"}},{q="Какие службы и удобства есть в Караносе?",a="В городе есть знаменитая таверна «Громоварка», где можно поесть и отдохнуть, большая общая кузница, а также учителя классов и профессий. Соседние мастерские, например Поселок Сталежара, снабжают механизмами для инженерного дела.",al={"kharanos trainers","what is in kharanos","kharanos inn"}},{q="Какие угрозы нависли над городом?",a="Каранос постоянно испытывает давление со стороны воинственных племен троллей Мерзлогривов на Мерцающем хребте к северо-западу и хищных вендиго, бродящих по ледяным пещерам прямо на западе.",al={"kharanos enemies","frostmane trolls kharanos","wendigo kharanos","враги каранос","тролли мерзлогривы каранос","вендиго каранос"}},{q="Кто такой Лазло Гриндвиджет?",a="Лазло Гриндвиджета помнят как местного народного героя, спасшего Каранос, когда огромный тролль Мерзлогрив напал на поселение и едва не одолел защитников-дворфов.",al={"lazlo hero","who saved kharanos","giant troll attack kharanos","лазло герой","кто спас каранос","нападение гигантского тролля каранос"}}},fp="8,268,23.544.0,21.508.0,17.221.0,45.237.0,31.190.0,26.173.0"}
P.entries["subzone:kodo-rock"] = {n="Дольмен Кодо",s="Дольмен Кодо — природный каменный монумент на равнинах Плато Красного Облака, между Лагерем Нараче и Ежевичной лощиной. Он тихо стоит среди трав Мулгора и служит ранним местом паломничества для молодых шаманов-таурен, учащихся общаться с духами земли. Из-за скромного силуэта на фоне холмистого пейзажа путникам нужно быть очень внимательными, чтобы его заметить.",h="Дольмен Кодо — природный каменный монумент на равнинах Плато Красного Облака, между Лагерем Нараче и...",kw={"brambleblade ravine","camp narache","kodo rock","monument","mulgore","red cloud mesa","shaman trial","tauren shaman","ежевичная лощина","лагерь нараче","дольмен кодо","монумент","мулгор","плато красного облака","испытание шамана","шаман таурен"},ang={["class:Shaman"]="Для начинающих шаманов-таурен, вступающих на духовный путь в Лагере Нараче, Дольмен Кодо — важный ориентир, где они настраиваются на мир стихий.",["race:Tauren"]="Каменное образование служит знакомым ориентиром на равнинах Плато Красного Облака и отражает священную связь Шу'хало со зверями Мулгора."},sec={{t="Ориентир на плато",b="Дольмен Кодо расположен примерно на полпути между Лагерем Нараче и враждебными землями свинобразов в Ежевичной лощине; у его основания виднеется участок истоптанной земли. Хотя ему не хватает величия высоких утесов вокруг Плато Красного Облака, его очертания напоминают почитаемых кодо, бродящих по равнинам. Для странствующих сородичей это тихий природный маяк на продуваемых ветрами равнинах Мулгора."},{t="Духовное значение",b="Для Шу'хало природные образования часто имеют духовный вес. Дольмен Кодо особо почитаем молодыми шаманами-тауренами, вступающими на духовный путь. Новичков направляют сюда на ранние обряды посвящения: одинокий каменный монумент служит священным местом, где они общаются со стихиями и чтят природу, прежде чем отправиться в более опасные края континента."}},faq={{q="Где находится Дольмен Кодо?",a="Дольмен Кодо находится на Плато Красного Облака в Мулгоре. Его можно найти примерно на полпути по прямой между Лагерем Нараче и Ежевичной лощиной; на земле он отмечен небольшой прогалиной голой земли.",al={"kodo rock location","where is kodo rock","find kodo rock","где дольмен кодо","расположение дольмена кодо","найти дольмен кодо"}},{q="Почему Дольмен Кодо трудно найти?",a="Монумент естественно сливается с холмами и травами плато. Он хорошо виден лишь с небольшого расстояния, поэтому путникам нужно внимательно смотреть на местность и искать пятно земли под ним.",al={"cant find kodo rock","kodo rock hidden","не могу найти дольмен кодо","дольмен кодо скрыт"}},{q="Почему Дольмен Кодо важен для шаманов-таурен?",a="Шаманы-таурены приходят к камню во время первых испытаний за пределами Лагеря Нараче. Это мирный священный ориентир для новичков, учащихся настраивать свой дух на землю и стихии Мулгора.",al={"shaman quest kodo rock","why go to kodo rock","задание шамана дольмен кодо","зачем идти к дольмену кодо"}},{q="Какие опасности есть рядом с Дольменом Кодо?",a="Хотя сам участок вокруг Дольмена Кодо обычно спокоен, дальше на северо-восток путь ведет прямо к Ежевичной лощине — каньону, густо населенному воинственными свинобразами Дыбогривами.",al={"is kodo rock safe","enemies near kodo rock","безопасен ли дольмен кодо","враги у дольмена кодо"}}},fp="9,395,22.444.0,22.386.0,27.206.0,30.240.0,45.214.0,32.197.0"}
P.entries["subzone:kolkar-crag"] = {n="Утес Колкара",s="Утес Колкара — выжженное солнцем зазубренное ущелье на юге Дуротара, занятое враждебными кентаврами племени Колкар. Этот оплот под предводительством полководца Колканиса служит плацдармом для организованных набегов на соседние поселения Орды.",h="Утес Колкара — выжженное солнцем зазубренное ущелье на юге Дуротара, занятое враждебными кентаврами племени...",kw={"centaur","durotar","kolkanis","kolkar","kolkar crag","sen'jin village","valley of trials","warlord kolkanis","кентавр","дуротар","колканис","колкар","утес колкара","деревня сен'джин","долина испытаний","полководец колканис"},ang={["faction:Horde"]="Защита южного Дуротара от вторжений кентавров оберегает линии снабжения между Деревней Сен'джин и дорогой к Оргриммару.",["race:Orc"]="Присутствие кентавров так близко к Долине Испытаний угрожает посвящению молодых орков, поэтому усмирение Утеса Колкара — неотложная задача обороны территории."},sec={{t="Заноза в боку Дуротара",b="Утес Колкара, спрятанный в неприступных каньонах южного Дуротара, — опорная база воинственного племени Колкар. Несмотря на засушливую и суровую местность, кентавры укрепили естественные узкие проходы ущелья. Из этой лощины их разведчики и мародеры следят за окрестными равнинами, ища слабые места в землях орков и Черного Копья. Для молодых воинов, тренирующихся в Долине Испытаний или патрулирующих южное побережье, Утес Колкара — ближайший организованный очаг вражды кентавров."},{t="Планы вторжения",b="Кентавры, засевшие на утесе под командованием полководца Колканиса, вынашивают замыслы куда масштабнее мелких стычек. Захваченные планы нападения указывают на цели: Долину Испытаний, Деревню Сен'джин, Колючий Холм и дерзкие удары прямо к вратам Оргриммара. Чтобы остановить эти планы, нужны решительные упреждающие удары вглубь лощины, чтобы убить Колканиса и разбить их сбор, пока боевые отряды не прокатились по долинам."}},faq={{q="Кто живет на Утесе Колкара?",a="Утес Колкара занимает племя кентавров Колкар во главе с полководцем Колканисом. Они используют укрепленный каньон как лагерь и опорный пункт для набегов на форпосты Орды по всему Дуротару.",al={"who is at kolkar crag","kolkar crag inhabitants","who owns kolkar crag","кто на утесе колкара","обитатели утеса колкара","чей утес колкара"}},{q="Почему Орда обеспокоена этой лощиной?",a="Кентавры в ущелье составили планы организованных нападений на важные поселения Дуротара, включая тренировочные земли Долины Испытаний, Деревню Сен'джин, Колючий Холм и сам Оргриммар.",al={"why care about kolkar crag","is kolkar crag dangerous","kolkar threat","чем опасен утес колкара","опасен ли утес колкара","угроза колкаров"}},{q="Кто возглавляет здешних кентавров?",a="Лагерем командует полководец Колканис, свирепый предводитель кентавров, который направляет разведку и составляет боевые планы против орков и троллей.",al={"kolkar crag boss","who leads kolkar crag","warlord kolkanis","босс утеса колкара","кто возглавляет утес колкара","полководец колканис"}}},fp="11,219,25.544.0,19.461.1,25.181.0,45.217.0,27.170.0"}
P.entries["subzone:kormek-s-hut"] = {n="Хижина Кормека",s="Хижина Кормека — уединенное полуразвалившееся жилище посреди бесплодных равнин на севере центральной части Пустошей. Несмотря на унылую обстановку и загадочное название, сейчас в ней живет странная парочка: на удивление миролюбивый культист и гоблин, одержимый добычей костей кодо.",h="Хижина Кормека — уединенное полуразвалившееся жилище посреди бесплодных равнин на севере центральной части...",kw={"bibbly f'utzbuckle","desolace","kodo bones","kormek","kormek's hut","twilight's hammer","willow","биббли футцбакл","пустоши","кости кодо","кормек","хижина кормека","сумеречный молот","уиллоу"},sec={{t="Странный оазис чудаков",b="Эта маленькая лачуга стоит в засушливых пустошах на севере центральной части Пустошей и названа в честь личности, чье местонахождение и имя остаются совершенно неизвестными. Вместо Кормека путники, наткнувшиеся на хижину, встречают необычную пару, живущую в глуши: Уиллоу и Биббли Футцбакла. Внутри хижины сидит Уиллоу, член обычно враждебного и нигилистичного Сумеречного Молота, который, как ни странно, радушно и спокойно относится к чужакам. Снаружи загон, усеянный выбеленными солнцем костями кодо, служит личной танцплощадкой и рабочей площадкой Биббли, непоседливого гоблина, увлеченного коммерческими возможностями сбора костей."}},faq={{q="Кто такой Кормек?",a="Никто не знает. Хижина носит имя Кормека, но ни гоблин снаружи, ни культист внутри не объясняют, кем был Кормек, а сам тезка нигде в пустошах не встречается.",al={"who is kormek","kormek identity","where is kormek","кто такой кормек","личность кормека","где кормек"}},{q="Почему здесь живет дружелюбный культист Сумеречного Молота?",a="Уиллоу живет в хижине и принадлежит к Сумеречному Молоту — культу, обычно враждебному ко всему смертному. По собственным причинам она не проявляет агрессии к путникам, заглянувшим в это уединенное убежище.",al={"willow twilights hammer","why is willow friendly","willow hut","уиллоу сумеречный молот","почему уиллоу дружелюбна","хижина уиллоу"}},{q="Чем занят гоблин снаружи?",a="Биббли Футцбакл целыми днями восторженно пляшет вокруг загона, полного костей кодо. Как и многие предприимчивые гоблины, он в восторге от перспективы превратить древние останки пустыни в чистую прибыль.",al={"bibbly futzbuckle","goblin dancing desolace","why is the goblin dancing","биббли футцбакл","гоблин танцует пустоши","почему гоблин танцует"}},{q="Где находится Хижина Кормека?",a="Хижина расположена на севере центральной части Пустошей, на сухих продуваемых ветрами равнинах к северу от центрального перекрестка и кладбища.",al={"kormek hut location","where is kormek hut","kormek desolace","хижина кормека расположение","где хижина кормека","кормек пустоши"}}},fp="12,278,27.652.0,14.176.0,55.212.0,33.211.0,30.130.0"}
P.entries["subzone:kurzen-s-compound"] = {n="Лагерь Курцена",s="Лагерь Курцена — сильно укрепленное поселение людей в холмах на севере Тернистой долины. Основанный экспедицией, посланной из Штормграда под командованием полковника Курцена, этот форпост превратился в разбойничий лагерь головорезов и диких зверей после того, как их командир впал в безумие.",h="Лагерь Курцена — сильно укрепленное поселение людей в холмах на севере Тернистой долины.",kw={"colonel","compound","kurzen","rebel","stockpile","stranglethorn","полковник","лагерь","курцен","повстанцы","склад","тернистая долина"},ang={["class:Hunter"]="В лагере видны грубые и жестокие попытки приручить диких тернистых пантер и тигров, превратив их в боевых зверей передовой.",["faction:Alliance"]="Экспедиция Курцена была отправлена под знаменем Альянса, поэтому падение форпоста в безумие стало постыдным скандалом, который соседние повстанцы отчаянно стремятся исправить."},sec={{t="Сердце тьмы",b="То, что начиналось как официальная экспедиция в дикие джунгли Тернистой долины, обернулось кошмаром, когда полковник Курцен лишился рассудка. Вместо выполнения задачи Штормграда гарнизон откололся от власти королевства, порвал связи с короной и скатился в тиранию. Сегодня лагерь действует как оплот наемников: здесь есть работающая лесопилка, стойла, где пойманных тернистых пантер и тигров обучают как боевых животных, и обширный пещерный комплекс под названием Склад, где отступники прячут награбленные припасы."},{t="Расколотый полк",b="Не все первоначальные члены экспедиции последовали за командиром в жестокость. Когда безумие Курцена усилилось, часть его людей подняла мятеж и бежала на запад, основав Лагерь Повстанцев, что положило начало жестокой и кровавой вражде в густых джунглях. Из своего укрепленного лагеря Курцен и его верные люди безжалостно выслеживают дезертиров и считают врагом экспедиции любого чужака, ступившего в их джунглевые владения."}},faq={{q="Кто живет в Лагере Курцена?",a="Поселение занимают отколовшиеся остатки экспедиции Курцена. Эти солдаты, бойцы джунглей и наемники подчиняются полковнику Курцену и его лейтенантам, а не законам Штормграда.",al={"who is here","kurzen soldiers","who lives in the compound","кто здесь","солдаты курцена","кто живет в лагере"}},{q="Почему здешние люди враждебны?",a="Полковник Курцен впал в безумие в глубине джунглей и отказался от верности Альянсу. Теперь он и его люди считают смертельной угрозой всех нарушителей, включая силы Альянса и дезертиров из соседнего Лагеря Повстанцев.",al={"why do they attack","kurzen hostile","are kurzen friendly","почему они нападают","курцен враждебны","дружелюбны ли люди курцена"}},{q="Что за пещера в глубине лагеря?",a="Пещерная система позади лагеря известна как Склад. Люди Курцена используют ее как укрепленный склад снабжения для хранения оружия, провизии и контрабанды вдали от джунглевых мародеров и набегов повстанцев.",al={"cave in kurzen compound","the stockpile","kurzen cave","пещера в лагере курцена","склад","пещера курцена"}},{q="Почему здесь есть тигры и пантеры в клетках?",a="Бойцы ловят местных тернистых тигров и пантер и держат их у стойл. Из этих хищников они выращивают свирепых боевых пантер и боевых тигров Курцена, которые защищают лагерь и патрулируют окрестные джунгли.",al={"kurzen animals","caged panthers","war tigers","звери курцена","пантеры в клетках","боевые тигры"}}},fp="17,311,17.583.0,18.424.0,31.204.0,32.243.0,41.200.0,45.226.0"}
P.entries["subzone:lake-al-ameth"] = {n="Озеро Аль'Амет",s="Озеро Аль'Амет — одно из крупнейших пресных водоемов, расположенных высоко в ветвях Тельдрассила, к югу от Доланаара. Некогда это было тихое убежище с одним лишь простым деревянным причалом, но теперь его берега стали опасными из-за яростного возбуждения местных растений.",h="Озеро Аль'Амет — одно из крупнейших пресных водоемов, расположенных высоко в ветвях Тельдрассила, к югу от...",kw={"dolanaar","kaldorei","lake al'ameth","oakenscowl","teldrassil","timberling","timberling seeds","доланаар","кальдораи","озеро аль'амет","дубохмур","тельдрассил","древолюд","семена древолюда"},ang={["class:Druid"]="Дикие древолюды вокруг озера дают друидам возможность на практике изучить неестественную порчу, разрушающую флору и фауну Тельдрассила.",["race:NightElf"]="Для кальдораев Доланаара Озеро Аль'Амет — тревожный признак недугов, поражающих их недавно взращенный дом, и молодым защитникам приходится охранять окрестную дорогу."},sec={{t="Неспокойный берег",b="Озеро Аль'Амет лежит сразу к югу от деревни Доланаар и служит важным природным бассейном в сердце Тельдрассила. Несмотря на безмятежные воды и малочисленные постройки, покоя здесь больше нет. Стаи разъяренных древолюдов и их отростков бродят у кромки воды, обезумев от неестественной болезни, распространяющейся по мировому древу. Друиды и исследователи из Доланаара часто отправляют путников на эти берега собирать семена и истреблять агрессивных существ, пока порча не проникла глубже в окружающий лес."},{t="Корни гнева",b="Враждебность вокруг Озера Аль'Амет напрямую связана с утратой равновесия лесными духами. В ближайших рощах таятся огромные, оскверненные древни, как Дубохмур, а обычные древолюды набрасываются на всякого, кто приблизится. Для Круга Кенария диагностика и лечение гнили вокруг Озера Аль'Амет — срочная проверка того, сможет ли Тельдрассил, лишенный благословения, действительно устоять."}},faq={{q="Где находится Озеро Аль'Амет?",a="Озеро Аль'Амет лежит прямо к югу от поселения ночных эльфов Доланаар в восточной части Тельдрассила.",al={"lake alameth location","where is lake al'ameth","find lake al'ameth","озеро аль'амет расположение","где озеро аль'амет","найти озеро аль'амет"}},{q="Почему существа вокруг Озера Аль'Амет враждебны?",a="Древесные существа и растения на берегах стали жертвами порчи, поражающей Тельдрассил, и ранее безобидные лесные спригганы и древни впали в территориальную ярость.",al={"why timberlings angry","lake alameth enemies","aggressive timberlings","почему древолюды злые","враги озера аль'амет","агрессивные древолюды"}},{q="Какие постройки и ориентиры есть на озере?",a="Озеро в основном дикое и необжитое: на его северном берегу возле тропы из Доланаара есть лишь простой деревянный рыбацкий причал.",al={"lake alameth pier","dock at lake alameth","озеро аль'амет причал","пристань озеро аль'амет"}},{q="Кто такой Дубохмур?",a="Дубохмур — могучий оскверненный древень, затаившийся возле рощ Озера Аль'Амет. Он воплощает яростную гниль, искажающую лесных существ в этих местах.",al={"what is oakenscowl","oakenscowl lake al'ameth","что такое дубохмур","дубохмур озеро аль'амет"}}},fp="13,291,20.551.0,18.386.0,31.96.0,51.198.0,45.136.0,18.173.0"}
P.entries["subzone:lake-elune-ara"] = {n="Озеро Элуне'ара",s="Озеро Элуне'ара — мерцающий священный водоем в сердце Лунной поляны. Озеро, чтящее Богиню Луны Элуну, служит для Круга Кенария местом духовных размышлений, но на его темном дне покоится спящий оскверненный полубог Омен.",h="Озеро Элуне'ара — мерцающий священный водоем в сердце Лунной поляны.",kw={"cenarion circle","dark waters","elune","lake elune'ara","moonglade","nighthaven","omen","круг кенария","темные воды","элуна","озеро элуне'ара","лунная поляна","ночная гавань","омен"},ang={["class:Druid"]="Озеро — важное место друидских ритуалов и испытаний; в его глубоких водах хранятся священные реликвии, помогающие посвященным на их пути.",["race:NightElf"]="Названное в честь Элуны, озеро представляет собой место божественного покоя и историческую память о Войне Древних."},sec={{t="Сердце священной долины",b="Озеро Элуне'ара, окруженное залитыми лунным светом рощами Лунной поляны, обладает безмятежными водами, которые, как говорят, благословила сама Белая Госпожа. Озеро находится в духовном центре друидского убежища, к северу от него лежит Ночная Гавань, а рядом — святилища Круга Кенария. Посвященные издавна погружаются в его спокойные глубины за давно потерянными реликвиями, настраиваясь на течения природы в поисках гармонии с землей."},{t="Сон Омена",b="Несмотря на спокойствие на поверхности, под мягкой рябью таится древняя опасность. Вековые легенды повествуют о двуглавом волке-полубоге Омене, почитаемом древне, оскверненном Пылающим Легионом во время Войны Древних. Побежденный и низвергнутый в озерное дно давным-давно, Омен спит глубоко под темными водами как неизменное напоминание о ранах природы."}},faq={{q="Что такое Озеро Элуне'ара?",a="Это большое священное озеро в центре Лунной поляны. Ночные эльфы и друиды чтят его; оно названо в честь Богини Луны Элуны и окружено святилищами Круга Кенария.",al={"lake eluneara","moonglade lake","where is lake eluneara","озеро элуне'ара","озеро лунной поляны","где озеро элуне'ара"}},{q="Что скрывается на дне озера?",a="В темных глубинах озера спит павший полубог Омен. Некогда благородный древень, он был сведен с ума Пылающим Легионом во время древней войны и низвергнут в озеро после поражения.",al={"what is inside lake elune'ara","omen in moonglade","monster in lake","что в озере элуне'ара","омен в лунной поляне","чудовище в озере"}},{q="Почему друиды приходят к этому озеру?",a="Озеро тесно связано с друидскими испытаниями и общением с духами природы. Молодые друиды часто ныряют в его воды в поисках священных реликвий в рамках обрядов посвящения.",al={"druid quest lake","aquatic form lake","задание друида озеро","водная форма озеро"}}},fp="14,278,24.429.0,19.359.0,23.198.0,37.187.0,32.192.0"}
P.entries["subzone:lake-falathim"] = {n="Озеро Фалатим",s="Озеро Фалатим — тихое озеро среди лесистых холмов западной части Ясеневого леса, к юго-западу от Заставы Мейстры. Его воды день и ночь постоянно освещены лунным светом Элуны, и когда-то оно было любимым местом отдыха ночных эльфов. Однако в последнее время агрессивные мурлоки заполонили его берега, превратив священное убежище в опасное место.",h="Озеро Фалатим — тихое озеро среди лесистых холмов западной части Ясеневого леса, к юго-западу от Заставы...",kw={"ashenvale","elune","falathim","lake falathim","maestra's post","moonlight","murloc","teronis","ясеневый лес","элуна","фалатим","озеро фалатим","застава мейстры","лунный свет","мурлок","теронис"},ang={["faction:Alliance"]="Разведчики Альянса из Заставы Мейстры внимательно следят за Озером Фалатим, опасаясь набегов мурлоков и пытаясь узнать о пропавших учених вроде Терониса.",["race:NightElf"]="Для кальдораев Озеро Фалатим — напоминание о священной природе, находящейся под угрозой: идиллическое озеро, постоянно освещенное лунным светом Элуны, оскверняют дикие племена мурлоков."},sec={{t="Омытое лунным светом",b="Озеро Фалатим, скрытое к юго-востоку от Зорамского взморья, издавна ценилось кальдорай как мирное место для купания и рыбалки. По местным преданиям, мягкое сияние Элуны покоится на этих водах в любое время суток. Несмотря на это священное благословение, свирепые мурлоки хлынули вглубь суши и захватили берега: они гнездятся там во множестве и прогоняют как местных путников, так и ученых."},{t="Исчезновение ученого",b="Внезапное вторжение мурлоков сделало озеро смертельно опасным для одиноких странников. Ученый-ночной эльф Теронис недавно пропал где-то у кромки воды, отправившись туда с целью исследования. Учитывая дикую враждебность земноводных, затаившихся на берегах и на мелководье, Часовые опасаются худшего для всякого, кто в одиночку отправится к освещенному луной водоему."}},faq={{q="Где находится Озеро Фалатим?",a="Озеро Фалатим лежит в западной части Ясеневого леса, среди холмов к юго-западу от Заставы Мейстры и к юго-востоку от Зорамского взморья.",al={"lake falathim location","where is lake falathim","find lake falathim","озеро фалатим где находится","где озеро фалатим","найти озеро фалатим"}},{q="Чем Озеро Фалатим особенно для ночных эльфов?",a="Озеро имеет духовное значение, потому что лунный свет богини Элуны, как считается, вечно касается его вод — днем и ночью. Исторически ночные эльфы приходили на его тихие берега, чтобы ловить рыбу и купаться.",al={"why is lake falathim important","lake falathim lore","moonlight lake ashenvale","чем важно озеро фалатим","предания озера фалатим","лунное озеро ясеневый лес"}},{q="Какие существа обитают в озере?",a="Озеро заполонили враждебные мурлоки, пришедшие из ближних прибрежных областей, из-за чего берег опасен для путников.",al={"lake falathim mobs","what is at lake falathim","lake falathim monsters","озеро фалатим монстры","кто на озере фалатим","существа озера фалатим"}},{q="Кем был Теронис?",a="Теронис — ученый-ночной эльф, отправившийся к Озеру Фалатим и пропавший; его исчезновение приписывают свирепым мурлокам, обитающим в этой местности.",al={"teronis lake falathim","who is teronis","missing scholar lake falathim","теронис озеро фалатим","кто такой теронис","пропавший ученый озеро фалатим"}}},fp="13,369,19.413.0,27.352.0,31.125.0,48.215.0,32.146.0,16.163.0"}
P.entries["subzone:lake-kel-theril"] = {n="Озеро Кел'Терил",s="Озеро Кел'Терил — обширное замерзшее озеро в самом сердце Зимних Ключей. На его скованных льдом берегах стоят древние руины кальдорай, населенные неупокоенными духами, оставшимися там со времен Великого Раскола.",h="Озеро Кел'Терил — обширное замерзшее озеро в самом сердце Зимних Ключей.",kw={"highborne","kel'theril","lake kel'theril","ruins of kel'theril","specters","winterspring","высокорожденные","кел'терил","озеро кел'терил","руины кел'терила","привидения","зимние ключи"},ang={["race:NightElf"]="Трагические привидения, бродящие у Озера Кел'Терил, служат жутким напоминанием о разрушении, вызванном безрассудной надменностью древних высокорожденных."},sec={{t="Ледяная гробница высокорожденных",b="Озеро Кел'Терил окутано вечным холодом, его воды скрыты под толстым слоем льда. На его поверхности и заснеженных берегах разбросаны разбитые колонны и арки древней эльфийской архитектуры. Это остатки Кел'Терила, когда-то форпоста древней цивилизации высокорожденных, до того как Великий Раскол разрушил Калимдор. Вместо упокоения в смерти духи павшей аристократии блуждают по льду как измученные призраки и привидения, навеки привязанные к печальным останкам своего былого величия."}},faq={{q="Почему озеро населено призраками ночных эльфов?",a="Духи, блуждающие у Озера Кел'Терил, — измученные призраки древних высокорожденных. Когда десять тысяч лет назад Великий Раскол разорвал Калимдор, катастрофический крах их цивилизации оставил их души привязанными к ледяным руинам прежнего поселения.",al={"lake keltheril ghosts","why are there spirits here","winterspring lake ghosts","призраки озера кел'терил","почему здесь духи","призраки озера зимние ключи"}},{q="Какие руины стоят на берегах озера?",a="Рушащиеся колонны и каменная кладка принадлежат Руинам Кел'Терила — древнему поселению кальдорай, процветавшему во времена владычества высокорожденных, до Войны Древних.",al={"ruins in the lake","what are the keltheril ruins","руины в озере","что за руины кел'терила"}}},fp="15,206,30.526.0,39.269.0,41.182.0"}
P.entries["subzone:lake-mennar"] = {n="Озеро Меннар",s="Озеро Меннар — тихое пресное озеро среди разрушенных руин Азшары. Оно известно как одно из крайне редких мест за пределами Нордскола, где обитают представители синего драконьего рода. Хотя по краям озера множество охраняющих синих дракончиков, сами его берега на удивление спокойны.",h="Озеро Меннар — тихое пресное озеро среди разрушенных руин Азшары.",kw={"azshara","azuregos","blue dragonflight","dragonspawn","lake mennar","mazthoril","whelps","азшара","азурегос","синий драконий род","дракончики","озеро меннар","маззорил"},ang={["class:Mage"]="Как хранители тайных энергий мира, синие драконы, охраняющие Озеро Меннар, делают эту котловину местом большого интереса и осторожности для практиков тайной магии."},sec={{t="Убежище синего драконьего рода",b="Озеро Меннар расположено среди древних разрушенных земель Азшары и служит уединенным местом сбора синего драконьего рода. Если не считать Маззорила на севере в Зимних Ключах, встретить синих драконов в таком числе в Калимдоре почти невозможно. Синие дракониды неустанно патрулируют хребты и подступы вокруг котловины, яростно охраняя воды. Но для любого странника, достаточно смелого, чтобы проскользнуть через это бдительное кольцо стражей, спокойные воды озера дарят неожиданную тишину, защищенную от волшебных потрясений и бродячих стай зверей, обычных для остальной части полуострова."}},faq={{q="Почему у Озера Меннар есть синие драконы?",a="Озеро Меннар имеет особое тихое значение для синего драконьего рода и является одним из немногих мест его сбора в Калимдоре, не считая Маззорила в Зимних Ключах. Дракончики бдительно патрулируют окрестности, охраняя котловину и не подпуская чужаков к своему потомству.",al={"why blue dragons here","who lives at lake mennar","blue dragonflight lake mennar","почему здесь синие драконы","кто живет у озера меннар","синий драконий род озеро меннар"}},{q="Опасно ли посещать Озеро Меннар?",a="Окрестные гребни и подходы усиленно патрулируют агрессивные синие драконы и дракончики. Однако вода и ближайший берег внутри котловины на удивление спокойны, если вам удастся проскользнуть мимо внешнего кольца стражей.",al={"is lake mennar safe","enemies at lake mennar","безопасно ли озеро меннар","враги у озера меннар"}},{q="Как Озеро Меннар связано с другими гнездовьями синих драконов?",a="На континенте Калимдор Озеро Меннар и Маззорил в Зимних Ключах — основные известные территории, за которыми присматривает синий драконий род. Оба места — редкие форпосты далеко к югу от исконной родины их рода в Нордсколе.",al={"connection to mazthoril","lake mennar winterspring","связь с маззорилом","озеро меннар зимние ключи"}}},fp="11,338,37.610.0,42.284.0,34.239.0,57.234.0"}
P.entries["subzone:lake-mereldar"] = {n="Озеро Мерельдар",s="Озеро Мерельдар — обширный зараженный водоем к югу от Перекрестка Корина в Восточных Чумных землях. Когда-то часть идиллической сельской глубинки Лордерона, его оскверненные воды теперь порождают искаженных элементалей и гниют под не рассеявшейся порчей Плети.",h="Озеро Мерельдар — обширный зараженный водоем к югу от Перекрестка Корина в Восточных Чумных землях.",kw={"blighted surge","corin's crossing","eastern plaguelands","elementals","ferry","lake mereldar","plague ravager","оскверненный прилив","перекресток корина","восточные чумные земли","элементали","паром","озеро мерельдар","чумной опустошитель"},ang={["class:Shaman"]="Существование оскверненных приливов в Озере Мерельдар — мрачное свидетельство того, как гнусная магия Плети искажает даже природных духов стихий, превращая их в безумных свирепых чудовищ."},sec={{t="Отравленное убежище",b="Озеро Мерельдар, лежащее к югу от городка Перекресток Корина, когда-то было мирной частью сельской местности северного Лордерона. По его берегам разбросаны разлагающиеся руины старой усадьбы, заброшенная лачуга и ветхий паром, возивший местных фермеров и путников по спокойным водам. С приходом Плети и чумы нежизни озеро полностью погибло. Окрестная почва засохла, а воды стали гнилыми и ядовитыми."},{t="Искаженные обитатели",b="Неестественная порча, просочившаяся в Озеро Мерельдар, полностью заразила местную экосистему и связанных с ней духов. Оскверненные приливы — испорченные водные элементали, сведенные с ума остатками некромантии, — таятся на мелководье и внезапно всплывают. На заросших водорослями берегах по грязи бродят свирепые звери, такие как чумные опустошители, охотящиеся на любых живых существ, подошедших слишком близко к мертвому берегу."}},faq={{q="Где находится Озеро Мерельдар?",a="Озеро Мерельдар лежит в центрально-южной части Восточных Чумных земель, прямо к югу от разрушенного городка Перекресток Корина.",al={"mereldar location","where is lake mereldar","find lake mereldar","озеро мерельдар где находится","где озеро мерельдар","найти озеро мерельдар"}},{q="Почему в озере есть водные элементали?",a="Здешние водные элементали, известные как оскверненные приливы, были искажены и стали враждебными из-за всепроникающей некромантической порчи, просочившейся в озеро во время падения Лордерона.",al={"blighted surge","water elementals mereldar","corrupted elementals","оскверненный прилив","водные элементали мерельдар","оскверненные элементали"}},{q="Кому принадлежали лачуга и паром на берегу?",a="Они принадлежали местной фермерской усадьбе, основанной до Третьей войны. Когда чума опустошила Восточный Предел, обитатели усадьбы погибли или бежали, оставив дом и паром гнить.",al={"ferry ruins","mereldar house","abandoned dock","руины парома","дом мерельдар","заброшенная пристань"}},{q="Безопасно ли пить воду или плавать в ней?",a="Нет. Озеро сильно загрязнено чумой нежизни, поэтому пить воду, плавать или собирать в ней ресурсы опасно, а в ее водах обитают агрессивные зараженные существа.",al={"can you drink the water","is lake mereldar poisoned","можно ли пить воду","отравлено ли озеро мерельдар"}}},fp="13,275,16.486.0,19.409.0,31.133.0,43.181.0,43.188.0,38.166.0"}
P.entries["subzone:lake-nazferiti"] = {n="Озеро Назферити",s="Озеро Назферити — обширное пресное озеро в густых джунглях северной части Тернистой долины. Его питает большая речная система, тянущаяся далеко на север в горы; в его водах кишат свирепые кроколиски и хищные бешеные рыбы, а на берегах расположен промышленный лагерь гоблинов Торговой Компании.",h="Озеро Назферити — обширное пресное озеро в густых джунглях северной части Тернистой долины.",kw={"crocolisks","frenzies","lake nazferiti","nazferiti","river","stranglethorn vale","venture company","кроколиски","бешеные рыбы","озеро назферити","назферити","река","тернистая долина","торговая компания"},ang={["class:Hunter"]="Берега и глубины Озера Назферити богаты дичью — от агрессивных речных зверей до опасных кроколисков, затаившихся в камышах.",["race:NightElf"]="Промышленные шрамы, оставленные Торговой Компанией у Озера Назферити, показывают, какое чудовищное разорение природе приносит безудержная гоблинская алчность."},sec={{t="Сердце водного пути джунглей",b="Озеро Назферити лежит на реке Назферити — одной из самых длинных непрерывных водных артерий юга Восточных королевств. Река берет начало глубоко в северных высотах, низвергаясь водопадами с Красногорья, и, возможно, начинается еще дальше вглубь суши, у Перевала Мертвого Ветра. В Тернистой долине вода разливается в мутное озеро, где кишат свирепые хищники — речные бешеные рыбы и кроколиски, охотящиеся из засады, — из-за которых даже простое купание смертельно опасно."},{t="Вторжение Торговой Компании",b="Природному равновесию Озера Назферити угрожают гоблины Торговой Компании. Развернув масштабные работы на берегах озера, эти безжалостные барыги истощают лес и ресурсы джунглей с помощью механических пил, буров и бригад лесорубов. Их обширная база загрязняет воды и постоянно сталкивается с местной фауной и бродячими охотниками, отважившимися зайти в долину."}},faq={{q="Откуда Озеро Назферити берет воду?",a="Озеро питает река Назферити — обширная речная сеть, берущая начало высоко в северных горах. Ее подтвержденный исток — водопад, низвергающийся с Красногорья, а неподтвержденные верховья простираются вглубь суши до скал Перевала Мертвого Ветра.",al={"nazferiti river source","where does lake nazferiti come from","water source lake nazferiti","исток реки назферити","откуда берется озеро назферити","источник воды озера назферити"}},{q="Кто контролирует берега Озера Назферити?",a="Торговая Компания, которой управляют гоблины, занимает крупную базу на границах озера. Опираясь на нее, она вырубает окрестные джунгли и добывает ресурсы, размещая вооруженных надсмотрщиков и гоблинские механизмы у кромки воды.",al={"who is at lake nazferiti","goblins at lake nazferiti","venture co lake","кто на озере назферити","гоблины на озере назферити","торговая компания озеро"}},{q="Безопасно ли плавать в Озере Назферити?",a="Плавать в озере опасно. В мутных водах обитают стаи агрессивных речных бешеных рыб и притаившиеся кроколиски, которые быстро нападают на каждого, кто отходит от мелководья.",al={"lake nazferiti monsters","what lives in lake nazferiti","creatures in lake nazferiti","монстры озера назферити","кто живет в озере назферити","существа озера назферити"}},{q="Где находится Озеро Назферити?",a="Озеро Назферити расположено в северной части Тернистой долины, к югу от границы с Сумеречным лесом и к западу от руин Зул'Гуруба, вдоль главной речной магистрали.",al={"lake nazferiti location","where is lake nazferiti","find lake nazferiti","озеро назферити где находится","где озеро назферити","найти озеро назферити"}}},fp="14,333,28.480.0,28.393.0,40.270.0,42.234.0,37.178.0,32.159.0"}
P.entries["subzone:lakeridge-highway"] = {n="Озерный тракт",s="Озерный тракт — старая дорога, проходящая вдоль южного берега Озера Безмолвия в Красногорье. До Первой войны это была важная и оживленная артерия, но теперь она пришла в упадок и заброшена. Сегодня бродячие стаи гноллов и орки клана Черной горы делают путь по дороге опасным для путников.",h="Озерный тракт — старая дорога, проходящая вдоль южного берега Озера Безмолвия в Красногорье.",kw={"gnolls","highway","lake everstill","lakeridge","redridge","road","stonewatch","гноллы","тракт","озеро безмолвия","озерный тракт","красногорье","дорога","каменная стража"},ang={["faction:Alliance"]="Тракт — наглядное напоминание о заброшенных рубежах Штормграда: местные дороги сразу за Приозерьем из-за нехватки подкреплений отданы гноллам и оркам."},sec={{t="Павшая артерия",b="До разорения Первой войны Озерный тракт был оживленным торговым путем через Красногорье, по которому перевозили товары и путешествовали люди вдоль южных берегов Озера Безмолвия. В те мирные дни путники могли ходить между поселениями в долине и восточными возвышенностями под защитой Королевства Штормград. Эта безопасность исчезла, когда через область прошла Орда, оставив восточное Красногорье спорным и опустошенным."},{t="Опасность на дороге",b="После захвата Крепости Каменной Стражи орками клана Черной горы обслуживание и патрули вдоль тракта прекратились полностью. Дорога быстро превратилась в заросшую тропу, за которую борются свирепые стаи гноллов. Поскольку войска Штормграда разбросаны и не могут усилить Приозерье, тракт официально остается небезопасным. Любому путнику, желающему добраться до восточных хребтов, теперь приходится прорубать путь через засады гноллов."}},faq={{q="Куда ведет Озерный тракт?",a="Дорога тянется вдоль южного края Озера Безмолвия и идет на восток от окрестностей Приозерья к предгорьям вокруг Крепости Каменной Стражи и восточным горам Красногорья.",al={"where does lakeridge highway go","lakeridge highway path","where is lakeridge highway","куда ведет озерный тракт","путь озерного тракта","где находится озерный тракт"}},{q="Почему тракт заброшен?",a="Тракт пришел в упадок после Первой войны, особенно когда орки клана Черной горы укрепили Крепость Каменной Стражи. Без людей для охраны дороги Штормград не мог ее содержать, и враждебные гноллы заняли ее и перекрыли путь мирным жителям.",al={"why is it abandoned","why is lakeridge highway empty","lakeridge highway fallen into disuse","почему он заброшен","почему озерный тракт пуст","озерный тракт в запустении"}},{q="Какие угрозы бродят по дороге сегодня?",a="Тракт населяют в основном агрессивные гноллы, нападающие из засады на всех, кто отходит от Приозерья, а также оставшиеся разведчики орков клана Черной горы из восточных оплотов.",al={"dangers on lakeridge highway","mobs on lakeridge highway","who controls lakeridge highway","опасности на озерном тракте","монстры на озерном тракте","кто контролирует озерный тракт"}},{q="Был ли тракт опасным всегда?",a="Нет. В мирную эпоху до Первой войны Озерный тракт был хорошо содержимым, оживленным путем, который безопасно связывал сердце Красногорья с его восточными форпостами.",al={"lakeridge highway history","highway before the war","история озерного тракта","тракт до войны"}}},fp="17,320,15.451.0,17.420.0,38.189.0,29.249.0,35.187.0,33.181.0"}
P.entries["subzone:lakeshire"] = {n="Приозерье",s="Приозерье — главное человеческое поселение в Красногорье, расположенное на северных берегах Озера Безмолвия. Живописный городок, которым управляет Мировой судья Соломон и который охраняет маршал Маррис, сейчас на грани гибели из-за непрерывных нападений орков клана Черной горы, агрессивных стай гноллов и прибрежных мурлоков.",h="Приозерье — главное человеческое поселение в Красногорье, расположенное на северных берегах Озера Безмолвия.",kw={"blackrock orcs","everstill bridge","lake everstill","lakeshire","magistrate solomon","marshal marris","redridge","stonewatch","орки черной горы","мост безмолвия","озеро безмолвия","приозерье","мировой судья соломон","маршал маррис","красногорье","каменная стража"},ang={["faction:Alliance"]="Приозерье — восточный оплот Штормграда; если город падет перед кланом Черной горы, центральные земли Элвинна напрямую столкнутся с набегами орков.",["race:Human"]="Приозерье, отстроенное Альянсом Лордерона после разорения Второй войны, олицетворяет упорную стойкость беженцев из Штормграда, не желающих второй раз покидать родину."},sec={{t="Город в осаде",b="Когда-то мирное убежище в предгорьях к востоку от Штормграда, Приозерье стало самым осажденным рубежом королевства. Гарнизон города в Крепости Каменной Стражи был жестоко разгромлен орками клана Черной горы, хлынувшими с севера, а темное колдовство подняло стаи гноллов Темношкуров на организованные набеги. Диверсанты Черной горы даже разрушили часть Моста Безмолвия, и Штейгер Ослоу с рабочими пытаются починить пролет под постоянной угрозой нападения. Мурлоки заполонили берега озера, а гноллы рыщут на горных перевалах, и защитники Приозерья измотаны до предела."},{t="Покинутые короной",b="Несмотря на неоднократные отчаянные мольбы Мирового судьи Соломона, посланные через горы, Штормград практически не оказал военной поддержки. Ресурсы королевства истощены внутренними раздорами, а королевские советники считают бедствие Красногорья преувеличенными пограничными стычками. Отряд дворфов, посланный из Стальгорна, попал в засаду и исчез в Пылающих степях, и маршалу Маррису с горсткой оставшихся стражников приходится держать баррикады в одиночку. Теперь Приозерье держится лишь на мужестве странствующих наемников и свободных искателей приключений, нанятых прямо в ратуше."}},faq={{q="Кто управляет Приозерьем?",a="Гражданская власть принадлежит Мировому судье Соломону, который руководит городской администрацией из ратуши. Оборона и охрана порядка находятся в ведении маршала Марриса и потрепанных остатков городской стражи.",al={"lakeshire leader","who is in charge of lakeshire","magistrate of lakeshire","глава приозерья","кто главный в приозерье","судья приозерья"}},{q="Почему Штормград не посылает солдат на помощь Приозерью?",a="Силы Штормграда растянуты из-за беспорядков в регионе, а королевские советники, в частности леди Катрана Престор, активно убеждали верховного лорда Болвара Фордрагона не отправлять регулярные войска в Красногорье, из-за чего короне приходится полагаться на нанятых искателей приключений.",al={"why no stormwind reinforcements","stormwind army lakeshire","why is lakeshire abandoned","почему нет подкреплений штормграда","армия штормграда приозерье","почему приозерье брошено"}},{q="Что случилось с Мостом Безмолвия?",a="Орки клана Черной горы повредили огромный каменный мост во время набегов через озеро, сильно нарушив торговлю и перевозки. Штейгер Ослоу руководит ремонтом, но нехватка инструментов и постоянные нападения замедляют работу.",al={"broken bridge redridge","who broke everstill bridge","foreman oslow bridge","сломанный мост красногорье","кто сломал мост безмолвия","штейгер ослоу мост"}},{q="Какие угрозы сейчас окружают город?",a="Город осажден с трех сторон: орки клана Черной горы занимают Крепость Каменной Стражи на востоке, гноллы Темношкуры под началом колдуна-отступника Морганта действуют в северных холмах, а агрессивные мурлоки наводнили воды и берега Озера Безмолвия.",al={"who is attacking lakeshire","redridge threats","lakeshire enemies","кто атакует приозерье","угрозы красногорья","враги приозерья"}}},fp="9,330,18.631.0,22.599.1,22.196.0,52.283.1,38.230.0,41.243.0"}
P.entries["subzone:lakeshire-inn"] = {n="Таверна Приозерья",s="Таверна Приозерья — центр общения и главное убежище в осажденном городе Приозерье. Расположенная в сердце Красногорья, она дарит тепло, эль и безопасный ночлег местным жителям и усталым путникам, сталкивающимся с окрестными опасностями.",h="Таверна Приозерья — центр общения и главное убежище в осажденном городе Приозерье.",kw={"barkeep daniels","darcy parker","innkeeper brianna","lake everstill","lakeshire inn","redridge inn","wiley the black","yorus barleybrew","кабатчик дэниэлс","дарси паркер","трактирщица брианна","озеро безмолвия","таверна приозерья","таверна красногорья","вилли черный","йорус ячменовар"},ang={["faction:Alliance"]="Таверна Приозерья — незаменимый оплот гостеприимства Альянса, место сбора для всех, кто сражается за защиту уязвимого восточного фланга Штормграда.",["profession:Cooking"]="Общий зал — оживленное место, где в горах можно купить основные продукты, местные рецепты и свежие напитки у Кабатчика Дэниэлса."},sec={{t="Островок тепла",b="Стоя на берегу Озера Безмолвия, Таверна Приозерья дарит краткую передышку от банд гноллов и орков клана Черной горы, теснящих город. Несмотря на все более отчаянное военное положение Приозерья, в таверне сохраняется уютная и оживленная атмосфера. Кабатчик Дэниэлс и трактирщица Брианна обслуживают местных и путников, подавая кружки эля, вино и горячие блюда. Это важное место встреч, где горожане обмениваются новостями, топят горе и ищут наемников для защиты восточной границы королевства."},{t="Посетители и слухи",b="Помимо обычных посетителей, потягивающих напитки у стойки, в таверну заходят самые разные колоритные личности. Вилли Черный наблюдает за залом из-за стола, храня свои мысли при себе и следя за опасностями в регионе. Странствующие пивовары вроде Йоруса Ячменовара останавливаются здесь, а Дарси Паркер и другие горожане часто бывают в общем зале. Для искателей приключений, отправляющихся в зубчатые горы или на юг, в Сумеречный лес, таверна — последний оплот цивилизации и безопасности перед спорными дикими землями."}},faq={{q="Какие услуги предоставляет Таверна Приозерья?",a="Таверна служит главным местом отдыха в Красногорье. Трактирщица Брианна привязывает камни возвращения и сдает комнаты усталым путникам, а Кабатчик Дэниэлс предлагает закуски, еду и напитки в дорогу.",al={"lakeshire inn services","what can I do at lakeshire inn","innkeeper lakeshire","услуги таверны приозерья","что можно делать в таверне приозерья","трактирщик приозерья"}},{q="Почему в таверне так многолюдно, несмотря на близкие нападения?",a="Поскольку орки клана Черной горы спускаются с северных скал, а гноллы грабят местные фермы, горожане и беженцы ищут безопасности в центре города. Таверна дает и физический кров, и место, где можно обменяться новостями об обороне.",al={"why is lakeshire inn full","lakeshire refugees inn","redridge tavern crowd","почему таверна приозерья полна","беженцы в таверне приозерья","толпа в таверне красногорья"}},{q="Кто такой Вилли Черный?",a="Вилли Черный — мрачный местный житель, сидящий в таверне. Он внимательно следит за угрозами Приозерью и делится сведениями и поручениями со способными искателями приключений, готовыми отразить натиск врага в Красногорье.",al={"wiley the black","guy in lakeshire tavern","wiley npc","вилли черный","человек в таверне приозерья","вилли"}},{q="Где в Приозерье находится таверна?",a="Таверна стоит у западного въезда в Приозерье на северном берегу Озера Безмолвия, недалеко от главной дороги, ведущей в город из Элвиннского леса.",al={"where is lakeshire inn","lakeshire tavern location","find lakeshire inn","где таверна приозерья","расположение таверны приозерья","найти таверну приозерья"}}},fp="13,263,18.532.0,20.514.0,45.203.0,53.255.0,23.229.0,42.161.0"}
P.entries["subzone:lakeshire-town-hall"] = {n="Ратуша Приозерья",s="Ратуша Приозерья — административный центр Красногорья, стоящий в сердце прибрежного поселения. Внутри Мировой судья Соломон руководит местным управлением, борясь с непрерывными угрозами орков клана Черной горы и гноллов.",h="Ратуша Приозерья — административный центр Красногорья, стоящий в сердце прибрежного поселения.",kw={"blackrock","gnolls","lakeshire","magistrate solomon","redridge","redridge mountains","stormwind","town hall","черная гора","гноллы","приозерье","мировой судья соломон","красногорье","штормград","ратуша"},ang={["faction:Alliance"]="Ратуша Приозерья — восточный рубеж Альянса в Красногорье, осажденный форпост, отчаянно удерживающий линию без королевской поддержки Штормграда.",["race:Human"]="Для людей Штормграда эта обновленная ратуша отражает и непреклонный дух сельских поселений, и горькое чувство брошенности, которое испытывают местные управители, когда столица закрывает глаза."},sec={{t="Центр управления Красногорьем",b="Ратуша Приозерья — старое каменное здание, которое не раз старательно обновляли. Она заметно расположена в Приозерье, и в ней находится Мировой судья Соломон, добрый и преданный гражданский руководитель, отвечающий за порядок на восточных рубежах Королевства Штормград. Поскольку военные ресурсы Штормграда истощены, а королевской помощи мало, ратуша из тихой канцелярии превратилась в действующий командный центр, где ежедневно обрабатываются отчаянные призывы к добровольным защитникам и наемникам."},{t="В осаде и в смятении",b="Набеги гноллов и наступление орков Черной Горы довели Соломона до отчаяния. Помощи мало, и магистрат охотно принимает помощь независимых искателей приключений, заходящих в двери ратуши."}},faq={{q="Кто главный в Ратуше Приозерья?",a="Ратушей руководит Мировой судья Соломон. Это добрый и благонамеренный администратор, главная управляющая власть Приозерья и окрестной долины Красногорья.",al={"who leads lakeshire","magistrate solomon","who is in town hall","кто управляет приозерьем","мировой судья соломон","кто в ратуше"}},{q="Почему ратуша ищет столько помощи извне?",a="Приозерью угрожают серьезные и растущие опасности от местных стай гноллов и враждебных отрядов орков клана Черной горы. Поскольку Штормград прислал минимум подкреплений, Мировому судье Соломону приходится нанимать проходящих искателей приключений для защиты региона.",al={"why does solomon need help","lakeshire problems","why are there so many quests here","зачем соломону помощь","проблемы приозерья","почему здесь так много заданий"}},{q="Почему Соломон принимает помощь путников?",a="Проблемы города с гноллами и орками Черной Горы поставили Соломона в отчаянное положение. Он охотно принимает помощь искателей приключений.",al={"why does solomon accept aid","lakeshire adventurers","town hall help","почему соломон принимает помощь","приключенцы приозерья","помощь ратуше"}},{q="Давно ли стоит Ратуша Приозерья?",a="Да, это старое здание, пережившее неспокойные десятилетия и прошедшее старательный ремонт и обновление, чтобы продолжать служить гражданским центром Красногорья.",al={"town hall age","how old is lakeshire town hall","town hall history","возраст ратуши","как стара ратуша приозерья","история ратуши"}}},fp="19,255,27.550.0,27.207.0,40.183.0,50.234.0,44.141.0,46.170.0"}
P.entries["subzone:lakkari-tar-pits"] = {n="Смоляные ямы Лаккари",s="Смоляные ямы Лаккари — череда зловонных булькающих луж густой черной смолы на севере Кратера Ун'Горо. Расположенные прямо под утесами Укрытия Маршалла, они служат естественной смертельной ловушкой для неосторожных зверей и инкубатором для враждебных смоляных элементалей.",h="Смоляные ямы Лаккари — череда зловонных булькающих луж густой черной смолы на севере Кратера Ун'Горо.",kw={"creeper","gormashh","lakkari","marshal's refuge","tar beast","tar pits","tarblossom","un'goro","ползун","гормашш","лаккари","укрытие маршалла","смоляной зверь","смоляные ямы","смоляной цветок","ун'горо"},ang={["class:Hunter"]="Держите питомцев на твердой земле возле Лаккари: любое существо, увязшее в густой жиже, становится неподвижной мишенью для хищных смоляных засадников.",["profession:Herbalism"]="Ямы известны редким смоляным цветком — неуловимым растением, что процветает глубоко под удушающей смолой."},sec={{t="Цепкая ловушка",b="Смоляные ямы Лаккари занимают низину на севере Кратера Ун'Горо, прямо к югу от Укрытия Маршалла. Густые зловонные лужи смолы затягивают всякого, кто неосторожно в них ступит, и быстро сковывают как зверей, так и искателей приключений. Торчащие кости сотен доисторических существ пробивают черную поверхность и свидетельствуют о поколениях животных, поглощенных трясиной. Хищные падальщики кружат по краям в ожидании, пока пойманная добыча выбьется из сил, а живые смоляные звери, засадники и ползуны поднимаются прямо из грязи, чтобы разделаться с чужаками."},{t="Скрытые растения",b="Несмотря на удушливые условия, в ямах существует уникальная жизнь. Редкие растения, известные как смоляной цветок, глубоко укореняются на дне смоляных озер. Эти цветы ценятся ботаниками и травниками за удивительную прочность и яркий вид, но добыть их можно, лишь преодолев удушающую жижу и отбившись от хищных смоляных владык, правящих кипящей топью."}},faq={{q="Что будет, если ступить в смолу?",a="Смола исключительно густая и липкая. Стоит войти в нее, и скорость движения падает до черепашьей, из-за чего мучительно трудно уклониться от агрессивных смоляных элементалей, патрулирующих поверхность.",al={"tar pits effect","tar slow","stepping in tar","действие смоляных ям","замедление в смоле","шаг в смолу"}},{q="Какие существа обитают в Смоляных ямах Лаккари?",a="Ямы населены разумной жижей и стихийными существами: смоляными зверями, ползунами, засадниками и владыками. Редкий исполин Гормашш тоже бродит по жиже в сопровождении местных падальщиков, которые кружат над лужами в поисках застрявшей добычи.",al={"tar beasts","tar pit monsters","tar creepers","смоляные звери","монстры смоляных ям","смоляные ползуны"}},{q="Что такое смоляные цветки?",a="Смоляные цветки — выносливые красивые цветы, которые растут погруженными в дно смоляных ям. Вязкая смола сохраняет и защищает их, поэтому они прочны и востребованы натуралистами, но собирать их исключительно опасно.",al={"tar blossom","tar flowers","un'goro tar flower","смоляной цветок","смоляные цветы","цветок смолы ун'горо"}},{q="Где находятся Смоляные ямы Лаккари?",a="Они находятся на севере Кратера Ун'Горо, в котловине прямо под аванпостом Укрытие Маршалла на утесе.",al={"tar pits location","where is lakkari","how to find tar pits","где смоляные ямы","расположение лаккари","как найти смоляные ямы"}}},fp="16,264,15.573.0,17.382.0,38.211.0,44.256.0,21.249.0,39.125.0"}
P.entries["subzone:land-s-end-beach"] = {n="Пляж на Краю Света",s="Пляж на Краю Света — безлюдный участок побережья на самой южной оконечности Танариса, фактически отмечающий южный край Калимдора. Защищенный высокими горными хребтами и бескрайними водами океана, он остается одним из самых уединенных и недоступных берегов континента.",h="Пляж на Краю Света — безлюдный участок побережья на самой южной оконечности Танариса, фактически отмечающий...",kw={"beach","coast","kalimdor","land's end beach","shore","south seas","tanaris","uldum","пляж","побережье","калимдор","пляж на краю света","берег","южные моря","танарис","ульдум"},sec={{t="Край мира",b="Скрытый за южными горами Танариса и запечатанными титанскими вратами Ульдума, Пляж на Краю Света представляет собой самый южный край материка Калимдора. Он отрезан от сухопутных путей через пустынные дюны, и добраться до этого обдуваемого ветрами берега можно, лишь проплыв по опасным, изнуряющим открытым водам Южных морей. Пляж — бесплодный рубеж бьющего прибоя, зыбучего песка и тихого уединения, почти не тронутый картелями и исследователями пустыни, которые обитают севернее, вокруг Прибамбасска."},{t="Тайны за линией прибоя",b="За полосой прибоя лежат одинокие безымянные островки, отделенные от материка обширными изнурительными глубокими водами. Добраться до этих далеких каменных крупиц достаточно опасно, чтобы довести до предела даже опытных пловцов. Мало кто из смертных имеет причину искать одинокие воды на краю Калимдора, поэтому пляж и окружающие его отмели остаются нетронутыми под палящим южным солнцем."}},faq={{q="Где находится Пляж на Краю Света?",a="Пляж на Краю Света находится на самом южном побережье Танариса, прямо к югу от гор, которые закрывают древние титанские врата Ульдума на крайнем юге Калимдора.",al={"where is lands end beach","lands end beach location","how to find lands end beach","где пляж на краю света","расположение пляжа на краю света","как найти пляж на краю света"}},{q="Как добраться до Пляжа на Краю Света?",a="Поскольку огромные горные хребты преграждают путь по суше из глубины пустыни, путникам обычно приходится плыть вдоль южного побережья от восточного Танариса или огибать опасные открытые воды, стараясь не поддаться усталости в глубоком море.",al={"how do i get to lands end beach","get to lands end tanaris","reach lands end","как добраться до пляжа на краю света","пляж на краю света танарис","дойти до края света"}},{q="Что находится на островах у берега пляжа?",a="Отдаленные безымянные острова лежат далеко от берега за широким проливом глубокого, изнуряющего океана. Это пустынные скалистые косы, которых достигали и исследовали лишь очень немногие путники.",al={"unnamed islands lands end","offshore islands tanaris","islands near lands end","безымянные острова край света","острова у берега танариса","острова у края света"}},{q="Живет ли кто-нибудь на Пляже на Краю Света?",a="На берегу нет крупных поселений. Отрезанный от торговли и цивилизации, он остается бесплодным природным побережьем, продуваемым океанскими ветрами.",al={"who lives at lands end","lands end beach inhabitants","is anyone at lands end","кто живет на краю света","жители пляжа на краю света","есть ли кто на краю света"}}},fp="16,276,21.525.0,18.420.0,34.184.0,34.261.0,50.189.0,37.154.0"}
P.entries["subzone:lariss-pavilion"] = {n="Павильон Лорисс",s="Павильон Лорисс — древнее эльфийское строение в глуши Фераласа, к северу от Лагеря Мохаче. Когда-то это было тихое убежище в классической архитектуре ночных эльфов, но окружающий лес стал опасен из-за порченых дриад, а изгнанный маг-высокорожденный выжидает в его тени.",h="Павильон Лорисс — древнее эльфийское строение в глуши Фераласа, к северу от Лагеря Мохаче.",kw={"azj'tordin","camp mojache","dire maul","dryads","feralas","highborne","lariss pavilion","pusillin","xerash fireblade","азж'тордин","лагерь мохаче","забытый город","дриады","фералас","высокорожденные","павильон лорисс","пузиллин","зераш огненный клинок"},ang={["class:Mage"]="Для знатоков тайной магии одинокий высокорожденный Азж'Тордин — живой реликт древнего, неограниченного колдовства Эльдре'Таласа.",["race:NightElf"]="Ночным эльфам павильон покажется горьким зрелищем: его красота затенена наследием гордыни высокорожденных, а родственные им дриады страдают от темной порчи."},sec={{t="Руины высокорожденных",b="Тихо стоя на утесах к северу от Лагеря Мохаче, Павильон Лорисс демонстрирует изящную каменную кладку и высокие арки древней империи кальдораев. В пору расцвета он принадлежал великому городу Эльдре'Талас, ныне известному как Забытый Город. Сегодня отсюда открывается защищенный вид на густой полог лесов Фераласа, но покой здесь хрупок: некогда кроткие дриады, бродящие по окрестным полянам, впали в безумие и порчу и яростно нападают на всякого, кто приблизится."},{t="Азж'Тордин и тайный проход",b="Самый известный обитатель павильона — неуловимый эльф Азж'Тордин. Порвав с развратным правлением принца Тортелдрина в Забытом Городе, Азж'Тордин бежал из руин через тайный проход, соединяющий павильон с недрами древнего города. Однако его тихое изгнание нарушено: непоседливый бес по имени Пузиллин украл его любимую книгу заклинаний, и изгнанник ищет помощи со стороны, чтобы вернуть ее."}},faq={{q="Где находится Павильон Лорисс?",a="Павильон Лорисс расположен на возвышенной лесистой местности в восточном Фераласе, к северу от аванпоста Орды — Лагеря Мохаче.",al={"lariss pavilion location","where is lariss pavilion","how to get to lariss pavilion","расположение павильона лорисс","где павильон лорисс","как добраться до павильона лорисс"}},{q="Кто такой Азж'Тордин?",a="Азж'Тордин — древний чародей-высокорожденный, бежавший от тирана принца Тортелдрина из Забытого Города. Теперь он расположился в павильоне и ищет искателей приключений, которые помогут вернуть украденную книгу заклинаний у проказливого беса.",al={"azjtordin","who is the elf at lariss pavilion","lariss pavilion quest giver","азж'тордин","кто эльф в павильоне лорисс","персонаж, выдающий задания в павильоне лорисс"}},{q="Почему дриады вокруг павильона враждебны?",a="Дриады, бродящие по лесу возле павильона, поддались порче, расползающейся по дебрям Фераласа, и обычно замкнутые хранительницы природы превратились в свирепых нападающих.",al={"angry dryads","why are dryads attacking","corrupted dryads feralas","злые дриады","почему дриады нападают","порченые дриады фералас"}},{q="Как павильон связан с Забытым Городом?",a="Скрытый черный ход у основания Павильона Лорисс ведет прямо в Забытый Город — это путь побега, которым Азж'Тордин ускользнул от своих собратьев.",al={"dire maul backdoor","dire maul shortcut","secret passage","черный ход забытого города","короткий путь в забытый город","тайный проход"}}},fp="15,312,23.484.0,33.435.0,33.129.0,18.220.0,47.190.0,43.158.0"}
P.entries["subzone:launch-bay"] = {n="Пусковая установка",s="Пусковая установка — подземный аэродром и ангар в глубинах Гномрегана, сразу за Залом Шестеренок. Некогда площадка для гномьих летательных машин и бомбардировщиков, теперь она полностью во власти враждебных лепрогномов и порченых механизмов.",h="Пусковая установка — подземный аэродром и ангар в глубинах Гномрегана, сразу за Залом Шестеренок.",kw={"bomber","dark iron","engineering labs","flying machine","gnomeregan","hangar","launch bay","leper gnome","бомбардировщик","черное железо","инженерные лаборатории","летательная машина","гномреган","ангар","пусковая установка","лепрогном"},ang={["profession:Engineering"]="Ангар демонстрирует вершину гномьей авиации и конструкций шасси, но старателям придется иметь дело с враждебными механизмами, чтобы рассмотреть их вблизи.",["race:Gnome"]="Видеть жемчужины гномьей авиации — летательные машины и бомбардировщики — брошенными и облепленными облученными прокаженными сородичами — горькое напоминание о трагической утрате города."},sec={{t="Аэродром на приколе",b="Пусковая установка — главный ангар воздушного флота Гномрегана — разделена на два яруса. Ее центральная платформа, куда ведут пандусы с верхнего перехода, до сих пор хранит гномьи летательные машины и тяжелые бомбардировщики, не успевшие вылететь до эвакуации города. Вместо опытных пилотов на летных палубах теперь кишат безумные лепрогномы, которые обслуживают и охраняют простаивающие боевые машины."},{t="Перекресток глубинного города",b="Помимо военной роли, Пусковая установка служит важным узлом комплекса. Пандусы из ее юго-восточного коридора спускаются в Инженерные лаборатории, а южный проход нижней палубы заполонили вторгшиеся дворфы Черного Железа. Этот южный туннель — опасный путь к сердцу города, Двору Механиков."}},faq={{q="Для чего использовалась Пусковая установка?",a="Она была задумана как подземный аэродром и ремонтный ангар для гномьих летательных машин и бомбардировщиков. Сегодня она заброшена и приспособлена лепрогномами, обитающими в руинах.",al={"gnomeregan hangar","what is launch bay","launch bay purpose","ангар гномрегана","что такое пусковая установка","назначение пусковой установки"}},{q="Кто сейчас контролирует Пусковую установку?",a="Верхний и нижний уровни заняты лепрогномами и агрессивными механизмами. Дальше, у южных выходов, закрепились и враждебные дворфы Черного Железа.",al={"who is in launch bay","launch bay enemies","who lives here","кто в пусковой установке","враги пусковой установки","кто здесь живет"}},{q="Куда ведет Пусковая установка?",a="Верхний восточный туннель ведет обратно в Зал Шестеренок. Юго-восточные пандусы спускаются в Инженерные лаборатории, а южный нижний туннель уходит глубже в Гномреган, к Двору Механиков.",al={"launch bay exits","how to leave launch bay","launch bay directions","выходы пусковой установки","как выйти из пусковой установки","пусковая установка маршрут"}},{q="Работают ли здешние летательные машины?",a="Несколько гномьих летательных машин и бомбардировщиков стоят на центральных платформах, но простаивают без присмотра среди хаоса падения города.",al={"can i fly the planes","flying machines gnomeregan","hangar planes","можно ли летать на самолетах","летательные машины гномрегана","самолеты в ангаре"}}},fp="10,302,19.415.0,27.339.0,32.191.0,32.198.0,31.201.0,41.149.0"}
P.entries["subzone:library-ironforge"] = {n="Библиотека (Стальгорн)",s="Библиотека, расположенная в восточном крыле Зала Исследователей, — главное хранилище исторических знаний, археологических реликвий и древних преданий Стальгорна. Ею заботливо управляет Лига исследователей: здесь собраны обширные исторические труды и редкие артефакты, найденные при раскопках по всему Азероту.",h="Библиотека, расположенная в восточном крыле Зала Исследователей, — главное хранилище исторических знаний...",kw={"books","curator thorius","explorers league","hall of explorers","ironforge","library","mae paledust","museum","книги","куратор ториус","лига исследователей","зал исследователей","стальгорн","библиотека","мэй бледнопыль","музей"},ang={["faction:Alliance"]="Библиотека — ценнейший стратегический архив для Альянса: в ней хранятся важные записи Альянса Лордерона и свидетельства очевидцев Второй и Третьей войн.",["race:Dwarf"]="Для дворфов этот зал воплощает стремление короля Магни Бронзоборода раскрыть их происхождение от Титанов: здесь хранятся сами рассказы о Пробуждении и Войне трех молотов."},sec={{t="Сердце Лиги исследователей",b="Occupying a massive chamber within the Hall of Explorers, the Library is where dwarven scholars sift through the relics and field reports recovered by adventurers across the world. Administered by the Explorers' League, the shelves are packed with foundational chronicles detailing the War of the Three Hammers, the ancient Troll Wars, and the origins of the dwarven race. Inquiries regarding rare books or archival locations are directed to Librarian Mae Paledust."},{t="Музейные экспозиции",b="За рядами плотных книжных полок библиотека служит еще и действующим музеем под руководством куратора Ториуса. Здесь изучают, сохраняют и выставляют образцы, добытые при глубоких раскопках, в заброшенных руинах и на дальних берегах. Хранители Лиги собирают все — от грубых идолов мурлоков и резных ножей до загадочных реликвий, найденных во льдах севера, — и каталогизируют каждую находку, чтобы восстановить скрытую историю Титанов и раннего Азерота."}},faq={{q="Для чего нужна Библиотека в Стальгорне?",a="Это главный исследовательский архив и музей Лиги исследователей. Ее члены приносят сюда найденные артефакты, тома и полевые записи, чтобы их каталогизировали, расшифровали и сохранили для дворфов и Альянса.",al={"ironforge library purpose","what is this place","hall of explorers library","библиотека стальгорна","что это за место","библиотека зала исследователей","зачем нужна библиотека"}},{q="Кто управляет здешними коллекциями?",a="Письменные собрания библиотеки и поиск по архивам находятся в ведении библиотекаря Мэй Бледнопыль, а музейное крыло и его исторические артефакты хранит и опекает куратор Ториус.",al={"who runs the library","ironforge librarian","museum curator","кто управляет библиотекой","библиотекарь стальгорна","хранитель музея"}},{q="Какие книги здесь можно прочесть?",a="В библиотеке хранятся основополагающие труды о древних и недавних событиях: о Древних богах, драконьих родах, войнах с троллями, Войне трех молотов, возвышении Орды и создании Альянса Лордерона.",al={"ironforge books","readable tomes","what lore is here","книги стальгорна","книги для чтения","какие предания здесь"}},{q="Где в Стальгорне находится Библиотека?",a="Библиотека занимает восточное крыло Зала Исследователей, расположенного в северо-восточной части Стальгорна.",al={"ironforge library location","how to find the library","где библиотека стальгорна","как найти библиотеку"}}},fp="19,321,30.465.0,19.470.0,48.230.0,33.202.0,36.239.0,42.115.0"}
P.entries["subzone:library-wing-northshire"] = {n="Библиотечное крыло (Североземье)",s="Библиотечное крыло — тихое, заставленное книгами южное крыло Аббатства Североземья в Элвиннском лесу. Это приют для ученых, где начинающих жрецов и магов, вставших на защиту Штормграда, обучают основам.",h="Библиотечное крыло — тихое, заставленное книгами южное крыло Аббатства Североземья в Элвиннском лесу.",kw={"elwynn forest","khelden bremen","library wing","mage trainer","northshire","northshire abbey","priest trainer","priestess anetta","элвиннский лес","кельден бремен","библиотечное крыло","учитель магов","североземье","аббатство североземья","учитель жрецов","жрица анетта"},ang={["class:Mage"]="Кельден Бремен обучает в этих тихих залах начинающих магов, преподавая им основы магии огня и льда.",["class:Priest"]="Жрица Анетта живет здесь и дает молодым жрецам первые уроки использования Света, чтобы исцелять раны и поражать врагов."},sec={{t="Обитель тайных и священных знаний",b="Библиотечное крыло отходит на юг от главного зала Аббатства Североземья. Здесь стоят пыльные полки, кафедры для занятий и тихие альковы для умственного и духовного обучения. Пока воины-новобранцы тренируются в северном Зале Оружия, будущие маги и жрецы собираются здесь, чтобы постичь основы тайной магии и Света. Сейчас жрица Анетта наставляет молодых жрецов в вопросах веры и исцеления, а Кельден Бремен учит начинающих магов управлять первозданной энергией стихий."}},faq={{q="Где находится Библиотечное крыло?",a="Библиотечное крыло занимает южную часть Аббатства Североземья и находится рядом с главным залом. Оно расположено прямо напротив воинского Зала Оружия.",al={"where is the library wing","how to find northshire library","library location northshire","где библиотечное крыло","как найти библиотеку североземья","расположение библиотеки североземья"}},{q="Для чего нужно это крыло?",a="Это научный и духовный центр Аббатства Североземья, где новобранцы, готовящиеся служить Королевству Штормград, занимаются исследованиями, учатся магии и молятся.",al={"why does northshire abbey have a library","library wing purpose","зачем в аббатстве североземья библиотека","назначение библиотечного крыла"}}},fp="25,224,32.500.0,34.152.0,33.189.0"}
P.entries["subzone:library-wing-tyr-s-hand"] = {n="Библиотечное крыло (Длань Тира)",s="Библиотечное крыло — уединенный зал внутри Аббатства Длани Тира, расположенный в сильно укрепленном оплоте Алого ордена в Восточных Чумных землях. Когда-то оно служило священным занятиям и размышлениям, а теперь его полки заполнены жесткими догмами и пропагандой фанатичного ордена. Члены ордена собираются здесь, чтобы изучать писания и охранять священные реликвии святилища.",h="Библиотечное крыло — уединенный зал внутри Аббатства Длани Тира, расположенный в сильно укрепленном оплоте...",kw={"abbey","eastern plaguelands","holy water","library wing","propaganda","scarlet crusade","tomes","tyr's hand","аббатство","восточные чумные земли","святая вода","библиотечное крыло","пропаганда","алый орден","тома","длань тира"},ang={["class:Paladin"]="Паладины видят в этом крыле извращение изначальных научных традиций Серебряной Длани, где преданность Свету сменилась воинственным фанатизмом.",["class:Priest"]="Для служителей Света Библиотечное крыло — горькое свидетельство того, как божественное созерцание можно исказить до узколобого экстремизма и паранойи."},sec={{t="Святилище фанатичных преданий",b="Библиотечное крыло находится у центрального нефа Аббатства Длани Тира напротив воинских помещений и отражает идейную сердцевину Алого ордена. В этих тихих каменных альковах жрецы и крестоносцы погружаются в богословские трактаты, воинственные доктрины и тексты, искаженные годами непрерывной войны с Плетью. Вместо того чтобы хранить открытое знание, здешние тексты питают паранойю ордена и укрепляют его убежденность, что все чужаки несут на себе скверну."},{t="Сосуды Света",b="Помимо собрания пристрастных свитков и писаний, Библиотечное крыло служит хранилищем священных предметов, которые оберегает жречество Алого ордена. В задних комнатах крыла крестоносцы держат освященные припасы, в том числе чаши с чистой святой водой для обрядов высших чинов. Чтобы пробиться в эти внутренние святилища, нужно одолеть элитных защитников Алого ордена, для которых библиотека — одновременно оплот веры и неприступная крепость."}},faq={{q="Где находится Библиотечное крыло?",a="Библиотечное крыло расположено внутри Аббатства Длани Тира, в анклаве Алого ордена — Длани Тира — на юго-востоке Восточных Чумных земель. Внутри аббатства оно находится к югу от главного входного зала, напротив Зала Оружия.",al={"library wing location","where is the library wing","how to find library wing tyr's hand","расположение библиотечного крыла","где библиотечное крыло","как найти библиотечное крыло длани тира"}},{q="Какие книги здесь хранятся?",a="На полках стоят богословские труды о Свете, а также воинственные доктрины и тщательно отобранная фанатичная литература Алого ордена, оправдывающая его нескончаемый поход против нежити и чужаков.",al={"what books are in the library","tyr's hand library tomes","what is stored in the library wing","какие книги в библиотеке","тома библиотеки длани тира","что хранится в библиотечном крыле"}},{q="Кто контролирует эту часть аббатства?",a="Библиотечное крыло прочно удерживают элитные силы Алого ордена, в том числе клирики, ученые и тяжеловооруженные защитники, охраняющие догматические тексты и освященные припасы.",al={"who is in the library wing","who controls the library wing","кто в библиотечном крыле","кто контролирует библиотечное крыло"}},{q="Опасно ли посещать Библиотечное крыло?",a="Да, здесь исключительно опасно. Библиотека находится в глубине Длани Тира — элитного оплота Алого ордена, населенного фанатиками высокого уровня, которые нападают на чужаков без предупреждения.",al={"is the library wing safe","tyr's hand library difficulty","безопасно ли библиотечное крыло","сложность библиотеки длани тира"}}},fp="25,379,23.516.0,20.463.0,34.235.0,34.213.0,36.198.0,39.175.0"}
P.entries["subzone:light-s-hope-chapel"] = {n="Часовня Последней Надежды",s="Часовня Последней Надежды — священное убежище в восточной части Чумных земель, главный оплот и штаб Серебряного Рассвета. Когда-то уединенная святыня Церкви Священного Света в Восточном Пределе, теперь она стоит как несокрушимый бастион против Плети. В ее освященной земле покоятся останки тысячи павших героев Лордерона, защищенные от некромантии Короля-лича.",h="Часовня Последней Надежды — священное убежище в восточной части Чумных земель, главный оплот и штаб...",kw={"argent dawn","consecrated ground","eastweald","holy light","lights hope","plaguelands","sanctum of light","tyrosus","серебряный рассвет","освященная земля","восточный предел","свет","последняя надежда","чумные земли","святилище света","тиросс"},ang={["class:Paladin"]="Для воинов Света Часовня Последней Надежды — священный маяк в море смерти, где покоятся освященные гробницы величайших павших героев Серебряной Длани.",["faction:Horde"]="Хотя часовня находится в глубине человеческих земель и ею управляют бывшие рыцари Серебряной Длани, она принимает бойцов Орды, доказавших стремление истребить нежить."},sec={{t="Бастион в Чумных землях",b="Часовня Последней Надежды, основанная много веков назад как застава Церкви Священного Света в цветущем Восточном Пределе, пережила падение Лордерона и стала важным убежищем в зараженном краю. Когда фанатичные экстремисты из числа уцелевших откололись и создали Алый орден, более умеренные рыцари и жрецы объединились и основали Серебряный Рассвет. Избрав это уединенное освященное место передовой базой, Рассвет открыл двери для всех рас и фракций — как Альянса, так и Орды, — объединенных общим походом за изгнание Плети и возвращение северных земель."},{t="Освященные склепы",b="Стратегическое значение Часовни Последней Надежды гораздо глубже ее наземных укреплений. После Третьей войны лорд Максвелл Тиросс и его соратники совершили тайную торжественную миссию по всему Лордерону: они извлекли тела тысячи почитаемых героев Света и перезахоронили их в катакомбах под часовней. Это массовое перезахоронение должно было уберечь их священные останки и праведные души от осквернения и обращения в воинов армии Короля-лича. Поэтому здешняя земля излучает глубокую священную силу, которую Плеть раз за разом пыталась погасить — и безуспешно."}},faq={{q="Почему Альянс и Орда действуют сообща в Часовне Последней Надежды?",a="Серебряный Рассвет считает Плеть смертельной угрозой для всех живых существ, стоящей выше мелкой политики Альянса и Орды. В отличие от фанатичного Алого ордена, считающего людей высшей расой, Рассвет охотно принимает способных воинов, шаманов, друидов и жрецов из любого народа, готового сражаться с нежитью.",al={"why is horde allowed here","argent dawn neutral","cross faction base","почему здесь можно орде","серебряный рассвет нейтрален","общая база фракций"}},{q="Кто возглавляет защитников?",a="Лорд Максвелл Тиросс руководит Серебряным Рассветом из Часовни Последней Надежды, заняв место после гибели первого главы ордена, лорда Реймонда Джорджа. Тиросс лично возглавил усилия по захоронению павших героев Лордерона в катакомбах часовни и успешно отразил несколько крупных вторжений Плети на заставу.",al={"who is in charge of lights hope","argent dawn leader","lord tyrosus","кто главный в последней надежде","глава серебряного рассвета","лорд тиросс"}},{q="Почему эта часовня так священна?",a="Это древнее священное место, построенное в пору раннего расширения Церкви Священного Света, а в катакомбах под зданием покоятся останки тысячи павших защитников Лордерона. Сосредоточенная в освященной земле священная сила не дает Королю-личу поднять эти души в виде нежити.",al={"what is under the chapel","why does the scourge want lights hope","sanctum beneath chapel","что под часовней","зачем плети последняя надежда","святилище под часовней"}},{q="Как часовня связана с Алым орденом?",a="Серебряный Рассвет возник из паладинов и жрецов, отвергших безудержный фанатизм и изоляционизм Алого ордена, но у двух орденов остается общий враг — Плеть. Рассвет сражается с ней по-своему, из часовни, открытой для всех, кто готов выступить против нежити.",al={"are they friends with scarlet crusade","scarlet crusade lights hope","argent dawn vs scarlet crusade","дружат ли с алым орденом","алый орден последняя надежда","серебряный рассвет против алого ордена"}}},fp="19,423,28.612.0,22.633.0,67.327.0,29.326.0,29.335.0,64.289.0"}
P.entries["subzone:lion-s-pride-inn"] = {n="Таверна Гордость Льва",s="Таверна Гордость Льва — оживленная таверна и общественный центр Златоземья в Элвиннском лесу. Ее держит на протяжении многих поколений семья Фарли, и она служит главным местом отдыха, собраний и найма для путников, направляющихся к югу от Штормграда.",h="Таверна Гордость Льва — оживленная таверна и общественный центр Златоземья в Элвиннском лесу.",kw={"elwynn forest","farley","goldshire","goldshire inn","innkeeper farley","lion's pride inn","lions pride","элвиннский лес","фарли","златоземье","таверна в златоземье","хозяин таверны фарли","таверна гордость льва","гордость льва"},ang={["faction:Alliance"]="Как главная таверна у ворот Штормграда, она служит оживленным постоялым двором, где путники Альянса согласуют патрули и торгуют по всем центральным землям.",["race:Human"]="Для людей, покидающих Аббатство Североземья, таверна Гордость Льва — первое знакомство с широкой жизнью и бедами королевства за стенами монастыря."},sec={{t="Сердце Златоземья",b="Таверна Гордость Льва стоит на перекрестке дорог Элвиннского леса и является оживленным центром Златоземья. Ею управляет Хозяин таверны Фарли согласно традиционному девизу заведения — «Отдых и покой для усталых и замерзших». Здесь есть теплые очаги, крепкие напитки и комнаты для уставших искателей приключений, только что покинувших Североземье. Семья Фарли с гордостью управляет заведением на протяжении многих поколений, еще со времен правления короля Ллейна Рина I. Поскольку Златоземье лежит на важных торговых путях между Штормградом, Западным Краем, Красногорьем и Сумеречным лесом, таверна стала незаменимым местом встреч, где собираются городские маршалы, местные мастера и опытные наставники, чтобы обменяться новостями и нанять проходящих мимо наемников."}},faq={{q="Кому принадлежит таверна Гордость Льва и кто ею управляет?",a="Таверной управляет Хозяин таверны Фарли. Его семья на протяжении многих поколений честно ведет дело в таверне Гордость Льва еще с до Первой войны, со времен короля Ллейна Риня I.",al={"innkeeper","who owns lions pride","who runs goldshire inn","трактирщик","хозяин гордости льва","кто управляет таверной в златоземье"}},{q="Какие услуги доступны в таверне?",a="Помимо еды, напитков и ночлега, в таверне Гордость Льва можно найти учителей разных классов, приезжих торговцев и местных персонажей, выдающих задания, которым нужна помощь с гнолльями, кобольдами и разбойниками, досаждающими Элвиннскому лесу.",al={"trainers","what is inside","amenities","учителя","что внутри","услуги"}},{q="Почему таверна — такой важный центр Элвиннского леса?",a="Таверна расположена прямо на перекрестке Златоземья к югу от Штормграда и служит главным местом отдыха для путников, идущих между столицей, Западным Краем и Красногорьем. Естественно, это первый крупный центр, который посещают молодые искатели приключений после ухода из Долины Североземья.",al={"why so popular","goldshire crossroads","importance of lions pride","почему так популярна","перекресток златоземья","значение гордости льва"}},{q="Каков девиз таверны Гордость Льва?",a="По словам Хозяина таверны Фарли, основополагающий девиз таверны — «Отдых и покой для усталых и замерзших».",al={"inn motto","motto","девиз таверны","девиз"}}},fp="16,263,18.715.0,39.209.0,43.208.0,44.279.0,42.104.0"}
P.entries["subzone:loading-room"] = {n="Погрузочный зал",s="Погрузочный зал — промышленное складское помещение в обширном механическом комплексе Гномрегана. Сейчас эта подземная площадка находится в глубине оскверненной павшей столицы, опасно близко к взбесившимся механизмам, таким как Техбот.",h="Погрузочный зал — промышленное складское помещение в обширном механическом комплексе Гномрегана.",kw={"dun morogh","gnomeregan","loading room","techbot","tinkertown","train depot","дун морог","гномреган","погрузочный зал","техбот","город механиков","железнодорожное депо"},ang={["profession:Engineering"]="Взбесившийся Техбот и оставшиеся в Погрузочном зале механизмы дают инженерам наглядный урок о том, что случается, когда автоматическая защита выходит из строя без обслуживания.",["race:Gnome"]="Для гномов, возвращающих свой город, Погрузочный зал — горькое напоминание о том, как привычная городская инфраструктура была в спешке брошена во время вторжения троггов и токсичной катастрофы."},sec={{t="Промышленный склад в осаде",b="До падения Гномрегана Погрузочный зал был оживленным транзитным пунктом и грузовым отсеком, связанным с подземными транспортными сетями столицы механиков. Сегодня, как и весь разрушенный город, он погрузился в хаос. Радиоактивные осадки, вторгшиеся трогги и неисправные механизмы сделали это место крайне опасным. Окрестности охраняет взбесившийся механизм Техбот, представляющий серьезную угрозу для выживших гномов и отважных бойцов Альянса, пытающихся отвоевать периметр."}},faq={{q="Для чего использовался Погрузочный зал?",a="Исторически он служил промышленным погрузочным отсеком и грузовым пунктом, связанным с внутренним транспортом и поездами Гномрегана. После падения города он стал еще одним потерянным сектором, захваченным опасностями.",al={"loading room purpose","what is loading room","what was loading room","назначение погрузочного зала","что такое погрузочный зал","чем был погрузочный зал"}},{q="Какие угрозы можно встретить в Погрузочном зале?",a="В Погрузочном зале обитает вышедший из строя механический защитник Техбот, а также повсюду радиоактивное заражение и неисправные механизмы в глубинах города.",al={"who is in loading room","loading room bosses","techbot location","кто в погрузочном зале","боссы погрузочного зала","где техбот"}},{q="Безопасно ли исследовать Погрузочный зал?",a="Нет. Весь этот район — спорная территория среди руин Гномрегана. Любой ударный отряд Альянса, идущий в эту часть комплекса, столкнется с враждебными механизмами и ядовитой средой.",al={"is it safe","can alliance go here","безопасно ли","может ли альянс пройти сюда"}}},fp="12,252,28.525.0,34.220.0,46.194.0,36.199.0"}
P.entries["subzone:longshore"] = {n="Бескрайний берег",s="Бескрайний берег — обширное песчаное побережье, тянущееся вдоль всего западного края Западного Края. Несмотря на простор и живописность, берег известен своей опасностью из-за множества агрессивных мурлоков и разбросанных у побережья обломков кораблей.",h="Бескрайний берег — обширное песчаное побережье, тянущееся вдоль всего западного края Западного Края.",kw={"aquatic form","daphne stilwell","longshore","murloc","old murk-eye","shipwrecks","westfall","westfall lighthouse","водяной облик","дафна стилвелл","бескрайний берег","мурлок","старый мрачноглаз","кораблекрушения","западный край","маяк в западном крае"},ang={["class:Druid"]="Друидам Альянса приходится погружаться в глубины у северо-запада Бескрайнего берега, чтобы найти сундук, спрятанный у затонувшего корабля, и собрать подвеску, необходимую для водяного облика.",["class:Paladin"]="Паладины, следующие указаниям Даториана Ралла в Штормграде, отправляются на юг, на ферму Дафны Стилвелл на Бескрайнем берегу, и доказывают свою доблесть, защищая невинную фермершу от налетчиков Братства Справедливости."},sec={{t="Коварное побережье",b="Бескрайний берег тянется по всей западной границе Западного Края и является одним из самых широких непрерывных пляжей Восточных королевств. Но путникам он почти не дает покоя. Прибрежные мурлоки властвуют в прибое под предводительством таких грозных тварей, как Старый Мрачноглаз, а на мелководье лежат остатки затонувших судов, включая разрушенные эльфийские эсминцы. Ближе к югу одинокие поселенцы вроде Дафны Стилвелл борются с разбойниками Братства Справедливости, находясь в виду Маяка в Западном Крае через воду."}},faq={{q="Почему Бескрайний берег так опасен?",a="Берег кишит агрессивными племенами мурлоков, которые беспрепятственно бродят по пескам и нападают из засады на всякого, кто подойдет слишком близко к прибою. Помимо мурлоков, южную оконечность пляжа беспокоят разбойники Братства Справедливости, грабящие прибрежные усадьбы.",al={"why are there so many murlocs","longshore hazards","is longshore safe","почему так много мурлоков","опасности бескрайнего берега","безопасен ли бескрайний берег"}},{q="Кто такая Дафна Стилвелл?",a="Дафна Стилвелл — одинокая поселенка, живущая на уединенной ферме на юго-западе Бескрайнего берега. Из-за ее уязвимого положения на нее часто нападает Братство Справедливости, и Рыцари Серебряной Длани отправляют ей на защиту послушников-паладинов.",al={"daphne stilwell","stilwell farm","woman on the beach","дафна стилвелл","ферма стилвелл","женщина на пляже"}},{q="Что за кораблекрушения лежат у побережья?",a="У Бескрайнего берега под водой лежит множество обломков — от торговых судов до эльфийских эсминцев, погибших в прошлых морских сражениях. Эти подводные руины привлекают мародеров, мурлоков и искателей приключений, ищущих реликвии, потерянные под волнами.",al={"elven destroyers westfall","sunken ships longshore","shipwrecks","эльфийские эсминцы западный край","затонувшие корабли бескрайний берег","кораблекрушения"}},{q="Почему друиды приходят на Бескрайний берег?",a="Друиды Альянса проходят обряд, известный как Испытание морского льва, чтобы овладеть водяным обликом. Для этого нужно найти подводный сундук у затонувшего корабля у берега на северо-западе Бескрайнего берега и достать из него Половинка подвески Выносливости водяного облика.",al={"druid quest longshore","strange lockbox westfall","half pendant of aquatic endurance","задание друида бескрайний берег","странный сундук западный край","половинка подвески выносливости водяного облика"}}},fp="9,255,23.513.0,34.260.0,23.284.0,44.239.0,34.262.0"}
P.entries["subzone:lordamere-internment-camp"] = {n="Лордамерские выселки",s="Лордамерские выселки — бывший лагерь заключения времен Второй войны, стоящий на возвышенности над кратером Даларана. Некогда построенный для содержания вялых орков, лагерь теперь занят уцелевшими магами и стражами Даларана, а также вероломной группой беглецов из числа Отрекшихся.",h="Лордамерские выселки — бывший лагерь заключения времен Второй войны, стоящий на возвышенности над кратером...",kw={"alterac","belamoore","bloodstone","dalaran","internment","kegan darkmar","lordamere","orcs","альтерак","беламур","кровавый камень","даларан","выселки","кеган мракмар","лордамер","орки"},ang={["race:Orc"]="Для орков посещение этого лагеря — мрачное напоминание о временах после Второй войны, когда тысячи их сородичей чахли в плену, пока Тралл не сплотил их народ.",["race:Undead"]="Дезертиры, засевшие в Лордамере, — прямое предательство Темной Госпожи. Выследить Кегана Мракмара и вернуть кровавые камни необходимо, чтобы тайны Отрекшихся не попали в руки людей."},sec={{t="От тюрьмы до исследовательского форпоста",b="После Второй войны Альянс построил лагеря для интернированных по всем северным королевствам, чтобы содержать побежденную орочью Орду. Лордамер был уникален как единственный лагерь в Альтеракских горах, находившийся под юрисдикцией Даларана. Много лет назад принц Артас Менетил и леди Джайна Праудмур, будучи юными, как известно, тайком пробрались мимо сторожевых башен, чтобы взглянуть на пленных орков и поспорить о нравственности их заключения. Теперь, когда орки давно освобождены или бежали, лагерь под началом тюремщицы Беламур служит форпостом для остатков Даларана, изучающих опасные магические реликвии."},{t="Беглецы из Отрекшихся",b="Лагерь оказался втянут в политику нежити Лордерона. Четверо отрекшихся-ренегатов — Кеган Мракмар и его соратники — похитили из Подгорода могущественные артефакты из кровавого камня и бежали сюда, обменяв их у тюремщицы Беламур на убежище за линиями Даларана. Маги охотно приняли артефакты для изучения тайной магии, а палачи в Мельнице Таррен посылают верных агентов Орды выследить перебежчиков и вернуть похищенные кровавые камни, пока Даларан не открыл их силу."}},faq={{q="Для чего изначально был построен этот лагерь?",a="Его основал Альянс после Второй войны, чтобы держать в заключении пленных орков, впавших в вялость после потери демонической жажды крови. Даларан нес службу на сторожевых башнях и надзирал за лагерем из-за его близости к городу магов.",al={"internment camp history","why is there a camp here","what is this place","история лагеря","почему здесь лагерь","что это за место"}},{q="Кто контролирует лагерь сейчас?",a="Лагерь удерживают тюремщица Беламур и отряд стражей и магов Даларана. Хотя сам Даларан сильно пострадал и укрыт защитным куполом в соседнем кратере, эти уцелевшие продолжают исследования с укрепленного холма.",al={"who lives here","who runs the camp","who is warden belamoore","кто здесь живет","кто управляет лагерем","кто такая тюремщица беламур"}},{q="Почему внутри лагеря есть Отрекшиеся?",a="Это дезертиры из Подгорода под предводительством Кегана Мракмара. Предав королеву Сильвану и украв священные артефакты из кровавого камня, они обменяли реликвии тюремщице Беламур на защиту Даларана от возмездия Отрекшихся.",al={"undead here","kegan darkmar","forsaken deserters","нежить здесь","кеган мракмар","дезертиры отрекшихся"}},{q="Какая связь у этого места с Артасом и Джайной?",a="За годы до того, как Плеть обрушилась на Лордерон, принц Артас Менетил и леди Джайна Праудмур однажды ночью проскользнули мимо стражи лагеря, чтобы увидеть пленных орков. Джайна глубоко посочувствовала заключенным семьям, а Артас считал лагеря суровой необходимостью.",al={"arthas jaina camp","arthas visit","jaina camp","артас джайна лагерь","визит артаса","джайна лагерь"}}},fp="25,274,31.595.0,18.501.1,40.265.0,32.224.0,46.240.0,57.294.0"}
P.entries["subzone:lordamere-lake"] = {n="Озеро Лордамер",s="Озеро Лордамер — одно из крупнейших пресноводных озер Восточных королевств; оно граничит с Тирисфальскими лесами, Серебряным бором и Альтеракскими горами. Когда-то оживленное водное сердце человеческой цивилизации на севере, теперь его холодные воды и острова населяют некроманты Плети, одичавшие мурлоки и расползающаяся тень нежити.",h="Озеро Лордамер — одно из крупнейших пресноводных озер Восточных королевств; оно граничит с Тирисфальскими...",kw={"alterac mountains","dawning isles","fenris isle","lake lordamere","lordamere lake","silverpine forest","thule ravenclaw","tirisfal glades","vile fin","альтеракские горы","рассветные острова","остров фенриса","озеро лордамер","лордамер","серебряный бор","тул коготь ворона","тирисфальские леса","злобный плавник"},ang={["race:Human"]="Тихие, туманные воды Лордамера — мрачное напоминание о разрушенном величии северных человеческих королевств, которые некогда свободно торговали на его берегах.",["race:Undead"]="Для Отрекшихся озеро Лордамер — одновременно оборонительный ров, защищающий Тирисфаль, и действующая линия фронта, где необходимо уничтожить остатки Плети на Острове Фенриса."},sec={{t="Сердце павших королевств",b="В золотой век Альянса Лордерона озеро Лордамер лежало на перекрестке человеческого могущества. Его северные берега охраняла Столица Лордерона, у южной оконечности поднимался город-государство магов Даларан, а гористый восточный край занимал Альтерак. Торговые суда и рыбацкие лодки когда-то без страха пересекали его широкую, окутанную туманом гладь. После разорения Третьей войны озеро превратилось из центра торговли в естественную преграду, отделяющую земли Отрекшихся — Тирисфаль и Серебряный бор — от коварных высот Альтерака."},{t="Спорные просторы",b="Сегодня плавание по темным водам Лордамера полно опасностей. В центре озера лежит Остров Фенриса, где некромант Плети Тул Коготь Ворона и его мертвые прислужники держатся против Отрекшихся, а по окрестностям рыщут свирепые воргены. Дальше к востоку находятся Рассветные острова, полностью захваченные агрессивными мурлоками Злобного Плавника. От руин вокруг Даларана до берегов Подгорода озеро больше не мирный путь, а затопленный рубеж, за который борются уцелевшие чудовища и армии мертвых."}},faq={{q="Какие королевства исторически граничили с озером Лордамер?",a="В пору расцвета Альянса Лордерона озеро Лордамер граничило с тремя крупными человеческими королевствами: Королевством Лордерон на севере и западе, Даларан на юге и Альтерак на восточных горных склонах.",al={"who lived on lordamere lake","lordamere lake history","kingdoms around lordamere","кто жил у озера лордамер","история озера лордамер","королевства вокруг лордамера"}},{q="Кто управляет Островом Фенриса посреди озера?",a="Остров Фенриса сейчас удерживают агенты Плети под командованием некроманта Тула Когтя Ворона, хотя им приходится отражать неослабевающие атаки Отрекшихся и постоянный натиск голодных воргенов.",al={"who is on fenris isle","fenris island lordamere","fenris isle ruler","кто на острове фенриса","остров фенриса лордамер","правитель острова фенриса"}},{q="Что такое Рассветные острова?",a="Рассветные острова — группа небольших островов в восточной части озера Лордамер, к востоку от Острова Фенриса. Их захватили и заняли враждебные мурлоки Злобного Плавника.",al={"dawning isles location","islands in lordamere lake","dawning isles monsters","расположение рассветных островов","острова озера лордамер","монстры рассветных островов"}},{q="Как озеро получило свое название?",a="Озеро названо по соседней Столице и королевству Лордерон, которые получили имя от древнего человеческого полководца Лордена.",al={"lordamere name origin","why is it called lordamere","происхождение названия лордамер","почему озеро называется лордамер"}}},fp="14,349,28.598.0,19.525.0,51.222.0,51.207.0,27.184.0,30.150.0"}
P.entries["subzone:lost-fleet"] = {n="Погибший Флот",s="Погибший Флот — разбитые деревянные остовы Третьей флотилии Кул Тираса, затонувшие у северного побережья Болотины в Бухте Барадин. Уничтоженные во время Второй войны красными драконами, порабощенными кланом Драконьей Пасти, обломки теперь населяют неупокоенные проклятые моряки-нежить, привязанные к ним таинственным проклятием.",h="Погибший Флот — разбитые деревянные остовы Третьей флотилии Кул Тираса, затонувшие у северного побережья...",kw={"baradin bay","bluegill marsh","derek proudmoore","doomed fleet","eye of paleth","fitzsimmons","halyndor","intrepid","lost fleet","snellig","third fleet","wave mistress","wetlands","бухта барадин","болота синежабрых","дерек праудмур","обреченный флот","око палета","фитсиммонс","халиндор","неустрашимый","погибший флот","снеллиг","третья флотилия","повелительница волн","болотина"},ang={["faction:Alliance"]="Остовы — мрачное напоминание о тяжелой цене, которую заплатили Кул Тирас и Альянс во Второй войне; они требуют уважения к павшим и конца их проклятых мук.",["profession:Blacksmithing"]="Кузнецы Альянса часто слышат рассказы о затонувшем флоте: другой корабль той же эскадры, «Летящий орлан», пошел ко дну с редкими слитками светокованого железа."},sec={{t="Трагический конец во Второй войне",b="Во время Второй войны Третья флотилия Кул Тираса находилась под командованием Дерека Праудмура, старшего сына лорда-адмирала. В бою с флотом орков корабли Альянса были атакованы с воздуха красными драконами, порабощенными кланом Драконьей Пасти. Драконье пламя быстро охватило флотилию, и гордые корабли, такие как «Повелительница волн» и «Неустрашимый», разбились на мелях и рифах северных Болот Синежабрых. Почти весь экипаж утонул или сгорел, и единственным выжившим стал Первый помощник Фитсиммонс."},{t="Проклятие Палета",b="Водная могила не стала концом для моряков Третьей флотилии. Глубоко в затонувшем трюме «Неустрашимого» лежал запретный артефакт — Проклятое Око Палета, которое копил жадный командир корабля капитан Халиндор. Темная реликвия осквернила утонувших моряков и привязала их души к расщепленным доскам в облике безумной проклятой нежити. Лишь призрак первого помощника Снеллига сохранил подобие рассудка и бродит по болотистому берегу, пока его бывшие товарищи яростно набрасываются на всех, кто приближается к обломкам."}},faq={{q="Что такое Погибший Флот?",a="Погибший Флот — обломки нескольких боевых кораблей Кул Тираса из Третьей флотилии, лежащие у северного побережья Болотины в Бухте Барадин. Они были уничтожены во время Второй войны, и теперь их населяет нежить из бывших экипажей.",al={"lost fleet","what is this place","wetlands shipwrecks","third fleet","погибший флот","что это за место","кораблекрушения болотины","третья флотилия"}},{q="Как были уничтожены эти корабли?",a="Во время Второй войны флотилию атаковали с воздуха и сожгли порабощенные красные драконы орков из клана Драконьей Пасти. Яростное драконье пламя превратило корабли в горящие остовы, севшие на мель вдоль побережья.",al={"who sank the ships","how did they sink","what destroyed the fleet","кто потопил корабли","как они затонули","что уничтожило флот"}},{q="Почему моряки здесь стали нежитью?",a="Их души остаются привязанными к обломкам проклятием. Первый помощник Фитсиммонс ищет помощи, чтобы выяснить, почему они не могут обрести покой.",al={"why are they ghosts","undead sailors","curse of paleth","почему они призраки","моряки-нежить","проклятие палета"}},{q="Кто-нибудь выжил при гибели флота?",a="Первый помощник Фитсиммонс с «Повелительницы волн» — единственный известный выживший в катастрофе. Он сумел добраться до безопасного места и теперь живет в Гавани Менетилов.",al={"any survivors","did anyone live","fitzsimmons","выжившие","кто-нибудь выжил","фитсиммонс"}},{q="Кто командовал Третьей флотилией?",a="Третьей флотилией командовал Дерек Праудмур, старший сын верховного адмирала Даэлина Праудмура. Дерек погиб на вороньем гнезде своего флагмана, когда драконы охватили флотилию пламенем.",al={"who commanded the fleet","fleet captain","derek proudmoore","кто командовал флотом","капитан флота","дерек праудмур"}}},fp="10,323,30.561.0,19.546.1,23.230.0,31.209.0,32.122.0,48.160.0,37.197.0"}
P.entries["subzone:lost-point"] = {n="Разрушенная башня",s="Разрушенная башня — обветшавшая деревянная сторожевая башня на западе Пылевых топей, изначально построенная силами Терамора как передовой разведывательный пост. Она пришла в упадок и вышла из-под контроля стражи леди Джайны Праудмур, а теперь служит убежищем для дезертиров-изгоев.",h="Разрушенная башня — обветшавшая деревянная сторожевая башня на западе Пылевых топей, изначально построенная...",kw={"balos jacken","dustwallow marsh","lost point","scout tower","theramore deserters","балос хакен","пылевые топи","разрушенная башня","разведывательная башня","дезертиры терамора"},ang={["faction:Alliance"]="Для верных Альянсу Разрушенная башня — горький символ падающей дисциплины в рядах Терамора и логово отступников, хранящих мрачные тайны о военной измене."},sec={{t="Заброшенный форпост",b="Построенная экспедиционными силами Терамора для наблюдения за движением и угрозами из Степей, Разрушенная башня давно пережила свое военное назначение. Застава обветшала от неумолимой сырости топей, дерево гниет, а оборону оставили регулярные войска. Вместо часовых гарнизона башню и ее ближайшие окрестности занимают человеческие дезертиры, ушедшие со службы в Тераморе и нашедшие приют в глухой глуши вдали от дисциплины городских командиров."},{t="Логово дезертиров",b="Дезертиры, засевшие в Разрушенной башне, подчиняются Балосу Хакену, недовольному бывшему солдату, сплотившему этих изгоев. Их присутствие — далеко не просто военное неповиновение. Хакен и его приспешники хранят важные сведения об изменниках в рядах Терамора, включая участие рядового Хендела в опасном заговоре, который тянется до высших кругов Альянса."}},faq={{q="Что такое Разрушенная башня?",a="Разрушенная башня — полуразвалившаяся сторожевая башня, построенная людьми Терамора в западных топях Пылевых топей. Она предназначалась как передовая разведывательная вышка, но военные ее бросили, и ее заняли дезертиры.",al={"lost point overview","what is this tower","about lost point","обзор разрушенной башни","что это за башня","о разрушенной башне"}},{q="Кто сейчас живет в Разрушенной башне?",a="Башню и окружающий лагерь сейчас населяют дезертиры из Терамора. Эти солдаты-отступники нарушили присягу Тераморе и действуют под началом Балоса Хакена.",al={"who is at lost point","lost point enemies","lost point mobs","кто в разрушенной башне","враги разрушенной башни","мобы разрушенной башни"}},{q="Кто такой Балос Хакен?",a="Балос Хакен — главарь дезертиров из Терамора, прячущихся в Разрушенной башне. Несмотря на преступный статус, он обладает важными сведениями о тревожных делах в рядах Терамора.",al={"balos jacken","deserter leader","who leads lost point","балос хакен","главарь дезертиров","кто управляет разрушенной башней"}},{q="Почему Терамор бросил башню?",a="Пылевые топи враждебны, и снабжать их трудно. Когда боевой дух гарнизона упал, а дисциплина ослабла, изолированная застава пришла в упадок и стала идеальным убежищем для солдат, желающих уклониться от службы, не бежав на территорию Орды.",al={"why abandoned","why is lost point ruined","why run down","почему заброшена","почему разрушенная башня в руинах","почему обветшала"}}},fp="10,298,18.537.0,16.431.1,19.221.0,34.198.0,20.194.1,36.246.0"}
P.entries["subzone:lost-rigger-cove"] = {n="Бухта Сорванных Парусов",s="Бухта Сорванных Парусов, укрытая у восточных утесов Танариса, служит главной базой пиратов Южных морей в этом районе. Защищенная с трех сторон высокими пустынными горами, эта скрытая гавань располагает причалами, укрепленными лагерями и действующей верфью, где строят новые пиратские суда.",h="Бухта Сорванных Парусов, укрытая у восточных утесов Танариса, служит главной базой пиратов Южных морей в этом...",kw={"freebooter","gadgetzan","lost rigger cove","shipyard","southsea pirates","tanaris","флибустьеры","прибамбасск","бухта сорванных парусов","верфь","пираты южных морей","танарис"},ang={["class:Rogue"]="Раскинувшийся пиратский лагерь полон карманов для обчистки, личных сундуков и головорезов, знающих все грязные приемы морского разбоя.",["race:Gnome"]="Для гномов-изобретателей пиратский сухой док — грубая, но показательная демонстрация трофейных механизмов и краденых деталей и постоянная угроза каждому торговому судну южных морей."},sec={{t="Пираты и горные стены",b="Естественно укрепленная отвесными скалами почти со всех сторон, Бухта Сорванных Парусов дает Флибустьерам Южных морей идеальный морской оплот на юго-восточной окраине Калимдора. Здесь пираты-головорезы, портовые рабочие и разбойники таскают добычу и собирают новые корпуса прямо под носом у властей Прибамбасска. Из бухты Южные моря могут проецировать силу через Великое море, совершая набеги на торговые пути между Кабестаном, Пиратской бухтой и прибрежными поселениями."},{t="Соперники на пороге",b="Пираты владеют бухтой не без помех. Гоблины Прибамбасска и соседнего Порта Картеля возмущены налетчиками на своем пороге и платят наемникам, чтобы те убивали пиратов, редили их ряды и срывали их операции."}},faq={{q="Кто управляет Бухтой Сорванных Парусов?",a="Бухтой владеют пираты Южных морей — известный морской синдикат, действующий по всему Калимдору и в Южных морях. Эту естественную гавань они используют для ремонта флота и постройки новых боевых кораблей.",al={"who owns lost rigger cove","who lives in lost rigger cove","lost rigger cove factions","кому принадлежит бухта сорванных парусов","кто живет в бухте сорванных парусов","фракции бухты сорванных парусов"}},{q="Кто сражается здесь с пиратами?",a="Гоблины Прибамбасска и Порта Картеля, недовольные налетчиками на своем пороге, нанимают проезжих искателей приключений, чтобы те наносили удары по пиратскому оплоту и сокращали ряды Южных морей.",al={"gnome goblin camp tanaris","why are gnomes here","why fight the pirates","лагерь гоблинов танарис","почему здесь гномы","зачем сражаться с пиратами"}},{q="Где находится Бухта Сорванных Парусов?",a="Она лежит на восточном побережье Танариса, к юго-востоку от Прибамбасска. В нее ведет извилистая тропа по каньону, прорезающему прибрежную горную преграду.",al={"where is lost rigger cove","how to get to lost rigger cove","lost rigger cove map","где бухта сорванных парусов","как добраться до бухты сорванных парусов","карта бухты сорванных парусов"}},{q="Что пираты строят в бухте?",a="Пираты Южных морей держат в центре бухты действующий сухой док и верфь, где плотники и разбойники заняты сборкой корпуса большого океанского боевого корабля.",al={"shipyard lost rigger cove","pirate boat construction","верфь бухта сорванных парусов","постройка пиратского корабля"}}},fp="16,310,26.461.0,22.235.0,30.201.0,33.178.0,34.154.0,42.180.0"}
P.entries["subzone:lushwater-oasis"] = {n="Цветущий оазис",s="Цветущий оазис — один из трех животворных водоемов в засушливых Степях, расположенный к югу от Перекрестка. Несмотря на пышный вид, оазис полон опасностей: он кишит агрессивными кентаврами из племени Колкар и скрывает вход в Пещеры Стенаний. Его оскверненные воды хорошо известны рыболовам, ищущим необычную загадочную рыбу.",h="Цветущий оазис — один из трех животворных водоемов в засушливых Степях, расположенный к югу от Перекрестка.",kw={"crossroads","deviate fish","kolkar","lushwater oasis","the barrens","wailing caverns","перекресток","загадочная рыба","колкар","цветущий оазис","степи","пещеры стенаний"},ang={["class:Druid"]="В Цветущем оазисе наблюдается тревожный неестественный рост растительности, вызванный искаженными энергиями, вырывающимися из соседних Пещер Стенаний.",["profession:Cooking"]="Эти пруды — одни из немногих водоемов, где рыболовы могут выловить загадочную рыбу — ценный по всему Калимдору ингредиент для приготовления вкусных загадочных блюд."},sec={{t="Ненадежное убежище",b="Цветущий оазис, лежащий в недолгом переходе к югу от Перекрестка, дарит обманчивую передышку среди выбеленных солнцем просторов Степей. Пальмовые кроны и свежие источники привлекают жаждущих зверей со всей саванны, а кентавры Колкар занимают берега и подстерегают как дичь, так и неосторожных путников. Оазис также служит вратами в Пещеры Стенаний, чьи обширные подземные ходы просачиваются порочной энергией в пруды наверху, порождая неестественных существ и причудливые мутации."}},faq={{q="Где находится вход в Пещеры Стенаний?",a="Вход в систему пещер Пещер Стенаний вырублен в природных скалах, нависающих над восточной стороной Цветущего оазиса.",al={"where is wc","wc cave entrance","wailing caverns entrance","где пс","вход в пещеры","вход в пещеры стенаний"}},{q="Кто контролирует Цветущий оазис?",a="Кентавры Колкар господствуют по всему оазису: они используют густую растительность, чтобы охотиться на проходящих зверей и нападать на путников, идущих от Перекрестка.",al={"who lives at lushwater oasis","lushwater enemies","centaur at the oasis","кто живет в цветущем оазисе","враги цветущего оазиса","кентавры в оазисе"}},{q="Почему здешняя рыба странная?",a="Глубинные энергии, просачивающиеся из Пещер Стенаний, осквернили водоемы оазиса, из-за чего местная рыба мутирует в необычную загадочную рыбу.",al={"deviate fish location","why deviate fish","mutated fish oasis","где найти загадочную рыбу","почему загадочная рыба","мутировавшая рыба в оазисе"}},{q="Проходила ли здесь Орда Тралла?",a="Во время Долгого марша орков через Степи вместе с таурен Тралл вел своих воинов через разбросанные по региону оазисы, чтобы обеспечить их питьевой водой, отбиваясь от непрестанных засад кентавров.",al={"thrall long march oasis","orcs in barrens oasis","долгий марш тралла оазис","орки в оазисе степей"}}},fp="15,364,22.501.0,53.138.0,29.174.0,30.153.0,39.206.0"}
P.entries["subzone:maclure-vineyards"] = {n="Виноградники Маклура",s="Виноградники Маклура — обширное сельскохозяйственное поместье на юге Элвиннского леса, принадлежащее семье Маклюров. Оно известно виноградом и вином для королевства Штормград, но не менее печально известно затяжной ожесточенной враждой с соседней семьей Стоунфилдов.",h="Виноградники Маклура — обширное сельскохозяйственное поместье на юге Элвиннского леса, принадлежащее семье...",kw={"boars","elwynn","gerard","maclure","maybell","stonefield","vineyard","wine","кабаны","элвинн","джерард","маклюр","мейбелл","стоунфилд","виноградник","вино"},ang={["faction:Alliance"]="Поместье служит важной житницей и виноградником, снабжающим соседние поселения Златоземье и Штормград продовольствием и спиртным.",["race:Human"]="Для людей Штормграда вражда на виноградниках — классический пример деревенского упрямства: она напоминает путникам, что даже в сердце королевства соседи грызутся из-за заборов, пока над ними нависают большие опасности."},sec={{t="Горький урожай",b="Виноградники Маклура, укрывшиеся в зеленых холмах юга Элвиннского леса, должны были бы стать мирным оплотом виноделия и земледелия. Но повседневный труд омрачен жестоким давним соперничеством со Стоунфилдами, живущими неподалеку. Обвинения в воровстве и застарелая злоба глубоко засели между семьями, и страсти не утихают, даже когда общие беды — голодные бродячие кабаны и наступающие кобольды — угрожают обоим хозяйствам."},{t="Запретная любовь",b="Несмотря на яростную вражду двух глав семейств, юная любовь преодолела границы. Мейбелл Маклюр и Томми Джо Стоунфилд тайно влюбились и встречаются в укромных рощах вдали от подозрительных глаз родителей. Те, кто проходит через виноградники, нередко оказываются втянуты в доставку тайных посланий, улаживание мелких обид и попытки помочь юной паре выйти из тени семейной вражды."}},faq={{q="Почему Маклюры и Стоунфилды враждуют?",a="Это давняя деревенская вражда, выросшая из многолетнего недоверия, мелких обвинений и упрямой гордости. Ни одна семья ни на йоту не доверяет другой: они винят друг друга в пропаже товаров и скота, хотя явных доказательств злого умысла нет ни у одной из сторон.",al={"maclure stonefield feud","why do they hate each other","family feud","вражда маклюров и стоунфилдов","почему они ненавидят друг друга","семейная вражда"}},{q="Кто такая Мейбелл Маклюр?",a="Мейбелл — дочь семьи Маклюров. Она тайно влюбилась в Томми Джо Стоунфилда, не считаясь с горькой ненавистью своей семьи к соседям, и надеется найти способ быть вместе с ним.",al={"maybell","maclure daughter","мейбелл","дочь маклюров"}},{q="Какие угрозы есть у виноградников?",a="Помимо семейных споров, виноградники страдают от прожорливых диких кабанов, вытаптывающих посевы и лозы, а также от бродячих кобольдов, совершающих набеги на ближние поля из окрестных золотых копей.",al={"vineyard dangers","boars at maclure","опасности виноградников","кабаны у маклюров"}},{q="Что производят здесь Маклюры?",a="Семья Маклюров выращивает виноград, поставляя вино и свежие фрукты трактирщикам и торговцам по всему Элвиннскому лесу и Штормграду.",al={"what grows here","maclure crops","что здесь растет","урожай маклюров"}}},fp="17,281,16.441.0,19.440.1,46.246.0,23.216.0,35.187.0,34.148.0"}
P.entries["subzone:maestra-s-post"] = {n="Застава Мейстры",s="Застава Мейстры — небольшое поселение Альянса на западе Ясеневого леса, расположенное у дороги к северо-западу от Астранаара и к югу от Руин Ордил'Арана. Ее охраняют Часовые из числа ночных эльфов, а присутствие людей в древнем лесу Калимдора здесь редкость; застава служит передовым дозором против надвигающихся угроз.",h="Застава Мейстры — небольшое поселение Альянса на западе Ясеневого леса, расположенное у дороги к...",kw={"ashenvale","delgren the purifier","feero ironhand","maestra's post","maestras post","ordil'aran","sentinels","ясеневый лес","делгрен очиститель","фиро железнорук","застава мейстры","ордил'аран","часовые"},ang={["faction:Alliance"]="Для путников Альянса, покидающих безопасные Темные берега, эта застава — первый дружелюбный прием и укрепленное убежище в спорных чащах Ясеневого леса.",["race:NightElf"]="Застава демонстрирует зарождающееся партнерство нового Альянса: Часовые делят очаг и дозор с молодыми расами Восточных королевств."},sec={{t="Передовой дозор",b="Застава Мейстры, раскинувшаяся под сенью западного Ясеневого леса, состоит из узкой башни ночных эльфов и открытого домика. Она служит важным пунктом для путников между побережьем Темных берегов и крупным центром Астранаар. Несмотря на безмятежную эльфийскую архитектуру, застава постоянно настороже. Местные Часовые зорко следят за окрестными дебрями, где шевелятся оскверненные фурболги, а близкие передвижения Орды постоянно угрожают линиям снабжения Альянса."},{t="Сбор Альянса",b="В отличие от многих замкнутых поселений ночных эльфов в глубине лесов, Застава Мейстры примечательна тем, что здесь живет горстка союзников-людей. Такие личности, как Фиро Железнорук и Делгрен Очиститель, живут бок о бок с Часовыми, отдавая свою воинскую силу и преданность священному Свету на службу всему Альянсу. Благодаря им этот отдаленный лагерь стал одним из первых мест встречи между Восточными королевствами и древними защитниками Калимдора."}},faq={{q="Где находится Застава Мейстры?",a="Она находится на западе Ясеневого леса, у дороги к северо-западу от Астранаара и чуть южнее Руин Ордил'Арана.",al={"maestra's post location","where is maestras post","find maestras post","где застава мейстры","расположение заставы мейстры","найти заставу мейстры"}},{q="Кто такая Мейстра?",a="Застава названа в честь лунной жрицы Мейстры, почитаемой ночной эльфийки, хотя сама жрица сейчас на заставе не присутствует.",al={"who is maestra","moon priestess maestra","who was maestra","кто такая мейстра","лунная жрица мейстра","кем была мейстра"}},{q="Почему на эльфийском форпосте есть люди?",a="После Третьей войны и вступления ночных эльфов в Альянс путники и воины, такие как Фиро Железнорук и Делгрен Очиститель, отправились в Калимдор, чтобы предложить помощь и укрепить связи с союзниками — ночными эльфами.",al={"why are humans in ashenvale","feero ironhand why here","delgren the purifier why here","почему люди в ясеневом лесу","почему здесь фиро железнорук","почему здесь делгрен очиститель"}},{q="Какие угрозы есть у Заставы Мейстры?",a="Заставе приходится бороться с кланами оскверненных фурболгов, скрывающимися в окрестных лесах, а также с разведывательными отрядами и вторжениями соседних сил Орды, продвигающихся в Ясеневый лес.",al={"who attacks maestras post","dangers at maestras post","кто нападает на заставу мейстры","опасности у заставы мейстры"}}},fp="14,306,15.496.0,21.462.0,32.125.0,16.155.0,41.223.0,33.186.0"}
P.entries["subzone:mage-quarter"] = {n="Квартал магов",s="Квартал магов — магическое сердце Штормграда, расположенное за каналами в юго-западном углу столицы. Над его мощеными улицами и необычными лавками возвышается Святилище волшебника, где заклинатели королевства оттачивают мастерство. Под ученой поверхностью района скрываются и темные закоулки, где обитают приверженцы куда более мрачных искусств.",h="Квартал магов — магическое сердце Штормграда, расположенное за каналами в юго-западном углу столицы.",kw={"arcane","blue recluse","canals","mage quarter","slaughtered lamb","stormwind","wizard's sanctum","тайная магия","синий отшельник","каналы","квартал магов","забитый ягненок","штормград","святилище волшебника"},ang={["class:Mage"]="Этот район — ваш главный дом в Штормграде: в Святилище волшебника есть мастера-наставники и реагенты для заклинаний.",["class:Warlock"]="Под публичным обликом таверны «Забитый ягненок» скрыт тайный ковен, где последователи темных искусств собираются, чтобы обучаться и втайне призывать приспешников."},sec={{t="Святилище тайной магии",b="Квартал магов, до которого можно добраться по мостам через каналы от Соборной площади или Торгового квартала, целиком обслуживает мистические нужды Альянса. Вокруг шпиля Святилища волшебника собираются люди и союзные заклинатели, изучающие плетение тайной магии и обучающие учеников. Окрестные улицы полны торговцев тканями для портняжного дела, реагентами, алхимическими припасами и зачарованными посохами; это замкнутый район, посвященный исследованиям и защите королевства."},{t="Тайны под поверхностью",b="Не вся магия, практикуемая в квартале, одобрена верховными чародеями королевства. Если такие заведения, как «Синий отшельник», дарят ученым тихое убежище, то печально известная таверна «Забитый ягненок» скрывает тайный ковен чернокнижников в подземных склепах. Там, вдали от городской стражи и священных глаз Соборной площади, демонологи изучают запретные обряды Скверны и подчиняют потусторонние сущности, прячась за общей терпимостью района к мистическим аномалиям."}},faq={{q="Что такое Святилище волшебника?",a="Святилище волшебника — заметная башня, господствующая над Кварталом магов. Это главная академия, библиотека и учебная площадка магов Штормграда; здесь живут ученые, мистические наставники и защитные заклинатели, которым поручена охрана столицы.",al={"mage tower","wizards sanctum","mage sanctum stormwind","башня магов","святилище волшебника","святилище магов штормград"}},{q="Где в Квартале магов могут учиться чернокнижники?",a="Чернокнижники тайно собираются под «Забитым ягненком» — неприметной таверной в квартале. В ее склепах и тайных подвалах последователи магии Скверны могут изучать темные ритуалы, призывать демонов и учиться вдали от надзора городской стражи.",al={"warlock trainer location","slaughtered lamb basement","stormwind warlock trainers","учитель чернокнижников","подвал забитого ягненка","учителя чернокнижников штормград"}},{q="Какие лавки есть в Квартале магов?",a="Район полон специализированных лавок для заклинателей и ремесленников. Здесь есть портняжные мастерские, такие как «Ткани Дункана» и «Одежда Ларсона», торговцы алхимическими товарами и травами, зачарователи, поставщики пиротехники и торговцы посохами.",al={"mage quarter vendors","what shops are here","stores in mage quarter","торговцы квартала магов","какие здесь лавки","магазины квартала магов"}},{q="Как добраться до Квартала магов?",a="Квартал магов занимает юго-западный угол Штормграда. Попасть в него можно напрямую, пройдя по мостам через каналы от Торгового квартала или Соборной площади.",al={"where is mage quarter","how to get to mage quarter","directions to mage quarter","где квартал магов","как добраться до квартала магов","дорога до квартала магов"}}},fp="12,378,21.510.0,27.491.1,29.257.0,45.246.0,43.254.0,34.193.0"}
P.entries["subzone:magic-quarter"] = {n="Магический квартал",s="Магический квартал — северо-восточный район Подгорода, центр изучения тайной магии и темного чародейства Отрекшихся. В квартале, над которым возвышается зловещий Храм Проклятых, обитают практики как тайных, так и магии Скверны.",h="Магический квартал — северо-восточный район Подгорода, центр изучения тайной магии и темного чародейства...",kw={"forsaken","mage","magic quarter","portal trainer","tailoring","temple of the damned","undercity","warlock","отрекшиеся","маг","магический квартал","учитель порталов","портняжное дело","храм проклятых","подгород","чернокнижник"},ang={["class:Mage"]="Магический квартал — сердце чародейства Отрекшихся: здесь обучают тайным искусствам и сетям телепортации, связывающим Подгород с остальной Ордой.",["class:Warlock"]="В темных нишах Храма Проклятых чернокнижники призывают демонических прислужников и оттачивают магию Тьмы вдали от осуждающих глаз Альянса."},sec={{t="Средоточие темных искусств",b="Магический квартал занимает северо-восточную четверть подземного города. Здесь Отрекшиеся хранят свое тайное наследие и погружаются в более темные методики. Центр района — возвышающийся Храм Проклятых, архитектурная реликвия, построенная Плетью и перепрофилированная свободной нежитью. Под его сводчатыми сумрачными потолками маги тонко управляют магическими энергиями, а чернокнижники общаются с демонами, что делает квартал средоточием интеллектуальной мощи и оккультных исследований в Лордероне."},{t="Ученые, ткачи и призыватели",b="Помимо изучения чистой магии вызова и призыва, Магический квартал служит важным общественным центром для заклинателей. Учителя порталов поддерживают сообщение между землями Орды, а мастера-портные работают с напитанными магией тканями, создавая робы и покровы. В отличие от Даларана, где строго разделены академическое волшебство и запретная магия, Отрекшиеся открыто сочетают в этих залах тягу к тайному знанию и силу Скверны, чтобы закрепиться среди множества врагов."}},faq={{q="Для чего нужен Магический квартал?",a="Магический квартал — центр изучения тайной магии и магии демонов у Отрекшихся. Здесь находятся учителя классов для магов и чернокнижников, мастера порталов, соединяющих с другими городами, и портные, ткущие зачарованную ткань.",al={"what is magic quarter","magic quarter purpose","undercity magic district","что такое магический квартал","назначение магического квартала","магический район подгорода"}},{q="Почему в Подгороде есть Храм Проклятых?",a="Когда Плеть вырыла Подгород под руинами Столицы, она возвела такие сооружения, как Храм Проклятых. Когда Сильвана и ее свободные Отрекшиеся захватили подземный комплекс, они заняли эти готовые здания и приспособили их для своих заклинателей.",al={"temple of the damned undercity","why temple of the damned here","scourge building undercity","храм проклятых подгород","почему здесь храм проклятых","постройка плети в подгороде"}},{q="Кого можно обучить в Магическом квартале?",a="Учителя магов, чернокнижников и повелителей демонов обучают практиков в квартале, а мастера порталов и портные дают обучение перемещению и ремеслу.",al={"trainers in magic quarter","who trains here","magic quarter classes","учителя в магическом квартале","кто здесь обучает","классы магического квартала"}},{q="Где находится Магический квартал?",a="Он расположен в северо-восточной четверти Подгорода, напротив Апотекариума через центральное кольцо.",al={"where is magic quarter","magic quarter location","find magic quarter","где магический квартал","расположение магического квартала","найти магический квартал"}}},fp="13,245,23.561.0,32.481.0,41.233.0,53.301.0,40.165.0,35.117.0"}
P.entries["subzone:magram-village"] = {n="Деревня Маграм",s="Деревня Маграм — поселение клана кентавров Маграм среди зловонных желтых прудов на юго-востоке Пустошей. Это главная база Маграмов в их беспощадной войне с ненавистными соперниками — Гелкисами.",h="Деревня Маграм — поселение клана кентавров Маграм среди зловонных желтых прудов на юго-востоке Пустошей.",kw={"centaur","desolace","gelkis","magram","magram village","pools","кентавр","пустоши","гелкис","маграм","деревня маграм","пруды"},ang={["race:Tauren"]="Дикость кентавров терзает племена Калимдора на протяжении поколений, поэтому любое поселение этих кочевых грабителей тревожно напоминает о былом кровопролитии."},sec={{t="Оплот в трясине",b="Деревня Маграм раскинулась на островах и берегах вокруг стоячих сернистых прудов на юго-востоке Пустошей. Это грубое поселение из кое-как сколоченных деревянных мостков и шатров из шкур. Кентавры Маграм живут здесь в постоянной бдительности по отношению к соседним кланам. Известные жестокостью и глубокой враждой к южному клану Гелкис, Маграмы терпят чужаков, лишь если те докажут свою ценность, перебив их врагов Гелкисов."}},faq={{q="Кто живет в Деревне Маграм?",a="В деревне живет клан Маграм, один из нескольких враждующих племен кентавров Пустошей. Они живут под грубыми навесами из шкур на островах, соединенных неказистыми мостками.",al={"who is here","magram residents","centaur village","кто здесь живет","жители маграма","деревня кентавров"}},{q="Можно ли войти в Деревню Маграм, не подвергшись нападению?",a="Поначалу кентавры Маграм враждебны ко всем чужакам. Однако путники могут завоевать их доверие, выслеживая и убивая их заклятых врагов — кентавров Гелкис, и тем повысить свою репутацию у клана.",al={"are magram friendly","magram hostile","how to visit magram village","дружелюбны ли маграмы","маграмы враждебны","как посетить деревню маграм"}},{q="Почему пруды вокруг деревни желтые?",a="Пруды в деревне и вокруг нее загрязнены серой и минеральными стоками, типичными для бесплодных земель Пустошей, из-за чего вода стоячая, мутная и отравленная.",al={"yellow water","polluted pools","magram water","желтая вода","загрязненные пруды","вода маграма"}},{q="Почему Маграмы воюют с Гелкисами?",a="Кланы кентавров Пустошей давно славятся кровожадным соперничеством. Кланы Маграм и Гелкис особенно ожесточенно воюют за господство над югом пустынных земель уже многие поколения.",al={"magram vs gelkis","centaur blood feud","centaur war","маграм против гелкис","кровная вражда кентавров","война кентавров"}}},fp="14,232,24.482.0,28.176.0,50.201.0,44.169.0,39.210.0"}
P.entries["subzone:main-hall-northshire"] = {n="Главный зал (Североземье)",s="Главный зал — центральный входной зал Аббатства Североземья в Элвиннском лесу. Это главный перекресток, соединяющий территорию аббатства с его верхней башней, Залом Оружия и Библиотечным крылом. Здесь новоприбывшие люди-герои являются за первыми поручениями на службе Королевства Штормград.",h="Главный зал — центральный входной зал Аббатства Североземья в Элвиннском лесу.",kw={"abbey","elwynn","hall of arms","library wing","main hall","northshire","stormwind","аббатство","элвиннский лес","зал оружия","библиотечное крыло","главный зал","североземье","штормград"},ang={["race:Human"]="Для людей королевства Главный зал Аббатства Североземья знаменует начало пути на службе Штормграду и Свету."},sec={{t="Сердце аббатства",b="Пройдя через величественные арки Аббатства Североземья, посетители попадают прямо в Главный зал. Как центральный узел здания, он направляет прибывающих новобранцев и клириков между разными частями аббатства: воинским Залом Оружия с одной стороны, ученым Библиотечным крылом с другой и лестницей, ведущей в башню аббатства. Тишину зала нарушает непрекращающаяся борьба в долине: офицеры собирают здоровых новичков на защиту границ королевства."}},faq={{q="Для чего нужен Главный зал?",a="Главный зал служит центральным приемным залом и перекрестком Аббатства Североземья. Он направляет новобранцев, священников и посетителей в Зал Оружия, Библиотечное крыло и верхнюю башню аббатства.",al={"what is main hall","northshire main hall use","что такое главный зал","назначение главного зала североземья"}},{q="Кто направляет здесь новобранцев?",a="Офицеры и клирики обороны Штормграда, находящиеся в Главном зале, оценивают прибывающих героев и дают им первые боевые приказы — очистить окрестности аббатства от угроз.",al={"who gives quests here","abbey commander","кто дает задания","командир аббатства"}}},fp="22,334,18.494.0,37.202.0,30.208.0"}
P.entries["subzone:maker-s-terrace"] = {n="Терраса Творца",s="Терраса Творца — обширные открытые раскопки на севере Бесплодных земель, прямо перед входом в древнее хранилище титанов Ульдаман. Путникам, идущим на юг из Лок Модана, приходится пробираться по ее неровной окраине, занятой враждебными дворфами из клана Черного Железа. Раскопки — спорный порог между пустошами на поверхности и тайнами титанов, погребенными внизу.",h="Терраса Творца — обширные открытые раскопки на севере Бесплодных земель, прямо перед входом в древнее...",kw={"badlands","dark iron","excavation","maker's terrace","makers terrace","titans","uldaman","бесплодные земли","черное железо","раскопки","терраса творца","титаны","ульдаман"},ang={["profession:Mining"]="Обширные карьеры и земляные работы, прорезанные в песчаниковых утесах, ясно свидетельствуют об интенсивной добыче руды дворфийскими землекопами.",["race:Dwarf"]="Для дворфов Стальгорна видеть Террасу Творца в руках вероломного клана Черного Железа горько: Ульдаман хранит глубочайшие тайны происхождения дворфов."},sec={{t="Порог хранилища",b="Терраса Творца раскинулась на северных утесах Бесплодных земель и служит внешним плацдармом для подземных залов Ульдамана. Еще до спуска в подземные руины путникам приходится иметь дело с опаленными солнцем земляными работами, лесами и каменными траншеями этих грандиозных раскопок. Она лежит прямо у перевала, ведущего из Лок Модана, и потому первой встречает любого, кто решится отправиться в засушливые пустоши. Терраса кипит жестокой деятельностью: враждующие стороны ищут путь к древним тайнам под скалами."},{t="Оккупация Черного Железа",b="Раскопки твердо удерживает клан Черного Железа, патрулирующий рвы и границы с враждебной бдительностью. Привлеченные запахом реликвий титанов и жаждой подземного господства, эти подземные дворфы неустанно роют склон холма в поисках оружия, записей и земных реликвий, оставленных древними Творцами. Всякий, кто попытается пройти в глубокие залы Ульдамана, не разобравшись с укрепленными дозорными, быстро окажется разгромлен."}},faq={{q="Где находится Терраса Творца?",a="Терраса Творца находится на дальнем севере Бесплодных земель, возле долинного перевала, соединяющего эту зону с Лок Моданом. Она окружает внешний вход в древний комплекс Ульдаман.",al={"maker's terrace location","where is makers terrace","how to find makers terrace","где терраса творца","расположение террасы творца","как найти террасу творца"}},{q="Кто управляет Террасой Творца?",a="Место занято и патрулируется враждебными дворфами из клана Черного Железа, которые ведут активные раскопки и яростно охраняют внешние подступы к Ульдаману от чужаков.",al={"who is at makers terrace","makers terrace enemies","who controls makers terrace","кто на террасе творца","враги террасы творца","кто владеет террасой творца"}},{q="Для чего ведутся раскопки?",a="Дворфы клана Черного Железа раскапывают древний комплекс титанов Ульдаман. Они стремятся добыть реликвии, мощные механизмы и древние тайны титанов, погребенные в подземных хранилищах, прежде чем их заберут соперники.",al={"why are they digging here","makers terrace dig","what are dark irons looking for","почему здесь копают","раскопки террасы творца","что ищет черное железо"}},{q="Является ли Терраса Творца частью Ульдамана?",a="Да, Терраса Творца — внешний открытый раскоп, ведущий прямо в подземелье и пещеры Ульдамана.",al={"is this uldaman","makers terrace vs uldaman","terrace connection to dungeon","это ульдаман","терраса творца и ульдаман","связь террасы с подземельем"}}},fp="15,402,22.586.0,20.471.0,37.203.0,33.169.0,38.225.0,35.127.0"}
P.entries["subzone:malaka-jin"] = {n="Малака'джин",s="Малака'джин — небольшой лагерь Орды в предгорьях Когтистых гор, к югу от Заставы Зловещего Тотема. Его населяют в основном охотники-тролли из племени Черного Копья; поселение служит простой станцией и охотничьим форпостом для путников, поднимающихся в суровые горы из Степей.",h="Малака'джин — небольшой лагерь Орды в предгорьях Когтистых гор, к югу от Заставы Зловещего Тотема.",kw={"darkspear","grimtotem","horde","hunters","malaka'jin","outpost","stonetalon","trolls","черное копье","зловещий тотем","орда","охотники","малака'джин","форпост","когтистые горы","тролли"},ang={["faction:Horde"]="Малака'джин — самый южный рубеж Орды в Когтистых горах, важная станция на тропе между Степями и северными горными оплотами.",["race:Troll"]="Для троллей Черного Копья Малака'джин — гордое свидетельство самостоятельности троллей и их искусства выслеживания: они обустроили дом в суровых высотах вдали от тропических берегов Калимдора."},sec={{t="Убежище охотников",b="Малака'джин, укрытый возле главной тропы в Когтистые горы, — желанное убежище для странников Орды, отправляющихся в спорные высоты. В деревне живет отряд суровых троллей-охотников, добывающих пропитание на утесах и в зарослях. Живя скромно, эти охотники предлагают припасы, обменивают свежую дичь усталым путникам и настороженно следят за враждебными горными животными и воинственными тауренами Зловещего Тотема, скрывающимися выше по тропам."},{t="Опора в горах",b="Малака'джин, шатко стоящий у границы Степей, — одно из первых мест, где Орда закрепилась в Когтистых горах. Хотя он мал и тих по сравнению с большой крепостью Приют у Солнечного Камня дальше на севере, он служит важной опорной базой: следопыты Орды наблюдают за племенными волнениями и защищают извилистые дороги от наступающих угроз."}},faq={{q="Что такое Малака'джин?",a="Малака'джин — небольшая деревня и форпост Орды на юге Когтистых гор. Его населяет община троллей-охотников из племени Черного Копья, дающая кров, торговлю и припасы путникам, поднимающимся из Степей.",al={"where is malakajin","what is this place","malakajin stonetalon","где малака'джин","что это за место","малака'джин когтистые горы"}},{q="Кто живет в Малака'джине?",a="Поселение почти целиком населено троллями-охотниками. Они живут охотой на горную дичь и торгуют мясом и кожей с проходящими путниками.",al={"malakajin npcs","who is here","trolls in stonetalon","персонажи малака'джина","кто здесь живет","тролли в когтистых горах"}},{q="Какие угрозы нависают над лагерем?",a="Помимо свирепых горных хищников, деревня расположена прямо к югу от враждебной Заставы Зловещего Тотема, и небольшой лагерь троллей постоянно настороже перед агрессией враждебного племени тауренов.",al={"malakajin enemies","who attacks malakajin","враги малака'джина","кто нападает на малака'джин"}},{q="Есть ли здесь распорядитель полетов?",a="Нет. В это время в Малака'джине нет распорядителя полетов. Путникам в Когтистых горах приходится пользоваться распорядителем полетов в Приюте у Солнечного Камня дальше на северо-запад или идти по дороге пешком.",al={"malakajin flight path","fly to malakajin","полеты малака'джин","долететь до малака'джина"}}},fp="10,305,17.479.0,25.373.0,19.227.0,24.169.0,27.211.0,30.203.0"}
P.entries["subzone:malden-s-orchard"] = {n="Сад Мальдена",s="Сад Мальдена — разрушенная ферма на севере Серебряного бора, названная по имени хозяина-человека, который бежал во время вторжения Плети в Лордерон. Давно заброшенный сад зарос темными вечнозелеными деревьями, а по его территории рыщут свирепые черные воргены-волки. Развалившийся домик сада стал временным убежищем для отрезанного от своего отряда разведчика Отрекшихся.",h="Сад Мальдена — разрушенная ферма на севере Серебряного бора, названная по имени хозяина-человека, который...",kw={"cottage","erland mckree","ivar patch","malden","malden's orchard","maldens orchard","silverpine","worgs","домик","эрланд маккри","делянка ивара","мальден","сад мальдена","серебряный бор","ворги"},ang={["faction:Horde"]="Путникам, идущим на юг от Гробницы или от границы Тирисфаля, следует осторожно обходить сад из-за агрессивных стай воргенов-волков, поселившихся на ферме.",["race:Undead"]="Для Отрекшихся сад напоминает о гибели людей и является спорным участком севера Серебряного бора, который разведчики Стражей смерти должны защищать от диких зверей."},sec={{t="Зараженный урожай",b="До Третьей войны эта усадьба снабжала свежими фруктами города Лордерона; за ней ухаживал фермер по имени Мальден. Когда Плеть прошла по королевству, Мальден бросил свою землю и бежал от чумы. С тех пор сад задыхается в темных наступающих туманах Серебряного бора. Вечнозеленые деревья не подрезаны, а плоды гниют несобранными на зараженных ветвях, и участок полностью отвоевали дикие хищники."},{t="В ловушке в домике",b="Заросший сад стал охотничьими угодьями территориальных черных воргенов-волков, и пройти здесь по северу Серебряного бора опасно. Во время разведывательного задания для Стражей смерти разведчик Эрланд Маккри был послан осмотреть местность, но оказался в окружении зверей. Несколько дней он пролежал взаперти в полуразрушенном домике Мальдена и дожил лишь до того, как подкрепление Отрекшихся прорвалось сквозь стаю и проводило его обратно к товарищам-разведчикам в Делянке Ивара."}},faq={{q="Кто такой Мальден?",a="Мальден был фермером-человеком, жившим здесь до падения Лордерона. Он бросил сад и бежал, спасая жизнь, когда Плеть вторглась в королевство во время Третьей войны.",al={"malden lore","who owned the orchard","who is malden","мальден","кто владел садом","кто такой мальден"}},{q="Почему в саду полно воргенов-волков?",a="Когда не осталось живых хозяев, способных защитить ферму, дикие черные воргены-волки, бродившие по Серебряному бору, сделали густую рощу и заброшенный двор территорией своей стаи.",al={"why are there worgs here","malden orchard dogs","worg infestation","почему здесь ворги","сад мальдена собаки","нашествие воргов"}},{q="Кто заперт в домике?",a="В домике заперт страж смерти Эрланд Маккри. Посланный Отрекшимися в разведку, он попал в засаду воргенов-волков сада и отсиживался внутри, пока не пришла помощь.",al={"cottage scout","who is in the house","deathstalker in the cabin","разведчик в домике","кто в доме","страж смерти в хижине"}},{q="Собирает ли кто-нибудь теперь фрукты в этом саду?",a="Нет. За темными деревьями не ухаживали годами, и их плоды гниют на ветвях среди порчи, расползающейся по Серебряному бору.",al={"is the fruit edible","malden's orchard harvest","can you pick fruit","съедобны ли фрукты","урожай сада мальдена","можно ли собирать фрукты"}}},fp="16,362,18.448.0,22.486.1,15.174.0,33.159.0,34.186.0,48.140.0"}
P.entries["subzone:mannoroc-coven"] = {n="Поле Маннорок",s="Поле Маннорок — населенные демонами руины на юге Пустошей, названные в честь властителя преисподней Маннорота. Оно раскинулось среди древней архитектуры ночных эльфов и является крупнейшим оплотом Пылающего Легиона в центральном Калимдоре. Культисты Пылающего Клинка держат здесь действующие порталы призыва, наполняя окутанную пеплом землю гончими Скверны, суккубами и инфернальными демонами.",h="Поле Маннорок — населенные демонами руины на юге Пустошей, названные в честь властителя преисподней Маннорота.",kw={"azrethoc","burning blade","coven","desolace","felhounds","infernals","jugkar grim'rod","mannoroc","азретох","пылающий клинок","лагерь","пустоши","гончие скверны","инфернальные демоны","джугкар грим'род","маннорок"},ang={["class:Warlock"]="Сосредоточенная энергия Скверны и действующие разрывы призыва Легиона делают лагерь предметом пристального тактического интереса: здесь можно напрямую наблюдать проявление демонической силы в чистом виде.",["race:NightElf"]="Видеть, как каменную кладку ваших древних предков оскверняют и топчут демоны-захватчики, мучительно: Поле Маннорок напоминает о Войне Древних."},sec={{t="Оплот Пламени Скверны",b="Поле Маннорок лежит к югу от Заставы Скитающихся Духов и к востоку от Деревни Ночных Охотников и покрывает древние руины ночных эльфов гнетущей пеленой скверны. Здесь командует лорд Азретох вместе с чернокнижником Пылающего Клинка Джугкаром Грим'родом. Вместе они используют действующие порталы призыва, чтобы перебрасывать в Калимдор демонические подкрепления, в том числе стражей рока, инфернальных демонов и гончих Скверны. Даже когда путники, союзные Орде, пытаются разорвать эти связи с помощью реликвий вроде Руки Ируксоса, в израненной земле открываются новые разрывы."}},faq={{q="Почему это место называется Поле Маннорок?",a="Лагерь назван в честь Маннорота Разрушителя, печально известного властителя преисподней, который подчинил орков через проклятие крови и погиб в Ясеневом лесу.",al={"who is mannoroc","mannoroc name origin","why named mannoroc","кто такой маннорок","происхождение названия маннорок","почему назван маннорок"}},{q="Кто правит на этом поле?",a="Демонические силы здесь возглавляет демон лорд Азретох. Делами смертных управляет Джугкар Грим'род, чернокнижник, представляющий культ Пылающего Клинка.",al={"who leads mannoroc coven","mannoroc coven boss","azrethoc","кто главный на поле маннорок","босс поля маннорок","азретох"}},{q="На каких руинах построен этот лагерь?",a="Демонический лагерь занимает рассыпающиеся каменные основания древнего поселения ночных эльфов, лежавшего в руинах задолго до того, как демоны затопили область магией Скверны.",al={"what ruins are here","mannoroc ancient ruins","elf ruins desolace","какие здесь руины","древние руины маннорок","руины эльфов пустоши"}},{q="Как демоны попадают в Пустоши?",a="Культисты Пылающего Клинка поддерживают магические порталы призыва среди руин. Через них непрерывно прибывают подкрепления прямо из Круговерти Пустоты, что сводит на нет попытки посторонних навсегда очистить это место.",al={"where do demons come from","burning blade portals desolace","откуда берутся демоны","порталы пылающего клинка пустоши"}}},fp="14,360,21.572.0,40.165.0,25.152.0,36.169.0,40.217.0"}
P.entries["subzone:manor-mistmantle"] = {n="Поместье Мистмантла",s="Поместье Мистмантла — разрушающаяся усадьба в темных холмах северо-востока Сумеречного леса, к северу от Темнолесья. Когда-то это был достойный семейный дом, но он обратился в руины и ужас, кишащие немертвыми вурдалаками, подчиненными его печально известному хозяину.",h="Поместье Мистмантла — разрушающаяся усадьба в темных холмах северо-востока Сумеречного леса, к северу от...",kw={"beggar's haunt","darkshire","duskwood","ghouls","manor mistmantle","stalvan","stalvan mistmantle","tear of tilloa","приют бродяги","темнолесье","сумеречный лес","вурдалаки","поместье мистмантла","сталван","сталван мистмантл","слеза тиллоа"},ang={["faction:Alliance"]="Для следователей Альянса, прослеживающих мрачную судьбу жертв из Луноречья и Златоземья, Поместье Мистмантла — трагический конец Легенды о Сталване."},sec={{t="Зараженная усадьба",b="Поместье Мистмантла, расположенное к западу от Приюта Бродяги, стоит как мрачный памятник убийствам и безумию. Территорию заполонило разложение, а по ней бродят свирепые вурдалаки, защищающие разрушенное строение. Среди гнили и увядшей растительности единственный признак живой красоты на всем участке — одинокий печальный цветок в заброшенном саду: цветок, известный как Слеза Тиллоа."},{t="Хозяин поместья",b="Поместье принадлежит Сталвану Мистмантлу, бывшему школьному учителю и домашнему наставнику, чьи ужасающие злодеяния в Луноречье и Златоземье стали темной легендой всего королевства. Теперь Сталван — приспешник нежити; он таится на верхнем этаже родового дома среди останков своих убитых жертв, и его охраняют бредущие чудовища. Путники и следователи из Темнолесья часто обнаруживают, что след самого печально известного призрака Сумеречного леса приводит в это залитое кровью поместье."}},faq={{q="Где находится Поместье Мистмантла?",a="Поместье Мистмантла лежит на северо-востоке Сумеречного леса, прямо к северу от Темнолесья и чуть западнее Приюта Бродяги.",al={"manor mistmantle location","where is mistmantle manor","how to find manor mistmantle","где поместье мистмантла","как найти поместье мистмантла","расположение поместья мистмантла"}},{q="Кто живет в Поместье Мистмантла?",a="Поместье принадлежит Сталвану Мистмантлу, бывшему наставнику, который теперь существует как немертвое создание в окружении вурдалаков.",al={"who is in mistmantle manor","manor mistmantle boss","stalvan house","кто в поместье мистмантла","босс поместья мистмантла","дом сталвана"}},{q="Что такое Слеза Тиллоа?",a="Слеза Тиллоа — одинокий нежный цветок, растущий в саду Поместья Мистмантла и выделяющийся как единственный уцелевший признак живой природы среди разоренной территории.",al={"tear of tilloa flower","mistmantle garden flower","tilloa flower","цветок слеза тиллоа","цветок в саду мистмантла","цветок тиллоа"}},{q="Почему территорию охраняет нежить?",a="Вурдалаки, бродящие по территории поместья, — прислужники Сталвана Мистмантла; они защищают своего хозяина и убивают всякого, кто посмеет вторгнуться в его зараженное имение.",al={"why are ghouls at mistmantle","mistmantle undead","manor mistmantle enemies","почему вурдалаки в мистмантле","нежить мистмантла","враги поместья мистмантла"}}},fp="16,239,20.393.0,24.491.1,34.132.0,30.115.1,27.177.0,42.173.1"}
P.entries["subzone:mardenholde-keep"] = {n="Крепость Марденхольд",s="Крепость Марденхольд — внушительная каменная цитадель, возвышающаяся над Дольным Очагом на севере Западных Чумных земель. Когда-то родовое владение верховного лорда Тириона Фордринга, теперь она служит региональным центром командования фанатичного Алого ордена под управлением его сына, верховного лорда Телана Фордринга.",h="Крепость Марденхольд — внушительная каменная цитадель, возвышающаяся над Дольным Очагом на севере Западных...",kw={"dathrohan","hearthglen","mardenholde","scarlet crusade","silver hand","taelan fordring","tirion fordring","датрохан","дольный очаг","марденхольд","алый орден","серебряная длань","телан фордринг","тирион фордринг"},ang={["class:Paladin"]="Марденхольд — трагическая глава истории паладинов: некогда благородное убежище Серебряной Длани, он стал местом, где орден раскололся на фанатичный Алый орден и бдительный Серебряный Рассвет.",["race:Human"]="Для людей Лордерона Марденхольд — горькое напоминание о том, как гордейшие крепости их родины пережили войны с орками, но пали перед безумием и фанатизмом во время вторжения Плети."},sec={{t="Резиденция Фордрингов",b="Крепость Марденхольд, построенная как административное сердце княжества Дольный Очаг, долго славилась среди жителей Лордерона тем, что ни разу не была взята во время Второй войны. Из ее залов совета верховный лорд Тирион Фордринг управлял окрестными долинами вместе с доверенными советниками и поддерживал мир, пока его не судили и не изгнали за защиту орка Эйтригга. После падения Тириона управление перешло к его честолюбивому ученику Бартиласу, а затем к сыну Тириона, Телану, который унаследовал владения отца накануне гибели Лордерона."},{t="Колыбель ордена",b="Когда Плеть захлестнула Лордерон, Телан открыл Марденхольд для уцелевших командиров Рыцарей Серебряной Длани, среди которых были Александрос Могрейн и Сайдан Датрохан. В этих стенах остатки ордена строили планы сопротивления нежити. Однако внутренняя паранойя и коварное разложение вскоре раскололи их братство. Когда после гибели Могрейна всплыли обвинения в предательстве, Максвелл Тиросус откололся и основал Серебряный Рассвет, а Датрохан и остальные фанатики превратили Дольный Очаг в укрепленный оплот только что созданного Алого ордена."}},faq={{q="Кто сейчас контролирует Крепость Марденхольд?",a="Крепость удерживает Алый орден, и она служит его главным военным командованием в Западных Чумных землях. Ею напрямую управляет верховный лорд Телан Фордринг, живущий в главном зале в окружении элитных защитников Алого ордена.",al={"who leads mardenholde","who is in charge of hearthglen keep","mardenholde boss","кто управляет марденхольдом","кто главный в крепости дольного очага","босс марденхольда"}},{q="Почему эта крепость так важна для Тириона Фордринга?",a="Марденхольд был родовым домом Тириона Фордринга и резиденцией, откуда он правил областью как паладин Альянса. Он растил семью в этих стенах, пока его не лишили титулов и не изгнали за защиту благородного врага.",al={"tirion connection to mardenholde","did tirion live here","связь тириона с марденхольдом","жил ли здесь тирион"}},{q="Как Алый орден захватил Крепость Марденхольд?",a="После изгнания Тириона и падения Лордерона во время Третьей войны сын Тириона Телан предложил крепость как убежище уцелевшим паладинам Серебряной Длани. Под влиянием таких командиров, как Сайдан Датрохан, Телан отдал гарнизон Дольного Очага их радикальному новому ордену.",al={"how did scarlet crusade get hearthglen","why is scarlet crusade here","как алый орден получил дольный очаг","почему здесь алый орден"}},{q="Можно ли безопасно войти в Крепость Марденхольд?",a="Нет. Алый орден считает всех чужаков возможными переносчиками чумы или врагами своего дела. Любой искатель приключений, приблизившийся к крепости, будет атакован без предупреждения, если только не скроется с помощью мощной магии иллюзий.",al={"is mardenholde friendly","can alliance enter mardenholde","can horde enter mardenholde","дружелюбен ли марденхольд","может ли альянс войти в марденхольд","может ли орда войти в марденхольд"}}},fp="16,306,21.581.0,21.597.1,40.234.0,53.235.0,50.266.0,42.225.0"}
P.entries["subzone:marshal-s-refuge"] = {n="Укрытие Маршалла",s="Укрытие Маршалла — ненадежное нейтральное убежище в северных утесах кратера Ун'Горо. Его основали Виллиден Маршал и его экспедиция как запасной оплот после того, как первобытные звери котловины разгромили нижние лагеря.",h="Укрытие Маршалла — ненадежное нейтральное убежище в северных утесах кратера Ун'Горо.",kw={"cave","expedition","hol'anyee","marshal's refuge","un'goro crater","williden marshal","пещера","экспедиция","хол'аньи","укрытие маршалла","кратер ун'горо","виллиден маршал"},ang={["class:Hunter"]="Укрытие, безопасно расположенное над дном кальдеры, дает охотникам возможность изучить самых редких и опасных зверей Ун'Горо, прежде чем спуститься в места выслеживания.",["race:Gnome"]="Гномы-ученые и полевые инженеры считают Укрытие идеальным форпостом для испытаний устройств на причудливых кристаллах силы и неустойчивых гейзерах кратера."},sec={{t="Опасное пристанище",b="Когда Виллиден и Хол'аньи Маршал привели экспедицию в кратер Ун'Горо, они сильно недооценили свирепость его доисторических обитателей. После того как первые лагеря не раз разоряли разъяренные звери, измотанные выжившие взобрались в пещеристые северные утесы, спасаясь от гибели. Заново основанный как Укрытие Маршалла, лагерь цепляется за склон высоко над джунглями и дает усталым исследователям северной части кратера единственное надежное место для отдыха, базовые припасы и распорядителей полетов."},{t="Перекресток любопытных",b="Поскольку в кратере Ун'Горо есть древние биологические чудеса и загадочные кристаллические образования, Укрытие Маршалла привлекает пеструю толпу исследователей, искателей удачи и чудаковатых странников. Натуралисты Альянса и Орды, включая посланников-таурену и гномов-изобретателей, делят тесный уступ с уцелевшими людьми Маршалла. Отсюда разведчики отправляются к вулканическим вершинам вроде Вулкана Огненного Венца или к бурлящим местам вроде Горячих источников Голакка, надеясь описать первобытную глушь, пока она их не поглотила."}},faq={{q="Почему Укрытие Маршалла построено так высоко на утесе?",a="Экспедиция Маршалла сначала разбила лагеря ниже, в котловине, но свирепые динозавры и агрессивные существа Ун'Горо постоянно топтали и громили их. Выжившие отступили вверх по северной скале, чтобы получить оборонимую позицию вне досягаемости крупных зверей.",al={"why is it in a cave","marshals refuge location","why cliffside camp","почему в пещере","где укрытие маршалла","почему лагерь на утесе"}},{q="Дружелюбно ли Укрытие Маршалла и к Орде, и к Альянсу?",a="Да. Это нейтральный форпост. Первобытные опасности кратера Ун'Горо делают вражду фракций непозволительной роскошью, поэтому представители обеих фракций мирно встречаются здесь, чтобы пополнить припасы и обменяться исследованиями.",al={"is marshals refuge neutral","can horde go here","can alliance go here","нейтрально ли укрытие маршалла","может ли орда сюда","может ли альянс сюда"}},{q="Кто руководит лагерем?",a="Форпостом руководят Виллиден Маршал и Хол'аньи Маршал, организаторы обреченных экспедиций Маршалла в кратер.",al={"who is in charge","who runs marshals refuge","camp leader","кто главный","кто управляет укрытием маршалла","глава лагеря"}},{q="Какие услуги доступны в Укрытии?",a="Укрытие дает все необходимое для выживания в отдаленной котловине: распорядителей полетов для обеих фракций, торговцев базовыми товарами, ремонт и место сбора исследователей, предлагающих награды и задания по всему кратеру.",al={"flight path","repairs","vendors","полеты","ремонт","торговцы"}}},fp="16,250,18.523.0,25.535.0,52.295.0,56.206.0,25.138.0,42.248.0"}
P.entries["subzone:marshlands"] = {n="Топи",s="Топи — обширное пропитанное водой болото на юго-востоке кратера Ун'Горо. Оно лежит прямо у подножия извилистого спуска из Танариса, и именно его новички чаще всего видят первым при входе в первобытную котловину.",h="Топи — обширное пропитанное водой болото на юго-востоке кратера Ун'Горо.",kw={"blue power crystals","marshlands","mor'vek","raptors","ravasaur","tanaris","torwa pathfinder","un'goro","синие кристаллы силы","топи","мор'век","ящеры","равазавр","танарис","землепроходец торва","ун'горо"},ang={["class:Hunter"]="Топи сразу становятся испытанием на выживание в дикой природе: здесь водятся быстрые ящеры, ядовитые хищники и редкие звери, которых направляют опытные следопыты вроде Землепроходца Торвы.",["profession:Herbalism"]="Северные края болота заросли агрессивными побегами кровавика и влажной листвой, поэтому это отличное место для наблюдения за враждебными подвижными растениями."},sec={{t="Врата в кратер",b="Спуск по крутой тропе из засушливых просторов Танариса приводит путников прямо во влажную трясину Топей. Любой другой путь вдоль отвесного края кратера грозит смертельным падением, поэтому эта коварная полоса болот — главный вход в Ун'Горо. Густые кроны, стоячая вода и грязь скрывают множество свирепых стай ящеров, в том числе ядовитых, подстерегающих в тростнике. На влажных прогалинах путешественники находят рассыпанные по земле синие кристаллы силы, встречающиеся только в этой части кратера."},{t="Лагеря в трясине",b="Несмотря на постоянную опасность хищников, несколько одиноких знатоков дикой природы держат форпосты в болоте. На заметном земляном холме таурен Землепроходец Торва и его спутник Гарл Грозный Коготь следят за первобытной фауной, преодолев котловину на каноэ. Дальше по болотам тролль Мор'век изучает и обучает местных равазавров."}},faq={{q="Почему Топи обычно — первое, что люди видят в Ун'Горо?",a="Отвесные скалы вокруг кратера Ун'Горо делают вход с любой стороны, кроме юго-восточного прохода в Танарисе, почти наверняка смертельным. Спуск ведет прямо в Топи, и все наземные путники вынуждены идти через их сырые земли.",al={"how to enter ungoro","entering ungoro crater","marshlands entrance","как войти в ун'горо","вход в кратер ун'горо","вход в топи"}},{q="Какие существа здесь встречаются чаще всего?",a="Болото славится плотными популяциями ящеров. Здесь есть и обычные охотничьи ящеры, и смертоносные ядовитые виды, способные одолеть неосторожных исследователей в густых зарослях.",al={"marshlands beasts","marshlands raptors","what lives here","звери топей","ящеры топей","кто здесь живет"}},{q="Какие уникальные ресурсы есть в Топях?",a="Топи — единственное место в кратере Ун'Горо, где естественным образом образуются синие кристаллы силы. Эти светящиеся осколки ценят исследователи, изучающие загадочные кристаллические пилоны, разбросанные по котловине.",al={"blue power crystals","marshlands crystals","blue crystals ungoro","синие кристаллы силы","кристаллы топей","синие кристаллы ун'горо"}},{q="Кто такой Землепроходец Торва?",a="Землепроходец Торва — опытный таурен-охотник, стоящий на высоком холме в Топях вместе с Гарлом Грозным Когтем. Он наблюдает за экологией кратера и направляет умелых искателей приключений против самых свирепых зверей Ун'Горо.",al={"torwa","torwa pathfinder camp","торва","лагерь землепроходца торвы"}},{q="Можно ли приручить или обучить здешних равазавров?",a="Да. Мор'век, тролль, живущий в Топях, специализируется на обращении с местными равазаврами и их выращивании и рассказывает об их агрессивном нраве и инстинктах.",al={"ravasaur trainer","morvek","train ravasaur","учитель равазавров","морвек","обучить равазавра"}}},fp="10,248,21.540.0,22.362.0,67.252.0,36.190.0,50.222.0,24.227.0,43.162.0"}
P.entries["subzone:mast-room"] = {n="Мачтовая",s="Мачтовая — огромный подземный лесопильный цех в глубине Мертвых копей. Под надзором гоблина-надсмотрщика Снида и его резчиков по дереву здесь обрабатывают древесину, вывезенную из Западного Края.",h="Мачтовая — огромный подземный лесопильный цех в глубине Мертвых копей.",kw={"deadmines","goblin woodcarver","lumber mill","mast room","shredder","sneed","мертвые копи","гоблин-резчик","лесопилка","мачтовая","крошшер","снид"},ang={["faction:Alliance"]="Обработка древесины в этой пещере показывает, что грабежи Братства Справедливости в Западном Крае — часть скоординированных промышленных усилий, а не простой разбой.",["profession:Engineering"]="Гоблинский крошшер Снида в этой пещере — чудо грубой паровой техники с шестернями, переделанное из лесозаготовительной машины в орудие против незваных гостей."},sec={{t="Подземная лесопилка",b="За глубокими шахтными туннелями Мертвых копей лежит Мачтовая — огромная пещера, превращенная в действующую лесопилку. Пространство занимают груды срубленных бревен, опилки и мощное режущее оборудование. Здесь гоблины-резчики изготавливают огромные мачты, шпангоуты и доски для сборки большого боевого корабля, спрятанного дальше в Потайной бухте. Под бдительным взором Снида Братство Справедливости превращает добытую в Западном Крае древесину в орудия войны."},{t="Промышленный труд",b="Эта пещера — пример гоблинской промышленности в самом неустанном виде. Снид руководит работой, стоя на механическом крошшере, и следит, чтобы резчики выполняли изнурительные нормы. Огромные бревна беспрерывно поднимают и строгают, превращая бывшую заброшенную золотую шахту в гудящую, закопченную военную верфь."}},faq={{q="Почему в подземной шахте есть лесопилка?",a="Братство Справедливости тайно строит огромный боевой корабль в бухте под шахтами. Мачтовая служит местом сборки и обработки мачт, каркаса и обшивки корабля из древесины, тайно привезенной с поверхности Западного Края.",al={"why timber here","why wood in deadmines","mast room purpose","зачем здесь древесина","зачем дерево в мертвых копях","назначение мачтовой"}},{q="Кто управляет Мачтовой?",a="Пещерой управляет Снид, гоблин-мастер, который руководит гоблинами-резчиками и управляет смертоносной механическим крошшером для бревен.",al={"mast room boss","who leads mast room","who is sneed","босс мачтовой","кто главный в мачтовой","кто такой снид"}},{q="Почему гоблины работают здесь на Братство Справедливости?",a="Эдвин ван Клиф нанял гоблинов-инженеров и мастеров, чтобы получить технические знания, которых не хватало человеческим каменщикам. Гоблины предоставляют тяжелые машины, взрывчатку и навыки корабелов в обмен на золото и прибыль.",al={"why are goblins in deadmines","defias goblins","почему гоблины в мертвых копях","гоблины братства справедливости"}}},fp="9,203,23.487.1,16.324.1,54.252.1,23.146.0,44.217.1"}
P.entries["subzone:master-s-cellar"] = {n="Хозяйский погреб",s="Хозяйский погреб — обширный подземный комплекс под разрушенным поселением к югу от Каражана на Перевале Мертвого Ветра. Когда-то он служил винными погребами и кладовыми поместья Медива, а теперь превратился в населенные призраками руины, где бродят неупокоенные духи бывших слуг и смотрителей.",h="Хозяйский погреб — обширный подземный комплекс под разрушенным поселением к югу от Каражана на Перевале...",kw={"deadwind pass","karazhan","lower cellar","master's cellar","masters cellar","medivh","unliving caretaker","перевал мертвого ветра","каражан","нижний погреб","хозяйский погреб","медив","неживой смотритель"},ang={["class:Mage"]="Призрачные остатки под поместьем Хранителя свидетельствуют о жесточайшей волне тайной магии, высвобожденной при падении Медива, которая превратила обычные кладовые в средоточие остаточной призрачной энергии.",["class:Priest"]="Измученные призраки, запертые в сырых подвалах, — трагические души простых смотрителей и слуг, лишенные покоя тяготеющим над Перевалом Мертвого Ветра проклятием."},sec={{t="Призрачные недра Каражана",b="К югу от величественной башни Каражана лежат разрушенные остатки деревушки, где жили слуги, садовники и работники, содержавшие поместье Медива. Под этими обвалившимися домами находится Хозяйский погреб. В комплекс ведут два отдельных входа в наземных руинах, а сам он уходит глубоко под землю. Одна дверь открывается в обширный сводчатый винный погреб, другая спускается через обрушенную каменную кладку в глубокие природные пещеры. Какая бы темная гибель ни постигла Каражан и его хозяина, она поглотила и этот подвал, оставив неживых смотрителей, стенающих призраков и проклятые души в вечном услужении."},{t="Нижние пещеры",b="Самые глубокие уголки комплекса, называемые Нижним погребом, показывают, где пол погреба провалился в необработанную подземную породу Перевала Мертвого Ветра. Фундамент погреба обрушился в эти пещерные системы, образовав зазубренный лабиринт, где разносятся призрачные стоны. Искатели приключений, исследующие Перевал, редко встречают здесь живых, а разлитая магическая порча от соседней башни крепко привязала эти привидения к камню, так что пещеры так же опасны, как руины наверху."}},faq={{q="Для чего изначально использовался Хозяйский погреб?",a="Он служил главными кладовыми и винными погребами башни Каражан. В деревне наверху жила прислуга и работники, содержавшие обширное хозяйство Хранителя Медива; в подземных хранилищах они держали припасы и выдержанные бочки.",al={"purpose of masters cellar","what is this cellar","why is there a wine cellar here","назначение хозяйского погреба","что это за погреб","почему здесь винный погреб"}},{q="Почему погреб полон призраков?",a="Никто не знает наверняка, что с ними случилось. Какая бы темная судьба ни постигла Каражан и его хозяина, она забрала и деревушку: слуги и жители, жившие там когда-то, теперь бродят по руинам беспокойными тенями, стенающими призраками и неживыми смотрителями.",al={"why are there ghosts","who are the undead in the cellar","why is masters cellar haunted","почему здесь призраки","кто нежить в погребе","почему хозяйский погреб населен призраками"}},{q="Как попасть в пещеры под погребом?",a="Среди разрушенных построек к югу от Каражана есть два отдельных входа в погреб. Восточный ведет в обустроенный винный погреб, а западный спускается в обрушенный участок кладки, откуда можно попасть в природные подземные пещеры Нижнего погреба.",al={"how to get into the lower cellar","masters cellar entrances","where is the cave entrance","как попасть в нижний погреб","входы в хозяйский погреб","где вход в пещеру"}},{q="Соединен ли Хозяйский погреб напрямую с внутренними помещениями Каражана?",a="Нет. Несмотря на близость к основанию башни и историческую роль в снабжении поместья Хранителя, подземные залы не имеют открытого прохода в сам Каражан. Погреб остается замкнутым под руинами деревни.",al={"does masters cellar lead into karazhan","entrance to karazhan from cellar","ведет ли хозяйский погреб в каражан","вход в каражан из погреба"}}},fp="15,302,30.662.0,17.508.0,49.272.0,33.256.0,52.288.0,70.251.0"}
P.entries["subzone:master-s-glaive"] = {n="Меч Властителя",s="Меч Властителя — древняя, тревожная достопримечательность на юго-западе Темных берегов: колоссальное адамантитовое оружие, вонзенное в огромный окаменевший череп. Ночные эльфы издавна почитали это место как священную тайну, а теперь оно кишит сектантами Сумеречного Молота, привлеченными остаточной злобой древней сущности.",h="Меч Властителя — древняя, тревожная достопримечательность на юго-западе Темных берегов: колоссальное...",kw={"darkshore","master's glaive","old god","twilight's hammer","темные берега","меч властителя","древний бог","сумеречный молот"},ang={["race:NightElf"]="Поколениями ночные эльфы считали странный окаменевший памятник священным местом, поэтому недавнее вторжение культа Сумеречного Молота стало для них невыносимым осквернением священной земли Темных берегов."},sec={{t="Памятник древней битве",b="Меч Властителя — огромный адамантитовый клинок, глубоко вонзенный в колоссальный окаменевший череп, — поднимается из земли Темных берегов. Никакие записи не называют ни существо, погибшее здесь, ни руку, вонзившую клинок. Ону, Древо Мудрости, говорит лишь, что на этом месте пал древний-предревний повелитель земли, а ночные эльфы издавна считали, что столь огромное оружие могли держать только титаны. Сегодня пронзенный монолит остается суровым окаменевшим памятником той забытой борьбе."},{t="Темные раскопки",b="Хотя ночные эльфы поколениями относились к этому месту с благоговением, недавно его захватили зловещие силы. Фанатики культа Сумеречного Молота разбили лагерь вокруг погрузившейся в землю туши, прорыли траншеи и обнажили окаменевшие ребра. Привлеченные шепотом под камнем, сектанты одержимо изучают останки и общаются со злобной силой, что все еще таится в древних останках, стремясь воскресить или подчинить себе скверную сущность, дремлющую в земле."}},faq={{q="Что за огромное оружие торчит в черепе?",a="Никто не знает наверняка. Колоссальный адамантитовый клинок — это и есть Меч Властителя, вонзенный в череп в какую-то забытую эпоху. Ночные эльфы считали, что только титаны могли владеть оружием такого размера.",al={"what is the sword","masters glaive sword","who put the sword there","что за меч","меч властителя","кто воткнул меч"}},{q="Чей череп погребен здесь?",a="Его имя утеряно. Ону, Древо Мудрости, говорит лишь, что здесь пал древний-предревний повелитель земли, а Сумеречный Молот считает, что окаменевшие останки принадлежат слуге Древних богов.",al={"what died here","who is buried at masters glaive","что здесь погибло","кто погребен у меча властителя"}},{q="Почему здесь собрался культ Сумеречного Молота?",a="Культ Сумеречного Молота поклоняется Древним богам. Сектанты захватили Меч Властителя, чтобы раскопать окаменевшие останки: их привлекает остаточная темная сила, и они надеются вернуть павшее существо к жизни.",al={"why are cultists here","twilight hammer darkshore","what are cultists digging","почему здесь сектанты","сумеречный молот темные берега","что копают сектанты"}},{q="Кто знает историю этого места?",a="Ону, Древо Мудрости, обитающий на Темных берегах, признает это место обителью покоя древнего повелителя земли и призывает исследователей изучить его.",al={"who studies the glaive","кто изучает меч"}}},fp="15,333,30.490.0,16.506.0,46.219.0,37.192.0,48.207.0,41.160.0"}
P.entries["subzone:maul-subzone"] = {n="Кувалда (подзона)",s="Кувалда — утопленная боевая арена в Разрушенном общинном квартале у руин Забытого Города в Фераласе. Некогда великолепное место древнего эльфийского Эльдре'Таласа, а теперь — неподконтрольная арена кровавых боев, где странники сражаются за славу или выживание со свирепыми зверями и соперниками-чемпионами.",h="Кувалда — утопленная боевая арена в Разрушенном общинном квартале у руин Забытого Города в Фераласе.",ang={["class:Warrior"]="Для воинов, ищущих настоящих сражений вне организованных полей боя, Кувалда предлагает грубые, неприкрашенные кровавые бои, где выживание определяют лишь личное мастерство и прочные доспехи.",["race:NightElf"]="Для ночных эльфов видеть, как величественная архитектура древнего Эльдре'Таласа превратилась в залитую кровью яму для казней, кишащую ограми, — суровое и болезненное напоминание о том, как низко пала цивилизация высокорожденных."},sec={{t="Утопленная яма",b="Высеченная глубоко в камне Разрушенного общинного квартала, Кувалда когда-то служила высокорожденным Эльдре'Таласа театром или церемониальной ареной. После Раскола и последовавшего захвата огров Гордока яма превратилась в грубый колизей. Как и печально известная Арена Гурубаши в далекой Тернистой долине, песок Кувалды отменяет все союзы и бросает бойцов в беззаконную схватку каждый сам за себя, где границы фракций исчезают, а выживание зависит лишь от воинской силы."},{t="Звери и кровопролитие",b="Бойцы, спускающиеся на арену, должны быть осторожны. Смельчаки часто прыгают прямо с высоких уступов квартала, но падение оказывается жестоким. Более безопасная западная арка ведет через туннели, где спят гиены Гордока, и это единственный пеший выход с арены. В неравные промежутки времени на арене появляются опасные звери и известные гладиаторы, и каждый спуск становится непредсказуемым испытанием стали и чутья."}},faq={{q="Почему здесь можно атаковать членов своей фракции?",a="Кувалда служит беззаконной бойцовской ареной, подобно Арене Гурубаши в Тернистой долине. Когда боец ступает на ее песок, обычные договоры и перемирия между фракциями перестают действовать, и бойцы вступают в схватку каждый сам за себя против всех, кто не состоит с ними в одной группе.",al={"ffa pvp dire maul","free for all arena","why can i hit horde","pvp каждый за себя забытый город","арена каждый сам за себя","почему можно бить орду"}},{q="Как безопасно попасть в Кувалду и выйти из нее?",a="Можно спрыгнуть прямо из Разрушенного общинного квартала, но падение нанесет значительный урон. Самый безопасный путь — через дверной проем на западной стороне квартала, по туннелю мимо спящих гиен Гордока. Этот туннель — еще и единственный способ выбраться обратно пешком.",al={"how to get into the maul","maul entrance","exit maul","как попасть в кувалду","вход в кувалду","выход из кувалды"}},{q="Какие враги появляются на арене?",a="Помимо соперников-авантюристов, на арене известны экзотические и свирепые противники, в том числе огромный грибной великан Грибогог, химера Разза и яростный гладиатор Скарр Неукротимый.",al={"arena rares","who spawns in the maul","maul bosses","редкие враги арены","кто появляется в кувалде","боссы кувалды"}},{q="Для чего изначально использовалась эта арена?",a="До Раскола, разрушившего древний Калимдор, этот каменный колизей принадлежал великому городу высокорожденных Эльдре'Таласу. Вторгшиеся огры Гордока приспособили древнюю эльфийскую архитектуру под кровавую арену, отвечающую их диким вкусам.",al={"lore of the maul","who built the maul","eldre'thalas arena","предания кувалды","кто построил кувалду","арена эльдре'таласа"}}},fp="14,297,14.496.0,20.468.0,48.270.0,41.288.0,42.219.0,40.240.0"}
P.entries["subzone:menethil-bay"] = {n="Бухта Менетил",s="Бухта Менетил — защищенный водоем у западного побережья Болотины, расположенный между Гаванью Менетилов и крутыми северными утесами Дун Морога. Она выходит в более широкую Бухту Барадин, и в ее водах обитают агрессивные кроколиски и лежат остовы затонувших кораблей. Это главный морской путь Альянса между Восточными королевствами и Калимдором.",h="Бухта Менетил — защищенный водоем у западного побережья Болотины, расположенный между Гаванью Менетилов и...",kw={"baradin bay","crocolisk","dun morogh","flying osprey","menethil bay","menethil harbor","wetlands","бухта барадин","кроколиск","дун морог","летучий скопа","бухта менетил","гавань менетилов","болотина"},ang={["faction:Alliance"]="Бухта Менетил — жизненно важный морской подход к Гавани Менетилов, оберегающий хрупкий морской путь, который соединяет Стальгорн и Штормград с Калимдором."},sec={{t="Защищенные воды Болотины",b="Бухта Менетил — часть более обширной Бухты Барадин на берегу Великого моря. Она образует естественный залив, граничащий с Гаванью Менетилов на севере, Черной трясиной на востоке и высокими прибрежными обрывами Дун Морога на юге. Мелководье и болотистые берега кишат кроколисками разного возраста и размера, поэтому для путников без проводника мели опасны, хотя бухта — жизненная артерия морских перевозок Альянса. Близ устья бухты лежат разбитые обломки «Летучего скопы» — безмолвное напоминание об опасностях, таящихся под водой."}},faq={{q="Где именно находится Бухта Менетил?",a="Бухта Менетил расположена на западном побережье Болотины. Она лежит в пределах более обширной Бухты Барадин и граничит с Гаванью Менетилов на севере, Черной трясиной на востоке и северными горными обрывами Дун Морога на юге.",al={"where is menethil bay","menethil bay location","wetlands bay","где бухта менетил","расположение бухты менетил","бухта болотины"}},{q="Какие существа живут в Бухте Менетил?",a="Болотистые берега и мелкие заливы бухты густо населены кроколисками разных размеров. Они нападают на неосторожных пловцов, и на них часто охотятся кожевники в поисках ценных шкур.",al={"menethil bay mobs","what is in the bay","crocolisks in menethil bay","существа бухты менетил","что водится в бухте","кроколиски в бухте менетил"}},{q="Что это за затонувший корабль в бухте?",a="Обломки близ входа в Бухту Менетил принадлежат «Летучему скопе» — погибшему судну, лежащему под прибрежными водами у подходов к гавани.",al={"shipwreck menethil bay","flying osprey","sunken ship wetlands","кораблекрушение бухта менетил","летучий скопа","затонувший корабль болотина"}},{q="Почему бухта важна для Альянса?",a="Бухта прикрывает Гавань Менетилов — главные морские врата, связывающие Стальгорн и северные земли Каз Модана с Калимдором и югом. Транспортные корабли, идущие в Терамор и на Темные берега и обратно, должны проходить через эти воды.",al={"importance of menethil bay","alliance port wetlands","menethil harbor water","значение бухты менетил","порт альянса болотина","воды гавани менетилов"}}},fp="12,405,32.571.0,38.247.0,36.200.0,35.161.0,41.241.0"}
P.entries["subzone:menethil-harbor"] = {n="Гавань Менетилов",s="Гавань Менетилов — сильно укрепленный дворфийский портовый город на острове у западного берега Болотины. Она построена на месте старой орочьей верфи и названа в честь короля Теренаса Менетила II. Это главная морская артерия, связывающая Восточные королевства с далекими берегами Калимдора. Город укрыт за массивными каменными стенами и крепкими башнями Крепости Менетил и служит оживленным центром для торговцев, солдат в увольнении и бывалых искателей приключений.",h="Гавань Менетилов — сильно укрепленный дворфийский портовый город на острове у западного берега Болотины.",kw={"auberdine","boat","deepwater","docks","ferry","harbor","menethil","stoutfist","theramore","wetlands","аубердин","корабль","большая вода","причалы","паром","гавань","менетил","крепкий кулак","терамор","болотина"},ang={["faction:Alliance"]="Для любого путника Альянса, отправляющегося на запад, Гавань Менетилов — важнейший плацдарм и единственный морской мост, связывающий Восточные королевства с Тераморем и Калимдором.",["race:Dwarf"]="Хотя порт носит имя человеческого короля, его содержат в основном дворфийской каменной кладкой, а охраняют стражи Стальгорна, удерживающие внешний рубеж Каз Модана."},sec={{t="Порт, рожденный войной",b="Место, где стоит Гавань Менетилов, впервые послужило вождю Оргриму Молоту Рока во время Второй войны, когда Орда строила вторжения армаду из леса и железа, награбленных в Каз Модане. После разгрома орков верховный адмирал Даэлин Праудмур руководил перестройкой стоянки в главную гавань Альянса и назвал ее в память о покойном короле Теренасе Менетиле II из Лордерона. Несмотря на удаленное болотистое расположение, она остается сильно защищенным оплотом: ее укрепляют массивные стены, единственная мощеная дамба и четыре каменные сторожевые башни Крепости Менетил."},{t="Врата через Великое море",b="Сегодня гавань — главный перекресток Альянса. Корабли беспрестанно пересекают океан к Острову Терамор в Пылевых топях и к Аубердину на Темных берегах, перевозя грузы, дипломатов и култирасских морпехов, спускающих жалованье в Таверне «Большая вода». Но мир здесь хрупок: путь снабжения через Дун Альгаз регулярно оспаривает клан Драконьей Пасти, а враждебные налетчики из клана Черного Железа давят на северные топи, и капитан Крепкий Кулак с гарнизоном гавани постоянно начеку."}},faq={{q="Куда плывут корабли из Гавани Менетилов?",a="Суда, отходящие от причалов Гавани Менетилов, пересекают Великое море к континенту Калимдор. Пассажирские корабли регулярно ходят к Острову Терамор в Пылевых топях и на север, в гавань ночных эльфов Аубердин.",al={"menethil harbor boat","where does the boat go","menethil ferries","kalimdor boats","корабль гавани менетилов","куда идет корабль","паромы менетила","корабли в калимдор"}},{q="Кто правит Гаванью Менетилов?",a="Гавань Менетилов — поселение Альянса под властью Стальгорна. Капитан Крепкий Кулак командует городской стражей и руководит обороной гавани из Крепости Менетил, оберегая причалы от болотных тварей, орков-отступников и налетчиков из глубины суши.",al={"who is in charge of menethil","menethil harbor leader","who leads menethil","кто главный в менетиле","глава гавани менетилов","кто управляет менетилом"}},{q="Почему город назван Менетил?",a="Гавань назвал верховный адмирал Даэлин Праудмур после Второй войны в память о короле Теренасе Менетиле II из Лордерона, чье руководство объединило королевства людей, дворфов и эльфов в первоначальный Альянс Лордерона.",al={"why menethil harbor","menethil name origin","who is menethil","почему гавань менетилов","происхождение названия менетил","кто такой менетил"}},{q="Какие угрозы сейчас нависли над гаванью?",a="Гавани постоянно угрожает клан Драконьей Пасти, затаившийся в холмах Болотины: он регулярно пытается перерезать проход через Дун Альгаз, чтобы лишить порт подкреплений. Набеги клана Черного Железа на севере близ Дун Модра и хищные ящеры добавляют гарнизону хлопот.",al={"is menethil harbor in danger","menethil threats","wetlands orcs menethil","в опасности ли гавань менетилов","угрозы менетилу","орки болотины менетил"}}},fp="15,461,22.571.0,28.516.0,46.228.0,26.258.0,31.231.0,44.285.0"}
P.entries["subzone:menethil-keep"] = {n="Крепость Менетил",s="Крепость Менетил — каменный оплот, господствующий над Гаванью Менетилов в Болотине. Четыре крепкие сторожевые башни отмечают ее как административное сердце и оборонительный бастион порта Альянса; здесь находится командир местного ополчения капитан Крепкий Кулак.",h="Крепость Менетил — каменный оплот, господствующий над Гаванью Менетилов в Болотине.",kw={"captain stoutfist","menethil harbor","menethil keep","militia","towers","wetlands","капитан крепкий кулак","гавань менетилов","крепость менетил","ополчение","башни","болотина"},ang={["faction:Alliance"]="Для путников Альянса, прибывающих на корабле из Калимдора или направляющихся на север к Стальгорну и Арати, Крепость Менетил — главный военный оплот, обеспечивающий безопасность этого важного транспортного узла."},sec={{t="Бастион гавани",b="Возвышаясь над деревянными причалами и сырыми болотами Болотины, Крепость Менетил — главный военный опорный пункт Гавани Менетилов. Четыре каменные сторожевые башни смотрят на город и бухту, и крепость дает отличный обзор для защиты от морских налетчиков, отступников и наступающих болотных тварей. Внутри капитан Крепкий Кулак руководит обороной порта, командует городским ополчением и организует патрули для защиты интересов Альянса в регионе."}},faq={{q="Для чего служит Крепость Менетил?",a="Крепость Менетил — штаб ополчения Гавани Менетилов и главный командный пункт Альянса в Болотине. Капитан Крепкий Кулак командует местным гарнизоном из ее каменных стен, направляя оборону и привлекая искателей приключений к борьбе с угрозами по всей топи.",al={"purpose of menethil keep","menethil keep role","what is this castle","назначение крепости менетил","роль крепости менетил","что это за замок"}},{q="Кто управляет Крепостью Менетил?",a="Капитан Крепкий Кулак командует крепостью и ополчением Менетила. Он руководит обороной гавани от местных угроз, таких как налетчики из дворфов клана Черного Железа, болотные твари и пираты.",al={"who leads menethil keep","keep commander","captain stoutfist","кто возглавляет крепость менетил","командир крепости","капитан крепкий кулак"}},{q="Где находится крепость?",a="Крепость заметно возвышается внутри Гавани Менетилов на западном побережье Болотины и нависает прямо над поселением своими четырьмя высокими каменными башнями.",al={"where is menethil keep","menethil keep location","how to find menethil keep","где крепость менетил","расположение крепости менетил","как найти крепость менетил"}}},fp="13,269,21.473.0,31.297.0,34.184.0,26.160.0"}
P.entries["subzone:merchant-coast"] = {n="Торговое побережье",s="Торговое побережье — участок восточного берега Степей, граничащий с Великим морем. Здесь доминирует оживленный гоблинский порт Кабестан; побережье получило имя от доходной морской торговли, но постоянно оспаривается пиратами.",h="Торговое побережье — участок восточного берега Степей, граничащий с Великим морем.",kw={"barrens","great sea","merchant coast","ratchet","southsea freebooters","steamwheedle cartel","степи","великое море","торговое побережье","кабестан","флибустьеры южных морей","картель хитрая шестеренка"},ang={["faction:Alliance"]="Альянс держит неподалеку военно-морское присутствие в Крепости Северной Стражи, настороженно следя и за гоблинской торговлей через Кабестан, и за буйными пиратами Южных морей на берегу.",["faction:Horde"]="Торговое побережье — главная торговая связь Орды с морем в Степях, поэтому безопасность Кабестана и подавление местных пиратов жизненно важны для линий снабжения региона."},sec={{t="Врата торговли и раздора",b="Торговое побережье тянется вдоль восточного края Степей и служит важной морской артерией, связывающей центральный Калимдор с Восточными королевствами и Тераморем. Название дано в честь трудолюбивых гоблинских торговцев Картеля Хитрая Шестеренка, чей нейтральный порт Кабестан принимает грузы любого, у кого есть деньги. Однако открытые морские пути привлекают не только торговые суда: Флибустьеры Южных морей рыщут по пескам и ближним водам, нападая на торговые корабли и устраивая незаконные дела на пляжах."}},faq={{q="Почему оно называется Торговым побережьем?",a="Берег получил имя из-за доходной торговли, которая идет через гоблинский порт Кабестан. Торговцы Хитрой Шестеренки везут грузы с этого побережья через Великое море в порты по всему Азероту.",al={"merchant coast name origin","why called merchant coast","происхождение названия торговое побережье","почему торговое побережье"}},{q="Какие крупные поселения есть на Торговом побережье?",a="Самое заметное поселение — Кабестан, нейтральный гоблинский портовый город под управлением Газлоу. Дальше к югу вдоль побережья находится оплот Альянса — Крепость Северной Стражи, а Остров Битв лежит неподалеку от берега.",al={"towns on merchant coast","what is on merchant coast","города торгового побережья","что есть на торговом побережье"}},{q="Кто контролирует здешние пляжи?",a="Хотя Кабестан контролирует ближайшую гавань, Флибустьеры Южных морей устроили лагеря на окрестных пляжах. Эти пираты активно мешают торговле, грабят гоблинские караваны и бросают вызов власти Кабестана.",al={"pirates on merchant coast","who is attacking merchant coast","пираты торгового побережья","кто нападает на торговое побережье"}}},fp="14,248,35.506.0,36.200.0,49.201.0,37.222.0"}
P.entries["subzone:military-ward"] = {n="Военный квартал",s="Военный квартал — боевое сердце Стальгорна: здесь расположены командование города, оружейных дел мастера и казармы. Он отмечен яркими красными знаменами; тут тренируются дворфийские солдаты, охотники и осадные инженеры рядом с механизированными осадными машинами и летательными аппаратами.",h="Военный квартал — боевое сердце Стальгорна: здесь расположены командование города, оружейных дел мастера и...",kw={"buliwyf stonehand","flying machines","hall of arms","ironforge","military ward","steam tanks","timberline arms","бульвиф каменная рука","летательные аппараты","зал оружия","стальгорн","военный квартал","паровые танки","оружие тимберлайн"},ang={["class:Hunter"]="Следопыты и горцы найдут в Зале Оружия укротителей зверей и припасы, а также «Охотничьи припасы Золотой Ярости» с боеприпасами и снаряжением.",["class:Warrior"]="Военный квартал — главный воинский центр Стальгорна: здесь есть наставники воинов, тренировочные манекены для боевой практики и мастера оружия, которые расширят ваш боевой арсенал."},sec={{t="Наковальня дворфийской мощи",b="Военный квартал расположен в северной части горной крепости и собирает оборонительные силы Стальгорна в оживленный сборный пункт. В центральном комплексе, Зале Оружия, находятся наставники воинов и охотников, полевые командиры, а также ангары с дворфийскими летательными аппаратами и паровыми танками. Вокруг плацов и тренировочных манекенов расположены лавки снабжения — «Латы и кольчуги Крагхелма», «Охотничьи припасы Золотой Ярости» и «Оружие Тимберлайн», — и квартал служит главным сборным пунктом для горцев и защитников города."},{t="Гарнизон под знаменами войны",b="В отличие от бледно-голубого Общинного квартала и огненно-оранжевой Великой кузни, Военный квартал украшают боевые красные знамена. Между учениями и осмотрами оружия солдаты и стражники в свободное время собираются в «Углу Бруука» за элем, а Мастер оружия Бульвиф Каменная Рука обучает новобранцев древним дворфийским боевым традициям."}},faq={{q="Что такое Военный квартал?",a="Это воинский квартал Стальгорна, центральная база дворфийской армии, наставников воинов и охотников, торговцев оружием и осадных машин.",al={"military ward ironforge","ironforge barracks","ironforge warrior district","военный квартал стальгорна","казармы стальгорна","квартал воинов стальгорна"}},{q="Где в Стальгорне можно обучиться владению оружием?",a="Мастер оружия Бульвиф Каменная Рука находится в «Оружии Тимберлайн» в Военном квартале и обучает бойцов Альянса владению различным оружием.",al={"ironforge weapon master","where is buliwyf stonehand","learn weapons ironforge","мастер оружия стальгорна","где бульвиф каменная рука","обучение оружию стальгорн"}},{q="Что находится внутри Зала Оружия?",a="Зал Оружия служит военным штабом: в нем находятся боевые наставники, полевые командиры и большие ангары для паровых танков и дворфийских летательных аппаратов.",al={"hall of arms ironforge","what is in hall of arms","ironforge siege engines","зал оружия стальгорн","что в зале оружия","осадные машины стальгорна"}},{q="Почему в этом квартале красные знамена?",a="Кварталы Стальгорна используют особые геральдические цвета для ориентации и по традиции; Военный квартал украшен яркими красными знаменами как воинская рука горного города.",al={"military ward colors","red banners ironforge","цвета военного квартала","красные знамена стальгорн"}}},fp="13,282,26.548.0,31.342.0,26.158.0,42.150.0,37.166.0,41.179.0"}
P.entries["subzone:mirage-flats"] = {n="Маревые равнины",s="Маревые равнины — бесплодная, выжженная солнцем местность в центре Бесплодных земель. Это сухое плато к востоку от Грота Гнилобрюхих известно мерцающей жаркой дымкой и голодными хищниками.",h="Маревые равнины — бесплодная, выжженная солнцем местность в центре Бесплодных земель.",kw={"badlands","crag coyote","dragon's mouth","dustbelch grotto","giant buzzard","mirage flats","ridge stalker","бесплодные земли","скальный койот","пасть дракона","грот гнилобрюхих","гигантский стервятник","маревые равнины","скальный охотник"},ang={["class:Hunter"]="На широких открытых Маревых равнинах множество агрессивных зверей, которых можно выслеживать, изучать или приручать, особенно свирепых скальных охотников и выносливых койотов, закаленных жизнью в пустыне."},sec={{t="Выжженная пустошь",b="К востоку от Грота Гнилобрюхих Маревые равнины предстают перед путниками суровой полосой растрескавшейся красной земли и мерцающего зноя, давшего равнине название. Здесь почти не задерживаются разумные существа: открытые равнины принадлежат хищникам-падальщикам и смертоносным зверям. Стаи гигантских стервятников лениво кружат в горячих потоках воздуха, высматривая остатки добычи свирепых скальных охотников и стайных скальных койотов, прочесывающих заросли в поисках легкой поживы."}},faq={{q="Где находятся Маревые равнины?",a="Равнины лежат в центральной части Бесплодных земель, к востоку от Грота Гнилобрюхих. Путники, идущие между западными утесами и восточными каньонами, нередко оказываются на этой выжженной солнцем земле.",al={"mirage flats location","where is mirage flats","mirage flats map","маревые равнины где","где находятся маревые равнины","карта маревых равнин"}},{q="Почему эта местность называется Маревые равнины?",a="Название происходит от слепящего пустынного солнца и гнетущего жара, исходящего от плоской каменистой земли. Из-за него возникают постоянные оптические иллюзии и марево, способные сбить с пути измученных жаждой путников в пустоши.",al={"why called mirage flats","mirage flats name meaning","heat mirage badlands","почему маревые равнины","значение названия маревые равнины","марево бесплодные земли"}},{q="Какие существа бродят по равнинам?",a="Здесь обитают выносливые хищники и падальщики, приспособленные к суровым Бесплодным землям. Стаи бешеных скальных койотов и скальные охотники-патриархи рыщут по зарослям, а гигантские стервятники кружат над головой в ожидании добычи, упавшей в пыль.",al={"mirage flats mobs","what lives in mirage flats","beasts of mirage flats","существа маревых равнин","кто живет в маревых равнинах","звери маревых равнин"}}},fp="12,203,20.473.0,35.189.0,36.216.0,31.268.0"}
P.entries["subzone:mirkfallon-lake"] = {n="Мутное озеро",s="Мутное озеро лежит в центральной нагорной котловине Когтистых гор, под отвесными скалами Утеса Ветрорезов. В его водах и на берегах обитает местная живность, в том числе агрессивные слизни, бродячие громовые ящеры и спускающиеся виверны.",h="Мутное озеро лежит в центральной нагорной котловине Когтистых гор, под отвесными скалами Утеса Ветрорезов.",kw={"mirkfallon","mirkfallon lake","stonetalon lake","stonetalon thunder lizards","windshear lake","мутное озеро","когтистые горы озеро","громовые ящеры когтистых гор","озеро утеса ветрорезов"},ang={["class:Druid"]="Дикие звери у Мутного озера отражают хрупкое равновесие природы Когтистых гор, неуютно близкой к наступающим механическим топорам на утесе наверху."},sec={{t="Нагорная котловина",b="Расположенное в географическом центре Когтистых гор, Мутное озеро лежит между горными перевалами, ведущими на юг к Паучьему тракту и на север к Пику Каменного Когтя. Питаемое стоком с высокогорий, озеро служит плодородным оазисом среди скалистых вершин: к нему спускаются на водопой громовые ящеры, а с высоких гнезд слетаются виверны. В водах также обитают странные пузырящиеся слизи, из-за которых обычно тихий горный пруд становится опасным местом для одиноких путников."},{t="Перекресток утесов",b="Тропы расходятся от котловины озера во все стороны. На востоке скалистые дороги поднимаются к Утесу Ветрорезов и лесозаготовкам, уходящим вглубь лесистых долин. Путники, идущие на север мимо озера, поднимаются к святилищам ночных эльфов и высотам таурен, а те, кто идет южнее, должны считаться с ядовитыми паучьими логовами. Поэтому берега Мутного озера часто становятся непредсказуемым перекрестком для исследователей и разведчиков в спорных горах."}},faq={{q="Какие существа живут вокруг Мутного озера?",a="На озере и его берегах обитают бродячие громовые ящеры, ядовитые слизни на мелководье и горные виверны, охотящиеся вокруг котловины и гнездящиеся на высотах над ней.",al={"mirkfallon lake beasts","mirkfallon wildlife","what is at mirkfallon lake","звери мутного озера","живность мутного озера","что у мутного озера"}},{q="Куда ведут пути от озера?",a="Подъем на север ведет к Пику Каменного Когтя. На юг спуск идет через Паучий тракт, а скалистые подъемы на восток выводят к Утесу Ветрорезов.",al={"mirkfallon paths","where does mirkfallon go","mirkfallon lake directions","тропы мутного озера","куда ведет мутное озеро","мутное озеро маршрут"}},{q="Безопасно ли ловить рыбу в Мутном озере?",a="Озеро богато шалфейной рыбой и плавучими обломками, что привлекает рыболовов. Однако агрессивные звери, такие как слизни и виверны, часто бывают на берегу, и спокойно ловить рыбу трудно.",al={"fishing mirkfallon lake","can i fish in mirkfallon","рыбалка мутное озеро","можно ли ловить рыбу в мутном озере"}}},fp="15,267,16.492.0,22.484.0,43.200.0,25.156.0,35.200.0"}
P.entries["subzone:mirror-lake"] = {n="Зеркальное озеро",s="Зеркальное озеро — живописный водоем на северо-западе Элвиннского леса возле сада. Питаемое мягким водопадом под скалами Штормграда, оно скрывает за тихой гладью опасности на берегах: от рыщущих бандитов Братства Справедливости до странных нарушений в местных линиях силы.",h="Зеркальное озеро — живописный водоем на северо-западе Элвиннского леса возле сада.",kw={"defias","elwynn forest","mirror lake","stormwind","waterfall","wizards sanctum","братство справедливости","элвиннский лес","зеркальное озеро","штормград","водопад","святилище волшебника"},ang={["class:Mage"]="Ученики Святилища волшебника в Штормграде приходят сюда за пробами воды и на практике узнают, как бурные потоки тайной энергии просачиваются в природную экосистему.",["faction:Alliance"]="Хотя озеро находится близ высоких стен столицы, оно напоминает, насколько растянуты силы стражи королевства в борьбе с преступниками Братства Справедливости."},sec={{t="Неспокойная идиллия",b="Зеркальное озеро лежит под высокими стенами Штормграда и должно быть мирным убежищем для рыбаков и усталых путников. Однако разбойники Братства Справедливости рыщут по окрестным садам, делая любое долгое пребывание опасным для местных. Хуже того, магические возмущения по всему Азероту начали искажать естественные потоки тайной энергии в лесу. Маги Святилища волшебника осторожно следят за озером, отправляя магов брать пробы воды, чтобы хаотичные тайные стоки не отравили поселения ниже по течению."}},faq={{q="Почему Зеркальное озеро опасно?",a="Несмотря на живописный вид, окрестности озера буквально кишат бандитами Братства Справедливости, нападающими на путников и фермеров. Кроме того, недавние колебания магии в регионе вызвали опасения за безопасность воды в озере.",al={"is mirror lake safe","mirror lake enemies","defias mirror lake","безопасно ли зеркальное озеро","враги зеркального озера","братство справедливости зеркальное озеро"}},{q="Почему маги изучают Зеркальное озеро?",a="Масштабные магические конфликты по всему Азероту расшатали потоки силы в Элвиннском лесу и Штормграде. Святилище волшебника посылает учеников брать пробы воды из озера, чтобы выявить нестабильные тайные остатки прежде, чем они повредят тем, кто пьет эту воду.",al={"wizard sanctum mirror lake","mirror lake quest","magic in mirror lake","святилище волшебника зеркальное озеро","задание зеркальное озеро","магия зеркального озера"}},{q="Откуда берется водопад у Зеркального озера?",a="Водопад низвергается с высоких скал и водных путей вдоль границы Штормграда и питает озеро, после чего вода течет по речной системе Элвиннского леса.",al={"mirror lake waterfall","water source mirror lake","водопад зеркального озера","источник воды зеркального озера"}}},fp="11,296,15.590.0,29.236.0,35.262.0,50.177.0"}
P.entries["subzone:mirror-lake-orchard"] = {n="Сад у Зеркального озера",s="Сад у Зеркального озера — тихая роща с домиком на южном берегу Зеркального озера в западной части Элвиннского леса. Когда-то мирная усадьба близ Ревущего водопада, теперь она попала в руки бандитов Братства Справедливости, которые грабят округу, пока стража Штормграда смотрит в другую сторону.",h="Сад у Зеркального озера — тихая роща с домиком на южном берегу Зеркального озера в западной части Элвиннского...",kw={"defias brotherhood","elwynn forest","mirror lake","mirror lake orchard","stormwind bandits","thunder falls","братство справедливости","элвиннский лес","зеркальное озеро","сад у зеркального озера","бандиты штормграда","ревущий водопад"},ang={["class:Rogue"]="Сад демонстрирует классическую стратегию Братства Справедливости: захватывать защищенные, незаметные владения у воды и скал, чтобы следить за дорогами и уходить от городских патрулей.",["faction:Alliance"]="Для путников из Альянса захваченный сад — еще один горький признак наглой экспансии Братства Справедливости по всему сердцу королевства."},sec={{t="Захваченная роща",b="Сад у Зеркального озера, укрытый близ низвергающихся вод Ревущего водопада, когда-то был процветающей фермой, пользовавшейся чистой водой Зеркального озера. Сегодня мирный домик захвачен: им завладели воры и разбойники под знаменами Братства Справедливости. Пока армия королевства растянута, а король Вариан Ринн пропал, сельские владения вроде этого сада стали легкой добычей для преступников, ищущих укрытия в Элвиннской глубинке."}},faq={{q="Кто сейчас контролирует Сад у Зеркального озера?",a="Сад у Зеркального озера и домик рядом с ним сейчас занимают бандиты Братства Справедливости. Они прогнали всех честных людей, некогда ухаживавших за деревьями, и используют уединенное место как базу на западе Элвиннского леса.",al={"who is at mirror lake orchard","who lives here","orchard enemies","кто в саду у зеркального озера","кто здесь живет","враги в саду"}},{q="Где находится Сад у Зеркального озера?",a="Сад расположен на южном берегу Зеркального озера в западной части Элвиннского леса, к востоку от Ревущего водопада и к северу от главной дороги в Западный Край.",al={"mirror lake orchard location","where is the orchard","find orchard elwynn","сад у зеркального озера где","где сад","найти сад элвиннский лес"}},{q="Почему Штормград не вернул себе сад?",a="Регулярная армия Штормграда в основном отсутствует в сельской местности Элвиннского леса из-за политического тупика и загадочного исчезновения короля Вариана Ринна. Из-за нехватки людей в местных гарнизонах дальние фермы и сады часто остаются один на один с Братством Справедливости.",al={"why are defias here","where are the guards","почему здесь братство справедливости","где стража"}},{q="Как связаны сад и Ревущий водопад?",a="Зеркальное озеро стекает прямо в Ревущий водопад, и сад оказывается чуть выше ревущего каскада. Его уединенное положение у скал делает его удобным и защищенным местом для бандитов.",al={"thunder falls connection","orchard and waterfall","связь с ревущим водопадом","сад и водопад"}}},fp="19,281,21.494.0,43.208.0,37.161.0,43.283.0,61.185.0"}
P.entries["subzone:mist-s-edge"] = {n="Туманный Предел",kw={"auberdine","beach","coast","crabs","darkshore","mist's edge","murloc","shipwreck","аубердин","пляж","побережье","крабы","темные берега","туманный предел","мурлок","кораблекрушение"},ang={["race:NightElf"]="Для ночных эльфов Аубердина Туманный Предел — одновременно важная морская граница и дикий рубеж, где досаждают вторгающиеся мурлоки и мерзкие падальщики."},sec={{t="Берег в тумане",b="Туманный Предел тянется вдоль западного края Темных берегов и состоит из влажных песков, скалистых приливных озер и вечного прибрежного тумана. Пляж — кладбище моря, усеянное разлагающимися тушами морских исполинов, плавником и обломками ребер разбитых кораблей. Хотя берег кажется пустынным, он кишит падальщиками: агрессивными крабами и враждебными племенами мурлоков, гнездящимися в прибое."},{t="Крушения и падальщики",b="Коварные воды у берегов Темных берегов погубили бесчисленное множество судов, оставив на песке разбитые корпуса и брошенные грузы. Часовые ночных эльфов и местные падальщики внимательно следят за побережьем, где лагеря мурлоков часто угрожают путникам, идущим вдоль берега от Аубердина и обратно."}},faq={{q="Что такое Туманный Предел?",a="Mist's Edge is the expansive stretch of coastline that runs north from Auberdine along the western shore of Darkshore, known for its cold ocean fog, shipwrecks, and beached sea creatures.",al={"mists edge","darkshore beach","what is mists edge","туманный предел","пляж темных берегов","что такое туманный предел"}},{q="Какие опасности бродят на этом берегу?",a="Берег густо населен враждебными прибрежными крабами и агрессивными стаями мурлоков, живущими в примитивных лагерях у кромки воды.",al={"mists edge monsters","what attacks you on the beach","darkshore coast dangers","монстры туманного предела","кто нападает на пляже","опасности побережья темных берегов"}},{q="Почему здесь так много кораблекрушений и скелетов?",a="Суровые течения, скрытые рифы и густой туман у Темных берегов делают плавание опасным и разбивают корабли о скалы. Кроме того, океанские течения часто выбрасывают на берег останки огромных левиафанов и морских существ.",al={"darkshore beached whales","shipwrecks mists edge","giant bones darkshore","киты на темных берегах","кораблекрушения туманный предел","гигантские кости темных берегов"}}},fp="11,248,20.407.0,21.337.0,20.187.0,31.141.0,52.216.0"}
P.entries["subzone:misty-pine-refuge"] = {n="Сторожка у заснеженной сосны",s="Сторожка у заснеженной сосны — небольшой форпост Серебряного Рассвета среди промерзших снегов центральной части Дун Морога.",h="Сторожка у заснеженной сосны — небольшой форпост Серебряного Рассвета среди промерзших снегов центральной...",kw={"argent dawn","dun morogh","father gavin","misty pine refuge","серебряный рассвет","дун морог","отец гавин","сторожка у заснеженной сосны"},ang={["class:Priest"]="Скромный пост отца Гавина показывает, что служение Свету часто заключается в тихом бдении вдали от полей сражений."},sec={{t="Приют в снегах",b="Сторожка у заснеженной сосны, расположенная среди продуваемых ветрами холмов Дун Морога, — скромный форпост Серебряного Рассвета во владениях дворфов. Окрестные скалы патрулируют горные пехотинцы Стальгорна, а в сторожке живет отец Гавин, единственный здесь агент ордена. Он предлагает тихий очаг среди суровой стужи и опасностей, угрожающих горным дорогам."}},faq={{q="Что такое Сторожка у заснеженной сосны?",a="Это здание-форпост Серебряного Рассвета в центральной части Дун Морога, которым управляет единственный агент ордена — отец Гавин.",al={"what is this place","misty pine","misty pine refuge overview","что это за место","заснеженная сосна","сторожка у заснеженной сосны обзор"}},{q="Почему Серебряный Рассвет находится здесь, в Дун Мороге?",a="Хотя Серебряный Рассвет занимается в основном угрозой нежити на севере, такие агенты, как отец Гавин, наблюдают и из более тихих уголков земель Альянса.",al={"why argent dawn here","father gavin argent dawn","argent dawn dwarf lands","почему серебряный рассвет здесь","отец гавин серебряный рассвет","серебряный рассвет земли дворфов"}},{q="Кто живет в сторожке?",a="Отец Гавин, агент Серебряного Рассвета, — единственный член ордена, находящийся в сторожке.",al={"who is at misty pine","misty pine npcs","кто в сторожке у заснеженной сосны","персонажи сторожки у заснеженной сосны"}}},fp="17,118,19.366.0,26.118.0,42.164.0,24.99.0"}
P.entries["subzone:misty-reed-post"] = {n="Тростниковая застава",s="Тростниковая застава — суровый лагерь Орды между Вязкой топью и Тростниковым берегом в восточной части Болота Печали. Созданная как передовой дозорный пост под властью Каменора, она следит за опасными болотами и коварным побережьем.",h="Тростниковая застава — суровый лагерь Орды между Вязкой топью и Тростниковым берегом в восточной части Болота...",kw={"katar","misty reed post","misty reed strand","stagalbog","stonard","swamp of sorrows","tok'kar","катар","тростниковая застава","тростниковый берег","вязкая топь","каменор","болото печали","ток'кар"},ang={["class:Hunter"]="Застава, где служат в основном охотники Каменора, знающие местную болотную экологию, воплощает стойкость, нужную для выслеживания и выживания среди враждебных хищников топей.",["faction:Horde"]="Лагерь дает разведчикам Орды желанный уголок безопасности и местные советы при передвижении по опасным восточным окраинам болота."},sec={{t="Одинокий форпост",b="Тростниковая застава, затерявшаяся во влажном сумраке между Вязкой топью и восточным берегом, — лишь спартанский лагерь под знаменем Каменора. В нем несут службу несколько охотников Каменора, шаман Катар и Ток'Кар, руководящий дозором. Условия суровы: укрепленного убежища от враждебных болотных тварей и вечной сырости нет. Ток'Кар втайне надеется, что командование Орды в Каменоре однажды укрепит позицию прочной орочьей норой или сторожевой башней, но пока разведчикам приходится удерживать болото с помощью палаток, дыма костров и отточенной стали."}},faq={{q="Для чего нужна Тростниковая застава?",a="Она служит вторым передовым лагерем гарнизона Орды в Каменоре. Расположенные между болотами Вязкой топи и побережьем Тростникового берега, ее часовые следят за угрозами с моря и местными болотными зверями.",al={"why is misty reed post here","misty reed post purpose","what is this camp","зачем здесь тростниковая застава","назначение тростниковой заставы","что это за лагерь"}},{q="Кто здесь главный?",a="Заставой руководит Ток'Кар, орк, которому поручено удерживать уязвимый лагерь вместе с Катаром, шаманом Каменора, и несколькими охотниками Каменора. Ток'Кар надеется, что поселению в конце концов выделят ресурсы для постройки постоянных укреплений.",al={"who leads misty reed post","tokkar","tok'kar","кто командует тростниковой заставой","токкар","ток'кар"}},{q="Есть ли на Тростниковой заставе распорядитель полетов?",a="Нет. Тростниковая застава — аскетичный полевой лагерь без насестов для наездников на ветрокрылах. Путникам, которым нужны маршруты полета, придется отправиться на запад по дороге в Каменор.",al={"misty reed flight path","is there a flight path here","flight master misty reed post","полеты тростниковая застава","есть ли здесь пункт полета","распорядитель полетов тростниковая застава"}}},fp="15,285,16.597.0,39.226.0,22.247.0,44.166.0"}
P.entries["subzone:misty-reed-strand"] = {n="Тростниковый берег",s="Тростниковый берег — окутанное туманом пустынное восточное побережье Болота Печали. Он усеян острыми скалами, выброшенными обломками и стелющейся болотной дымкой, и в нем обитают агрессивные крабы, кроколиски и прибрежные племена мурлоков. Путники, спускающиеся к прибою, часто вынуждены бороться с местной живностью за все, что выносит на берег.",h="Тростниковый берег — окутанное туманом пустынное восточное побережье Болота Печали.",kw={"beach","coast","crocolisk","driftwood","great sea","misty reed strand","murloc","swamp of sorrows","пляж","побережье","кроколиск","плавник","великое море","тростниковый берег","мурлок","болото печали"},ang={["faction:Alliance"]="Разведчики Альянса, идущие на юг от Крепости Стражей Пустоты или пересекающие болота, часто собирают обильный плавник и другие ресурсы пляжа, сдерживая его агрессивных обитателей.",["faction:Horde"]="Защитники Каменора считают племена мурлоков на берегу неконтролируемой угрозой и часто отправляют боевые патрули, чтобы уничтожить их лагеря у прибоя."},sec={{t="Туманный берег",b="Тростниковый берег тянется вдоль всей восточной границы Болот Печали и образует сырой барьер между глубокой трясиной и Великим морем. С воды постоянно наползают густые туманы, которые застилают обзор и приглушают крики местных животных. Пляжи усеяны морским мусором, плавником и гниющими растениями, вынесенными из внутренней топи. Из-за удаленного положения и сурового климата на побережье нет официальных постоянных поселений, и пески достаются агрессивным ракообразным, подстерегающим кроколискам и мурлокам, которые яростно защищают свои места промысла."},{t="Спорные воды",b="Разведчики и Альянса, и Орды время от времени отправляют искателей приключений на берег, хотя ни одна из сторон не считает пляж своей территорией. Альянс часто собирает здесь плавник и добычу с берега, пытаясь сократить число снующих крабов. Тем временем форпосты Орды в глубине болот следят за лагерями мурлоков на побережье и посылают опытных бойцов сокращать их число, пока земноводные налетчики не продвинулись дальше к Каменору или не стали угрожать путникам в болоте."}},faq={{q="Где находится Тростниковый берег?",a="Тростниковый берег тянется вдоль крайнего восточного края Болота Печали у Великого моря. До него можно добраться, идя прямо на восток через топи от Каменора или по окрестным болотным тропам.",al={"where is misty reed strand","misty reed strand location","how to get to misty reed strand","где тростниковый берег","расположение тростникового берега","как добраться до тростникового берега"}},{q="Какие существа обитают на берегу?",a="Берег густо населен гигантскими прибрежными крабами, болотными кроколисками и разными племенами враждебных мурлоков, обыскивающих линию прилива.",al={"monsters at misty reed strand","what lives on misty reed strand","misty reed strand enemies","монстры тростникового берега","кто живет на тростниковом берегу","враги тростникового берега"}},{q="Есть ли на пляже поселения?",a="На самом пляже нет ни постоянных дружественных городов, ни устоявшихся военных застав. Ближайшие поселения находятся дальше от берега, в глубине Болота Печали.",al={"towns near misty reed strand","misty reed strand base","friendly camps misty reed strand","города рядом с тростниковым берегом","база тростниковый берег","дружественные лагеря тростниковый берег"}},{q="Почему фракции посылают искателей приключений на Тростниковый берег?",a="И Альянс, и Орда время от времени отправляют на побережье наемников. Посланники Альянса часто ищут плавник и прибрежные материалы, а Орда посылает воинов сокращать число агрессивных племен мурлоков, живущих в прибое.",al={"why go to misty reed strand","misty reed strand quests","зачем идти на тростниковый берег","задания тростникового берега"}}},fp="17,365,17.603.0,16.496.0,39.221.0,34.141.0,39.173.0,62.242.0"}
P.entries["subzone:misty-valley"] = {n="Туманная долина",s="Туманная долина, укрывшаяся на северо-западе Болота Печали, — затененная, пропитанная туманом лощина к северу от прохода на Перевал Мертвого Ветра. Уединенную котловину заполонили первобытные болотные звери, бродячие болотоходы и спутанные ужасы. В глубине дальней пещеры обитает огромный и устрашающий Владыка трясины.",h="Туманная долина, укрывшаяся на северо-западе Болота Печали, — затененная, пропитанная туманом лощина к северу...",kw={"deadwind pass","mire lord","misty valley","swamp of sorrows","swampwalker","tangled horror","перевал мертвого ветра","владыка трясины","туманная долина","болото печали","болотоход","спутанный ужас"},ang={["class:Druid"]="Громадные болотоходы и спутанные ужасы, населяющие эту уединенную долину, воплощают дикую, неукротимую ярость болотных элементалей, тесно связанных с первобытной природой топи."},sec={{t="Туманная лощина",b="Туманная долина, лежащая под высокими утесами, что отделяют Болото Печали от Перевала Мертвого Ветра, постоянно скрыта густыми болотными испарениями. В отличие от открытых болот на востоке, этот изолированный уголок кишит огромными болотными элементалями: громадными болотоходами, древними старейшинами болотоходов и ползучими спутанными ужасами. В дальнем конце туманного ущелья находится пещера — логово Владыки трясины, одной из самых грозных природных опасностей болота."}},faq={{q="Где находится Туманная долина?",a="Туманная долина расположена в дальнем северо-западном углу Болота Печали, прямо к северу от дороги, ведущей к Перевалу Мертвого Ветра.",al={"misty valley location","where is misty valley","misty valley swamp of sorrows","расположение туманной долины","где туманная долина","туманная долина болото печали"}},{q="Какие существа обитают в этой долине?",a="Долину заполонили огромные растительные элементали и болотные ужасы — болотоходы, старейшины болотоходов и спутанные ужасы, бродящие в густом тумане.",al={"misty valley mobs","what lives in misty valley","enemies in misty valley","монстры туманной долины","кто живет в туманной долине","враги в туманной долине"}},{q="Что находится в пещере в глубине долины?",a="В глубине пещеры в задней части Туманной долины обитает Владыка трясины, огромный и могучий болотный элементаль, властвующий над уединенной лощиной.",al={"misty valley cave","mire lord cave","who is in misty valley cave","пещера туманной долины","пещера владыки трясины","кто в пещере туманной долины"}},{q="Безопасно ли ходить по Туманной долине?",a="Вовсе нет. Огромные болотоходы и спутанные ужасы, бродящие в густом тумане, враждебны и агрессивны, и долина опасна для неосторожных путников, сошедших с главной дороги.",al={"is misty valley dangerous","misty valley level","опасна ли туманная долина","уровень туманной долины"}}},fp="12,324,19.487.0,34.145.0,35.171.0,50.151.0,37.187.0"}
P.entries["subzone:mizjah-ruins"] = {n="Руины Мизжа",s="Руины Мизжа — древние каменные развалины на севере Тернистой долины, к юго-востоку от Лагеря Гром'гол. Давно покинутые своими создателями-троллями, обрушающиеся строения заняли огры клана Мош'Огг, известные грубой силой. Отсюда огры устраивают засады на проходящие обозы со снабжением, направляющиеся к Болоту Печали.",h="Руины Мизжа — древние каменные развалины на севере Тернистой долины, к юго-востоку от Лагеря Гром'гол.",kw={"brute","grom'gol","mizjah","mizjah ruins","mosh'ogg","stonard","stranglethorn","witch doctor","громила","гром'гол","мизжа","руины мизжа","мош'огг","каменор","тернистая долина","знахарь"},ang={["faction:Horde"]="Присутствие Мош'Огг в Мизжа напрямую угрожает важному снабжению Орды и вынуждает Лагерь Гром'гол отправлять воинов на защиту пути к Каменору."},sec={{t="Логово огров",b="Как и многие древние каменные руины, разбросанные по Тернистой долине, Руины Мизжа были построены Империей Гурубаши задолго до возвышения современных государств. Сегодня поросшие мхом арки и растрескавшиеся плиты заняты кланом Мош'Огг — в основном свирепыми воинами и грубыми знахарями. Эти огры не ограничиваются захваченной территорией и регулярно нападают на ближайшие обозы со снабжением, идущие в поселение Орды Каменор, превращая древнюю историю в постоянную кровавую занозу для командиров Лагеря Гром'гол."}},faq={{q="Кто построил Руины Мизжа?",a="Как и большинство каменных построек на севере Тернистой долины, Руины Мизжа изначально возвели тролли джунглей Империи Гурубаши, пока века войн и упадка не опустошили их.",al={"who made mizjah","mizjah origins","troll ruins mizjah","кто построил мизжа","история мизжа","тролльские руины мизжа"}},{q="Кто живет в Руинах Мизжа сейчас?",a="Сейчас руины заняты ограми Мош'Огг, а именно громилами и знахарями Мош'Огг, которые укрепили каменные строения под свой лагерь.",al={"who lives here","mizjah mobs","mosh'ogg camp","кто здесь живет","мобы мизжа","лагерь мош'огг"}},{q="Почему Орда заинтересована в очистке руин?",a="Огры Мош'Огг, обитающие в Мизжа, активно нападают на линии снабжения Орды, устраивая засады на обозы между Лагерем Гром'гол и аванпостом Каменор на Болоте Печали.",al={"why kill mosh'ogg","grom'gol defense","stonard caravan quest","зачем убивать мош'огг","оборона гром'гол","задание обоз каменор"}}},fp="12,387,14.535.0,27.229.0,34.175.0,50.184.0"}
P.entries["subzone:mo-grosh-stronghold"] = {n="Оплот Мо'грош",s="Оплот Мо'грош — укрепленное логово огров, вырытое в северо-восточных холмах Лок Модана. Эти свирепые великаны, обосновавшиеся среди древних обветшалых руин, постоянно угрожают расположенным внизу поселениям дворфов.",h="Оплот Мо'грош — укрепленное логово огров, вырытое в северо-восточных холмах Лок Модана.",kw={"loch modan","mo'grosh","mogrosh","mountaineers","ogre","ruins","stronghold","лок модан","мо'грош","горцы","огр","огры","руины","оплот"},ang={["faction:Alliance"]="Чтобы обезопасить Лок Модан, нужно держать огров Мо'грош в узде и обеспечивать безопасный проход между Стальгорном и северными горными дорогами.",["race:Dwarf"]="Огры Мо'грош постоянно угрожают патрулям и путникам дворфов, поэтому уничтожение их оплота становится делом гражданской обороны для горцев Лок Модана."},sec={{t="Нависшая угроза",b="Оплот Мо'грош, укрывшийся в скалах северо-востока Лок Модана, служит главной базой клана огров Мо'грош в этих краях. Громилы, скрывающиеся в пещерах и внешних лагерях, нападают на караваны дворфов и постоянно угрожают спокойствию Телсамара. Грубая каменная кладка вокруг лагеря говорит о том, что здесь когда-то находилось более древнее поселение, пока неуклюжие огры не заняли эту землю и не воздвигли свои особые курганы."}},faq={{q="Что такое Оплот Мо'грош?",a="Это становище огров в холмах северо-востока Лок Модана. Огры Мо'грош живут в пещерах и на окрестных землях, образуя крупнейший враждебный анклав огров в этой местности.",al={"mogrosh stronghold","ogre camp loch modan","mogrosh cave","оплот мо'грош","лагерь огров лок модан","пещера мо'грош"}},{q="Кто жил здесь до огров?",a="Старая каменная кладка говорит о том, что здесь до огров стояло поселение, но кто в нем жил, неизвестно.",al={"ancient ruins loch modan","who built mogrosh","trolls in loch modan","древние руины лок модан","кто построил мо'грош","тролли в лок модане"}},{q="Чем огры опасны для дворфов?",a="Близость к важным путям делает их серьезной угрозой для местных путников и торговых караванов в Лок Модане. Власти дворфов регулярно просят искателей приключений сократить их число и сохранить горные перевалы безопасными.",al={"why kill mogrosh ogres","ironforge threat mogrosh","зачем убивать огров мо'грош","угроза стальгорну мо'грош"}}},fp="19,211,16.489.0,28.192.0,39.110.0,44.235.0"}
P.entries["subzone:molsen-farm"] = {n="Ферма Мольсена",s="Ферма Мольсена — заброшенная усадьба в житнице Западного Края. Когда-то это были плодородные земли, снабжавшие Штормград, но теперь ферма лежит в руинах после возвышения Братства Справедливости и появления бродящих механических жатвенных големов.",h="Ферма Мольсена — заброшенная усадьба в житнице Западного Края.",kw={"abandoned farm","defias","harvest watcher","homestead","molsen farm","westfall","заброшенная ферма","братство справедливости","страж урожая","усадьба","ферма мольсена","западный край"},ang={["faction:Alliance"]="Заросшие поля Фермы Мольсена — мрачное напоминание о слабеющей власти Штормграда над сельскими землями и о нависшей угрозе Братства Справедливости."},sec={{t="Разрушенная усадьба",b="Как и многие усадьбы Западного Края, Ферма Мольсена стала жертвой запустения королевства и преступного мятежа. Когда Братство Справедливости взяло под контроль сельскую местность, фермеров изгнали или хуже, и они бросили посевы и постройки. Теперь вместо работников, собирающих зерно, заброшенные поля прочесывают враждебные механические Стражи урожая и бродячие разбойники, и ферма опасна для всех, кто проходит через провинцию."}},faq={{q="Почему Ферма Мольсена заброшена?",a="Ферму оставили, когда Братство Справедливости захлестнуло Западный Край. Лишенные военной защиты Штормграда, поселенцы не смогли отстоять свою землю от бандитов и взбесившихся жатвенных големов и были вынуждены бежать из домов.",al={"why is it empty","who lived here","what happened to molsen farm","почему она пуста","кто здесь жил","что случилось с фермой мольсена"}},{q="Кто сейчас контролирует Ферму Мольсена?",a="Поля захвачены неисправными Стражами урожая и разбойниками Братства Справедливости. Законопослушных жителей на участке сейчас нет, и никто его не обрабатывает.",al={"molsen farm enemies","who is at molsen farm","враги фермы мольсена","кто на ферме мольсена"}},{q="Кем был Мольсен?",a="Ферма названа по местной семье, которая первой поселилась здесь и обрабатывала землю, пока недавние беспорядки не обрекли земледельцев Западного Края на изгнание или нищету.",al={"who is molsen","molsen family","кто такой мольсен","семья мольсен"}}},fp="11,268,18.458.0,29.243.0,26.164.0,15.174.0"}
P.entries["subzone:moon-horror-den"] = {n="Обитель Лунного Ужаса",s="Обитель Лунного Ужаса — уединенная, покрытая инеем пещера к северо-востоку от гоблинского торгового поселка Круговзор в Зимних Ключах. Расположенная у зубчатого горного склона, она служит гнездовьем свирепых яростных совиных. Путникам следует быть осторожными у ледяного входа: эти территориальные дикие совы яростно защищают свое убежище.",h="Обитель Лунного Ужаса — уединенная, покрытая инеем пещера к северо-востоку от гоблинского торгового поселка...",kw={"cave","everlook","moon horror den","owlbeasts","raging owlbeast","wildkin","winterspring","пещера","круговзор","обитель лунного ужаса","совиные","яростный совиный","дикие звери","зимние ключи"},ang={["class:Druid"]="Как хранители священных созданий Элуны, друиды видят в яростном неистовстве совиных обители мрачное зрелище, отражающее дикие смуты в Зимних Ключах.",["class:Hunter"]="Пещера — тесная и опасная арена для выслеживания свирепых диких зверей, где ближний бой с толстошкурыми совиными испытывает нервы любого следопыта."},sec={{t="Логово из перьев и льда",b="Обитель Лунного Ужаса, расположенная недалеко к северо-востоку от охраняемых ворот Круговзора, глубоко врезается в горную породу. В пещере живут могучие яростные совиные — грозные лесные звери, известные силой и дикостью в суровых снегах Зимних Ключей. Хотя деревня фурболгов Деревня Зимней Спячки находится неподалеку к югу, отвесная гора образует непроходимую преграду, и обитель остается изолированным убежищем, а не путем сообщения."}},faq={{q="Какие существа живут в Обители Лунного Ужаса?",a="Пещеру населяют яростные совиные — крупные агрессивные дикие звери, приспособившиеся к холодному климату Зимних Ключей. Эти территориальные твари жестоко нападают на всех, кто забредет в их подземное логово.",al={"what is in moon horror den","moon horror den mobs","owlbeasts in cave","кто в обители лунного ужаса","мобы обители лунного ужаса","совиные в пещере"}},{q="Где находится Обитель Лунного Ужаса?",a="Она находится в восточных Зимних Ключах, недалеко к северо-востоку от гоблинского города Круговзор. Вход в пещеру врезан в северный горный склон.",al={"moon horror den location","how to find moon horror den","where is moon horror den","где обитель лунного ужаса","как найти обитель лунного ужаса","расположение обители лунного ужаса"}},{q="Можно ли добраться из обители до Деревни Зимней Спячки?",a="Нет. Хотя Деревня Зимней Спячки лежит прямо к югу на карте, высокий горный хребет за обителью образует непроходимую естественную стену. Чтобы попасть в деревню, нужно обойти горные склоны через открытую долину.",al={"path to winterfall village","shortcut to winterfall","den to winterfall","путь в деревню зимней спячки","короткий путь в деревню зимней спячки","из обители в деревню"}},{q="Зачем путники идут в эту пещеру?",a="Искатели приключений обычно приходят в обитель, чтобы охотиться на яростных совиных, помогая натуралистам и исследователям, изучающим испорченных или агрессивных диких зверей Зимних Ключей.",al={"why go to moon horror den","moon horror den quests","зачем идти в обитель лунного ужаса","задания обители лунного ужаса"}}},fp="15,356,27.526.0,43.211.0,37.160.0,46.228.0,40.182.0"}
P.entries["subzone:moonbrook"] = {n="Луноречье",s="Когда-то оживленный сельскохозяйственный и горнодобывающий центр на юго-западе Западного Края, Луноречье теперь стоит беззаконным городом-призраком. Город полностью захвачен Братством Справедливости, которое использует его как укрепленную завесу, скрывающую подземную штаб-квартиру в Мертвых копях.",h="Когда-то оживленный сельскохозяйственный и горнодобывающий центр на юго-западе Западного Края, Луноречье...",kw={"deadmines","defias","moonbrook","schoolhouse","sentinel hill","vancleef","westfall","мертвые копи","братство справедливости","луноречье","школа","сторожевой холм","ван клиф","западный край"},ang={["class:Rogue"]="Переулки и разграбленные дома Луноречья наглядно показывают целую преступную организацию, действующую средь бела дня.",["faction:Alliance"]="Луноречье — горькое напоминание о пренебрежении королевства, где законопослушных подданных бросили на произвол Братства Справедливости."},sec={{t="Павший город",b="До Первой войны Луноречье было важной общиной в центре житницы Западного Края, поддерживавшей местные фермерские семьи и богатые золотые шахты Мертвых копей. Хотя Старая Орда разрушила его, а после Второй войны его кропотливо отстроили, мир длился недолго. Забытое Домом знати в Штормграде и лишенное военной защиты, поселение не смогло противостоять мстительной Гильдии каменщиков, бежавшей в глушь. Бандиты изгнали честных поселенцев, и жители вместе с учителями вынуждены были бежать к Сторожевому холму и в Элвиннский лес."},{t="Оплот Братства Справедливости",b="Сегодня Луноречье по сути служит наземным гарнизоном мятежа Эдвина ван Клифа. Громилы в красных масках и мятежные маги патрулируют улицы и разграбленные дома, а жатвенные големы обходят заросшие сорняками поля. Тихие жилые улицы скрывают вход в Мертвые копи под неприметным амбаром на краю города, делая Луноречье самым опасным очагом измены в королевстве."}},faq={{q="Почему Луноречье заброшено?",a="Мирные жители покинули Луноречье, когда Братство Справедливости захватило Западный Край. Без Армии Штормграда, которая охраняла бы регион, горожан вытеснили, а бандиты объявили весь город своим оплотом.",al={"what happened to moonbrook","why are there bandits in moonbrook","who took over moonbrook","что случилось с луноречьем","почему в луноречье бандиты","кто захватил луноречье"}},{q="Куда ведет шахта в Луноречье?",a="Вход в шахту под амбаром на краю Луноречья ведет в Мертвые копи. Когда-то это был огромный источник золота для Штормграда, а теперь лабиринты туннелей стали тайным убежищем и плацдармом Братства Справедливости.",al={"where are deadmines","what is under moonbrook","moonbrook mine entrance","где мертвые копи","что под луноречьем","вход в шахту луноречья"}},{q="Кто жил здесь до бандитов?",a="Луноречье когда-то населяли шахтеры, фермеры и ремесленники, обслуживавшие сельское хозяйство Западного Края. Среди известных прежних жителей был Сталван Мистмантл, недолго служивший директором местной Школы Луноречья до захвата города бандитами.",al={"moonbrook residents","who lived in moonbrook","stalvan mistmantle school","жители луноречья","кто жил в луноречье","сталван мистмантл школа"}},{q="Планирует ли Штормград вернуть город?",a="Двор Штормграда неоднократно отказывался посылать королевские войска для освобождения Луноречья или окрестных ферм, ссылаясь на нехватку ресурсов. Местная оборона полностью лежит на добровольцах Народного ополчения, расположенного у Сторожевого холма.",al={"will stormwind save moonbrook","why doesn't the army help moonbrook","спасет ли штормград луноречье","почему армия не помогает луноречью"}}},fp="9,275,13.594.0,17.406.1,27.252.0,42.229.0,41.266.0,40.245.0"}
P.entries["subzone:moonshrine-ruins"] = {n="Руины Лунного святилища",s="Руины Лунного святилища — затопленный комплекс древней архитектуры ночных эльфов в глубине Непроглядной Пучины. Когда-то здесь поклонялись Элуне, но теперь эти рушащиеся залы осквернены и захвачены культом Сумеречного Молота.",h="Руины Лунного святилища — затопленный комплекс древней архитектуры ночных эльфов в глубине Непроглядной...",kw={"aquanis","blackfathom","moonshrine","ruins","sanctum","threshadon","twilight's hammer","акванис","непроглядная пучина","лунное святилище","руины","алтарь","жесткозуб","сумеречный молот"},ang={["class:Shaman"]="Подчинение духов воды вроде барона Акваниса с помощью темных рунных камней показывает, насколько сильно Сумеречный Молот искажает и порабощает силы стихий.",["race:NightElf"]="Для любого ночного эльфа, спускающегося в глубины, видеть эти священные залы, посвященные Элуне, превращенными в затопленные руины, полные культистов, — горькая обида."},sec={{t="Затопленные залы Элуны",b="За огромным Прудом Аск'ара лежат Руины Лунного святилища — мрачное свидетельство древнего прошлого ночных эльфов на побережье Ясеневого леса. Эти частично затопленные залы когда-то звенели песнопениями во славу Богини Луны Элуны, но Великий Раскол разрушил храм и затопил его нижние уровни морской водой. Сегодня в мутных водах бродят дикие водные твари, от агрессивных крабов до змеевидных жесткозубов, а культ Сумеречного Молота по-прежнему занимает эти камни и творит темные ритуалы, глумящиеся над священным прошлым святилища."},{t="Стихийные глубины",b="Руины напрямую соединяются с Забытым прудом и Алтарем святилища Луны и служат культистам местом для призыва. Под поверхностью затопленных залов лежит древний рунический камень, связанный со стихиями. Через этот водный фокус Сумеречный Молот управляет водами глубин и призывает барона Акваниса, чудовищного элементаля воды, подчиненного их темным замыслам."}},faq={{q="Для чего изначально были построены Руины Лунного святилища?",a="Руины были частью огромного подземного храмового комплекса, посвященного богине ночных эльфов Элуне и возведенного до того, как Великий Раскол разорвал древний континент.",al={"moonshrine origins","who built moonshrine ruins","what is this place","происхождение лунного святилища","кто построил руины лунного святилища","что это за место"}},{q="Кто контролирует Руины Лунного святилища сейчас?",a="Руины кишат враждебными водными тварями, такими как жесткозубы и крабы-щелкуны, а также культистами Сумеречного Молота, захватившими весь затонувший комплекс.",al={"who is here","moonshrine mobs","twilights hammer blackfathom","кто здесь","враги руин лунного святилища","сумеречный молот непроглядная пучина"}},{q="Куда ведут Руины Лунного святилища?",a="Руины лежат за туннелями за Прудом Аск'ара. Из Руин Лунного святилища проходы ведут глубже, к Алтарю святилища Луны, и дают доступ к Забытому пруду.",al={"moonshrine exits","where does this go","path through ruins","выходы из руин лунного святилища","куда это ведет","путь через руины"}},{q="Кто такой барон Акванис?",a="Барон Акванис — могущественный элементаль воды, которого призывают прикосновением к погруженному рунному камню, скрытому в мутной воде под руинами. Он служит зловещим целям Сумеречного Молота.",al={"baron aquanis lore","underwater boss moonshrine","elemental in water","предания барона акваниса","подводный босс лунного святилища","элементаль в воде"}}},fp="16,234,22.564.0,20.402.1,52.185.0,38.186.0,35.189.0,21.183.0"}
P.entries["subzone:moonshrine-sanctum"] = {n="Алтарь святилища Луны",s="Алтарь святилища Луны — древнее эльфийское святилище в глубине Непроглядной Пучины, ныне служащее внутренним оплотом культа Сумеречного Молота. Им правит Повелитель сумрака Келрис, а в зале стоит нетронутый монумент королеве Азшаре, и он напрямую охраняет запечатанный вход в Логово Аку'май.",h="Алтарь святилища Луны — древнее эльфийское святилище в глубине Непроглядной Пучины, ныне служащее внутренним...",kw={"aku'mai","azshara","blackfathom","candles","kelris","moonshrine","sanctum","twilight's hammer","аку'май","азшара","непроглядная пучина","свечи","келрис","лунное святилище","алтарь","сумеречный молот"},ang={["class:Priest"]="Извращенные ритуалы, которые проводит в этом зале Повелитель сумрака Келрис, переворачивают священное служение: вместо исцеляющих молитв здесь звучит безумный шепот Бездны.",["race:NightElf"]="Видеть древний храм, высеченный вашими предками до Раскола, превращенным в жертвенную пещеру для Сумеречного Молота и нагов, — тошнотворное свидетельство наступающих теней Ясеневого леса."},sec={{t="Оскверненный храм",b="Алтарь святилища Луны находится сразу за затопленными Руинами Лунного святилища и является центром активности культистов в Непроглядной Пучине. Хотя ночные эльфы построили его тысячелетия назад в честь луны и своих правителей, теперь зал осквернен Сумеречным Молотом. Любопытно, что культисты бережно сохранили возвышающееся изваяние королевы Азшары, чувствуя родство со змеевидными нагами, служащими тем же темным подводным владыкам. Под бдительным взглядом Повелителя сумрака Келриса под сводами пещеры день и ночь звучат песнопения темных ритуалов."},{t="Порог Аку'май",b="Алтарь служит последним рубежом перед Логовом Аку'май. Тяжелые двойные каменные двери запечатывают чудовищную гидру, удерживаемую древними охранными чарами. Вокруг центральной статуи Азшары стоят четыре ритуальные жаровни, которые нужно зажечь, чтобы снять печать. Это тревожит спящих стражей святилища — полчища гигантских крабов, черепах с острыми челюстями, бронированных макура и призванных элементалей воды, обязанных защищать алтарь от неосторожных чужаков."}},faq={{q="Где находится Алтарь святилища Луны?",a="Алтарь святилища Луны находится в глубине подземелья Непроглядная Пучина на Зорамском взморье в Ясеневом лесу. Он лежит сразу за затопленными Руинами Лунного святилища, непосредственно перед логовом гидры Аку'май.",al={"moonshrine sanctum location","where is moonshrine sanctum","bfd sanctum","где алтарь святилища луны","расположение алтаря святилища луны","алтарь непроглядная пучина"}},{q="Кто правит Алтарем святилища Луны?",a="Алтарем управляет Повелитель сумрака Келрис — грозный чародей культа Сумеречного Молота, плетущий сон и проводящий ритуалы в честь их древнего покровителя, затронутого Пустотой.",al={"who leads here","boss of moonshrine sanctum","who runs the sanctum","кто здесь главный","босс алтаря святилища луны","кто управляет алтарем"}},{q="Почему здесь стоит целая статуя Азшары?",a="Алтарь изначально был древним эльфийским храмом, посвященным королеве Азшаре до Великого Раскола. Сумеречный Молот хранит изваяние в безупречном виде, потому что культ напрямую заодно с нагами Азшары в глубинах.",al={"azshara statue","why statue of azshara","naga statue bfd","статуя азшары","почему статуя азшары","статуя нагов непроглядная пучина"}},{q="Как открыть большие двери в глубине зала?",a="Чтобы открыть двери в Логово Аку'май, искателям приключений нужно зажечь четыре ритуальные свечи у подножия статуи Азшары. Каждая зажженная свеча пробуждает волны стражей — водных тварей и элементалей воды, которых нужно одолеть.",al={"how to open bfd doors","akumai door open","light candles bfd","как открыть двери непроглядной пучины","открыть дверь аку'май","зажечь свечи"}}},fp="18,295,19.587.0,24.469.1,32.213.0,38.179.0,46.247.0,59.240.0"}
P.entries["subzone:moonspray"] = {n="Лунные Брызги",s="«Лунные Брызги» — транспортный корабль Альянса, принадлежащий флоту кальдораев. Он обеспечивает важное морское сообщение через воды, отделяющие материковый Калимдор от великого Мирового Древа Тельдрассила.",h="«Лунные Брызги» — транспортный корабль Альянса, принадлежащий флоту кальдораев.",kw={"auberdine","boat","darkshore","ferry","kaldorei fleet","moonspray","rut'theran village","teldrassil","transport","аубердин","корабль","темные берега","паром","флот кальдораев","лунные брызги","деревня рут'теран","тельдрассил","транспорт"},ang={["faction:Alliance"]="«Лунные Брызги» — ключевое транспортное звено, соединяющее главный прибрежный узел Альянса на севере Калимдора с изолированной столицей Дарнассом.",["race:NightElf"]="Для молодых ночных эльфов, покидающих Тельдрассил, чтобы узнать большой мир, «Лунные Брызги» нередко становятся тем самым кораблем, который впервые увозит их из уединенного дома на материк."},sec={{t="Важная островная переправа",b="«Лунные Брызги» — важнейшая связующая нить между причалами Аубердина на побережье Темных берегов и деревней Рут'теран у корней Тельдрассила. Пересекая Сокрытое Море, судно перевозит искателей приключений, гонцов и необходимые припасы между уединенным убежищем ночных эльфов в кроне Мирового Древа и древним материком Калимдора."}},faq={{q="Куда плывут «Лунные Брызги»?",a="«Лунные Брызги» ходят между портовым городом Аубердин в Темных берегах и Деревней Рут'теран, расположенной у океанского основания Тельдрассила.",al={"moonspray route","where does moonspray go","moonspray destination","маршрут лунных брызг","куда плывут лунные брызги","пункт назначения лунных брызг"}},{q="Кому принадлежит этот корабль и кто им управляет?",a="«Лунные Брызги» — корабль ночных эльфов, входящий во флот кальдораев и плавающий под знаменем Альянса.",al={"who sails the moonspray","kaldorei fleet moonspray","is moonspray alliance","кто управляет лунными брызгами","флот кальдораев лунные брызги","лунные брызги альянс"}},{q="Почему этот паромный маршрут важен?",a="Тельдрассил — остров, высоко вознесшийся над морем у северо-западного побережья Калимдора. Корабли вроде «Лунных Брызг» — главный способ переправлять войска, припасы и путников через воду на материк.",al={"why take moonspray","teldrassil boat","зачем плыть на лунных брызгах","корабль в тельдрассил"}}},fp="9,203,20.354.0,32.139.0,32.120.0,34.218.0"}
P.entries["subzone:moonwell-ashenvale"] = {n="Лунный колодец (Ясеневый лес)",s="Это уединенное святилище, известное у ночных эльфов как Лунный колодец Чистоты, находится в центре Ясеневого леса, к востоку от Озера Ирис и к западу от Приюта в Ночных Лесах. Его благословенные воды несут милость Элуны, питая древний лес и очищая землю от подступающей скверны. Путники Альянса и стражи-ночные эльфы часто приходят к его тихой купели, чтобы очистить оскверненные предметы, найденные в лесу.",h="Это уединенное святилище, известное у ночных эльфов как Лунный колодец Чистоты, находится в центре Ясеневого...",kw={"ashenvale","cleansing","elune","iris lake","moonwell","moonwell of purity","raynewood retreat","ясеневый лес","очищение","элуна","озеро ирис","лунный колодец","лунный колодец чистоты","приют в ночных лесах"},ang={["profession:Tailoring"]="Портные могут использовать плотную лунную энергию, скопившуюся в водах, чтобы создавать чистую луноткань из ткани Скверны.",["race:NightElf"]="Для кальдораев каждый лунный колодец — священный второй дом, одновременно духовный источник милости Элуны и передовой оплот против демонической скверны, угрожающей Ясеневому лесу."},sec={{t="Святилище чистоты",b="Этот лунный колодец, укрытый под пологом центральной части Ясеневого леса, служит духовным якорем для кальдораев. Его светящиеся воды черпают скрытую магию природы и свет Богини Луны. Пока окружающий лес страдает от скверны сатиров, магии Скверны и вторжений лесорубов, такие чистые святилища становятся жизненно важными опорами для тех, кто пытается исцелить леса."},{t="Исцеление леса",b="Купель служит очищающим источником в попытках восстановить оскверненные реликвии. Искатели приключений, помогающие Раэне Волкопас, приходят сюда, чтобы погрузить в воду оскверненные обломки жезла, используя нетронутую лунную энергию, чтобы изгнать скверну там, где обычные средства бессильны."}},faq={{q="Как называется этот лунный колодец?",a="Это место известно как Лунный колодец Чистоты. Это один из нескольких лунных колодцев Ясеневого леса, расположенный к востоку от Озера Ирис и к западу от Приюта в Ночных Лесах.",al={"which moonwell is this","moonwell name","moonwell of purity","какой это лунный колодец","название лунного колодца","лунный колодец чистоты"}},{q="Для чего используются лунные колодцы?",a="Лунные колодцы — священные купели, посвященные Элуне, в которых лунная сила сочетается с магией природы. Ночные эльфы используют их, чтобы поддерживать жизнь земли, восстанавливать духовные силы и очищать предметы, оскверненные темными или демоническими силами.",al={"what does a moonwell do","moonwell purpose","why moonwells exist","что делает лунный колодец","назначение лунного колодца","зачем нужны лунные колодцы"}},{q="Почему искатели приключений Альянса приходят к этому лунному колодцу?",a="Героев Альянса направляют сюда при очищении оскверненных реликвий, найденных в лесу, например в ходе расследований, которые ведет Раэна Волкопас из Астранаара.",al={"raene's cleansing moonwell","why come here","cleanse rod here","лунный колодец раэны","зачем приходить сюда","очистить жезл здесь"}}},fp="20,400,19.380.0,16.245.1,38.151.0,28.225.0,48.182.0"}
P.entries["subzone:mor-shan-rampart"] = {n="Застава Мор'шан",s="Застава Мор'шан — сильно укрепленный оплот Орды на северной границе Степей, охраняющий вход в Ясеневый лес. Ее возвел главным образом клан Песни Войны: застава защищает земли Орды от ответных ударов ночных эльфов и служит плацдармом для вылазок вглубь леса.",h="Застава Мор'шан — сильно укрепленный оплот Орды на северной границе Степей, охраняющий вход в Ясеневый лес.",kw={"ashenvale","barrens","gold road","mor'shan rampart","morshan","warsong clan","warsong outriders","ясеневый лес","степи","золотой путь","застава мор'шан","мор'шан","клан песни войны","всадники песни войны"},ang={["faction:Alliance"]="Бойцы Альянса видят в Заставе Мор'шан агрессивную баррикаду, возведенную лесорубами Орды, чтобы защищать захваченные земли и устраивать набеги на Ясеневый лес.",["faction:Horde"]="Для Орды Застава — главные сухопутные врата, защищающие сердце Степей от вторжений ночных эльфов и обеспечивающие бесперебойное снабжение лесозаготовок в Ясеневом лесу."},sec={{t="Северные врата",b="Застава Мор'шан стоит на северном конце Золотого Пути и отмечает переход от сухих равнин Степей к древним кронам Ясеневого леса. Этот оплот из тяжелых бревен, оборонительных палисадов и укрепленных сторожевых башен возвели, чтобы сдержать ответные удары ночных эльфов, возмущенных вырубкой лесов Ордой. Он служит и щитом, охраняющим северные врата во внутренние земли Калимдора, и передовым пунктом для рейдовых отрядов, идущих на север к Астранаару."},{t="Застава Песни Войны",b="Заставу населяют в основном закаленные в боях воины клана Песни Войны, и она всегда находится в боевой готовности. С этих брустверов часовые следят за опушкой, высматривая разведчиков и лучников ночных эльфов, и поддерживают связь между передовыми постами Ясеневого леса и крупными поселениями Орды на юге."}},faq={{q="Что такое Застава Мор'шан?",a="Это укрепленный пограничный пост Орды на стыке Степей и Ясеневого леса. Его построили, чтобы не допустить в Степи ответные удары Альянса и охранять северный конец Золотого Пути.",al={"morshan rampart","what is this barricade","northern barrens gate","застава мор'шан","что это за баррикада","северные врата степей"}},{q="Кто контролирует это укрепление?",a="В укреплении стоит гарнизон Орды — воины и часовые клана Песни Войны. Они поддерживают сторожевые башни и палисады вдоль границы леса.",al={"who holds morshan","who guards the rampart","morshan defenders","кто держит мор'шан","кто охраняет заставу","защитники мор'шан"}},{q="Почему застава расположена здесь, а не глубже в Ясеневом лесу?",a="Она закрывает северный конец Золотого Пути — главный сухопутный путь между центральными Степями и Ясеневым лесом. Контроль над этим узким проходом не дает ночным эльфам легко прорваться на юг, в сердце земель Орды.",al={"why build ramparts here","strategic importance morshan","зачем строить заставу здесь","стратегическое значение мор'шан"}},{q="Могут ли путники из Альянса безопасно пройти через заставу?",a="Нет. Застава — действующий военный пост Орды. Путников из Альянса, подходящих со стороны Ясеневого леса или Степей, стражи атакуют сразу же.",al={"can alliance pass","alliance crossing morshan","может ли альянс пройти","проход альянса через мор'шан"}}},fp="16,318,17.523.0,15.337.0,29.205.0,32.173.0,55.251.0,55.172.0"}
P.entries["subzone:morgan-s-vigil"] = {n="Дозор Моргана",s="Дозор Моргана — разрушенный оплот Альянса на юго-восточных высотах Пылающих степей. Когда-то это была небольшая деревня; теперь ее обгоревшие дома и разбитая башня мага служат суровым передовым лагерем для разведчиков, наблюдающих за проходами к Черной горе. Это единственный опорный пункт Альянса в задыхающемся от пепла краю, где господствуют дворфы Черного Железа и орки Черной Горы.",h="Дозор Моргана — разрушенный оплот Альянса на юго-восточных высотах Пылающих степей.",kw={"alliance outpost","blackrock mountain","burning steppes","gryphon master","mage tower","morgans vigil","ruins","форпост альянса","черная гора","пылающие степи","распорядитель полетов на грифонах","башня мага","дозор моргана","руины"},ang={["faction:Alliance"]="Этот потрепанный утес — ваше единственное безопасное убежище в Пылающих степях: отсюда есть прямой перелет в Штормград, и здесь собирается сопротивление угрозам Черного Железа и Черной Горы.",["race:Human"]="Удержание этого хребта не дает ужасам, рожденным под Черной горой, беспрепятственно хлынуть через проход в уязвимые долины Красногорья и к сердцу Штормграда."},sec={{t="Последний очаг в Степях",b="Дозор Моргана, расположенный на высокой скале над огненными пустошами, был скромным поселением, пока ужасы Пылающих степей не захлестнули его. Сегодня обугленные балки и треснувший остов разрушенной башни мага напоминают о нашествии. Уцелевшие защитники ютятся в грубых палатках среди сажи. Несмотря на разруху, в лагере есть гнездовье грифонов, дающее прямое воздушное сообщение через горы со Штормградом. Это крайне нужное убежище, где разведчики, маршалы и странствующие искатели приключений переводят дух вдали от рыскающих внизу военных отрядов."},{t="Долгий дозор",b="Форпост получил название и предназначение от бдительности, с которой следят за нависшей угрозой Черной горы. Поскольку клан Черного Железа погружается в темное чародейство, а орки Черной Горы занимают окрестные пустоши, лагерь служит передовым плацдармом. Его защитники поддерживают оборону лагеря, координируют разведывательные вылазки по пеплу и охраняют важный проход на юг, в Красногорье."}},faq={{q="Что случилось со здешними постройками?",a="Дома и другие постройки деревни сожжены дотла, а башня магов лежит в руинах. Выжившие жители ютятся в палатках среди развалин. Кто повинен в разрушении, неизвестно.",al={"why is morgans vigil burned","ruins at morgans vigil","who destroyed morgans vigil","почему дозор моргана сожжен","руины дозора моргана","кто разрушил дозор моргана"}},{q="Кто такой Морган?",a="Морган — женщина, в честь которой назван дозор. Среди защитников, находящихся сейчас в лагере, ее нет.",al={"who is morgan","morgans vigil namesake","where is morgan","кто такой морган","в честь кого дозор моргана","где морган"}},{q="Зачем Альянс содержит этот лагерь?",a="Это единственный укрепленный наблюдательный пункт Альянса в Пылающих степях: он охраняет северный проход в Красногорье и следит за передвижением войск вокруг Черной горы, а снабжение и подкрепления получает прямо из Штормграда.",al={"why alliance here","morgans vigil purpose","why keep morgans vigil","зачем здесь альянс","назначение дозора моргана","зачем держать дозор моргана"}},{q="Как добраться до Дозора Моргана и обратно?",a="На форпосте есть распорядитель полетов Альянса на грифонах с прямыми рейсами в Штормград и Лагерь Братства Тория в Тлеющем ущелье.",al={"morgans vigil flight master","how to get to morgans vigil","flight paths morgans vigil","распорядитель полетов дозор моргана","как добраться до дозора моргана","маршруты полета дозор моргана"}},{q="Безопасен ли Дозор Моргана от нападений?",a="Его усиленно охраняют часовые Альянса, но по периметру постоянно бродят звери, огненные элементали и орки-налетчики, таящиеся сразу за гребнем.",al={"is morgans vigil contested","can horde enter morgans vigil","safe zone","оспаривается ли дозор моргана","может ли орда войти в дозор моргана","безопасная зона"}}},fp="14,374,30.620.0,14.408.0,36.238.0,14.114.0,41.259.0,44.130.0,35.171.0"}
P.entries["subzone:morlos-aran"] = {n="Морлос'Аран",s="Морлос'Аран — древние руины ночных эльфов на юге Оскверненного леса. Когда-то гордое процветающее поселение до Великого Раскола, теперь он стоит мрачным памятником утраченному золотому веку, погребенным под демонической скверной, поражающей окрестный лес.",h="Морлос'Аран — древние руины ночных эльфов на юге Оскверненного леса.",kw={"ameth'aran","bashal'aran","felwood","kaldorei","morlos aran","morlos'aran","ruins","sundering","амет'аран","башал'аран","оскверненный лес","кальдораи","морлос'аран","руины","раскол"},ang={["class:Druid"]="Искореженная земля вокруг разрушенных основ показывает, какой огромный урон нанесен Оскверненному лесу, и подстегивает усилия Кенария по очищению этих земель.",["race:NightElf"]="Путь через Морлос'Аран трагически напоминает, как низко пала империя: священная древняя кладка поглощена мерзкой демонической скверной Легиона."},sec={{t="Отголоски золотого века",b="Десять тысяч лет назад, до Раскола, Морлос'Аран был великим городским центром древней цивилизации кальдораев. Как и родственные поселения Амет'Аран, Башал'Аран и Ордил'Аран на севере Калимдора, его мраморные арки и залитые лунным светом площади кипели эльфийской жизнью и магией. Когда Источник Вечности рухнул, город раскололся, оставив лишь разбитые колоннады как памятники расцвета их цивилизации."},{t="Оскверненная реликвия",b="Пока соседние руины в Темных берегах и Ясеневом лесу приходили в упадок и зарастали, Морлос'Аран во время Третьей войны постигла куда более мрачная участь. Расположенные прямо на пути, истоптанном Пылающим Легионом, его уцелевшие основания были задушены демонической порчей и ядовитой топью. Сегодня руины населяют бродячие звери, оскверненные элементали и остатки темных сил, задержавшихся в Оскверненном лесу."}},faq={{q="Чем изначально был Морлос'Аран?",a="Это было крупное поселение ночных эльфов, процветавшее до Великого Раскола. Вместе с родственными городами древнего Калимдора оно входило в ядро цивилизации золотого века кальдораев, прежде чем десять тысяч лет назад пало.",al={"what is morlos aran","morlos'aran history","who built morlos aran","что такое морлос'аран","история морлос'аран","кто построил морлос'аран"}},{q="Почему название оканчивается на «Аран»?",a="Этот суффикс встречается в нескольких городах ночных эльфов эпохи до Раскола, включая Амет'Аран и Башал'Аран на Темных берегах, Ордил'Аран в Ясеневом лесу и Тетрис'Аран в Пустошах. Он обозначает поселения, построенные во времена древней империи.",al={"meaning of aran","aran suffix","ameth aran connection","значение аран","суффикс аран","связь с амет'аран"}},{q="Где именно находится Морлос'Аран?",a="Он лежит на юге Оскверненного леса, близ пограничного перехода из Ясеневого леса. Его рушащиеся мраморные постройки видны среди оскверненных, иссохших деревьев недалеко от главной дороги.",al={"morlos aran location","where is morlos'aran","finding morlos aran","где морлос'аран","расположение морлос'аран","как найти морлос'аран"}},{q="Какие опасности бродят в этих руинах сегодня?",a="Оскверненные животные, порченые древни и остатки демонической нечисти наводняют окрестный лес и делают Морлос'Аран крайне опасным для путников, идущих на север по Оскверненному лесу.",al={"what is inside morlos'aran","morlos aran mobs","dangers of morlos aran","что внутри морлос'аран","монстры морлос'аран","опасности морлос'аран"}}},fp="11,274,24.437.0,16.413.0,32.242.0,33.223.0,37.193.0,38.185.0"}
P.entries["subzone:mosh-ogg-ogre-mound"] = {n="Холм Мош'Огг",s="Холм Мош'Огг — укрепленный пещерный комплекс на севере Тернистой долины, к югу от руин Зул'Гуруба. Это главный оплот свирепого племени Мош'Огг в джунглях, где правит безжалостный вождь, огр-маг Май'Зот. Задолго до того, как здесь поселились огры, холм был священным местом со святилищем, посвященным лоа Луку.",h="Холм Мош'Огг — укрепленный пещерный комплекс на севере Тернистой долины, к югу от руин Зул'Гуруба.",kw={"lukou","mai'zoth","mind's eye","mosh'ogg","mound","ogre","stranglethorn","zul'gurub","луку","май'зот","око разума","мош'огг","холм","огры","тернистая долина","зул'гуруб"},ang={["class:Mage"]="Огр-маг Май'Зот владеет Оком разума в глубине холма и обладает необузданной тайной энергией, необычной для грубых огров.",["race:Troll"]="В пещере некогда находилось почитаемое святилище лоа исцеления Луку, но поклонение угасло после того, как ваш народ был вынужден покинуть исконные земли в джунглях."},sec={{t="Логово огров и древней веры",b="Холм Мош'Огг, вырубленный в неровных гребнях джунглей к югу от Зул'Гуруба, кишит грубыми дробителями, шаманами и поджигателями войны из племени Мош'Огг. Огры заняли сеть пещер как удобное убежище от враждебных троллей джунглей и бродячих зверей. Но под грубостью их поселения скрыта более древняя история: до того как племя Черного Копья покинуло южные джунгли, эта пещера была священной полостью со святилищем Луку, лоа исцеления и жизни. Когда тролли ушли, святилище пришло в запустение, и огры завладели подземным лабиринтом."},{t="Май'Зот и Око разума",b="В глубине извилистых недр холма правит Май'Зот, грозный двухголовый огр-маг, повелевающий кланом Мош'Огг. У него хранится Око разума — мощная и опасная магическая реликвия, усиливающая его власть над разумом и колдовством его приспешников. Мастерство Май'Зота в магии и грубая сила делают путь в самые глубины холма опасным для любого путника на севере Тернистой долины."}},faq={{q="Кто живет на Холме Мош'Огг?",a="Холм населяет племя огров Мош'Огг: воины, дробители, шаманы и поджигатели войны. Ими правит из глубины пещеры их вождь, двухголовый огр-маг Май'Зот.",al={"who is in the mound","mosh'ogg inhabitants","ogre mound monsters","кто на холме","обитатели мош'огг","монстры холма огров"}},{q="Что такое Око разума?",a="Око разума — мощный магический артефакт, которым владеет в холме огр-маг Май'Зот. Его странная тайная сила питает его колдовство и власть над местными ограми.",al={"what does mai'zoth have","mind's eye relic","minds eye","что есть у май'зота","реликвия око разума","око разума"}},{q="Для чего использовался холм до прихода огров?",a="До прихода огров пещера была местом поклонения со святилищем Луку, лоа исцеления. Его почитали главным образом тролли джунглей, включая племя Черного Копья, до того как покинули Тернистую долину.",al={"mound history","lukou shrine","troll cave history","история холма","святилище луку","история пещеры троллей"}},{q="Где находится холм?",a="Холм расположен на севере Тернистой долины, среди холмов к югу от входа в троллий город Зул'Гуруб.",al={"where is mosh'ogg ogre mound","ogre mound location","how to find ogre mound","где холм мош'огг","расположение холма огров","как найти холм огров"}}},fp="19,389,32.606.0,27.425.0,37.204.0,23.172.0,54.222.0,27.133.0"}
P.entries["subzone:mosshide-fen"] = {n="Болото Мохошкуров",s="Болото Мохошкуров — топкая, коварная местность на востоке Болотины, захваченная племенем гноллов Мохошкур. Усеянная примитивными стоянками, она одна из самых опасных областей для путников, сошедших с главных торговых дорог.",h="Болото Мохошкуров — топкая, коварная местность на востоке Болотины, захваченная племенем гноллов Мохошкур.",kw={"gnawbone","gnolls","marshlands","mosshide","mosshide fen","wetlands","грызикост","гноллы","топи","мохошкуры","болото мохошкуров","болотина"},ang={["race:Dwarf"]="Горцам Стальгорна приходится постоянно следить за Болотом Мохошкуров, ведь агрессивные стаи гноллов угрожают старателям, обшаривающим топи, и разведчикам, охраняющим восточные тропы."},sec={{t="Владения стаи",b="Болото Мохошкуров раскинулось на мутных восточных окраинах Болотины и служит главным владением агрессивных гноллов Мохошкур. Здесь болото густое и запутанное, усеянное грубыми шалашами и лагерями, заваленными костями. Под жестоким началом вожаков вроде Грызикоста гноллы яростно охраняют свои топи и без колебаний нападают из засады на любых путников, разведчиков и старателей, неосторожно забредших на их охотничьи земли, и пожирают их."}},faq={{q="Что такое Болото Мохошкуров?",a="Болото Мохошкуров — местность на востоке Болотины. Это сырые топи, целиком занятые и заселенные гноллами Мохошкур.",al={"mosshide fen lore","what is this place","mosshide swamp","предания болота мохошкуров","что это за место","болото мохошкур"}},{q="Кто правит Болотом Мохошкуров?",a="Болото занимает племя гноллов Мохошкур, подчиняющееся жестоким вожакам вроде Грызикоста, который приказывает своей стае захватывать и пожирать любых чужаков, вторгшихся на их землю.",al={"who leads the gnolls here","gnawbone","mosshide leader","кто правит гноллами здесь","грызикост","вожак мохошкуров"}},{q="Чем эта местность опасна для путников?",a="Гноллы Болота Мохошкуров известны агрессией и хищным аппетитом. Путники, сошедшие с проторенных троп или ищущие припасы в сырых зарослях, рискуют попасть во внезапную засаду бродячих охотничьих стай.",al={"why is it dangerous","fen dangers","почему опасно","опасности болота"}}},fp="12,228,21.449.0,21.144.0,23.179.0,40.222.0"}
P.entries["subzone:mystic-ward"] = {s="Мистический квартал — северо-западный район Стальгорна, тихое убежище дворфийской столицы для духовного служения и изучения тайных искусств. Его легко узнать по прохладным бледно-голубым знаменам и безмолвным залам, что резко контрастирует с гулом наковален неподалеку, в Великой кузне. Самое величественное здание квартала — Зал Тайн — собирает жрецов, паладинов и магов под сводами огромных каменных арок.",h="Мистический квартал — северо-западный район Стальгорна, тихое убежище дворфийской столицы для духовного...",kw={"hall of mysteries","ironforge","longberrys reagents","maevas mystical apparel","mage trainer","mystic ward","priest trainer","the fighting wizard","зал тайн","стальгорн","реагенты лонгберри","мистические одеяния маевы","учитель магов","мистический квартал","учитель жрецов","боевой волшебник"},ang={["class:Mage"]="Для заклинателей Альянса Мистический квартал — главный центр в Каз Модане для тайных припасов, томов заклинаний и углубленного обучения вне академий Штормграда.",["class:Priest"]="Квартал и его величественный Зал Тайн — мирное убежище, где дворфы и гости, практикующие Свет, собираются для молитвы, наставления и единения."},sec={{t="Убежище веры и магии",b="Хотя дворфы известны по всему Азероту мастерством в кузнечном деле и на поле боя, Мистический квартал воплощает более тихие интеллектуальные и духовные устремления королевства. Этот пещерный квартал с бледно-голубыми гербами соединяет шумный Общинный квартал с Одинокой пещерой и Великой кузней. Здесь торговцы снабжают ученых и заклинателей облачениями, свитками и алхимическими реагентами в лавках вроде «Боевой волшебник» и «Мистические одеяния Маевы». Над районом возвышается величественный Зал Тайн, где священные учения Света пересекаются с отточенными искусствами тайной магии и наставляют тех, кто владеет незримыми силами на защиту Альянса."}},faq={{q="Для чего служит Мистический квартал?",a="Мистический квартал — район Стальгорна, отведенный тайной магии, научным изысканиям и духовному служению. Здесь есть товары для заклинателей, лавки реагентов и места обучения паладинов, жрецов и магов.",al={"purpose of mystic ward","what happens here","mystic ward role","назначение мистического квартала","что здесь происходит","роль мистического квартала"}},{q="Какое главное здание в Мистическом квартале?",a="Центр района — Зал Тайн, величественный сводчатый чертог, где расположены учителя священных и тайных заклинателей столицы, а также заметный декоративный пруд.",al={"hall of mysteries","big temple","mystic ward building","зал тайн","большой храм","здание мистического квартала"}},{q="Почему знамена в этом квартале бледно-голубые?",a="Стальгорн использует особую геральдику, чтобы различать районы города. Если над Военным кварталом реют боевые красные знамена, а Великая кузня отмечена огненно-оранжевым, то Мистический квартал несет бледно-голубые знамена, символизирующие размышление, мудрость и изучение магии.",al={"blue banners ironforge","why blue flags","голубые знамена стальгорн","почему голубые флаги"}},{q="Куда ведет Мистический квартал?",a="Квартал находится в северо-западной части города. Проходы соединяют его на юге с Общинным кварталом, на юго-востоке с Великой кузней, а на востоке напрямую с Одинокой пещерой.",al={"mystic ward connections","how to get to mystic ward","связи мистического квартала","как пройти в мистический квартал"}}},fp="11,406,32.715.0,33.214.0,45.179.0,43.248.0,32.174.0"}
P.entries["subzone:mystral-lake"] = {n="Озеро Мистраль",s="Озеро Мистраль — самый большой водоем Ясеневого леса, лежащий в центре юга леса, чуть ниже Приюта Серебряного Ветра. Когда-то это было тихое убежище под охраной водных элементалей, верных ночным эльфам, но теперь его воды опасны из-за порчи местных элементалей.",h="Озеро Мистраль — самый большой водоем Ясеневого леса, лежащий в центре юга леса, чуть ниже Приюта Серебряного...",kw={"ashenvale","call of water","lake mystral","mystral lake","sarilus foulborne","silverwind refuge","water elementals","ясеневый лес","зов воды","озеро мистраль","сарилус грязнорожденный","приют серебряного ветра","водные элементали"},ang={["class:Shaman"]="Бурные глубины Озера Мистраль — важная остановка на пути Зова Воды, где начинающие шаманы должны встретиться с местными духами, чтобы овладеть стихийным мастерством.",["race:NightElf"]="Некогда дом мирных стражей, союзных вашему народу, озеро остается горьким напоминанием о внешней порче, вторгающейся в священные рощи Ясеневого леса."},sec={{t="Оскверненное убежище",b="Озеро Мистраль, раскинувшееся к югу от Приюта Серебряного Ветра и к востоку от Долины Когтя, издавна ценилось кальдораями за чистые воды и мирных элементалей-стражей. Однако темное вмешательство нарушило этот древний покой. Маг-отступник Сарилус Грязнорожденный обратил свои чары на водных духов озера и превратил их во враждебных, жестоких существ. Сегодня путники и Орды, и Альянса нередко оказываются на этих неспокойных берегах и сталкиваются с гневом духов, некогда оберегавших лес."},{t="Духовный перекресток",b="Помимо порчи, тревожащей местных ночных эльфов, Озеро Мистраль привлекает внимание представителей обеих фракций. Шаманы Орды, идущие путем общения со стихиями, ищут его глубокие воды во время испытаний, чтобы постичь стихию воды. Несмотря на порчу, поразившую его духов-стражей, изначальный отклик озера делает его важным местом паломничества для тех, кто учится подчинять приливных духов и уважать их."}},faq={{q="Где находится Озеро Мистраль?",a="Озеро Мистраль лежит в центре юга Ясеневого леса. Оно расположено прямо к югу от Приюта Серебряного Ветра и к востоку от Долины Когтя и является самым большим открытым водоемом в лесу.",al={"where is mystral lake","mystral lake location","lake mystral map","где озеро мистраль","расположение озера мистраль","карта озера мистраль"}},{q="Почему здешние водные элементали враждебны?",a="Водные элементали были изначально мирными и верными ночным эльфам Ясеневого леса. Но маг-отступник Сарилус Грязнорожденный испортил их, превратив их мягкую природу в неутомимую враждебность ко всем, кто приближается к озеру.",al={"why are water elementals attacking","corrupted water elementals","who corrupted mystral lake","почему нападают водные элементали","оскверненные водные элементали","кто осквернил озеро мистраль"}},{q="Почему шаманы посещают Озеро Мистраль?",a="Шаманов Орды направляют к Озеру Мистраль во время духовных испытаний Зова Воды. Озеро обладает глубоким стихийным резонансом, поэтому это важное место для постижения духов воды и настройки на них.",al={"call of water mystral lake","shaman quest mystral lake","зов воды озеро мистраль","задание шамана озеро мистраль"}},{q="Кто контролирует Озеро Мистраль?",a="Ни одна из фракций не держит самого озера под прямым военным контролем. Ночные эльфы наблюдают за ним из ближних застав вроде Приюта Серебряного Ветра, но враждебные оскверненные элементали сейчас господствуют над водами и угрожают как Альянсу, так и Орде.",al={"is mystral lake horde or alliance","who owns mystral lake","озеро мистраль орды или альянса","кому принадлежит озеро мистраль"}}},fp="12,287,21.554.0,20.429.0,30.173.0,42.241.0,33.222.0,26.259.0"}
P.entries["subzone:nat-s-landing"] = {n="Лагерь Ната",s="Лагерь Ната — скромная рыбацкая стоянка на берегу Пылевой бухты в Пылевых топях. Это личный лагерь и убежище Ната Пэгла, которого многие считают самым известным рыболовом Азерота. Искатели приключений со всего мира приходят к этому неприметному причалу, чтобы довести свое мастерство рыбной ловли до совершенства.",h="Лагерь Ната — скромная рыбацкая стоянка на берегу Пылевой бухты в Пылевых топях.",kw={"angler","dock","dustwallow bay","dustwallow marsh","fishing","nat pagle","nats landing","theramore","рыболов","причал","пылевая бухта","пылевые топи","рыбная ловля","нат пэгл","лагерь ната","терамор"},ang={["faction:Alliance"]="Для граждан Альянса, расквартированных в Тераморе, Лагерь Ната — недолгая тихая прогулка вдоль берега, дающая легкий доступ к лучшему рыболову мира.",["faction:Horde"]="Рыболовы Орды, пробравшиеся через опасное болото из Степей, обнаружат, что Нату нет дела до войны: он судит гостей лишь по качеству заброса."},sec={{t="Приют мастера",b="Лагерь Ната скрыт к юго-западу от Острова Терамор у мутных вод Пылевой бухты и представляет собой лишь потрепанную стоянку. Здесь есть простая парусиновая палатка, сушилки, увешанные дневным уловом, запасные снасти на деревьях и шаткий деревянный пирс, выдающийся в бухту. Несмотря на туманы и опасности болот, этот тихий участок берега дает легендарному рыболову Нату Пэглу уединенное место, где можно забросить удочку и спокойно выпить вдали от городского шума."},{t="Паломничество рыбаков",b="Хотя с виду лагерь неприметен, он — важная остановка для начинающих рыболовов. Рыбаков, исчерпавших знания обычных наставников в Стальгорне, Оргриммаре и других местах, направляют сюда, чтобы они доказали свое мастерство самому Нату. Пэглу нет дела до политики и дрязг фракций; любой рыболов, преодолевший хищников болот и добравшийся до его причала, должен показать терпение и умение в самых опасных водах мира, чтобы получить высшее обучение."}},faq={{q="Где находится Лагерь Ната?",a="Лагерь Ната расположен на небольшом прибрежном выступе у вод Пылевой бухты, в восточной части Пылевых топей, к юго-западу от Острова Терамор.",al={"where is nats landing","nats landing location","how to get to nats landing","где лагерь ната","расположение лагеря ната","как добраться до лагеря ната"}},{q="Кто живет в Лагере Ната?",a="Лагерь — личная стоянка Ната Пэгла, известного рыболова-человека, который целыми днями ловит рыбу с пирса, держа в руке напиток.",al={"who is at nats landing","nats landing npc","who lives here","кто в лагере ната","персонаж лагеря ната","кто здесь живет"}},{q="Почему рыболовы приходят сюда?",a="Когда рыболовы усвоили все, чему могут научить местные наставники в столицах, их направляют к Нату Пэглу. Он проверяет их упорство трудными уловами по всему миру, а затем дает обучение ранга искусника.",al={"why come to nats landing","artisan fishing trainer","nat pagle training","зачем идти в лагерь ната","наставник рыбной ловли искусник","обучение у ната пэгла"}},{q="Принимает ли Нат Пэгл и Альянс, и Орду?",a="Да. Нат Пэгл нейтрален к увлеченным рыболовам и принимает как путников Альянса из Терамора, так и путников Орды, приходящих из Степей, независимо от их верности фракциям.",al={"is nats landing hostile","can horde talk to nat","is nat pagle neutral","враждебен ли лагерь ната","может ли орда говорить с натом","нейтрален ли нат пэгл"}}},fp="13,320,16.503.0,26.473.0,31.167.0,27.139.0,27.229.0,47.184.0"}
P.entries["subzone:nek-mani-wellspring"] = {n="Родник Нек'Мани",s="Родник Нек'Мани, расположенный высоко в скалах над Южным Гибельным берегом, хранит источник удивительно чистой святой воды. Он славится как единственный нетронутый источник пресной воды к югу от Сумеречного леса. Однако недавно это священное место захватили враждебные исследователи-наги, ревниво охраняющие его воды.",h="Родник Нек'Мани, расположенный высоко в скалах над Южным Гибельным берегом, хранит источник удивительно...",kw={"holy spring","holy water","naga","nek'mani","savage coast","stranglethorn","wellspring","святой родник","святая вода","наги","нек'мани","гибельный берег","тернистая долина","родник"},ang={["class:Priest"]="Утверждения о божественном происхождении вод Нек'Мани делают его предметом любопытства для жрецов, хотя споры о том, какой вере он принадлежит, остаются давней научной тяжбой."},sec={{t="Священная чаша",b="Родник Нек'Мани спрятан среди изрезанных прибрежных круч западной части Тернистой долины. Это единственный источник неоскверненной пресной воды к югу от Сумеречного леса, и многие ученые и паломники считают его святым. Поскольку разные культуры и традиции утверждают, что его божественные воды были благословлены именно для их народа, он остается предметом острого богословского интереса. Несмотря на духовную славу, спокойно предаваться размышлениям здесь невозможно: свирепый отряд наг недавно захватил чашу и охраняет воды от всех чужаков."}},faq={{q="Чем особенен Родник Нек'Мани?",a="Родник дает исключительно чистую святую воду — как известно, единственный неоскверненный источник совершенно пресной воды в глуши к югу от Сумеречного леса. Многие религиозные ученые считают его воды божественными, хотя разные веры спорят о том, для чьего народа они были предназначены изначально.",al={"why is nek'mani important","what is holy water of clarity","holy spring stv","почему важен нек'мани","что такое святая вода ясности","святой родник тернистая долина"}},{q="Где именно находится родник?",a="Он расположен высоко на утесе, выходящем на Южный Гибельный берег, на западном побережье Тернистой долины.",al={"where is nekmani wellspring","how to find nek'mani","nekmani location","где родник нек'мани","как найти нек'мани","расположение нек'мани"}},{q="Кто сейчас контролирует Родник Нек'Мани?",a="Отряд враждебных наг недавно продвинулся вглубь суши от океана, чтобы захватить священную чашу, и яростно нападает на всякого, кто приближается к воде.",al={"who is at nek'mani","nekmani monsters","naga at nekmani","кто у нек'мани","монстры нек'мани","наги у нек'мани"}},{q="Почему искателей приключений посылают к этому роднику?",a="Путники и исследователи ищут святую воду родника для сильных чар, очищений и алхимических смесей, требующих абсолютно чистой воды.",al={"nekmani quests","holy water quest stv","clean water stv","задания нек'мани","задание святая вода тернистая долина","чистая вода тернистая долина"}}},fp="19,322,14.571.0,43.288.0,40.121.0,47.153.0,40.168.0"}
P.entries["subzone:nesingwary-s-expedition"] = {n="Экспедиция Эрнестуэя",s="Экспедиция Эрнестуэя — простой охотничий лагерь на севере Тернистой долины, к северу от Озера Назферити. Его основал знаменитый стрелок-дворф Хеминг Эрнестуэй, и лагерь служит опорной базой для охотников, желающих испытать себя против самых свирепых хищников джунглей.",h="Экспедиция Эрнестуэя — простой охотничий лагерь на севере Тернистой долины, к северу от Озера Назферити.",kw={"camp","expedition","green hills","hemet","hunters","nazferiti","nesingwary","stranglethorn","лагерь","экспедиция","зеленые холмы","хеминг","охотники","назферити","эрнестуэй","тернистая долина"},ang={["class:Hunter"]="Для стрелков и повелителей зверей этот лагерь — испытательная площадка, где вы можете отточить умение выслеживать самых опасных хищников Тернистой долины.",["race:Dwarf"]="Видеть, как Хеминг Эрнестуэй и другие горцы Каз Модана устраивают процветающий лагерь среди влажных тропических дебрей — привычная картина для дворфов с их упорством и любовью к охоте."},sec={{t="Охотничий лагерь в джунглях",b="Этот отдаленный лагерь у реки к северу от Озера Назферити — оживленное пристанище охотников на крупную дичь, следопытов и стрелков. Хеминг Эрнестуэй основал его, чтобы выслеживать легендарных зверей Тернистой долины, в окружении опытных соратников: сэра С. Дж. Эрлгадина, Аджека Руака и Барнила Каменного Горшка. Лагерь охраняют наемные стрелки, снабжают нейтральные торговцы, и он принимает всякого, кто умеет обращаться с ружьем или луком, независимо от принадлежности, объединяя их общей целью — выследить самых опасных хищников джунглей."},{t="Страницы и хищники",b="Жизнь в лагере экспедиции построена на жестком соперничестве и грандиозных охотничьих байках. Охотникам постоянно предлагают освоить выслеживание и добычу местных пантер, ящеров и тигров, а затем перейти к охоте на высших зверей. Помимо азарта погони, у лагеря хватает и собственных мелких неприятностей: рукопись Эрнестуэя разбросало по глуши, и ученые лагеря стремятся вернуть каждую недостающую главу."}},faq={{q="Кто руководит Экспедицией Эрнестуэя?",a="Лагерь основал и возглавляет легендарный охотник на крупную дичь, дворф Хеминг Эрнестуэй, вместе с кругом опытных стрелков.",al={"who leads this camp","nesingwary camp leader","who is in charge here","кто руководит лагерем","глава лагеря эрнестуэя","кто здесь главный"}},{q="Почему экспедиция находится здесь, в Тернистой долине?",a="Экспедиция отправилась в Тернистую долину, чтобы охотиться на самых опасных животных густых джунглей, включая крадущихся пантер, агрессивных ящеров, свирепых тигров и легендарных зверей-трофеев.",al={"what are they doing here","why nesingwary stranglethorn","purpose of camp","что они здесь делают","почему эрнестуэй в тернистой долине","цель лагеря"}},{q="Дружелюбна ли Экспедиция Эрнестуэя и к Альянсу, и к Орде?",a="Да. Лагерь действует как нейтральный охотничий отряд. Наемники Эрнестуэя поддерживают мир, пока гости уважают лагерь, и принимают охотников и Альянса, и Орды, желающих проверить свое умение выслеживать.",al={"is nesingwary neutral","can horde visit nesingwary","can alliance visit nesingwary","нейтрален ли эрнестуэй","может ли орда посетить эрнестуэя","может ли альянс посетить эрнестуэя"}},{q="Что за история с пропавшими страницами рукописи?",a="Хеминг Эрнестуэй написал обширные охотничьи мемуары «Зеленые холмы Тернистой долины». К несчастью, листы рукописи затерялись по всей глуши, и архивариус лагеря Барнил Каменный Горшок просит путников собрать их.",al={"green hills of stranglethorn story","why are pages scattered","barnil stonepot book","зеленые холмы тернистой долины история","почему страницы разбросаны","барнил книга"}}},fp="23,306,32.579.0,19.482.0,33.130.0,49.188.0,63.211.0,54.255.0"}
P.entries["subzone:nethander-stead"] = {n="Владение Нетандера",s="Владение Нетандера — заброшенная ферма у дороги к востоку от Южнобережья в Предгорьях Хилсбрада. Когда-то это была действующая человеческая ферма, но она пришла в упадок и целиком захвачена стаей гноллов Грязного Рыла. Поля заросли гигантскими белыми грибами, известными как Цветок Грязного Рыла, что привлекает внимание алхимиков Отрекшихся.",h="Владение Нетандера — заброшенная ферма у дороги к востоку от Южнобережья в Предгорьях Хилсбрада.",kw={"blossoms","gnolls","hillsbrad","mudsnout","mushrooms","nethander","southshore","stead","цветки","гноллы","хилсбрад","грязное рыло","грибы","нетандер","южнобережье","владение"},ang={["faction:Alliance"]="Захваченная ферма — тревожное напоминание о том, насколько хрупок периметр Южнобережья: одичавшие гноллы закрепились прямо на восточной дороге.",["faction:Horde"]="Проникнуть на эту ферму близ Южнобережья необходимо, чтобы собрать Цветок Грязного Рыла, нужный Королевскому фармацевтическому обществу для его смертоносных исследований."},sec={{t="Разрушенная усадьба",b="Владение Нетандера, находящееся в виду восточных границ Южнобережья, некогда было частью сельскохозяйственного пояса региона. Как и многие места в восточных предгорьях, ферма была брошена, когда безопасность в регионе пошатнулась и туда пришли дикие стаи. Сегодня это единственное логово гноллов Грязного Рыла в предгорьях. Эти твари обитают среди разрушенных изгородей и построек и яростно прогоняют всякого путника, подошедшего слишком близко к их территории."},{t="Цветок Грязного Рыла",b="Неухоженная почва усадьбы благоприятна для необычных грибных зарослей. Гигантские бледные грибы, известные как Цветок Грязного Рыла, покрывают заброшенные участки. В этих грибах содержатся сильные природные яды, что привлекло внимание Королевского фармацевтического общества в Мельнице Таррен. Аптекари ищут образцы, собранные прямо на землях гноллов, чтобы перегонять едкие смеси, и потому эта ничем не примечательная ферма стала целью тайных вылазок Орды на земли Альянса."}},faq={{q="Что такое Владение Нетандера?",a="Владение Нетандера — заброшенная человеческая ферма к востоку от Южнобережья в Предгорьях Хилсбрада. Ее полностью захватила враждебная стая гноллов Грязного Рыла.",al={"what is this farm","nethander stead info","where is nethander stead","что это за ферма","информация о владении нетандера","где владение нетандера"}},{q="Кто сейчас контролирует Владение Нетандера?",a="Усадьбу занимает племя гноллов Грязного Рыла. Это единственное место в Предгорьях Хилсбрада, где эта стая разбила лагерь.",al={"who lives here","who is at nethander stead","what mobs are here","кто здесь живет","кто во владении нетандера","какие враги здесь"}},{q="Что за гигантские белые грибы растут на полях?",a="Это Цветки Грязного Рыла — крупные белые грибы, процветающие на невозделанной почве усадьбы. Они содержат токсичные вещества, что делает их ценными для алхимиков Отрекшихся, изучающих яды.",al={"white mushrooms","mudsnout mushrooms","mudsnout blossoms","белые грибы","грибы грязного рыла","цветок грязного рыла"}},{q="Почему Орду интересует эта разрушенная ферма?",a="Аптекарь Лидон в Мельнице Таррен ищет Цветок Грязного Рыла, растущий на полях усадьбы. Их сильнодействующий сок — важный реагент для приготовления Эликсира агонии.",al={"why go here horde","forsaken interest","horde quest nethander","зачем орде сюда","интерес отрекшихся","задание орды нетандер"}}},fp="15,347,18.467.0,21.472.1,24.169.0,39.145.0,57.190.0,47.169.0"}
P.entries["subzone:nethergarde-keep"] = {n="Крепость Стражей Пустоты",s="Крепость Стражей Пустоты — укрепленный оплот Альянса, расположенный высоко на утесах вдоль дороги, ведущей в Выжженные земли. Построенная Гильдией каменщиков после Второй войны, она бдительным стражем возвышается над безмолвным Темным порталом и хаотичными энергиями, расползающимися по красным пустошам. Сегодня маги и гарнизоны, которых поддерживает Штормград, продолжают нести одинокую вахту против демонов и остаточной скверны.",h="Крепость Стражей Пустоты — укрепленный оплот Альянса, расположенный высоко на утесах вдоль дороги, ведущей в...",kw={"blasted lands","dark portal","keep","khadgar","kirin tor","nethergarde","stonemasons","stormwind","vancleef","выжженные земли","темный портал","крепость","кадгар","кирин-тор","крепость стражей пустоты","каменщики","штормград","ван клиф"},ang={["class:Mage"]="Для владеющих тайной магией Крепость Стражей Пустоты — это десятилетия исследований Кирин-Тора в области межмировых разломов, их запечатывания и сдерживания энтропийного распространения порчи Скверны.",["faction:Alliance"]="Крепость — один из важнейших передовых бастионов Альянса, оплаченный кровью и золотом, чтобы ужасы Первой и Второй войн никогда больше не вышли из портала."},sec={{t="Страж над красным миром",b="После разрушения Темного портала в конце Второй войны верховный маг Кадгар и предводители Альянса Лордерона поняли, что Азерот больше никогда не сможет оставить брешь без охраны. Под руководством Эдвина ван Клифа Гильдия каменщиков возвела вдоль каньонного прохода в Выжженные земли высокие бастионы, казармы и башни магов. Благодаря чародеям Кирин-Тора крепость решала две задачи: непрерывно наблюдать за разрушенными вратами и плести обереги, не дающие демонической порче выжженного края расползтись на север, в человеческие королевства."},{t="Одинокая вахта",b="Когда Темный портал открылся вновь и экспедиция Альянса отправилась в Дренор, Кадгар и его спутники запечатали врата за собой, оставив Крепость Стражей Пустоты охранять безмолвные остатки. Два десятилетия ученые из Даларана и Святилища волшебника изучают остаточные энергии портала, мутировавшую местную фауну и вторжения демонов. После разорения Даларана в годы Третьей войны крепость целиком зависит от жизненно важных обозов снабжения из Штормграда, которые поддерживают ее солдат и магов, в одиночку противостоящих ужасам пустоши."}},faq={{q="Почему построили Крепость Стражей Пустоты?",a="Ее заказали после Второй войны верховный маг Кадгар и Альянс Лордерона, чтобы защититься от нового вторжения орков из Дренора и сдержать распространение демонической порчи в Выжженных землях.",al={"purpose of nethergarde","why is nethergarde here","nethergarde history","назначение крепости стражей пустоты","зачем здесь крепость стражей пустоты","история крепости стражей пустоты"}},{q="Кто построил крепость?",a="Крепость Стражей Пустоты построила Гильдия каменщиков под архитектурным руководством Эдвина ван Клифа на средства королевств — членов Альянса Лордерона.",al={"who built nethergarde","nethergarde builders","vancleef nethergarde","кто построил крепость стражей пустоты","строители крепости стражей пустоты","ван клиф крепость стражей пустоты"}},{q="Кто сейчас командует крепостью и снабжает ее?",a="Изначально крепость содержал Кирин-Тор Даларана, но после падения Даларана под ударами Плети и Легиона она в основном зависит от Королевства Штормград, которое присылает войска, регулярные обозы и обеспечивает материально-техническую поддержку.",al={"who runs nethergarde","nethergarde supplies","stormwind nethergarde","кто управляет крепостью стражей пустоты","снабжение крепости стражей пустоты","штормград крепость стражей пустоты"}},{q="Что изучают маги внутри крепости?",a="Исследователи из Святилища волшебника изучают дремлющие энергии Темного портала, странные мутации местных животных и способы защиты от порчи Скверны, нависшей над красным краем.",al={"nethergarde mages","wizards sanctum nethergarde","what are they researching","маги крепости стражей пустоты","святилище волшебника крепость стражей пустоты","что они исследуют"}}},fp="16,416,32.597.0,16.556.0,31.211.0,25.172.0,43.223.0,44.205.0"}
P.entries["subzone:night-run"] = {n="Ночная поляна",s="Ночная поляна — небольшой уединенный аванпост сатиров на окруженном утесами холме в центрально-восточной части Ясеневого леса. Он заселен демоническими сатирами Оскверненной Шерсти и представляет собой оскверненный лагерь, где среди древних эльфийских руин таится темная магия душ.",h="Ночная поляна — небольшой уединенный аванпост сатиров на окруженном утесами холме в центрально-восточной...",kw={"ashenvale","cult of the dark strand","falfarren river","felmusk","night run","satyr","soulgem","ясеневый лес","культ темной нити","река фалфаррен","оскверненная шерсть","ночная поляна","сатиры","камень душ"},ang={["faction:Alliance"]="Ночная поляна лежит к северу от Приюта в Ночных Лесах и представляет собой неизменную демоническую угрозу важным линиям снабжения Часовых.",["race:NightElf"]="Осквернение Ночной поляны — незаживающий шрам: эти древние камни были залиты кровью ночных эльфов во время войны сатиров и до сих пор оскверняются извращенными сатирами Оскверненной Шерсти."},sec={{t="Защищенное обрывистое пристанище",b="Ночная поляна — самый маленький и самый изолированный из трех крупных оплотов сатиров в Ясеневом лесу, наряду с Ксавианом и Сатирнааром. Поселение скрыто среди разрушающейся эльфийской кладки и обломков колонн и выдается на высоком хребте, ограниченном крутыми неприступными утесами. Добраться до него можно лишь окольным путем вдоль Реки Фалфаррен у вод Ксавиана или по опасному северному уступу над Приютом в Ночных Лесах. Несмотря на скромные размеры, это место крайне опасно: живущие здесь сатиры Оскверненной Шерсти действуют заодно со зловещим Культом Темной Нити и закрепляют искаженные камни душ, собирая в лесу демоническую сущность."}},faq={{q="Кто управляет Ночной поляной?",a="Ночную поляну занимают сатиры Оскверненной Шерсти — демонические осквернители из числа ночных эльфов, связанные с Культом Темной Нити.",al={"who lives at night run","night run mobs","what is at night run","кто живет на ночной поляне","монстры ночной поляны","что на ночной поляне"}},{q="Как добраться до Ночной поляны?",a="Поскольку она расположена на возвышенности, окруженной отвесными утесами, путники должны подходить либо по узкому уступу к северу от Приюта в Ночных Лесах, либо по Реке Фалфаррен в сторону Ксавиана, а затем свернуть на запад и подняться на хребет.",al={"how to get to night run","night run path","night run entrance","как добраться до ночной поляны","путь к ночной поляне","вход на ночную поляну"}},{q="Что здесь делает Культ Темной Нити?",a="Культ действует вместе с сатирами и поддерживает на Ночной поляне темный камень душ, чтобы собирать демонические энергии и направлять их по всему Ясеневому лесу.",al={"cult of the dark strand night run","soulgem night run","культ темной нити ночная поляна","камень душ ночная поляна"}},{q="Какие исторические события произошли на Ночной поляне?",a="Тысячи лет назад, после Великого Раскола, ранние друиды в звериной облике стаи напали здесь на Часовых ночных эльфов, ранив Шандрису Оперенную Луну, и положили яростное начало войне сатиров.",al={"night run lore","war of the satyr night run","предания ночной поляны","война сатиров ночная поляна"}}},fp="9,235,26.643.0,23.130.0,27.228.0,47.138.0,45.219.0"}
P.entries["subzone:nighthaven"] = {n="Ночная Гавань",s="Ночная Гавань — уединенное поселение на северном берегу Озера Элуне'ара в Лунной поляне. Будучи сердцем Круга Кенария, она служит убежищем, где ночные эльфы и таурены-друиды вместе учатся в мире, вдали от войн фракций Азерота.",h="Ночная Гавань — уединенное поселение на северном берегу Озера Элуне'ара в Лунной поляне.",kw={"cenarion circle","druid","lake elune'ara","loganaar","lunar festival","moonglade","nighthaven","remulos","круг кенария","друид","озеро элуне'ара","логанаар","лунный фестиваль","лунная поляна","ночная гавань","ремулос"},ang={["class:Druid"]="Ночная Гавань — ваш духовный дом вдали от дома. Благодаря способности «Телепортация: Лунная поляна» она дает быстрый доступ к наставникам вашего ордена, испытаниям звериных обликов и особым маршрутам полета в Деревню Рут'теран или Громовой Утес.",["profession:Herbalism"]="Ночная Гавань — тихое место, где среди спокойных рощ Лунной поляны можно обратиться к учителям травничества."},sec={{t="Убежище Круга Кенария",b="Ночная Гавань, построенная в традиционном ночноэльфийском стиле на спокойном берегу Озера Элуне'ара, — тихое прибежище, почти отрезанное от внешнего мира. Здесь лунные колодцы мягко освещают рощи и залы, посвященные сохранению природного равновесия. Как главное поселение Круга Кенария, она предоставляет наставников, травников и особых торговцев для посвященных друидов. Поселение строго нейтрально и принимает последователей независимо от того, на чьей стороне их родные земли — Альянса или Орды."},{t="Древняя история и священные собрания",b="Покой Ночной Гавани не раз подвергался испытаниям. Спустя века после Войны Древних здесь собрались герои, чтобы сразиться с разъяренным полубогом Омен и загнать его в глубины Озера Элуне'ара. Деревня также открывает свои уединенные границы во время Лунного фестиваля, принимая паломников со всего Азерота, чтобы почтить предков и праздновать под бдительным взором Элуны."}},faq={{q="Кто правит Ночной Гаванью или присматривает за ней?",a="Ночной Гаванью управляет Круг Кенария под руководством Хранителя Ремулоса и старших друидов, таких как Логанаар. Это независимое нейтральное убежище, а не территория ночноэльфийского правительства.",al={"who runs nighthaven","nighthaven leaders","who is in charge here","кто управляет ночной гаванью","лидеры ночной гавани","кто здесь главный"}},{q="Могут ли посещать Ночную Гавань не друиды?",a="Да. Те, кто не является друидами, могут добраться до Лунной поляны через туннели Древобрюхов или воспользоваться общедоступными распорядителями полетов в другой части долины, а затем дойти до Ночной Гавани. Местные распорядители полетов обслуживают только друидов.",al={"can non druids go to nighthaven","how do non druids get here","могут ли не друиды попасть в ночную гавань","как не друидам добраться сюда"}},{q="Почему ночные эльфы и таурены мирно живут здесь вместе?",a="Круг Кенария посвятил себя исцелению природы и Изумрудного Сна превыше политики фракций. Пока члены круга находятся в Лунной поляне, они дают обет нейтралитета, откладывают вражду Альянса и Орды и на равных изучают друидизм.",al={"why no fighting here","why are tauren allowed here","horde alliance peace","почему здесь нет боев","почему здесь разрешены таурены","мир орды и альянса"}},{q="Какие маршруты полета доступны из Ночной Гавани?",a="Особые распорядители полетов Кенария предлагают друидам прямые перелеты: гиппогрифы доставляют друидов Альянса в Деревню Рут'теран, а наездники на ветрокрылах переносят друидов Орды в Громовой Утес.",al={"nighthaven flight masters","where can i fly from here","распорядители полетов ночной гавани","куда отсюда можно улететь"}}},fp="10,253,34.541.0,37.385.0,33.224.0,32.202.0,63.228.0,49.198.0"}
P.entries["subzone:nightmare-vale"] = {n="Долина Кошмаров",s="Долина Кошмаров — затененная низина на юго-западе Тирисфальских лесов, к западу от Заставы Крестоносцев. Когда-то это был пышный лесной приют, но его деревья засохли от мора, а среди искривленных стволов бродят свирепые хищники.",h="Долина Кошмаров — затененная низина на юго-западе Тирисфальских лесов, к западу от Заставы Крестоносцев.",kw={"darkhounds","nightmare vale","ressan the needler","tirisfal glades","vampire bats","темные гончие","долина кошмаров","куссан жалящий","тирисфальские леса","вампирические летучие мыши"},ang={["class:Hunter"]="В долине обитают свирепые темные гончие и вампирические летучие мыши, включая редкую белую мышь Куссана Жалящего, поэтому она служит достойным испытанием для охотников, ищущих грозных зверей.",["race:Undead"]="Искаженная фауна Долины Кошмаров напоминает о неизгладимом следе чумы в Тирисфале и представляет непосредственную угрозу для путешествующих Отрекшихся, отважившихся выйти за пределы Брилла."},sec={{t="Разрушенная глушь",b="До Третьей войны эта долина была цветущей частью тирисфальской глубинки, полной певчих птиц и обычной лесной дичи. После чумы Плети растительность почернела и сгнила. Ненасытные темные гончие и огромные вампирические летучие мыши пожрали местных животных, превратив низину в мрачное пристанище падальщиков и хищников."},{t="Охотники низины",b="В тенях Долины Кошмаров затаился Куссан Жалящий — необычайно крупная бледная вампирическая летучая мышь, известная среди местных путников. Зажатая между населенной призраками глушью и ревностными часовыми близкой Заставы Крестоносцев, долина — суровое место, где неосторожные искатели приключений быстро становятся добычей."}},faq={{q="Где находится Долина Кошмаров?",a="Долина Кошмаров лежит на юго-западе Тирисфальских лесов, к западу от Заставы Крестоносцев.",al={"nightmare vale location","where is nightmare vale","find nightmare vale","где долина кошмаров","расположение долины кошмаров","найти долину кошмаров"}},{q="Почему долину называют Долиной Кошмаров?",a="Некогда мирный, цветущий лес, долина полностью поддалась чуме, опустошившей Лордерон. Засохшие деревья и агрессивные хищники — голодные темные гончие и кровососущие летучие мыши — превращают ее в кошмар наяву для каждого, кто здесь проходит.",al={"why nightmare vale","nightmare vale lore","почему долина кошмаров","предания долины кошмаров"}},{q="Какие существа бродят по Долине Кошмаров?",a="Долину заполонили свирепые темные гончие и гигантские вампирические летучие мыши, которые изгнали или съели местных лесных животных. В низине также охотится редкая белая вампирическая летучая мышь Куссан Жалящий.",al={"nightmare vale mobs","monsters in nightmare vale","beasts here","монстры долины кошмаров","звери долины кошмаров","кто здесь обитает"}},{q="Кто такой Куссан Жалящий?",a="Куссан Жалящий — редкая ослепительно белая вампирическая летучая мышь, которая, как известно, охотится в темном небе и среди засохшего полога леса Долины Кошмаров.",al={"ressan","ressan the needler","rare bat tirisfal","куссан","куссан жалящий","редкая мышь тирисфаль"}}},fp="14,238,20.366.0,22.325.0,32.111.0,40.250.0,35.196.0,26.126.0"}
P.entries["subzone:nightsong-woods"] = {n="Леса Ночной Песни",s="Леса Ночной Песни — спорная восточная часть Ясеневого леса, протянувшаяся от Приюта в Ночных Лесах к границам Азшары. Это главное поле боя между ночными эльфами, защищающими свой священный лес, и кланом Песни Войны, заготавливающим древесину для Орды. В его темных рощах древние чащи сталкиваются с укрепленными лагерями на фоне непрекращающейся демонической порчи.",h="Леса Ночной Песни — спорная восточная часть Ясеневого леса, протянувшаяся от Приюта в Ночных Лесах к границам...",kw={"ashenvale","falfarren river","nightsong woods","satyrnaar","silverwing sentinels","splintertree post","warsong lumber camp","ясеневый лес","река фалфаррен","леса ночной песни","сатирнаар","среброкрылые часовые","застава расщепленного дерева","лесозаготовки песни войны"},ang={["faction:Horde"]="Этот восточный фронт обеспечивает Орду ценной строевой древесиной и стратегическими путями снабжения через Заставу Расщепленного Дерева, требуя бдительности перед засадами Часовых и демоническими тварями.",["race:NightElf"]="Леса Ночной Песни — священное пограничье в осаде; защита древних рощ от топоров Песни Войны и изгнание остатков сатирской порчи — основной долг кальдораев."},sec={{t="Лес, изрезанный войной",b="Леса Ночной Песни тянутся на восток через Ясеневый лес до Азшары, и их определяет нарастающее насилие. Река Фалфаррен рассекает западную часть, образуя неспокойную границу между поселениями Альянса и вторжениями Орды. Дальше на восток лес распадается на ожесточенно оспариваемые земли, где Застава Расщепленного Дерева координирует походы Орды против Среброкрылых Часовых. Орочьи топоры постоянно вырубают южные рощи, питая рост Орды, и оставляют голые просеки, приводящие кальдораев в ярость. Опасность усугубляют крепости сатиров, такие как Сатирнаар и Ксавиан, а также остатки демонов в Каньоне Гибели Демона и на Холме Демонического Огня, оскверняющие восточные кроны."}},faq={{q="Где находятся Леса Ночной Песни?",a="Леса Ночной Песни занимают восточную половину Ясеневого леса. Их границы тянутся от Приюта в Ночных Лесах и северной дороги в Оскверненный лес на восток, до дикой границы Азшары.",al={"nightsong woods location","where is nightsong woods","ashenvale east woods","леса ночной песни где находятся","где леса ночной песни","восток ясеневого леса"}},{q="Почему в этой части Ясеневого леса так много сражений?",a="Этот край лежит на линии фронта между Среброкрылыми Часовыми и кланом Песни Войны. Орда сильно зависит от плотной древесины южных деревьев для строительства и поддержания своих поселений, а ночные эльфы яростно стремятся остановить вырубку и вернуть землю предков.",al={"why fighting in nightsong woods","horde vs alliance ashenvale","warsong conflict","почему сражения в лесах ночной песни","орда против альянса ясеневый лес","конфликт песни войны"}},{q="Кто контролирует Леса Ночной Песни?",a="Ни одна фракция не владеет этими лесами безраздельно. Река Фалфаррен примерно разделяет западные земли Альянса и восточные позиции Орды у Заставы Расщепленного Дерева и Лесозаготовок Песни Войны. Участки леса также удерживают порочные сатиры в Сатирнааре и Ксавиане, а также силы Легиона возле Каньона Гибели Демона.",al={"who owns nightsong woods","nightsong woods faction control","кто владеет лесами ночной песни","контроль фракций леса ночной песни"}},{q="Какие демонические угрозы здесь есть?",a="Восточная глушь полна демонического и оскверняющего влияния. Сатиры обитают в укрепленных древних руинах, таких как Сатирнаар и Ксавиан, а уцелевшие демоны Пылающего Легиона населяют Холм Демонического Огня и глубины Каньона Гибели Демона.",al={"demons in nightsong woods","satyr in eastern ashenvale","felfire hill demons","демоны в лесах ночной песни","сатиры восточный ясеневый лес","демоны холм демонического огня"}}},fp="15,388,22.678.0,38.187.0,56.319.0,29.325.0,32.240.0"}
P.entries["subzone:nijel-s-point"] = {n="Высота Найджела",s="Высота Найджела — укрепленный оплот Альянса и Круга Кенария на высоких северных утесах Пустошей. Надежно укрытая от гибельных долин внизу, она служит единственным безопасным убежищем для путников, исследователей и солдат Альянса в суровой пустыне.",h="Высота Найджела — укрепленный оплот Альянса и Круга Кенария на высоких северных утесах Пустошей.",kw={"brother anton","centaur","desolace","marandis","maraudon","nijel's point","outpost","pentigast","брат антон","кентавр","пустоши","марандис","мародон","высота найджела","застава","пентигаст"},ang={["class:Druid"]="Хранитель Марандис использует это высокогорное убежище, чтобы организовать возвращение останков Заетара из-под порчи, гноящейся в Мародоне.",["faction:Alliance"]="Высота Найджела — ваше единственное укрепленное убежище и пункт полетов в Пустошах, связывающий пути снабжения между Когтистыми горами, Терамором и Фераласом."},sec={{t="Бастион над пустошами",b="Высота Найджела вырублена в отвесных скалах у границы Когтистых гор и возвышается над серой пылью и разбойничьими стаями кентавров Пустошей. Поселение удерживает отряд Армии Штормграда под командованием капитана Пентигаста, которому поручено следить за жестокими войнами кланов, угрожающими интересам Альянса на юге Калимдора. Высокое положение и узкие тропы делают ее легко защищаемой и дают надежную стоянку гонцам, разведчикам и всадникам на грифонах, летающим между Пиком Каменного Когтя, Терамором и Крепостью Оперенной Луны."},{t="Экспедиции Кенария и Алого ордена",b="Помимо гарнизона Штормграда, в лагере находятся посланники с особыми и опасными целями. Хранитель Марандис и его дриады используют лагерь как оперативную базу, чтобы сразиться с принцессой Терадрас в глубинах Мародона и вернуть павшего полубога Заетара. Даже Алый орден держит здесь посланника — брата Антона, стремящегося очистить долину от нежити. Несмотря на кипучую жизнь солдат и друидов, личность самого Найджела остается древней тайной, неизвестной даже гарнизону на хребте."}},faq={{q="Почему Альянс расквартирован в Пустошах?",a="Капитан Пентигаст возглавляет отряд Армии Штормграда, наблюдающий за враждующими кланами кентавров. Альянс опасается, что когда один клан уничтожит остальных, победившая орда обратит агрессию на соседние земли и поселения, такие как Когтистые горы и Фералас.",al={"why is alliance here","stormwind army in desolace","why nijels point exists","почему здесь альянс","армия штормграда в пустошах","зачем нужна высота найджела"}},{q="Кто такой Найджел?",a="Похоже, на заставе этого никто не знает. Его настоящая история утрачена во времени.",al={"who is nijel","nijel lore","who was nijels point named after","кто такой найджел","предания о найджеле","в честь кого названа высота найджела"}},{q="Что делает Круг Кенария на Высоте Найджела?",a="Хранитель Марандис и его сестры-дриады пришли в Пустоши, чтобы очистить Мародон, убить принцессу Терадрас и вернуть останки Заетара в священные рощи Когтистых гор.",al={"druids in nijels point","keeper marandis mission","why are dryads here","друиды высота найджела","миссия хранителя марандиса","почему здесь дриады"}},{q="Почему Алый орден находится на Высоте Найджела?",a="Брат Антон служит дальним посланником Алого ордена. Брат Кроули в Штормграде направляет к нему авантюристов Альянса, и он проверяет их решимость в борьбе с нежитью в Долине Костей в Пустошах.",al={"brother anton scarlet crusade","scarlet crusade in desolace","брат антон алый орден","алый орден в пустошах"}}},fp="13,281,26.564.0,32.548.0,42.271.0,14.76.0,51.202.0,44.216.0"}
P.entries["subzone:north-coast"] = {n="Северное побережье",s="Северное побережье — мрачная, окутанная туманом полоса берега на северной окраине Тирисфальских лесов у Великого моря. Отравленные падением Лордерона, холодные пляжи завалены гниющими морскими обитателями и яростно охраняются враждебными племенами мурлоков.",h="Северное побережье — мрачная, окутанная туманом полоса берега на северной окраине Тирисфальских лесов у...",kw={"beach","deeb","great sea","murloc","north coast","tirisfal glades","vile fin","пляж","диб","великое море","мурлок","северное побережье","тирисфальские леса","злобный плавник"},ang={["race:Undead"]="Хотя патрульные маршруты Отрекшихся держатся дороги через Брилл, очистка Северного побережья от наседающих мурлоков помогает сохранять северный фланг Тирисфальских лесов относительно безопасным."},sec={{t="Зараженный берег",b="До Третьей войны эти северные воды и каменистые пляжи были частью мирной северной границы Лордерона. Когда Чума нежизни прокатилась по континенту, ее губительная зараза просочилась по утесам и отравила побережье. Воды стали холодными и мутными, выбрасывая на песок туши гигантских морских тварей, которые теперь гниют в вечном прибрежном тумане."},{t="Берег Злобного Плавника",b="Когда человеческое королевство пало, а Отрекшиеся сосредоточились вокруг Брилла и Столицы, прибрежные мурлоки захватили опустевшие пески. Местное племя Злобного Плавника держит хижины у прибоя и использует мелководье как нерестилище. Стаи свирепых мурлоков, среди которых заметный Диб и множество растущих головастиков, жестоко охраняют линию прибоя от любых обитателей суши."}},faq={{q="Какие существа обитают на Северном побережье?",a="Пляж занимают главным образом агрессивные мурлоки Злобного Плавника, их головастики и падальщики, питающиеся гниющими морскими обитателями, которых выбрасывает на берег Великое море.",al={"north coast mobs","what lives on north coast","monsters north coast","мобы северное побережье","кто живет на северном побережье","монстры северное побережье"}},{q="Кто такой Диб?",a="Диб — одинокий мурлок, которого можно найти на Северном побережье среди хижин и мелководья.",al={"deeb","murloc deeb","who is deeb","диб","мурлок диб","кто такой диб"}},{q="Почему берег усеян гниющими тушами?",a="Чума нежизни, опустошившая Лордерон, просочилась в прибрежную экосистему, отравив мелководье, и мертвые морские твари выбрасываются на берег и разлагаются на зараженном песке.",al={"dead sea monsters","beached whales tirisfal","why dead creatures","мертвые морские чудовища","выброшенные киты тирисфаль","почему мертвые существа"}},{q="Оспаривается ли Северное побережье крупными фракциями?",a="Ни Отрекшиеся, ни остатки Альянса не держат на Северном побережье гарнизонов. Это дикая, нетронутая окраина, оставленная в основном мурлокам и морским тварям.",al={"who owns north coast","forsaken presence north coast","кто владеет северным побережьем","отрекшиеся на северном побережье"}}},fp="11,272,20.385.0,18.410.0,39.165.0,12.119.0,46.192.0,51.162.0"}
P.entries["subzone:north-gate-outpost"] = {n="Форт у северных врат",kw={"dun morogh","ironforge","loch modan","mountaineers","north gate outpost","north gate pass","дун морог","стальгорн","лок модан","горные пехотинцы","форт у северных врат","северные врата"},ang={["race:Dwarf"]="Форт показывает стойкий долг горных пехотинцев Стальгорна, которые держат суровые нагорные проходы открытыми, несмотря на лютый холод и хищных зверей.",["race:Gnome"]="Поселившись по всему Дун Мороге, гномы часто помогают гарнизону дворфов своей смекалкой и меткостью, выслеживая пропавшие патрули."},sec={{t="Стражи прохода",b="Это небольшое поселение в середине Северных врат служит северо-восточным порогом Дун Морога. Расквартированные здесь горные пехотинцы дворфов очищают главную дорогу от хищных зверей и следят за движением через горные туннели в Лок Модан. Суровый климат и крутые овраги делают патруль опасным, и гарнизон часто просит путников осмотреть окрестные хребты в поисках пропавших патрулей и опасных хищников."}},faq={{q="Для чего нужен Форт у северных врат?",a="Это горный военный пост, охраняющий Северные врата — северную дорогу, соединяющую Дун Морог с Лок Моданом. Расквартированные здесь горные пехотинцы сдерживают численность диких зверей и держат проход открытым для торговли и путешествий.",al={"north gate outpost purpose","why is north gate outpost here","назначение форта у северных врат","зачем нужен форт у северных врат"}},{q="Куда ведет дорога через проход?",a="Путь на восток через горные туннели за фортом ведет в умеренную долину Лок Модана, а на запад — обратно вниз к Караносу и Стальгорну.",al={"where does north gate pass go","road past north gate outpost","куда ведут северные врата","дорога за фортом у северных врат"}},{q="Почему горным пехотинцам нужна помощь путников?",a="Местные звери на заснеженных утесах яростно охраняют свои территории. Несколько горных пехотинцев пропали в скалах, охотясь на опасных тварей, и гарнизон вынужден нанимать умелых разведчиков, чтобы выяснить их судьбу.",al={"north gate outpost quests","missing mountaineers","задания форт у северных врат","пропавшие горные пехотинцы"}}},fp="18,261,18.469.0,36.233.0,42.175.0,49.223.0"}
P.entries["subzone:north-gate-pass"] = {n="Северные врата",s="Северные врата — важный горный путь, соединяющий заснеженные скалы Дун Морога с холмистой котловиной Лок Модана. Он образует северный коридор через вершины Каз Модана под охраной укрепленного форта дворфов. Путники, направляющиеся к северным низинам Болотины, часто проходят по этой горной дороге.",h="Северные врата — важный горный путь, соединяющий заснеженные скалы Дун Морога с холмистой котловиной Лок...",kw={"dun morogh","ironforge","loch modan","mountaineers","north gate outpost","north gate pass","wetlands","дун морог","стальгорн","лок модан","горные пехотинцы","форт у северных врат","северные врата","болотина"},ang={["faction:Alliance"]="Проход — важный военный и снабженческий коридор, соединяющий столицу дворфов с северными экспедициями Альянса, идущими в Болотину.",["race:Dwarf"]="Для дворфов, идущих между высокими вратами Стальгорна и приграничными поселениями у озера Лок, проход — знакомый, высеченный в камне порог под охраной собратьев-горных пехотинцев."},sec={{t="Врата между вершинами",b="Северные врата, вырубленные в отвесной скале Каз Модана, служат северной магистралью между высокими, застывшими долинами Дун Морога и умеренными водами Лок Модана. Спускаясь по крутым горным туннелям, путники, идущие с запада, видят перед собой широкую долину озера. Поскольку проход расположен недалеко от троп, ведущих вниз в Болотину, здесь оживленное движение гонцов дворфов, торговцев и бродячих искателей приключений. Его стратегическую ценность обеспечивает Форт у северных врат, где горные пехотинцы бдительно следят за троггами и горными хищниками."}},faq={{q="Куда ведут Северные врата?",a="Проход соединяет восточный Дун Морог с северо-западным Лок Моданом. Дорога дальше на север вокруг озера ведет к горным туннелям, спускающимся в Болотину, что делает его важным перекрестком для путников на север.",al={"where does north gate pass go","north gate pass destination","path through north gate pass","куда ведут северные врата","пункт назначения северных врат","путь через северные врата"}},{q="Кто охраняет проход?",a="Горные пехотинцы Стальгорна содержат Форт у северных врат прямо у дороги, следя за путниками и очищая горный проход от хищных зверей и бродячих троггов.",al={"who guards north gate pass","north gate pass guards","dwarf outpost north gate","кто охраняет северные врата","стража северных врат","форт дворфов северные врата"}},{q="Чем он отличается от Южных врат?",a="Оба прохода соединяют Дун Морог с Лок Моданом через прорубленные туннели, но Северные врата лежат севернее и дают самый прямой сухопутный путь для идущих дальше в Болотину и северные земли.",al={"difference north and south gate pass","north gate vs south gate","разница северные и южные врата","северные врата против южных врат"}}},fp="15,332,25.629.0,32.231.0,21.178.0,42.212.0"}
P.entries["subzone:north-tide-s-hollow"] = {n="Северная приливная низина",s="Северная приливная низина — суровый дикий уголок Серебряного бора к северу от Гробницы. Эту поляну населяют свирепые воргены Лунной Ярости, преданные беглому верховному магу Аругалу, и она служит опорной базой для зверей, рыщущих в прибрежных лесах.",h="Северная приливная низина — суровый дикий уголок Серебряного бора к северу от Гробницы.",kw={"arugal","beachhead","moonrage","north tide's hollow","sepulcher","silverpine forest","worgen","аругал","плацдарм","лунный гнев","северная приливная низина","гробница","серебряный бор","ворген"},ang={["race:Undead"]="Стая Лунной Ярости в Северной приливной низине, расположенная неприятно близко к Гробнице, представляет непосредственную угрозу власти Отрекшихся и их линиям снабжения в Серебряном бору."},sec={{t="Дикий оплот",b="Северная приливная низина, укрытая в густом лесу к северу от поселения Отрекшихся — Гробницы, находится во власти свирепой стаи Лунной Ярости. Эти дикие воргены, попавшие в Лордерон из-за безрассудного колдовства верховного мага Аругала, устроили по всей низине грубые лагеря. Эти простые укрытия построены лишь с самым необходимым для выносливых зверей и образуют передовую базу, опасно близкую к путям Отрекшихся."},{t="В тени Темного Клыка",b="В отличие от обычных лесных хищников, воргены Северной приливной низины подчиняются зловещей воле, исходящей из Крепости Темного Клыка. Близость к западному побережью и главной дороге через Серебряный бор делает их постоянной угрозой для гонцов и патрулей Отрекшихся, пытающихся защитить этот край."}},faq={{q="Где находится Северная приливная низина?",a="Северная приливная низина находится в западной части Серебряного бора, к северу от форпоста Отрекшихся — Гробницы, неподалеку от прибрежных утесов.",al={"north tides hollow location","where is north tides hollow","hollow location","северная приливная низина где","где находится северная приливная низина","расположение низины"}},{q="Какие существа обитают в Северной приливной низине?",a="Низину наводнили воргены Лунной Ярости — сверхъестественные волкоподобные звери, скованные безумием верховного мага Аругала.",al={"who lives here","north tides hollow enemies","mobs in north tides hollow","кто здесь живет","враги в северной приливной низине","монстры в северной приливной низине"}},{q="Почему воргены живут здесь в грубых лагерях?",a="Хотя воргены свирепы и дики, стая Лунной Ярости сохраняет достаточно хитрости, чтобы устраивать простые лагеря. Будучи от природы выносливыми и закаленными, они довольствуются самыми примитивными укрытиями и необходимым для выживания в глуши Лордерона.",al={"worgen camps","why do worgen have tents","лагеря ворженов","зачем воргенам палатки"}},{q="Кто управляет воргенами в этой местности?",a="Воргены Лунной Ярости в Северной приливной низине служат верховному магу Аругалу, который призвал воргенов в Лордерон и командует ими из Крепости Темного Клыка.",al={"who leads the worgen","worgen master","кто ведет ворженов","хозяин ворженов"}}},fp="19,263,16.462.0,25.309.0,29.160.0,43.110.0,43.253.0,37.140.0"}
P.entries["subzone:north-tide-s-run"] = {n="Берег Северного прилива",s="Берег Северного прилива — продуваемое ветрами северо-западное побережье Серебряного бора на краю Великого моря. Этот участок песка с одиноким костром и наполовину затонувшим кораблем известен как уединенное место испытаний для странствующих друидов, ищущих гармонию с водами.",h="Берег Северного прилива — продуваемое ветрами северо-западное побережье Серебряного бора на краю Великого...",kw={"aquatic form","druid trial","great sea","north tide's run","shipwreck","silverpine forest","wallace the blind","водный облик","испытание друида","великое море","берег северного прилива","кораблекрушение","серебряный бор","уоллес слепой"},ang={["class:Druid"]="Для тауренов-друидов этот холодный берег — важный обряд посвящения: здесь находятся подводные части испытания, необходимые для овладения обликом морского льва.",["race:Tauren"]="Вдали от теплых равнин Мулгора Берег Северного прилива — одно из немногих мест в Лордероне, куда молодые таурены попадают в начале духовного пути."},sec={{t="Одинокий прибрежный пост",b="Берег Северного прилива тянется вдоль северо-западного края Серебряного бора и состоит из холодного песка, грохочущего прибоя и полосы Великого моря. Его самая заметная примета — частично затонувший корабль, опасно накренившийся на мелководье у пляжа. Помимо обломков, единственный признак жилья — скромный костер Уоллеса Слепого, который молча коротает время у плещущегося прилива."},{t="Воды морского льва",b="Несмотря на мрачную обстановку, Берег Северного прилива священен для новичков Орды, идущих путем Кенария. Юных тауренов-друидов отправляют сюда в паломничество за подводными реликвиями, утерянными в волнах: проверяя дыхание и выносливость, они заслуживают благословение водного облика."}},faq={{q="Что такое Берег Северного прилива?",a="Это северо-западное побережье и прибрежный шельф Серебряного бора, граничащие с Великим морем. Его отличают затонувший корабль, приливные воды и мрачный тихий берег.",al={"north tides run","where is north tides run","what is this beach","берег северного прилива","где берег северного прилива","что это за пляж"}},{q="Кто такой Уоллес Слепой?",a="Уоллес Слепой — отшельник, разбивший небольшой лагерь с костром прямо у кромки воды на пляже и тихо сидящий возле затонувшего судна.",al={"wallace blind","wallace the blind silverpine","who is the guy at the fire","уоллес слепой","уоллес слепой серебряный бор","кто человек у костра"}},{q="Почему друиды приходят на Берег Северного прилива?",a="Тауренские друиды совершают сюда паломничество во время испытаний, чтобы говорить с духами моря. Отважно ныряя на глубину у берега за утерянными фрагментами кулона, они обретают силу принимать водный облик.",al={"druid quest silverpine beach","aquatic form silverpine","why tauren here","задание друида пляж серебряный бор","водный облик серебряный бор","почему тауренов сюда"}},{q="Что за затонувший корабль в воде?",a="Обломки — это частично погрузившееся судно на мелководье у самого берега. Оно служит ориентиром для путников, идущих вдоль побережья.",al={"shipwreck north tides run","sunken boat silverpine beach","ship wreck","кораблекрушение берег северного прилива","затонувшая лодка серебряный бор","обломки корабля"}}},fp="16,282,24.412.0,22.304.0,25.178.0,25.150.0,39.219.0,37.164.0"}
P.entries["subzone:northdale"] = {n="Северный Дол",s="Северный Дол — разрушенное поселение к северу от Часовни Последней Надежды в Восточных Чумных землях, у границы Кель'Таласа. Некогда процветавший северный городок теперь лежит в руинах, захваченный банши, незримыми стражами и оскверненными элементалями. Он больше всего известен как горький перекресток, где Телан Фордринг отрекся от Ордена Серебряной Длани, приняв фанатизм Алого ордена.",h="Северный Дол — разрушенное поселение к северу от Часовни Последней Надежды в Восточных Чумных землях, у...",kw={"banshee","eyeless watcher","fordring","northdale","plaguelands","scarlet crusade","silver hand","taelan","банши","безглазый страж","фордринг","северный дол","чумные земли","алый орден","серебряная длань","телан"},ang={["class:Paladin"]="Для рыцарей Света Северный Дол — отрезвляющий памятник утраченной вере: на этой земле Телан Фордринг оставил Серебряную Длань ради мести.",["race:Human"]="Обгоревшие фундаменты и бродящие банши Северного Дола — еще одна община Лордерона, уничтоженная и захваченная Плетью."},sec={{t="Город скорби",b="Северный Дол, расположенный на холмах к северу от Часовни Последней Надежды, когда-то был мирной общиной на северном тракте в Кель'Талас. Третья война превратила его в руины: очаги остыли, жителей перебили или изгнали. Ныне среди крошащейся кладки бродят воющие банши, а невидимые Безглазые стражи таятся во тьме, наблюдая за проклятыми дорогами. Даже соседнее озеро поддалось чуме: его воды кипят искаженными, оскверненными водными элементалями."},{t="Клятва Отрекшихся",b="Северный Дол имеет мрачное значение в трагической истории семьи Фордринг. После падения Лордерона и роспуска Рыцарей Серебряной Длани юный Телан Фордринг стоял на этих разбитых улицах и открыто отверг наставления отца. Считая остатки Серебряной Длани слишком слабыми, чтобы очистить мир от нежити Плети, он отказался от священного долга и примкнул к радикальным рядам Алого ордена — роковое решение, определившее власть ордена над Дольным Очагом."}},faq={{q="Что случилось с Северным Долом?",a="Северный Дол был разрушен в Третью войну, когда Плеть прошла по Лордерону. Здания сровняли с землей, а жители погибли от чумы, оставив каменную оболочку, где теперь обитают мстительные духи и оскверненные элементали.",al={"why is northdale ruined","northdale history","what is northdale","почему северный дол в руинах","история северного дола","что такое северный дол"}},{q="Какое важное событие здесь произошло?",a="Именно здесь Телан Фордринг отрекся от Ордена Серебряной Длани. В отчаянии от падения Лордерона он отказался здесь от клятв паладина и присягнул возникавшему Алому ордену.",al={"taelan fordring northdale","what happened to taelan","order of the silver hand northdale","телан фордринг северный дол","что случилось с теланом","орден серебряной длани северный дол"}},{q="Какие существа обитают в руинах сейчас?",a="Руины города кишат воющими банши и невидимыми Безглазыми стражами, служащими Плети. Соседние воды тоже осквернены и кишат оскверненными водными элементалями.",al={"mobs in northdale","northdale enemies","whats in northdale","монстры в северном доле","враги в северном доле","что в северном доле"}},{q="Где находится Северный Дол?",a="Северный Дол находится на северо-востоке Восточных Чумных земель, к северу от Часовни Последней Надежды и к юго-востоку от Талассийского перевала в Кель'Талас.",al={"northdale location","where is northdale","finding northdale","где северный дол","расположение северного дола","найти северный дол"}}},fp="9,406,16.499.0,17.503.1,27.235.0,39.205.0,37.178.0,27.159.0"}
P.entries["subzone:northfold-manor"] = {n="Северное поместье",s="Северное поместье — обветшалая сельская усадьба на северо-западной окраине Нагорья Арати. Когда-то процветавшее человеческое хозяйство до падения Стромгарда, теперь оно занято преступниками Синдиката, занимающимися тревожными темными практиками.",h="Северное поместье — обветшалая сельская усадьба на северо-западной окраине Нагорья Арати.",kw={"arathi highlands","bloodstone","northfold manor","singer","stromgarde","syndicate","tor'gan","нагорье арати","кровавый камень","северное поместье","певец","стромгард","синдикат","тор'ган"},ang={["class:Shaman"]="Демонические остатки над Северным поместьем нарушают естественные стихии, вызывая у приближающихся настроенных шаманов духовное беспокойство и пылкую ярость.",["faction:Horde"]="Шаманы Павшего Молота пристально следят за Северным поместьем и посылают воинов отбирать талисманы из кровавого камня, с помощью которых Синдикат балуется демоническими призывами."},sec={{t="Разбойничье логово",b="Северное поместье, стоящее на холмистом нагорье близ прохода у Стены Торадина, некогда поддерживало королевство Стромгард. В хаосе после распада державы изгнанная альтеракская знать и разбойники Синдиката заняли господский дом, амбар и поля под оперативную базу. Вместо возделывания посевов наемники, грабители и следопыты Синдиката используют ферму для засад на дорогах и координации своего присутствия по всему Арати."},{t="Демонические отголоски",b="За обычным воровством и вооруженным бахвальством Северное поместье скрывает более зловещие занятия. Следы демонических призывов цепляются за ферму, и их остро чувствуют чуткие заклинатели и шаманы региона. Брошенные амулеты из кровавого камня — мощные талисманы для темных призываний — усеивают землю, указывая, что разбойники Синдиката здесь погружаются в демоническую магию, далеко превосходящую простой разбой."}},faq={{q="Кто управляет Северным поместьем?",a="Усадьба попала в руки Синдиката — организации лишенных владений альтеракских дворян, бандитов и наемников-изгоев, которые теперь используют ее как вооруженный лагерь.",al={"who lives here","who owns northfold","syndicate farm","кто здесь живет","кому принадлежит северное поместье","ферма синдиката"}},{q="Какая темная магия здесь применяется?",a="Гости, чувствительные к магическим энергиям, ощущают остаточные следы демонических призывов. У сил Синдиката, расквартированных в поместье, есть амулеты из кровавого камня, которые используются для направления и поддержки опасных демонических ритуалов.",al={"demons at northfold","bloodstone","what are they summoning","демоны в северном поместье","кровавый камень","что они призывают"}},{q="Почему Орду заботит эта ферма?",a="Шаман-тролль Тор'ган из Павшего Молота почувствовал неестественное возмущение, назревающее над нагорьем. Поиск источника привел его прямо к Северному поместью, и Орда занялась расследованием оккультной деятельности Синдиката.",al={"horde interest northfold","why tor'gan cares","интерес орды северное поместье","почему тор'ган беспокоится"}},{q="Кто такой Певец?",a="Певец — неуловимая фигура Синдиката, которого иногда замечают в главном доме Северного поместья среди других разбойников.",al={"singer","singer rare","who is singer","певец","редкий певец","кто такой певец"}}},fp="15,292,17.469.0,18.439.1,29.183.0,40.212.0,40.232.0,14.133.0"}
P.entries["subzone:northpass-tower"] = {n="Башня Северного перевала",s="Башня Северного перевала — разрушенная разведывательная башня Лордерона на севере Восточных Чумных земель, у дороги в Кель'Талас. Разбитая в Третью войну, благодаря своему расположению она стала важным стратегическим призом в нарастающем конфликте между Альянсом и Ордой.",h="Башня Северного перевала — разрушенная разведывательная башня Лордерона на севере Восточных Чумных земель, у...",kw={"eastern plaguelands","lordaeron","northpass tower","quel'thalas","scourge","scout tower","восточные чумные земли","лордерон","башня северного перевала","кель'талас","плеть","разведывательная башня"},ang={["faction:Alliance"]="Возвращение Башни Северного перевала — важный шаг к восстановлению павших бастионов Лордерона и лишению Орды плацдарма на севере.",["faction:Horde"]="Захват этой стратегической руины защищает передвижения на севере и укрепляет наступление Орды против Плети и вторгшихся сил Альянса."},sec={{t="Северный страж",b="Башня Северного перевала, построенная Королевством Лордерон для охраны важной дороги на север в Кель'Талас, была превращена в разбитую оболочку во время вторжения Плети. Несмотря на разрушенную кладку, возвышенное положение башни сохраняет огромную тактическую ценность: она нависает над истерзанным чумой пограничьем между оскверненными окраинами Стратхольма и далекими землями эльфов."},{t="Борьба на передовой",b="Пока Серебряный Рассвет закрепился в Часовне Последней Надежды, и Альянс, и Орда стремятся создать защищенные форпосты в Чумных землях. Башня Северного перевала стала частым очагом столкновений: ее захват укрепляет региональные линии снабжения и дает передовой плацдарм против обеих противоборствующих фракций и наступающих патрулей Плети."}},faq={{q="Для чего изначально построили Башню Северного перевала?",a="Первоначально ее возвел как наблюдательный пост Королевство Лордерон для наблюдения за северной дорогой в эльфийское королевство Кель'Талас.",al={"what is northpass tower","northpass history","why was northpass tower built","что такое башня северного перевала","история башни северного перевала","зачем построили башню северного перевала"}},{q="Почему Башня Северного перевала в руинах?",a="Она была разрушена вместе с остальной северной обороной Лордерона во время вторжения Плети в Третью войну, и остались лишь треснувшая кладка и леса.",al={"who destroyed northpass tower","why is northpass tower broken","кто разрушил башню северного перевала","почему башня северного перевала разбита"}},{q="Почему Альянс и Орда сражаются за эту башню?",a="Обе фракции продвигаются в Чумные земли, чтобы противостоять Плети и друг другу. Владение Башней Северного перевала дает укрепленный разведывательный форпост и важное влияние в регионе на северных дорогах.",al={"why fight over northpass","who controls northpass tower","почему сражаются за северный перевал","кто контролирует башню северного перевала","кому принадлежит башня северного перевала"}},{q="Куда ведет дорога за Башней Северного перевала?",a="Дорога идет на север прямо к границе Талассии и южным землям Кель'Таласа.",al={"road past northpass tower","where does northern road go","дорога за башней северного перевала","куда ведет северная дорога"}}},fp="15,289,17.375.0,20.351.0,46.154.0,32.167.0,52.199.0,46.101.0"}
P.entries["subzone:northridge-lumber-camp"] = {n="Лесопилка Северного Кряжа",s="Лесопилка Северного Кряжа — действующая лесопилка в северных холмах Западных Чумных земель, неподалеку от Дольного Очага. Сейчас ее удерживает и укрепляет Алый орден: она поставляет древесину, жизненно важную для его ближайших оплотов. И Альянс, и Орда считают это предприятие удобной целью, чтобы подорвать региональную инфраструктуру фанатиков.",h="Лесопилка Северного Кряжа — действующая лесопилка в северных холмах Западных Чумных земель, неподалеку от...",kw={"dumah","hearthglen","levine","lumber","mill","northridge","plaguelands","scarlet crusade","termites","дума","дольный очаг","левин","древесина","лесопилка","северный кряж","чумные земли","алый орден","термиты"},ang={["faction:Alliance"]="Хотя Алый орден заявляет, что борется с нежитью, его жестокая ксенофобия делает его угрозой для разведки и действий Альянса на севере Лордерона.",["faction:Horde"]="Для Отрекшихся и их союзников из Орды срыв лесозаготовок ордена ослабляет Дольный Очаг и отбрасывает фанатиков назад к их оплотам."},sec={{t="Топливо для ордена",b="Лесопилка Северного Кряжа находится недалеко от Дольного Очага по дороге и служит важным логистическим узлом Алого ордена. Несмотря на не отступающую чуму, душащую окрестные леса, лагерь валит и обрабатывает местную древесину для строительства укреплений, ремонта сторожевых башен и нужд военных усилий ордена в Лордероне. Лесопилку охраняют многочисленные фанатичные рабочие и стражи, и она ревностно защищена как от Плети, так и от посторонних."},{t="Цель для диверсии",b="Поскольку Дольный Очаг сильно зависит от этой древесины для поддержания обороны, посторонние силы активно замышляют сорвать ее поставки. И командиры Альянса, и разведчики Орды понимают, что открытый штурм укрепленных позиций ордена обойдется дорого. Поэтому агенты прибегают к нестандартным диверсиям — например, выпускают прожорливых древесных термитов на склады лесопилки, чтобы тихо сгноить запасы ордена изнутри."}},faq={{q="Кто контролирует Лесопилку Северного Кряжа?",a="Лесопилку сейчас контролирует и использует Алый орден: его стражи и рабочие заготавливают древесину для соседнего Дольного Очага.",al={"who runs northridge","who controls the lumber mill","northridge faction","кто управляет северным кряжем","кто контролирует лесопилку","фракция лесопилки северного кряжа"}},{q="Почему эта лесопилка важна?",a="Она поставляет необходимую древесину и стройматериалы для поддержания укреплений и застав Алого ордена на севере Западных Чумных земель.",al={"why does northridge matter","significance of northridge","what is this camp for","почему важна лесопилка северного кряжа","значение лесопилки","для чего этот лагерь"}},{q="Почему Альянс и Орда хотят устроить там диверсию?",a="Обе фракции считают агрессивный и фанатичный Алый орден опасной угрозой в Чумных землях. Лишив его древесины, они ослабят его способность укреплять Дольный Очаг и избегут дорогостоящего прямого вторжения.",al={"why attack northridge","termites quest","why ruin the lumber","зачем нападать на лесопилку","задание про термитов","зачем портить древесину"}},{q="Кто управлял лесопилкой до Третьей войны?",a="Пока Королевство Лордерон не пало под ударами Плети, на лесопилке жили и работали местные семьи, например Думы и Левины, ведя тихое региональное дело.",al={"who owned northridge lumber camp","history of northridge mill","кому принадлежала лесопилка северного кряжа","история лесопилки северного кряжа"}}},fp="22,356,19.470.0,19.440.0,36.139.0,34.158.0,50.218.0,38.165.0"}
P.entries["subzone:northshire-abbey"] = {n="Аббатство Североземья",s="Аббатство Североземья — историческая обитель в Долине Североземья, в северных предгорьях Элвиннского леса. Восстановленное после разрушения в Первую войну, оно служит духовным сердцем Братства Североземья и главным учебным центром для новых защитников, откликающихся на зов королевства Штормград.",h="Аббатство Североземья — историческая обитель в Долине Североземья, в северных предгорьях Элвиннского леса.",kw={"abbey","brotherhood","clerics","defias","elwynn","faol","northshire","valley","аббатство","братство","священники","братство справедливости","элвиннский лес","фаол","североземье","долина"},ang={["class:Paladin"]="Североземье воплощает наследие архиепископа Алонсуса Фаола и первых священников, чьи жертвы заложили основу Рыцарей Серебряной Длани.",["race:Human"]="Для людей Штормграда Аббатство Североземья — колыбель вашего пути, где история стойкости и преданности королевства встречает каждого новобранца, берущегося за оружие."},sec={{t="Наследие веры и руин",b="Много столетий назад священники из Лордерона отправились на юг, в королевство Штормград, чтобы нести поклонение Свету, и основали Священный орден священников Североземья и свое аббатство. Обитель быстро стала опорой жизни королевства: она заботилась о больных и даже ухаживала за юным Хранителем Медивом в годы его комы. В Первую войну аббатство не раз подвергалось нападениям разбойников и Орочьей Орды, и в итоге было полностью разрушено. Когда Альянс Лордерона освободил эти земли во Вторую войну, архиепископ Алонсус Фаол помог восстановить святилище, вновь основав его защитников как Братство Североземья."},{t="Учебные земли",b="Сегодня Аббатство Североземья служит отправной точкой для добровольцев, новобранцев ополчения и послушников, желающих защитить осажденный Штормград. Оно делится на Главный зал, Зал Оружия и Библиотечное крыло; здесь работают наставники боевых, тайных и священных искусств, а разведчики и разбойники тренируются на внешних дворах. Несмотря на бдительное присутствие Рыцарей Серебряной Длани, мир здесь хрупок. Кобольды заполонили ближние рудники, агрессивные волки бродят по садам, а агенты Братства Справедливости рыщут на дорогах долины, похищая древние свитки и священные манускрипты из богатых архивов аббатства."}},faq={{q="Что такое Братство Североземья?",a="Братство Североземья — религиозный орден священников, жрецов и паладинов, базирующийся в Аббатстве Североземья. Изначально его основали много столетий назад священники-миссионеры из Лордерона; после Первой войны архиепископ Алонсус Фаол воссоздал его, чтобы обучать верных защитников и хранить священные писания.",al={"who runs northshire abbey","northshire clerics","brotherhood of northshire lore","кто управляет аббатством североземья","священники североземья","предания братства североземья"}},{q="Почему Аббатство Североземья было разрушено в Первую войну?",a="Во время Первой войны аббатство имело для Штормграда стратегическое и духовное значение. Орки подстрекали людей-разбойников напасть на него, а после того как там ненадолго оказалась в плену полуорк Гарона, огромное нашествие Орды сровняло священную землю с землей. Оно оставалось в руинах всю войну, пока Альянс не изгнал орочьи кланы и не отстроил его.",al={"who destroyed northshire abbey","northshire first war","what happened to northshire","кто разрушил аббатство североземья","североземье первая война","что случилось с североземьем"}},{q="Почему у аббатства есть бандиты Братства Справедливости и кобольды?",a="Армия Штормграда растянута по дальним границам, и отдаленные земли почти не охраняются. Кобольды-оппортунисты заселили местные золотые рудники, а Братство Справедливости пользуется брешами, чтобы грабить путников, донимать местные виноградники и воровать из библиотеки аббатства тайные фолианты и священные реликвии.",al={"why is northshire under attack","kobolds in northshire","defias outside northshire","почему нападают на североземье","кобольды в североземье","братство справедливости у североземья"}},{q="Какая связь между Аббатством Североземья и Мертвыми копями?",a="Во время Первой войны вождь огров по имени Турок похитил из Аббатства Североземья священный Фолиант Божественности и скрылся в Мертвых копях. Сэр Андуин Лотар повел экспедицию в глубины, чтобы вернуть священное писание, но оказался в ловушке, пока королевский отряд не спас его и не вернул фолиант на попечение аббатства.",al={"tome of divinity northshire","northshire deadmines lore","anduin lothar deadmines","фолиант божественности североземье","мертвые копи североземье предания","андуин лотар мертвые копи"}}},fp="16,322,26.656.0,20.618.0,38.314.0,52.351.0,59.321.0,66.320.0"}
P.entries["subzone:northshire-valley"] = {n="Долина Североземья",s="Долина Североземья, укрытая в северных горах Элвиннского леса, — мирная колыбель и учебная площадка для новейших защитников королевства Штормград. Окруженная природными преградами, она вмещает историческое Аббатство Североземья, плодородные виноградники и богатый Рудник Горного Эха. Несмотря на безмятежный вид, в долине растет смута: разбойники, заполонившие ее кобольды и изгнанные хищники.",h="Долина Североземья, укрытая в северных горах Элвиннского леса, — мирная колыбель и учебная площадка для...",kw={"abbey","defias","echo ridge","elwynn","kobolds","mcbride","northshire","vineyards","willem","аббатство","братство справедливости","горное эхо","элвиннский лес","кобольды","макбрайд","североземье","виноградники","виллем"},ang={["faction:Alliance"]="Североземье служит важным пунктом набора и восстановления для Великого Альянса: здесь обучают новое поколение защитников, чтобы укрепить сердце королевства.",["race:Human"]="Для людей Штормграда Долина Североземья — место, где начинается их путь: они вступают на земли аббатства, чтобы откликнуться на зов нуждающегося королевства."},sec={{t="Укромное святилище",b="Долину Североземья обрамляют почти непроходимые горные гряды, и единственная дорога ведет на юг через укрепленную сторожку к Златоземью и остальному Элвиннскому лесу. Чистая река петляет среди пастбищ и течет на юг в Озеро Хрустальное. В сердце долины стоит Аббатство Североземья — древнее святилище, где учат Свету и где новобранцев обучают Рыцари Серебряной Длани и опытные ветераны. За стенами аббатства лежат обильные Виноградники Североземья и Рудник Горного Эха, образуя самодостаточный уголок земель Штормграда, далекий от войн большого мира."},{t="Надвигающиеся беды",b="Даже этот укромный уголок ощутил тяготы перегруженной обороны Штормграда. Маршал Макбрайд и его отряд Стражи Штормграда с трудом поддерживают порядок в долине. Стаи волков, изгнанных на север из зараженного Сумеречного леса, бродят по окрестным лесам, а похожие на паразитов кобольды заполонили туннели Рудника Горного Эха. Хуже того, люди в масках из Братства Справедливости открыто донимают виноградники и угрожают землям аббатства, вынуждая местных командиров вербовать каждого здорового гражданина, пришедшего к их воротам."}},faq={{q="Почему Долина Североземья так хорошо охраняется?",a="В долине находится Аббатство Североземья — важный духовный центр и учебная площадка войск Штормграда, а также ценные местные ресурсы, такие как Рудник Горного Эха и виноградники. Поскольку армия Штормграда растянута, маршал Макбрайд держит охраняемые ворота на южном перевале, чтобы угрозы не проникали между долиной и остальным Элвиннским лесом.",al={"why guards northshire","gate in northshire","who protects northshire","зачем охрана в североземье","ворота в североземье","кто защищает североземье"}},{q="Откуда в долине столько волков?",a="Заместитель судьи Виллем отмечает, что стаи волков недавно хлынули через реку, бежав в долину из темных чащ Сумеречного леса на юге. Тьма, расползающаяся по Сумеречному лесу, выгнала диких зверей на обычно мирные пастбища.",al={"why so many wolves","wolf infestation","wolves from duskwood","почему так много волков","нашествие волков","волки из сумеречного леса"}},{q="Почему кобольды нападают на Рудник Горного Эха?",a="Кобольды — норные оппортунисты, привлеченные подземными жилами. Когда патрулей королевства стало меньше, клан кобольдов воспользовался отсутствием защиты и занял Рудник Горного Эха ради золота и свечей, выгнав людей-шахтеров из туннелей.",al={"echo ridge kobolds","why kobolds in northshire","kobold problem","кобольды горного эха","почему кобольды в североземье","проблема с кобольдами"}},{q="Кто эти бандиты, донимающие виноградники?",a="Воры возле виноградника Милли Осворт — агенты Братства Справедливости. Они орудуют на окраинах долины, чтобы срывать поставки, донимать местных фермеров и проверять оборону аббатства.",al={"vineyard bandits","defias in northshire","red mask thugs","бандиты на виноградниках","братство справедливости в североземье","бандиты в красных масках"}},{q="Что случилось с Североземьем во Вторую войну?",a="Во Вторую войну Аббатство Североземья попало в руки врага, и его ненадолго использовал как штаб клан Сумеречного Молота Чо'Галла, пока Альянс не вернул и не восстановил долину.",al={"northshire second war","twilight hammer northshire","chogall northshire","североземье вторая война","сумеречный молот североземье","чо'галл североземье"}},{q="Как покинуть Долину Североземья?",a="Единственный проходимый пеший выход — южная дорога через охраняемую сторожку. Пройдя эти ворота, путники попадают прямо в центральную часть Элвиннского леса, на главную дорогу к Златоземью.",al={"exit northshire","path to goldshire","how to leave","выход из североземья","путь в златоземье","как уйти"}}},fp="17,423,20.635.0,20.549.0,44.358.0,49.250.0,42.256.0,44.204.0,50.196.0,35.215.0"}
P.entries["subzone:northshire-vineyards"] = {n="Виноградники Североземья",s="Виноградники Североземья — возделываемые виноградные поля к востоку от Аббатства Североземья, в защищенной низине долины. Когда-то они мирно снабжали вином священников, но теперь поля перешли под власть Братства Справедливости и его местных разбойников.",h="Виноградники Североземья — возделываемые виноградные поля к востоку от Аббатства Североземья, в защищенной...",kw={"defias","elwynn","garrick padfoot","grapes","milly osworth","northshire valley","northshire vineyards","братство справедливости","элвиннский лес","гаррик тихокрад","виноград","милли осворт","долина североземья","виноградники североземья"},ang={["faction:Alliance"]="Беспорядки на этих мирных виноградных полях показывают, как глубоко беззаконие проникло даже в самые защищенные уголки королевства Штормград.",["race:Human"]="Для многих молодых людей, отправляющихся в мир, занятые виноградники — первая прямая встреча с жестокостью и размахом Братства Справедливости."},sec={{t="Разграбленный урожай",b="Виноградники Североземья расположены к востоку от Аббатства Североземья, за ручьем, и отражают тихую сельскую жизнь долины. Поля обрабатывают местные работники вроде Милли Осворт, но растущие беспорядки оставили их без защиты. Бандиты Братства Справедливости, которыми на месте командует головорез по имени Гаррик Тихокрад, захватили угодья. Воры не просто безобразничат: они занимают поля, чтобы разграбить урожай и лишить местных фермеров средств к существованию, давая новобранцам Братства легкую опору прямо под носом у аббатства."}},faq={{q="Кто сейчас контролирует Виноградники Североземья?",a="Поля занимают воры и головорезы из Братства Справедливости. Их местный главарь — Гаррик Тихокрад, разыскиваемый разбойник, который руководит разграблением урожая и запугивает местных работников.",al={"who is at the vineyards","who took over northshire vineyards","who is garrick padfoot","кто на виноградниках","кто захватил виноградники североземья","кто такой гаррик тихокрад"}},{q="Почему аббатство позволяет бандитам хозяйничать на полях?",a="Военные ресурсы Штормграда предельно растянуты из-за исчезновения короля Вариана Ринна. Стражи аббатства отошли для защиты самого аббатства и наблюдения за дорогами долины, и местным фермерам приходится рассчитывать на недавно прибывших искателей приключений, чтобы вернуть украденное.",al={"why no stormwind guards","why isn't the abbey defending the vineyards","почему нет стражи штормграда","почему аббатство не защищает виноградники"}},{q="Кто такая Милли Осворт?",a="Милли Осворт — местная фермерша, работающая на виноградниках. Когда бандиты Братства Справедливости пришли и захватили урожай винограда, ее прогнали, и теперь она ищет храбрых путников, готовых отправиться на поля и вернуть ее украденные ящики.",al={"milly osworth","who is milly","милли осворт","кто такая милли"}}},fp="20,269,19.577.0,48.206.0,59.276.0,21.227.0"}
P.entries["subzone:noxious-glade"] = {n="Ядовитая поляна",s="Ядовитая поляна — уединенная котловина в холмах к северу от Часовни Последней Надежды, пропитанная концентрированной чумой. Воздух там отравлен зеленым туманом, а почва потемнела; поляна служит ближним оплотом Плети прямо под носом у Серебряного Рассвета.",h="Ядовитая поляна — уединенная котловина в холмах к северу от Часовни Последней Надежды, пропитанная...",kw={"blight","eastern plaguelands","light's hope chapel","noxious glade","plague cauldron","scourge","slaughterhouse","ziggurat","скверна","восточные чумные земли","часовня последней надежды","ядовитая поляна","чумной котел","плеть","бойня","зиккурат"},ang={["class:Paladin"]="Поляна тревожно напоминает, как близко скверна Плети подобралась к священному убежищу Часовни Последней Надежды; здесь немало поганищ и некромантов, которых нужно уничтожить.",["race:Undead"]="Отрекшиеся узнают здесь бойни и чумные котлы как обычные орудия власти Короля-лича — яркое напоминание о судьбе тех, кто не сумел освободиться."},sec={{t="Мерзкий плацдарм",b="Пока Серебряный Рассвет несет дозор в Часовне Последней Надежды, лагерь Плети затаился в холмах прямо к северу от нее. Ядовитая поляна заражена куда сильнее окрестных земель: воздух затянут болезненной зеленой дымкой, а почва сгнила до глубокого лиловато-синего цвета. В низине нежить возвела зиккураты, бойню для сшивания поганищ и чумной котел, который непрерывно извергает заразу в воздух."},{t="Под взором Рассвета",b="Из-за близости к часовне поляна постоянно угрожает путникам, гонцам и святым воинам, действующим из Часовни Последней Надежды. Закрепившиеся здесь силы Плети создают мерзостных чудовищ и варят яды, не боясь солнечного света; их скрывает окружающий природный хребет, пока неосторожный путник не поднимется по тропе прямо в их гущу."}},faq={{q="Где находится Ядовитая поляна?",a="Ядовитая поляна находится в холмах сразу к северу от Часовни Последней Надежды, в восточной части Восточных Чумных земель.",al={"where is noxious glade","noxious glade location","how to get to noxious glade","где ядовитая поляна","расположение ядовитой поляны","как добраться до ядовитой поляны"}},{q="Почему здесь воздух и земля другого цвета?",a="Поляна сильно поражена скверной даже по меркам остальных Чумных земель. Действующий чумной котел и расположенные рядом сооружения Плети непрерывно нагнетают яды в низину, окрашивая землю в темно-лиловый цвет и окутывая поляну ядовитой зеленой дымкой.",al={"why is it green","why is ground purple","noxious glade blight","почему зеленый воздух","почему земля фиолетовая","скверна ядовитой поляны"}},{q="Какие сооружения Плети есть на поляне?",a="На поляне стоят типичные постройки Плети: высокий чумной котел, несколько зиккуратов и бойня, где собирают чудовищные создания вроде поганищ.",al={"what is inside noxious glade","noxious glade buildings","что на ядовитой поляне","постройки ядовитой поляны"}},{q="Знает ли Серебряный Рассвет об этом месте?",a="Да, но его силы постоянно распылены на защиту от массированных атак Плети по всем Чумным землям, поэтому такие форпосты, как Ядовитая поляна, остаются опасными гнойниками сразу за границей владений часовни.",al={"lights hope chapel aware","argent dawn noxious glade","часовня последней надежды знает","серебряный рассвет ядовитая поляна"}}},fp="13,268,15.527.0,21.374.0,35.134.0,49.257.0,41.186.0,43.224.0"}
P.entries["subzone:noxious-lair"] = {n="Ядовитый улей",s="Ядовитый улей — просевшее гнездо силитидов в юго-западных пустынях Танариса, у границы с Кратером Ун'Горо. Когда-то это была зеленая низина с проточной водой, но роющий рой Сентипаар заразил ее и истощил. Теперь это кислотный рассадник, кишащий насекомоподобными тварями, с богатыми рудными жилами.",h="Ядовитый улей — просевшее гнездо силитидов в юго-западных пустынях Танариса, у границы с Кратером Ун'Горо.",kw={"centipaar","hive","noxious lair","sandreaver","silithid","soriid","tanaris","сентипаар","улей","ядовитый улей","песчаный губитель","силитид","сориид","танарис"},ang={["class:Druid"]="Улей — тревожное извращение природы: он показывает, как быстро захватчики-силитиды могут превратить некогда орошаемую низину в безводную кислотную пустошь.",["profession:Mining"]="Рытье силитидов в низине обнажило необычно разнообразные руды, и горняки могут добывать в одном месте жилы железа, мифрила, истинного серебра и тория."},sec={{t="Истощенная низина",b="Ядовитый улей лежит у западных хребтов над Кратером Ун'Горо, в песчаной впадине, где прежде было озеро или мелкая река. Когда пришли силитиды Сентипаар, они вытянули остатки подземной влаги пустыни и превратили низину в разрастающуюся колонию. Огромные клешни и дергающиеся конечности поднимаются прямо из дюн, а вокруг тянутся подземные ходы, скользкие от едких выделений насекомых, и кладки яиц."},{t="Рой Сентипаар",b="Подземные туннели соединяют входы на поверхности с влажными, покрытыми кислотой выводковыми камерами под песками. Рабочие центипаары, прокладчики туннелей, осы и огромные песчаные разрушители патрулируют периметр, защищая свой выводок от внешних угроз. Помимо биологической опасности, перемены, вызванные раскопками силитидов, обнажили глубокие залежи минералов, и это создало необычно разнообразное место для охоты и добычи руды, где подземные руды лежат открыто среди роящихся ульев."}},faq={{q="Какие существа живут в Ядовитом улье?",a="Улей населяет Сентипаар — колония насекомоподобных силитидов. Его защищают рабочие, роющие туннельщики, летающие осы и хищные песчаные губители, а правят ими редкие ужасы улья, например Сориид Пожиратель.",al={"what mobs are in noxious lair","noxious lair insects","centipaar silithid","какие мобы в ядовитом улье","насекомые ядовитого улья","силитиды сентипаар"}},{q="Что было здесь до того, как власть захватили силитиды?",a="Просевший рельеф говорит о том, что здесь было русло реки или мелкое пустынное озеро. Пришедшие силитиды зарылись в землю, лишили западный Танарис воды и природных ресурсов и оставили пустынную, пропитанную кислотой низину.",al={"noxious lair history","was noxious lair a lake","water in noxious lair","история ядовитого улья","было ли здесь озеро","вода в ядовитом улье"}},{q="Почему гоблины интересуются этим ульем?",a="Гоблины Прибамбасска считают улей угрозой торговле в пустыне и отправили искателей приключений изучить его и расширение силитидов.",al={"goblin quests noxious lair","steamwheedle noxious lair","thunderdrome silithid","задания гоблинов ядовитый улей","картель ядовитый улей","силитиды громодром"}},{q="Связан ли Ядовитый улей с другими ульями насекомых в пустыне?",a="Ядовитый улей — это улей Сентипаар, одна из нескольких колоний насекомоподобных, расползающихся с южных пустошей. Хотя он обособлен от ульев дальше к югу, его туннели имеют ту же жуткую подземную структуру и грозят задушить жизнь по всему Танарису.",al={"other hives tanaris","centipaar hive connection","silithid expansion","другие ульи танариса","связь улья сентипаар","расширение силитидов"}}},fp="12,359,15.475.0,19.467.0,48.244.0,44.252.0,40.140.0,66.279.0"}
P.entries["subzone:old-ironforge"] = {n="Старый Стальгорн",s="Старый Стальгорн, также называемый Собранием тэнов, — древний подземный зал прямо под Высоким троном Стальгорна. Он высечен глубоко в корнях горы над светящимися жилами магмы и является исконным сердцем столицы дворфов. Сегодня тяжелые ворота к нему в тронном зале остаются запертыми и под бдительной охраной.",h="Старый Стальгорн, также называемый Собранием тэнов, — древний подземный зал прямо под Высоким троном...",kw={"aegrim's study","assembly of thanes","high seat","ironforge","magni bronzebeard","old ironforge","кабинет эйгрима","собрание тэнов","высокий трон","стальгорн","магни бронзобород","старый стальгорн"},ang={["class:Rogue"]="Глава шпионов Штормграда Матиас Шоу строго предостерегает от попыток пробраться в Старый Стальгорн, напоминая о сильной охране и мрачной цене попадания в руки стражи короля Магни.",["race:Dwarf"]="Для дворфов Старый Стальгорн и Собрание тэнов — священная связь с предками; здесь сохранились глубочайшие каменные основания, высеченные на заре их горного королевства."},sec={{t="Собрание тэнов",b="Под троном короля Магни Бронзоборода в Высоком троне находится огромный зал, известный как Старый Стальгорн, или Собрание тэнов. В глубине этих огненных подземных основ каменные мосты вьются над озерами лавы. Задолго до того, как в шумных залах Великой кузни и Общинного квартала зазвучала современная торговля дворфов, первые тэны собирались в этих пещерных глубинах, чтобы совещаться и править горным королевством."},{t="Запечатанный зал",b="Сейчас вход в Старый Стальгорн из тронного зала надежно закрыт. Королевская стража Стальгорна строго следит за порогами, ведущими вниз, в старые подземелья. Даже Мастер Матиас Шоу из ШРУ Штормграда отмечает усиленную охрану этих нижних уровней и предупреждает, что любая попытка проникнуть туда или вмешаться в дела закрытого подземного города грозит суровым дворфийским правосудием."}},faq={{q="Что такое Старый Стальгорн?",a="Старый Стальгорн, исторически известный как Собрание тэнов, — древний нижний район, высеченный прямо под современным городом Стальгорном. Он состоит из пещерных залов и лавовых каналов.",al={"assembly of thanes","what is old ironforge","subterranean ironforge","собрание тэнов","что такое старый стальгорн","подземный стальгорн"}},{q="Могут ли игроки попасть в Старый Стальгорн?",a="Нет. Главные ворота в тронном зале Высокого трона заперты, а вход усиленно охраняет королевская стража дворфов. Залы внизу закрыты для обычных жителей и искателей приключений.",al={"how to get into old ironforge","is old ironforge open","old ironforge door locked","как попасть в старый стальгорн","открыт ли старый стальгорн","дверь старого стальгорна закрыта"}},{q="Где находится вход?",a="Вход находится прямо внутри Высокого трона — королевского приемного зала, где в Стальгорне восседает король Магни Бронзобород.",al={"where is old ironforge entrance","old ironforge location","где вход в старый стальгорн","расположение старого стальгорна"}},{q="Чем Старый Стальгорн важен для истории дворфов?",a="Известный как Собрание тэнов, он служил древним местом встреч вождей дворфов и горных королей в ранние эпохи, до того как верхние кольца современной горной столицы были полностью построены.",al={"history of old ironforge","why is it called assembly of thanes","история старого стальгорна","почему называется собрание тэнов"}}},fp="13,365,22.435.0,16.387.0,22.194.0,32.198.0,30.141.0,52.202.0"}
P.entries["subzone:old-port-authority"] = {n="Старое портовое управление",s="Старое портовое управление — оживленный склад с множеством торговцев на дощатых мостках Пиратской бухты. Пока гоблинские бригады постоянно чинят его ветхую крышу, посетители внутри выбирают все: от экзотических питомцев и огнестрельного оружия до сытной провизии и искусно сделанного оружия.",h="Старое портовое управление — оживленный склад с множеством торговцев на дощатых мостках Пиратской бухты.",kw={"blackwater cartel","boomstick imports","booty bay","cuts-n-bruises","goblin construction","nautical needs","old port authority","stranglethorn vale","картель Мутной Воды","бумстик импорт","пиратская бухта","порезы и ушибы","гоблинские строители","морские нужды","старое портовое управление","тернистая долина"},ang={["class:Hunter"]="Торговцы из «Восточного импорта Бумстик» делают это здание надежной остановкой, чтобы пополнить запас пуль и пороха перед походом в глухие джунгли Тернистой долины.",["profession:Cooking"]="Путешественники-кулинары могут заглянуть в «Добрую еду» за региональными кулинарными ингредиентами и провизией, привезенной проходящими торговыми судами."},sec={{t="Торговля под дырявой крышей",b="Старое портовое управление, расположенное в пиратской гавани Пиратской бухты, — крытый рынок, разделенный на отдельные лавки. Пока гоблины-строители стучат молотками на крыше, внутри кипит бойкая торговля. Торговцы предлагают общие припасы для приключений, огнестрельное оружие, луки, еду и оружие как негодяям, так и каперам. Здесь также продают экзотические товары: ярких птиц и морские диковинки прямо с причалов — всякому, у кого есть деньги."}},faq={{q="Что такое Старое портовое управление?",a="Это крупный торговый склад в Пиратской бухте, разделенный на несколько рыночных лавок. Искатели приключений и буканьеры приходят сюда за едой, боеприпасами, оружием и мелкими товарами под крышей, которую гоблины почти непрерывно чинят.",al={"what is this building","booty bay warehouse","port authority booty bay","что это за здание","склад пиратской бухты","портовое управление пиратской бухты"}},{q="Почему гоблины работают на крыше?",a="Влажный соленый морской воздух Тернистой долины постоянно разрушает деревянные постройки Пиратской бухты. Гоблинские бригады часто стучат молотками по деревянным стропилам, чтобы шумный рынок оставался под крышей.",al={"why construction on roof","goblin roof repair","roof workers","почему ремонтируют крышу","гоблины чинят крышу","рабочие на крыше"}},{q="Какие лавки здесь есть?",a="На складе пять отдельных торговых лавок: «Морские нужды», «Добрая еда», «Быстрые полеты», «Восточный импорт Бумстик» и «Порезы и ушибы, Инк.»; в них продают провизию, оружие, ручных птиц и товары первой необходимости.",al={"vendors inside","shops in port authority","what can i buy here","торговцы внутри","лавки портового управления","что здесь можно купить"}},{q="Можно ли здесь купить питомцев?",a="Да. В лавке «Морские нужды» путешественники могут приобрести экзотических птиц-спутников, например кореллу и сенегальского попугая — популярных питомцев среди местных моряков и корсаров.",al={"pet vendor booty bay","parrots booty bay","nautical needs vendor","торговец питомцами пиратская бухта","попугаи пиратская бухта","морские нужды торговец"}}},fp="18,283,29.466.0,31.235.0,36.220.0,28.212.0,22.171.0"}
P.entries["subzone:old-town"] = {n="Старый город",s="Старый город — самый древний и суровый квартал Штормграда, который в основном уцелел после разрушений Первой войны. Вместо сверкающих каменных площадей здесь узкие переулки, потемневший кирпич, жилые дома рабочего люда и шумные военные объекты. Здесь расположены Ставка командования королевства, а также тайная штаб-квартира ШРУ.",h="Старый город — самый древний и суровый квартал Штормграда, который в основном уцелел после разрушений Первой...",kw={"champions hall","command center","first war","mathias shaw","old town","pig and whistle","si:7","stormwind","зал защитников","ставка командования","первая война","матиас шоу","старый город","свинья и свисток","шру","штормград"},ang={["class:Rogue"]="Старый город — ваше естественное убежище в столице: за обычными переулками скрывается штаб ШРУ, где мастера-шпионы и тайные наставники дают советы.",["class:Warrior"]="Ставка командования и Зал Защитников делают Старый город главным местом сбора в Штормграде для закаленных в боях ветеранов, ищущих снаряжение и боевую подготовку."},sec={{t="Наследие старого королевства",b="Пока остальной Штормград после Первой войны заново отстраивали с нуля Каменщики, Старый город избежал полного разрушения. Поскольку его не требовалось отстраивать целиком, он так и не получил безупречных мраморных фасадов и величественных каналов, как Торговый квартал или Соборная площадь. Это по-прежнему простой, тесный квартал, где живут рабочие, чернорабочие и беднейшие горожане. Его мощеные улицы уже, грязнее и куда хаотичнее, чем в остальной столице, но они хранят подлинную атмосферу довоенного Штормграда."},{t="Солдаты, шпионы и таверны",b="За потемневшими жилыми домами Старый город служит военной опорой столицы Альянса. В Ставке командования находятся офицеры Штормграда, казармы и боевые наставники, а рядом расположен Зал Защитников, где собираются лучшие воины Альянса. На краю квартала скрыт тайный штаб ШРУ — секретной разведывательной службы королевства, которой руководит Мастер Матиас Шоу. Пехотинцы в увольнении и тайные агенты собираются в таверне «Свинья и свисток», в одном из самых оживленных питейных заведений города."}},faq={{q="Почему Старый город выглядит намного грязнее остального Штормграда?",a="Старый город в основном уцелел, когда Орда разрушила Штормград во время Первой войны. Поскольку он не был разрушен до основания, Каменщики не отстраивали его заново, и ему не достались новая безупречная кладка и величественная архитектура, которыми обзавелся остальной город.",al={"why is old town run down","old town poverty","why is old town gross","почему старый город запущен","бедность старого города","почему старый город грязный"}},{q="Что такое ШРУ и где оно находится?",a="ШРУ — секретная разведывательная служба Штормграда и Альянса, во главе которой стоит Мастер Матиас Шоу. Ее тайная штаб-квартира скрыта в глубине Старого города, за тренировочными дворами и военными конюшнями.",al={"si7 location","what is si:7","stormwind spies","шру местонахождение","что такое шру","шпионы штормграда"}},{q="Для чего нужна Ставка командования в Старом городе?",a="Ставка командования служит главным гарнизоном и штабом армии Штормграда. В ней и вокруг ее двора офицеры координируют оборону города, а воины и охотники тренируются рядом с конюхами и инструкторами верховой езды.",al={"command center purpose","old town barracks","stormwind military headquarters","назначение ставки командования","казармы старого города","штаб армии штормграда"}},{q="Где находится таверна в Старом городе?",a="Местный трактир — таверна «Свинья и свисток», расположенная почти в центре района. Она известна тем, что в ней собираются голодные солдаты, искатели приключений и путники, ищущие рецепты сытных блюд.",al={"old town inn","pig and whistle location","where is pig and whistle","трактир старого города","где свинья и свисток","таверна свинья и свисток"}}},fp="8,373,26.585.0,28.556.0,66.262.0,37.217.0,48.237.0,32.200.0"}
P.entries["subzone:olsen-s-farthing"] = {n="Удел Ольсена",s="Удел Ольсена когда-то был процветающей фермой на главной торговой дороге через Серебряный бор. После Третьей войны поля пришли в запустение, и их заполонили поднятые рабы, подчиненные отступнику-некроманту Тулу Когтю Ворона.",h="Удел Ольсена когда-то был процветающей фермой на главной торговой дороге через Серебряный бор.",kw={"fenris isle","lordaeron farm","olsen's farthing","olsens farthing","ravenclaw raiders","ravenclaw slaves","silverpine forest","thule ravenclaw","остров фенриса","ферма лордерона","удел ольсена","налетчики когтя ворона","рабы когтя ворона","серебряный бор","тул коготь ворона"},ang={["faction:Horde"]="Уничтожение налетчиков в Уделе Ольсена жизненно важно для защиты дороги снабжения, соединяющей Гробницу на севере и путь к Тирисфальским лесам.",["race:Undead"]="Для Отрекшихся такие места, как Удел Ольсена, — мрачное напоминание об угрозе Плети, которая стремится не освободить мертвых, а поработить их."},sec={{t="Оскверненная усадьба",b="До того как чума поглотила Лордерон, Удел Ольсена был оживленной сельской усадьбой с прямым выходом на главный сухопутный торговый путь Серебряного бора. Сегодня его вспаханные поля заросли сорняками, постройки разрушены, а всякая память о честном земледелии стерта некромантией Плети. Нежить, порабощенная и служащая налетчиками под началом Тула Когтя Ворона, бродит по пустошам и убивает всех путников, подошедших слишком близко."},{t="Хватка Когтя Ворона",b="Шаркающие ужасы, населяющие Удел Ольсена, — не бездумные бродяги, а слуги Тула Когтя Ворона, могущественного некроманта, действующего с Острова Фенриса посреди Озера Лордамер. Темным колдовством он оживляет и порабощает мертвецов окрестных земель; влияние Тула простирается через Удел Ольсена и прямо угрожает Отрекшимся, стремящимся укрепить северные рубежи Серебряного бора."}},faq={{q="Чем был Удел Ольсена до Третьей войны?",a="Это была продуктивная придорожная ферма, поддерживавшая местную торговлю на главном торговом тракте Серебряного бора и кормившая поселения Лордерона до его падения под натиском Плети.",al={"olsens farthing history","what was this place","who lived at olsens farthing","история удела ольсена","что это было за место","кто жил в уделе ольсена"}},{q="Почему ферма кишит нежитью?",a="Ферма была разрушена во время Третьей войны, а ее остатки захватил некромант Тул Коготь Ворона, который поднял мертвецов как рабов и налетчиков, чтобы терроризировать путников на дороге.",al={"why are there undead here","who controls the undead at olsens farthing","ravenclaw slaves silverpine","почему здесь нежить","кто управляет нежитью удела ольсена","рабы когтя ворона серебряный бор"}},{q="Кто такой Тул Коготь Ворона?",a="Тул Коготь Ворона — опасный некромант, связанный с Плетью, который из своей крепости на Острове Фенриса организует набеги нежити по всему Серебряному бору.",al={"who is thule ravenclaw","thule ravenclaw lore","who commands ravenclaw raiders","кто такой тул коготь ворона","предания о туле когте ворона","кто командует налетчиками когтя ворона"}},{q="Есть ли здесь присутствие Орды или Отрекшихся?",a="Нет. Ферма полностью захвачена враждебной нежитью, преданной Тулу Когтю Ворона, поэтому она опасна и для разведчиков Отрекшихся, и для путников Орды.",al={"is olsens farthing horde","do forsaken live at olsens farthing","is there a quest hub here","принадлежит ли удел ольсена орде","живут ли отрекшиеся в уделе ольсена","есть ли здесь задания"}}},fp="16,270,20.455.0,22.434.1,47.192.0,37.190.0,23.163.0,50.150.0"}
P.entries["subzone:oneiros"] = {n="Онейрос",s="Онейрос — обширные руины древних ночных эльфов к югу от Нефритового озера на севере Фераласа. Тесно связанные с близлежащими порталами в царство Изеры, его поросшие мхом камни охраняют элитные зеленые драконы-стражи.",h="Онейрос — обширные руины древних ночных эльфов к югу от Нефритового озера на севере Фераласа.",kw={"dragonspawn","feralas","green dragonflight","jademir lake","oneiros","драконьи отпрыски","фералас","зеленый драконий род","нефритовое озеро","онейрос"},ang={["class:Druid"]="Друиды относятся к Онейросу с глубоким почтением и тревогой, сознавая его призрачную связь с владениями Изеры и сохраняющуюся опасность порчи Кошмара.",["race:NightElf"]="Для ночных эльфов прогулка по Онейросу — торжественное напоминание о размахе их древней империи и о бдительной страже зеленых драконов-стражей."},sec={{t="Руины под Сном",b="Руины Онейроса раскинулись по густому лесу на севере Фераласа: рушащиеся каменные арки и обломки колонн говорят о древнем поселении кальдораев, заброшенном тысячелетия назад. Сегодня природа вернула себе эти строения, оплетя их огромными корнями и буйной зеленью. Элитные стражи зеленого драконьего рода неустанно патрулируют тенистые тропы и разрушенные площади, не подпуская смертных к древним тайнам."},{t="Отголоски и порча",b="Духовная связь Онейроса с Изумрудным Сном делает эту область нестабильной. Драконы-стражи, верные Сновидцу, бдительно охраняют ее границы, но за завесой шевелится тьма. Смертным, забредшим в Онейрос, приходится сражаться с могучими драконьими отпрысками, видящими в каждом чужаке угрозу хрупким чарам, сдерживающим порчу."}},faq={{q="Где находится Онейрос?",a="Онейрос лежит на севере Фераласа, прямо к югу от Нефритового озера и к северу от главных дорог через лес. Он расположен рядом с Великим Древом, граничащим с порталом в Изумрудный Сон.",al={"oneiros location","where is oneiros","find oneiros","местонахождение онейроса","где онейрос","найти онейрос"}},{q="Какие существа обитают в Онейросе?",a="Руины усиленно патрулируют могучие зеленые драконьи отпрыски и драконы-стражи, верные зеленому драконьему роду. Путникам следует быть осторожными: эти часовые — грозные элитные стражи.",al={"oneiros mobs","enemies in oneiros","who lives in oneiros","монстры онейроса","враги в онейросе","кто живет в онейросе"}},{q="Почему здесь находятся руины ночных эльфов?",a="Онейрос — древнее поселение ночных эльфов, существовавшее еще до Великого Раскола. Как и многое в Фераласе, цивилизация здесь пала более десяти тысяч лет назад, оставив каменные колоннады и дворы, отвоеванные природой.",al={"why are there ruins","kaldorei ruins feralas","oneiros history","почему здесь руины","руины кальдораев фералас","история онейроса"}},{q="Как связаны Онейрос и Изумрудный Сон?",a="Близость к огромным ветвям, соединяющим Калимдор с миром Сна, размывает границы между физическим миром и миром духов.",al={"oneiros emerald dream","dream connection feralas","онейрос изумрудный сон","связь со сном фералас"}},{q="Есть ли поблизости безопасное место для отдыха?",a="Не в самих руинах, которые принадлежат зеленым драконам-стражам. Путники Альянса могут укрыться в Крепости Оперенной Луны у западного побережья, а Орда находит приют в Лагере Мохаче на востоке Фераласа.",al={"safe camp near oneiros","dreamers rest feralas","friendly hub oneiros","безопасный лагерь рядом с онейросом","отдых фералас","дружественный лагерь онейрос"}}},fp="7,245,23.440.0,21.360.1,25.194.0,31.199.0,35.230.0,61.151.0,37.210.0"}
P.entries["subzone:onyxia-s-lair"] = {n="Логово Ониксии",s="Логово Ониксии — подземная пещера в глубине Драконьих топей в Пылевых топях. Это гнездовье и оплот Ониксии, матери черного драконьего рода. В ее раскаленных, залитых магмой залах великая драконица охраняет кладки яиц черных драконов.",h="Логово Ониксии — подземная пещера в глубине Драконьих топей в Пылевых топях.",kw={"black dragonflight","broodmother","dragonmurk","dustwallow","lair","onyxia","whelps","wyrmbog","черный драконий род","мать драконов","земля драконов","пылевые топи","логово","ониксия","дракончики","драконьи топи"},ang={["faction:Alliance"]="Для защитников Альянса эта пещера — логово черной матери драконов, чей растущий выводок угрожает Терамору и всем поселениям вокруг топей.",["faction:Horde"]="Пылевые топи граничат с землями Орды в Степях и Мулгоре; позволить черной матери драконов вывести армию драконов в Калимдоре — значит создать смертельную угрозу всей новой Орде."},sec={{t="Обитель магмы и разрухи",b="Вход в пещеру, вырубленный в предательской грязи и окаменевшем дереве Драконьих топей, напоминает разинутую пасть дракона. Внутри прохладная гниль болота сменяется сильным вулканическим жаром. Из трещин в обсидиановом камне сочится магма, а подземные толчки регулярно сотрясают своды. Центральный зал открывается в огромный инкубатор, где среди пепла и углей лежат сотни яиц черных драконов; за ними присматривают стражи из числа сородичей драконов и драконьего отродья, а также сама Ониксия."},{t="Убежище матери драконов",b="Пока брат Ониксии Нефариан строит козни за морем, в Вершине Черной горы, Ониксия давно держит это уединенное гнездо в Калимдоре, чтобы растить новое поколение черного драконьего рода. Логово служит оплотом, когда ее хитроумные политические замыслы рушатся. Здесь, вдали от дворов смертных королевств, она может отбросить человеческие облики и принять свой истинный, ужасный облик дочери Смертокрыла."}},faq={{q="Где именно находится Логово Ониксии?",a="Логово расположено на юге Пылевых топей, в Драконьих топях, к югу от Земли Драконов. Вход отмечен огромными драконьими костями, тлеющей землей и черными драконами-стражами у каменной расселины в форме открытой пасти.",al={"where is onyxia","onyxia location","how to find onyxia lair","dragonmurk cave","где ониксия","местонахождение ониксии","как найти логово ониксии","пещера земли драконов"}},{q="Какие существа обитают в логове?",a="Пещера населена почти исключительно представителями черного драконьего рода. Мать драконов Ониксия повелевает в глубинном зале, окруженная роями только что вылупившихся дракончиков, драконьих отпрысков-стражей и взрослых черных драконов.",al={"onyxia lair mobs","who lives in onyxia lair","what is inside","монстры логова ониксии","кто живет в логове ониксии","что внутри"}},{q="Почему в пещере так жарко, если она находится в болоте?",a="Ониксия вырыла свое логово глубоко в земной коре Калимдора, добравшись до подземных жил магмы. Сильный вулканический жар создает палящие условия, необходимые для вынашивания яиц черных драконов, и резко контрастирует с холодной грязью Пылевых топей наверху.",al={"why is there lava in dustwallow","onyxia lair volcano","почему лава в пылевых топях","вулкан логова ониксии"}},{q="Почему Ониксия прячется в Калимдоре?",a="Пылевые топи обеспечивают уединение и укрытие. Густые туманы, мрачные трясины и опасные звери удерживают армии смертных вдали, позволяя матери драконов спокойно восполнять численность своего рода, пока она координирует тайное вмешательство в дела других земель.",al={"why is onyxia here","why dustwallow marsh","onyxia kalimdor","почему ониксия здесь","почему пылевые топи","ониксия калимдор"}}},fp="13,299,23.478.0,25.400.1,31.246.0,37.218.0,45.255.0,37.253.0"}
P.entries["subzone:oracle-glade"] = {n="Поляна Оракула",s="Поляна Оракула — священное лесное убежище на северо-западе Тельдрассила, где растет чудесное Древо Оракула и находится главный лунный колодец Мирового Древа. Несмотря на мирное предназначение как места единения и бдительности, поляна постоянно подвергается нападениям гарпий Кровавого Пера, проникающих на ее земли.",h="Поляна Оракула — священное лесное убежище на северо-западе Тельдрассила, где растет чудесное Древо Оракула и...",kw={"bloodfeather","fandral staghelm","harpies","moonwell","oracle glade","oracle tree","teldrassil","wellspring lake","кровавое перо","фэндрал олений шлем","гарпии","лунный колодец","поляна оракула","древо оракула","тельдрассил","родниковое озеро"},ang={["class:Druid"]="Для друидов-хранителей дикой природы Древо Оракула — живой партнер в деле опеки над землей: прямо на его коре проступают письменные свидетельства о состоянии края.",["race:NightElf"]="Поляна Оракула олицетворяет бережную заботу, необходимую для того, чтобы Тельдрассил расцвел: здесь находится самый мощный лунный колодец венца и безмолвный страж, говорящий напрямую с руководством Круга Кенария."},sec={{t="Сердце леса",b="Поляна Оракула тихо раскинулась между Дарнассом и Родниковым озером и служит важнейшим средоточием единения ночных эльфов с природой. В ее центре стоит Древо Оракула — древний исполин, чьи огромные ветви напоминают силуэт орла, сидящего на медведе. Рядом мерцает первый и самый могущественный из священных лунных колодцев Тельдрассила — оазис лунной магии, омытый милостью Элуны. Вместе с Кругом Древних Древо Оракула охраняет ветви острова, сбрасывая исписанную кору, которая служит важными посланиями верховному друиду Фэндралу Оленьему Шлему о здоровье Мирового Древа."},{t="Ветвь в осаде",b="Покой поляны хрупок. Агрессивные гарпии Кровавого Пера вторглись в рощу, устроили гнезда в высоких ветвях и угрожают священному древу. Часовые, присланные из Дарнасса, с трудом выкорчевывают этих пернатых падальщиков, которые преследуют странствующих друидов и портят естественное спокойствие лунного колодца. Путникам, идущим по северным ветвям, следует ступать осторожно: гарпии быстро нападают на всякого, кто приблизится к их гнездам."}},faq={{q="Что такое Древо Оракула?",a="Древо Оракула — древнее, магически взращенное дерево в форме огромного орла, сидящего на медведе. Оно следит за ростом и здоровьем Тельдрассила и сбрасывает исписанную кору с подробными отчетами, которые друиды доставляют прямо верховному друиду Фэндралу Оленьему Шлему в Дарнассе.",al={"who is the oracle tree","oracle tree lore","talking tree teldrassil","кто такое древо оракула","древо оракула предания","говорящее дерево тельдрассил"}},{q="Почему гарпии нападают на Поляну Оракула?",a="Клан гарпий Кровавого Пера устроил гнезда в высоких кронах поляны, привлеченный ее дикой природой и магической силой. Они яростно защищают свои гнезда и досаждают Древу Оракула, поэтому местным Часовым приходится их сдерживать.",al={"bloodfeather harpies","why harpies here","oracle glade enemies","гарпии кровавого пера","почему здесь гарпии","враги поляны оракула"}},{q="Чем важен лунный колодец на этой поляне?",a="Пруд на Поляне Оракула — первый и самый мощный лунный колодец, созданный в Тельдрассиле. Он направляет священную энергию Элуны, питая окрестный лес и поддерживая друидов и жриц кальдораев, приходящих черпать его воды.",al={"oracle glade moonwell","first moonwell","teldrassil first moonwell","лунный колодец поляны оракула","первый лунный колодец","первый лунный колодец тельдрассила"}},{q="Где находится Поляна Оракула?",a="Она находится на северо-западе Тельдрассила, к западу от Родникового озера. Южная дорога соединяет поляну с главной тропой, огибающей ворота Дарнасса.",al={"oracle glade location","where is oracle glade","how to get to oracle glade","где поляна оракула","расположение поляны оракула","как добраться до поляны оракула"}}},fp="12,297,21.596.0,16.473.0,24.279.0,43.245.0,53.253.0,34.178.0"}
P.entries["subzone:orgrimmar"] = {n="Оргриммар",s="Оргриммар — грозная воинская столица Новой Орды, высеченная в извилистых красных каньонах на севере Дуротара. Основанный вождем Траллом и названный в память об Оргриме Молоте Рока, он стал биением сердца возрождения орков и межплеменного выживания на Калимдоре.",h="Оргриммар — грозная воинская столица Новой Орды, высеченная в извилистых красных каньонах на севере Дуротара.",kw={"darkspear","doomhammer","durotar","grommash hold","new horde","orgrimmar","tauren","thrall","черное копье","молот рока","дуротар","крепость громмаш","новая орда","оргриммар","таурены","тралл"},ang={["faction:Horde"]="Как высшая резиденция руководства Орды, Оргриммар — главный плацдарм военных походов, союзов кланов и дипломатических отношений на Калимдоре и за его пределами.",["race:Orc"]="Для орков Оргриммар — воплощение их искупления, где они отбросили наследие демонического проклятия, чтобы построить честное и независимое будущее."},sec={{t="Крепость в камне",b="После Третьей войны и победы на горе Хиджал вождь Тралл привел уцелевших соплеменников на юг, чтобы основать постоянный дом в Дуротаре. Оргриммар встроен в природный барьер из отвесных скал и рассчитан на выдержку осады: заостренные деревянные частоколы, каменные сторожевые башни и глубокие пещеры, вырубленные в горах. Построенная совместно с троллями Черного Копья, таурен-каменщиками и гоблинами-инженерами, крепость превратила безлюдную пустошь в неприступный оплот силы."},{t="Сердце Новой Орды",b="Free of the demonic bloodlust that once bound them, the orcs built Orgrimmar as a beacon of honor, community, and survival. Today in 25 ADP, the city houses not only orcs and Darkspear trolls, but also welcomes emissaries from the tauren of Mulgore and emissaries from the newly allied Forsaken. Within its fortified canyons, shamans instruct the next generation in ancestral balance, while veterans clash in gladiatorial rings to hone the army that shields the fragile peace of Kalimdor."}},faq={{q="В честь кого назван Оргриммар?",a="Вождь Тралл назвал город в честь своего наставника и предшественника, легендарного вождя орков Оргрима Молота Рока. Молот Рока пал в Восточных королевствах во время освобождения лагерей для интернированных орков, передав Траллу свои знаменитые латы и боевой молот.",al={"orgrimmar name origin","why called orgrimmar","who was orgrimmar named for","происхождение названия оргриммар","почему оргриммар так называется","в честь кого назван оргриммар"}},{q="Кто помогал строить город?",a="Столица была быстро возведена совместными усилиями орков, троллей Черного Копья, таурен, нанятых гоблинов-саперов и инженеров, а также странствующего героя Рексара. Ее природные каменные стены были расширены и укреплены, чтобы дать быстрое и защищенное убежище в суровых землях Дуротара.",al={"who built orgrimmar","how was orgrimmar made","orgrimmar builders","кто построил оргриммар","как создан оргриммар","строители оргриммара"}},{q="Какие расы считают Оргриммар домом?",a="Оргриммар населяют главным образом орки и тролли Черного Копья Сен'джина, делящие его кварталы. Путники-таурены часто живут в городе как верные союзники, а посланники недавно принятых Отрекшихся начали тихо обживаться рядом с ними.",al={"who lives in orgrimmar","orgrimmar residents","races in orgrimmar","кто живет в оргриммаре","жители оргриммара","расы в оргриммаре"}},{q="Где живет вождь Тралл?",a="Тралл правит Новой Ордой из Крепости Громмаш — центрального оплота в Аллее Мудрости в Оргриммаре, названного в честь его павшего друга, Грома Адского Крика.",al={"where is thrall","thrall location orgrimmar","warchief seat","где тралл","местонахождение тралла в оргриммаре","резиденция вождя"}}},fp="9,274,25.514.0,22.488.0,29.268.0,26.292.0,32.271.0,34.176.0"}
P.entries["subzone:ortell-s-hideout"] = {n="Укрытие Ортелла",s="Укрытие Ортелла — скромная уединенная пещера в горах на юго-востоке Силитуса. Это убежище Отшельника Ортелла, одного из немногих одиночек, достаточно выносливых или безрассудных, чтобы жить в одиночестве в этой бесплодной пустоши.",h="Укрытие Ортелла — скромная уединенная пещера в горах на юго-востоке Силитуса.",kw={"cave","hermit ortell","ortell's hideout","silithus","southeastern silithus","пещера","отшельник ортелл","укрытие ортелла","силитус","юго-восточный силитус"},sec={{t="Приют отшельника",b="Укрытие Ортелла спрятано в зазубренных скалах на юго-востоке Силитуса и дает скудный приют от бушующих песчаных бурь и рыщущих роев силитидов, властвующих в пустошах. В пещере живет лишь Отшельник Ортелл — чудаковатый затворник, едва сводящий концы с концами вдали от цивилизации и укрепленных гарнизонов Крепости Кенария. Путники, отважившиеся на опасный путь в этот дальний уголок, часто ищут его особых знаний о пустыне и ее опасностях."}},faq={{q="Где находится Укрытие Ортелла?",a="Укрытие высечено в горной породе на юго-восточном краю Силитуса, вдали от центральных пустынных дорог, глубоко у пограничных скал.",al={"where is ortell","ortell location","how to find ortell cave","где ортелл","местонахождение ортелла","как найти пещеру ортелла"}},{q="Кто такой Отшельник Ортелл?",a="Отшельник Ортелл — одинокий житель, живущий вдали от экспедиции Круга Кенария и фракций мира. Он предпочитает жить один среди опасностей Силитуса, не покидая своей маленькой пещеры.",al={"who is ortell","hermit ortell lore","кто такой ортелл","предания об отшельнике ортелле"}},{q="Безопасно ли Укрытие Ортелла от силитидов?",a="Хотя сама пещера не заражена, она стоит обособленно в крайне враждебной зоне, кишащей насекомоподобными силитидами и культистами Сумеречного Молота. Чтобы добраться до укрытия, нужно пробиваться через опасную местность.",al={"are there bugs in the cave","is ortell cave safe","есть ли жуки в пещере","безопасна ли пещера ортелла"}}},fp="16,236,18.475.0,26.163.0,21.201.0,43.208.0"}
P.entries["subzone:owl-wing-thicket"] = {n="Совиная чаща",s="Совиная чаща — суровое скопление пещер и каменных гнезд на юге Зимних Ключей. Ее населяют многочисленные яростные, отмеченные луной и безумные совы-звери, рыщущие по заснеженным скалам. В глубине древние алтари ночных эльфов хранят священные знания о происхождении этих существ и их связи с богиней луны Элуной.",h="Совиная чаща — суровое скопление пещер и каменных гнезд на юге Зимних Ключей.",kw={"elune","guardians of elune","moonkin","moontouched","owl wing thicket","owlbeast","ranshalla","winterspring","элуна","стражи элуны","лунные совы","отмеченные луной","совиная чаща","совиный зверь","раншалла","зимние ключи"},ang={["class:Druid"]="Друиды почитают облик совиного зверя священным, поэтому эта чаща для них — мрачное место, где существа, наделенные лунным родством, скатились в необузданное безумие.",["race:NightElf"]="Для кальдораев Совиная чаща — священная земля, одичавшая: она хранит ранние свидетельства милости Элуны и диких лунных сов, утративших свое древнее равновесие."},sec={{t="Святилище лунных сов",b="Совиная чаща, вырубленная в заснеженном нагорье к югу от Круговзора, — одно из самых густых мест гнездования диких совиных зверей Зимних Ключей. Когда-то давно ночные эльфы-хранители почитали этих существ как священных стражей, благословленных Элуной. Древние святилища и алтари из лунного камня до сих пор скрыты под сводами пещер, а над ними бдят задержавшиеся духи Стражей Элуны. Но ныне многие звери поддались безумию и бросаются на путников, вторгшихся в их священные логова."},{t="Предания о лунных совах",b="Ученые и жрецы ночных эльфов приходят в Совиную чащу, чтобы обрести единение со Стражами Элуны. Под руководством жрицы Раншаллы искатели из Альянса зажигают священные жаровни по всему пещерному комплексу, чтобы пробудить древних духов. Эти стражи рассказывают легенду о том, как Элуна впервые создала диких лунных сов, чтобы охранять нетронутые природные святилища, проясняя божественное происхождение зверей, несмотря на их нынешнюю дикую враждебность."}},faq={{q="Что такое Совиная чаща?",a="Совиная чаща — сеть заснеженных скал и пещер на юге Зимних Ключей. Она известна густым населением диких совиных зверей и несколькими древними святилищами, посвященными богине ночных эльфов Элуне.",al={"owl wing thicket","where is owl wing thicket","owl wing thicket lore","совиная чаща","где совиная чаща","предания совиной чащи"}},{q="Почему здешние совиные звери так агрессивны?",a="Хотя изначально они были созданы как защитники природы, благословленные Элуной, многие совиные звери Зимних Ключей впали в яростное бешенство. В Совиной чаще они бродят как безумные, яростные и отмеченные луной звери, нападая на всех, кто приближается к их логовам.",al={"why are moonkin mad","crazed owlbeasts winterspring","berserk owlbeasts","почему лунные совы безумны","безумные совиные звери зимние ключи","яростные совиные звери"}},{q="Кто такая Раншалла?",a="Раншалла — жрица Элуны из ночных эльфов, отправляющаяся в Совиную чащу. Она ищет наставления древних Стражей Элуны, чтобы раскрыть священное происхождение и историю лунных сов.",al={"ranshalla","who is ranshalla winterspring","priestess ranshalla","раншалла","кто такая раншалла зимние ключи","жрица раншалла"}},{q="Кто такие Стражи Элуны, обитающие в чаще?",a="Стражи Элуны — древние духи ночных эльфов, связанные с алтарями в пещерах. Когда их призывают, вновь зажигая священные огни, они рассказывают, как лунные совы были созданы охранять дикие и священные земли.",al={"guardians of elune","spirits in owl wing thicket","moonkin spirits","стражи элуны","духи в совиной чаще","духи лунных сов"}}},fp="16,334,24.512.0,23.458.1,25.206.0,41.253.0,17.199.0,57.216.0"}
P.entries["subzone:palemane-rock"] = {n="Утес Бледногривов",s="Утес Бледногривов — пещера и лагерь в западных горах Мулгора. Это главный оплот агрессивного племени гноллов Бледногривов, постоянно досаждающих и угрожающих таурен Деревни Кровавого Копыта по соседству.",h="Утес Бледногривов — пещера и лагерь в западных горах Мулгора.",kw={"bloodhoof","cave","gnoll","mulgore","palemane","rock","кровавое копыто","пещера","гнолл","мулгор","бледногривы","утес"},ang={["faction:Horde"]="Защита границ Мулгора от местных вредителей вроде гноллов Бледногривов необходима для безопасности и стабильности родины таурен.",["race:Tauren"]="Гноллы Бледногривов, обосновавшиеся в этих западных пещерах, — постоянная заноза для вашего народа: они угрожают дичи и неосторожным путникам на пастбищах Мулгора."},sec={{t="Оплот гноллов",b="Утес Бледногривов расположен вдоль западного края травянистых равнин Мулгора и состоит из обширного лагеря под открытым небом перед глубокой темной пещерой, вырубленной в склоне горы. Гноллы Бледногривов объявили своей территорией и внутренность пещеры, и ближние предгорья. Враждебные и свирепо оберегающие свои земли, эти гноллы яростно защищают логово, нападая на охотников, путников и разведчиков, подошедших слишком близко к их скалистому убежищу."}},faq={{q="Что такое Утес Бледногривов?",a="Утес Бледногривов — природная пещера и укрепленное поселение гноллов в западных скалах Мулгора.",al={"palemane rock info","palemane cave","where is palemane rock","утес бледногривов","пещера бледногривов","где утес бледногривов"}},{q="Кто живет на Утесе Бледногривов?",a="Пещера и окружающий лагерь принадлежат гноллам племени Бледногривов. Они яростно защищают свою территорию от чужаков, в том числе от коренных таурен.",al={"who is here","palemane mobs","gnolls at palemane rock","кто здесь живет","бледногривы мобы","гноллы на утесе бледногривов"}},{q="Почему Утес Бледногривов важен для таурен?",a="Близость Утеса Бледногривов к центральному Мулгору и Деревне Кровавого Копыта делает его действующим гнездом враждебных налетчиков, которых охотникам и воинам таурен приходится постоянно подавлять.",al={"why do tauren care","bloodhoof village gnolls","threat to mulgore","почему таурены беспокоятся","гноллы деревни кровавого копыта","угроза мулгору"}}},fp="13,242,18.449.0,22.113.0,27.172.0,44.172.0"}
P.entries["subzone:park"] = {n="Парк",s="Парк расположен на западной окраине Штормграда между Соборной площадью и Кварталом магов — это пышный зеленый уголок для тихих размышлений. Посвященный природе и отдыху среди шумной каменной столицы, он служит главным прибежищем для приезжих ночных эльфов и вмещает единственных учителей друидов в Восточных королевствах.",h="Парк расположен на западной окраине Штормграда между Соборной площадью и Кварталом магов — это пышный зеленый...",kw={"druid","kaldorei","moonwell","nara meideros","night elf","park","stormwind","друид","кальдораи","лунный колодец","нара мейдерос","ночной эльф","парк","штормград"},ang={["class:Druid"]="Этот тихий анклав — ваше единственное место для обучения и наставлений во всех Восточных королевствах.",["race:NightElf"]="Для ночных эльфов, путешествующих через море, Парк — желанный кусочек дома: светящийся лунный колодец и знакомые учителя Элуны и дикой природы."},sec={{t="Роща в каменной столице",b="Пока остальной Штормград состоит из мощеных улиц, высоких известняковых стен и людных рыночных рядов, Парк дарит спокойное дыхание дикой природы. Изначально он был создан как тихое место отдыха для горожан, но естественным образом превратился в анклав для посланников ночных эльфов и путников, прибывающих из-за Великого моря. Под тенистыми кронами, вокруг центрального лунного колодца, этот район приносит частицу священных рощ Калимдора в самое сердце человеческого королевства."},{t="Убежище и братство",b="Для ночных эльфов Парк — важный оплот на чужбине. Здесь жрицы кальдораев, такие как Нара Мейдерос, заботятся о приезжих паломниках, а наставники-друиды дают советы тем, кто предан дикой природе. Этот район также служит тихим приютом, где усталые искатели приключений отдыхают от шума Торгового квартала и строгих обязанностей Собора."}},faq={{q="Где в Штормграде находится Парк?",a="Парк находится на самой западной окраине Штормграда. До его зеленых троп можно дойти, направившись на юго-запад от Соборной площади или на северо-запад от Квартала магов.",al={"where is the park","how to get to the park","park location","где парк","как пройти в парк","расположение парка"}},{q="Почему в Парке так много ночных эльфов?",a="Парк стал убежищем для приезжих ночных эльфов, искавших передышки от высоких каменных улиц Штормграда. Пышные рощи и безмятежная атмосфера напоминали им родные леса, поэтому они обосновались здесь и даже устроили на площади лунный колодец.",al={"why night elves here","stormwind night elf district","kaldorei district","почему здесь ночные эльфы","район ночных эльфов в штормграде","район кальдораев"}},{q="Можно ли здесь изучать умения друида?",a="Да. Сейчас Парк — единственное место в Восточных королевствах, где находятся учителя друидов Альянса, дающие наставления и обучение кальдораям вдали от Калимдора.",al={"druid trainers stormwind","where to train druid eastern kingdoms","park druid training","учителя друидов штормград","где учить друида восточные королевства","обучение друидов в парке"}},{q="Что за светящийся водоем в центре Парка?",a="Водоем в центре Парка — освященный лунный колодец ночных эльфов, созданный гостями-кальдораями как священный источник духовного покоя и лунной силы посреди человеческого города.",al={"park moonwell","glowing fountain park","pool in the park","лунный колодец парка","светящийся фонтан парк","водоем в парке"}}},fp="4,338,28.525.0,24.376.0,39.170.0,46.264.0,33.196.0,51.186.0"}
P.entries["subzone:pestilent-scar"] = {n="Моровой овраг",s="Моровой овраг — глубокое зараженное ущелье среди оскверненных земель Восточных Чумных земель. В отличие от зазубренных разломов, разорванных катастрофической порчей Плети, эта пропасть, судя по всему, была естественным каньоном или высохшим озерным руслом, которое впоследствии осквернили и заполонили прожорливые слизи.",h="Моровой овраг — глубокое зараженное ущелье среди оскверненных земель Восточных Чумных земель.",kw={"blight","eastern plaguelands","gorge","infectis scar","oozes","pestilent scar","slime","порча","восточные чумные земли","ущелье","чумной овраг","слизи","моровой овраг","слизь"},ang={["profession:Herbalism"]="Края ущелья пропитаны концентрированной гнилью и порой питают редкие, закаленные порчей растения, такие как слезы Артаса и чумоцвет, на его утесах.",["race:Undead"]="Отрекшиеся-аптекари часто изучают слизи, обитающие в таких глубоких расселинах, чтобы выделить нестабильные разновидности самых мерзких токсинов Плети."},sec={{t="Зараженная пропасть",b="Моровой овраг вьется по восточным окраинам Восточных Чумных земель, образуя мрачный разлом в оскверненном ландшафте. Хотя соседние разломы, такие как Чумной овраг, были вырваны из земли внезапными катастрофическими извержениями Чумы нежизни, ученые отмечают, что Моровой овраг, по-видимому, возник как естественное геологическое образование. Вероятно, это был глубокий речной каньон или озеро, высохшее, когда Плеть захлестнула Лордерон; осталась пустая впадина, в которой постепенно скопились зловонные стоки и мерзкая слизь."},{t="Слизевые ямы",b="Лишенная чистой воды и постоянно пропитанная нечестивым распадом, впадина стала рассадником мутировавших кислотных слизей и падальщиков. Путь вдоль ее осыпающегося края опасен: воздух над обрывом пропитан едкими испарениями, а неустойчивая почва грозит сбросить неосторожных искателей приключений прямо в бурлящую грязь внизу."}},faq={{q="Что такое Моровой овраг?",a="Моровой овраг — провалившееся ущелье в Восточных Чумных землях. Осквернен во время падения Лордерона; каньон полон зловонных стоков, больной земли и агрессивных слизевых чудовищ.",al={"pestilent scar lore","what is pestilent scar","pestilent scar canyon","предания морового оврага","что такое моровой овраг","каньон морового оврага"}},{q="Как образовался Моровой овраг?",a="В отличие от неестественных трещин, разорванных в земле катастрофическими извержениями Плети, Моровой овраг, судя по всему, был естественной долиной, озером или речным каньоном, который высох и зачах под порчей Чумы нежизни.",al={"how was pestilent scar made","pestilent scar origin","who made pestilent scar","как образовался моровой овраг","происхождение морового оврага","кто создал моровой овраг"}},{q="Чем он отличается от Чумного оврага?",a="Чумной овраг был яростно разорван как неестественный вулканический разлом, сочащийся чистой магической порчей. Моровой овраг — более древняя естественная впадина, в которой постепенно скопились скверна и стоки после гибели земли.",al={"pestilent scar vs infectis scar","infectis scar difference","моровой овраг и чумной овраг","отличие чумного оврага"}},{q="Какие существа обитают в Моровом овраге?",a="На дне пропасти преобладают кислотные слизи, порожденные чумой, и питающиеся падалью паразиты, процветающие в ядовитых лужах и гниющей органике, скопившейся внизу.",al={"pestilent scar mobs","what lives in pestilent scar","монстры морового оврага","кто живет в моровом овраге"}}},fp="14,293,16.543.0,14.354.0,27.201.0,32.237.0,42.228.0,42.175.0"}
P.entries["subzone:petitioner-s-chamber"] = {n="Палата просителей",s="Палата просителей, также известная как Зал просителей, — приемная рядом с главным входным пандусом Крепости Штормграда. Она служит официальной комнатой ожидания для дворян, церковных сановников и подданных, добивающихся аудиенции у короны. Те, кто ждет здесь, часто проводят часы за беседой, выпивкой или в ожидании милости регента.",h="Палата просителей, также известная как Зал просителей, — приемная рядом с главным входным пандусом Крепости...",kw={"bishop delavey","caledra dawnbreeze","count remington ridgewell","hall of petitioners","petitioners chamber","stormwind keep","епископ делавей","каледра рассветный бриз","граф ремингтон риджвелл","зал просителей","палата просителей","крепость штормграда"},ang={["class:Priest"]="Поскольку епископ Делавей часто находится в этой приемной, она служит пересечением административной иерархии Света и королевского двора.",["faction:Alliance"]="Для сторонников Альянса эта палата — административное узкое место Штормграда, где бытовые прошения, церковные дела и просьбы дворян ждут редкого внимания королевского совета."},sec={{t="Комната ожидания и влияния",b="Палата просителей находится сразу справа при входе в Крепость Штормграда; здесь государственные дела встречаются с повседневной бюрократией. Дворяне, такие как граф Ремингтон Риджвелл, и высокопоставленные клирики, как епископ Делавей, коротают здесь время в ожидании аудиенции у юного короля Андуина Ринна и верховного лорда Болвара Фордрагона. За лоском придворного этикета это идеальный уголок замка для сплетен, тихого лоббирования и выяснения того, кто на самом деле обладает влиянием в королевстве."}},faq={{q="Где находится Палата просителей?",a="Палата находится внутри Крепости Штормграда. Как только вы поднимаетесь по большому входному пандусу в крепость, это первая комната прямо справа.",al={"where is petitioners chamber","how to find petitioner chamber","petitioner room location","где палата просителей","как найти палату просителей","расположение палаты просителей"}},{q="Кто собирается в этой комнате?",a="В комнате часто бывают просители, придворные и дворяне, ищущие внимания трона, в том числе граф Ремингтон Риджвелл, Каледра Рассветный Бриз и епископ Делавей из Церкви Священного Света.",al={"who is in petitioners chamber","npcs in petitioner chamber","who waits here","кто в палате просителей","персонажи в палате просителей","кто здесь ждет"}},{q="Почему ее также называют Залом просителей?",a="Ее официальная задача — принимать подданных, подавших формальные прошения короне. Посетители должны ждать здесь, пока регент, верховный лорд Болвар Фордрагон или королевский совет не допустит их в тронный зал.",al={"hall of petitioners","why called hall of petitioners","petitioners hall","зал просителей","почему зал просителей","палата просителей"}},{q="Что происходит здесь во время заданий в городе?",a="Палату в основном посещают, чтобы доставить товары или поговорить с дворянами и клириками крепости, например, выполняя поручения по доставке тонких напитков вроде портвейна для томимых жаждой аристократов, ожидающих дел при дворе.",al={"petitioner chamber quests","what quests lead here","задания палаты просителей","какие задания ведут сюда"}}},fp="20,373,31.524.0,42.151.0,25.219.0,46.222.0,37.226.0"}
P.entries["subzone:pig-and-whistle-tavern"] = {n="Таверна \"Свинья и свисток\"",s="Таверна «Свинья и свисток» — шумная таверна в суровом Старом городе Штормграда. Это излюбленное место встреч путников Альянса, местных работяг и закаленных ветеранов, вспоминающих прошлые конфликты королевства.",h="Таверна «Свинья и свисток» — шумная таверна в суровом Старом городе Штормграда.",kw={"cooking","kendor kabonka","old town","pig and whistle","stormwind","tavern","кулинария","кендор кабонка","старый город","свинья и свисток","штормград","таверна"},ang={["faction:Alliance"]="Для солдат и путников Альянса, проезжающих через столицу, таверна предлагает радушный, простой очаг и дружескую компанию ветеранов прежних войн королевства.",["profession:Cooking"]="Мастера кулинарии часто совершают паломничество в таверну, чтобы найти Кендора Кабонку, продающего непревзойденную коллекцию редких кулинарных рецептов со всего Азерота."},sec={{t="Прибежище в Старом городе",b="Среди грубых извилистых переулков Старого города Таверна «Свинья и свисток» предлагает тепло, эль и ночлег тем, кто ходит по более суровому кварталу столицы. Пока городская знать собирается на соборных площадях и мраморных плазах, это заведение обслуживает простых горожан, рабочий люд и путников, только что с дороги. Внутри можно встретить торговцев, например известного продавца рецептов Кендора Кабонку, и седых ветеранов, которые коротают время за кружками и вспоминают Первую и Вторую войны."}},faq={{q="Где находится Таверна «Свинья и свисток»?",a="Таверна «Свинья и свисток» стоит в Старом городе — восточном районе Штормграда, известном военными казармами, логовами разбойников и рабочими кварталами.",al={"where is pig and whistle","pig and whistle location","old town tavern","где свинья и свисток","расположение свиньи и свистка","таверна старого города"}},{q="Кто бывает в таверне?",a="Таверна популярна среди путников, стражников вне службы и ветеранов, обменивающихся рассказами о Первой и Второй войнах, а также среди известных торговцев, например Кендора Кабонки, продающего рецепты мастера кулинарии.",al={"who is in pig and whistle","pig and whistle patrons","кто в свинье и свистке","посетители свиньи и свистка"}},{q="Какие услуги предоставляет таверна?",a="«Свинья и свисток» — таверна, где усталые путники могут отдохнуть, купить еду, напитки и особые кулинарные рецепты.",al={"is pig and whistle an inn","pig and whistle services","свинья и свисток таверна","услуги свиньи и свистка"}}},fp="22,246,20.527.0,44.158.0,25.203.0,38.122.0"}
P.entries["subzone:plaguemist-ravine"] = {n="Чумная лощина",s="Чумная лощина — узкий горный проход, соединяющий зеленые дебри Внутренних земель с призрачными берегами озера Дарроумир в Западных Чумных землях. Названная в честь болезнетворного тумана, стелющегося с севера, она дает тихий и безлюдный путь через горный хребет.",h="Чумная лощина — узкий горный проход, соединяющий зеленые дебри Внутренних земель с призрачными берегами озера...",kw={"caer darrow","darrowmere","hinterlands","mountain pass","plaguemist","plaguemist ravine","quel'danil","western plaguelands","каэр дарроу","дарроумир","внутренние земли","горный проход","чумная лощина","кель'данил","западные чумные земли"},ang={["class:Hunter"]="Лощина служит спокойным переходом, хотя отсутствие дичи и лесных зверей делает ее жуткой границей для следопытов, идущих на север в Чумные земли.",["faction:Alliance"]="Проход дает разведчикам Альянса в Сторожке Кель'Данил скрытный путь для наблюдения за зараженными берегами вокруг Каэр Дарроу, не сталкиваясь с дорожными патрулями."},sec={{t="Зараженный порог",b="Скрытая в горах к северо-западу от Сторожки Кель'Данил, Чумная лощина служит географическим порогом между двумя совершенно разными мирами. На юге раскинулся пышный дикий нагорный лес Внутренних земель, а на севере проход выходит прямо к Каэр Дарроу и оскверненным просторам Западных Чумных земель. Лощина получила имя от зловонных неестественных испарений, ползущих на юг из Чумных земель и резко контрастирующих со свежим горным воздухом соседних диких мест."},{t="Тихий проход",b="Несмотря на то что лощина врезается прямо в край земель, разоренных Плетью, она остается удивительно безлюдной. В самом ущелье путники не встречают ни диких зверей, ни бродячей нежити. Из-за этой жуткой тишины извилистая тропа служит удобной, хотя и зловещей, тайной дорогой для отважных курьеров и искателей приключений, желающих обойти хорошо укрепленные тракты и пограничные заставы, ведущие в Лордерон."}},faq={{q="Куда ведет Чумная лощина?",a="Чумная лощина соединяет Внутренние земли с Западными Чумными землями. Путь на север выводит к берегам озера Дарроумир возле островной крепости Каэр Дарроу, а путь на юг — в лесистые холмы к северо-западу от Сторожки Кель'Данил.",al={"where does plaguemist ravine go","plaguemist ravine path","plaguemist connection","куда ведет чумная лощина","путь через чумную лощину","связь чумной лощины"}},{q="Почему она называется Чумной лощиной?",a="Проход получил название недавно из-за всепроникающего зараженного тумана, плывущего на юг из Западных Чумных земель. Болезненный воздух резко контрастирует со свежей, нетронутой атмосферой, типичной для Внутренних земель.",al={"why is it called plaguemist","plaguemist name origin","почему называется чумная лощина","происхождение названия чумная лощина"}},{q="Есть ли в лощине враги или персонажи?",a="Нет. В лощине нет ни враждебных существ, ни животных, ни дружелюбных неигровых персонажей, поэтому это необычно тихий проход между двумя оживленными зонами.",al={"plaguemist ravine mobs","is plaguemist ravine safe","монстры чумной лощины","безопасна ли чумная лощина"}},{q="Как найти вход во Внутренних землях?",a="Во Внутренних землях вход скрыт в северной горной стене к западу от Сторожки Кель'Данил и к северу от лагеря Рапсодии Шиндиггер.",al={"how to find plaguemist ravine","plaguemist ravine entrance","как найти чумную лощину","вход в чумную лощину"}}},fp="17,291,20.524.0,15.438.0,34.258.0,35.217.0,44.163.0,48.144.0"}
P.entries["subzone:plaguewood"] = {n="Проклятый лес",s="Некогда мирный лес под названием Зеленолесье, Проклятый лес теперь — истощенная, заросшая грибами пустошь к югу от Стратхольма. Здесь полно построек Плети, а по дорогам рыщут патрули Алого ордена; это один из самых оскверненных уголков Восточных Чумных земель.",h="Некогда мирный лес под названием Зеленолесье, Проклятый лес теперь — истощенная, заросшая грибами пустошь к...",kw={"fungus","greenwood","plaguewood","scourge","slaughterhouses","stratholme","terrordale","ziggurats","грибы","зеленолесье","проклятый лес","плеть","скотобойни","стратхольм","долина ужаса","зиккураты"},ang={["class:Paladin"]="Искривленные деревья и мерзкие котлы Проклятого леса — тяжкое напоминание о падении Лордерона; здесь любой защитник Света проходит испытание полчищами мерзостей и непреклонными фанатиками.",["faction:Alliance"]="Для выживших из Альянса эти тропы — та самая дорога, по которой принц Артас шел к своей позорной чистке Стратхольма; теперь она утонула в гнили и безумных фанатиках Алого ордена."},sec={{t="От Зеленолесья к распаду",b="До Третьей войны эта область называлась Зеленолесье — цветущий лес, похожий на густые чащи Элвиннского леса. У его входа стояла небольшая деревня, а по дорогам ходили и фермеры, и солдаты. Все рухнуло, когда из Андорала прибыло зараженное зерно. Теперь на месте плодородной земли — рыхлая, оскверненная почва, а исполинские грибы возвышаются над мертвыми деревьями и непрерывно изрыгают над лесной землей ядовитые бурые пары."},{t="Оплот мертвых",b="Теперь Проклятый лес полностью захвачен Плетью и служит мрачным плацдармом для нежити, окружающей Стратхольм. Зиккураты и бойни разбросаны по разоренной местности и непрерывно порождают чудовищ и сектантов. Путникам приходится еще тяжелее: фанатичные воины Алого ордена безостановочно патрулируют дорогу к вратам Стратхольма, стремясь уничтожить Плеть и жестоко убить любого живого странника, который им встретится."}},faq={{q="Как назывался этот лес до чумы?",a="До Третьей войны эта область называлась Зеленолесье. Это был цветущий лес с небольшой деревней у входа, очень похожий красотой и климатом на Элвиннский лес.",al={"plaguewood old name","greenwood lore","what was plaguewood","прежнее название проклятого леса","зеленолесье предания","что такое проклятый лес"}},{q="Почему повсюду растут огромные грибы?",a="Чума в корне изменила местную природу. Почва стала рыхлой, а по лесной земле выросли чудовищные грибы, которые выпускают ядовитые бурые клубы, похожие на пары чумных котлов.",al={"giant mushrooms plaguewood","fungus plaguewood","why mushrooms","гигантские грибы проклятый лес","грибы проклятый лес","почему грибы"}},{q="Кто контролирует Проклятый лес сегодня?",a="Лес почти целиком принадлежит Плети: здесь есть некроманты, вурдалаки, зиккураты и скотобойни. Кроме того, по главным дорогам регулярно проходят патрули Алого ордена, нападающие на нежить и на любых живых путников.",al={"who rules plaguewood","plaguewood enemies","who lives in plaguewood","кто правит проклятым лесом","враги проклятого леса","кто живет в проклятом лесу"}},{q="Куда ведет дорога через лес?",a="Главная дорога идет прямо на север, к вратам павшего города Стратхольма, а западные просторы зараженного леса тянутся к разрушенной деревне Долина Ужаса.",al={"plaguewood road destination","where does path go","stratholme road","куда ведет дорога проклятый лес","куда идет тропа","дорога к стратхольму"}}},fp="10,276,23.444.0,21.427.0,46.176.0,51.204.0,34.257.0,43.184.0"}
P.entries["subzone:plaguewood-tower"] = {n="Башня Проклятого леса",s="Башня Проклятого леса — разрушенная разведывательная башня Лордерона на севере Проклятого леса, неподалеку от Долины Ужаса. Разбитая во время вторжения Плети, она стоит руиной среди зараженного леса.",h="Башня Проклятого леса — разрушенная разведывательная башня Лордерона на севере Проклятого леса, неподалеку от...",kw={"eastern plaguelands","lordaeron","outpost","plaguewood","plaguewood tower","scourge","terrordale","watchtower","восточные чумные земли","лордерон","застава","проклятый лес","башня проклятого леса","плеть","долина ужаса","сторожевая башня"},ang={["faction:Alliance"]="Для сил Альянса разрушенные сторожевые башни Лордерона — горькое напоминание о землях людей, потерянных из-за Плети.",["faction:Horde"]="Для Орды разрушенные укрепления вроде Башни Проклятого леса показывают, насколько полно Плеть сокрушила оборону северных королевств."},sec={{t="Разрушенный страж на севере",b="Башня Проклятого леса стоит на краю Проклятого леса и оскверненного города Долина Ужаса; когда-то она служила Королевству Лордерон важным северным сторожевым постом. Когда Плеть захлестнула страну, укрепление превратили в груду крошащейся кладки, оставленную среди грибных зарослей. Сегодня расколотые камни все еще смотрят на северные тропы — безмолвное напоминание о страже, что Лордерон нес над этой землей."}},faq={{q="Для чего изначально использовалась Башня Проклятого леса?",a="Башню Проклятого леса построило Королевство Лордерон как местную сторожевую башню. До Третьей войны расквартированные здесь стражи наблюдали за северными лесами, дорогами и поселениями вроде Долины Ужаса, пока Плеть не сокрушила гарнизон.",al={"original purpose","who built plaguewood tower","history of tower","первоначальное назначение","кто построил башню проклятого леса","история башни"}},{q="Где именно находится башня?",a="Она расположена в северной части Восточных Чумных земель, в Проклятом лесу, прямо у разрушенного города Долина Ужаса и к югу от внешних зараженных земель Стратхольма.",al={"tower location","where is plaguewood tower","map location","расположение башни","где башня проклятого леса","место на карте"}}},fp="16,214,30.448.0,46.257.0,35.182.0"}
P.entries["subzone:pool-of-ask-ar"] = {n="Пруд Аск'ара",s="Пруд Аск'ара — обширное подводное пещерное озеро в глубине Непроглядной Пучины. В его водах кишат морские твари и мерзкие наги-захватчики, а под водой скрыты древняя архитектура ночных эльфов и потайные ходы, ведущие глубже в оскверненное святилище.",h="Пруд Аск'ара — обширное подводное пещерное озеро в глубине Непроглядной Пучины.",kw={"blackfathom deeps","drowned sacellum","ghamoo-ra","lady sarevess","lorgalis manuscript","naga","pool of ask'ar","непроглядная пучина","затонувшее святилище","гхаму-ра","леди саревесс","манускрипт лоргалиса","наги","пруд аск'ара"},ang={["faction:Alliance"]="Чтобы узнать судьбу Стража Талрида из ордена Серебряного Рассвета, отправившегося в эти пещерные глубины со священной миссией против Сумеречного Молота, необходимо пройти через водные пути.",["race:NightElf"]="Пруд затопил то, что некогда было землями священного храма Элуны, погрузив под воду древнюю архитектуру и разбросав священные реликвии вроде Манускрипта Лоргалиса, которые теперь растаскивают наги."},sec={{t="Глубины затонувшего грота",b="Сразу за Затонувшим святилищем Пруд Аск'ара заполняет огромный подземный свод мутной холодной водой. Природные пещеры и древняя каменная кладка стали гнездовьем для гигантских черепах-кусак и глубоководных крабов, над которыми властвует огромное древнее черепахоподобное существо Гхаму-ра. Наги, захватившие храм, используют этот затопленный порог как оборонительный рубеж, охраняя залитые водой подходы, что ведут дальше в комплекс — к леди Саревесс и Руинам Лунного святилища."},{t="Тайны под поверхностью",b="Помимо чудовищной фауны и враждебных патрулей, воды пруда скрывают ценные реликвии со времен до Раскола, принадлежавшие святилищу. Подводные уступы и скрытые ниши по краям пещеры хранят утерянные артефакты, в том числе ценный Манускрипт Лоргалиса, который разыскивает гном-ученый Геррик Костохват из Стальгорна. Если проплыть по затопленным южным ходам, путники выйдут в сухие туннели, где стоят мерзкие мурлоки и культисты Древних богов; это делает пруд важнейшим водным перекрестком Непроглядной Пучины."}},faq={{q="Что такое Пруд Аск'ара?",a="Это обширный подземный пруд в Непроглядной Пучине, расположенный сразу за Затонувшим святилищем. В нем господствуют черепахи-кусаки, крабы и стражи-наги.",al={"pool of askar","what is this pool","bfd water area","пруд аск'ара","что это за пруд","водная зона непроглядной пучины"}},{q="Кто обитает в этом подземном пруду?",a="В пещере обитают дикие рифовые твари, такие как черепахи-кусаки и крабы, и прежде всего колоссальная черепаха Гхаму-ра. Враждебные наги также патрулируют затопленные берега и соседние залы.",al={"pool monsters","pool of askar bosses","who is in the pool","монстры пруда","боссы пруда аск'ара","кто в пруду"}},{q="Куда ведут подводные туннели?",a="Затопленные южные проходы ведут к залам, где находятся леди Саревесс и Страж Талрид из ордена Серебряного Рассвета, и выходят на тропу, что вьется мимо Гелихаста к Руинам Лунного святилища.",al={"pool tunnels","where does the water go","pool of askar exit","туннели пруда","куда ведет вода","выход из пруда аск'ара"}},{q="Какие примечательные предметы можно найти в пруду?",a="В затонувших руинах по краям пруда лежит Манускрипт Лоргалиса — древний текст о Древних богах, который жаждет заполучить Геррик Костохват из Стальгорна.",al={"pool of askar relics","lorgalis manuscript","pool loot","реликвии пруда аск'ара","манускрипт лоргалиса","добыча в пруду"}}},fp="14,275,27.526.0,27.525.0,27.158.0,36.192.0,37.194.0,44.152.0"}
P.entries["subzone:pool-of-tears"] = {n="Озеро Слез",s="Озеро Слез — большое мутное озеро в восточной части Болота Печали. Глубоко под его поверхностью лежит затонувший Храм Атал'Хаккара, низвергнутый зеленым драконьим родом, чтобы сдержать таящийся в нем ужас. Сегодня в мутных водах рыщут свирепые рыбы-неистовицы, а на затопленных берегах разбросаны древние тролльи руины.",h="Озеро Слез — большое мутное озеро в восточной части Болота Печали.",kw={"atal'ai","frenzies","pool of tears","sunken temple","swamp of sorrows","temple of atal'hakkar","ysera","атал'ай","неистовицы","озеро слез","затонувший храм","болото печали","храм атал'хаккара","изера"},ang={["class:Druid"]="Друиды почитают это озеро, видя в нем место, где Изера и Зеленый драконий род вмешались, чтобы остановить скверну Кровавого бога.",["race:Troll"]="Для троллей Черного Копья это озеро — мрачное предупреждение о том, что бывает, когда тролли обращаются к запретной магии крови, как Атал'ай."},sec={{t="Затонувшее святилище",b="Давным-давно фанатичные тролли Атал'ай возвели монументальный зиккурат в честь своего кровожадного бога, Хаккара Свежевателя Душ. Ужаснувшись кощунствам, творившимся внутри, Аспект драконов Изера расколола землю под строением и погрузила огромный храм в глубины болота. Прежнее озеро затопило руины храма. Драконы стремились похоронить зло навеки; зиккурат все еще стоит под илом и волнами, а зеленые драконы остаются на страже, не давая его скверне вырваться."},{t="Воды опасности",b="Путь через мутное озеро коварен для любого искателя приключений, идущего к затонувшим залам. Воды кишат плотоядными неистовицами, а артефакты Атал'ай и затопленная кладка разбросаны по илистому дну. Путникам приходится преодолевать эти враждебные мелководья, чтобы попасть в верхние ходы затонувшего храма, где культисты и оставшиеся стражи-драконы спорят за власть над темным святилищем."}},faq={{q="Почему оно называется Озеро Слез?",a="Происхождение названия не записано. Озеро известно Храмом Атал'Хаккара, который Изера погрузила под его воды, чтобы остановить призыв Хаккара.",al={"pool of tears name origin","why pool of tears","pool of tears meaning","происхождение названия озера слез","почему озеро слез","значение озера слез"}},{q="Что за огромное строение в центре озера?",a="Это Храм Атал'Хаккара, который часто называют Затонувшим храмом. Некогда возвышавшийся зиккурат Атал'ай, он был низвергнут Изерой под воду и остается частично погруженным в центре озера.",al={"building in pool of tears","ruins in lake swamp of sorrows","sunken temple location","здание в озере слез","руины в озере болота печали","где затонувший храм"}},{q="Почему у воды столько зеленых драконов?",a="Выводок Изеры прибыл, чтобы разрушить храм и потопить его мерзкие обряды. Зеленые драконы и их сородичи до сих пор присматривают за озером, чтобы культисты Атал'ай не смогли завершить призыв Кровавого бога.",al={"green dragons swamp of sorrows","why are dragons here","ysera temple lake","зеленые драконы болото печали","почему здесь драконы","изера храм озеро"}},{q="Безопасно ли переплывать озеро?",a="Нет. Озеро кишит агрессивными плотоядными неистовицами, которые нападают на всех, кто плывет ко входу в храм.",al={"pool of tears swimming","sharks in pool of tears","frenzies swamp of sorrows","плавание в озере слез","акулы в озере слез","неистовицы болото печали"}}},fp="13,329,19.521.0,15.403.0,35.157.0,55.197.0,45.206.0,35.128.0"}
P.entries["subzone:pools-of-arlithrien"] = {n="Пруды Арлитриэна",kw={"arlithrien","darnassus","furbolg","gnarlpine","moonwell","pools of arlithrien","teldrassil","арлитриэн","дарнасс","фурболг","седая сосна","лунный колодец","пруды арлитриэна","тельдрассил"},ang={["class:Druid"]="Друиды, изучающие нарушенное равновесие Тельдрассила, видят в буйной живности и заброшенном лунном колодце еще один признак того, что Великому Древу недостает истинного благословения природы.",["race:NightElf"]="Заброшенный священный лунный колодец так близко к Дарнассу — тревожное напоминание ночным эльфам о порче и разладе, расползающихся по Тельдрассилу."},sec={{t="Тревожное святилище",b="Пруды Арлитриэна, укрытые тенистыми ветвями к югу от Дарнасса, изначально задумывались как тихое место природной гармонии. В их сердце стоит каменный лунный колодец — сосуд для вод, наполненных благодатью Элуны. Но, несмотря на близость к столице ночных эльфов, святилище стало опасным. По мелководью бродят разъяренные звери, а постоянная враждебность вытесненных фурболгов Седой Сосны вынудила ночных эльфов перестать ухаживать за этим местом, и мирное чудо оказалось в тени растущего недуга острова."}},faq={{q="Где находятся Пруды Арлитриэна?",a="Пруды укрылись в западной части Тельдрассила, к югу от главного моста и входа в столицу — Дарнасс.",al={"pools of arlithrien location","where is arlithrien","arlithrien map","расположение прудов арлитриэна","где арлитриэн","карта арлитриэна"}},{q="Почему здешний лунный колодец заброшен?",a="Ночные эльфы перестали ухаживать за лунным колодцем из-за растущей опасности. Враждебные фурболги Седой Сосны обосновались неподалеку и грозят нападением, а агрессивные лесные звери заполонили окрестные воды.",al={"why abandoned","arlithrien moonwell abandoned","empty moonwell","почему заброшен","лунный колодец арлитриэна заброшен","пустой лунный колодец"}},{q="Какие опасности ждут путников у прудов?",a="Путникам, бродящим у прудов, приходится иметь дело с агрессивными лесными тварями, захватившими воды, и с постоянной угрозой со стороны соседних фурболгов Седой Сосны, защищающих свою территорию.",al={"arlithrien monsters","pools of arlithrien mobs","enemies at pools","монстры арлитриэна","мобы прудов арлитриэна","враги у прудов"}},{q="Можно ли по-прежнему пользоваться лунным колодцем у Прудов Арлитриэна?",a="Да. Хотя жрицы и друиды забросили его из-за местных опасностей, сам лунный колодец все еще хранит священные воды и остается действующим источником лунной сущности.",al={"use arlithrien moonwell","is moonwell active","water at pools","использовать лунный колодец арлитриэна","активен ли лунный колодец","вода у прудов"}}},fp="19,305,20.549.0,42.146.0,36.216.0,45.190.0,62.185.0"}
P.entries["subzone:pools-of-vision"] = {n="Пруды Видений",kw={"defilers","forsaken","mage portal","pools of vision","spirit rise","thunder bluff","undead enclave","осквернители","отрекшиеся","портал мага","пруды видений","вершина духов","громовой утес","убежище нежити"},ang={["class:Mage"]="Пещера служит опорой для тайных силовых линий города: любое заклинание телепортации в Громовой Утес доставляет мага прямо к этим уединенным прудам.",["race:Undead"]="Для Отрекшихся, странствующих по равнинам Калимдора, эта пещера — привычное тенистое убежище с тайными ресурсами, наставлениями жрецов и товариществом."},sec={{t="Убежище под плато",b="Если залитые солнцем вершины Громового Утеса принадлежат ветру, земле и небу, то Пруды Видений уходят прямо под Вершину Духов, в сумрачное уединение. В грот ведет неприметная пещерная тропа от моста к вершине; этот подземный грот дарит передышку, совсем не похожую на открытые шатры наверху. Здесь в темноте стоят туманные воды, создавая отрешенную атмосферу, где собираются заклинатели Орды вдали от шумных центральных плато."},{t="Аванпост нежити",b="В Громовом Утесе Пруды Видений служат фактической базой Отрекшихся. Путники с восточного континента находят здесь родственные души: жрецов нежити, практикующих темные искусства, магов, создающих тайные порталы, и посланников Осквернителей, которые набирают рекрутов для кампаний на Нагорье Арати. То ли из-за скепсиса таурен, то ли из-за природной любви Отрекшихся к темноте, это тихое убежище связывает нежить Лордерона с их союзниками в Калимдоре."}},faq={{q="Где находится вход в Пруды Видений?",a="Вход — это пещера на Вершине Духов, сразу справа после деревянного веревочного моста, ведущего с нижнего плато.",al={"how to get to pools of vision","pools of vision entrance","where are pools of vision","как добраться до прудов видений","вход в пруды видений","где пруды видений"}},{q="Почему Отрекшиеся живут здесь, внизу?",a="Пещера служит главным центром для Отрекшихся, расквартированных в Громовом Утесе. Она дает укрытие от жестокого солнца Калимдора и позволяет заниматься практиками, которые могут смутить традиционных таурен-духовидцев.",al={"why undead here","why forsaken in cave","thunder bluff undead","почему нежить здесь","почему отрекшиеся в пещере","нежить громовой утес"}},{q="Какие услуги можно найти в Прудах Видений?",a="В пещере находятся учителя и практики для жрецов и магов, а также посланники Осквернителей, набирающие солдат для войны на Нагорье Арати.",al={"trainers in pools of vision","what is in pools of vision","pools of vision trainers","учителя в прудах видений","что есть в прудах видений","учителя пруды видений"}},{q="Где появляются маги, телепортирующиеся в Громовой Утес?",a="Маги, использующие телепортацию или открывающие портал в Громовой Утес, появляются прямо в укрытых водах Прудов Видений под Вершиной Духов.",al={"mage teleport thunder bluff spot","tb teleport location","телепорт мага громовой утес","место телепорта громовой утес"}}},fp="15,238,24.459.0,18.509.0,45.158.0,38.217.0,54.169.0,58.151.0"}
P.entries["subzone:purgation-isle"] = {n="Остров Очищения",s="Остров Очищения — скалистый остров спиральной формы у южного побережья Предгорий Хилсбрада. Это безлюдная проклятая скала с кладбищем и разрушенной сторожевой башней кишит неупокоенными осужденными духами павших людей и дворфов.",h="Остров Очищения — скалистый остров спиральной формы у южного побережья Предгорий Хилсбрада.",kw={"arados the damned","hillsbrad","judge thelgram","kormok","kul tiras","purgation isle","spirits","арадос проклятый","хилсбрад","судья телград","кормок","кул тирас","остров очищения","духи"},ang={["class:Paladin"]="Печальное зрелище проклятых паладинов и судей, блуждающих по Острову Очищения, служит мрачным напоминанием о том, что бывает, когда святые защитники падают жертвой темных проклятий и лишаются вечного покоя.",["race:Dwarf"]="Среди проклятых призраков, населяющих кладбище, есть духи дворфов, привязывающие ваших сородичей к этой одинокой, продуваемой ветрами скале вдали от гор Каз Модана."},sec={{t="Обитель призраков",b="Остров Очищения резко поднимается из моря к югу от Хилсбрада; мрачное зрелище — извилистые тропы мимо надгробий к заброшенной сторожевой башне. Задолго до нынешних конфликтов остров был связан с морским королевством Кул Тирас. Теперь же его не считает своим ни одно живое государство. Вместо этого остров терзают осужденные души — бывшие паладины, жрецы, маги и судьи, что бродят среди могил, не находя покоя в смерти."},{t="Темные связи",b="Задержавшиеся на острове души сделали его местом зловещего интереса. Темные чародеи, такие как огр-некромант Кормок, как говорят, с наслаждением черпали силу из измученных мертвецов острова, призывая его духов исполнять свою волю."}},faq={{q="Где находится Остров Очищения?",a="Остров Очищения — уединенный остров у южного побережья Предгорий Хилсбрада, в заливе к югу от материка.",al={"purgation isle location","where is purgation isle","how to find purgation isle","расположение острова очищения","где остров очищения","как найти остров очищения"}},{q="Кто обитает на острове?",a="Остров наводнен могущественными осужденными духами, среди которых проклятые паладины, судьи, клирики, служители и корчащиеся маги из людей и дворфов.",al={"who is on purgation isle","mobs on purgation isle","purgation isle ghosts","кто на острове очищения","мобы на острове очищения","призраки острова очищения"}},{q="Кому изначально принадлежал Остров Очищения?",a="До Первой войны Остров Очищения считался отдаленной территорией островного королевства Кул Тирас, пока не пришел в запустение и призрачное забвение.",al={"history of purgation isle","who built purgation isle tower","история острова очищения","кто построил башню острова очищения"}},{q="Кто такой Кормок и почему его интересует этот остров?",a="Кормок — известный огр-некромант, овладевший искусством призывать осужденных духов Острова Очищения, чтобы они исполняли его волю, с помощью особых темных артефактов.",al={"kormok connection","brazier of invocation ghosts","связь кормока","жаровня призыва призраки"}}},fp="14,258,19.451.0,17.262.0,32.133.0,23.159.0,36.166.0,53.164.0"}
P.entries["subzone:pyrewood-village"] = {n="Деревня Погребальных Костров",s="Деревня Погребальных Костров — уединенное поселение людей на юге Серебряного бора, под Крепостью Темного Клыка. Она была частью Гилнеаса, но оказалась за Стеной Седогрива, и ее живые жители хранят жуткую тайну, навлеченную на них безумным верховным магом Аругалом.",h="Деревня Погребальных Костров — уединенное поселение людей на юге Серебряного бора, под Крепостью Темного...",kw={"arugal","crowley","greymane wall","moonrage","pyrewood","pyrewood village","shadowfang","silverpine","аругал","кроули","стена седогрива","лунный гнев","погребальные костры","деревня погребальных костров","темный клык","серебряный бор"},ang={["faction:Alliance"]="Деревня — трагический остаток живого человечества в Лордероне: днем жители готовы торговать с путниками, а каждую ночь поддаются жуткому проклятию.",["faction:Horde"]="Для Отрекшихся Погребальные Костры — очаг враждебных людей и чудовищных воргенов, служащих верховному магу Аругалу, прямо на границе их земель."},sec={{t="Отрезанный город",b="Погребальные Костры когда-то были процветающим поселением Гилнеаса во владении лорда Дариуса Кроули. Когда король Генн Седогрив решил изолировать свое королевство за громадной Стеной Седогрива после Второй войны, Погребальные Костры и соседняя Янтарная мельница остались на северной стороне. Отрезанные от родины, жители были совершенно беззащитны во время Третьей войны, когда Плеть шла по Лордерону. Хотя им удалось пережить первую волну нежити, настоящий кошмар начался, когда маг Аругал укрылся в крепости наверху."},{t="Проклятие Лунной Ярости",b="Из башен Крепости Темного Клыка верховный маг Аругал выпустил на окрестные земли потусторонних тварей и в итоге проклял живых жителей Погребальных Костров. При свете дня горожане выглядят обычными людьми и спокойно содержат ратушу, кузницу и часовню, даже торгуют с приезжими путниками Альянса. Но стоит солнцу скрыться за горизонтом, как происходит страшное превращение: каждый житель становится свирепым кровожадным воргеном стаи Лунной Ярости и нападает на любого, кому не повезло задержаться за стенами."}},faq={{q="Почему Деревня Погребальных Костров нападает на меня ночью?",a="Жители поражены темным проклятием верховного мага Аругала из Крепости Темного Клыка. Днем они сохраняют человеческий облик и рассудок, но каждую ночь превращаются в хищных воргенов Лунной Ярости, нападающих на всех чужаков на месте.",al={"pyrewood hostile at night","pyrewood worgen shift","why are they worgen","погребальные костры враждебны ночью","воргены погребальных костров","почему они воргены"}},{q="Почему Погребальные Костры находятся за Стеной Седогрива?",a="Король Генн Седогрив приказал построить Стену Седогрива, чтобы отгородить Гилнеас от внешнего мира после Второй войны. Лорд Дариус Кроули резко выступал против стены, так как она отрезала его северные владения, включая Погребальные Костры и Янтарную мельницу, оставив их жителей самим заботиться о себе.",al={"why outside the wall","is pyrewood gilnean","darius crowley pyrewood","почему за стеной","погребальные костры гилнеас","дариус кроули погребальные костры"}},{q="Могут ли игроки Альянса безопасно посещать Погребальные Костры?",a="Да, но строго в дневное время. Путники Альянса могут ходить среди горожан и торговать с местными торговцами, пока солнце не село. Но с наступлением темноты вся деревня превращается во враждебных воргенов, независимо от вашей фракции.",al={"alliance pyrewood friendly","can alliance go to pyrewood","pyrewood vendors","альянс погребальные костры дружелюбны","может ли альянс в погребальные костры","торговцы погребальных костров"}},{q="Как Орда относится к Погребальным Кострам?",a="Отрекшиеся считают деревню невыносимой угрозой на своей южной границе. По указаниям таких агентов, как Страж смерти Фарлия, Орда стремится убить совет деревни и разорвать связи Погребальных Костров с Аругалом.",al={"forsaken pyrewood","horde hostile pyrewood","deathstalker faerleia pyrewood","отрекшиеся погребальные костры","орда враждебна погребальные костры","страж смерти фарлия погребальные костры"}}},fp="16,279,14.546.0,18.571.1,45.250.0,42.295.0,43.254.0,33.228.0"}
P.entries["subzone:quagmire"] = {n="Трясина",s="Трясина — обширное коварное сердце центральных Пылевых топей. С севера ее ограничивает Деревня Гиблотопь, с юга — Земля Драконов; ее затопленные равнины печально известны трудной проходимостью. Враждебные звери и голодные слизи делают путь через это болото опасным.",h="Трясина — обширное коварное сердце центральных Пылевых топей.",kw={"beezil","crocolisk","dustwallow","quagmire","tabetha","бизил","кроколиск","пылевые топи","трясина","табета"},ang={["class:Mage"]="В глубине топи лежит Ферма Табеты — важная цель для начинающих магов, ищущих тайное обучение вдали от надзора Кирин-Тора."},sec={{t="Сердце топи",b="Трясина занимает широкое пространство между Разрушенной башней на западе и Пылевой бухтой на востоке и представляет собой дикое ядро болота. Почва здесь в лучшем случае ненадежна: твердая земля то и дело уступает место мутной воде и липкой грязи. Путникам приходится иметь дело с хищными кроколисками, таящимися под ряской, агрессивными пауками в мертвом кустарнике и странными слизями, сочащимися сквозь топь."},{t="Растущие столкновения",b="Помимо природных опасностей, Трясина служит непредсказуемым перекрестком для разумных сил, оспаривающих болото. В глубине топи скрывается Ферма Табеты — одинокое убежище для тех, кто ищет мудрость отшельницы среди опасностей болота."}},faq={{q="Где находится Трясина?",a="Трясина занимает центральную часть Пылевых топей. Она тянется на запад к Разрушенной башне, на восток к Пылевой бухте, на север до границ Деревни Гиблотопь, а на юг, где земля спускается к Земле Драконов.",al={"quagmire location","where is the quagmire","quagmire map","расположение трясины","где трясина","карта трясины"}}},fp="8,306,16.411.0,19.259.0,30.225.0"}
P.entries["subzone:quel-lithien-lodge"] = {n="Сторожка Кель'Литиен",s="Сторожка Кель'Литиен — изолированное убежище высших эльфов в лесистых северных холмах Восточных Чумных земель, неподалеку от границы Кель'Таласа. Ее Странники, которыми командует Рентар Ястребиное Копье, — изгнанники, отвергающие радикальные магические практики, принятые их сородичами в Silvermoon. Окруженная Плетью и преследуемая разведчиками Отрекшихся, сторожка борется за выживание и хранит древние эльфийские архивы.",h="Сторожка Кель'Литиен — изолированное убежище высших эльфов в лесистых северных холмах Восточных Чумных...",kw={"aurora skycaller","farstrider","high elves","marris stead","quel'lithien","quel'thalas registry","quellithien","renthar hawkspear","аврора небесный зов","странники","высшие эльфы","поместье маррисов","кель'литиен","реестр кель'таласа","рентар ястребиное копье"},ang={["class:Hunter"]="Размещенные здесь Странники олицетворяют многовековое талассийское мастерство стрельбы и поддерживают навыки выживания во враждебной глуши, полностью отрезанные от цивилизованного общества.",["faction:Horde"]="По приказам Натаноса Гнилостеня из Поместья Маррисов сюда направляют героев Орды со смертельным заданием — силой захватить записи высших эльфов."},sec={{t="Горькое изгнание",b="До Третьей войны Кель'Литиен был излюбленным лесным убежищем Странников Кель'Таласа, куда часто приезжали опытные следопыты, например Лор'темар Терон. Все изменилось, когда эльфийское королевство опустошила Плеть, а для облегчения отхода выживших были привнесены новые магические учения. Рентар Ястребиное Копье и отряд следопытов решительно возражали против этих сомнительных методов по моральным причинам. Не желая терпеть внутренние раздоры в разгар восстановления, регент-лорд Лор'темар изгнал несогласных на юг. Рентар привел своих последователей в Сторожку Кель'Литиен, где они сохраняют свою идентичность высших эльфов, оторванные от дома, но решительно держащиеся в стороне от оскверненных руин вокруг."},{t="Преследуемые в Чумных землях",b="Тихое бдение следопытов не осталось незамеченным. В глубине оскверненных лесов Натанос Гнилостень — некогда одинокий человек, Лорд-следопыт, обучавшийся вместе с этими самыми эльфами, — направил чемпионов Орды проникнуть в Сторожку Кель'Литиен. Натанос ищет Реестр Кель'Таласа — официальную запись со сведениями об ордене следопытов и родословных эльфов — и приказывает перебить защитников сторожки, чтобы заполучить его. Отрезанные от Луносвета и отказывающиеся от помощи, следопыты Кель'Литиен оказались в осаде как бывших союзников, так и окружающей нежити."}},faq={{q="Почему в Восточных Чумных землях живут высшие эльфы?",a="Обитатели сторожки — Странники и жрецы, изгнанные из Кель'Таласа регентом-лордом Лор'темаром Тероном. Они отказались принять мрачные, отчаянные методы, к которым прибегли после разрушения Солнечного Колодца, и предпочли изгнание тому, что считали моральным развращением своего народа.",al={"why high elves here","who lives at quel'lithien","quellithien elves","почему здесь высшие эльфы","кто живет в кель'литиене","эльфы кель'литиена"}},{q="Кто возглавляет Сторожку Кель'Литиен?",a="Сторожкой руководит Рентар Ястребиное Копье — опытный капитан эльфийских следопытов, командовавший здесь охотниками еще со времен Второй войны. После разногласий с руководством Луносвета он привел изгнанных инакомыслящих в сторожку, чтобы держать оборону вместе.",al={"quellithien leader","renthar hawkspear","who is renthar","лидер кель'литиена","рентар ястребиное копье","кто такой рентар"}},{q="Входят ли эльфы Сторожки Кель'Литиен в Альянс?",a="Нет. Хотя они дружелюбны к путникам из Альянса и открыто враждебны к Орде, сторожка является полностью независимым поселением высших эльфов и не получает ни официальной поддержки, ни указаний от Штормграда или Стальгорна.",al={"are quellithien elves alliance","quellithien faction","эльфы кель'литиена альянс","фракция кель'литиена"}},{q="Почему Натанос Гнилостень нацелился на сторожку?",a="Натанос Гнилостень посылает агентов Орды атаковать сторожку именно ради Реестра Кель'Таласа — важного исторического документа с перечнем эльфийских следопытов и записями о них, который хранится в архивах сторожки.",al={"why nathanos attack quellithien","the ranger lord's behest","quel'thalas registry","зачем натанос атакует кель'литиен","приказ лорда-следопыта","реестр кель'таласа"}},{q="Чем Кель'Литиен отличается от Сторожки Кель'Данил?",a="Обе были историческими охотничьими сторожками высших эльфов, но Кель'Данил безопасно расположена среди дружественных дворфов Громового Молота во Внутренних землях. Кель'Литиен же стоит в изоляции на линии фронта в Восточных Чумных землях, зажатая между оскверненными руинами и закрытыми вратами Кель'Таласа.",al={"queldanil vs quellithien","hinterlands lodge comparison","кель'данил и кель'литиен","сравнение сторожек внутренних земель"}}},fp="18,437,14.727.0,25.568.1,59.298.0,29.255.0,57.224.0,48.234.0,51.277.0"}
P.entries["subzone:rage-scar-hold"] = {n="Пещера Бешеного оврага",s="Пещера Бешеного оврага — пещера, вырубленная в глуши Фераласа на материке, недалеко от Крепости Оперенной Луны. Она известна тем, что в ней обитают одни из самых свирепых йети региона. Любопытно, что разбросанные книги, символы и следы архитектуры ночных эльфов в глубине говорят о том, что логово когда-то служило куда более мирной цели, пока его не заняли звери.",h="Пещера Бешеного оврага — пещера, вырубленная в глуши Фераласа на материке, недалеко от Крепости Оперенной...",kw={"barrow den","feathermoon","feralas","magic books","rage scar hold","yeti","логово-курган","оперенная луна","фередас","магические книги","пещера бешеного оврага","йети"},ang={["class:Mage"]="Наличие тайных символов и брошенных фолиантов в логове зверей вызывает тревожные вопросы о том, кто нашел свою гибель в глубине пещеры.",["race:NightElf"]="Осквернение того, что похоже на древнее логово-курган или святилище, грязными йети — горькое напоминание о диких опасностях, отвоевывающих исторические земли кальдораев."},sec={{t="Владения зверей",b="Пещера Бешеного оврага, вырубленная в суровой глуши Фераласа, принадлежит свирепым йети, нападающим на всякого, кто приблизится к их логову. Эти существа делают окрестные лесные тропы опасными как для часовых Альянса, так и для случайных путников. Йети обычны в диких землях Калимдора, но обитатели Пещеры Бешеного оврага выделяются крайней агрессией и свирепой защитой своей территории."},{t="Следы прошлого",b="Глубже в темных коридорах пещеры скрыты едва заметные признаки более древнего обитания. Резная каменная кладка и архитектура ночных эльфов говорят о том, что пещера когда-то была логовом-курганом или тайным убежищем магов. Забытые фолианты и таинственные знаки остались среди грязи и костей, и путники гадают: то ли несчастные ученые были убиты зверями, то ли йети почему-то тянутся к остаточной магии этого места."}},faq={{q="Что такое Пещера Бешеного оврага?",a="Пещера Бешеного оврага — сеть подземных пещер в Фераласе, на материке, недалеко от Крепости Оперенной Луны. Сейчас ее заполонила агрессивная стая диких йети.",al={"rage scar hold","what is this cave","feralas yeti cave","пещера бешеного оврага","что это за пещера","пещера йети в фераласе"}},{q="Почему в логове йети лежат книги и символы?",a="Фолианты, свитки и тайные символы брошены внутри пещеры. Вряд ли дикие звери умеют читать или изучать магию, поэтому эти реликвии говорят о том, что пещера когда-то была домом для несчастных магов или ученых-ночных эльфов, ставших жертвами йети.",al={"why books in yeti cave","are yetis studying magic","rage scar hold books","почему книги в пещере йети","йети изучают магию","книги пещеры бешеного оврага"}},{q="Построена ли эта пещера ночными эльфами?",a="Внутри есть каменная кладка ночных эльфов и пещерные сооружения, напоминающие логово-курган. Живых кальдораев внутри нет, а значит, первоначальные обитатели либо давно покинули это место, либо были истреблены, когда туда пришли йети.",al={"night elf architecture","was rage scar hold an elf barrow","barrow den feralas","архитектура ночных эльфов","была ли пещера бешеного оврага эльфийским курганом","курган логово фералас"}},{q="Отличаются ли здешние йети от других в Калимдоре?",a="Местные путники отмечают, что йети Пещеры Бешеного оврага — одни из самых свирепых и агрессивных в Фераласе: они защищают захваченный подземный дом с дикой жестокостью.",al={"feralas yetis","how dangerous are the yetis","rage scar beasts","йети фераласа","насколько опасны йети","звери бешеного оврага"}}},fp="14,374,16.391.0,18.421.0,23.186.0,50.262.0,37.241.0,53.193.0"}
P.entries["subzone:ragefire-chasm"] = {n="Огненная пропасть",s="Огненная пропасть — сеть вулканических пещер прямо под столицей Орды, Оргриммаром. Вход в нее находится в Расселине Теней, а в ее освещенных магмой туннелях обитают дикие трогги и тайная секта Совета Теней, стремящаяся изнутри разрушить молодую оркскую державу.",h="Огненная пропасть — сеть вулканических пещер прямо под столицей Орды, Оргриммаром.",kw={"bazzalan","cleft of shadow","jergosh the invoker","orgrimmar","ragefire chasm","rfc","searing blade","taragaman","troggs","баззалан","расселина теней","жергош призыватель духов","оргриммар","огненная пропасть","пламенеющий клинок","тарагаман","трогги"},ang={["class:Warlock"]="Присутствие Пламенеющего Клинка и его демонических хозяев показывает сохраняющуюся порчу магии Скверны, которую новая Орда Тралла активно стремится искоренить.",["faction:Horde"]="Огненная пропасть — вопиющий кризис безопасности в самом сердце столицы, проверяющий преданность молодых искателей приключений защите зарождающейся Орды."},sec={{t="Угроза под улицами",b="Пока Тралл укрепляет Дуротар наверху, под фундаментом Оргриммара зреют подземные опасности. Огненная пропасть — нестабильная сеть вулканических жерл и магматических рек, заполоненная свирепыми троггами Огненной пропасти. Эти враждебные существа, поднявшиеся из неведомых глубин под туннелями, жестоко отвергли дипломатические предложения Магаты Зловещего Тотема. Если их не остановить, одна лишь их численность грозит подорвать и захватить столицу."},{t="Пламенеющий Клинок",b="Гораздо опаснее троггов Пламенеющий Клинок — мятежная секта демонического Совета Теней, действующая из теней пропасти. Под руководством чернокнижника Жергоша Призывателя Духов, сатира Баззалана и громадного стражя Скверны по имени Тарагаман Ненасытный эти культисты замышляют гибель Орды Тралла. Хотя Нииру Огненный Клинок утверждает, что противостоит им, культ активно испытывает силы орков и подрывает их новый дом снизу."}},faq={{q="Где находится вход в Огненную пропасть?",a="Вход находится в глубине Оргриммара, в Расселине Теней, рядом с палаткой чернокнижника Нииру Огненного Клинка.",al={"rfc entrance","how to get to ragefire chasm","where is ragefire chasm located","вход в огненную пропасть","как попасть в огненную пропасть","где находится огненная пропасть"}},{q="Кто обитает в Огненной пропасти?",a="Пропасть заполонили агрессивные трогги Огненной пропасти, а также занял Пламенеющий Клинок — культ, связанный с Советом Теней. Его возглавляют чернокнижник Жергош Призыватель Духов, сатир Баззалан и страж Скверны Тарагаман Ненасытный.",al={"ragefire mobs","what enemies are in rfc","who controls ragefire chasm","враги огненной пропасти","какие враги в огненной пропасти","кто управляет огненной пропастью"}},{q="Почему Тралл не очистил пропасть?",a="Силы Орды растянуты: она обустраивает Дуротар и защищается от внешних угроз. Вождь Тралл полагается на способных героев, которые спустятся в пещеры, уничтожат главарей Пламенеющего Клинка и сократят число троггов, пока те не прорвались на улицы города.",al={"why does thrall allow ragefire","thrall ragefire chasm","почему тралл терпит огненную пропасть","тралл огненная пропасть"}},{q="Могут ли игроки Альянса войти в Огненную пропасть?",a="Да, но для этого нужно пробраться через ворота Оргриммара и спуститься в хорошо охраняемую Расселину Теней, что делает это крайне опасным предприятием для искателей приключений Альянса.",al={"can alliance do rfc","alliance in ragefire","может ли альянс в огненную пропасть","альянс в огненной пропасти"}}},fp="14,283,28.459.0,17.450.1,40.128.0,32.235.0,40.270.0,42.200.0"}
P.entries["subzone:ragefire-chasm-classic"] = {n="Огненная пропасть (Classic)",s="Огненная пропасть — обширная сеть вулканических туннелей прямо под Оргриммаром, вход в которую находится в сумрачных глубинах Расселины Теней. Несмотря на расположение под суверенной столицей Орды, эти огненные пещеры кишат враждебными троггами и подрывным культом, преданным Совету Теней.",h="Огненная пропасть — обширная сеть вулканических туннелей прямо под Оргриммаром, вход в которую находится в...",kw={"bazzalan","cleft of shadow","jergosh","ragefire chasm","rfc","searing blade","taragaman","troggs","баззалан","расселина теней","жергош","огненная пропасть","пламенеющий клинок","тарагаман","трогги"},ang={["faction:Horde"]="Очистка Огненной пропасти — дело обороны родины: она укрепляет основу Дуротара против внутренних диверсий и искореняет демонических пособников.",["race:Tauren"]="Мудрая старуха Магата Зловещий Тотем отправила посланников просить мира у вторгшихся троггов; их кровавый отказ доказал, что с этими подземными тварями дипломатия невозможна."},sec={{t="Скрытая опасность",b="Под каменными улицами и укрепленными башнями Оргриммара лежит Огненная пропасть — коварная сеть подземных пещер, заполненных магмой. Туннели недавно заполонили свирепые трогги, поднявшиеся из глубоких подземных трещин. Магата Зловещий Тотем из тауренов пыталась вести с ними мирные переговоры, но ее предложения были жестоко отвергнуты. Если их не остановить, трогги будут пробиваться все глубже к самому основанию города."},{t="Пламенеющий Клинок",b="Гораздо опаснее безмозглых троггов присутствие Пламенеющего Клинка — мятежного культа, подчиненного демоническому Совету Теней. Во главе с огромным стражем Скверны Тарагаманом Ненасытным, орком-чернокнижником Жергошем Призывателем Духов и порочным сатиром Баззаланом эти заговорщики замышляют разрушить все, что Орда Тралла создала в Дуротаре. Вместо того чтобы сразу очистить пещеры, вождь Тралл продолжает наблюдать за их действиями, надеясь, что их глупая самоуверенность выдаст их хозяев выше в иерархии Совета Теней."}},faq={{q="Где находится вход в Огненную пропасть?",a="Входной портал находится в глубине Оргриммара, в подземном каньоне под названием Расселина Теней, рядом с палаткой орка-чернокнижника Нииру Огненного Клинка.",al={"where is ragefire","rfc entrance","how to get to rfc","where is rfc located","где огненная пропасть","вход в огненную пропасть","как попасть в огненную пропасть"}},{q="Почему под Оргриммаром есть трогги?",a="Трогги поднялись из древних глубоких пещерных систем под Дуротаром и вышли прямо в вулканические недра города. Их внезапное вторжение создает структурную и физическую угрозу для столицы и не поддается попыткам мирного сдерживания.",al={"why are troggs here","ragefire troggs","orgrimmar troggs","почему здесь трогги","трогги огненной пропасти","трогги оргриммара"}},{q="Почему Тралл позволяет культистам жить под столицей?",a="Вождь Тралл прекрасно знает о присутствии культа под городом. Вместо грубого штурма, из-за которого сеть могла бы разбежаться, он позволяет им действовать под пристальным наблюдением, надеясь, что они невольно раскроют личности и местонахождение истинных руководителей Совета Теней.",al={"why doesn't thrall clear rfc","thrall shadow council","why is searing blade under orgrimmar","почему тралл не очистит огненную пропасть","тралл совет теней","почему пламенеющий клинок под оргриммаром"}},{q="Кто возглавляет культистов в пропасти?",a="Пламенеющим Клинком в Огненной пропасти командуют трое: Тарагаман Ненасытный, грозный страж Скверны; Жергош Призыватель Духов, орк-чернокнижник; и Баззалан, коварный сатир.",al={"rfc bosses","who leads the searing blade","ragefire chasm leaders","боссы огненной пропасти","кто возглавляет пламенеющий клинок","лидеры огненной пропасти"}}},fp="24,324,14.477.0,17.567.1,40.181.0,39.254.0,57.310.0,40.189.0"}
P.entries["subzone:raptor-grounds"] = {n="Земли Ящеров",s="Земли Ящеров — уединенная долина в пыльных холмах южных Степей, которую заняли ящеры Солнечной Чешуи. В отличие от обычных диких зверей, здешняя стая отличается жутковатой хитростью, использует орудия и одержима желанием красть блестящие безделушки из ближайших поселений.",h="Земли Ящеров — уединенная долина в пыльных холмах южных Степей, которую заняли ящеры Солнечной Чешуи.",kw={"northwatch hold","raptor grounds","raptors","stolen silver","sunscale raptor","the barrens","крепость северной стражи","земли ящеров","ящеры","краденое серебро","ящер солнечной чешуи","степи"},ang={["class:Hunter"]="Необычная хитрость стаи Солнечной Чешуи, ее согласованность и умение строить простейшие укрытия делают ящеров увлекательным объектом изучения для любого умелого следопыта.",["faction:Horde"]="Ящеры Солнечной Чешуи постоянно угрожают караванам и форпостам Орды на юге Степей, из-за чего назначаются награды и снаряжаются экспедиции за украденным богатством."},sec={{t="Необычные звери южных пустошей",b="Земли Ящеров, расположенные к западу от Крепости Северной Стражи, — основная территория гнездования ящеров Солнечной Чешуи. Путники быстро понимают, что эти существа — вовсе не бездумные хищники: они проявляют неестественный ум, строят грубые укрытия, мастерят примитивные орудия и согласованно охотятся. Движимая неутолимым влечением к блестящим и необычным предметам, стая регулярно нападает на проезжающие караваны и лагеря Орды и утаскивает монеты, безделушки и припасы в свои логова в каньоне."}},faq={{q="Где находятся Земли Ящеров?",a="Земли Ящеров — небольшая низинная долина в южной части Степей, укрытая в скалистых холмах к западу от Крепости Северной Стражи.",al={"raptor grounds location","where are the raptor grounds","raptor grounds map","земли ящеров где находятся","где земли ящеров","земли ящеров карта"}},{q="Чем здешние ящеры отличаются от обычных зверей?",a="Ящеры Солнечной Чешуи обладают неестественным умом. Вместо того чтобы полагаться лишь на дикие инстинкты, они мастерят примитивные орудия и строят грубые хижины, чтобы укрыть стаю и спрятать краденое.",al={"sunscale raptor intelligence","why do raptors have huts","smart raptors barrens","ум ящеров солнечной чешуи","зачем ящерам хижины","умные ящеры степи"}},{q="Почему ящеры нападают на караваны и крадут вещи?",a="Стаю неотступно влечет к блестящим, сверкающим и необычным предметам. Из-за этого ящеры устраивают засады на путников и грабят поселения Орды, пряча украденные монеты и металл в глубине своей долины.",al={"stolen silver raptors","why do raptors steal","raptor shiny things","краденое серебро ящеры","зачем ящеры воруют","ящеры блестящие вещи"}},{q="Кто владеет этой долиной?",a="Ни одна из фракций не владеет долиной. Это неприрученная охотничья территория и место гнездования диких ящеров Солнечной Чешуи, которые яростно защищают ее от любого, кто сюда забредет.",al={"who owns raptor grounds","is raptor grounds horde","кому принадлежат земли ящеров","земли ящеров орда"}}},fp="14,278,37.521.0,28.136.0,54.208.0,51.214.0,25.171.0"}
P.entries["subzone:raptor-ridge"] = {n="Гряда Ящеров",s="Гряда Ящеров — возвышенная неровная местность на востоке Болотины, к северо-западу от укрепленных Врат Драконьей Пасти. Это основные охотничьи угодья и места гнездования стай свирепых ящеров Остроклыков, над которыми в глубине пещер властвует особенно злобная матриарх.",h="Гряда Ящеров — возвышенная неровная местность на востоке Болотины, к северо-западу от укрепленных Врат...",kw={"dragonmaw gates","raptor ridge","razormaw","razormaw matriarch","wetlands","врата драконьей пасти","гряда ящеров","остроклык","матриарх остроклыков","болотина"},ang={["class:Hunter"]="Свирепые ящеры Остроклыки с гряды — мощные и агрессивные питомцы для любого охотника, ищущего быстрого и упорного спутника для болот."},sec={{t="Логово хищников",b="Гряда Ящеров возвышается над сырыми болотами восточной Болотины и считается одним из самых опасных диких мест региона. Злобные ящеры Остроклыки большими стаями бродят по скалам и каменистым тропам, и путешествовать у предгорий Каз Модана опасно. В сердце гряды лежит мрачная пещера, где властвует Матриарх Остроклыков; ее агрессивный выводок яростно защищает гнезда от любых хищников и неосторожных путников, подошедших слишком близко к Вратам Драконьей Пасти."}},faq={{q="Где находится Гряда Ящеров?",a="Гряда Ящеров лежит на дальнем востоке Болотины, прямо к северо-западу от Врат Драконьей Пасти, которые охраняют дорогу к Грим Батолу.",al={"raptor ridge location","where is raptor ridge","how to get to raptor ridge","гряда ящеров где находится","где гряда ящеров","как добраться до гряды ящеров"}},{q="Какие существа здесь обитают?",a="Гряда кишит ящерами Остроклыками. В глубине пещеры путники также найдут Матриарха Остроклыков, охраняющую свои гнезда и детенышей.",al={"what mobs are at raptor ridge","raptors in wetlands","raptor ridge beasts","какие монстры на гряде ящеров","ящеры в болотине","звери гряды ящеров"}},{q="Кто такая Матриарх Остроклыков?",a="Матриарх Остроклыков — огромная и смертоносная предводительница местных стай ящеров, которая охраняет свою кладку в центральной пещере гряды.",al={"razormaw matriarch","raptor matriarch wetlands","raptor boss wetlands","матриарх остроклыков","матриарх ящеров болотина","босс ящеров болотина"}},{q="Почему здесь так опасно путешествовать?",a="Помимо плотных стай агрессивных быстрых ящеров, нападающих на чужаков, гряда лежит в тени враждебных орков Драконьей Пасти, обитающих у горных перевалов.",al={"is raptor ridge dangerous","raptor ridge threat","опасна ли гряда ящеров","гряда ящеров угроза"}}},fp="12,284,18.515.0,30.145.0,25.151.0,30.137.0,41.177.0"}
P.entries["subzone:ratchet"] = {n="Кабестан",s="Кабестан — оживленный нейтральный портовый город Картеля Хитрая Шестеренка на восточном побережье Степей. Основанный главным инженером Газлоу после того, как тот помог построить Оргриммар, он служит главным морским торговым узлом между центральным Калимдором и Восточными королевствами.",h="Кабестан — оживленный нейтральный портовый город Картеля Хитрая Шестеренка на восточном побережье Степей.",kw={"barrens","booty bay","gazlowe","maiden's fancy","ratchet","steamwheedle cartel","strahad farsan","степи","пиратская бухта","газлоу","каприз девы","кабестан","картель хитрая шестеренка","страхад фарсан"},ang={["class:Warlock"]="Башня на утесах над Кабестаном — крупное место обучения, где чернокнижники всех происхождений собираются у Страхада Фарсана и Менары Расщепительницы Бездны, чтобы освоить высшие приемы призыва демонов.",["faction:Alliance"]="Кабестан предлагает искателям приключений из Альянса редкую безопасную гавань во враждебных землях центральных Степей, с морским сообщением и маршрутами полета."},sec={{t="Перекресток Великого моря",b="Кабестан расположен на засушливом побережье между Дуротаром и Пылевыми топями и предлагает безопасную гавань каждому, у кого есть деньги. Порт основал предприимчивый инженер Газлоу после Третьей войны: он вырос из контрабандистов, изгнанников и отважных торговцев, стремившихся нажиться на пограничье Калимдора. Город находится под знаменем Картеля Хитрая Шестеренка и соблюдает строгий нейтралитет между Ордой и Альянсом. Корабли, такие как «Прихоть девы», регулярно ходят через Великое море в Пиратскую бухту и перевозят товары, наемников и сырье между континентами. Местные громилы внимательно следят за причалами и безжалостно избивают всякого, кто по глупости затеет драку и помешает торговле."},{t="Тени над доками",b="Несмотря на облик шумного торгового города доков, таверн и мастерских, в Кабестане идут и более темные дела. Над гаванью, на холмах, стоит уединенная башня, где обосновался открытый ковен чернокнижников, среди которых Страхад Фарсан и Менара Расщепительница Бездны. Пока горожане и моряки заняты грузовыми описями и гоблинской инженерией, адепты темных искусств спокойно собираются здесь, чтобы общаться с демоническими силами, не стесняясь моральных запретов, действующих в обычных столицах фракций."}},faq={{q="Кто правит Кабестаном?",a="Кабестаном управляет главный инженер Газлоу от имени нейтрального Картеля Хитрая Шестеренка. Газлоу основал город вскоре после того, как вождь Тралл щедро заплатил ему за руководство строительством инфраструктуры Оргриммара.",al={"ratchet leader","who is in charge of ratchet","gazlowe ratchet","глава кабестана","кто управляет кабестаном","газлоу кабестан"}},{q="Могут ли игроки Альянса безопасно посещать Кабестан?",a="Да. Кабестан — нейтральный гоблинский порт. Пока вы не враждебны Картелю Хитрая Шестеренка и не нападаете на других в черте города, путники и Альянса, и Орды могут пользоваться гостиницей, банком, торговцами, маршрутами полета и паромом.",al={"is ratchet safe for alliance","alliance in ratchet","can alliance go to ratchet","безопасен ли кабестан для альянса","альянс в кабестане","может ли альянс зайти в кабестан"}},{q="Куда плывет корабль в Кабестане?",a="Судно, стоящее у южного причала, «Каприз девы», плывет через Великое море в Пиратскую бухту на южной оконечности Тернистой долины. Это одна из главных морских связей между Калимдором и Восточными королевствами.",al={"ratchet boat destination","where does the ratchet ship go","boat to eastern kingdoms","куда плывет корабль из кабестана","куда идет корабль кабестан","корабль в восточные королевства"}},{q="Почему на холмах над городом живут чернокнижники?",a="В башне над Кабестаном обосновался ковен чернокнижников, который возглавляют Страхад Фарсан и Менара Расщепительница Бездны. Безразличие Картеля Хитрая Шестеренка к темной магии позволяет этим колдунам работать, обучать учеников и подчинять демонов без вмешательства религиозных или светских властей.",al={"ratchet warlocks","strahad farsan tower","warlock tower ratchet","чернокнижники кабестана","башня страхада фарсана","башня чернокнижников кабестан"}},{q="Что будет, если затеять драку в Кабестане?",a="Громилы Кабестана немедленно вмешаются и атакуют зачинщика тяжелыми дубинками и сетями. Мешать торговле в гоблинских поселениях строго запрещено, а драки здесь быстро испортят вашу репутацию у Картеля Хитрая Шестеренка.",al={"ratchet guards","attacking players in ratchet","ratchet bruisers","стража кабестана","нападение на игроков в кабестане","громилы кабестана"}}},fp="7,272,31.707.0,23.547.0,18.248.0,42.248.0,34.239.0,51.291.0,43.248.0"}
P.entries["subzone:ravaged-caravan"] = {n="Разграбленный караван",s="Разграбленный караван — дымящиеся обломки на северо-восточном берегу Озера Каменного Быка в Мулгоре. Когда-то это был обоз с припасами для рудников Бригадира Шумовика; его подстерегли и разгромили местные таурены, решившие положить конец гоблинской эксплуатации их родины.",h="Разграбленный караван — дымящиеся обломки на северо-восточном берегу Озера Каменного Быка в Мулгоре.",kw={"mulgore","ravaged caravan","stonebull lake","supervisor fizsprocket","tauren","venture co","venture company","wagon","мулгор","разграбленный караван","озеро каменного быка","бригадир шумовик","таурены","торговая компания","повозка"},ang={["class:Druid"]="Черный дым, душащий берег Озера Каменного Быка, — суровое напоминание о бездумном вреде, который гоблинские машины наносят природному равновесию.",["race:Tauren"]="Обугленные повозки — свидетельство того, что ваш народ немедленно и решительно отказался позволить чужим промышленным синдикатам осквернять священные пастбища Мулгора."},sec={{t="Дым над Озером Каменного Быка",b="Разграбленный караван, стоящий на возвышенности над Озером Каменного Быка, отмечает одну из первых стычек между тауренами Деревни Кровавого Копыта и наступающей Торговой Компанией. Караван вез горное снаряжение, чертежи и оборудование на участок Бригадира Шумовика, но был отрезан и разгромлен защитниками-тауренами, не успев добраться до цели. Несмотря на разорение, упрямые уцелевшие работники Торговой Компании все еще держатся у разбитых повозок и тлеющих ящиков, ревниво охраняя остатки груза."}},faq={{q="Что случилось с этим караваном?",a="Караван перехватили и разгромили местные таурены, заметившие, как Торговая Компания продвигается вглубь Мулгора. Желая помешать гоблинам разорять землю, таурены уничтожили обоз до того, как груз добрался до ближайшего рудника.",al={"why is the caravan burned","what happened here","ravaged caravan backstory","почему караван сожжен","что здесь произошло","история разграбленного каравана"}},{q="Кому принадлежат разбитые повозки?",a="Караван принадлежит Торговой Компании — беспринципному гоблинскому горнодобывающему объединению, пытающемуся без разрешения наладить добычу в холмах Мулгора.",al={"whose caravan is this","who owns the caravan","venture company caravan","чей это караван","кому принадлежит караван","караван торговой компании"}},{q="Куда направлялся караван?",a="Он вез инструменты, механизмы и припасы на север, к Бригадиру Шумовику, который руководит открытыми горными разработками Торговой Компании на Руднике Торговой компании.",al={"caravan destination","where was it going","fizsprocket supplies","цель каравана","куда он направлялся","припасы шумовика"}},{q="Почему у обломков до сих пор остаются работники Торговой Компании?",a="Уцелевшие наемники и работники Торговой Компании яростно охраняют имущество компании. Вместо того чтобы бросить потерянное, они укрепились у обугленных повозок, пытаясь спасти остатки снаряжения.",al={"why are goblins still here","venture co survivors","who is guarding the wreck","почему здесь еще гоблины","выжившие торговой компании","кто охраняет обломки"}}},fp="15,284,25.507.0,30.244.0,28.156.0,30.162.0,63.237.0"}
P.entries["subzone:ravaged-twilight-camp"] = {n="Разоренный Сумеречный лагерь",s="Разоренный Сумеречный лагерь, спрятанный в уединенной Долине Кристаллов на северо-западе Силитуса, лежит в руинах среди высоких минеральных образований. Это отдаленное убежище эксцентричного отшельника верховного лорда Демитриана, почитателя Искателя Ветра.",h="Разоренный Сумеречный лагерь, спрятанный в уединенной Долине Кристаллов на северо-западе Силитуса, лежит в...",kw={"crystal vale","demitrian","highlord demitrian","ravaged twilight camp","silithus","thunderaan","thunderfury","twilight's hammer","долина кристаллов","демитриан","верховный лорд демитриан","разоренный сумеречный лагерь","силитус","громораан","громовая ярость","сумеречный молот"},ang={["class:Paladin"]="Тем, кто ищет легендарное стихийное оружие древности, нужно найти Демитриана в Долине Кристаллов, чтобы разгадать сосуд принца Громораана.",["class:Warrior"]="Любой воин, идущий по слухам о легендарном клинке — Громовой ярости, благословенном клинке Искателя Ветра, — рано или поздно придет прямо к верховному лорду Демитриану в этом забытом лагере."},sec={{t="Руины отшельника в долине",b="Хотя Сумеречный Молот держит множество действующих застав в песках Силитуса, этот разрушенный лагерь в Долине Кристаллов рассказывает иную историю. Он лежит вдали от главных крепостей культа, почти разрушенный и покинутый, если не считать верховного лорда Демитриана. Слуга Громораана, Демитриан остается среди камней, словно брошенный остальным Сумеречным Молотом или оторванный от него, и размышляет о стихийных оковах и утраченной силе Искателя Ветра."}},faq={{q="Что такое Разоренный Сумеречный лагерь?",a="Это разбитый разрушенный форпост в Долине Кристаллов на северо-западе Силитуса, известный как личное жилище верховного лорда Демитриана.",al={"ravaged twilight camp","ruined twilight camp silithus","crystal vale camp","разоренный сумеречный лагерь","разрушенный сумеречный лагерь силитус","лагерь в долине кристаллов"}},{q="Кто здесь живет?",a="Единственный заметный обитатель — верховный лорд Демитриан, одинокая фигура, тесно связанная с преданиями о стихиях и оковами принца Громораана.",al={"who is at the ravaged twilight camp","highlord demitrian location","camp npc","кто в разоренном сумеречном лагере","где верховный лорд демитриан","персонаж лагеря"}},{q="Почему лагерь разрушен?",a="Записи культа упоминают о разрушенном состоянии места, но Демитриан остается среди развалин, изолированный от остального Сумеречного Молота, действующего в Силитусе.",al={"why is it ravaged","what destroyed the camp","who attacked the camp","почему разорен","что разрушило лагерь","кто напал на лагерь"}},{q="Враждебен ли здесь Сумеречный Молот?",a="В отличие от оживленных Сумеречных лагерей на юге и в центре Силитуса, в этом лагере нет агрессивных патрулей культа, и Демитриан может спокойно размышлять в одиночестве.",al={"are cultists attacking here","is demitrian hostile","нападают ли здесь культисты","враждебен ли демитриан"}}},fp="21,246,27.486.0,34.146.0,15.135.0,23.159.0,38.150.0"}
P.entries["subzone:raven-hill"] = {n="Вороний Холм",s="Вороний Холм — опустевшая разрушенная деревня на западе Сумеречного леса, лежащая в длинной тени обширного Кладбища Вороньего Холма. Некогда оживленное человеческое поселение, теперь оно покинуто всеми, кроме горстки напуганных поселенцев и невидимых духов.",h="Вороний Холм — опустевшая разрушенная деревня на западе Сумеречного леса, лежащая в длинной тени обширного...",kw={"abandoned town","bliztik","cemetery","duskwood","jitters","raven hill","unseen","заброшенный город","близтик","кладбище","сумеречный лес","трясунчик","вороний холм","незримые"},ang={["faction:Alliance"]="Для путников Альянса, пересекающих мост из Западного Края, Вороний Холм становится зловещим предвестником кошмара, поглощающего запад Сумеречного леса.",["race:Human"]="Гниющие домики — мрачное напоминание о том, как много земель королевство Штормград потеряло из-за подступающей тьмы и запустения."},sec={{t="Город, павший во тьму",b="Вороний Холм расположен у западной дороги Сумеречного леса, к северу от Участка Эддла, и стал трагической тенью самого себя. Когда темная магия и ужасы нежити захлестнули область Большой деревни, живые ушли на восток, в Темнолесье, или вовсе покинули эти земли. Сегодня разрушенные деревянные дома гниют под вечным мраком. Путники обходят их стороной, опасаясь и беспокойных мертвецов, приходящих с соседнего кладбища, и Незримых, таящихся среди рушащихся стен."},{t="Те, кто остался",b="Несмотря на мрачную славу, Вороний Холм не совсем безлюден. Искатель приключений по имени Трясунчик, нервный и издерганный, прячется среди заброшенных построек: он в ужасе от того, что помогло выпустить на волю его собственное былое любопытство. Выше, на чердаке одного из ветхих домов, предприимчивый гоблин по имени Близтик едва сводит концы с концами, продавая припасы осторожным прохожим. Руины они делят с невидимыми духами, известными как Незримые, живя взаймы у края раскинувшегося кладбища."}},faq={{q="Почему Вороний Холм заброшен?",a="Вороний Холм был покинут, когда над Сумеречным лесом сгустилась тень, принесшая нежить, темную магию и хищных зверей. Близость огромного Кладбища Вороньего Холма сделала город особенно беззащитным, и уцелевшие жители бежали на восток, в укрепленное поселение Темнолесье.",al={"what happened to raven hill","why is raven hill ruined","who lived in raven hill","что случилось с вороньим холмом","почему вороний холм разрушен","кто жил в вороньем холме"}},{q="Кто на самом деле живет в деревне сейчас?",a="Здесь обитает лишь горстка смелых или отчаявшихся душ. Напуганный человек Трясунчик прячется среди разрушенных фундаментов, терзаемый виной и страхом, а торговец-гоблин по имени Близтик работает на верхнем этаже и торгует со всеми, кто осмелится обыскать заброшенные здания.",al={"who is in raven hill","raven hill npcs","living people raven hill","кто в вороньем холме","персонажи вороний холм","жители вороний холм"}},{q="Кто такие Незримые, обитающие в Вороньем Холме?",a="Незримые — невидимые враждебные духи, бродящие по Вороньему Холму и соседнему кладбищу. Хотя обычным зрением их не увидеть, они внезапно и смертельно угрожают любому неосторожному путнику, исследующему опустевший поселок.",al={"unseen raven hill","invisible monsters raven hill","ghosts in raven hill","незримые вороний холм","невидимые монстры вороний холм","призраки в вороньем холме"}},{q="Куда ведет дорога через Вороний Холм?",a="Дорога мимо Вороньего Холма ведет на запад, к мосту через реку в Западный Край, на юг, к Участку Эддла и границе Тернистой долины, и на восток через сердце Сумеречного леса в Темнолесье.",al={"raven hill road","where does road go","travel raven hill","дорога вороний холм","куда ведет дорога","путь через вороний холм"}}},fp="10,238,23.498.0,18.499.0,28.305.0,38.275.0,40.236.0,44.215.0"}
P.entries["subzone:raven-hill-cemetery"] = {n="Кладбище Вороньего Холма",s="Кладбище Вороньего Холма — обширное проклятое кладбище, раскинувшееся на западе Сумеречного леса. Когда-то тихое место захоронений для окрестных деревень, теперь оно захвачено полчищами ходячих мертвецов, пауков-падальщиков и безжалостных расхитителей могил.",h="Кладбище Вороньего Холма — обширное проклятое кладбище, раскинувшееся на западе Сумеречного леса.",kw={"abercrombie","duskwood","forlorn rowe","grave robbers","mor'ladim","morbent fel","raven hill cemetery","skeletons","аберкромби","сумеречный лес","покинутая усадьба","расхитители могил","мор'ладим","морбент скверн","кладбище вороньего холма","скелеты"},ang={["class:Paladin"]="Неослабевающая порча и осквернение могил на Кладбище Вороньего Холма требуют священного освящения.",["class:Priest"]="Кладбище хранит мощные проводники Тьмы и остаточной скорби — мрачный урок о трагедии духов, которым закрыт путь к Свету."},sec={{t="Сад беспокойных мертвецов",b="Пока тьма не поглотила Сумеречный лес, Кладбище Вороньего Холма служило главным местом упокоения для окрестных поселений. Когда на область обрушилась темная волшба, мертвецы перестали оставаться в могилах. Скелеты, вурдалаки и бредущие ужасы выбирались из земли, расширяя мрачные границы кладбища. Сегодня это одна из самых опасных язв Сумеречного леса. Здесь бродят не только гниющие мерзости и гигантские пауки, но и отчаянные расхитители могил, стремящиеся без помех местных властей грабить склепы предков."},{t="Беспокойные духи и темные силы",b="Трагедию кладбища воплощает Мор'Ладим — безмозглый скелет павшего рыцаря Моргана Ладимора, который бесконечно бродит среди надгробий после того, как покончил с собой в безумии и скорби. Севернее, на возвышенностях Покинутой усадьбы, темный некромант Морбент Скверн использует мерзкую энергию могил, чтобы поднимать и подчинять легионы нежити. Еще дальше, у северо-восточного края, стоит уединенная хижина отшельника Аберкромби, который наблюдает за кладбищем с края тумана."}},faq={{q="Почему на Кладбище Вороньего Холма поднимается так много нежити?",a="Кладбище поддалось темной порче, когда Сумеречный лес был осквернен, и некромантические силы просочились в землю. Мерзкий маг Морбент Скверн, скрывающийся в Покинутой усадьбе на краю кладбища, намеренно искажает эти энергии, поднимая трупы из могил и управляя ими.",al={"why are there zombies","why is raven hill haunted","who raised the dead in raven hill","почему там зомби","почему вороний холм населен призраками","кто поднял мертвецов в вороньем холме"}},{q="Кто такой Мор'Ладим?",a="Mor'Ladim is a deadly skeletal revenant who patrols the graveyard and attacks travelers. His identity and past are learned through an investigation in Darkshire.",al={"morladim","skeleton wandering the graveyard","morgan ladimore","морладим","скелет на кладбище","морган ладимор"}},{q="Где на кладбище находится Морбент Скверн?",a="Морбент Скверн обитает на вершине холма, известного как Покинутая усадьба, в северо-западном углу Кладбища Вороньего Холма. Он живет в ветхом доме над надгробиями и управляет окружающей его нежитью.",al={"morbent fel location","where is morbent fel","forlorn rowe","где морбент скверн","морбент скверн","покинутая усадьба"}},{q="Кто тот отшельник, живущий на краю кладбища?",a="Отшельник — Аберкромби, чудаковатый и немощный старик, живущий в покосившейся хижине у северо-восточной границы кладбища. Он часто просит проходящих путников собрать странные компоненты и ингредиенты для его мрачных личных затей.",al={"hermit at raven hill","abercrombie","shack in raven hill","отшельник вороний холм","аберкромби","хижина в вороньем холме"}}},fp="19,251,29.579.0,32.497.1,53.274.0,17.161.1,45.206.0,53.252.0"}
P.entries["subzone:ravencrest-monument"] = {sec={{t="Руины колосса",b="Standing high above the ocean southeast of the Ruins of Eldarath, the Ravencrest Monument was once an awe-inspiring marvel of Kaldorei stonework. Today, little remains of the majestic colossus beyond its pair of gigantic broken legs rooted to the stone plinth, with the shattered fragments of its torso and head either buried in the cliffside dirt or lost beneath the waves below. Reaching this remote coastal promontory requires trekking across the mainland bridges of Azshara, as sheer, rocky drops prevent any approach from the sea."},{t="Забытое наследие",b="Scholars often speculate that the monument commemorates Lord Kur'talos Ravencrest, the famed noble who rallied and led the night elven host during the War of the Ancients after the fall of Zin-Azshari. However, its close proximity to the pre-Sundering city of Eldarath and ambiguous surviving stonework leave its true origins debated. Rather than pilgrims or night elven caretakers, the surrounding cliff is currently claimed by the serpentine Spitelash naga, who defend the fallen monument with vicious territorial aggression."}},faq={{q="What is the Ravencrest Monument?",a="Это разрушенное основание огромного колосса ночных эльфов на прибрежном мысу в южной Азшаре. Прямо стоят лишь его гигантские каменные ноги, а остальная часть скульптуры лежит разбитой и разбросанной по вершине утеса.",al={"ravencrest statue","what is this statue","giant legs azshara"}},{q="В чью честь воздвигнут памятник?",a="It bears the name of House Ravencrest, most famous for Lord Kur'talos Ravencrest, the noble commander who led the mortal resistance against the Burning Legion during the War of the Ancients. However, because it sits near the ancient ruins of Eldarath, it is unclear whether it honors Kur'talos directly or an earlier ancestor from before the Great Sundering.",al={"who is ravencrest","who is the statue of","kurtalos ravencrest"}},{q="Как добраться до памятника?",a="На памятник нельзя подняться или попасть с моря из-за отвесных утесов. Путникам нужно идти по суше через южную Азшару, пересекая каменные мосты у Руин Эльдарата, чтобы добраться до мыса.",al={"how to get to ravencrest monument","ravencrest path","ravencrest access"}},{q="Какие существа обитают у памятника сегодня?",a="The clifftop and surrounding terraces are infested with the Spitelash naga, making any exploration of the ancient ruins perilous for solitary travelers.",al={"what lives here","monument enemies","azshara naga","кто здесь живет","враги у памятника","наги азшары"}}},fp="19,325,19.535.0,18.527.0,32.240.0,36.358.0,30.213.0,42.152.0"}
P.entries["subzone:ravenholdt-manor"] = {kw={"alterac","assassin","hillsbrad","jorach ravenholdt","manor","ravenholdt","rogue guild","syndicate","thief","альтерак","убийца","хилсбрад","джорах черный ворон","поместье","черный ворон","гильдия разбойников","синдикат","вор"},ang={["class:Rogue"]="Поместье Черного Ворона — главное убежище для представителей вашей профессии: здесь строгие испытания, особое обучение и обширная сеть подпольных связей.",["profession:Engineering"]="Знающие инженеры отправляются через горный проход именно за редкой схемой Маскировочного механизма гномов из запасов поместья."},sec={{t="Убежище в тени",b="Hidden behind a narrow mountain pass and a winding cave northwest of Durnholde Keep, Ravenholdt Manor sits isolated on the borderlands of the Alterac Mountains. The property belongs to Lord Jorach Ravenholdt, a nobleman who maintains a disciplined enclave of rogues, assassins, and intelligence operatives. The grounds feature a tranquil garden and an outdoor training arena overseen by martial experts like Master Kang, providing a disciplined space to practice lockpicking, poison-crafting, and close-quarters combat. While the manor welcomes those with a talent for skullduggery, clumsy outsiders and unwanted visitors are treated with cold suspicion by the manor's watchful sentries."},{t="Затяжная вражда в предгорьях",b="Prior to the First War, the land surrounding the manor was part of the kingdom of Alterac, reflected in the weathered orange tiles of the manor's roof. In the turbulent wake of Alterac's ruin, the fallen nobles of the Syndicate sought to control the region, placing them in direct conflict with Ravenholdt. Ravenholdt maintains an uneasy association with Stormwind's SI:7 intelligence service, cooperating where interests align to purge Syndicate influences from the surrounding highlands. For Jorach's followers, every skirmish fought across Hillsbrad and Alterac is part of a silent war to maintain their sovereign haven."}},faq={{q="How do you reach Ravenholdt Manor?",a="Чтобы добраться до поместья, идите на плато к северо-западу от Крепости Дарнхольд в Предгорьях Хилсбрада. Там, где плато встречается с северными горами, малозаметная грунтовая тропа поднимается вверх и проходит через скрытую пещеру, выходя прямо на территорию поместья.",al={"where is ravenholdt manor","how to get to ravenholdt","ravenholdt path"}},{q="Who owns Ravenholdt Manor?",a="Поместье принадлежит лорду Джораху Черному Ворону, возглавляющему элитное братство воров и убийц, известное просто как Черный Ворон. Он пользуется глубоким уважением среди разбойников всего Азерота.",al={"who leads ravenholdt","lord ravenholdt","manor owner","кто возглавляет черный ворон","лорд черный ворон","владелец поместья"}},{q="Почему Черный Ворон ненавидит Синдикат?",a="Обе организации ведут корни из разрушенных земель Альтерака. Пока изгнанные дворяне Синдиката прибегают к бандитизму и беззаконию в холмах, Черный Ворон действует в строгой дисциплине и активно срывает замыслы Синдиката.",al={"ravenholdt vs syndicate","syndicate feud","why fight syndicate","черный ворон против синдиката","вражда с синдикатом","зачем бороться с синдикатом"}},{q="Может ли любой посетить поместье?",a="Любой путник может войти на территорию, но стражи и убийцы, стоящие там, открыто враждебны к чужакам. Разбойники и доверенные агенты находят радушный прием и обширное обучение, остальных же ледяными предупреждениями гонят прочь.",al={"non-rogue in ravenholdt","are outsiders allowed in ravenholdt","не разбойник в черном вороне","пускают ли чужаков в черный ворон"}}},fp="16,328,26.687.0,30.623.0,34.259.0,26.187.0,39.256.0,27.259.0"}
P.entries["subzone:raynewood-retreat"] = {n="Приют в Ночных Лесах",s="Приют в Ночных Лесах — древний форпост ночных эльфов, раскинувшийся вокруг огромного великого древа на севере центральной части Ясеневого леса. Его охраняют дриады и защитники Кенария, и он служит бдительным убежищем, следящим за северными перевалами в сторону Оскверненного леса. Здесь также находится убежище хранителя Гордана, старшего сына Кенария, на которого нацелены зловещие внешние силы.",h="Приют в Ночных Лесах — древний форпост ночных эльфов, раскинувшийся вокруг огромного великого древа на севере...",kw={"ashenvale","braelyn","cenarius","felwood","laughing sister","ordanus","raynewood","retreat","ясеневый лес","брайлин","кенарий","оскверненный лес","смеющиеся сестры","гордан","ночные леса","приют"},ang={["class:Druid"]="Приют в Ночных Лесах — священная земля под опекой детей Кенария, служащая оплотом против демонической порчи и Скверны.",["faction:Horde"]="Для Орды приют — дружественная Альянсу роща, чьего стража, хранителя Гордана, тайные заказчики заданий намечают к устранению."},sec={{t="Оплот Великого Древа",b="Задолго до нынешних столкновений Альянса и Орды Приют в Ночных Лесах служил плацдармом для ночных эльфов-защитников во время древней войны сатиров, много тысячелетий назад. Сегодня лагерь сохраняет свое священное военное предназначение. Форпост расположен между лунным колодцем Шаэл'дрин и населенными сатирами руинами Ночной поляны, и его яростно охраняют защитники Кенария, волшебные драконы и Смеющиеся сестры. Их общая бдительность не спускает глаз с наступающей порчи, спускающейся из Оскверненного леса к северу отсюда."},{t="Охота на Гордана",b="Высоко в ветвях великого древа обитает хранитель Гордан, один из старших сыновей Кенария. Хотя крона дает ему убежище, она же стала центром темных интриг. Агенты, лояльные теневым остаткам Совета Теней, в частности Брайлин Огненная Длань, добиваются гибели хранителя. Наемников Орды посылают штурмовать высоты и добыть его голову, превращая то, что должно быть мирным лесным убежищем, в поле боя."}},faq={{q="Что такое Приют в Ночных Лесах?",a="Приют в Ночных Лесах — поселение ночных эльфов и Круга Кенария вокруг Великого Древа на севере центральной части Ясеневого леса. Это лояльное Альянсу убежище и сторожевой пост, наблюдающий за подступами к Оскверненному лесу.",al={"raynewood retreat","what is this place","raynewood tree","приют в ночных лесах","что это за место","древо приюта"}},{q="Кто живет в Приюте в Ночных Лесах?",a="Форпост защищают защитники Кенария, дриады, известные как Смеющиеся сестры, и волшебные драконы. Самый известный его обитатель — хранитель Гордан, живущий высоко в великом древе.",al={"who is here","raynewood mobs","who guards raynewood","кто здесь","существа приюта","кто охраняет приют"}},{q="Кто такой хранитель Гордан?",a="Хранитель Гордан — могущественный хранитель рощи и один из старших сыновей полубога Кенария. Он присматривает за убежищем, но сам оказался добычей враждебных лазутчиков.",al={"keeper ordanus","who is ordanus","ordanus lore","хранитель гордан","кто такой гордан","предания о гордане"}},{q="Почему Орда нападает на Приют в Ночных Лесах?",a="Брайлин Огненная Длань нанимает искателей приключений из Орды, чтобы они проникли в дерево и разыскали хранителя Гордана. Ее мотивы и союзы раскрываются в ходе задания.",al={"horde raynewood quest","why kill ordanus","braelyn firehand quest","задание орды приют","зачем убивать гордана","задание брайлин огненная длань"}},{q="Какова история этого места?",a="Почти десять тысяч лет назад, во время войны сатиров, военные ночных эльфов использовали Приют в Ночных Лесах как оперативную базу для борьбы с демоническими силами сатиров, угрожавшими Калимдору.",al={"raynewood history","war of the satyr raynewood","история приюта","война сатиров приют"}}},fp="17,353,25.538.0,20.442.1,26.206.0,31.187.0,22.176.0,44.149.0,34.189.0"}
P.entries["subzone:razor-hill"] = {n="Колючий Холм",s="Колючий Холм — главное поселение Орды в центральной части Дуротара, расположенное на стратегическом перекрестке между Долиной Испытаний, Степями и Оргриммаром. Он построен вокруг заметных укрепленных казарм и служит плацдармом и учебным центром для молодых воинов-орков и троллей, проверяющих себя в суровой глуши.",h="Колючий Холм — главное поселение Орды в центральной части Дуротара, расположенное на стратегическом...",kw={"barracks","burning blade","durotar","gar'thok","kul tiras","orgnil soulscar","razor hill","казармы","пылающий клинок","дуротар","га'ток","кул тирас","оргнил душегрыз","колючий холм"},ang={["faction:Horde"]="Как первый настоящий город на пути из тренировочных земель, Колючий Холм служит стартовой площадкой для молодых солдат Орды, доказывающих верность новой нации Тралла.",["race:Orc"]="Колючий Холм — свидетельство новой жизни, которую орки создали в Дуротаре, променяв демоническое рабство на прочные норы и тяжело давшееся выживание."},sec={{t="Сердце Дуротара",b="Колючий Холм построен в важном географическом узле и соединяет север Дуротара с прибрежными поселениями на юге и обширными равнинами Степей за рекой Строптивая. Поселение, в котором преобладают каменно-деревянные казармы и классические орочьи норы, было основано на раннем этапе создания Дуротара. Вскоре после Третьей войны люди из Кул Тираса заманили здесь Орду в засаду под видом встречи посланников, но нападение сорвалось, когда вместо Тралла пришел Рексар. Сегодня форпост полностью укреплен против новых вторжений с побережья."},{t="Дозор на границе",b="Под командованием опытных офицеров, таких как Га'Ток, Колючий Холм координирует местную оборону от нескольких нависших угроз. Остатки людей-морпехов все еще удерживают Крепость Тирагард на восточном побережье, а агрессивные племена свинобразов и гарпий досаждают местным путям снабжения. Гораздо коварнее присутствие культа Пылающего Клинка, чьи темные ритуалы и оскверненных агентов в ближних скалах пристально выслеживают и искореняют следователи вроде Оргнила Душегрыза."}},faq={{q="Какова роль Колючего Холма в Дуротаре?",a="Колючий Холм служит главным административным и оборонительным форпостом в центральной части Дуротара. Он связывает южные берега и Долину Испытаний с Оргриммаром на севере и Степями на западе, а также снабжает и обучает молодых искателей приключений.",al={"why is razor hill here","razor hill purpose","what is razor hill","зачем нужен колючий холм","назначение колючего холма","что такое колючий холм"}},{q="Что здесь произошло во время вторжения Кул Тираса?",a="После Третьей войны силы, лояльные Кул Тирасу, предложили вождю Траллу мирную встречу в Колючем Холме. Заподозрив предательство, защитник Рексар отправился вместо Тралла, раскрыл засаду и победил людей-убийц.",al={"kul tiras ambush","rexxar razor hill","what happened at razor hill summit","засада кул тираса","рексар колючий холм","что случилось на встрече в колючем холме"}},{q="Кто командует поселением?",a="Гарнизоном поселения командует орк-ветеран Га'Ток из городских казарм, руководя патрулями против остатков людей и местных диких зверей.",al={"razor hill leader","who runs razor hill","gar'thok","глава колючего холма","кто управляет колючим холмом","га'ток"}},{q="Чем занимается Пылающий Клинок возле Колючего Холма?",a="Темный демонический культ проник в скрытые скалы и каньоны вокруг центральной части Дуротара. Разведчики Орды под руководством Оргнила Душегрыза действуют из Колючего Холма, чтобы найти их шабаши и уничтожить их влияние.",al={"burning blade durotar","orgnil soulscar","cultists near razor hill","пылающий клинок дуротар","оргнил душегрыз","культисты возле колючего холма"}}},fp="10,337,16.588.0,21.469.0,40.259.0,49.233.0,28.164.0,48.210.0"}
P.entries["subzone:razor-hill-watchtower"] = {n="Сторожевая башня Колючего Холма",s="Эта прочная застава, стоящая на красных каменных утесах над Колючим Холмом, служит сторожевым постом раннего оповещения для сердца Дуротара. Фурл Хмурый Лоб бдительно следит за пыльными равнинами и побережьем, защищая селение внизу от надвигающихся угроз.",h="Эта прочная застава, стоящая на красных каменных утесах над Колючим Холмом, служит сторожевым постом раннего...",kw={"durotar","lookout","razor hill","razor hill watchtower","sentry","watchtower","дуротар","наблюдательный пункт","колючий холм","сторожевая башня колючего холма","часовой","сторожевая башня"},ang={["class:Hunter"]="Высокая точка обеспечивает беспрепятственный обзор окрестных скал, что идеально для наблюдателей, выслеживающих добычу и передвижения зверей по Дуротару.",["faction:Horde"]="Для молодых воинов и разведчиков, выходящих из Долины Испытаний, башня — ободряющий ориентир, говорящий о безопасности и силе молодой Орды."},sec={{t="Глаза над Дуротаром",b="Сторожевая башня Колючего Холма, построенная из толстых бревен и железного каркаса, охраняет селение Колючий Холм и окрестные каньоны. Дуротару непрестанно угрожают морпехи Кул Тираса на восточном берегу, налетчики-свинобразы в кустарниковых пустошах и культисты Пылающего Клинка, прячущиеся в ближних скалах. С возвышенной точки на гребне дозорный замечает приближающиеся боевые отряды, сигнальные дымы и вторжения задолго до того, как они достигнут ворот селения."}},faq={{q="Для чего нужна Сторожевая башня Колючего Холма?",a="Башня служит главным наблюдательным пунктом для Колючего Холма и центральной части Дуротара. Благодаря высоте разведчики следят за тропами, высматривают враждебных зверей и замечают передвижения войск из ближних лагерей Альянса или набеги кентавров.",al={"why is the watchtower here","watchtower purpose","razor hill tower","зачем здесь башня","назначение башни","башня колючего холма"}},{q="Кто охраняет башню?",a="Фурл Хмурый Лоб, пожилой орк, несет здесь дозор, высматривая захватчиков, и при необходимости трубит в сигнальный рог. Теперь, когда Дуротар стал более обжитым, он занялся изготовлением сумок для юных искателей приключений.",al={"who is at the tower","watchtower guards","кто на башне","стража башни"}},{q="Какие угрозы видны отсюда?",a="Разведчики в основном следят за агрессивными свинобразами из племен Иглогривых, лазутчиками-людьми из Крепости Тирагард на восточном побережье и дикими зверями, бродящими по сухим долинам.",al={"threats to razor hill","what are they looking for","угрозы колючему холму","что высматривают"}}},fp="21,275,17.485.0,49.259.0,26.186.0,38.184.0"}
P.entries["subzone:razorfen-downs"] = {n="Курганы Иглошкурых",s="Курганы Иглошкурых — древняя столица и священный погребальный лабиринт свинобразов, вырезанный глубоко в колоссальных зарослях терновника на границе южных Степей и Тысячи Игл. Некогда их священнейшее святилище, он попал под влияние нежити Плети и превратился в гниющий оплот некромантии.",h="Курганы Иглошкурых — древняя столица и священный погребальный лабиринт свинобразов, вырезанный глубоко в...",kw={"agamaggan","amnennar","coldbringer","death speaker blackthorn","death's head","downs","quilboar","razorfen downs","scourge","агамагган","амненнар","хладовестник","вестник смерти терновник","мертвая голова","курганы","свинобраз","курганы иглошкурых","плеть"},ang={["faction:Horde"]="Свинобразы — вечная заноза для Перекрестка, но форпост Короля-лича на самом краю Степей — угроза самому существованию, которую Орда не может позволить себе игнорировать.",["race:Undead"]="Для Отрекшихся обнаружение лича Плети, тайно действующего в Калимдоре, — леденящее напоминание о господине, против которого они восстали, и повод для скорого и решительного искоренения."},sec={{t="Оскверненный священный город",b="Курганы Иглошкурых, издавна почитаемые как древняя столица и место погребения свинобразов, лежат среди колоссальных окаменевших зарослей, выросших из павшего полубога Агамаггана. Согласно легенде, арочный вход был вырезан прямо из пасти Великого Вепря. Веками верховные жрецы племени Мертвой Головы ухаживали за этими глубокими извилистыми норами и чтили своих почитаемых мертвецов. Но несмотря на священный статус среди свинобразов, лабиринт из костей и терний недавно постигла катастрофа куда более мрачная, чем любые споры из-за воды в Степях."},{t="Плеть приходит в Калимдор",b="После разрушений Третьей войны щупальца нежити из Плети бесшумно дотянулись до южного Калимдора. Под предводительством ледяного лича Амненнара Хладовестника агенты смерти проникли в лабиринт из терний и подчинили жречество Мертвой Головы. Вместо того чтобы почитать предков, свинобразы теперь укрывают в своих священных загонах гниющих вурдалаков, скелетов и некромантов. Порча угрожает расползтись по Степям, превратив самую святую землю свинобразов в плацдарм для замыслов Плети на западе."}},faq={{q="Что такое Курганы Иглошкурых?",a="Курганы Иглошкурых — древняя столица и место погребения свинобразов. Выросшие из огромных терновых зарослей, образованных павшим Древним Агамагганом, они служат духовным сердцем культуры свинобразов и штаб-квартирой их верховного жречества — племени Мертвой Головы.",al={"what is the downs","razorfen downs lore","who lives in razorfen downs","что такое курганы","предания курганов иглошкурых","кто живет в курганах иглошкурых"}},{q="Почему Плеть находится в Курганах Иглошкурых?",a="Лич Амненнар Хладовестник прибыл после Третьей войны, чтобы создать в Калимдоре оплот для Короля-лича. Осквернив жречество Мертвой Головы и подняв мертвых свинобразов, Амненнар превратил лабиринтный город из терний в скрытое гнездо некромантической силы.",al={"why are there undead in razorfen downs","amnennar razorfen downs","scourge in razorfen","почему в курганах иглошкурых нежить","амненнар курганы иглошкурых","плеть в иглошкурых"}},{q="Чем Курганы Иглошкурых отличаются от Лабиринтов Иглошкурых?",a="Лабиринты Иглошкурых — главный военный оплот и живое логово свинобразов, которым напрямую правит старуха Чарлга Остробок. Курганы же — их традиционная столица и священное место погребения, расположенное глубже к югу, которое попало под влияние некромантии и власть Плети.",al={"difference between kraul and downs","downs vs kraul","kraul or downs","разница между лабиринтами и курганами","курганы или лабиринты","лабиринты или курганы"}},{q="Где находится вход?",a="Курганы расположены на самой южной границе Степей, над великим обрывом в Тысячу Игл. Вход — естественная арочная расселина среди высоких спутанных зарослей, которая, по преданию, вырезана из разверстой пасти Агамаггана.",al={"downs entrance","where is razorfen downs","how to get into razorfen downs","вход в курганы","где курганы иглошкурых","как попасть в курганы иглошкурых"}}},fp="14,311,23.565.0,28.557.1,23.288.0,41.273.0,51.288.0,30.259.0"}
P.entries["subzone:razorfen-downs-classic"] = {n="Курганы Иглошкурых (Classic)",s="Курганы Иглошкурых — древнее место захоронений и традиционная столица свинобразов, скрытая в гигантских колючих зарослях на юге Степей. Недавно агенты Плети во главе с личем Амненаром Хладоносцем захватили лабиринт, поднимая мертвых свинобразов и угрожая распространить свою власть на весь центральный Калимдор.",h="Курганы Иглошкурых — древнее место захоронений и традиционная столица свинобразов, скрытая в гигантских...",kw={"agamaggan","amnennar","barrens","death's head","quilboar","razorfen downs","rfd","scourge","агамагган","амненар","степи","мертвая голова","свинобраз","курганы иглошкурых","плеть"},ang={["faction:Horde"]="Цитадель Плети прямо у южной границы Степей представляет непосредственную угрозу сердцу земель Орды и ее путям снабжения.",["race:Undead"]="Королевское фармацевтическое общество и руководство Отрекшихся в Подгороде проявляют живой интерес к изучению и уничтожению соперничающей некромантской магии, расцветающей в Курганах."},sec={{t="Столица шипов",b="Курганы Иглошкурых выросли из тех же исполинских окаменевших лоз, что и соседние Лабиринты Иглошкурых, и находятся там, где во время Войны Древних пал древний кабан-полубог Агамагган. На протяжении поколений этот лабиринт шипов служил священным некрополем и средоточием власти свинобразов, а его бдительно охраняли мистики племени Мертвой Головы. Для свинобразов густые заросли — священная земля, пропитанная кровью их божественного прародителя."},{t="Оплот Плети в Калимдоре",b="Святость Курганов была нарушена, когда агенты Плети проникли в заросли. Амненар Хладоносец, могущественный лич на службе Короля-лича, подчинил местных свинобразов племени Мертвой Головы и превратил земли предков в оплот нежити. Поднятые скелеты, бредущие трупы и воющие банши теперь бродят по Спирали Шипов. И Орда в соседних Степях, и посланники Собора Света в Штормграде видят в этом растущем очаге власти Плети серьезную угрозу для всего континента."}},faq={{q="Что такое Курганы Иглошкурых?",a="Курганы Иглошкурых — древняя столица и некрополь народа свинобразов, вырезанные в огромных зарослях колючек на юге Степей. Недавно они оказались под властью Плети.",al={"what is rfd","razorfen downs lore","downs background","что такое курганы иглошкурых","история курганов иглошкурых","предыстория курганов"}},{q="Почему в городе свинобразов есть нежить?",a="Лич Плети по имени Амненар Хладоносец вторгся в Курганы, подчинил местное племя Мертвой Головы и поднял мертвых свинобразов, чтобы создать плацдарм нежити в Калимдоре.",al={"why scourge in downs","why undead in barrens","who brought the scourge here","почему плеть в курганах","почему нежить в степях","кто привел плеть"}},{q="Чем Курганы Иглошкурых отличаются от Лабиринтов Иглошкурых?",a="Оба подземелья вырезаны в зарослях Агамаггана, но Лабиринты Иглошкурых — это оплот живых свинобразов под предводительством Чарлги Остробок. Курганы Иглошкурых — их древнее место захоронений, которое сейчас захвачено Плетью.",al={"downs vs kraul","rfk vs rfd","difference between downs and kraul","курганы или лабиринты","курганы иглошкурых против лабиринтов","разница между курганами и лабиринтами"}},{q="Кто правит Курганами Иглошкурых сейчас?",a="Амненар Хладоносец, лич Плети, управляет оплотом из глубин Спирали Шипов.",al={"rfd final boss","who leads razorfen downs","boss of downs","последний босс курганов","кто правит курганами иглошкурых","босс курганов"}}},fp="24,367,17.436.0,29.535.0,23.185.0,44.173.0,65.226.0,35.111.0"}
P.entries["subzone:razorfen-kraul-classic"] = {n="Лабиринты Иглошкурых (Classic)",s="Лабиринты Иглошкурых — древняя родина свинобразов, вырезанная глубоко в колоссальных шипах, выросших из крови павшего кабана-полубога Агамаггана. Этим укрепленным лабиринтом правит безжалостная старуха Чарлга Остробок, и он служит плацдармом для кровавых набегов на юг Степей.",h="Лабиринты Иглошкурых — древняя родина свинобразов, вырезанная глубоко в колоссальных шипах, выросших из крови...",kw={"agamaggan","agathelos","barrens","charlga razorflank","quilboar","ramtusk","razorfen kraul","rfk","scourge","агамагган","агатилос","степи","чарлга остробок","свинобраз","рамтуск","лабиринты иглошкурых","плеть"},ang={["faction:Horde"]="Агрессивные набеги Чарлги Остробок напрямую угрожают южным поселениям и торговым путям, поэтому усмирение Лабиринтов — неотложная задача безопасности для Орды.",["race:Tauren"]="Охотники и шаманы тауренов издавна враждуют со свинобразами, а слухи о нечестивой порче Плети, пускающей корни в почитаемой земле Агамаггана, требуют их скорого вмешательства."},sec={{t="Кровь бога-кабана",b="Десять тысяч лет назад, во время Войны Древних, колоссальный кабан-полубог Агамагган погиб в битве с Пылающим Легионом, спасая Азерот. Повсюду, где его священная кровь впитывалась в почву южного Калимдора, из земли вырастали огромные непроходимые колючие лозы. Свинобразы, считавшие себя смертными потомками Великого Кабана, собрались в этих густых зарослях, чтобы жить там и чтить его жертву. Плотное переплетение, известное как Лабиринты Иглошкурых, — их самый почитаемый оплот, полный воинов-свинобразов, укротителей зверей и шаманов, повелевающих землей."},{t="Амбиции старухи",b="Власть над Лабиринтами перешла к стареющей геомантке Чарлге Остробок. При ее железной власти племя Иглошкурых ведет беспощадную войну как с соперничающими бандами свинобразов, так и с ближайшими лагерями Орды. Но куда тревожнее обычных набегов за земли сообщения бдительных разведчиков о фигурах нежити, замеченных среди колючих зарослей. Ходят слухи, что Чарлга начала торговаться с агентами Плети, подвергая опасности не только Степи, но и грозя открыть мрачный плацдарм нежизни в Калимдоре."}},faq={{q="Что породило гигантские шипы вокруг Лабиринтов Иглошкурых?",a="Согласно легенде, колоссальные колючие лозы проросли везде, где кровь кабана-полубога Агамаггана упала на землю во время Войны Древних десять тысяч лет назад.",al={"why are there thorns here","giant thorn vines barrens","agamaggan thorns lore","почему здесь шипы","гигантские колючие лозы степи","шипы агамаггана"}},{q="Кто правит Лабиринтами Иглошкурых?",a="Лабиринтами Иглошкурых управляет Чарлга Остробок, безжалостная старуха-свинобраз и геомантка, направляющая набеги на соседние племена и поселения.",al={"razorfen kraul leader","who leads the kraul","charlga razorflank","предводитель лабиринтов иглошкурых","кто правит лабиринтами","чарлга остробок"}},{q="Почему рядом с Лабиринтами есть нежить?",a="По слухам, Чарлга Остробок вступила в тайные переговоры с агентами Плети, стремясь к нечестивому союзу, который принес бы силу нежизни в стан свинобразов.",al={"scourge in razorfen","undead quilboar","why scourge barrens","плеть в иглошкурых","нежить свинобразы","почему плеть в степях"}},{q="Где находятся Лабиринты Иглошкурых?",a="Лабиринты Иглошкурых расположены в самой южной части Степей, на западной стороне колоссальных колючих зарослей, чуть севернее Великого Подъемника.",al={"where is rfk","rfk entrance","razorfen kraul location","где лабиринты иглошкурых","вход в лабиринты иглошкурых","расположение лабиринтов иглошкурых"}}},fp="24,306,21.566.0,20.529.1,52.176.0,25.152.0,36.179.1,32.159.0"}
P.entries["subzone:razormane-grounds"] = {n="Земли Иглогривых",s="Земли Иглогривых — передовой лагерь свинобразов-Иглогривых, продвигающихся на восток из Степей в центральный Дуротар. Это ощетинившееся поселение, заросшее острыми колючками и усеянное освежеванными тушами дичи, — передовая в нескончаемой борьбе свинобразов с орками Оргриммара.",h="Земли Иглогривых — передовой лагерь свинобразов-Иглогривых, продвигающихся на восток из Степей в центральный...",kw={"captain flat tusk","durotar","geolord mottle","quilboar","raggaran","razormane","razormane grounds","капитан плоский бивень","дуротар","геолорд пестрый","свинобраз","раггаран","иглогривые","земли иглогривых"},ang={["faction:Horde"]="Подавление Земель Иглогривых жизненно важно для безопасности путей и линий снабжения между Степями и столицей Орды — Оргриммаром.",["race:Orc"]="Для орков Дуротара Земли Иглогривых — постоянная угроза в самом сердце их новой родины, и молодым воинам приходится доказывать доблесть, истребляя свинобразов."},sec={{t="Заноза в боку Дуротара",b="Земли Иглогривых раскинулись под красными скалами центрального Дуротара и отмечают самый восточный предел расширения свинобразов из Степей. Лагерь, затерянный в густых зарослях и окруженный выбеленными костями, постоянно угрожает путникам вдоль Реки Строптивой. Его возглавляют такие предводители, как капитан Плоский Бивень из Боевой стражи и геолорд Пестрый, организующие набеги на соседние поселения орков и проходящие обозы. Несмотря на регулярные патрули из Колючего Холма и ближайших застав, Иглогривые неутомимо пополняют свои ряды, вырастая из колючек быстрее, чем Орда успевает их расчищать."}},faq={{q="Что такое Земли Иглогривых?",a="Это укрепленный лагерь свинобразов в центральном Дуротаре, служащий передовой базой племени Иглогривых, которое расширяется на восток из Степей.",al={"razormane grounds","quilboar camp durotar","where are razormane","земли иглогривых","лагерь свинобразов дуротар","где иглогривые"}},{q="Почему свинобразы нападают на Дуротар?",a="Свинобразы-Иглогривые считают все соседние земли по праву своими и стремятся расширить свои колючие заросли и охотничьи угодья за счет новых поселений Орды.",al={"why quilboar attack","why are razormane here","quilboar invasion","почему свинобразы нападают","почему здесь иглогривые","вторжение свинобразов"}},{q="Кто возглавляет свинобразов в Землях Иглогривых?",a="Лагерем командует капитан Плоский Бивень, предводитель Боевой стражи Иглогривых, вместе с геомантом, повелевающим землей, геолордом Пестрым.",al={"razormane bosses","who leads the razormane grounds","captain flat tusk","предводители иглогривых","кто возглавляет земли иглогривых","капитан плоский бивень"}},{q="Почему вокруг лагеря так много костей?",a="Иглогривые — агрессивные падальщики и охотники: они обдирают местных животных до костей, чтобы прокормить своих налетчиков, а туши оставляют, отмечая свою территорию.",al={"bones in camp","razormane animal carcasses","why dead animals","кости в лагере","туши животных иглогривых","почему мертвые животные"}}},fp="17,305,25.653.0,30.148.0,39.180.0,48.140.0,44.174.0"}
P.entries["subzone:razorwind-canyon"] = {n="Каньон Колючего Ветра",s="Каньон Колючего Ветра — извилистая скалистая лощина, пересекающая главную дорогу между Колючим Холмом и Оргриммаром. Каньон заражен агрессивными гарпиями Пыльного Ветра и представляет постоянную опасность для путников, идущих на север к столице Орды.",h="Каньон Колючего Ветра — извилистая скалистая лощина, пересекающая главную дорогу между Колючим Холмом и...",kw={"drygulch ravine","durotar","dustwind harpies","razor hill","razorwind canyon","tor'kren farm","сухая лощина","дуротар","гарпии пыльного ветра","колючий холм","каньон колючего ветра","ферма тор'кренов"},ang={["faction:Horde"]="Изгнание гарпий Пыльного Ветра из Каньона Колючего Ветра жизненно важно для безопасности главного тракта между Колючим Холмом и столицей Оргриммаром для курьеров и новобранцев.",["race:Orc"]="Гарпии, гнездящиеся прямо вдоль центральной дороги Дуротара, — оскорбление безопасности родины орков, и молодым воинам приходится сокращать их число."},sec={{t="Угроза на большой дороге",b="Каньон Колючего Ветра тянется вдоль центральной артерии, соединяющей Колючий Холм с Оргриммаром, и прорезает тропы как в восточные утесы, так и в западные заросли кустарника в сторону Фермы Тор'кренов. Каньон — место гнездовий гарпий Пыльного Ветра, территориальных существ, без колебаний нападающих на путников, подошедших слишком близко к их насестам. Их близость к торговым путям столицы делает зачистку этих оврагов постоянной необходимостью для защитников Дуротара."},{t="Проходы и лощины",b="Помимо того что извилины Каньона Колючего Ветра служат гнездами гарпий, они образуют скрытые пути через красные скалистые холмы Дуротара. Восточное ответвление глубоко уходит в скалы и ведет через пещеру в Сухую лощину. Поскольку гарпии гнездятся на высоких уступах и спускаются стаями, неосторожные путешественники на этих тропах легко могут оказаться окруженными и убитыми."}},faq={{q="Где находится Каньон Колючего Ветра?",a="Каньон Колючего Ветра находится в центральном Дуротаре и тянется по обе стороны главной дороги между Колючим Холмом и Оргриммаром. Входы в него расположены к северу от Колючего Холма, рядом с Фермой Тор'кренов, а также через пещеру, соединяющуюся с Сухой лощиной.",al={"razorwind canyon location","where is razorwind canyon","how to find razorwind canyon","где каньон колючего ветра","расположение каньона колючего ветра","как найти каньон колючего ветра"}},{q="Какие существа обитают в Каньоне Колючего Ветра?",a="Каньон густо населен гарпиями Пыльного Ветра. Эти агрессивные пернатые существа гнездятся большими выводками по всем оврагам и скальным выступам и охотятся на неосторожных путников.",al={"razorwind mobs","what lives in razorwind canyon","harpy canyon durotar","существа каньона колючего ветра","кто живет в каньоне колючего ветра","гарпии дуротар"}},{q="Почему Орда обеспокоена этим каньоном?",a="Каньон Колючего Ветра граничит с главным торговым и транспортным путем между Колючим Холмом и Оргриммаром. Гнездящиеся гарпии часто нападают на курьеров, торговые караваны и путников на центральной дороге.",al={"why care about razorwind","orgrimmar threat razorwind","почему важен каньон колючего ветра","угроза оргриммару"}},{q="Соединяется ли Каньон Колючего Ветра с другими местами?",a="Да. Помимо выхода на главную дорогу, из каньона ведут тропы на запад к Ферме Тор'кренов, а также восточная пещера, ведущая в Сухую лощину.",al={"canyon connections","where does razorwind lead","связи каньона","куда ведет каньон колючего ветра"}}},fp="16,239,25.462.0,20.394.0,34.240.0,40.189.0,45.204.0,45.160.0"}
P.entries["subzone:rebel-camp"] = {n="Лагерь Повстанцев",s="Лагерь Повстанцев, укрытый неподалеку от дороги на севере Тернистой долины, служит укрепленным убежищем для солдат Альянса, порвавших с Полковником Курценом. Под началом лейтенанта Дорена эти бойцы отказались сдаваться безумию, охватившему экспедицию их командира, и теперь борются за выживание и стремятся остановить его скатывание в тиранию.",h="Лагерь Повстанцев, укрытый неподалеку от дороги на севере Тернистой долины, служит укрепленным убежищем для...",kw={"colonel kurzen","doren","kurzen","kurzen's compound","mai'zoth","rebel camp","stranglethorn","stranglethorn vale","полковник курцен","дорен","курцен","лагерь курцена","май'зот","лагерь повстанцев","тернистая долина"},ang={["faction:Alliance"]="Лагерь Повстанцев — ваш главный плацдарм и самое безопасное убежище при переходе на юг по мосту из Сумеречного леса в Тернистую долину.",["race:Human"]="Видеть, как собратья-солдаты Штормграда сходят с ума в джунглях, тяжело, и лейтенанту Дорену отчаянно нужны подданные королевства, чтобы покончить с опозорившимся отрядом Курцена."},sec={{t="Противостояние безумию",b="Когда экспедиция Полковника Курцена по поручению Штормграда углубилась в джунгли Тернистой долины, все быстро пошло прахом. Пораженные темной магией джунглей и проклятием огра-мага Май'Зота, Полковник и его ближайшие приспешники впали в безумие, взбунтовались и начали терроризировать окрестности. Горстка здравомыслящих солдат во главе с лейтенантом Дореном отказалась участвовать в зверствах. Покинув Лагерь Курцена, они основали на севере этот скрытый лагерь, чтобы вести отчаянную партизанскую войну против бывших товарищей."},{t="Удержать рубеж",b="Лагерь Повстанцев, опасно расположенный у границы Сумеречного леса, постоянно находится под угрозой. Отрезанный от обычной помощи Штормграда, Дорен полагается на тайные поставки и оборонительное вооружение, включая гоблинскую взрывчатку, полученную через Пиратскую бухту, чтобы удерживать периметр от рейдов людей Курцена. Для путников Альянса, отправляющихся на юг в дикие джунгли, лагерь становится важным первым оплотом здравого смысла."}},faq={{q="Кто такие повстанцы в Лагере Повстанцев?",a="Это бывшие солдаты Штормграда, входившие в экспедицию Полковника Курцена в Тернистую долину. Когда Курцен и его ближний круг впали в безумие и тиранию, лейтенант Дорен поднял этот отряд на мятеж, чтобы спастись и противостоять им.",al={"who lives at rebel camp","who are these soldiers","rebel camp alliance","кто живет в лагере повстанцев","кто эти солдаты","лагерь повстанцев альянс"}},{q="Почему он называется Лагерем Повстанцев, если они верны Штормграду?",a="Повстанцами их считают только по отношению к командованию Полковника Курцена. Курцен был их командиром, поэтому неповиновение его приказам формально было мятежом, хотя они остаются верны Альянсу и Штормграду.",al={"why rebel camp","are they traitors","who did they rebel against","почему лагерь повстанцев","они предатели","против кого они восстали"}},{q="Как лагерь выживает без официальной поддержки Штормграда?",a="Действуя вдали от официальных линий снабжения, лейтенант Дорен опирается на находчивые неофициальные связи, в том числе торговлю с такими людьми, как Кразек из Пиратской бухты, который поставляет мины и необходимое снаряжение для укрепления обороны лагеря.",al={"rebel camp supplies","where do they get food","rebel camp logistics","снабжение лагеря повстанцев","где они берут еду","логистика лагеря повстанцев"}},{q="Где находится Полковник Курцен?",a="Курцен и его обезумевшие последователи занимают Лагерь Курцена, укрепленную базу к юго-востоку от Лагеря Повстанцев.",al={"kurzen location","where is kurzen","kurzens compound","местонахождение курцена","где курцен","лагерь курцена"}}},fp="10,330,23.565.0,16.424.0,37.239.0,63.219.0,61.238.0,32.123.0"}
P.entries["subzone:red-rocks"] = {n="Красные скалы",s="Красные скалы — высокий песчаниковый утес на северо-востоке Мулгора, священное место захоронения предков тауренов. Здесь павших героев через очищающее пламя вверяют Матери-Земле, а молодые воины поднимаются на его тихие вершины, чтобы обрести мудрость предков.",h="Красные скалы — высокий песчаниковый утес на северо-востоке Мулгора, священное место захоронения предков...",kw={"bristleback","burial ground","earth mother","mulgore","quilboar","red rocks","rite of wisdom","thunder bluff","дыбогрив","место захоронения","мать-земля","мулгор","свинобраз","красные скалы","обряд мудрости","громовой утес"},ang={["class:Shaman"]="Ветер несет скорбь неупокоенных духов, потревоженных осквернением свинобразов, и взывает к обрядам шаманов, чтобы восстановить равновесие стихий и покой предков.",["race:Tauren"]="Для вашего народа Красные скалы — священная земля. Мерзкие свинобразы, роющиеся среди погребальных костров ваших почитаемых предков, — открытое оскорбление, требующее очищения."},sec={{t="Священные камни и погребальные костры предков",b="Багровые скалы Красных скал, возвышающиеся над равнинами северо-восточного Мулгора, отмечают священный порог между миром живых и загробным миром. Традиции тауренов отводят эту торжественную землю самым доблестным героям — вождям, защитникам и воинам, отдавшим жизнь за основание и защиту Громового Утеса. Их останки предают небу и земле на обрядовых кострах, возвращая их души Матери-Земле и Отцу-Небу. Это также место духовного начала: здесь молодые таурены завершают обряды посвящения, чтя могилы предков и общаясь с ветром."},{t="Осквернение свинобразами",b="Вечный покой Красных скал нарушили свинобразы Дыбогривы. Выбираясь из своих логов, эти агрессивные падальщики заполонили песчаниковые уступы и осквернили погребальные костры предков грязью. Это глубоко оскорбляет духовные традиции Громового Утеса. Шаманы и хранители преданий теперь призывают помощь, чтобы очистить скалы, изгнать Дыбогривов и вернуть святость покою усопших."}},faq={{q="Для чего нужны Красные скалы?",a="Красные скалы — главное место захоронения предков и обрядов тауренов Мулгора. Павших героев и почитаемых воинов здесь кремируют, чтобы вернуть их души Матери-Земле, а молодые таурены поднимаются на его вершины, чтобы почтить мертвых во время испытаний взросления.",al={"why is red rocks important","red rocks purpose","what happens at red rocks","почему важны красные скалы","назначение красных скал","что происходит на красных скалах"}},{q="Почему на Красных скалах есть свинобразы?",a="Свинобразы Дыбогривы выбрались из своих колючих нор и захватили плато, осквернив погребальные курганы. Таурены считают их вторжение невыносимым святотатством против покоящихся душ предков.",al={"quilboar at red rocks","who is invading red rocks","why are bristlebacks here","свинобразы на красных скалах","кто вторгся на красные скалы","почему здесь дыбогривы"}},{q="Кто похоронен на Красных скалах?",a="Погребение на Красных скалах — честь, доступная лишь самым доблестным тауренам, включая великих воинов, сражавшихся бок о бок с Кэрном Кровавым Копытом, чтобы защитить Мулгор и построить Громовой Утес, а также героев, погибших на службе своим племенам.",al={"who is cremated here","red rocks dead","whose graves are these","кто здесь кремирован","мертвые красных скал","чьи это могилы"}},{q="Какие обряды здесь проводятся?",a="Помимо погребальных костров, вверяемых Матери-Земле и Отцу-Небу, утес — центр Обряда мудрости, где таурены-воины оставляют дары и прислушиваются к наставлениям духов предков в ветре.",al={"rites at red rocks","tauren rituals red rocks","обряды на красных скалах","ритуалы тауренов красные скалы"}}},fp="9,293,35.621.0,24.440.0,33.290.0,36.229.0,27.224.0,35.216.0"}
P.entries["subzone:refuge-pointe"] = {n="Опорный пункт",s="Опорный пункт — главный оплот Альянса и уцелевших остатков Стромгарда на Нагорье Арати. Расположенный в центре на торговой дороге нагорья, он служит плацдармом для возвращения разрушенной столицы, Крепости Стромгард, и сдерживания враждебных сил в регионе.",h="Опорный пункт — главный оплот Альянса и уцелевших остатков Стромгарда на Нагорье Арати.",kw={"arathi highlands","arathor","captain nials","league of arathor","refuge pointe","stromgarde","thandol span","нагорье арати","аратор","капитан ниалс","лига аратора","опорный пункт","стромгард","мост тандола"},ang={["faction:Alliance"]="Опорный пункт — ваше единственное военное убежище и узел полетов на Нагорье Арати, дающий важную передышку на опасной территории, за которую борются огры, Синдикат и Орда.",["race:Human"]="Для людей Опорный пункт — трогательное напоминание о былом величии Стромгарда как военного сердца человечества, где стойкие защитники отказываются покидать родину, несмотря на подавляющий перевес врагов."},sec={{t="Бастион остатков Стромгарда",b="После разорения Третьей войны и катастрофического падения Крепости Стромгард большая часть уцелевших жителей Стромгарда бежала на юг, в более дружелюбные земли. Оставшиеся образовали стойкий авангард, окопавшись в Опорном пункте под началом капитана Ниалс. Лагерь, состоящий из закаленных в боях солдат Стромгарда, сил Лиги Аратора и вспомогательных специалистов Альянса, — последний организованный оплот королевства на родной земле."},{t="На пределе сил",b="Опорный пункт постоянно на грани разгрома. Зажатый между Отрекшимися и Ордой из Павшего Молота, троллями Сухокожими, разбойниками Синдиката и ограми Тяжелого Кулака, гарнизон не имеет ни единого лишнего бойца. Когда дворфийские командиры на разрушенном Мосту Тандола отчаянно попросили подкреплений для борьбы с кланом Черного Железа, капитану Ниалс пришлось отказать. Каждый меч, щит и крупица припасов в Опорном пункте должны служить защите нагорья и подготовке контрнаступления для возвращения Крепости Стромгард."}},faq={{q="Почему здесь так мало сил Альянса?",a="Королевство Стромгард лежит в руинах после Третьей войны, и большинство уцелевших мирных жителей эвакуировалось на юг. Войска в Опорном пункте — измотанные остатки стромгардской армии, усиленные экспедиционным отрядом Альянса. Из-за скудных припасов и врагов со всех сторон они едва удерживают свой укрепленный лагерь.",al={"why is refuge pointe small","why so few soldiers","alliance numbers arathi","почему мал опорный пункт","почему так мало солдат","силы альянса нагорье арати"}},{q="Почему Опорный пункт не посылает солдат на помощь Мосту Тандола?",a="Когда дворфийские посланники прибыли с просьбой о войсках для защиты Дун Модра и Моста Тандола от нападений Черного Железа, капитану Ниалс пришлось отказать. Когда Крепость Стромгард захвачена, а вокруг враги, долг и выживание требуют, чтобы каждый солдат оставался удерживать нагорье и готовиться вернуть павшую столицу.",al={"why no help dun modr","captain nials thandol span","plea to the alliance quest","почему нет помощи дун модру","капитан ниалс мост тандола","задание мольба к альянсу"}},{q="Кто командует лагерем?",a="Гарнизоном Опорного пункта командует капитан Ниалс. Она руководит военными операциями Стромгарда на нагорье, координируя разведку, стычки с Синдикатом и ограми и оборонительные патрули вдоль главной дороги.",al={"refuge pointe leader","who is in charge here","captain nials","командир опорного пункта","кто здесь главный","капитан ниалс"}},{q="Что такое Лига Аратора?",a="Лига Аратора — коалиция Альянса, стремящаяся вернуть Нагорье Арати и обеспечить важные ресурсы в соседней Низине Арати. Действуя вместе с остатками сил Стромгарда в Опорном пункте, ее бойцы не дают Осквернителям под предводительством Отрекшихся завладеть плодородной долиной.",al={"league of arathor","who are league of arathor","arathi basin alliance","лига аратора","кто такая лига аратора","низина арати альянс"}}},fp="13,302,35.464.0,22.557.0,43.337.0,66.329.0,22.238.0,30.295.0"}
P.entries["subzone:remtravel-s-excavation"] = {n="Раскопки рассеянного геолога",s="Раскопки рассеянного геолога — археологические раскопки на юге Темных берегов. Основанная дворфом Геологом Сомнамбулером экспедиция недавно наткнулась на древние подземные руины и невольно пробудила враждебных троггов и каменных големов, которые быстро захватили карьер.",h="Раскопки рассеянного геолога — археологические раскопки на юге Темных берегов.",kw={"darkshore","excavation","fossil","golem","gravelflint","prospector","remtravel","trogg","темные берега","раскопки","окаменелость","голем","кремнегрив","геолог","сомнамбулер","трогг"},ang={["race:Dwarf"]="Дворфы-исследователи из Лиги исследователей известны поисками тайн прошлого, хотя раскопки опасных троггов в чужих землях часто приводят к привычным неприятностям.",["race:NightElf"]="Кальдораи обычно с недоверием наблюдают за глубокими раскопками дворфов Альянса, особенно когда неосторожные копатели пробуждают диких троггов на древней земле Темных берегов."},sec={{t="Захваченный карьер",b="Геолог Сомнамбулер прибыл на Темные берега в поисках реликвий далекого прошлого и устроил масштабные раскопки вдали от безопасного Аубердина. Копая древние пласты, его команда обнаружила полчища подземных троггов Кремнегривов и громадных каменных големов, погребенных в земле. Место мгновенно превратилось из научного карьера в опасную зону, рабочие разбежались, а Сомнамбулер бросился спасать свои самые ценные находки."},{t="Пропавшая окаменелость",b="До того как раскопки погрузились в хаос, Сомнамбулер нашел редкую окаменелость с любопытными мистическими свойствами. В панике при натиске троггов, да еще из-за своей известной рассеянности, геолог потерял ценную реликвию среди обширных земляных котлованов. Чтобы вернуть ее, придется спуститься в раскоп и встретиться и с жестокими троггами, и с древними автоматами, пробужденными кирками."}},faq={{q="Что такое Раскопки рассеянного геолога?",a="Это археологические раскопки на юге Темных берегов, основанные Геологом Сомнамбулером, исследователем, ищущим древние окаменелости и подземные реликвии.",al={"what is this place","darkshore dig site","remtravel site","что это за место","раскопки на темных берегах","раскопки сомнамбулера"}},{q="Почему здесь есть трогги?",a="Дворфийские шахтеры слишком глубоко зарылись в землю и вскрыли подземные пещеры, пробудив местное племя троггов Кремнегривов вместе со спящими каменными големами.",al={"why troggs in darkshore","gravelflint troggs","where did troggs come from","трогги на темных берегах","трогги кремнегривы","откуда взялись трогги"}},{q="Кто такой Геолог Сомнамбулер?",a="Это дворф-археолог, возглавляющий раскопки. Известный острым глазом на артефакты и рассеянностью, он потерял ключевую окаменелость, когда на раскопки напали.",al={"who is remtravel","prospector remtravel lore","кто такой сомнамбулер","геолог сомнамбулер предания"}},{q="Какую реликвию здесь обнаружили?",a="Сомнамбулер нашел необычную окаменелость со странными мистическими свойствами незадолго до того, как трогги хлынули из глубин.",al={"what did they find","remtravel fossil","mystic fossil","что они нашли","окаменелость сомнамбулера","мистическая окаменелость"}}},fp="22,296,16.470.0,18.413.1,31.154.0,26.167.0,28.184.0,39.133.0"}
P.entries["subzone:render-s-rock"] = {n="Скала Ренда",s="Скала Ренда — укрепленная пещера в северо-западных скалах Красногорья, неподалеку от высокого перевала, ведущего в Пылающие степи. Ею владеют свирепые орки клана Черной горы: это передовой оплот и действующая стоянка для набегов на долины внизу.",h="Скала Ренда — укрепленная пещера в северо-западных скалах Красногорья, неподалеку от высокого перевала...",kw={"blackrock orcs","burning steppes","corporal keeshan","keeshan","redridge","render's rock","renders rock","орки черной горы","пылающие степи","капрал кеешан","кеешан","красногорье","скала ренда"},ang={["faction:Alliance"]="Для бойцов Альянса Скала Ренда — одна из самых укрепленных позиций Черной горы в Красногорье, и ее зачистка жизненно важна для освобождения капрала Кеешана и защиты Приозерья."},sec={{t="Оплот Черной горы на высотах",b="Скала Ренда, высеченная в неприступных высотах к северу от Приозерья, служит укрепленной системой пещер для вторгшегося клана Черной горы. Из этого защищенного оплота у перевала в Пылающие степи опытные орки Черной горы организуют нападения на местных защитников Красногорья. Ее темные глубины строго охраняются, и любая вылазка внутрь опасна для тех, кто хочет нарушить орочье снабжение или освободить пленных, захваченных в ходе затянувшегося конфликта."},{t="Заложник во тьме",b="Помимо стратегической ценности для орков, Скала Ренда мрачно значима для защитников Приозерья. В ее глубинах в плену удерживают раненого красногорского солдата — капрала Кеешана. Находясь глубоко в тылу врага, вдали от товарищей, Кеешан своим пленом показывает и дерзость вторжений Черной горы, и высокую цену, которую заплатил местный гарнизон, стараясь сохранить горную дорогу открытой."}},faq={{q="Где находится Скала Ренда?",a="Скала Ренда расположена в самых северо-западных пиках Красногорья, неподалеку от тропы, ведущей на север, в Пылающие степи.",al={"renders rock location","where is renders rock","find renders rock","скала ренда где находится","где скала ренда","найти скалу ренда"}},{q="Кто владеет Скалой Ренда?",a="Пещеру занимают грозные орки Черной горы: они используют скалу как оплот, чтобы координировать нападения и следить за горными перевалами у границы с Пылающими степями.",al={"who lives in renders rock","renders rock enemies","who holds renders rock"}},{q="Кто содержится в плену внутри пещеры?",a="Капрал Кеешан, раненый солдат-ветеран гарнизона Альянса, удерживается в плену в Скале Ренда, и ему нужна помощь, чтобы благополучно бежать обратно в Приозерье.",al={"keeshan location","captive in renders rock","who is trapped in renders rock","кеешан где находится","пленник в скале ренда","кто в плену в скале ренда"}},{q="Чем эта пещера важна для обороны Приозерья?",a="Поскольку в ней укрылись опытные воины Черной горы прямо над долиной Красногорья, Скала Ренда представляет непосредственную угрозу городку Приозерье и позволяет оркам удерживать плацдарм к югу от Пылающих степей.",al={"why attack renders rock","renders rock threat","importance of renders rock","зачем атаковать скалу ренда","скала ренда угроза","важность скалы ренда"}}},fp="13,300,34.483.0,24.411.1,31.144.0,27.164.0,34.166.0,50.220.0"}
P.entries["subzone:render-s-valley"] = {n="Долина Ренда",s="Долина Ренда — укрытый лагерь орков клана Черной горы на юго-востоке Красногорья. Он гораздо слабее укреплен, чем огромные крепости Каменной Стражи, но все равно постоянно угрожает путникам поблизости и держит пленников, захваченных в окрестных землях.",h="Долина Ренда — укрытый лагерь орков клана Черной горы на юго-востоке Красногорья.",kw={"blackrock orcs","redridge","render's valley","renders valley","servant of azora","swamp of sorrows pass","орки черной горы","красногорье","долина ренда","слуга азоры","болото печали проход"},ang={["faction:Alliance"]="Лагерь — второстепенный опорный пункт набегов Черной горы, угрожающий югу Красногорья, поэтому его зачистка жизненно важна для безопасности торговли и путешествий в Приозерье.",["profession:Tailoring"]="Плененный слуга Азоры в орочьем лагере предлагает уникальные выкройки и материалы портным, готовым пробиться через часовых к нему."},sec={{t="Плацдарм на юго-востоке",b="Долина Ренда, укрытая среди скалистых хребтов к юго-востоку от Озера Безмолвия, служит вспомогательным лагерем орков Черной горы в Красногорье. В отличие от сильно укрепленных крепостей и каменных башен северных утесов, долина состоит из скромного скопления боевых шатров, знамен и сторожевых постов. Хотя воины здесь малочисленнее и хуже вооружены, чем основные силы клана, они грабят местные дороги, донимают путников и держат захваченных пленников под охраной в грубых клетках."},{t="Тайные тропы и пленники",b="Помимо отрядов, бродящих по ее грунтовым тропам, в долине есть неожиданные места для отважных разведчиков. В лагере иногда замечали пленных людей, в том числе захваченного слугу, связанного с Башней Азоры, который умудрился торговать редкими товарами прямо под носом у пленителей. Кроме того, нехоженые тропы через высокие южные утесы за долиной позволяют смелым следопытам пробраться через границу в туманные топи Болота Печали."}},faq={{q="Кто владеет Долиной Ренда?",a="Долину занимает клан Черной горы — агрессивная орочья фракция, продвинувшаяся на юг из Пылающих степей в Красногорье, чтобы захватить земли и донимать поселения людей.",al={"who is in renders valley","renders valley orcs","what clan is in renders valley","кто в долине ренда","орки долины ренда","какой клан в долине ренда"}},{q="Здешние орки так же опасны, как орки в Каменной Страже?",a="Нет. Воины Черной горы в Долине Ренда, как правило, моложе или слабее как застрельщики по сравнению с закаленными элитными силами, охраняющими Крепость Каменной Стражи на севере.",al={"renders valley difficulty","how strong are the orcs here","сложность долины ренда","насколько сильны здешние орки"}},{q="Кто пленник, которого держат в лагере?",a="Слугу, связанного с Башней Азоры в Элвиннском лесу, захватил клан Черной горы и держит здесь в клетке. Те, кто осмелится добраться до него, могут приобрести особые материалы для портняжного дела.",al={"renders valley captive","servant of azora redridge","renders valley tailor","пленник долины ренда","слуга азоры красногорье","портной долины ренда"}},{q="Можно ли отсюда добраться до Болота Печали?",a="Да. Крутая неофициальная горная тропа вьется по южным утесам сразу за Долиной Ренда и дает скрытый короткий путь прямо в северные пределы Болота Печали.",al={"path to swamp of sorrows","renders valley mountain pass","redridge to swamp shortcut","путь в болото печали","горный перевал долины ренда","красногорье болото печали короткий путь"}}},fp="15,279,27.484.0,25.498.0,29.186.0,57.188.0,37.197.0,45.187.0"}
P.entries["subzone:rethban-caverns"] = {n="Пещеры Ретбана",s="Пещеры Ретбана — обширная система пещер в северо-западных утесах Красногорья. Они кишат агрессивными гноллами Красногорья и известны как единственный источник необычной руды Ретбана.",h="Пещеры Ретбана — обширная система пещер в северо-западных утесах Красногорья.",ang={["faction:Alliance"]="Агрессивная стая гноллов, засевшая в пещерах, постоянно угрожает путникам на севере Красногорья, и защитникам Приозерья приходится держать утесы под контролем.",["profession:Mining"]="Пещеры известны залежами руды Ретбана — минерала, за который яростно борются местные племена гноллов."},sec={{t="Логово гноллов",b="Пещеры Ретбана, глубоко высеченные в северо-западных горах над Озером Безмолвия, служат укрепленным оплотом местных гноллов. Под хитрым руководством Ардо Грязной Лапы стая яростно охраняет извилистые ходы и подземные залы, нападая на любых странников, подошедших слишком близко ко входу на склоне."},{t="Жилы Ретбана",b="The caverns are best known for Rethban ore, a distinct mineral found within the rock walls and carried by the Dirtpaw pack. Blacksmiths and researchers in Lakeshire often send travelers into the dangerous, winding tunnels to recover samples of this rare mountain ore."}},faq={{q="Где находятся Пещеры Ретбана?",a="Пещеры лежат вдоль зубчатых утесов в северо-западной части Красногорья, к северу от главной дороги в Приозерье.",al={"rethban caverns location","where is rethban","how to find rethban caverns","пещеры ретбана где находятся","где ретбан","как найти пещеры ретбана"}},{q="Какие существа обитают в Пещерах Ретбана?",a="Туннели заполонили гноллы Красногорья из клана Грязных Лап, подчиняющиеся хитрому вождю Ардо Грязной Лапе.",al={"rethban mobs","who lives in rethban caverns","rethban enemies","монстры ретбана","кто живет в пещерах ретбана","враги в пещерах ретбана"}},{q="Почему искатели приключений отправляются в эти пещеры?",a="Путники и жители Приозерья ищут руду Ретбана — необычную минеральную жилу в глубине пещер, которой владеют обитающие там гноллы.",al={"rethban cavern quests","why go to rethban caverns","rethban ore quest","задания пещер ретбана","зачем идти в пещеры ретбана","задание руда ретбана"}}},fp="15,209,14.331.0,20.267.0,34.142.0,44.113.0,44.146.0"}
P.entries["subzone:ridgepoint-tower"] = {n="Дозорная башня",s="Дозорная башня — укрепленный сторожевой пост, наблюдающий за восточной границей Элвиннского леса. Ее занимает Стража Штормграда, и она служит оплотом раннего оповещения о вражеских вторжениях, угрожающих сердцу королевства. Стражи несут дозор над опасными проходами к соседним диким землям.",h="Дозорная башня — укрепленный сторожевой пост, наблюдающий за восточной границей Элвиннского леса.",kw={"defias","duskwood","elwynn forest","gnolls","redridge","ridgepoint tower","stormwind guard","watchtower","братство справедливости","сумеречный лес","элвиннский лес","гноллы","красногорье","дозорная башня","стража штормграда","сторожевая башня"},ang={["class:Warrior"]="Солдаты и наемники одинаково способны уважать стойкую решимость стражников, удерживающих столь открытый пограничный пост против окружающих врагов.",["faction:Alliance"]="Для путников Альянса Дозорная башня — обнадеживающий маяк безопасности и порядка перед входом в опасные перевалы Красногорья или на призрачные дороги Сумеречного леса."},sec={{t="Часовой восточной границы",b="Дозорная башня, стоящая на возвышенности в восточной части Элвиннского леса, — последний оплот прямой власти Штормграда перед началом диких земель. Размещенный здесь гарнизон постоянно наблюдает за окрестными долинами и дорогами. На фоне растущей напряженности на континенте эта каменная башня позволяет заметить и остановить приближающиеся угрозы прежде, чем они смогут повредить фермам и поселениям ближе к Североземью и Златоземью."},{t="Угрозы на каждом горизонте",b="Дозорная башня испытывает давление сразу с нескольких сторон. На востоке лежит Красногорье, где обитают агрессивные стаи гноллов и налетчики-орки Черной горы, испытывающие оборону людей. За южной рекой маячит мрачная опушка Сумеречного леса с бродящими там ужасами нежити. Ближе к дому в лагерях в глуши рыщут разбойники Братства Справедливости, готовые воспользоваться любой брешью в обороне стражи."}},faq={{q="Что такое Дозорная башня?",a="Дозорная башня — укрепленная разведывательная башня Стражи Штормграда на востоке Элвиннского леса. Это передовой сторожевой пост, призванный предупреждать и защищать королевство от вражеских вторжений.",al={"ridgepoint tower elwynn","what is this guard tower","east elwynn tower","дозорная башня элвиннский лес","что это за сторожевая башня","восточная башня элвиннского леса"}},{q="Кто владеет башней и несет в ней службу?",a="Башню удерживают и охраняют стражники и разведчики, верные Королевству Штормград, под командованием Стражи Штормграда.",al={"who is at ridgepoint tower","who owns ridgepoint tower","кто в дозорной башне","чья дозорная башня"}},{q="Каких угроз опасается гарнизон?",a="Стражи высматривают гноллов и вторгающихся орков, выходящих из Красногорья, нежить, пересекающую границу из оскверненных рощ Сумеречного леса, и разбойников Братства Справедливости, действующих в тайных лесных лагерях неподалеку.",al={"enemies near ridgepoint","what is attacking ridgepoint","why is the tower here","враги у дозорной башни","кто атакует дозорную башню","зачем здесь башня"}},{q="Где находится Дозорная башня?",a="Она стоит на возвышенности на крайнем востоке Элвиннского леса, рядом с границами, соединяющими его и с Красногорьем, и с Сумеречным лесом.",al={"ridgepoint tower location","where is ridgepoint","дозорная башня где находится","где дозорная башня"}}},fp="16,309,30.471.0,24.421.0,25.209.0,32.143.0,45.206.0,34.155.0"}
P.entries["subzone:rocktusk-farm"] = {n="Ферма Каменного Клыка",s="Ферма Каменного Клыка — небольшая свиноферма на севере Дуротара, неподалеку от дороги у ворот Оргриммара. Расположенная рядом с укрепленными подступами к столице, она снабжает жителей города мясом и провизией.",h="Ферма Каменного Клыка — небольшая свиноферма на севере Дуротара, неподалеку от дороги у ворот Оргриммара.",kw={"durotar","horde provisions","orgrimmar","pig farm","rocktusk farm","swine","дуротар","провизия орды","оргриммар","свиноферма","ферма каменного клыка","свиньи"},ang={["faction:Horde"]="Свиньи, выращиваемые здесь неподалеку от столицы, — важнейшее пропитание для воинов и работников Оргриммара.",["profession:Cooking"]="Свиней с фермы ценят повара Орды, ищущие свежую свинину, ребрышки и вкусные куски для жарки."},sec={{t="Провизия для столицы",b="Ферма Каменного Клыка, устроенная на сухой почве Дуротара, посвящена разведению выносливых свиней, приспособленных к суровому пустынному климату. Земля Дуротара славится сухостью и каменистостью, выращивать урожай трудно, поэтому домашние свинофермы — важнейший источник пропитания для растущего населения Оргриммара. Благодаря близости к укрепленной границе столицы усадьба пользуется безопасностью, редкой в суровых диких землях красных каньонов."}},faq={{q="Для чего служит Ферма Каменного Клыка?",a="Ферма Каменного Клыка — свиноферма. Там разводят свиней, чтобы снабжать свежим мясом и провизией соседний Оргриммар, где мало пахотной земли.",al={"what is this place","rocktusk farm purpose","why are there pigs here","что это за место","назначение фермы каменного клыка","почему здесь свиньи"}},{q="Где находится Ферма Каменного Клыка?",a="Ферма находится на севере Дуротара, к юго-западу по дороге от главных ворот Оргриммара, среди скалистых утесов.",al={"where is rocktusk farm","rocktusk farm location","где ферма каменного клыка","ферма каменного клыка расположение"}},{q="Безопасна ли ферма от диких зверей?",a="Близость к Оргриммару и патрули Орды делают ее безопаснее большинства дальних усадеб Дуротара, хотя дикие звери и вредители по-прежнему бродят на окраинах.",al={"is rocktusk farm safe","dangers at rocktusk farm","безопасна ли ферма каменного клыка","опасности фермы каменного клыка"}}},fp="13,241,26.449.0,31.159.0,31.140.0,34.187.0"}
P.entries["subzone:roguefeather-den"] = {n="Логово Легкоперых",s="Логово Легкоперых — пещера на юге-центре Тысячи Игл. Ее заполонили свирепые визгливые гарпии, превратившие ее в укрепленное гнездовье, где стая хранит награбленную провизию в темных глубинах.",h="Логово Легкоперых — пещера на юге-центре Тысячи Игл.",kw={"cavern","harpies","roguefeather","roguefeather den","roost","thousand needles","пещера","гарпии","легкоперые","логово легкоперых","гнездовье","тысяча игл"},ang={["faction:Horde"]="Для путников Орды, совершающих долгий переход к Мерцающей равнине, агрессивная стая из Логова Легкоперых — постоянная угроза нападения с воздуха и из засады на южном дне каньона."},sec={{t="Гнездовье в каньонах",b="Логово Легкоперых, высеченное в отвесных песчаниковых утесах юга Тысячи Игл, — мерзкое гнездовье местных гарпий. Известные диким визгом и агрессивной территориальностью, гарпии считают пещеру и надежным убежищем, и складом, бдительно охраняя собранную еду и украденные припасы, сваленные в темной глубине пещеры."}},faq={{q="Что такое Логово Легкоперых?",a="Это небольшая пещера в южных утесах Тысячи Игл, служащая гнездовьем и складом припасов для территориальных гарпий Легкоперых.",al={"what is this cave","roguefeather den info","where is roguefeather","что это за пещера","логово легкоперых информация","где легкоперые"}},{q="Какие существа обитают в пещере?",a="Пещеру заполонили враждебные визгливые гарпии, яростно защищающие свои гнездовья и собранную еду от любых чужаков.",al={"who lives in roguefeather den","mobs in roguefeather den","кто живет в логове легкоперых","монстры логова легкоперых"}},{q="Что хранится в глубине Логова Легкоперых?",a="В глубине пещеры гарпии копят запасы найденной и украденной еды, которую неустанно и агрессивно охраняют.",al={"what is in the back of the cave","roguefeather food","что в глубине пещеры","еда легкоперых"}}},fp="16,246,22.378.0,25.157.0,32.138.0,42.133.0"}
P.entries["subzone:rogues-quarter"] = {n="Квартал разбойников",s="Квартал разбойников — тускло освещенный район в юго-восточном крыле Подгорода. Он служит сборным пунктом для разведчиков, убийц и тайных агентов Отрекшихся, а также для ремесленников, которые их снабжают.",h="Квартал разбойников — тускло освещенный район в юго-восточном крыле Подгорода.",kw={"engineering","forsaken","leatherworking","poison vendor","rogue trainer","rogues quarter","rogues' quarter","skinning","undercity","инженерное дело","отрекшиеся","кожевничество","торговец ядами","учитель разбойников","квартал разбойников","снятие шкур","подгород"},ang={["class:Rogue"]="Для убийц из числа Отрекшихся и Орды этот квартал — главный центр, где можно освоить скрытность, изучить боевые приемы и запастись реагентами для смертельных ядов.",["profession:Engineering"]="Механики приходят в Квартал разбойников, чтобы изучить схемы и создавать бомбы, устройства и механические инструменты, которые любят тайные агенты."},sec={{t="Тени Подгорода",b="Квартал разбойников расположен в юго-восточной части подземного города и собирает самых хитрых и смертоносных из Отрекшихся. При жизни многие из них были ворами, карманниками или безмолвными клинками Королевства Лордерон; после смерти их мастерство в скрытности, ядах и отвлечении внимания служит защите молодого государства от Плети и Алого ордена. В районе царит тихая деятельность: это тайное убежище, где агенты точат кинжалы, варят смертельные яды и оттачивают скрытные навыки."},{t="Предметы торговли",b="Помимо скрытности и убийств, в Квартале разбойников обосновались ремесла, необходимые для тайного выживания. Мастера обучают путников кожевничеству и снятию шкур, превращая сырые шкуры в легкую бесшумную броню. По каменным залам разносится стук инженерных верстаков: механики собирают устройства, а полевые лекари и аптекари обучают первой помощи и продают смертельные яды, необходимые для тайной работы."}},faq={{q="Где находится Квартал разбойников?",a="Квартал разбойников находится в юго-восточной части внешнего кольца Подгорода, за Торговым кварталом.",al={"rogues quarter location","where is rogues quarter","undercity rogues quarter map","квартал разбойников где","где находится квартал разбойников","подгород квартал разбойников карта"}},{q="Какие учителя здесь есть?",a="В квартале находятся учителя разбойников, а также наставники по кожевничеству, снятию шкур, инженерному делу и первой помощи. Поблизости также стоят торговцы ядами, снабжающие реагентами.",al={"rogues quarter trainers","undercity rogue trainer","who trains in rogues quarter","учителя квартал разбойников","учитель разбойников подгород","кто учит в квартале разбойников"}},{q="Почему у Отрекшихся есть отдельный район для разбойников?",a="Окруженные враждебными силами, такими как Плеть и Алый орден, Отрекшиеся во многом полагаются на шпионаж, убийства и тактику «ударил и скрылся» для защиты своей территории, поэтому тайные агенты жизненно важны для их выживания.",al={"why do forsaken need rogues","forsaken assassins","undercity rogue lore","зачем отрекшимся разбойники","убийцы отрекшихся","предания разбойники подгорода"}}},fp="15,226,24.540.0,18.454.0,37.114.0,32.181.0,61.226.0"}
P.entries["subzone:roland-s-doom"] = {n="Погибель Роланда",s="Погибель Роланда — заброшенная, погруженная во мрак шахта в юго-восточных холмах Сумеречного леса, к востоку от Гниющего сада. Когда-то это была обычная выработка, а теперь она печально известна как опасное логово, захваченное свирепыми воргенами.",h="Погибель Роланда — заброшенная, погруженная во мрак шахта в юго-восточных холмах Сумеречного леса, к востоку...",kw={"gutspill","jitters","nefaru","nightbane","roland's doom","rolands doom","rotting orchard","scythe of elune","velinde starsong","кишкодер","трясунчик","нефару","ночная погибель","погибель роланда","гниющий сад","коса элуны","велинда песнь звезд"},ang={["profession:Mining"]="Хотя когда-то здесь был действующий карьер, любой старатель, безрассудно взмахнувший киркой, быстро поймет, что единственные жилы в Погибели Роланда принадлежат кровожадным воргенам.",["race:NightElf"]="Трагическая гибель жрицы Велинды Песни Звезд в этой шахте делает Погибель Роланда местом скорби и печальных раздумий для ночных эльфов, выясняющих судьбу сородичей и неуловимой Косы Элуны."},sec={{t="Логово теней и жестокости",b="Погибель Роланда, прорубленная в холмах к востоку от Гниющего сада, давно перестала быть действующей шахтой. Теперь это жестокий оплот стаи воргенов Ночной Погибели, которую возглавляют такие звери, как Кишкодер и Нефару. В темных туннелях отдаются гортанное рычание и запах сырой земли и крови, и для неосторожных путников это одно из самых опасных мест во всем Сумеречном лесу."},{t="Гибель Велинды Песни Звезд",b="Настоящая трагедия Погибели Роланда скрыта глубоко в ее туннелях. Именно здесь ночная эльфийка-жрица Велинда Песнь Звезд встретила свою смерть, неся Косу Элуны — древний артефакт огромной и неукротимой силы. Позже напуганный странник Трясунчик наткнулся в шахте на косу, случайно выпустил на волю еще больше свирепых воргенов и привлек в Сумеречный лес Темных всадников. Потревоженная в шахте земля до сих пор может пробудить призрак Велинды, и он расскажет о ее последних мгновениях."}},faq={{q="Что такое Погибель Роланда?",a="Погибель Роланда — разрушенная заброшенная шахта на юго-востоке Сумеречного леса, к востоку от Гниющего сада. Сейчас она захвачена злобными воргенами Ночной Погибели.",al={"where is rolands doom","what is this mine","где погибель роланда","что это за шахта"}},{q="Почему в шахте есть воргены?",a="Шахту наводнили воргены после потери Косы Элуны. Сейчас в ее сырых штольнях обитают могучие звери стаи Ночной Погибели, в том числе Нефару и Кишкодер.",al={"why worgen here","who lives in rolands doom","почему здесь воргены","кто живет в погибели роланда"}},{q="Кто такая Велинда Песнь Звезд и почему она связана с этим местом?",a="Велинда Песнь Звезд была ночной эльфийкой, жрицей Элуны, которая владела Косой Элуны, чтобы сражаться с демонами Оскверненного леса. Ее путь пролег через море в Сумеречный лес, где ее убили в этой самой шахте, а коса осталась здесь.",al={"velinde starsong rolands doom","who died here","велинда песнь звезд погибель роланда","кто здесь погиб"}},{q="Какую роль Трясунчик играет в истории Погибели Роланда?",a="Трясунчик вошел в Погибель Роланда и обнаружил погребенную Косу Элуны. Его вмешательство невольно выпустило в Сумеречный лес еще больше воргенов и привлекло в этот край зловещих Темных всадников, ввергнув лес в еще большую опасность.",al={"jitters mine","jitters scythe","трясунчик шахта","трясунчик коса"}}},fp="13,225,29.390.0,28.522.1,22.157.0,37.200.1,64.240.1,53.225.1"}
P.entries["subzone:rolling-plains"] = {n="Холмистые равнины",s="Холмистые равнины протянулись по южной части Мулгора между Деревней Кровавого Копыта и границей Степей. Эти продуваемые ветрами луга служат домом для многочисленных стад диких животных, но здесь также приходится постоянно быть настороже из-за рыскающих кентавров-налетчиков и агрессивных гарпий.",h="Холмистые равнины протянулись по южной части Мулгора между Деревней Кровавого Копыта и границей Степей.",kw={"bloodhoof village","centaur","harpies","kodo","mulgore","rolling plains","tallstrider","windfury","деревня кровавого копыта","кентавры","гарпии","кодо","мулгор","холмистые равнины","долгоног","ярость ветра"},ang={["class:Hunter"]="Обилие стад кодо, долгоногов, волков и пум делает Холмистые равнины идеальным местом, чтобы оттачивать навыки выслеживания, добывать припасы и приручать первых питомцев.",["race:Tauren"]="Холмистые равнины — жизненно важные охотничьи угодья для недавно объединившихся племен, но появление древних врагов-кентавров так близко к Деревне Кровавого Копыта делает охрану этого южного прохода вопросом выживания племени."},sec={{t="Сердце южного Мулгора",b="Холмистые равнины тянутся на юг от Деревни Кровавого Копыта к природным земляным вратам в Степи и воплощают бескрайние просторы родины тауренов. Здесь изобилует дичь, жизненно важная для племен: луговые волки, стада кодо, пумы плоскогорья и быстрые долгоноги. Для молодых охотников, доказывающих свою ценность старейшинам, эти раздольные саванны — незаменимое испытание, где проверяются умение выслеживать, терпение и почтение к природе."},{t="Надвигающаяся опасность",b="Несмотря на естественное кольцо утесов вокруг Мулгора, Холмистые равнины остаются особенно уязвимыми для внешних угроз. Это единственный рубеж, где агрессивным кентаврам-разведчикам удалось прорвать оборону и нападать на путников и охотничьи отряды. К опасности добавляется гнездо хищных гарпий Ярости Ветра в восточных скалах, которые налетают на заблудившуюся дичь и беззащитные кочевые стоянки."}},faq={{q="Какие животные обитают на Холмистых равнинах?",a="Луга кормят множество местных животных: бродячие стада диких кодо, проворных долгоногов, луговых волков и крадущихся пум плоскогорья. Эти звери дают жизненно важные мясо, шкуры и жилы племенам Деревни Кровавого Копыта.",al={"rolling plains wildlife","mobs rolling plains","animals mulgore plains","животные холмистых равнин","монстры холмистые равнины","звери мулгора"}},{q="Почему в этой части Мулгора бродят кентавры?",a="Холмистые равнины граничат с восточными проходами в Степи, поэтому это единственная область Мулгора, где кентаврам-налетчикам удалось прорвать границу. Разбойничьи разведчики постоянно осматривают равнины, проверяя оборону тауренов и угрожая одиноким охотникам.",al={"centaur in mulgore","why centaur rolling plains","centaur outriders","кентавры в мулгоре","почему кентавры холмистые равнины","кентавры-разведчики"}},{q="Какие еще враждебные существа угрожают равнинам?",a="Помимо бродячих кентавров-разведчиков, в восточных скалах региона гнездится опасная стая гарпий Ярости Ветра, которая охотится на неосторожных путников и тревожит местных животных.",al={"harpies rolling plains","dangers rolling plains","гарпии холмистые равнины","опасности холмистых равнин"}},{q="Где начинаются и заканчиваются Холмистые равнины?",a="Равнины занимают большую часть юга Мулгора и тянутся от Деревни Кровавого Копыта до горной границы со Степями.",al={"rolling plains location","where are rolling plains","boundaries rolling plains","холмистые равнины где","где находятся холмистые равнины","границы холмистых равнин"}}},fp="14,296,25.493.0,19.418.0,48.256.0,53.268.0,49.179.0,42.122.0"}
P.entries["subzone:rotting-orchard"] = {n="Гниющий сад",s="Гниющий сад — зараженная порчей заброшенная плодовая роща на юге Сумеречного леса. Когда-то он давал урожай соседнему поселению Темнолесье, но пришел в упадок и теперь захвачен ненасытными волкоподобными хищниками — стаей Ночной Погибели.",h="Гниющий сад — зараженная порчей заброшенная плодовая роща на юге Сумеречного леса.",kw={"darkshire","duskwood","marus","nightbane","rotting orchard","shadow weavers","worgen","темнолесье","сумеречный лес","марус","ночная погибель","гниющий сад","ткачи теней","воргены"},ang={["class:Hunter"]="Искореженные деревья и разрушенные постройки — отличное место для выслеживания, но хищные чувства и колдовство стаи Ночной Погибели делают его готовой засадой.",["faction:Alliance"]="Вторжение воргенов Ночной Погибели в Гниющий сад представляет прямую хищную угрозу хрупкой безопасности Темнолесья, расположенного неподалеку по дороге."},sec={{t="Логово Ночной Погибели",b="Гниющий сад находится к востоку от разрушенной Усадьбы Йоргена и к западу от Безмятежного кладбища и служит мрачным свидетельством упадка Сумеречного леса. Деревья отягощены засохшими, гнилыми плодами, а полуразрушенные амбары и постройки воргены Ночной Погибели превратили в грубые стоянки. Сторожа Ночной Погибели рыщут в искореженных зарослях, а темные заклинатели, известные как Ткачи Теней, плетут зловещую магию среди гниющих бревен. Стая подчиняется свирепому вожаку Марусу, который бродит по окрестным лесам, охраняя захваченные владения."}},faq={{q="Какие существа обитают в Гниющем саду?",a="Сад целиком заражен стаей Ночной Погибели — группировкой ненасытных воргенов. Среди них хитрые охотники, называемые сторожами Ночной Погибели, темные чародеи, известные как ткачи теней Ночной Погибели, и их бродячий вожак Марус.",al={"rotting orchard mobs","who lives in rotting orchard","what is at rotting orchard","гниющий сад монстры","кто живет в гниющем саду","что в гниющем саду"}},{q="Где в Сумеречном лесу находится Гниющий сад?",a="Гниющий сад лежит на юге Сумеречного леса, к юго-западу от города Темнолесье. Он расположен прямо между разрушенной Усадьбой Йоргена на западе и Безмятежным кладбищем на востоке.",al={"rotting orchard location","where is rotting orchard","how to find rotting orchard","гниющий сад где","где находится гниющий сад","как найти гниющий сад"}},{q="Кто возглавляет воргенов в этом саду?",a="Вожака местных воргенов зовут Марус. Он бродит по территории между гниющим садом и своим близлежащим логовом, яростно защищая владения стаи.",al={"rotting orchard boss","packleader marus","who leads nightbane","босс гниющего сада","вожак марус","кто возглавляет ночную погибель"}},{q="Это место всегда было захвачено чудовищами?",a="Нет. Как и многие окрестные усадьбы Сумеречного леса, это была плодородная ферма и плодовый сад, кормивший местных людей, пока темные проклятия и сверхъестественные ужасы не захватили край и не прогнали фермеров.",al={"orchard history","why is orchard rotting","история сада","почему сад гниет"}}},fp="15,253,20.573.0,42.231.0,49.197.0,37.172.0,42.223.0"}
P.entries["subzone:royal-gallery"] = {n="Королевская галерея",s="Королевская галерея, скрытая в Крепости Штормграда за садом во дворе, — тихий зал памяти. В ней выставлены великолепные статуи и произведения искусства в честь выдающихся деятелей истории королевства и Великого Альянса.",h="Королевская галерея, скрытая в Крепости Штормграда за садом во дворе, — тихий зал памяти.",kw={"daelin proudmoore","dena kennedy","llane wrynn","mara fordragon","royal gallery","statues","stormwind keep","даэлин праудмур","дена кеннеди","ллейн ринн","мара фордрагон","королевская галерея","статуи","крепость штормграда"},ang={["faction:Alliance"]="Галерея — тихий памятник жертвам Альянса, отдающий дань легендарным лидерам, таким как Даэлин Праудмур и король Ллейн.",["race:Human"]="Для людей Штормграда этот зал чтит наследие дома Ринн и дома Фордрагон, сохраняя их королевское наследие в стенах крепости."},sec={{t="Зал героев",b="Королевская галерея находится рядом с Королевской библиотекой, сразу за зеленым внутренним садом Крепости Штормграда. В зале стоят статуи великих людей, определивших судьбу королевства: Короля Ллейна Ринна, павшего правителя Штормграда; верховного адмирала Даэлина Праудмура из Кул Тираса; и Мары Фордрагон, предка нынешнего регента. Это одновременно частный музей благородного наследия и тихое убежище для придворных гостей, таких как леди Дена Кеннеди."}},faq={{q="Где находится Королевская галерея?",a="Королевская галерея находится внутри Крепости Штормграда. Пройдите через крепость мимо небольшого внутреннего парка во дворе, рядом с Королевской библиотекой.",al={"royal gallery location","how to get to royal gallery","where is it","королевская галерея где","как попасть в королевскую галерею","где она"}},{q="Каким историческим личностям здесь воздают почести?",a="В галерее стоят величественные статуи в честь короля Ллейна Ринна, верховного адмирала Даэлина Праудмура и Мары Фордрагон, прославляющие род и доблесть королевства и его ближайших союзников.",al={"statues in royal gallery","who are the statues of","who is honored here","статуи в королевской галерее","чьи это статуи","кого здесь почитают"}},{q="Кого можно встретить в галерее?",a="Леди Дену Кеннеди часто можно застать за созерцанием изящного искусства и задумчивой атмосферы галереи.",al={"who is here","npcs in royal gallery","lady dena kennedy","кто здесь","персонажи в королевской галерее","леди дена кеннеди"}},{q="Чем Королевская галерея отличается от Королевской библиотеки?",a="Хотя они расположены вплотную друг к другу в королевском крыле Крепости Штормграда, это разные помещения. В библиотеке хранятся королевские архивы и работают ученые, а галерея посвящена изящному искусству и памятным скульптурам.",al={"royal gallery vs library","is it part of the library","королевская галерея и библиотека","часть ли это библиотеки"}}},fp="13,249,16.443.0,35.155.0,47.187.0,38.105.0,71.221.0"}
P.entries["subzone:royal-library"] = {n="Королевская библиотека",s="Глубоко в каменном крыле Крепости Штормграда находится Королевская библиотека, где хранятся коллективная память, летописные свитки и трактаты королевства. Под присмотром главного библиотекаря Милтона Снопа на ее полках лежат важнейшие записи о древних войнах, утраченных легендах и землях за морем.",h="Глубоко в каменном крыле Крепости Штормграда находится Королевская библиотека, где хранятся коллективная...",kw={"book of medivh","mathias shaw","milton sheaf","royal library","stormwind keep","stormwind library","книга медива","матиас шоу","милтон сноп","королевская библиотека","крепость штормграда","библиотека штормграда"},ang={["class:Mage"]="Для знатоков тайных искусств библиотека хранит редкие первоисточники о прошлом Тирисфаля, древней охоте на драконов и наследии Последнего Хранителя.",["faction:Alliance"]="На полках хранятся основополагающие договоры и военные хроники, связывающие народы людей, дворфов и эльфов на протяжении поколений конфликтов."},sec={{t="Хранилище королевства",b="Пока Крепость Штормграда кишит стражей в доспехах и придворными интригами, Королевская библиотека остается островком научной тишины. Зал под управлением Милтона Снопа — главный архив истории южных людей: здесь хранятся уцелевшие тексты времен до Первой войны, недавние военные хроники и найденные фолианты. Ученые, жрецы и путники Альянса могут свободно знакомиться с открытыми трактатами — от создания первоначального Альянса Лордерона до недавнего появления Орды Тралла в Калимдоре."},{t="Тени среди полок",b="Библиотеку не всегда обходили стороной внешние конфликты. После Второй войны в ее хранилищах оказалась опасная Книга Медива, что привлекло лазутчиков Альтерака и рыцарей смерти, посланных Нер'зулом, в дерзком налете на замок."}},faq={{q="Где находится Королевская библиотека?",a="Она расположена внутри Крепости Штормграда — королевской цитадели в восточной части Штормграда. Пройдя через главный вестибюль крепости, идите по коридорам, ведущим в крылья ученых и архивов.",al={"where is the library","stormwind library location","how to find library","где библиотека","где находится библиотека штормграда","как найти библиотеку"}},{q="Кто управляет библиотекой?",a="Главным библиотекарем служит Милтон Сноп. Он ведет записи архива и помогает ученым и искателям приключений, которые ищут недостающие тома или конкретные трактаты королевства.",al={"who is the librarian","head librarian","milton sheaf","кто библиотекарь","главный библиотекарь","милтон сноп"}},{q="Какие книги здесь можно прочесть?",a="Посетители могут читать исторические труды об Альянсе Лордерона, Хранителях Тирисфаля, последствиях Второй войны и донесения о Новой Орде, а также региональные истории Штормграда и Альтерака.",al={"books in library","readable lore books","what to read","книги в библиотеке","книги по преданиям","что почитать"}},{q="Почему Книгу Медива хранили здесь?",a="После поражения Орды во Второй войне опасную книгу заклинаний поместили в Королевскую библиотеку на хранение. Однако заговорщики Альтерака похитили ее и столкнулись с рыцарями смерти Терона Кровожада, которые готовили нападение, чтобы забрать книгу для Нер'зула.",al={"book of medivh stormwind","medivh book stolen","книга медива штормград","кража книги медива"}}},fp="13,302,25.545.0,25.242.0,35.204.0,21.167.0,37.222.0,37.272.0"}
P.entries["subzone:royal-quarter"] = {n="Королевский квартал",s="Королевский квартал — уединенная обитель власти в Подгороде, тронный зал леди Сильваны Ветрокрылой. Здесь Королева банши управляет Отрекшимися вместе со своим стражем-повелителем ужаса Вариматрасом под охраной отборного отряда королевских стражей ужаса.",h="Королевский квартал — уединенная обитель власти в Подгороде, тронный зал леди Сильваны Ветрокрылой.",kw={"banshee queen","hall of the dark lady","royal dreadguard","royal quarter","sylvanas windrunner","throne room","undercity","varimathras","королева банши","зал темной госпожи","королевский страж ужаса","королевский квартал","сильвана ветрокрылая","тронный зал","подгород","вариматрас"},ang={["faction:Horde"]="Посланники Орды, прибывающие в Королевский квартал, часто смотрят на натрезим-советника Темной Госпожи с глубоким подозрением и сомневаются в мудрости доверия демону в сердце столицы Орды.",["race:Undead"]="Королевский квартал — сердце независимости Отрекшихся, где Сильвана Ветрокрылая и ее помощник-повелитель ужаса определяют будущее своего освобожденного народа."},sec={{t="Обитель Темной Госпожи",b="Королевский квартал, скрытый за высокими арками и тенистыми коридорами, также известный как Зал Темной Госпожи, — политический и военный центр Отрекшихся. Сильвана Ветрокрылая держит двор в этом огромном подземном зале, замышляя выживание своих свободных нежитей и уничтожение Плети. Тяжеловооруженные королевские стражи ужаса стоят на страже у возвышения, не давая незваным гостям и убийцам добраться до королевы."},{t="Опасный союз",b="Рядом с Темной Госпожой стоит натрезим Вариматрас — неожиданная и тревожная фигура в сердце Подгорода. Встав на сторону Сильваны во время гражданской войны в руинах Лордерона, чтобы спасти себе жизнь, повелитель ужаса поклялся служить ее делу. Из Королевского квартала он командует вестниками смерти и координирует оборону всего государства. Хотя его тактическая хитрость служит Отрекшимся хорошо, его демоническая природа заставляет многих союзников из Орды опасаться его истинных намерений."}},faq={{q="Кто правит из Королевского квартала?",a="Lady Sylvanas Windrunner, the Banshee Queen, rules the Forsaken from the throne within the Royal Quarter. She is flanked by the nathrezim Varimathras, who pledged allegiance to her during the reconquest of Lordaeron.",al={"who is in the royal quarter","undercity throne room leader","who leads undercity","кто в королевском квартале","предводитель в тронном зале подгорода","кто правит подгородом"}},{q="Почему в тронном зале стоит повелитель ужаса?",a="Varimathras surrendered to Sylvanas Windrunner during the reconquest of Capital City before betraying his brothers Detheroc and Balnazzar. He spared his own life by swearing loyalty to Sylvanas, and now acts as her enforcer and master of scouts.",al={"why is varimathras here","dreadlord in undercity","why is demon in royal quarter","почему здесь вариматрас","повелитель ужаса в подгороде","почему демон в королевском квартале"}},{q="Кто такие королевские стражи ужаса?",a="Королевские стражи ужаса — элитные защитники из числа Отрекшихся, избранные специально для охраны леди Сильваны и Королевского квартала. Они относятся к самым дисциплинированным и смертоносным защитникам Подгорода.",al={"dreadguards","undercity throne room guards","royal quarter guards","стражи ужаса","стража тронного зала подгорода","стража королевского квартала"}},{q="Какую еще роль играет этот зал?",a="Помимо роли главного приемного зала Темной Госпожи и Вариматраса, в Королевском квартале находятся распорядители боев, которые собирают бойцов Орды для походов за пределы земель и стратегических стычек по всему Азероту.",al={"what else is in royal quarter","royal quarter purpose","battlemasters royal quarter","что еще в королевском квартале","назначение королевского квартала","распорядители боев королевский квартал"}}},fp="13,267,25.479.0,20.495.0,33.216.0,53.245.0,31.192.0,44.215.0"}
P.entries["subzone:ruined-reaches"] = {n="Опустошенный берег",s="Опустошенный берег — коварное южное побережье Азшары у границы с Дуротаром. Эти пляжи, отмеченные рассыпающимися древними руинами, разбитыми кораблями и острыми отмелями, кишат агрессивными прибрежными хищниками. Среди запустения высоко на утесе над прибоем примостился небольшой гномий форпост.",h="Опустошенный берег — коварное южное побережье Азшары у границы с Дуротаром.",kw={"azshara","blimo gadgetspring","durotar","jagged reef","jubie gadgetspring","makrura","murloc","ruined reaches","азшара","блимо прибамбас","дуротар","острые рифы","джуби прибамбас","макрура","мурлок","опустошенный берег"},ang={["profession:Engineering"]="Одинокая мастерская Блимо и Джуби Прибамбас снабжает ценными деталями и припасами инженеров, исследующих дикие земли Азшары.",["race:Gnome"]="Высокотехнологичная гномья усадьба, процветающая на враждебных утесах Азшары, — приятное напоминание об изобретательности гномов вдали от Стальгорна."},sec={{t="Побитый берег",b="Опустошенный берег тянется вдоль южных границ Азшары, чуть севернее Дуротара, и представляет собой лабиринт скалистых бухт, утесов и усеянного обломками песка. Как и в Острых рифах севернее, скрытые мели делают морские путешествия крайне опасными, и вдоль берега лежит множество разбитых кораблей. В водах и на пляжах кишат враждебные существа, включая территориальных мурлоков, свирепых гидр и бронированных макрура, из-за чего путь по суше так же опасен, как и плавание у прибоя."},{t="Форпост Прибамбас",b="На западном утесе над пляжами неожиданно примостился островок механической цивилизации: гномья мастерская, к которой ведет крутая тропа с материковой части Азшары. Форпост держат Блимо и Джуби Прибамбас, и здесь проходящим искателям приключений предлагают инженерные детали и обычные товары. Внутри есть подъемник в жилые комнаты с тремя кроватями, но кому, если вообще кому-то, принадлежит третья койка, остается тихой домашней загадкой."}},faq={{q="Где находится Опустошенный берег?",a="Это самая южная прибрежная полоса Азшары, граничащая с северным краем Дуротара. Местность состоит из песчаных пляжей, прибрежных заливов и утесов под материковыми обрывами.",al={"ruined reaches location","where is ruined reaches","how to get to ruined reaches","где опустошенный берег","расположение опустошенного берега","как добраться до опустошенного берега"}},{q="Какие опасности обитают на этом участке побережья?",a="На пляжах и мелководье обитают враждебные существа, в основном агрессивные племена мурлоков, многоголовые гидры и макрура, таящиеся на приливных отмелях.",al={"ruined reaches mobs","what lives here","monsters in ruined reaches","монстры опустошенного берега","кто здесь живет","существа на опустошенном берегу"}},{q="Кто живет в гномьем строении на утесах?",a="Там живут и работают Блимо и Джуби Прибамбас. Они держат небольшую лавку с инженерными деталями и товарами для путников, пробирающихся по пустынному берегу.",al={"gnomes in ruined reaches","gadgetspring house","who lives in the gnome house","гномы на опустошенном берегу","дом прибамбас","кто живет в доме гномов"}},{q="Почему здесь так много кораблекрушений?",a="Как и у соседних Острых рифов, прибрежные воды здесь усеяны мелями и скрытыми опасностями: корабли то и дело натыкаются на них и разбиваются о скалы.",al={"shipwrecks in azshara","why are ships wrecked here","ruined reaches wrecks","кораблекрушения в азшаре","почему здесь разбиваются корабли","обломки на опустошенном берегу"}}},fp="14,331,16.490.0,24.465.0,37.184.0,43.169.0,49.161.0,38.171.0"}
P.entries["subzone:ruins-of-aboraz"] = {n="Руины Абораза",s="Руины Абораза — древние каменные руины Гурубаши на юго-восточных утесах Тернистой долины. Когда-то часть обширной империи троллей джунглей, ныне обветшавшие террасы служат укромным убежищем отступнику-знахарю Занзилу Отверженному и его одурманенным рабам.",h="Руины Абораза — древние каменные руины Гурубаши на юго-восточных утесах Тернистой долины.",kw={"aboraz","chucky","jubuwal","stranglethorn","witch doctor","yenniku","zanzil","абораз","чаки","жубуваль","тернистая долина","знахарь","йенникю","занзил"},ang={["faction:Alliance"]="Каперы и наемники Альянса часто сталкиваются с делами Занзила, преследуя долги или награды, связанные с гоблинами и пиратами Пиратской бухты.",["race:Troll"]="Для племени Черного Копья Абораз — оскорбление: изгой, используя извращенное колдовство вуду, порабощает собратьев-троллей и держит юного Йенникю в заложниках на древних землях Гурубаши."},sec={{t="Владения знахаря",b="Обветшавшая кладка Абораза на утесах к юго-востоку от Руин Жубуваля и к югу от Хрустальной шахты превратилась в алхимический полигон. Занзила Отверженного изгнали и местные племена, и жители материка, и он удалился сюда варить сильнодействующие дурманящие смеси и ядовитые эликсиры. Во дворах Занзил полностью подчиняет себе жутковатый набор слуг: бредущих нежитей-вурдалаков, порабощенных троллей и даже подчиненных прибрежных наг."},{t="Пешки и пленники",b="Странные зелья Занзила не просто отравляют тело — они ломают волю. Среди потерянных душ, бродящих по террасам, — порабощенный юноша из племени Черного Копья Йенникю, чей разум остается скован чарами Занзила. Вместе с ним бесцельно бродит Чаки «Десять Больших Пальцев», пират-должник, бегущий от попыток взыскания со стороны «Морского волка» Маккинли из Пиратской бухты, превращенный зельями Занзила в безучастного стража убежища."}},faq={{q="Кто правит Руинами Абораза?",a="Руинами управляет Занзил Отверженный, изгнанный знахарь, известный по всей Тернистой долине своей темной алхимией и мощными зельями, подчиняющими разум.",al={"who leads aboraz","aboraz boss","who is in ruins of aboraz","кто правит аборазом","босс абораза","кто в руинах абораза"}},{q="Почему здесь вместе наги и вурдалаки?",a="Особые смеси Занзила позволяют ему подчинять разум и поднимать мертвых. Он поработил троллей-изгоев, поднял лесных вурдалаков и пленил прибрежных наг, чтобы они служили беспрекословной стражей его террасы.",al={"why are naga here","aboraz ghouls","aboraz mobs","почему здесь наги","вурдалаки абораза","монстры абораза"}},{q="Где находятся Руины Абораза?",a="Они лежат на высоких утесах на юго-востоке Тернистой долины, к югу от Хрустальной шахты и сразу к юго-востоку от Руин Жубуваля, над восточным морем.",al={"aboraz location","where is aboraz","how to get to ruins of aboraz","где абораз","расположение абораза","как добраться до руин абораза"}}},fp="15,297,23.525.0,18.425.1,35.167.0,44.199.0,38.165.0"}
P.entries["subzone:ruins-of-alterac"] = {n="Руины Альтерака",s="Покрытые снегом Руины Альтерака — все, что осталось от города Альтерак, некогда гордой горной столицы королевства Альтерак. После того как король Эйден Перенольд предал союзников во время Второй войны, королевство было исключено из Альянса, а город введен под военное положение. Разрушенная цитадель теперь захвачена свирепыми ограми Раздробленного Хребта.",h="Покрытые снегом Руины Альтерака — все, что осталось от города Альтерак, некогда гордой горной столицы...",kw={"alterac city","bro'kin","crushridge","mug'thol","perenolde","ruins of alterac","strahnbrad","syndicate","город альтерак","бро'кин","раздробленный хребет","муг'тол","перенольд","руины альтерака","странбрад","синдикат"},ang={["faction:Horde"]="Павший город остается отголоском прежних союзов Старой Орды, но сегодня дает Отрекшимся возможность добыть магические реликвии у отвлеченных огров Раздробленного Хребта.",["race:Human"]="Для людей Альянса руины — мрачное напоминание о слабости и предательстве во время Второй войны, когда трусость Перенольда разрушила братство Семи королевств."},sec={{t="Предательство королевства",b="Альтерак был независимым человеческим государством, выделившимся из древней Араторской империи и расположенным высоко на торговых путях через горы. Во время Второй войны, опасаясь уничтожения вторгшейся Старой Ордой, король Эйден Перенольд тайно заключил союз с орками. Когда после сражений у Каэр Дарроу предательство раскрылось, Альянс Лордерона быстро ответил. Король Теренас Менетил II ввел в городе военное положение и низложил Перенольда. Величественные укрепления, церковь и дворец пришли в запустение, а жители бежали или встали на путь разбоя."},{t="Огрская оккупация",b="Пока уцелевшие альтеракские дворяне и мятежные солдаты создали Синдикат, чтобы вести партизанскую войну из таких городов, как Странбрад, свою древнюю столицу они потеряли полностью. Сегодня огры Раздробленного Хребта под предводительством Муг'тола обитают среди разрушенных стен, дворцовых залов и разбитых баллист. Ни Синдикату, ни человеческим защитникам Южнобережья не удалось вернуть павший город, и его рушащиеся башни и заброшенные хранилища остаются опасной территорией для охотников за сокровищами и мародеров."}},faq={{q="Почему Альтерак был разрушен?",a="Во время Второй войны король Эйден Перенольд заключил союз с вторгшейся Орочьей Ордой, чтобы пощадить свое королевство. Альянс Лордерона раскрыл предательство, вторгся в город Альтерак, разрушил его оборону и ввел в королевстве военное положение.",al={"why is alterac in ruins","what happened to alterac city","fall of alterac","почему альтерак в руинах","что случилось с городом альтерак","падение альтерака"}},{q="Кто живет в руинах сейчас?",a="Огры Раздробленного Хребта под предводительством Муг'тола захватили дворец, стены и заснеженные дворы. Кроме того, на северных стенах тихо сидит предприимчивый гоблин-торговец алхимией по имени Бро'кин.",al={"who controls alterac ruins","alterac ogres","who is in alterac","кто владеет руинами альтерака","огры альтерака","кто в альтераке"}},{q="Какое отношение Синдикат имеет к этому месту?",a="Синдикат в основном состоит из бывшей альтеракской аристократии и солдат, потерявших земли после роспуска королевства. Хотя они отчаянно стремятся вернуть Альтерак, огры Раздробленного Хребта изгнали их из самой столицы, и теперь они действуют из таких оплотов, как Странбрад.",al={"does the syndicate live here","syndicate alterac connection","живет ли здесь синдикат","синдикат и альтерак"}},{q="Почему искатели приключений Альянса приходят сюда?",a="Солдаты Альянса из Южнобережья назначают награды за враждебных огров Раздробленного Хребта, нападающих на дороги, а дворяне на юге, такие как граф Ремингтон Риджвелл, посылают в руины агентов, чтобы вернуть утраченные семейные реликвии, например Тиару Перенольда.",al={"alliance quests alterac ruins","crushridge bounty","задания альянса руины альтерака","награда за огров раздробленного хребта"}},{q="Чем Орду интересуют эти руины?",a="Леди Сильвана Ветрокрылая и Отрекшиеся живо интересуются артефактами, разбросанными по павшему человеческому королевству, и посылают защитников в населенную ограми цитадель, чтобы добыть могущественные реликвии, такие как Корона Воли.",al={"horde quests alterac ruins","sylvanas alterac","задания орды руины альтерака","сильвана альтерак"}}},fp="16,313,20.584.0,19.495.0,26.242.0,27.204.0,49.291.0,38.248.0,43.234.0"}
P.entries["subzone:ruins-of-andorhal"] = {n="Руины Андорала",s="Некогда сельскохозяйственный центр и пункт распределения зерна северного Лордерона, Руины Андорала теперь лежат в сердце Западных Чумных земель как разрушенная цитадель Некрополя. Под властью лича Аража Призывателя разоренный городок кишит полчищами нежити, вурдалаков и призраков.",h="Некогда сельскохозяйственный центр и пункт распределения зерна северного Лордерона, Руины Андорала теперь...",kw={"andorhal","araj the summoner","chromie","grain silos","scourge","temporal parasites","western plaguelands","андорал","араж призыватель","хроми","зернохранилища","плеть","временные паразиты","западные чумные земли"},ang={["class:Paladin"]="Для Рыцарей Серебряной Длани и паладинов всего Альянса Андорал — освященная земля, превратившаяся в кошмар: именно здесь чума отравила запасы зерна Лордерона и погубила северное королевство.",["race:Undead"]="Отрекшиеся смотрят на разрушенный город с мрачными воспоминаниями: многие из тех, кто сегодня ходит по Подгороду, были жителями Лордерона и когда-то съели отравленное зерно, собранное на окрестных полях."},sec={{t="Сердце чумы",b="Андорал был первым плацдармом чумы нежити в Лордероне: зерно, зараженное Культом Проклятых, упаковывали и развозили по всему человеческому королевству. Сегодня разрушенный город — обширный оплот Плети в Западных Чумных землях. Араж Призыватель властвует в центре руин в окружении вурдалаков, скелетов-ужасов и огромных плотяных големов. Разведывательные отряды Алого ордена время от времени исследуют окраины города, но Плеть железной рукой удерживает разрушенные улицы."},{t="Распад времени",b="Помимо физического присутствия нежити, Андорал страдает от странных временных аномалий. Часы на ратуше и брошенные карманные часы, разбросанные по улицам, навсегда остановились на трех часах. Бронзовая дракониха Хроми, укрывшаяся в трактире на краю руин, исследует временных паразитов, гнездящихся в зернохранилищах. Похоже, силы Плети вмешиваются в сам ход времени, пытаясь изменить историю трагического падения города."}},faq={{q="Кто правит Руинами Андорала?",a="Руинами управляет Араж Призыватель, могущественный лич, координирующий действия Плети в этой местности. Он обитает в центре города в окружении элитного авангарда скелетов-стражей и плотяных созданий.",al={"who leads andorhal","andorhal boss","araj the summoner","кто правит андоралом","босс андорала","араж призыватель"}},{q="Почему Хроми находится в руинах?",a="Хроми в облике гномки-женщины расследует неестественные нарушения в потоке времени. Она подозревает вмешательство возле городских хранилищ зерна и просит путников помочь в расследовании.",al={"what is chromie doing in andorhal","why is chromie here","chromie andorhal","что хроми делает в андорале","почему хроми здесь","хроми андорал"}},{q="Почему все часы остановились на трех часах?",a="Часы на здании ратуши и карманные часы, найденные среди обломков, остановились на трех часах. Связь с временными искажениями Андорала возможна, но точная причина не подтверждена.",al={"three oclock watch","andorhal clock frozen","why stopped at 3","три часа","замершие часы андорала","почему остановились на трех"}},{q="Почему Алый орден нападает на Андорал?",a="Небольшие боевые отряды из алых лекарей, охотников и призывателей пытаются проникнуть в город. Фанатичный орден стремится вернуть Лордерон и уничтожить Плеть, однако его вылазки в укрепленный центр редко бывают успешны.",al={"scarlet crusade in andorhal","scarlet patrols andorhal","алый орден в андорале","патрули алого ордена андорал"}}},fp="17,325,19.543.0,15.488.1,32.212.0,32.185.0,48.193.0,45.245.0"}
P.entries["subzone:ruins-of-constellas"] = {n="Руины Констелласа",s="Руины Констелласа — разрушенные остатки древнего поселения ночных эльфов в Оскверненном лесу у корней горы Хиджал. Некогда священные земли захвачены сатирами Нефритового Пламени, которые яростно осквернили лунный колодец поселения демонической магией Скверны.",h="Руины Констелласа — разрушенные остатки древнего поселения ночных эльфов в Оскверненном лесу у корней горы...",kw={"bearkin","constellas","felwood","jadefire","moonwell","satyr","xavaric","xavathras","медведи","констеллас","оскверненный лес","нефритовое пламя","лунный колодец","сатир","ксаваррик","ксаватрас"},ang={["class:Druid"]="Зрелище изумрудных медведей, сражающихся с демоническими захватчиками, делает Констеллас суровым напоминанием о клятве друидов восстановить равновесие в Оскверненном лесу.",["race:NightElf"]="Осквернение Констелласа и его лунного колодца — вопиющее оскорбление Элуны, требующее, чтобы ночные эльфы изгнали сатиров Нефритового Пламени."},sec={{t="Оскверненное святилище",b="Классические каменные арки и рушащиеся площади Констелласа говорят о том, что здесь жила идиллическая община ночных эльфов. Во время Третьей войны поход Пылающего Легиона через Оскверненный лес разрушил это убежище, оставив его открытым для демонической порчи. Теперь скверные сатиры Нефритового Пламени владеют этими камнями. Под предводительством Ксаватраса они деятельно ухаживают за оскверненным лунным колодцем, превращая чистые воды в источник губительной силы Скверны во имя своего господина, лорда Ксаваррика."},{t="Борьба за очищение",b="Осквернение Констелласа вызвало активное сопротивление защитников Калимдора. Друидические изумрудные медведи сражаются с сатирами по всем руинам, пытаясь вернуть лес, а ночные эльфы-разведчики наблюдают из лагеря неподалеку к юго-востоку. Чтобы защитить свои скверные ритуалы и не пустить чужаков к Ксаватрасу, сатиры закрыли глубокие ходы в руины непроницаемой стеной магического огня."}},faq={{q="Чем был Констеллас до осквернения?",a="Констеллас был древним поселением ночных эльфов у подножия горы Хиджал. Его архитектура и лунный колодец говорят о том, что это была безмятежная роща, посвященная Элуне и природе, до того как Пылающий Легион вторгся в лес во время Третьей войны.",al={"constellas history","what was constellas","who built constellas","история констелласа","чем был констеллас","кто построил констеллас"}},{q="Кто управляет руинами сейчас?",a="Руины заняты сатирами Нефритового Пламени, которых на месте возглавляет Ксаватрас. Они взращивают демоническую энергию по всей округе по общим приказам лорда Ксаваррика.",al={"who lives here","who rules constellas","jadefire satyrs constellas","кто здесь живет","кто правит констелласом","сатиры нефритового пламени констеллас"}},{q="Что случилось с лунным колодцем в Констелласе?",a="Лунный колодец захватили сатиры Нефритового Пламени и осквернили магией Скверны. Вместо того чтобы струить целительные благословения Элуны, он превращен в ядовитый источник энергии Скверны, которым управляет Ксаватрас.",al={"corrupted moonwell felwood","constellas moonwell","why is the well green","оскверненный лунный колодец оскверненный лес","лунный колодец констеллас","почему колодец зеленый"}},{q="Почему внутри руин есть стена огня?",a="Сатиры воздвигли пылающую преграду на внутренней тропе, чтобы защитить Ксаватраса и свои непрерывные ритуалы от друидов и изумрудных медведей, пытающихся отбить руины.",al={"constellas fire wall","fire barrier constellas","how to get past fire wall","стена огня констеллас","огненная преграда констеллас","как пройти стену огня"}}},fp="19,281,19.479.0,26.443.0,42.240.0,27.172.0,44.210.0,45.160.0"}
P.entries["subzone:ruins-of-eldarath"] = {n="Руины Эльдарата",s="Руины Эльдарата — разрушенные остатки города высокорожденных времен до Раскола, стоявшего на скалистых утесах Азшары. Некогда оплот аркановой науки кальдораев, его павшие площади и рушащиеся храмы теперь захвачены враждебными нагами. Ученые и искатели приключений отваживаются идти по опасным прибрежным руинам в поисках надписанных табличек и забытых реликвий древности.",h="Руины Эльдарата — разрушенные остатки города высокорожденных времен до Раскола, стоявшего на скалистых утесах...",kw={"azshara","azuregos","eldarath","explorers' league","highborne","kaldorei","naga","sundering","tablets","азшара","азурегос","эльдарат","лига исследователей","высокорожденные","кальдораи","наги","раскол","таблички"},ang={["class:Mage"]="Эльдарат — священное, хотя и поучительное место для изучения: каменные таблички на его площадях содержат основополагающие арканые теории, высеченные самыми одаренными чародеями-высокорожденными до падения их империи.",["race:NightElf"]="Эти выбеленные солнцем руины — горькое напоминание о гордыне высокорожденных и Расколе; современные кальдораи давно избегают их, а теперь их оскверняют извращенные наги."},sec={{t="Разрушенный оплот высокорожденных",b="До того как Великий Раскол десять тысяч лет назад разбил древний Калимдор, Эльдарат был процветающим городом ночных эльфов. Здесь собирались знаменитые маги-высокорожденные, высекая глубочайшие тайны арканы и основы магии на больших каменных табличках, оставленных на площадях для изучения собратьями. Во время Войны Древних город стал полем боя между Сопротивлением кальдораев и демонами Пылающего Легиона, а затем Раскол сбросил большую часть Эльдарата в Залив Бурь. Уцелевшие части вдоль восточных утесов тысячелетиями стояли в запустении, избегаемые современными ночными эльфами, постепенно покрываясь соленой пылью и плющом."},{t="Власть наг и забытые реликвии",b="В недавнее время свирепые наги вышли из моря и захватили разрушенные улицы Эльдарата под командованием полководцев, скрывающихся в ближайших святилищах, таких как Храм Зин-Малор. Несмотря на опасность со стороны змеелюдов, руины остаются неодолимой приманкой для чужаков. Лига исследователей отправила искателей приключений Альянса на разрушенные дворы, чтобы снять копии с древних арканых табличек Эльдарата. Слухи об утраченных сокровищах и остаточной магической энергии также привлекли синего дракона Азурегоса в окрестные земли, лишний раз подтверждая, что под треснувшими плитами руин все еще спят тайны огромной силы."}},faq={{q="Чем был Эльдарат до превращения в руины?",a="До Великого Раскола десять тысяч лет назад Эльдарат был величественным городом ночных эльфов, населенным высокорожденными. Он служил центром изучения арканы и укрепленным убежищем, пока Война Древних и раскол мира не разрушили его.",al={"what was eldarath","eldarath history","eldarath origin","что такое эльдарат","история эльдарата","происхождение эльдарата"}},{q="Кто управляет Руинами Эльдарата сегодня?",a="Враждебные наги полностью захватили руины, используя рушащиеся площади и ближайшие строения, например Храм Зин-Малор, как прибрежные оплоты под командованием таких предводителей, как полководец Креллиан.",al={"who lives in eldarath","what is in eldarath","eldarath mobs","кто живет в эльдарате","что есть в эльдарате","монстры эльдарата"}},{q="Почему ученые и исследователи отправляются в Эльдарат?",a="Ученые ищут сохранившиеся каменные таблички, оставленные древними магами-высокорожденными. Эти общественные таблички содержат основы аркановой магии и давно утраченные исследования, достаточно ценные, чтобы такие группы, как дворфийская Лига исследователей, посылали разведчиков снимать копии текста.",al={"why go to eldarath","eldarath quests","what is at eldarath","зачем идти в эльдарат","задания эльдарата","что в эльдарате"}},{q="Почему синий дракон Азурегос бродит возле руин?",a="Азурегоса привлекает огромная концентрация древней тайной силы на побережье Азшары. Ходят слухи, что могущественные реликвии времен до Раскола — возможно, даже флаконы, тронутые древним Источником Вечности, — скрыты в руинах или вокруг них.",al={"why is azuregos here","azuregos eldarath","blue dragon in azshara","почему азурегос здесь","азурегос эльдарат","синий дракон в азшаре"}}},fp="17,377,29.664.0,30.642.0,44.253.0,41.200.0,49.275.0,55.266.0"}
P.entries["subzone:ruins-of-isildien"] = {n="Руины Исильдиэна",s="Руины Исильдиэна — обширные остатки древнего города ночных эльфов на юго-западе Фераласа, разрушенного десять тысячелетий назад во время Великого Раскола. Сегодня заросшая каменная кладка и растрескавшиеся дворы храмов заняты грубыми ограми Гордунни.",h="Руины Исильдиэна — обширные остатки древнего города ночных эльфов на юго-западе Фераласа, разрушенного десять...",kw={"elune","feralas","gordunni","isildien","kaldorei","ogres","sundering","temple of the moon","элуна","фералас","гордунни","исильдиэн","кальдораи","огры","великий раскол","храм луны"},ang={["class:Priest"]="Огромная ротонда на вершине повторяет планировку высших святилищ Элуны и хранит отзвуки молитв, возносимых Белой Леди десять тысяч лет назад.",["race:NightElf"]="Прогулка по Исильдиэну горько напоминает о величии вашей империи до Раскола, ныне павшей в руины и оскверненной варварскими ограми Гордунни."},sec={{t="Павший город кальдораев",b="Десять тысяч лет назад, до того как мир раскололся, Исильдиэн был величественным поселением ночных эльфов в первобытных лесах древнего Калимдора. Его изящные мраморные арки и просторные террасы были памятниками цивилизации и благочестия кальдораев. Когда Источник Вечности взорвался изнутри и разорвал континенты, Исильдиэн лежал в руинах, погребенный под тысячелетними зарослями джунглей. Верхнюю террасу занимает огромное сооружение с куполом, удивительно похожее на Храм Луны в Дарнассе, — вероятно, город был важным святилищем Элуны."},{t="Крепость Гордунни",b="В наше время изящная каменная кладка Исильдиэна служит куда более грубым целям. Огры Гордунни из Фераласа превратили обширные террасы и скальные выступы в одно из своих главных поселений. Огры укрепили рушащиеся переходы, осквернив древние площади грубыми кострами, примитивными баррикадами и боевыми знаменами, и яростно защищают захваченный дом от любых чужаков, подошедших слишком близко к южным холмам."}},faq={{q="Чем был Исильдиэн изначально?",a="Исильдиэн был крупным городом ночных эльфов, построенным до Великого Раскола десять тысяч лет назад. В нем были обширные каменные площади, многоярусные террасы и величественные храмы, пока катаклизм не превратил его в руины.",al={"what is isildien","isildien history","who built isildien","что такое исильдиэн","история исильдиэна","кто построил исильдиэн"}},{q="Кто сейчас контролирует Руины Исильдиэна?",a="Руины захвачены и укреплены ограми Гордунни, которые используют разрушенные мраморные залы и естественные наблюдательные точки как крепость на юге Фераласа.",al={"who lives in isildien","isildien enemies","ogres in isildien","кто живет в исильдиэне","враги исильдиэна","огры в исильдиэне"}},{q="Что за большой круглый павильон наверху лестницы?",a="Заметный круглый павильон близко повторяет архитектуру Храма Луны в Дарнассе, что говорит о том, что верхний помост был священным святилищем, посвященным поклонению Элуне.",al={"isildien temple","round building in isildien","temple of elune feralas","храм исильдиэна","круглое здание в исильдиэне","храм элуны фералас"}},{q="Есть ли что-нибудь скрытое в руинах?",a="В восточных скалах рядом с руинами находится пещера, которую используют местные огры, как и разбросанные каменные террасы на северных и южных участках.",al={"isildien cave","secrets in isildien","пещера исильдиэна","тайны исильдиэна"}}},fp="17,260,29.600.0,23.441.0,29.214.0,39.159.0,61.207.0,42.170.0"}
P.entries["subzone:ruins-of-jubuwal"] = {n="Руины Жубуваля",s="Руины Жубуваля — рассыпающиеся остатки древнего поселения Гурубаши к востоку от Арены Гурубаши в Тернистой долине. Некогда место империи и ритуалов, руины оказались во власти отступника-знахаря Занзила Отверженного и его причудливой свиты прислужников.",h="Руины Жубуваля — рассыпающиеся остатки древнего поселения Гурубаши к востоку от Арены Гурубаши в Тернистой...",kw={"gurubashi","jon-jon","jubuwal","mackinley","maury club foot","stranglethorn","zanzil","гурубаши","жон-жон","жубуваль","макинли","мори косолапый","тернистая долина","занзил"},ang={["class:Rogue"]="Тени и рушащаяся кладка Жубуваля — идеальное укрытие для засад на преступников, прячущихся от охотников за головами Пиратской бухты.",["race:Troll"]="Для троллей Черного Копья Жубуваль — это и трагический упадок наследия Гурубаши, и извращение древнего вуду, которым занимаются отступники вроде Занзила."},sec={{t="Приют изгнанников",b="Жубуваль, расположенный в стороне от главной дороги через Тернистую долину, некогда был частью великой цивилизации Гурубаши. Сегодня каменную резьбу и увитую плющом кладку захватил Занзил Отверженный, эксцентричный знахарь, известный сильными зельями и мерзким вуду. Занзил наполнил руины неестественным зверинцем последователей: порабощенными вурдалаками, покоренными наги и троллями-отступниками. Среди каменных арок прячутся и отчаявшиеся беглецы, такие как Жон-Жон Ворон и Мори «Косолапый» Уилкинс, оба скрываются от безжалостного сборщика долгов «Морского волка» Макинли из Пиратской бухты."}},faq={{q="Где находятся Руины Жубуваля?",a="Руины лежат в центре Тернистой долины, к востоку от Арены Гурубаши и сразу рядом с главной грунтовой дорогой, соединяющей северную и южную части Тернистой долины.",al={"ruins of jubuwal location","where is jubuwal","jubuwal map","где руины жубуваля","где жубуваль","карта жубуваля"}},{q="Кто управляет Руинами Жубуваля?",a="Руины принадлежат Занзилу Отверженному и его прислужникам. Его разношерстные последователи — зомбированные тролли, воскрешенные вурдалаки, союзные наги и разные негодяи, ищущие укрытия от закона.",al={"who lives in jubuwal","jubuwal enemies","who controls jubuwal","кто живет в жубувале","враги жубуваля","кто управляет жубувалем"}},{q="Почему вурдалаки и наги действуют здесь вместе?",a="Занзил Отверженный использует ядовитые смеси вуду и зелья, изменяющие разум, чтобы подчинять и направлять окружающих. С их помощью он превращает восставшую нежить, наг и троллей в послушную боевую силу.",al={"why are there ghouls in jubuwal","zanzil minions","почему в жубувале вурдалаки","прислужники занзила"}},{q="Почему здесь прячутся такие преступники, как Жон-Жон и Мори?",a="Жон-Жон Ворон и Мори «Косолапый» Уилкинс бежали в Жубуваль, спасаясь от гнева «Морского волка» Макинли, известного сборщика долгов из Пиратской бухты.",al={"jon-jon the crow","maury club foot wilkins","mackinley debtors","жон-жон ворон","мори косолапый уилкинс","должники макинли"}}},fp="16,299,23.628.0,39.172.0,34.203.0,46.208.0,51.167.0"}
P.entries["subzone:ruins-of-kel-theril"] = {n="Руины Кел'Терила",s="Руины Кел'Терила — разрушенные остатки древнего города ночных эльфов у замерзшего озера Кел'Терил в центре Зимних Ключей. Город был уничтожен десять тысяч лет назад во время Великого Раскола, и его промерзшие колонны и храмы до сих пор преследуют измученные духи высокорожденных, погибших в катаклизме.",h="Руины Кел'Терила — разрушенные остатки древнего города ночных эльфов у замерзшего озера Кел'Терил в центре...",kw={"ghosts","highborne","kel'theril","lake kel'theril","ruins","sundering","winterspring","призраки","высокорожденные","кел'терил","озеро кел'терил","руины","великий раскол","зимние ключи"},ang={["class:Mage"]="Маги, исследующие руины, ощутят древние дремлющие тайные энергии, некогда питавшие один из гордейших магических городов Калимдора до Раскола.",["race:NightElf"]="Для ночных эльфов Кел'Терил — суровое напоминание о высокомерии древней касты высокорожденных и о чудовищных разрушениях, вызванных их безрассудным использованием тайной магии."},sec={{t="Разрушенное наследие",b="Задолго до того как Зимние Ключи стали замерзшим нагорьем, Кел'Терил был великим поселением древней империи ночных эльфов. Когда Источник Вечности обрушился во время Великого Раскола, город был разрушен и погребен под льдом и снегом. Беда застигла живших там высокорожденных врасплох и привязала их души к заснеженным камням. Сегодня духи бывших заклинателей витают среди промерзших арок, бесконечно переживая свои последние катастрофические мгновения."},{t="Эхо в снегах",b="Путники, отважившиеся пройти по центру Зимних Ключей, встречают неспокойных призрачных высокорожденных, бродящих среди руин колоннад у озера. Эти призраки часто враждебны: их свело с ума тысячелетнее одиночество и неистовая магия, разрушившая их цивилизацию. Однако несколько скорбных видений, например Раскаивающийся высокорожденный, ищут путников, готовых выслушать их печальные жалобы, и примиряются с забытым прошлым."}},faq={{q="Что случилось с городом Кел'Терил?",a="Кел'Терил был уничтожен десять тысяч лет назад во время Великого Раскола. Когда Источник Вечности взорвался изнутри и разорвал древний континент Калимдор, город обрушился грудой развалин и был поглощен внезапным лютым холодом, окутавшим Зимние Ключи.",al={"kel'theril history","why is kel'theril ruined","how did kel'theril fall","история кел'терила","почему кел'терил в руинах","как пал кел'терил"}},{q="Какие духи обитают в этих руинах?",a="Руины населяют призраки высокорожденных ночных эльфов, погибших во время Великого Раскола. Их души привязаны к павшим камням, томятся в муках и бродят по заснеженным окрестностям озера Кел'Терил.",al={"kel'theril ghosts","who haunts kel'theril","kel'theril undead","призраки кел'терила","кто обитает в кел'териле","нежить кел'терила"}},{q="Можно ли поговорить с призраками?",a="Хотя большинство духов враждебны и потеряны в безумии, среди руин можно найти одинокого Раскаивающегося высокорожденного, который готов говорить с путниками Альянса, стремящимися понять трагическое прошлое этого места.",al={"friendly ghost kel'theril","remorseful highborne","ghost quests kel'theril","дружелюбный призрак кел'терил","раскаивающийся высокорожденный","задания призрака кел'терил"}},{q="Где находятся эти руины?",a="Руины Кел'Терила расположены на берегах озера Кел'Терил, замерзшего озера в самом сердце центральных Зимних Ключей.",al={"kel'theril location","where is kel'theril","find kel'theril","где кел'терил","расположение кел'терила","найти кел'терил"}}},fp="19,341,18.488.0,18.422.0,40.267.0,31.226.0,37.216.0,28.133.0"}
